#include <stdlib.h>
#include <string.h>

typedef struct FSA {
    int state_id;
    struct FSA *edges[256];
} FSA;

typedef struct StateList {
    int state_id;
    struct StateList *next;
} StateList;

StateList* traverse_dom_tree(int states[], int num_states, FSA* fsa, int last_state, int (*match_selector)(FSA*, const char*)) {
    // Allocate memory for the new state list
    StateList* result = (StateList*)malloc(sizeof(StateList));
    if (!result) return NULL;

    // Initialize the new state list node
    result->state_id = states[last_state];
    result->next = NULL;

    // Recursively traverse the DOM tree
    for (int i = 0; i < num_states; i++) {
        FSA* next_fsa = fsa->edges[states[i]];
        if (next_fsa) {
            StateList* next_result = traverse_dom_tree(states, num_states, next_fsa, i, match_selector);
            if (!next_result) {
                free(result); // Clean up in case of memory allocation failure
                return NULL;
            }
            result->next = next_result;
        }
    }

    // Test the current state against the selector
    const char* selector = "example"; // Example selector, replace with actual selector function
    if (match_selector(fsa, selector)) {
        // If the current state matches the selector, create a new node and link it to the result list
        StateList* new_node = (StateList*)malloc(sizeof(StateList));
        if (!new_node) {
            free(result); // Clean up in case of memory allocation failure
            return NULL;
        }
        new_node->state_id = states[last_state];
        new_node->next = result;
        result = new_node;
    }

    return result;
}
