public class DOMTraverser
{
    public static Element[] FindElementsBySelector(Node node, string selector, Func<Element, bool> callback)
    {
        List<Element> matchingElements = new List<Element>();

        if (node is Element element && callback(element))
        {
            matchingElements.Add(element);
        }

        foreach (Node child in node.childNodes)
        {
            matchingElements.AddRange(FindElementsBySelector(child, selector, callback));
        }

        return matchingElements.ToArray();
    }
}
