using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class CustomObject
{
    public int Id { get; set; }
    public string Name { get; set; }
    // Add other properties as needed
}

public class DatabaseHelper
{
    private readonly string _connectionString;
    private readonly Dictionary<string, DataTable> _cache = new Dictionary<string, DataTable>();

    public DatabaseHelper(string connectionString)
    {
        _connectionString = connectionString;
    }

    public async Task<List<CustomObject>> ExecuteStoredProcedureAsync(
        SqlConnection connection,
        List<SqlParameter> parameters,
        string procedureName)
    {
        var key = $"{procedureName}_{string.Join(",", parameters)}";

        if (_cache.ContainsKey(key))
        {
            return MapToObjects(_cache[key]);
        }

        using (var command = new SqlCommand(procedureName, connection))
        {
            command.CommandType = CommandType.StoredProcedure;
            foreach (var parameter in parameters)
            {
                command.Parameters.Add(parameter);
            }

            using (var reader = await command.ExecuteReaderAsync())
            {
                var dataTable = new DataTable();
                dataTable.Load(reader);

                _cache[key] = dataTable;

                return MapToObjects(dataTable);
            }
        }
    }

    private List<CustomObject> MapToObjects(DataTable dataTable)
    {
        var objects = new List<CustomObject>();

        foreach (DataRow row in dataTable.Rows)
        {
            var obj = new CustomObject
            {
                Id = Convert.ToInt32(row["Id"]),
                Name = row["Name"].ToString()
                // Map other properties as needed
            };

            objects.Add(obj);
        }

        return objects;
    }
}
