#include <iostream>
#include <fstream>
#include <vector>
#include "Node.h"
#include "rapidjson/document.h"
#include "rapidjson/writer.h"
#include "rapidjson/stringbuffer.h"

class NodeManager {
public:
    NodeManager(const std::string& filename) : m_filename(filename), m_size(0), m_capacity(10) {
        m_nodes = new Node[m_capacity];
    }

    ~NodeManager() {
        delete[] m_nodes;
    }

    void readFromFile() {
        std::ifstream file(m_filename);
        if (!file.is_open()) {
            std::cerr << "Failed to open file: " << m_filename << std::endl;
            return;
        }

        // Read key-value pairs from file and initialize nodes
        // ...

        file.close();
    }

    void resize() {
        m_capacity *= 2;
        Node* newNodes = new Node[m_capacity];
        for (int i = 0; i < m_size; ++i) {
            newNodes[i] = m_nodes[i];
        }
        delete[] m_nodes;
        m_nodes = newNodes;
    }

    void serializeToJson(rapidjson::Writer<rapidjson::StringBuffer>& writer) const {
        writer.StartArray();
        for (int i = 0; i < m_size; ++i) {
            writer.StartObject();
            writer.Key("key");
            writer.Int(m_nodes[i].getKey());
            writer.Key("value");
            writer.String(m_nodes[i].getValue().c_str());
            writer.EndObject();
        }
        writer.EndArray();
    }

    void deserializeFromJson(const rapidjson::Value& json) {
        if (!json.IsArray()) return;
        for (rapidjson::SizeType i = 0; i < json.Size(); ++i) {
            int key = json[i]["key"].GetInt();
            std::string value = json[i]["value"].GetString();
            addNode(key, value);
        }
    }

private:
    void addNode(int key, const std::string& value) {
        if (m_size == m_capacity) resize();
        m_nodes[m_size++] = Node(key, value);
    }

    std::string m_filename;
    Node* m_nodes;
    int m_size;
    int m_capacity;
};

class Node {
public:
    Node(int key, const std::string& value) : m_key(key), m_value(value) {}

    int getKey() const { return m_key; }
    std::string getValue() const { return m_value; }

private:
    int m_key;
    std::string m_value;
};
