public class GameCharacter {

    private SocketChannel channel;
    private boolean isCooldownActive = false;
    private static final int COOLDOWN_SECONDS = 9;

    public void connectAndAttack() {
        try {
            // Establish connection
            channel = SocketChannel.open();
            channel.connect(new InetSocketAddress("remoteAddress", 8080));
            System.out.println("Connected to remote address.");

            // Simulate connection state change
            channel.register(new java.nio.channels.SelectionKey(channel, java.nio.channels.SelectionKey.OP_READ));

            // Select attack randomly and apply cooldown
            if (!isCooldownActive) {
                int selectedAttack = selectRandomAttack();
                System.out.println("Selected Attack: " + selectedAttack);
                isCooldownActive = true;
                new Thread(() -> {
                    try {
                        Thread.sleep(COOLDOWN_SECONDS * 1000);
                        isCooldownActive = false;
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                }).start();
            }

        } catch (IOException | InterruptedException e) {
            System.err.println("Error during connection or attack: " + e.getMessage());
        }
    }

    private int selectRandomAttack() {
        return (int) (Math.random() * 2) + 1; // Randomly selects between 1 and 2
    }
}
