using UnityEngine;

public class CustomRandomGenerator
{
    private int _seed;
    private Random.RangeMethod _rangeMethod;

    public CustomRandomGenerator(int? seed = null)
    {
        SetSeed(seed);
    }

    public void SetSeed(int? seed)
    {
        if (seed.HasValue)
        {
            UnityEngine.Random.Seed = seed.Value;
            _seed = seed.Value;
        }
        else
        {
            _seed = UnityEngine.Random.Range(0, int.MaxValue);
            UnityEngine.Random.Seed = _seed;
        }

        OnNewSeedGenerated?.Invoke(_seed);
    }

    public float CustomRange(float min, float max, bool isExclusive)
    {
        if (min >= max)
        {
            throw new ArgumentException("Min must be less than max.");
        }

        if (isExclusive)
        {
            return UnityEngine.Random.Range(min + 1e-5f, max);
        }
        else
        {
            return UnityEngine.Random.Range(min, max);
        }
    }

    public int CustomRange(int min, int max, bool isExclusive)
    {
        if (min >= max)
        {
            throw new ArgumentException("Min must be less than max.");
        }

        if (isExclusive)
        {
            return UnityEngine.Random.Range(min + 1, max);
        }
        else
        {
            return UnityEngine.Random.Range(min, max);
        }
    }

    public override string ToString()
    {
        return $"CustomRandomGenerator - Seed: {_seed}";
    }

    public event Action<int> OnNewSeedGenerated;
}
