import os
import importlib.util
from typing import Dict, List, Any

def load_protocol_details(directory_path: str) -> Dict[str, Any]:
    protocol_details = {}
    cache = {}

    for filename in os.listdir(directory_path):
        if filename.endswith(".py"):
            module_name = filename[:-3]
            module_path = os.path.join(directory_path, filename)
            spec = importlib.util.spec_from_file_location(module_name, module_path)
            if spec is not None:
                protocol_module = importlib.util.module_from_spec(spec)
                spec.loader.exec_module(protocol_module)

                for name, obj in protocol_module.__dict__.items():
                    if isinstance(obj, type) and hasattr(obj, "protocol_name"):
                        protocol_name = getattr(obj, "protocol_name")
                        if protocol_name not in cache:
                            try:
                                protocol_instance = obj()
                                supported_features = protocol_instance.supported_features
                                description = protocol_instance.description
                                default_settings = protocol_instance.default_settings
                                feature_flags = protocol_instance.feature_flags

                                cache[protocol_name] = {
                                    "name": protocol_name,
                                    "implementation_class": obj,
                                    "description": description,
                                    "supported_features": supported_features,
                                    "default_settings": default_settings,
                                    "feature_flags": feature_flags,
                                }
                            except Exception as e:
                                print(f"Error loading {module_name}: {e}")

    return cache
