#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>

// Function prototypes
int resolveDNS(const char *hostname, u_char *ipAddress);
void logDNSQuery(const char *hostname, int result);

// Global variables (for demonstration purposes)
u_char ipCache[256][16];
int cacheIndex = 0;

int resolveDNS(const char *hostname, u_char *ipAddress) {
    // Check cache
    for (int i = 0; i < cacheIndex; i++) {
        if (strcmp(hostname, (char *)ipCache[i]) == 0) {
            memcpy(ipAddress, ipCache[i + 1], sizeof(u_char));
            return 0;
        }
    }

    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        logDNSQuery(hostname, -1);
        return status;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        char ipstr[INET6_ADDRSTRLEN];

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);

        // Copy the IP address to the output buffer
        if (p->ai_family == AF_INET) {
            memcpy(ipAddress, &ipv4->sin_addr, 4);
        } else {
            memcpy(ipAddress, &ipv6->sin6_addr, 16);
        }

        logDNSQuery(hostname, 0);
        freeaddrinfo(res); // free the linked list
        return 0;
    }

    freeaddrinfo(res); // free the linked list if no address was found
    logDNSQuery(hostname, -2);
    return -2; // No valid IP address found
}

void logDNSQuery(const char *hostname, int result) {
    if (result == 0) {
        printf("DNS query for %s successful\n", hostname);
    } else {
        printf("DNS query for %s failed with error code %d\n", hostname, result);
    }
}
```

