<?php

function generateSecureToken($length = 32, $charset = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789') {
    if ($length <= 0) {
        throw new InvalidArgumentException('Length must be greater than 0');
    }

    return substr(str_shuffle(str_repeat($charset, ceil($length / strlen($charset)))), 1, $length);
}

function hashPassword($password, $algorithm = PASSWORD_BCRYPT, $cost = 12) {
    if (!in_array($algorithm, password_get_algorithms())) {
        throw new InvalidArgumentException('Invalid algorithm');
    }

    return password_hash($password, $algorithm, ['cost' => $cost]);
}

function verifyPassword($password, $hash) {
    return password_verify($password, $hash);
}

session_start();

function setSecureSessionToken() {
    $_SESSION['token'] = generateSecureToken();
}

function getSecureSessionToken() {
    if (!isset($_SESSION['token'])) {
        throw new Exception('Session token not set');
    }

    return $_SESSION['token'];
}

function storeHashedPassword($password) {
    $_SESSION['hashed_password'] = hashPassword($password);
}

function retrieveHashedPassword() {
    if (!isset($_SESSION['hashed_password'])) {
        throw new Exception('Hashed password not stored in session');
    }

    return $_SESSION['hashed_password'];
}

// Example usage
try {
    setSecureSessionToken();
    echo "Session Token: " . getSecureSessionToken();

    $password = 'my_secure_password';
    storeHashedPassword($password);
    echo "\nHashed Password: " . retrieveHashedPassword();

    if (verifyPassword('my_secure_password', retrieveHashedPassword())) {
        echo "\nPassword verified successfully!";
    } else {
        echo "\nPassword verification failed.";
    }
} catch (Exception $e) {
    echo "Error: " . $e->getMessage();
}
?>
