class ScriptLoader {
  constructor(fileList) {
    this.fileList = fileList;
    this.loadedScripts = {};
    this.errorHandler = (error) => console.error('Script error:', error);
  }

  async loadAll() {
    try {
      await Promise.all(this.fileList.map(scriptSrc => this.loadScript(scriptSrc)));
      console.log('All scripts loaded and executed successfully.');
    } catch (error) {
      this.errorHandler(error);
    }
  }

  async loadScript(src) {
    return new Promise((resolve, reject) => {
      const script = document.createElement('script');
      script.src = src;
      script.onload = () => {
        console.log(`Script loaded: ${src}`);
        this.loadedScripts[src] = true;
        resolve();
      };
      script.onerror = (error) => {
        error.message = `Failed to load script: ${src}`;
        reject(error);
      };
      document.head.appendChild(script);
    });
  }

  async executeScript(src) {
    if (!this.loadedScripts[src]) {
      await this.loadScript(src);
    }
    try {
      eval(this.getScriptContent(src));
      console.log(`Script executed: ${src}`);
    } catch (error) {
      this.errorHandler(error);
    }
