using System;
using UnityEngine;

public enum RangeType { Closed, Open, HalfOpen }

public delegate void SeedCallback(int seed);

public class AdvancedRandomGenerator
{
    private static readonly Random _random = new Random();
    private static int _seed = (int)DateTime.Now.Ticks & 0x7FFFFFFF;
    private static readonly object _lockObject = new object();

    public static void SetSeed(int seed)
    {
        lock (_lockObject)
        {
            _seed = seed & 0x7FFFFFFF;
            UnityEngine.Random.Seed(_seed);
        }
    }

    public static float CustomRange(float min, float max, RangeType rangeType, bool seeded = false, int? seed = null, SeedCallback? callback = null)
    {
        if (seed.HasValue)
        {
            SetSeed(seed.Value);
        }

        switch (rangeType)
        {
            case RangeType.Closed:
                return UnityEngine.Random.Range(min, max + 1f);
            case RangeType.Open:
                return UnityEngine.Random.Range(min + 1e-9f, max - 1e-9f);
            case RangeType.HalfOpen:
                if (UnityEngine.Random.value < 0.5f)
                    return UnityEngine.Random.Range(min, max + 1f);
                else
                    return UnityEngine.Random.Range(min + 1e-9f, max - 1e-9f);
            default:
                throw new ArgumentException("Invalid range type.");
        }
    }

    public static int CustomRange(int min, int max, RangeType rangeType, bool seeded = false, int? seed = null, SeedCallback? callback = null)
    {
        if (seed.HasValue)
        {
            SetSeed(seed.Value);
        }

        switch (rangeType)
        {
            case RangeType.Closed:
                return UnityEngine.Random.Range(min, max + 1);
            case RangeType.Open:
                throw new InvalidOperationException("Open range type not supported for integers.");
            case RangeType.HalfOpen:
                if (UnityEngine.Random.value < 0.5f)
                    return UnityEngine.Random.Range(min, max + 1);
                else
                    throw new InvalidOperationException("Half-open range type not supported for integers.");
            default:
                throw new ArgumentException("Invalid range type.");
        }
    }
}
