public class FileChunkProcessor {

    private ExecutorService executorService = Executors.newFixedThreadPool(4); // Adjust thread pool size as needed
    private LoggingCallback loggingCallback;

    public void setLoggingCallback(LoggingCallback callback) {
        this.loggingCallback = callback;
    }

    public void readProcessWriteFile(String filePath, int chunkSize, int bufferSize, boolean useParallelProcessing) throws IOException {
        if (useParallelProcessing) {
            processFileInParallel(filePath, chunkSize, bufferSize);
        } else {
            processFileInChunks(filePath, chunkSize, bufferSize);
        }
    }

    private void processFileInChunks(String filePath, int chunkSize, int bufferSize) throws IOException {
        try (RandomAccessFile file = new RandomAccessFile(filePath, "rw")) {
            long fileSize = file.length();
            byte[] buffer = new byte[bufferSize];

            for (long position = 0; position < fileSize; position += chunkSize) {
                int readBytes = file.read(buffer, 0, Math.min(chunkSize, (int) (fileSize - position)));
                if (readBytes == -1) break;

                // Process the chunk
                byte[] processedChunk = processChunk(buffer, readBytes);

                // Write the processed chunk back to the file
                synchronized (file) {
                    file.seek(position);
                    file.write(processedChunk, 0, processedChunk.length);
                }
            }
        } catch (IOException e) {
            logError("Failed to read/write file: " + filePath, e);
            throw e;
        }
    }

    private byte[] processChunk(byte[] chunk, int length) {
        // Placeholder for chunk processing logic
        return chunk; // Return the unmodified chunk as an example
    }

    private void processFileInParallel(String filePath, int chunkSize, int bufferSize) throws IOException {
        try (RandomAccessFile file = new RandomAccessFile(filePath, "rw")) {
            long fileSize = file.length();
            byte[] buffer = new byte[bufferSize];

            for (long position = 0; position < fileSize; position += chunkSize) {
                final long startPos = position;
                final int readBytes = file.read(buffer, 0, Math.min(chunkSize, (int) (fileSize - position)));
                if (readBytes == -1) break;

                executorService.submit(() -> {
                    try {
                        // Process the chunk
                        byte[] processedChunk = processChunk(buffer, readBytes);

                        // Write the processed chunk back to the file
                        synchronized (file) {
                            file.seek(startPos);
                            file.write(processedChunk, 0, processedChunk.length);
                        }
                    } catch (IOException e) {
                        logError("Failed to process and write file chunk", e);
                    }
                });
            }

            executorService.shutdown();
            try {
                if (!executorService.awaitTermination(1, TimeUnit.MINUTES)) {
                    executorService.shutdownNow();
                }
            } catch (InterruptedException ie) {
                executorService.shutdownNow();
                Thread.currentThread().interrupt();
            }
        }
    }

    private void logMessage(String message) {
        if (loggingCallback != null) {
            loggingCallback.logMessage(message);
        } else {
            System.out.println(message);
        }
    }

    private void logError(String message, Exception e) {
        String errorMessage = message + ": " + e.getMessage();
        logMessage(errorMessage);
    }
}
