using System;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class CipherService
{
    private readonly HttpClient _httpClient;
    private readonly string _tokenUrl;

    public CipherService(string tokenUrl)
    {
        _tokenUrl = tokenUrl;
        _httpClient = new HttpClient();
    }

    public async Task<byte[]> DecryptMessageAsync(byte[] ciphertext, byte[] key, byte[] iv)
    {
        if (ciphertext == null || key == null || iv == null)
            throw new ArgumentException("Ciphertext, key, and IV must not be null.");

        string token = await RetrieveTokenAsync();
        if (string.IsNullOrEmpty(token))
            throw new InvalidOperationException("Failed to retrieve token for decryption.");

        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.Key = key;
            aesAlg.IV = iv;
            aesAlg.Mode = CipherMode.CBC;
            aesAlg.Padding = PaddingMode.PKCS7;

            ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

            using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    using (MemoryStream msOutput = new MemoryStream())
                    {
                        await csDecrypt.CopyToAsync(msOutput);
                        return msOutput.ToArray();
                    }
                }
            }
        }
    }

    private async Task<string> RetrieveTokenAsync()
    {
        try
        {
            HttpResponseMessage response = await _httpClient.GetAsync(_tokenUrl, HttpCompletionOption.ResponseHeadersRead);
            response.EnsureSuccessStatusCode();

            string token = await response.Content.ReadAsStringAsync();
            return token;
        }
        catch (HttpRequestException ex)
        {
            throw new InvalidOperationException("Failed to retrieve token from external service.", ex);
        }
    }
}
