// Function to insert a string after the first occurrence of another string in a forward list
void insertAfterFirst(std::forward_list<std::string>& lst, const std::string& key, const std::string& value, int count = 1) {
    if (lst.empty() || key.empty() || value.empty()) {
        throw std::invalid_argument("Input strings cannot be empty");
    }

    auto it = lst.begin();
    while (it != lst.end() && *it != key) {
        ++it;
    }

    if (it == lst.end()) {
        lst.push_back(value);
    } else {
        for (int i = 0; i < count; ++i) {
            it = lst.insert_after(it, value);
            ++it;
        }
    }
}

// Function to log operation details to an external database
void logOperation(std::forward_list<std::string>& lst, const std::string& action, const std::string& key, int count) {
    try {
        // Simulate database connection and insertion of log entry
        std::time_t now = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());
        std::cout << "Timestamp: " << std::ctime(&now) << "Action: " << action << "Modified list state: ";
        for (const auto& item : lst) {
            std::cout << item << " ";
        }
        std::cout << "\n";
    } catch (const std::exception& e) {
        std::cerr << "Database connection failed: " << e.what() << '\n';
    }
}

int main() {
    try {
        std::forward_list<std::string> lst = {"apple", "banana", "cherry"};
        std::string key = "banana";
        std::string value = "orange";
        int count = 2;

        insertAfterFirst(lst, key, value, count);
        logOperation(lst, "Insert after first occurrence", key, count);

    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << '\n';
    }

    return 0;
}
