// Define a namespace to encapsulate all related functions
var ScriptRenderer = (function() {
    // Cache for stored scripts to minimize redundant network requests
    var scriptCache = {};

    // Regular expression to validate script type attributes
    var validScriptTypes = /^(text\/javascript|application\/javascript)$/i;

    // Function to fetch scripts from an external API endpoint
    function fetchScripts(apiUrl, onSuccess, onError) {
        // Check if the promise for this URL is already in cache
        if (scriptCache[apiUrl]) {
            return scriptCache[apiUrl];
        }

        // Create a new promise to handle the network request
        var fetchPromise = fetch(apiUrl)
            .then(response => response.json())
            .then(data => {
                onSuccess(data);
            })
            .catch(error => {
                onError(error);
            });

        // Store the promise in cache for future use
        scriptCache[apiUrl] = fetchPromise;

        return fetchPromise;
    }

    // Function to render scripts as <script> tags in a footer
    function renderScripts(scripts, footerElement) {
        scripts.forEach(script => {
            if (typeof script.code === 'string' && validScriptTypes.test(script.type)) {
                var scriptTag = document.createElement('script');
                scriptTag.innerHTML = script.code;
                scriptTag.async = true;
                footerElement.appendChild(scriptTag);
            } else {
                console.error('Invalid or missing properties in script object:', script);
            }
        });
    }

    // Function to manage and clean up old or unused script elements
    function cleanUpScripts(footerElement) {
        while (footerElement.firstChild) {
            footerElement.removeChild(footerElement.firstChild);
        }
    }

    // Main function to fetch and render scripts into a footer element
    function updateFooter(apiUrl, footerElement) {
        cleanUpScripts(footerElement);

        var spinner = document.createElement('div');
        spinner.textContent = 'Loading...';
        footerElement.appendChild(spinner);

        fetchScripts(apiUrl, (scripts) => {
            footerElement.removeChild(spinner);
            renderScripts(scripts, footerElement);
        }, (error) => {
            console.error('Error fetching scripts:', error);
            footerElement.removeChild(spinner);
            var errorMessage = document.createElement('div');
            errorMessage.textContent = 'Failed to load scripts.';
            footerElement.appendChild(errorMessage);
        });
    }

    // Public API for the ScriptRenderer module
    return {
        updateFooter: updateFooter
    };
})();

// Example usage:
var footerElement = document.querySelector('#footer-scripts');
ScriptRenderer.updateFooter('/api/scripts', footerElement);
```

