namespace DistributedSim {

class RandomNumberGenerator {
public:
    using SeedType = unsigned long;
    using RNGType = std::mt19937;

    RandomNumberGenerator(SeedType seed) : generator_(seed), distribution_(0, 1.0) {}

    void setRange(double min, double max) {
        distribution_ = std::uniform_real_distribution<>(min, max);
    }

    double generateRandom() {
        return distribution_(generator_);
    }

private:
    RNGType generator_;
    std::uniform_real_distribution<> distribution_;
};

class ExternalSeedSource {
public:
    virtual SeedType getSeed() = 0;
    virtual ~ExternalSeedSource() = default;
};

class DefaultSeedSource : public ExternalSeedSource {
public:
    SeedType getSeed() override {
        return std::chrono::system_clock::now().time_since_epoch().count();
    }
};

class NetworkSeedSource : public ExternalSeedSource {
private:
    // Simulate a network delay
    void simulateNetworkDelay() {
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }

public:
    SeedType getSeed() override {
        try {
            simulateNetworkDelay();
            // Simulate fetching seed from a network service
            return 42; // Placeholder for actual network call
        } catch (...) {
            throw std::runtime_error("Failed to fetch seed from external source");
        }
    }
};

class RNGManager {
public:
    RNGManager(ExternalSeedSource& source) : seedSource_(source), fallbackGenerator_(std::random_device()()) {}

    RandomNumberGenerator createRNG() {
        try {
            SeedType seed = seedSource_.getSeed();
            return RandomNumberGenerator(seed);
        } catch (...) {
            std::cerr << "Falling back to default seed generator" << std::endl;
            return RandomNumberGenerator(fallbackGenerator_());
        }
    }

private:
    ExternalSeedSource& seedSource_;
    RNGType fallbackGenerator_;
};

} // namespace DistributedSim

int main() {
    DistributedSim::NetworkSeedSource networkSource;
    DistributedSim::RNGManager rngManager(networkSource);

    for (size_t i = 0; i < 10; ++i) {
        auto rng = rngManager.createRNG();
        std::cout << "Random number: " << rng.generateRandom() << std::endl;
    }

    return 0;
}
