using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;

public class SqlQueryExecutor
{
    public static void ExecuteDynamicSql(
        SqlConnection connection, 
        string sqlCommandTemplate, 
        Dictionary<string, object> parameters)
    {
        if (connection == null || connection.State != ConnectionState.Open)
        {
            throw new ArgumentException("Invalid database connection.");
        }

        if (string.IsNullOrEmpty(sqlCommandTemplate))
        {
            throw new ArgumentException("SQL command template cannot be empty.");
        }

        using (SqlCommand command = new SqlCommand(sqlCommandTemplate, connection))
        {
            foreach (var param in parameters)
            {
                var sqlParam = new SqlParameter(param.Key, param.Value);
                command.Parameters.Add(sqlParam);
            }

            try
            {
                command.ExecuteNonQuery();
            }
            catch (SqlException ex)
            {
                LogError(ex.Message);
            }
            catch (Exception ex)
            {
                LogError($"Unexpected error: {ex.Message}");
            }
        }
    }

    public static void ExecuteDynamicQuery(
        SqlConnection connection, 
        string sqlCommandTemplate, 
        Dictionary<string, object> parameters, 
        out DataTable result)
    {
        if (connection == null || connection.State != ConnectionState.Open)
        {
            throw new ArgumentException("Invalid database connection.");
        }

        if (string.IsNullOrEmpty(sqlCommandTemplate))
        {
            throw new ArgumentException("SQL command template cannot be empty.");
        }

        using (SqlCommand command = new SqlCommand(sqlCommandTemplate, connection))
        {
            foreach (var param in parameters)
            {
                var sqlParam = new SqlParameter(param.Key, param.Value);
                command.Parameters.Add(sqlParam);
            }

            try
            {
                using (SqlDataAdapter adapter = new SqlDataAdapter(command))
                {
                    result = new DataTable();
                    adapter.Fill(result);
                }
            }
            catch (SqlException ex)
            {
                LogError(ex.Message);
                result = null;
            }
            catch (Exception ex)
            {
                LogError($"Unexpected error: {ex.Message}");
                result = null;
            }
        }
    }

    private static void LogError(string message)
    {
        // Implement error logging logic here
        Console.WriteLine($"Error: {message}");
    }
}
