class ScriptManager {
  constructor(apiUrl, cacheLimit = 10) {
    this.apiUrl = apiUrl;
    this.cache = {};
    this.cacheLimit = cacheLimit;
    this.loading = false;
  }

  async fetchScript(url) {
    if (this.cache[url]) return this.cache[url];
    try {
      this.loading = true;
      const response = await fetch(url);
      if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
      const script = await response.json();
      this.cache[url] = script;
      if (Object.keys(this.cache).length > this.cacheLimit) {
        const oldestKey = Object.keys(this.cache)[0];
        delete this.cache[oldestKey];
      }
      return script;
    } catch (error) {
      console.error('Error fetching script:', error);
      throw error;
    } finally {
      this.loading = false;
    }
  }

  async renderScripts(scripts) {
    let html = '';
    for (const script of scripts) {
      if (!script.code || !script.type) continue;
      try {
        const scriptElement = document.createElement('script');
        scriptElement.innerHTML = script.code;
        scriptElement.async = true;
        scriptElement.defer = true;
        scriptElement.key = Math.random().toString(36).substr(2, 9);
        html += scriptElement.outerHTML;
        document.head.appendChild(scriptElement);
      } catch (error) {
        console.error('Error rendering script:', error);
      }
    }
    return html;
  }

  async loadFooterScripts(scripts) {
    if (this.loading) return '';
    const loadingSpinner = this.renderLoadingSpinner();
    document.body.appendChild(loadingSpinner);

    let renderedHtml = '';
    for (const script of scripts) {
      try {
        const url = script.url || this.apiUrl;
        const fetchedScript = await this.fetchScript(url);
        if (fetchedScript.code) {
          renderedHtml += `<script key="${Math.random().toString(36).substr(2, 9)}">${fetchedScript.code}</script>`;
        }
      } catch (error) {
        console.error('Error loading script:', error);
      }
    }

    document.body.removeChild(loadingSpinner);
    return this.renderScripts(scripts.concat(JSON.parse(renderedHtml)));
  }

  renderLoadingSpinner() {
    const spinner = document.createElement('div');
    spinner.innerHTML = '<p>Loading...</p>';
    spinner.style.position = 'fixed';
    spinner.style.top = '50%';
    spinner.style.left = '50%';
    spinner.style.transform = 'translate(-50%, -50%)';
    return spinner;
  }
}

// Usage
const scriptManager = new ScriptManager('https://api.example.com/scripts');
scriptManager.loadFooterScripts([
  { url: 'https://example.com/script1.js' },
  { type: 'application/javascript', code: 'console.log("Script 2");' },
]);
