```csharp
using System;

public class RandomValueGenerator
{
    private double minValue;
    private double maxValue;
    private string distributionType;

    public RandomValueGenerator(double minValue, double maxValue, string distributionType)
    {
        if (minValue >= maxValue)
        {
            throw new ArgumentException("Max value must be greater than min value.");
        }

        this.minValue = minValue;
        this.maxValue = maxValue;
        this.distributionType = distributionType.ToLower();
    }

    public double GetRandomFloat()
    {
        Random random = new Random();
        switch (distributionType)
        {
            case "uniform":
                return minValue + (maxValue - minValue) * random.NextDouble();
            case "normal":
                return Math.Min(maxValue, Math.Max(minValue, random.NextGaussian() * 2 + minValue));
            default:
                throw new ArgumentException("Unsupported distribution type.");
        }
    }

    public int GetRandomInt()
    {
        Random random = new Random();
        switch (distributionType)
        {
            case "uniform":
                return random.Next((int)minValue, (int)(maxValue + 1));
            case "normal":
                double gaussian = random.NextGaussian() * 2;
                int result = (int)Math.Min(maxValue, Math.Max(minValue, gaussian)) - (int)minValue;
                return result >= 0 ? result : -(result + 1);
            default:
                throw new ArgumentException("Unsupported distribution type.");
        }
    }

    public double GetRandomFloatWithinQuantile(double lowerQuantile, double upperQuantile)
    {
        if (lowerQuantile < 0 || upperQuantile > 1 || lowerQuantile >= upperQuantile)
        {
            throw new ArgumentException("Invalid quantile values.");
        }

        Random random = new Random();
        switch (distributionType)
        {
            case "uniform":
                return minValue + (maxValue - minValue) * random.NextDouble() * (upperQuantile - lowerQuantile) + lowerQuantile;
            case "normal":
                double gaussian = random.NextGaussian() * 2;
                double quantileResult = Math.Min(maxValue, Math.Max(minValue, gaussian)) * (upperQuantile - lowerQuantile) + lowerQuantile;
                return quantileResult >= minValue && quantileResult <= maxValue ? quantileResult : GetRandomFloatWithinQuantile(lowerQuantile, upperQuantile);
            default:
                throw new ArgumentException("Unsupported distribution type.");
        }
    }

    public int GetRandomIntWithinStandardDeviation(double standardDeviations)
    {
        Random random = new Random();
        double mean = (minValue + maxValue) / 2;
        switch (distributionType)
        {
            case "uniform":
                return random.Next((int)Math.Max(minValue, mean - standardDeviations), (int)Math.Min(maxValue, mean + standardDeviations));
            case "normal":
                double gaussian = random.NextGaussian() * 2;
                int result = (int)Math.Min(maxValue, Math.Max(minValue, gaussian)) - (int)mean;
                return result >= 0 ? result : -(result + 1);
            default:
                throw new ArgumentException("Unsupported distribution type.");
        }
    }

    public override string ToString()
    {
        return $"Range: {minValue} to {maxValue}, Distribution: {distributionType}";
    }
}
