            throw new ArgumentException("Page section ID and element ID cannot be null or empty.");

        if (string.IsNullOrEmpty(htmlContent))
            throw new ArgumentException("HTML content cannot be null or empty.");

        var cacheKey = $"html_{pageSectionId}_{elementId}";
        var cachedHtml = await _cache.GetOrCreateAsync(cacheKey, async entry =>
        {
            entry.AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5);

            try
            {
                var storageUrl = GetStorageUrl(pageSectionId, elementId);
                var response = await _httpClient.GetAsync(storageUrl);
                if (response.IsSuccessStatusCode)
                {
                    return await response.Content.ReadAsStringAsync();
                }
                else
                {
                    throw new Exception($"Failed to fetch HTML content from storage. Status code: {response.StatusCode}");
                }
            }
            catch (Exception ex)
            {
                // Handle exceptions like network failures, storage service outages
                // Log the error and decide on a fallback strategy
                return null;
            }
        });

        if (cachedHtml == null)
        {
            throw new InvalidOperationException("Failed to fetch HTML content from cache.");
        }

        var updatedHtml = UpdateElementHtml(cachedHtml, elementId, htmlContent);

        try
        {
            var storageUrl = GetStorageUrl(pageSectionId, elementId);
            var content = new StringContent(updatedHtml, System.Text.Encoding.UTF8, "text/html");
