```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.util.Iterator;
import java.util.Random;

public class GameCharacter {

    private SocketChannel socketChannel;
    private Selector selector;
    private ByteBuffer buffer = ByteBuffer.allocate(1024);
    private long lastAttackTime = 0;
    private int attackCooldown = 5000; // Cooldown in milliseconds
    private Random random = new Random();

    public void establishConnectionAndHandleAttacks() {
        try {
            selector = Selector.open();
            socketChannel = SocketChannel.open(new InetSocketAddress("remote.server.com", 12345));
            socketChannel.configureBlocking(false);
            socketChannel.register(selector, SelectionKey.OP_CONNECT);

            while (true) {
                selector.select();

                Iterator<SelectionKey> keyIterator = selector.selectedKeys().iterator();
                while (keyIterator.hasNext()) {
                    SelectionKey key = keyIterator.next();

                    if (key.isConnectable()) {
                        connect(key);
                    } else if (key.isReadable()) {
                        read(key);
                    }

                    keyIterator.remove();
                }
            }
        } catch (IOException e) {
            System.err.println("Error in connection or data handling: " + e.getMessage());
        }
    }

    private void connect(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();
        if (channel.finishConnect()) {
            System.out.println("Connection established");
            selectAttackAndExecute();
        } else {
            channel.register(selector, SelectionKey.OP_CONNECT);
        }
    }

    private void read(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();
        int bytesRead = channel.read(buffer);
        if (bytesRead == -1) {
            System.out.println("Server closed connection");
            channel.close();
            key.cancel();
        } else if (bytesRead > 0) {
            buffer.flip();
            // Process incoming data
            buffer.clear();
        }
    }

    private void selectAttackAndExecute() {
        long currentTime = System.currentTimeMillis();
        if (currentTime - lastAttackTime >= attackCooldown) {
            int selectedAttack = random.nextInt(2);
            int attackPower;

            if (selectedAttack == 0) {
                // Attack A logic
                attackPower = random.nextInt(50); // Example power level
                System.out.println("Attacking with Attack A: Power " + attackPower);
            } else {
                // Attack B logic
                attackPower = random.nextInt(100); // Example power level
                System.out.println("Attacking with Attack B: Power " + attackPower);
            }

            lastAttackTime = currentTime;
        } else {
            long timeLeft = attackCooldown - (currentTime - lastAttackTime);
            System.out.println("Cooldown active. Time left until next attack: " + timeLeft + "ms");
        }
    }

    public static void main(String[] args) {
        GameCharacter gameCharacter = new GameCharacter();
        gameCharacter.establishConnectionAndHandleAttacks();
    }
}
