```csharp
using System;
using System.Collections.Generic;
using System.Threading;

public enum RangeType
{
    Closed,
    Open,
    HalfOpen
}

public delegate bool ConfigUpdateCallback(Dictionary<string, string> config);

public class DynamicRandomNumberGenerator
{
    private Random random;
    private object lockObject = new object();
    private Dictionary<string, string> configuration;

    public DynamicRandomNumberGenerator(bool seeded)
    {
        if (seeded)
            random = new Random();
    }

    public double GenerateCustomRandom(double min, double max, RangeType rangeType)
    {
        lock (lockObject)
        {
            switch (rangeType)
            {
                case RangeType.Closed:
                    return random.NextDouble() * (max - min) + min;
                case RangeType.Open:
                    if (min == max)
                        throw new ArgumentException("Min and Max values must be different for an open range.");
                    double result = random.NextDouble() * (max - min);
                    return Math.Min(Math.Max(result, min), max);
                case RangeType.HalfOpen:
                    return random.NextDouble() * (max - min) + min;
                default:
                    throw new ArgumentException("Invalid range type.");
            }
        }
    }

    public void ApplyConfiguration(Dictionary<string, string> config)
    {
        lock (lockObject)
        {
            configuration = config;
            // Apply configuration changes
        }
    }

    public bool UpdateConfig(ConfigUpdateCallback callback)
    {
        try
        {
            if (callback(configuration))
                return true;
            else
                throw new InvalidOperationException("Failed to update configuration.");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error updating configuration: {ex.Message}");
            return false;
        }
    }

    public int GenerateRandomInteger(int min, int max)
    {
        lock (lockObject)
        {
            return random.Next(min, max);
        }
    }

    public float GenerateRandomFloat(float min, float max)
    {
        lock (lockObject)
        {
            return (float)random.NextDouble() * (max - min) + min;
        }
    }
}
