<?php

/**
 * Generates a secure random string for use in URL tokens.
 *
 * @param int $length The desired length of the token.
 * @param string $charset A string containing all allowed characters for the token.
 * @return string|null The generated token, or null on failure.
 */
function generateSecureToken($length = 16, $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') {
    if ($length <= 0 || empty($charset)) {
        return null;
    }

    $token = '';
    for ($i = 0; $i < $length; $i++) {
        $token .= $charset[random_int(0, strlen($charset) - 1)];
    }

    return $token;
}

/**
 * Hashes a password using the specified algorithm and salt.
 *
 * @param string $password The password to hash.
 * @param string $algorithm The hashing algorithm to use (e.g., 'bcrypt', 'argon2id').
 * @return string|null The hashed password, or null on failure.
 */
function hashPassword($password, $algorithm = PASSWORD_BCRYPT) {
    if (empty($password)) {
        return null;
    }

    $options = [
        'cost' => 10,
    ];

    return password_hash($password, $algorithm, $options);
}

/**
 * Validates and sanitizes input parameters for use in URL tokens.
 *
 * @param string $input The input to validate and sanitize.
 * @return string|null The sanitized input, or null if it is invalid.
 */
function validateTokenInput($input) {
    if (empty($input)) {
        return null;
    }

    // Add your validation logic here (e.g., check for allowed characters)

    return $input;
}

/**
 * Stores a URL token and hashed password in the session.
 *
 * @param string $token The URL token to store.
 * @param string $hashedPassword The hashed password to store.
 */
function storeSessionData($token, $hashedPassword) {
    $_SESSION['url_token'] = $token;
    $_SESSION['hashed_password'] = $hashedPassword;
}

/**
 * Retrieves a URL token and hashed password from the session.
 *
 * @return array|null An associative array with 'url_token' and 'hashed_password', or null if not found.
 */
function getSessionData() {
    return [
        'url_token' => $_SESSION['url_token'] ?? null,
        'hashed_password' => $_SESSION['hashed_password'] ?? null,
    ];
}

