using System;
using System.Collections.Concurrent;
using System.Data;
using System.Threading.Tasks;

public class DatabaseConnectionManager : IDisposable
{
    private readonly ConcurrentDictionary<string, Queue<IDbConnection>> _connectionPools = new();
    private int _minPoolSize;
    private int _maxPoolSize;
    private int _idleTimeout;
    private Timer _poolMaintenanceTimer;

    public void ConfigurePooling(int minSize, int maxSize, int idleTimeout)
    {
        _minPoolSize = minSize;
        _maxPoolSize = maxSize;
        _idleTimeout = idleTimeout;

        // Start the pool maintenance timer
        _poolMaintenanceTimer = new Timer(MaintainConnectionPool, null, TimeSpan.Zero, TimeSpan.FromSeconds(30));
    }

    public void InitializeFromConfiguration()
    {
        // Load connection settings from external configuration management system
        var providerName = Environment.GetEnvironmentVariable("DB_PROVIDER");
        var connectionString = Environment.GetEnvironmentVariable("DB_CONNECTION_STRING");

        // Ensure the provider is supported
        if (!_connectionPools.ContainsKey(providerName))
        {
            _connectionPools[providerName] = new Queue<IDbConnection>();
        }
    }

    public IDbConnection GetConnection(string provider, string connectionString)
    {
        if (!_connectionPools.ContainsKey(provider))
        {
            _connectionPools[provider] = new Queue<IDbConnection>();
        }

        var pool = _connectionPools[provider];
        lock (pool)
        {
            if (pool.Count > 0)
            {
                var connection = pool.Dequeue();
                if (IsConnectionValid(connection))
                {
                    return connection;
                }
                else
                {
                    connection.Dispose();
                }
            }

            // Create a new connection if none are available or all are invalid
            return CreateNewConnection(provider, connectionString);
        }
    }

    public void ReleaseConnection(IDbConnection connection)
    {
        var provider = connection.GetType().Namespace.Split('.').Last();
        if (_connectionPools.ContainsKey(provider))
        {
            var pool = _connectionPools[provider];
            lock (pool)
            {
                pool.Enqueue(connection);
                EnsurePoolSize(provider);
            }
        }
    }

    public override string ToString()
    {
        var poolSummary = new System.Text.StringBuilder();
        foreach (var kvp in _connectionPools)
        {
            poolSummary.AppendLine($"{kvp.Key}: Active Connections {kvp.Value.Count}");
        }
        return $"DatabaseConnectionManager - Pool Summary:\n{poolSummary}";
    }

    public PerformanceMetrics GetPerformanceMetrics()
    {
        var metrics = new PerformanceMetrics
        {
            ConnectionRequestLatency = GetAverageRequestLatency(),
            ConnectionPoolSize = GetTotalConnectionCount(),
            IdleConnectionCount = GetIdleConnectionCount()
        };
        return metrics;
    }

    private IDbConnection CreateNewConnection(string provider, string connectionString)
    {
        var assemblyName = $"System.Data.{provider}";
        var className = $"{provider}.SqlClient.SqlConnection";
        var type = Type.GetType($"{assemblyName}.{className}");
        var connection = (IDbConnection)Activator.CreateInstance(type);
        connection.ConnectionString = connectionString;
        return connection;
    }

    private bool IsConnectionValid(IDbConnection connection)
    {
        try
        {
            if (connection.State == ConnectionState.Closed)
            {
                connection.Open();
            }
            return true;
        }
        catch
        {
            return false;
        }
    }

    private void MaintainConnectionPool(object state)
    {
        foreach (var kvp in _connectionPools)
        {
            var pool = kvp.Value;
            lock (pool)
            {
                while (pool.Count > 0 && DateTime.Now - pool.Peek().LastAccessTime > TimeSpan.FromSeconds(_idleTimeout))
                {
                    var connection = pool.Dequeue();
                    connection.Dispose();
                }

                EnsurePoolSize(kvp.Key);
            }
        }
    }

    private void EnsurePoolSize(string provider)
    {
        var pool = _connectionPools[provider];
        lock (pool)
        {
            while (pool.Count < _minPoolSize && pool.Count < _maxPoolSize)
            {
                var connection = CreateNewConnection(provider, GetConnectionStringFromConfig(provider));
                pool.Enqueue(connection);
            }
        }
    }

    private string GetConnectionStringFromConfig(string provider)
    {
        // Simulate loading from configuration
        return Environment.GetEnvironmentVariable($"{provider}_CONNECTION_STRING");
    }

    private double GetAverageRequestLatency()
    {
        // Implement logic to calculate average request latency
        return 0.5; // Placeholder value
    }

    private int GetTotalConnectionCount()
    {
        var total = 0;
        foreach (var pool in _connectionPools.Values)
        {
            total += pool.Count;
        }
        return total;
    }

    private int GetIdleConnectionCount()
    {
        var idleCount = 0;
        foreach (var pool in _connectionPools.Values)
        {
            foreach (var connection in pool)
            {
                if ((DateTime.Now - connection.LastAccessTime) > TimeSpan.FromSeconds(_idleTimeout))
                {
                    idleCount++;
                }
            }
        }
        return idleCount;
    }

    public void Dispose()
    {
        _poolMaintenanceTimer?.Change(Timeout.Infinite, 0);
        foreach (var pool in _connectionPools.Values)
        {
            while (pool.Count > 0)
            {
                var connection = pool.Dequeue();
                connection.Dispose();
            }
        }
    }

    public class PerformanceMetrics
    {
        public double ConnectionRequestLatency { get; set; }
        public int ConnectionPoolSize { get; set; }
        public int IdleConnectionCount { get; set; }
    }
}
