    public static async Task<TaskResult> AddAndStartWebsite(string directoryPath, string siteName)
    {
        try
        {
            // Check if web.config exists
            string webConfigPath = Path.Combine(directoryPath, "web.config");
            if (!File.Exists(webConfigPath))
            {
                LogError("Missing web.config file in the specified directory.");
                return new TaskResult { Success = false, Message = "Web configuration file not found." };
            }

            // Create a new website
            using (ServerManager serverManager = new ServerManager())
            {
                if (serverManager.Sites[siteName] != null)
                {
                    LogError("Website already exists.");
                    return new TaskResult { Success = false, Message = "A website with the same name already exists." };
                }

                Site site = serverManager.Sites.Add(siteName, directoryPath, "*:8080:");
                site.ServerAutoStart = true;
                serverManager.CommitChanges();

                // Start the website
                site.Start();
                return new TaskResult { Success = true, Message = "Website added and started successfully." };
            }
        }
        catch (Exception ex)
        {
            LogError($"An error occurred: {ex.Message}");
            return new TaskResult { Success = false, Message = $"An error occurred: {ex.Message}" };
        }
    }

    private static void LogError(string message)
    {
        // Implement logging logic here
        Console.WriteLine(message);
    }
}

public class TaskResult
{
    public bool Success { get; set; }
    public string Message { get; set; }
