using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class FileEncryptor
{
    private readonly IKeyManagementService _keyManagementService;

    public FileEncryptor(IKeyManagementService keyManagementService)
    {
        _keyManagementService = keyManagementService;
    }

    public async Task<byte[]> EncryptFileAsync(string filePath, string encryptionKeyId)
    {
        var (encryptionKey, salt) = await _keyManagementService.GetKeyAndSaltAsync(encryptionKeyId);
        using (var aesGcm = Aes.Create())
        {
            aesGcm.Key = encryptionKey;
            aesGcm.IV = GenerateRandomBytes(12); // 96-bit IV
            aesGcm.GCMTagLength = 128; // 128-bit tag

            var (nonce, ciphertext, tag) = await EncryptDataAsync(File.ReadAllBytes(filePath), aesGcm);

            File.WriteAllBytes(filePath + ".enc", nonce);
            File.WriteAllBytes(filePath + ".tag", tag);
            File.WriteAllBytes(filePath + ".gcm", ciphertext);

            return tag;
        }
    }

    public async Task<byte[]> DecryptFileAsync(string filePath, string encryptionKeyId)
    {
        var (encryptionKey, salt) = await _keyManagementService.GetKeyAndSaltAsync(encryptionKeyId);
        using (var aesGcm = Aes.Create())
        {
            aesGcm.Key = encryptionKey;

            var nonce = File.ReadAllBytes(filePath + ".enc");
            aesGcm.IV = nonce;
            aesGcm.GCMTagLength = 128; // 128-bit tag

            var ciphertext = File.ReadAllBytes(filePath + ".gcm");
            var tag = File.ReadAllBytes(filePath + ".tag");

            return await DecryptDataAsync(nonce, ciphertext, tag, aesGcm);
        }
    }

    private static byte[] GenerateRandomBytes(int length)
    {
        using (var rng = RandomNumberGenerator.Create())
        {
            var bytes = new byte[length];
            rng.GetBytes(bytes);
            return bytes;
        }
    }

    private async Task<(byte[], byte[], byte[])> EncryptDataAsync(byte[] data, Aes aesGcm)
    {
        using (var memoryStream = new MemoryStream())
        using (var cryptoStream = new CryptoStream(memoryStream, aesGcm.CreateEncryptor(), CryptoStreamMode.Write))
        {
            await cryptoStream.WriteAsync(data, 0, data.Length);
            await cryptoStream.FlushFinalBlockAsync();
        }

        return (aesGcm.IV, memoryStream.ToArray(), aesGcm.Tag);
    }

    private async Task<byte[]> DecryptDataAsync(byte[] nonce, byte[] ciphertext, byte[] tag, Aes aesGcm)
    {
        using (var memoryStream = new MemoryStream(ciphertext))
        using (var cryptoStream = new CryptoStream(memoryStream, aesGcm.CreateDecryptor(), CryptoStreamMode.Read))
        using (var outputStream = new MemoryStream())
        {
            await cryptoStream.CopyToAsync(outputStream);
        }

        return outputStream.ToArray();
    }
}

public interface IKeyManagementService
{
    Task<(byte[], byte[])> GetKeyAndSaltAsync(string keyId);
}
