std::string generateNewFileName(const std::string& filePath) {
    const int MAX_FILE_NAME_LENGTH = 255;
    char newFileName[MAX_FILE_NAME_LENGTH];

    // Extract directory, base name, and extension from file path
    size_t lastSlashPos = filePath.find_last_of("/\\");
    std::string directory = (lastSlashPos != std::string::npos) ? filePath.substr(0, lastSlashPos + 1) : "";
    std::string baseNameWithExtension = (lastSlashPos != std::string::npos) ? filePath.substr(lastSlashPos + 1) : filePath;

    size_t dotPos = baseNameWithExtension.find_last_of('.');
    std::string baseName = (dotPos != std::string::npos) ? baseNameWithExtension.substr(0, dotPos) : baseNameWithExtension;
    std::string extension = (dotPos != std::string::npos) ? baseNameWithExtension.substr(dotPos) : "";

    // Get current timestamp
    time_t now = time(nullptr);
    struct tm* timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);

    // Generate random alphanumeric string
    const std::string chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    std::string version(10, '\0');
    for (int i = 0; i < version.length(); ++i) {
        version[i] = chars[rand() % chars.length()];
    }

    // Create new file name
    snprintf(newFileName, MAX_FILE_NAME_LENGTH, "%s%s_%s%s", directory.c_str(), baseName.c_str(), timestamp, extension.c_str());

    return std::string(newFileName);
}

int main() {
    std::string filePath = "/path/to/your/file.txt";
    std::string newFileName = generateNewFileName(filePath);
    std::cout << "Original file path: " << filePath << std::endl;
    std::cout << "Generated new file name: " << newFileName << std::endl;
    return 0;
}
