typedef struct {
    char *access_token;
    int expires_in;
    char *token_type;
    char *refresh_token;
} OAuth2Token;

bool validate_oauth2_token(const char *json_string, OAuth2Token *token) {
    // Parse the JSON string and populate the token structure
    // Check for required fields and values
    if (strcmp(token->token_type, "Bearer") != 0 || token->expires_in <= 0) {
        return false;
    }
    return true;
}

RequestBuilder* create_request_builder(const char *url, bool disable_certificate_validation) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        return NULL;
    }

    RequestBuilder *builder = (RequestBuilder*)malloc(sizeof(RequestBuilder));
    builder->curl = curl;

    if (disable_certificate_validation) {
        curl_easy_setopt(curl, CURLOPT_SSL_VERIFYPEER, 0L);
        curl_easy_setopt(curl, CURLOPT_SSL_VERIFYHOST, 0L);
    }

    return builder;
}

void free_request_builder(RequestBuilder *builder) {
    if (builder->curl) {
        curl_easy_cleanup(builder->curl);
    }
    free(builder);
}
