#include <iostream>
#include <vector>
#include <mutex>
#include <condition_variable>

struct OctreeNode {
    std::vector<void*> data;
    std::array<OctreeNode*, 8> children;
    bool isLeaf;

    OctreeNode() : isLeaf(true) {}

    ~OctreeNode() {
        for (auto child : children)
            delete child;
    }
};

class Octree {
private:
    OctreeNode* root;
    std::mutex tree_mutex;
    std::condition_variable data_available;
    size_t maxDataCapacity;

public:
    Octree(size_t capacity) : root(new OctreeNode()), maxDataCapacity(capacity) {}

    ~Octree() {
        delete root;
    }

    bool insert(const void* data, const std::array<int, 3>& bounds) {
        std::unique_lock<std::mutex> lock(tree_mutex);
        if (root->data.size() >= maxDataCapacity) {
            return false; // Full node
        }
        // Insert logic here based on spatial partitioning of bounds
        root->data.push_back(const_cast<void*>(data));
        return true;
    }

    std::vector<const void*> query(const std::array<int, 3>& bounds) {
        std::unique_lock<std::mutex> lock(tree_mutex);
        std::vector<const void*> result;
        // Query logic here based on spatial partitioning of bounds
        return result;
    }

    void waitForData() {
        std::unique_lock<std::mutex> lock(tree_mutex);
        data_available.wait(lock, [this] { return root->data.size() > 0; });
    }
};

int main() {
    Octree octree(100);
    // Example usage
    octree.insert(nullptr, {0, 0, 0});
    octree.waitForData();
    std::vector<const void*> results = octree.query({0, 0, 0});
    return 0;
}
```
This code provides a basic structure for an Octree class with a mutex and condition variable to handle concurrent access and synchronization. The `insert` method is intended for inserting data into the tree, while the `query` method is for retrieving data based on spatial bounds. Error handling for full nodes and invalid inputs is included, and the `waitForData` method allows for waiting until data becomes available. This example uses a simple array to store pointers as data, but you can replace it with your own data type as needed.

