#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

typedef struct {
    CURL *curl;
    FILE *output_file;
} DownloadTask;

typedef struct {
    size_t total_bytes_downloaded;
    pthread_t *thread_ids;
    int num_threads_active;
    int download_successful;
} DownloadResult;

size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    FILE *file = (FILE *)userdata;
    if (fwrite(ptr, size, nmemb, file) != nmemb) {
        return 0;
    }
    return size * nmemb;
}

void *download_thread(void *arg) {
    DownloadTask *task = (DownloadTask *)arg;
    CURLcode res = curl_easy_setopt(task->curl, CURLOPT_WRITEFUNCTION, write_callback);
    if (res == CURLE_OK) {
        res = curl_easy_setopt(task->curl, CURLOPT_WRITEDATA, task->output_file);
    }
    if (res == CURLE_OK) {
        res = curl_easy_perform(task->curl);
    }
    long response_code;
    curl_easy_getinfo(task->curl, CURLINFO_RESPONSE_CODE, &response_code);
    if (res == CURLE_OK && response_code >= 200 && response_code < 300) {
        task->download_successful = 1;
    } else {
        task->download_successful = 0;
    }
    curl_easy_cleanup(task->curl);
    fclose(task->output_file);
    free(task);
    return NULL;
}

DownloadResult *download_url(const char *url, const char *output_file_path, int num_threads) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        return NULL;
    }
    FILE *output_file = fopen(output_file_path, "wb");
    if (!output_file) {
        curl_easy_cleanup(curl);
        return NULL;
    }

    DownloadTask task = {curl, output_file};
    pthread_t *thread_ids = (pthread_t *)malloc(num_threads * sizeof(pthread_t));
    if (!thread_ids) {
        fclose(output_file);
        curl_easy_cleanup(curl);
        return NULL;
    }

    DownloadResult *result = (DownloadResult *)malloc(sizeof(DownloadResult));
    if (!result) {
        free(thread_ids);
        fclose(output_file);
        curl_easy_cleanup(curl);
        return NULL;
    }
    result->total_bytes_downloaded = 0;
    result->thread_ids = thread_ids;
    result->num_threads_active = num_threads;
    result->download_successful = 1;

    int i;
    for (i = 0; i < num_threads; i++) {
        if (pthread_create(&result->thread_ids[i], NULL, download_thread, &task) != 0) {
            result->download_successful = 0;
            break;
        }
    }

    if (!result->download_successful) {
        for (i = 0; i < num_threads; i++) {
            pthread_join(result->thread_ids[i], NULL);
        }
        free(thread_ids);
        fclose(output_file);
        curl_easy_cleanup(curl);
        free(result);
        return NULL;
    }

    for (i = 0; i < num_threads; i++) {
        pthread_join(result->thread_ids[i], NULL);
    }

    long total_bytes = 0;
    for (i = 0; i < num_threads; i++) {
        // Assuming each thread downloads a portion of the file
        // Here, we're just adding up the bytes downloaded by all threads
        total_bytes += result->thread_ids[i].total_bytes_downloaded;
    }
    result->total_bytes_downloaded = total_bytes;

    free(thread_ids);
    fclose(output_file);
    curl_easy_cleanup(curl);

    return result;
}
