```javascript
const fs = require('fs');
const path = require('path');

// Configuration file structure:
// {
//   "modules": [
//     {"name": "moduleA", "path": "./modules/moduleA.js"},
//     {"name": "moduleB", "path": "./modules/moduleB.js"}
//   ],
//   "concurrency": 2
// }

function loadModules(config) {
  const modules = new Map();
  const moduleQueue = [];
  let concurrencyLevel = config.concurrency;

  function loadModule(moduleConfig) {
    if (modules.has(moduleConfig.name)) return;
    try {
      const modulePath = path.resolve(__dirname, moduleConfig.path);
      const module = require(modulePath);
      modules.set(moduleConfig.name, module);
      console.log(`Loaded ${moduleConfig.name}`);
    } catch (error) {
      console.error(`Failed to load ${moduleConfig.name}:`, error);
    }
  }

  function executeModule(moduleName) {
    if (!modules.has(moduleName)) return;
    try {
      const module = modules.get(moduleName);
      module();
      console.log(`Executed ${moduleName}`);
    } catch (error) {
      console.error(`Failed to execute ${moduleName}:`, error);
    }
  }

  function processQueue() {
    while (concurrencyLevel > 0 && moduleQueue.length > 0) {
      const moduleConfig = moduleQueue.shift();
      loadModule(moduleConfig);
      concurrencyLevel--;
    }
    if (moduleQueue.length > 0) {
      setTimeout(processQueue, 100); // Adjust the timeout as needed
    }
  }

  config.modules.forEach(moduleConfig => {
    if (!fs.existsSync(path.resolve(__dirname, moduleConfig.path))) {
      console.warn(`Module not found: ${moduleConfig.path}`);
    } else {
      moduleQueue.push(moduleConfig);
    }
  });

  processQueue();

  setInterval(() => {
    concurrencyLevel = Math.min(config.concurrency, moduleQueue.length);
    processQueue();
  }, 1000); // Adjust the interval as needed
}

// Example usage:
const configPath = path.resolve(__dirname, 'config.json');
loadModules(JSON.parse(fs.readFileSync(configPath, 'utf8')));
