#include <iostream>
#include <forward_list>
#include <algorithm>
#include <string>
#include <mutex>
#include <memory>

// Function to insert a replacement string after the first occurrence of a target string in a forward list
void insertAfterFirstOccurrence(std::forward_list<std::string>& lst, const std::string& target, const std::string& replacement, bool caseInsensitive = false) {
    // Lock to ensure thread safety
    static std::mutex mtx;
    std::lock_guard<std::mutex> lock(mtx);

    // Iterator to traverse the forward list
    auto it = lst.begin();

    // Search for the target string
    while (it != lst.end()) {
        if (caseInsensitive) {
            // Case-insensitive comparison using tolower function
            if (std::equal(it->begin(), it->end(), target.begin(), target.end(), [](char a, char b) { return std::tolower(a) == std::tolower(b); })) {
                ++it; // Move to the next element for insertion
                lst.insert_after(prev(it), replacement);
                break;
            }
        } else {
            if (*it == target) {
                ++it;
                lst.insert_after(prev(it), replacement);
                break;
            }
        }
        ++it;
    }

    // If target not found, insert at the end of the list
    if (it == lst.end()) {
        lst.push_back(replacement);
    }
}

// Example usage
int main() {
    std::forward_list<std::string> myList = {"apple", "banana", "orange"};
    insertAfterFirstOccurrence(myList, "banana", "grape");
    for (const auto& item : myList) {
        std::cout << item << " ";
    }
    return 0;
}
