#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    sem_t *sem;
} SemaphoreManager;

// Function to create and initialize a semaphore
SemaphoreManager* create_semaphore(int initial_value) {
    SemaphoreManager *manager = (SemaphoreManager*)malloc(sizeof(SemaphoreManager));
    manager->sem = (sem_t*)malloc(sizeof(sem_t));
    if (sem_init(manager->sem, 0, initial_value) != 0) {
        free(manager);
        return NULL;
    }
    return manager;
}

// Function to destroy a semaphore and clean up
void destroy_semaphore(SemaphoreManager *manager) {
    sem_destroy(manager->sem);
    free(manager->sem);
    free(manager);
}

// Function for threads to acquire the semaphore
int semaphore_acquire(SemaphoreManager *manager) {
    if (sem_wait(manager->sem) == 0) {
        return 1; // Success
    }
    return -1; // Failure
}

// Function for threads to release the semaphore
void semaphore_release(SemaphoreManager *manager) {
    sem_post(manager->sem);
}

int main() {
    SemaphoreManager *my_semaphore = create_semaphore(3); // Allow up to 3 concurrent accesses

    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
        if (pthread_create(&threads[i], NULL, thread_task, my_semaphore) != 0) {
            perror("Thread creation failed");
        }
    }

    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    destroy_semaphore(my_semaphore);

    return 0;
}

// Example task that acquires and releases the semaphore
void* thread_task(void *arg) {
    SemaphoreManager *manager = (SemaphoreManager*)arg;

    if (semaphore_acquire(manager) == -1) {
        printf("Failed to acquire semaphore\n");
        return NULL;
    }

    // Perform resource access here

    semaphore_release(manager);

    return NULL;
}
