}

void process_log_files_in_directory(const char* directory) {
    DIR* dir = opendir(directory);

    if (!dir) {
        perror("Error opening directory");
        return;
    }

    struct dirent* entry;

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG && strstr(entry->d_name, ".log") != NULL) {
            LogFile file_info = {entry->d_name, 0};
            log_files[file_count++] = file_info;

            pthread_create(&file_info.thread_id, NULL, process_log_file, &file_info);
        }
    }

    closedir(dir);

    for (int i = 0; i < file_count; i++) {
        pthread_join(log_files[i].thread_id, NULL);
    }
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <directory>\n", argv[0]);
        return 1;
    }

    process_log_files_in_directory(argv[1]);

    return 0;
}
