# Python function to update user profile picture in a distributed database system using DAO class

import os
from PIL import Image
import requests
from functools import wraps
from azure.storage.blob import BlobServiceClient, ContainerClient, BlobClient

class UserProfileDAO:
    def __init__(self, connection_string):
        self.connection_string = connection_string

    def update_profile_picture(self, user_id, image_file_path, max_size=5 * 1024 * 1024, allowed_formats=['png', 'jpg']):
        if not os.path.exists(image_file_path):
            raise FileNotFoundError("Image file not found")

        # Validate image format
        _, ext = os.path.splitext(image_file_path)
        if ext[1:].lower() not in allowed_formats:
            raise ValueError("Unsupported image format. Only PNG and JPG are allowed.")

        # Validate image size
        with Image.open(image_file_path) as img:
            if img.size > max_size:
                raise ValueError(f"Image file is too large. Maximum size: {max_size} bytes")

        # Cache updated profile picture
        cache_key = f"user_{user_id}_profile_picture"
        cache.set(cache_key, image_file_path)

        # Support versioning for concurrent updates
        version = 1
        current_version_key = f"{cache_key}_version"
        if cache.exists(current_version_key):
            version = int(cache.get(current_version_key)) + 1
        cache.set(current_version_key, str(version))

        # External cloud storage API integration with retries
        max_retries = 3
        for attempt in range(max_retries):
            try:
                blob_service_client = BlobServiceClient.from_connection_string(self.connection_string)
                container_name = "user-profile-pictures"
                container_client = blob_service_client.get_container_client(container_name)
                blob_client = container_client.get_blob_client(f"user_{user_id}_profile_picture_v{version}")
                with open(image_file_path, "rb") as data:
                    blob_client.upload_blob(data, overwrite=True)
                break
            except Exception as e:
                if attempt == max_retries - 1:
                    raise
