using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading;
using System.Threading.Tasks;

public class FileChunkProcessor
{
    private readonly int _chunkSize;
    private readonly int _bufferSize;
    private Action<string> _loggingCallback;

    public delegate void LoggingCallback(string message);

    public FileChunkProcessor(int chunkSize, int bufferSize)
    {
        if (chunkSize <= 0) throw new ArgumentException("Chunk size must be greater than zero.");
        if (bufferSize <= 0) throw new ArgumentException("Buffer size must be greater than zero.");

        _chunkSize = chunkSize;
        _bufferSize = bufferSize;
    }

    public void SetLoggingCallback(Action<string> callback)
    {
        _loggingCallback = callback ?? throw new ArgumentNullException(nameof(callback));
    }

    public async Task DecryptFileChunkAsync(string filePath, byte[] key, byte[] iv)
    {
        if (string.IsNullOrEmpty(filePath)) throw new ArgumentException("File path cannot be null or empty.");
        if (key == null || key.Length != 24) throw new ArgumentException("Invalid key length for Triple DES encryption.");
        if (iv == null || iv.Length != 8) throw new ArgumentException("Invalid IV length for Triple DES encryption.");

        using (var reader = File.OpenRead(filePath))
        using (var writer = File.Create(filePath + ".decrypted"))
        using (var cryptoTransform = Aes.Create().CreateDecryptor(key, iv))
        {
            byte[] buffer = new byte[_bufferSize];
            int bytesRead;

            while ((bytesRead = await reader.ReadAsync(buffer, 0, buffer.Length)) > 0)
            {
                var chunkBuffer = new byte[Math.Min(bytesRead, _chunkSize)];
                Array.Copy(buffer, chunkBuffer, chunkBuffer.Length);

                var decryptedChunk = cryptoTransform.TransformFinalBlock(chunkBuffer, 0, chunkBuffer.Length);
                await writer.WriteAsync(decryptedChunk, 0, decryptedChunk.Length);

                if (_loggingCallback != null)
                {
                    _loggingCallback($"Processed {chunkBuffer.Length} bytes");
                }
            }

            if (_loggingCallback != null)
            {
                _loggingCallback("File decryption completed.");
            }
        }
    }

    public void DecryptFileChunk(string filePath, byte[] key, byte[] iv)
    {
        Task.Run(() => DecryptFileChunkAsync(filePath, key, iv)).Wait();
    }
}
