    initialize_dns_resolver(argc, argv);
    // Start worker threads for handling concurrent requests
    pthread_t thread;
    while (1) {
        // Wait for new requests and pass them to worker threads
        handle_request("request_hostname");
        pthread_create(&thread, NULL, worker_thread, NULL);
        pthread_detach(thread);
    }
    return 0;
}

// Worker thread function
void* worker_thread(void *arg) {
