```javascript
// JavaScript code to render dynamic footer scripts

function fetchScripts(urls) {
    const cache = new Map();
    let spinner = document.createElement('div');
    spinner.textContent = 'Loading...';
    document.body.appendChild(spinner);

    async function loadScript(url) {
        if (cache.has(url)) return cache.get(url);
        try {
            let response = await fetch(url, { timeout: 5000 });
            if (!response.ok) throw new Error('Network response was not ok');
            let code = await response.text();
            cache.set(url, code);
            return code;
        } catch (error) {
            console.error(`Failed to load script from ${url}:`, error);
            return null;
        }
    }

    async function renderScripts() {
        spinner.remove();
        let scriptsHTML = '';
        for (let url of urls) {
            let code = await loadScript(url);
            if (code) {
                scriptsHTML += `<script key="${Date.now()}">${code}</script>`;
            }
        }
        document.body.insertAdjacentHTML('beforeend', scriptsHTML);
    }

    renderScripts();
}

// Example usage:
fetchScripts(['https://example.com/script1.js', 'https://example.com/script2.js']);
