using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;

public static IDataReader CreateParameterizedSqlCommand(List<object> values, SqlConnection connection, string commandText)
{
    if (values == null || connection == null || string.IsNullOrEmpty(commandText))
        throw new ArgumentException("Invalid input parameters");

    SqlCommand command = new SqlCommand(commandText, connection);
    for (int i = 0; i < values.Count; i++)
    {
        SqlParameter parameter = new SqlParameter("@p" + i, SqlDbType.Object);
        parameter.Value = values[i];
        command.Parameters.Add(parameter);
    }

    try
    {
        connection.Open();
        return command.ExecuteReader(CommandBehavior.CloseConnection);
    }
    catch (Exception ex)
    {
        Console.WriteLine("Error executing SQL command: " + ex.Message);
        throw;
    }
}
