const blueslip = require('blueslip-mock');
const { performance } = require('perf_hooks');

function runTests(moduleLabel, testSuite) {
  console.log(`Starting tests for ${moduleLabel}`);

  const testResults = [];

  function logTestResult(testName, result) {
    if (result.success) {
      console.log(`${testName} passed`);
    } else {
      console.error(`${testName} failed: ${result.error}`);
    }
  }

  async function runSingleTest(testFunction, testName) {
    blueslip.reset(); // Reset the mocking library before each test
    const startTime = performance.now();

    try {
      await testFunction(label => label === testName);
      testResults.push({ name: testName, success: true });
    } catch (error) {
      testResults.push({ name: testName, success: false, error: error.message });
    }

    const endTime = performance.now();
    console.log(`${testName} took ${endTime - startTime}ms`);
  }

  for (const { label, testFunction } of testSuite) {
    runSingleTest(testFunction, label);
  }

  console.log('All tests completed');
  return testResults;
}

// Example usage:
const moduleLabel = 'mathUtils';
const testSuite = [
  {
    label: 'addition',
    testFunction: async (label) => {
      // Test implementation for addition
    }
  },
  // Add more test cases as needed
];

runTests(moduleLabel, testSuite);
