using System;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class SecureCipherService : IDisposable
{
    private HttpClient httpClient;
    private string tokenEndpoint;
    private string clientId;
    private string clientSecret;
    private ICryptoTransform decryptor;
    private byte[] key;
    private byte[] iv;
    private TimeSpan tokenExpiryBuffer;
    private DateTime? cachedTokenExpiry;

    public SecureCipherService(string tokenEndpoint, string clientId, string clientSecret, byte[] key, byte[] iv)
    {
        this.tokenEndpoint = tokenEndpoint;
        this.clientId = clientId;
        this.clientSecret = clientSecret;
        this.key = key;
        this.iv = iv;
        this.tokenExpiryBuffer = TimeSpan.FromMinutes(5);
        httpClient = new HttpClient();
        InitializeDecryptor();
    }

    private void InitializeDecryptor()
    {
        decryptor = Aes.Create().CreateDecryptor(key, iv);
    }

    public async Task<byte[]> DecryptMessageAsync(byte[] ciphertext, int offset = 0)
    {
        try
        {
            EnsureTokenIsValid();

            using (var memoryStream = new MemoryStream(ciphertext))
            {
                memoryStream.Position = offset;
                using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read))
                {
                    using (var resultStream = new MemoryStream())
                    {
                        await cryptoStream.CopyToAsync(resultStream);
                        return resultStream.ToArray();
                    }
                }
            }
        }
        catch (PaddingOracleException)
        {
            throw new Exception("Padding oracle attack detected. Decryption failed.");
        }
        catch (Exception ex)
        {
            throw new Exception($"Decryption failed: {ex.Message}");
        }
    }

    private async Task EnsureTokenIsValid()
    {
        if (cachedTokenExpiry == null || cachedTokenExpiry <= DateTime.UtcNow.Add(tokenExpiryBuffer))
        {
            await AuthenticateAsync();
        }
    }

    private async Task AuthenticateAsync()
    {
        var tokenRequest = new
        {
            client_id = clientId,
            client_secret = clientSecret,
            grant_type = "client_credentials"
        };

        var content = new StringContent(Newtonsoft.Json.JsonConvert.SerializeObject(tokenRequest), System.Text.Encoding.UTF8, "application/json");

        try
        {
            HttpResponseMessage response = await httpClient.PostAsync(tokenEndpoint, content);
            if (response.IsSuccessStatusCode)
            {
                var tokenResponse = Newtonsoft.Json.JsonConvert.DeserializeObject<dynamic>(await response.Content.ReadAsStringAsync());
                // Assuming the token and expiry time are returned in a specific format
                string accessToken = tokenResponse.access_token;
                cachedTokenExpiry = DateTime.UtcNow.AddSeconds((int)tokenResponse.expires_in);
                // Set the authorization header for subsequent requests if needed
                httpClient.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", accessToken);
            }
            else
            {
                throw new Exception($"Failed to authenticate: {response.StatusCode}");
            }
        }
        catch (HttpRequestException ex)
        {
            throw new Exception($"Network error during authentication: {ex.Message}");
        }
    }

    public void Dispose()
    {
        httpClient.Dispose();
    }
}
```

