from flask import Flask, request, redirect, url_for, render_template_string
from flask_login import LoginManager, UserMixin, login_user, logout_user, login_required, current_user
from flask_principal import Principal, Permission, RoleNeed, Identity, identity_changed, identity_loaded
import oauthlib.oauth2

app = Flask(__name__)
app.secret_key = 'your_secret_key'

# Initialize extensions
login_manager = LoginManager()
login_manager.init_app(app)
principals = Principal(app)

# Define custom user model
class User(UserMixin):
    def __init__(self, id, roles=None):
        self.id = id
        self.roles = roles or []

    def has_role(self, role):
        return any(role in r for r in self.roles)

# Load user from session
@login_manager.user_loader
def load_user(user_id):
    return User.get(user_id)

# Define permissions and roles
admin_permission = Permission(RoleNeed('admin'))

# OAuth2 provider setup
oauth_provider = oauthlib.oauth2.WebApplicationClient('your_client_id')

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        # Authenticate user with external provider
        access_token = get_access_token_from_external_provider(request.form['code'])
        user_info = get_user_info(access_token)

        # Create or load user
        user = User.get(user_info['id'], roles=user_info['roles'])
        login_user(user)

        # Handle session hijacking
        identity_changed.send(app, identity=Identity(user.id))

        return redirect(url_for('dashboard'))
    return render_template_string('''
        <form method="post">
            <input type="text" name="code" placeholder="Enter access code">
            <button type="submit">Login</button>
        </form>
    ''')

@app.route('/logout')
@login_required
def logout():
    logout_user()
    identity_changed.send(app, identity=None)
    return redirect(url_for('login'))

@app.route('/dashboard')
@login_required
@admin_permission.require(http_exception=403)
def dashboard():
    return 'Welcome to the admin dashboard!'

if __name__ == '__main__':
    app.run(debug=True)
```

This code provides a basic structure for integrating user authentication and role-based access control using Flask-Login and Flask-Principal. It includes custom user model, permission and role definitions, OAuth2 provider setup, and mechanisms for session hijacking prevention.

