```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <pthread.h>

#define MAX_FILES 1000
#define MAX_THREADS 50
#define MAX_LINE_LENGTH 4096

typedef struct {
    int file_index;
    double sum;
    int count;
} LogData;

void* process_log_file(void* arg) {
    LogData* data = (LogData*)arg;
    FILE* fp;
    char line[MAX_LINE_LENGTH];
    double num1, num2;
    int found_nums;

    fp = fopen(data->file_index, "r");
    if (!fp) {
        perror("Error opening file");
        return NULL;
    }

    while (fgets(line, sizeof(line), fp)) {
        found_nums = 0;
        for (int i = strlen(line); i >= 0; i--) {
            if (isspace(line[i])) {
                line[i] = '\0';
            } else if (isdigit(line[i]) || (i > 0 && line[i - 1] == '.')) {
                found_nums++;
                num2 = num1;
                num1 = atof(&line[i]);
            }
        }

        if (found_nums >= 2) {
            data->sum += num1 + num2;
            data->count++;
        }
    }

    fclose(fp);
    return NULL;
}

int main(int argc, char* argv[]) {
    pthread_t threads[MAX_THREADS];
    LogData data[MAX_FILES];
    int file_count = 0;

    // Parse command-line arguments and initialize log file list
    for (int i = 1; i < argc; i++) {
        if (file_count >= MAX_FILES) {
            fprintf(stderr, "Error: Maximum number of files (%d) exceeded\n", MAX_FILES);
            return 1;
        }
        strcpy(data[file_count].file_index, argv[i]);
        data[file_count].sum = 0;
        data[file_count].count = 0;
        file_count++;
    }

    // Create threads to process log files concurrently
    for (int i = 0; i < file_count; i++) {
        if (pthread_create(&threads[i], NULL, process_log_file, &data[i])) {
            perror("Error creating thread");
            return 1;
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < file_count; i++) {
        pthread_join(threads[i], NULL);
    }

    // Calculate average of last two numerical fields in each line
    double total_sum = 0;
    int total_count = 0;
    for (int i = 0; i < file_count; i++) {
        total_sum += data[i].sum;
        total_count += data[i].count;
    }

    if (total_count > 0) {
        printf("Average of last two numerical fields in each line: %.2f\n", total_sum / total_count);
    } else {
        printf("No valid data found in log files.\n");
    }

    return 0;
}
