import re
import json
import requests

def extract_book_titles(text, min_count=1):
    book_regex = r'\b(fiction|non-fiction|poetry)\b'
    other_book_regex = r'\b[A-Z][a-z]+\b'

    books_found = {}

    for regex in [book_regex, other_book_regex]:
        matches = re.findall(regex, text)
        for match in matches:
            if match.lower() not in books_found:
                books_found[match.lower()] = 0
            books_found[match.lower()] += 1

    books_to_check = {k: v for k, v in books_found.items() if v >= min_count}

    book_details = {}
    api_key = 'YOUR_API_KEY'
    base_url = 'https://api.example.com/books'

    for book in books_to_check:
        url = f'{base_url}?title={book}'
        response = requests.get(url, headers={'Authorization': f'Bearer {api_key}'})

        try:
            data = response.json()
            if data['success']:
                book_details[book] = data['details']
            else:
                print(f'Error retrieving details for book: {book}')
        except json.JSONDecodeError:
            print('Error decoding JSON response')
        except requests.exceptions.RequestException as e:
            print(f'Request error: {e}')

    return books_to_check, book_details
```
Note that you will need to replace `'YOUR_API_KEY'` with a valid API key for the external book database.

