from bs4 import BeautifulSoup
from functools import lru_cache
import threading

class WebContentProcessor:
    def __init__(self):
        self.cache = {}
        self.locks = {}

    @lru_cache(maxsize=100)
    def extract_relevant_data(self, html, tag, attribute, value):
        soup = BeautifulSoup(html, 'html.parser')
        elements = soup.find_all(tag, {attribute: value})
        return [element.text for element in elements]

    def get_cached_data(self, tag, attribute, value):
        key = (tag, attribute, value)
        if key not in self.cache:
            self.cache[key] = []
            self.locks[key] = threading.Lock()

        with self.locks[key]:
            if not self.cache[key]:
                try:
                    html = self.fetch_html_from_source()  # Implement this method to fetch HTML from source
                    data = self.extract_relevant_data(html, tag, attribute, value)
                    self.cache[key] = data
                except Exception as e:
