import java.io.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class SerializationUtils {

    public static String getRandomStringFromDeserializedObject(byte[] byteArray, String charset, String password) {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(byteArray))) {
            Object obj = ois.readObject();
            // Generate a random string of the specified length using the given character set
            StringBuilder sb = new StringBuilder(charset.length());
            for (int i = 0; i < charset.length(); i++) {
                int index = ThreadLocalRandom.current().nextInt(0, charset.length());
                sb.append(charset.charAt(index));
            }
            String randomString = sb.toString();

            // Hash the given password using a default hash function
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] hashedPasswordBytes = md.digest(password.getBytes());
            StringBuilder sbHashedPassword = new StringBuilder();
            for (byte b : hashedPasswordBytes) {
                sbHashedPassword.append(String.format("%02x", b));
            }
            String hashedPassword = sbHashedPassword.toString();

            return "RandomString: " + randomString + ", HashedPassword: " + hashedPassword;
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Deserialization failed or class not found", e);
        }
    }

    public static void main(String[] args) {
        byte[] byteArray = ...; // Replace with the actual byte array
        String charset = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
        String password = "myPassword";

        try {
            String result = getRandomStringFromDeserializedObject(byteArray, charset, password);
            System.out.println(result);
        } catch (RuntimeException e) {
            e.printStackTrace();
        }
    }
}
