                1
            }
        });

        // Measure the resident set size after compilation
        let after_memory_usage = get_resident_set_size();

        // Calculate the performance metrics
        let compilation_time = start_time.elapsed();
        let memory_usage = after_memory_usage - before_memory_usage;

        // Handle any errors during compilation
