```csharp
using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class CustomObject
{
    public int Id { get; set; }
    public string Name { get; set; }
}

public interface ICacheProvider
{
    T Get<T>(string key);
    void Set<T>(string key, T value, TimeSpan expiration);
}

public class SqlProcedureExecutor : IDisposable
{
    private readonly SqlConnection _connection;
    private readonly ICacheProvider _cacheProvider;

    public SqlProcedureExecutor(SqlConnection connection, ICacheProvider cacheProvider)
    {
        _connection = connection ?? throw new ArgumentNullException(nameof(connection));
        _cacheProvider = cacheProvider ?? throw new ArgumentNullException(nameof(cacheProvider));
    }

    public async Task<List<CustomObject>> ExecuteStoredProcedureAsync(string procedureName, List<SqlParameter> parameters)
    {
        var key = $"{procedureName}_{string.Join("_", parameters)}";
        if (_cacheProvider.Get<List<CustomObject>>(key) is List<CustomObject> cachedResult)
        {
            return cachedResult;
        }

        using (var command = new SqlCommand(procedureName, _connection))
        {
            command.CommandType = CommandType.StoredProcedure;

            foreach (var param in parameters)
            {
                command.Parameters.Add(param);
            }

            await _connection.OpenAsync();

            using (var reader = await command.ExecuteReaderAsync())
            {
                var result = new List<CustomObject>();
                while (await reader.ReadAsync())
                {
                    result.Add(new CustomObject
                    {
                        Id = reader.GetInt32(0),
                        Name = reader.GetString(1)
                    });
                }

                _cacheProvider.Set(key, result, TimeSpan.FromMinutes(5)); // Cache for 5 minutes

                return result;
            }
        }
    }

    public void Dispose()
    {
        _connection?.Dispose();
    }
}
