```javascript
const buffer = require('buffer').Buffer;

function copyBytes(dataChunks, offset, length) {
    const newBuffer = Buffer.allocUnsafe(length);
    let bytesRead = 0;

    for (const chunk of dataChunks) {
        if (bytesRead >= length) break;
        const bytesToCopy = Math.min(chunk.length - offset, length - bytesRead);
        newBuffer.copy(chunk, 0, offset, offset + bytesToCopy);
        bytesRead += bytesToCopy;
        offset = 0; // Reset offset for next chunk
    }

    return newBuffer.slice(0, bytesRead); // Trim to actual length copied
}
