<?php
// Define a class to encapsulate database operations
class Database {
    private $pdo;

    public function __construct($dsn, $username, $password) {
        $this->pdo = new PDO($dsn, $username, $password);
        $this->pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
    }

    public function updateClinicStatus($clinicId, $newStatus, $ipAddress) {
        // Start a transaction
        $this->pdo->beginTransaction();

        try {
            // Check if the clinic ID is valid
            $stmt = $this->pdo->prepare("SELECT COUNT(*) FROM clinics WHERE id = ?");
            $stmt->execute([$clinicId]);
            $count = $stmt->fetchColumn();

            if ($count == 0) {
                throw new Exception("Invalid clinic ID.");
            }

            // Update the clinic status
            $stmt = $this->pdo->prepare("UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = NOW() WHERE id = ?");
            $stmt->execute([$newStatus, $ipAddress, $clinicId]);

            // Commit the transaction
            $this->pdo->commit();

            return "Success: 1 clinic updated.";
        } catch (Exception $e) {
            // Rollback in case of error
            $this->pdo->rollBack();
            return "Error: " . $e->getMessage();
        }
    }
}

