```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class CustomObject
{
    public int Id { get; set; }
    public string Name { get; set; }
    // Add other properties as needed
}

public static async Task<List<CustomObject>> ExecuteStoredProcedureAsync(
    SqlConnection connection,
    List<SqlParameter> parameters,
    string procedureName,
    TimeSpan cacheDuration = new TimeSpan(0, 15, 0)
)
{
    if (connection == null || parameters == null || string.IsNullOrEmpty(procedureName))
    {
        throw new ArgumentException("Invalid input parameter.");
    }

    var cacheKey = $"{procedureName}_{string.Join("_", parameters)}";
    if (MemoryCache.Default.Contains(cacheKey))
    {
        return MemoryCache.Default.Get(cacheKey) as List<CustomObject>;
    }

    using (var command = connection.CreateCommand())
    {
        command.CommandText = procedureName;
        command.CommandType = CommandType.StoredProcedure;

        foreach (var parameter in parameters)
        {
            command.Parameters.Add(parameter);
        }

        try
        {
            await command.Connection.OpenAsync();
            using (var reader = await command.ExecuteReaderAsync(CommandBehavior.CloseConnection))
            {
                var result = new List<CustomObject>();
                while (await reader.ReadAsync())
                {
                    result.Add(new CustomObject
                    {
                        Id = reader.GetInt32(reader.GetOrdinal("Id")),
                        Name = reader.GetString(reader.GetOrdinal("Name"))
                        // Map other properties as needed
                    });
                }
                MemoryCache.Default.Add(cacheKey, result, DateTimeOffset.UtcNow + cacheDuration);
                return result;
            }
        }
        catch (SqlException ex)
        {
            // Log error using external logging system
            throw new InvalidOperationException($"Error executing stored procedure: {ex.Message}");
        }
    }
}
```

This code defines a `CustomObject` class with properties that match the columns in the database result set. The `ExecuteStoredProcedureAsync` method is an asynchronous method that takes a `SqlConnection`, list of input parameters, stored procedure name, and optional cache duration as input.

The method first checks if the result is already cached. If it is, it returns the cached result immediately. Otherwise, it creates a new command object, sets its properties, and executes the stored procedure asynchronously using `ExecuteReaderAsync`. The results are then mapped to a list of `CustomObject` instances and added to the cache before being returned.

The method includes error handling for SQL exceptions and logs errors using an external logging system. It also supports parameter validation and prevents SQL injection attacks by creating new `SqlParameter` objects with values from the input parameters.

