```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class FileHasher
{
    private readonly ILogger _logger;

    public FileHasher(ILogger logger)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task<string> ComputeHashAsync(string filePath, int chunkSize = 8192)
    {
        using (var sha256 = SHA256.Create())
        using (var fileStream = File.OpenRead(filePath))
        {
            long fileSize = fileStream.Length;
            long bytesRead = 0;

            while (bytesRead < fileSize)
            {
                int read = await fileStream.ReadAsync(new byte[chunkSize], 0, chunkSize);
                if (read == 0) break; // End of stream
                sha256.TransformBlock(new byte[chunkSize], 0, read, null, 0);
                bytesRead += read;
            }
            sha256.TransformFinalBlock(new byte[0], 0, 0);

            byte[] hashBytes = sha256.Hash;
            string hashString = BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();

            _logger.Log($"Hash computation completed for file {filePath}. Hash: {hashString}");

            return hashString;
        }
    }

    public async Task ComputeHashAndLogAsync(string filePath, int chunkSize = 8192)
    {
        try
        {
            string hash = await ComputeHashAsync(filePath, chunkSize);
            _logger.Log($"Computed hash for file: {hash}");
        }
        catch (Exception ex)
        {
            _logger.LogError($"Error computing hash for file: {ex.Message}");
        }
    }
}

public interface ILogger
{
    void Log(string message);
    void LogError(string error);
}
```

This code snippet defines a `FileHasher` class that computes the SHA-256 hash of a file asynchronously. It handles large files efficiently by reading and hashing in chunks, which minimizes memory usage. The `ILogger` interface is used to record the hash computation time and any errors encountered during the process. The methods include proper exception handling and resource management to ensure no leaks occur.

