#include <mutex>
#include <condition_variable>

namespace fs = std::filesystem;

std::mutex log_mutex;
std::ofstream log_file("log.txt");

void log(const std::string& message) {
    std::lock_guard<std::mutex> lock(log_mutex);
    if (!log_file.is_open()) {
        log_file.open("log.txt", std::ios::app);
    }
    log_file << message << std::endl;
}

std::string readFileSynchronously(const fs::path& directory, const std::string& filename) {
    try {
        fs::path file_path = directory / filename;
        if (!fs::exists(file_path)) {
            throw std::runtime_error("File not found: " + file_path.string());
        }
        std::ifstream file(file_path);
        if (!file.is_open()) {
            throw std::runtime_error("Failed to open file: " + file_path.string());
        }
        std::string content((std::istreambuf_iterator<char>(file)), (std::istreambuf_iterator<char>()));
        file.close();
        return content;
    } catch (const std::exception& e) {
        log("Error reading file: " + std::string(e.what()));
        throw;
    }
}

void insertStringAfterTarget(std::forward_list<std::string>& list, const std::string& target, const std::string& replacement) {
    bool inserted = false;
    for (auto it = list.begin(); it != list.end() && !inserted; ++it) {
        if (*it == target) {
            list.insert_after(it, replacement);
            inserted = true;
            log("Inserted \"" + replacement + "\" after \"" + target + "\"");
        }
    }
    if (!inserted) {
        list.push_back(replacement);
        log("Appended \"" + replacement + "\" to the end of the list");
    }
}

int main() {
    std::forward_list<std::string> list = {"apple", "banana", "cherry"};
    std::string target = "banana";
    std::string replacement = "grape";
    fs::path directory = "/path/to/directory";

    try {
        insertStringAfterTarget(list, target, replacement);
        std::cout << "Updated list: ";
        for (const auto& item : list) {
            std::cout << item << " ";
        }
        std::cout << std::endl;

        std::string fileContent = readFileSynchronously(directory, "example.txt");
        std::cout << "File content: " << fileContent << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
```

