```javascript
function copyBufferChunks(chunks, offset, byteCount) {
  if (!Array.isArray(chunks)) {
    throw new Error('Invalid input: chunks must be an array');
  }

  if (typeof offset !== 'number' || typeof byteCount !== 'number') {
    throw new Error('Invalid input: offset and byteCount must be numbers');
  }

  let totalBytes = 0;
  for (const chunk of chunks) {
    totalBytes += chunk.length;
  }

  if (offset + byteCount > totalBytes) {
    throw new Error('Requested byte count exceeds available data');
  }

  const resultBuffer = Buffer.alloc(byteCount);
  let resultIndex = 0;

  for (let i = 0; i < chunks.length && resultIndex < byteCount; i++) {
    const chunk = chunks[i];
    if (offset >= chunk.length) {
      offset -= chunk.length;
    } else {
      const bytesToCopy = Math.min(chunk.length - offset, byteCount - resultIndex);
      chunk.copy(resultBuffer, resultIndex, offset, offset + bytesToCopy);
      resultIndex += bytesToCopy;
      offset = 0;
    }
  }

  return resultBuffer;
}
