#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* renameFileWithDigits(const char* filename, const char* fileType) {
    if (filename == NULL || fileType == NULL) return NULL;

    int len = strlen(filename);
    char* newFilename = malloc(len + 6); // Extra space for new digits and null terminator
    if (newFilename == NULL) return NULL; // Handle memory allocation failure

    const char* extensionStart = strrchr(filename, '.');
    if (extensionStart == NULL || extensionStart - filename >= len - 1) {
        // No extension or it's the last character, append new file type
        snprintf(newFilename, len + 6, "%s.%s", filename, fileType);
    } else {
        char* namePart = strdup(filename);
        if (namePart == NULL) {
            free(newFilename);
            return NULL; // Handle memory allocation failure
        }

        int num;
        sscanf(extensionStart + 1, "%d", &num); // Read the number part
        snprintf(namePart, len - (extensionStart - filename) + 1, "%s%d.%s", namePart, num + 1, fileType);
        newFilename = strdup(namePart);
        free(namePart);

        if (newFilename == NULL) {
            return NULL; // Handle memory allocation failure
        }
    }

    if (strlen(newFilename) > 255) {
        free(newFilename);
        return NULL; // Exceeds maximum length
    }

    return newFilename;
}
