import asyncio
import json
from abc import ABC, abstractmethod

class JsonParser(ABC):
    factories = {}

    @abstractmethod
    def to_json(self) -> str:
        pass

    @classmethod
    def from_json(cls, json_str: str):
        data = json.loads(json_str)
        subclass = cls.factories.get(data['type'])
        if subclass:
            return subclass.from_dict(data)
        raise ValueError("Unknown type in JSON")

    @abstractmethod
    def to_dict(self) -> dict:
        pass

class MyClass(JsonParser):
    def __init__(self, value: int):
        self.value = value

    def to_json(self) -> str:
        return json.dumps({"type": "MyClass", "value": self.value})

    @classmethod
    def from_dict(cls, data: dict):
        return cls(data['value'])

def add_factory(id: str, factory):
    JsonParser.factories[id] = factory

async def load_and_execute_json_files(file_paths):
    tasks = [load_file_async(file_path) for file_path in file_paths]
    results = await asyncio.gather(*tasks)
    for result in results:
        if isinstance(result, Exception):
            print(f"Error loading or executing JSON: {result}")
        else:
            result.execute()

async def load_file_async(file_path):
    try:
        with open(file_path, 'r') as file:
            json_str = await asyncio.to_thread(file.read)
            obj = JsonParser.from_json(json_str)
            return obj
    except Exception as e:
        return e

def execute(obj):
    print(f"Executing: {obj}")

# Example usage
add_factory("MyClass", MyClass)
file_paths = ["path/to/file1.json", "path/to/file2.json"]
asyncio.run(load_and_execute_json_files(file_paths))
