using Microsoft.AspNetCore.Identity;
using Microsoft.Extensions.Options;

public class AccountSettings : IOptions<AccountSettings>
{
    public string UsernameMinLength { get; set; }
    public string PasswordMinLength { get; set; }
    public int LockoutEnabledByDefault { get; set; }
}

public class IdentityConfiguration
{
    private readonly UserManager<IdentityUser> _userManager;
    private readonly AccountSettings _accountSettings;

    public IdentityConfiguration(UserManager<IdentityUser> userManager, IOptions<AccountSettings> accountSettings)
    {
        _userManager = userManager;
        _accountSettings = accountSettings.Value;
    }

    public void ConfigureIdentity()
    {
        var builder = new IdentityBuilder(typeof(IdentityUser), typeof(IdentityRole), _userManager);
        builder.AddEntityFrameworkStores<ApplicationDbContext>();
        builder.AddDefaultTokenProviders();

        builder.Configure<IdentityOptions>(options =>
        {
            options.User.RequireUniqueEmail = true;
            options.Password.RequireDigit = false;
            options.Password.RequireLowercase = false;
            options.Password.RequireNonAlphanumeric = false;
            options.Password.RequireUppercase = false;
            options.Password.RequiredLength = _accountSettings.PasswordMinLength;
            options.Lockout.AllowedForNewUsers = true;
            options.Lockout.DefaultBannedDuration = TimeSpan.FromMinutes(_accountSettings.LockoutEnabledByDefault);
        });
    }
}
