```java
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class DynamicResourcePoolManager {
    private static final ConcurrentHashMap<String, DynamicResourcePool> pools = new ConcurrentHashMap<>();
    private static final AtomicInteger seedCounter = new AtomicInteger(0);

    public enum ConnectionConfigCallback {
        MODIFY(ConnectionConfig config) { return config; }
    }

    public static void initializeResourcePool(String poolName, int minConnections, int maxConnections, int connectionTimeout, boolean seeded, Integer seed, ConnectionConfigCallback callback) {
        if (minConnections <= 0 || maxConnections <= 0 || connectionTimeout < 0) {
            throw new IllegalArgumentException("Invalid configuration parameters.");
        }

        DynamicResourcePool existingPool = pools.get(poolName);
        if (existingPool != null && !existingPool.isSeeded()) {
            synchronized (pools) {
                if (pools.get(poolName).isSeeded()) {
                    return;
                }
                existingPool.updateConfig(minConnections, maxConnections, connectionTimeout);
            }
        } else {
            ConnectionConfig config = new ConnectionConfig();
            if (seeded) {
                config.setSeed(seed == null ? seedCounter.incrementAndGet() : seed);
            }
            if (callback != null) {
                config = callback.MODIFY(config);
            }

            DynamicResourcePool newPool = new DynamicResourcePool(poolName, minConnections, maxConnections, connectionTimeout, config);
            pools.putIfAbsent(poolName, newPool);
        }
    }

    public static Connection getConnection(String poolName) {
        DynamicResourcePool pool = pools.get(poolName);
        if (pool == null) {
            throw new IllegalArgumentException("No such resource pool: " + poolName);
        }
        return pool.getConnection();
    }

