function renderScripts(scripts) {
  const defaultScriptType = 'text/javascript';
  const cacheKeyPrefix = 'script_cache_';

  // Function to fetch scripts from an external API
  async function fetchScripts(url, options = {}) {
    try {
      const response = await fetch(url, options);
      if (!response.ok) throw new Error(`Failed to fetch scripts: ${response.statusText}`);
      return response.json();
    } catch (error) {
      console.error('Error fetching scripts:', error);
      throw error;
    }
  }

  // Function to render a single script object as an HTML element
  function renderScript(scriptObject, key) {
    const { code = '', type = defaultScriptType } = scriptObject;
    return `<script key="${key}" type="${type}">${code}</script>`;
  }

  // Function to render multiple scripts and return the HTML string
  function renderMultipleScripts(scripts, cacheKey) {
    const renderedScripts = scripts.map((script, index) => renderScript(script, `${cacheKey}-${index}`)).join('');
    return `<footer>${renderedScripts}</footer>`;
  }

  // Fetch and render scripts with caching and error handling
  async function fetchAndRenderScripts(apiUrl, options = {}, cacheExpiry = 3600 * 24) {
    const now = Date.now();
    const cachedData = localStorage.getItem(cacheKeyPrefix + apiUrl);
    let data;

    if (cachedData && JSON.parse(cachedData).expires > now) {
      data = JSON.parse(cachedData).data;
    } else {
      try {
        data = await fetchScripts(apiUrl, options);
        localStorage.setItem(cacheKeyPrefix + apiUrl, JSON.stringify({ data, expires: now + cacheExpiry * 1000 }));
      } catch (error) {
        console.error('Error fetching scripts:', error);
        throw error;
      }
    }

    const htmlString = renderMultipleScripts(data.scripts || [], 'external-scripts');
    document.body.innerHTML += htmlString;

    data.scripts.forEach((script, index) => {
      const scriptElement = document.querySelector(`[key="${cacheKeyPrefix + apiUrl}-${index}"]`);
      if (scriptElement) {
        scriptElement.onload = () => {
          console.log(`Script ${index} loaded successfully.`);
          // Trigger callback function here
        };
        scriptElement.onerror = () => {
          console.error(`Error loading script ${index}:`, error);
          // Handle script load error here
        };
      }
    });
  }

  return fetchAndRenderScripts;
}

// Example usage:
const render = renderScripts();
render('https://api.example.com/scripts', { method: 'GET' }, 3600 * 24);
