use std::collections::HashMap;
use std::error::Error;
use std::net::SocketAddr;
use std::sync::{Arc, Mutex};
use tokio::net::TcpListener;
use tokio::signal;
use tokio::task;

mod config;
mod api;
mod logging;
mod health_check;

#[derive(Debug)]
enum Function {
    Function1,
    Function2,
}

impl Function {
    fn execute(&self) -> Result<(), Box<dyn Error>> {
        match self {
            Function::Function1 => todo!(),
            Function::Function2 => todo!(),
        }
    }
}

struct Config {
    functions: HashMap<String, Function>,
    api_key: String,
    log_level: logging::Level,
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn Error>> {
    let config_path = std::env::args().nth(1).expect("Usage: program <config.json>");
    let config = config::load_config(&config_path).await?;

    let logger = logging::Logger::new(config.log_level);

    let api_client = api::ApiClient::new(&config.api_key);

    for (name, function) in &config.functions {
        tokio::spawn(async move {
            if let Err(e) = function.execute() {
                logger.error(format!("Failed to execute function '{}': {}", name, e));
            }
        });
    }

    // Start health check server
    let addr = SocketAddr::from(([127, 0, 0, 1], 8080));
    let listener = TcpListener::bind(&addr).await?;
    logger.info(format!("Health check server listening on {}", addr));

    loop {
        match listener.accept().await {
            Ok((stream, _)) => {
                task::spawn(async move {
                    if let Err(e) = health_check::handle_request(api_client.clone()).await {
                        logger.error(format!("Failed to handle health check request: {}", e));
                    }
                });
            }
            Err(e) => {
                logger.error(format!("Error accepting connection: {}", e));
            }
        }

        // Check for termination signals
        if signal::ctrl_c().await.is_ok() {
            logger.info("Received termination signal, shutting down...");
            break;
        }
    }

    Ok(())
}
