import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.util.Iterator;
import java.util.Set;

public class NetworkedCharacter {
    private Selector selector;
    private SocketChannel channel;
    private ByteBuffer buffer;
    private int attackCooldown;
    private boolean isDoSAttackDetected;

    public NetworkedCharacter(String serverAddress, int port) throws IOException {
        selector = Selector.open();
        channel = SocketChannel.open(new InetSocketAddress(serverAddress, port));
        channel.configureBlocking(false);
        channel.register(selector, SelectionKey.OP_CONNECT | SelectionKey.OP_READ);
        buffer = ByteBuffer.allocate(1024);
    }

    public void start() throws IOException {
        while (true) {
            selector.select();
            Set<SelectionKey> selectedKeys = selector.selectedKeys();
            Iterator<SelectionKey> keyIterator = selectedKeys.iterator();

            while (keyIterator.hasNext()) {
                SelectionKey key = keyIterator.next();

                if (key.isConnectable()) {
                    connect(key);
                } else if (key.isReadable()) {
                    read(key);
                }

                keyIterator.remove();
            }
        }
    }

    private void connect(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();
        if (channel.finishConnect()) {
            System.out.println("Connected to server");
            // Handle initial connection logic
        } else {
            // Handle connection failure
        }
    }

    private void read(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();
        buffer.clear();
        int bytesRead = channel.read(buffer);

        if (bytesRead == -1) {
            channel.close();
        } else if (bytesRead > 0) {
            buffer.flip();
            byte[] data = new byte[buffer.remaining()];
            buffer.get(data);
            String response = new String(data);

            // Handle server response
            if ("DOS".equals(response)) {
                isDoSAttackDetected = true;
            } else {
                selectAttack(response);
            }
        }
    }

    private void selectAttack(String serverResponse) {
        // Implement dynamic cooldown period based on server load, latency, and resources
        if (attackCooldown > 0) {
            System.out.println("Attack cooldown: " + attackCooldown + " ms");
            return;
        }

        int[] attackOptions = {10, 20, 30}; // Attack power levels
        int[] resourceCosts = {5, 10, 15}; // Resource costs for each attack

        int selectedAttackIndex = -1;
        int minResourceCost = Integer.MAX_VALUE;

        for (int i = 0; i < resourceCosts.length; i++) {
            if (resourceCosts[i] <= getRemainingResources() && resourceCosts[i] < minResourceCost) {
                selectedAttackIndex = i;
                minResourceCost = resourceCosts[i];
            }
        }

        if (selectedAttackIndex != -1) {
            int attackPower = attackOptions[selectedAttackIndex];
            System.out.println("Selected attack: Power " + attackPower);
            // Implement logic to perform the attack
            updateCooldown();
        } else {
            System.out.println("No attacks available");
        }
    }

    private int getRemainingResources() {
        // Return the character's remaining resources
        return 100; // Placeholder value
    }

