#include <stdio.h>
#include <string.h>
#include <arpa/inet.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <netdb.h>
#include <unistd.h>

#define MAX_IP_LEN 16

typedef enum {
    SUCCESS = 0,
    INVALID_INPUT = -1,
    TIMEOUT_ERROR = -2,
    DNS_QUERY_FAILED = -3,
    INSUFFICIENT_BUFFER = -4
} ErrorCode;

int resolveHostWithTimeout(const char *hostname, u_char *ipAddress, size_t ipAddressLength, const char *dnsServers[], int timeout) {
    if (hostname == NULL || ipAddress == NULL || dnsServers == NULL || timeout < 0) {
        return INVALID_INPUT;
    }

    struct addrinfo hints = { .ai_family = AF_INET };
    struct addrinfo *res, *p;
    int sockfd;

    for (int i = 0; dnsServers[i] != NULL; i++) {
        if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
            perror("socket creation failed");
            return DNS_QUERY_FAILED;
        }

        struct sockaddr_in server_addr;
        memset(&server_addr, 0, sizeof(server_addr));
        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(53); // DNS port

        if (inet_pton(AF_INET, dnsServers[i], &server_addr.sin_addr) <= 0) {
            close(sockfd);
            continue; // Try next DNS server
        }

        struct timeval tv;
        tv.tv_sec = timeout / 1000;
        tv.tv_usec = (timeout % 1000) * 1000;

        if ((setsockopt(sockfd, SOL_SOCKET, SO_RCVTIMEO, (const char *)&tv, sizeof(tv))) < 0) {
            perror("setsockopt failed");
            close(sockfd);
            return DNS_QUERY_FAILED;
        }

        if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
            fprintf(stderr, "Error in getaddrinfo for hostname %s\n", hostname);
            close(sockfd);
            continue; // Try next DNS server
        }

        for (p = res; p != NULL; p = p->ai_next) {
            if (connect(sockfd, p->ai_addr, p->ai_addrlen) == 0) {
                break;
            }
        }

        freeaddrinfo(res);

        if (p == NULL) {
            close(sockfd);
            continue; // Try next DNS server
        }

        struct sockaddr_in *ip = (struct sockaddr_in *)p->ai_addr;
        if (ipAddressLength < INET_ADDRSTRLEN) {
            return INSUFFICIENT_BUFFER;
        }
        snprintf((char *)ipAddress, ipAddressLength, "%s", inet_ntoa(ip->sin_addr));

        close(sockfd);
        return SUCCESS;
    }

    fprintf(stderr, "Failed to resolve hostname %s\n", hostname);
    return DNS_QUERY_FAILED;
}

int main() {
    u_char ipAddress[MAX_IP_LEN];
    const char *dnsServers[] = {"8.8.8.8", "8.8.4.4"};
    int result = resolveHostWithTimeout("www.example.com", ipAddress, sizeof(ipAddress), dnsServers, 500);

    if (result == SUCCESS) {
        printf("Resolved IP: %s\n", inet_ntoa(*(struct in_addr *)ipAddress));
    } else {
        printf("Failed to resolve hostname with error code: %d\n", result);
    }

    return 0;
}
