    RX_UE_INFORMATION_TAG rxueinfo;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcindicationrel8;
} NFAPI_CRC_INDICATION_PDU_T;

int generateNFAPduList(int num_pdus, NFAPI_CRC_INDICATION_PDU_T **pdu_list, uint32_t *checksum) {
    if (num_pdus <= 0 || pdu_list == NULL || checksum == NULL) {
        return -1; // Invalid input
    }

    *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdu_list == NULL) {
        return -2; // Memory allocation failed
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    uint32_t total_crcflag = 0;

    for (int i = 0; i < num_pdus; ++i) {
