        (*pdu_list)[i].crcindicationrel8.crcflag = (uint8_t)rand_r(&CHECKSUM_SEED); // Random CRCFLAG

        total_crcflag += (*pdu_list)[i].crcindicationrel8.crcflag;
    }

    pthread_mutex_unlock(&mutex);

