public class DomTraversal
{
    public static Element[] FindElementsBySelector(Node node, string selector, Func<Element, bool> testFunction)
    {
        List<Element> elements = new List<Element>();
        TraverseDom(node, selector, testFunction, elements);
        return elements.ToArray();
    }

    private static void TraverseDom(Node node, string selector, Func<Element, bool> testFunction, List<Element> result)
    {
        if (node == null) return;

        if (testFunction((Element)node))
        {
            result.Add((Element)node);
        }

        foreach (Node child in node.childNodes)
        {
            TraverseDom(child, selector, testFunction, result);
        }
    }
}
