    traverseDom(node, selector, testFunction, elements);
    return elements;
}

function traverseDom(node, selector, testFunction, result) {
    if (!node) return;

    if (testFunction(node)) {
        result.push(node);
    }

    for (let i = 0; i < node.childNodes.length; i++) {
        traverseDom(node.childNodes[i], selector, testFunction, result);
    }
}
