```csharp
using System;
using System.IO;
using System.Xml.XPath;
using System.Xml.Schema;
using log4net;

public class XmlParser
{
    private static readonly ILog _log = LogManager.GetLogger(typeof(XmlParser));

    private readonly XPathNavigator _navigator;
    private readonly XmlSchemaSet _schemaSet;
    private readonly MemoryCache _cache;

    public XmlParser(string xmlContent, string xsdPath)
    {
        _navigator = new XPathDocument(new StringReader(xmlContent)).CreateNavigator();
        _schemaSet = new XmlSchemaSet();
        _schemaSet.Add(null, xsdPath);

        // Validate XML document against schema
        if (!_navigator.SchemaInfo.IsValid(_schemaSet))
            throw new InvalidOperationException("XML does not conform to the provided schema.");

        // Initialize caching mechanism
        _cache = MemoryCache.Default;
    }

    public string GetSingleElement(string xpath)
    {
        try
        {
            var nodes = _navigator.Select(xpath);

            if (!nodes.MoveNext())
                throw new InvalidOperationException($"No elements found with XPath '{xpath}'.");

            if (nodes.MoveNext())
                throw new InvalidOperationException($"Multiple elements found with XPath '{xpath}'.");

            return nodes.Current.Value;
        }
        catch (XPathException ex)
        {
            LogError(ex, xpath);
            throw;
        }
    }

    private void LogError(Exception ex, string xpath)
    {
        _log.Error($"XPath error: {ex.Message}. Incorrect query might be: '{xpath}'.");
    }
}
