use std::env;
use std::fs::{self, DirBuilder};
use std::path::{Path, PathBuf};
use std::thread;
use std::time::{Duration, Instant};
use log::{info, error};

fn main() {
    // Set up logging configuration
    env_logger::init();

    match setup_my_dir_env_var() {
        Ok(_) => info!("Environment variable set successfully."),
        Err(e) => error!("Failed to set environment variable: {}", e),
    }

    // Keep the program running to simulate ongoing operations
    thread::sleep(Duration::from_secs(600));
}

fn setup_my_dir_env_var() -> Result<(), Box<dyn std::error::Error>> {
    const DEFAULT_DIR_PATH: &str = "/tmp/my_dir";
    const ENV_VAR_NAME: &str = "MY_DIR_PATH";

    // Check if the environment variable is already set
    if let Some(path_str) = env::var(ENV_VAR_NAME).ok() {
        let path = Path::new(&path_str);
        if path.exists() && path.is_dir() {
            info!("Using existing directory: {}", path_str);
            return Ok(());
        } else {
            error!("Environment variable {} points to a non-existent or non-directory path.", ENV_VAR_NAME);
        }
    }

    // Create the new directory
    let mut dir_builder = DirBuilder::new();
    dir_builder.recursive(true); // Ensure parent directories are created if they don't exist

    let dir_path = PathBuf::from(DEFAULT_DIR_PATH);

    if dir_path.exists() {
        info!("Directory already exists: {}", DEFAULT_DIR_PATH);
    } else {
        match dir_builder.create(&dir_path) {
            Ok(_) => info!("Created directory at: {}", DEFAULT_DIR_PATH),
            Err(e) => return Err(format!("Failed to create directory: {}", e).into()),
        }
    }

    // Set the environment variable
    env::set_var(ENV_VAR_NAME, dir_path.display());
    info!("Set {} to: {}", ENV_VAR_NAME, dir_path.display());

    // Start a background thread to clean up the directory after 10 minutes
    let cleanup_thread = thread::spawn(move || {
        let start_time = Instant::now();
        loop {
            if start_time.elapsed() >= Duration::from_secs(600) {
                match fs::remove_dir_all(&dir_path) {
                    Ok(_) => info!("Cleaned up directory: {}", dir_path.display()),
                    Err(e) => error!("Failed to clean up directory: {}", e),
                }
                break;
            } else {
                thread::sleep(Duration::from_secs(10));
            }
        }
    });

    cleanup_thread.join().expect("Cleanup thread panicked");

    Ok(())
}
