<?php

class SecureTokenGenerator {
    private $charset;
    private $saltLength;
    private $hashAlgorithm;
    private $noSQLClient;

    public function __construct($charset, $saltLength = 16, $hashAlgorithm = 'bcrypt', $noSQLClient) {
        $this->charset = $charset;
        $this->saltLength = $saltLength;
        $this->hashAlgorithm = $hashAlgorithm;
        $this->noSQLClient = $noSQLClient;
    }

    public function generateToken($length) {
        if ($length < 1) {
            throw new InvalidArgumentException('Token length must be greater than 0.');
        }
        $token = '';
        $maxIndex = strlen($this->charset) - 1;
        for ($i = 0; $i < $length; $i++) {
            $token .= $this->charset[random_int(0, $maxIndex)];
        }
        return $token;
    }

    public function hashPassword($password) {
        $salt = random_bytes($this->saltLength);
        switch ($this->hashAlgorithm) {
            case 'bcrypt':
                $hashedPassword = password_hash($password . $salt, PASSWORD_BCRYPT);
                break;
            case 'argon2id':
                $hashedPassword = password_hash($password . $salt, PASSWORD_ARGON2ID);
                break;
            default:
                throw new InvalidArgumentException('Unsupported hash algorithm.');
        }
        return [
            'hash' => $hashedPassword,
            'salt' => bin2hex($salt)
        ];
    }

    public function storeToken($key, $token) {
        $this->noSQLClient->set($key, $token);
    }

    public function retrieveToken($key) {
        return $this->noSQLClient->get($key);
    }

    public function storeHashedPassword($userId, $hashedPassword, $salt) {
        $this->noSQLClient->set("user:$userId:password", $hashedPassword);
        $this->noSQLClient->set("user:$userId:salt", $salt);
    }

    public function retrieveHashedPassword($userId) {
        return [
            'hash' => $this->noSQLClient->get("user:$userId:password"),
            'salt' => hex2bin($this->noSQLClient->get("user:$userId:salt"))
        ];
    }
}

