using UnityEngine;

public class ValueGenerator : MonoBehaviour
{
    private int _min;
    private int _max;
    private bool _inclusive;

    public ValueGenerator(int min, int max, bool inclusive = false)
    {
        if (min > max)
            throw new ArgumentException("Minimum value must be less than or equal to maximum value.");

        _min = min;
        _max = max;
        _inclusive = inclusive;
    }

    public float GenerateRandomFloat()
    {
        return UnityEngine.Random.value * (_inclusive ? (_max - _min + 1) : (_max - _min)) + _min;
    }

    public int GenerateRandomInt()
    {
        if (_inclusive)
            return UnityEngine.Random.Range(_min, _max + 1);
        else
            return UnityEngine.Random.Range(_min, _max);
    }

    public float[] GenerateFloatArray(int size)
    {
        if (size <= 0) throw new ArgumentException("Array size must be greater than zero.");

        float[] array = new float[size];
        for (int i = 0; i < size; i++)
        {
            array[i] = GenerateRandomFloat();
        }
        return array;
    }

    public int[] GenerateIntArray(int size)
    {
        if (size <= 0) throw new ArgumentException("Array size must be greater than zero.");

        int[] array = new int[size];
        for (int i = 0; i < size; i++)
        {
            array[i] = GenerateRandomInt();
        }
        return array;
    }

    public override string ToString()
    {
        return $"Range: {_min} to {_max}, Inclusive: {_inclusive}";
    }
}
