```c
#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>
#include <pthread.h>

#define MAX_THREADS 10

// Function to find and print the largest integer in an array
void* find_largest_integer(void* arg) {
    int* numbers = (int*)arg;
    int max_num = numbers[0];

    for (int i = 1; i < sizeof(numbers) / sizeof(int); i++) {
        if (numbers[i] > max_num) {
            max_num = numbers[i];
        }
    }

    printf("Largest number: %d\n", max_num);
    pthread_exit(NULL);
}

int main() {
    int numbers[MAX_THREADS * 10]; // Adjust size as needed
    sem_t semaphore;
    pthread_t threads[MAX_THREADS];

    // Initialize the semaphore
    if (sem_init(&semaphore, 0, 1) != 0) {
        perror("Failed to initialize semaphore");
        exit(EXIT_FAILURE);
    }

    // Read numbers from standard input and store in the array
    int count = 0;
    while (scanf("%d", &numbers[count]) == 1 && count < sizeof(numbers) / sizeof(int)) {
        count++;
    }

    if (count == 0) {
        printf("No numbers read.\n");
        sem_destroy(&semaphore);
        exit(EXIT_FAILURE);
    }

    // Create threads to process the array
    for (int i = 0; i < MAX_THREADS && i * 10 < count; i++) {
        if (pthread_create(&threads[i], NULL, find_largest_integer, &numbers[i * 10]) != 0) {
            perror("Failed to create thread");
            sem_destroy(&semaphore);
            exit(EXIT_FAILURE);
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < MAX_THREADS && i * 10 < count; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Failed to join thread");
            sem_destroy(&semaphore);
            exit(EXIT_FAILURE);
        }
    }

    // Clean up
    sem_destroy(&semaphore);

    return 0;
}
