```javascript
const fs = require('fs');
const path = require('path');

class ModuleManager {
  constructor(configPath) {
    this.configPath = configPath;
    this.modules = {};
    this.moduleQueue = [];
    this.concurrencyLevel = 1;
    this.maxConcurrentLoads = 5; // Example concurrency level
    this.logger = console.log;
  }

  loadModules() {
    const config = JSON.parse(fs.readFileSync(this.configPath, 'utf8'));
    this.moduleQueue = config.modules.slice(); // Clone the array to avoid mutating the original config

    this.loadNextModule();
  }

  async loadNextModule() {
    while (this.moduleQueue.length > 0 && Object.keys(this.modules).length < this.maxConcurrentLoads) {
      const moduleName = this.moduleQueue.shift();
      if (!this.modules[moduleName]) {
        try {
          const modulePath = path.join(__dirname, 'modules', `${moduleName}.js`);
          const module = require(modulePath);
          this.modules[moduleName] = { module, loaded: true };
          this.logger(`Module ${moduleName} loaded successfully.`);
        } catch (error) {
          this.logger(`Failed to load module ${moduleName}:`, error);
        }
      }
    }

    if (this.moduleQueue.length > 0 || Object.keys(this.modules).length < this.maxConcurrentLoads) {
      setTimeout(() => this.loadNextModule(), 100); // Check again after a short delay
    } else {
      this.logger('All modules loaded.');
    }
  }

  setConcurrencyLevel(level) {
    this.concurrencyLevel = level;
    this.maxConcurrentLoads = Math.min(this.concurrencyLevel, 5);
  }
}

// Example usage:
const manager = new ModuleManager('config.json');
manager.setConcurrencyLevel(3); // Set concurrency level to 3
manager.loadModules();
