    public async Task<List<Product>> MergeProductsFromFilesAsync(string[] filePaths, IInventoryAPI api)
    {
        var products = new List<Product>();

        var tasks = filePaths.Select(async path =>
        {
            try
            {
                using (var stream = File.OpenRead(path))
                {
                    var formatter = new BinaryFormatter();
                    while (stream.Position < stream.Length)
                    {
                        var product = (Product)formatter.Deserialize(stream);
                        products.Add(product);
                        await api.IntegrateProductAsync(product); // Integrate with external system
                    }
                }
            }
            catch (Exception ex)
            {
                _logger.LogError($"Failed to load or process file {path}: {ex.Message}");
            }
        });

        await Task.WhenAll(tasks);

        return products;
    }
}

public interface ILogger
{
    void LogError(string message);
}

public interface IInventoryAPI
{
    Task IntegrateProductAsync(Product product);
}
```

