#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_NODE_SIZE 100
#define MAX_SUBNODE_SIZE 5

typedef struct SubNode {
    char* str;
    double value;
    struct SubNode* next;
} SubNode;

typedef struct Node {
    int value;
    SubNode* subList;
} Node;

void initSubNode(SubNode* node, const char* str, double value) {
    node->str = strdup(str);
    node->value = value;
    node->next = NULL;
}

void freeSubNode(SubNode* node) {
    if (node != NULL) {
        free(node->str);
        freeSubNode(node->next);
        free(node);
    }
}

Node* initNode(int value, int subListSize) {
    Node* node = malloc(sizeof(Node));
    if (node == NULL) {
        fprintf(stderr, "Memory allocation failed for Node\n");
        return NULL;
    }
    node->value = value;
    node->subList = NULL;

    if (subListSize > 0) {
        SubNode** subNodes = malloc(subListSize * sizeof(SubNode*));
        if (subNodes == NULL) {
            fprintf(stderr, "Memory allocation failed for SubNode array\n");
            free(node);
            return NULL;
        }

        node->subList = malloc(sizeof(SubNode));
        if (node->subList == NULL) {
            fprintf(stderr, "Memory allocation failed for first SubNode in list\n");
            free(subNodes);
            free(node);
            return NULL;
        }
        subNodes[0] = node->subList;

        srand(time(NULL));
        const char* strValues[] = {"apple", "banana", "cherry", "date"};
        double valueValues[] = {1.1, 2.2, 3.3, 4.4};

        for (int i = 1; i < subListSize; ++i) {
            subNodes[i] = malloc(sizeof(SubNode));
            if (subNodes[i] == NULL) {
                fprintf(stderr, "Memory allocation failed for SubNode at index %d\n", i);
                freeSubNode(node->subList);
                free(subNodes);
                free(node);
                return NULL;
            }
        }

        node->subList = subNodes[0];
        for (int i = 0; i < subListSize; ++i) {
            initSubNode(subNodes[i], strValues[rand() % 4], valueValues[rand() % 4]);
            if (i > 0) {
                subNodes[i - 1]->next = subNodes[i];
            }
        }
    }

    return node;
}

void freeNode(Node* node) {
    if (node != NULL) {
        freeSubNode(node->subList);
        free(node);
    }
}

int main() {
    srand(time(NULL));
    Node** nodes = malloc(MAX_NODE_SIZE * sizeof(Node*));
    if (nodes == NULL) {
        fprintf(stderr, "Memory allocation failed for Node array\n");
        return 1;
    }

    for (int i = 0; i < MAX_NODE_SIZE; ++i) {
        int value = rand() % 100 + 1;
        int subListSize = rand() % MAX_SUBNODE_SIZE + 1;
        nodes[i] = initNode(value, subListSize);
        if (nodes[i] == NULL) {
            fprintf(stderr, "Failed to initialize Node at index %d\n", i);
            for (int j = 0; j < i; ++j) {
                freeNode(nodes[j]);
            }
            free(nodes);
            return 1;
        }
    }

    // Use the nodes...

    for (int i = 0; i < MAX_NODE_SIZE; ++i) {
        freeNode(nodes[i]);
    }
    free(nodes);

    return 0;
}
