            {
                ITest testInstance = Activator.CreateInstance(type) as ITest;
                foreach (MethodInfo method in type.GetMethods(BindingFlags.Instance | BindingFlags.Public | BindingFlags.DeclaredOnly))
                {
                    if (method.IsDefined(typeof(TestAttribute)))
                    {
                        Console.WriteLine($"Starting test {method.Name} from module {moduleName}");
                        try
                        {
                            method.Invoke(testInstance, null);
                        }
                        catch (Exception ex)
                        {
                            Console.WriteLine($"Test {method.Name} failed: {ex.Message}");
                        }
                        finally
                        {
                            Console.WriteLine($"Ending test {method.Name} from module {moduleName}");
                        }
                    }
                }
            }
        }

        string originalFileName = "example.txt";
        string newFileName = ModifyFileName(originalFileName);
        UploadFileToCloud(newFileName, "newfile.txt");
    }

