    {
        IAmazonS3 client = new AmazonS3Client(Amazon.RegionEndpoint.USEast1);
        TransferUtility transferUtility = new TransferUtility(client);

        int retryCount = 0;
        while (retryCount < 5)
        {
            try
            {
                transferUtility.Upload(originalFileName, newFileName);
                break;
            }
            catch (Exception ex)
            {
                retryCount++;
                if (retryCount == 5) throw;
                Console.WriteLine($"Upload attempt {retryCount} failed: {ex.Message}");
            }
        }
    }
