public class WebSiteManager
{
    private static readonly object _lock = new object();

    public async Task<string> AddAndStartSiteAsync(string directoryPath, string siteName)
    {
        lock (_lock)
        {
            if (!Directory.Exists(directoryPath))
            {
                return "Error: Directory does not exist.";
            }

            if (string.IsNullOrEmpty(siteName) || !IsValidSiteName(siteName))
            {
                return "Error: Invalid site name.";
            }

            string configFilePath = Path.Combine(directoryPath, "web.config");
            if (!File.Exists(configFilePath))
            {
                // Retrieve default settings from external configuration management system
                var defaultSettings = await GetDefaultConfigAsync();
                if (defaultSettings == null)
                {
                    return "Error: Failed to retrieve default configuration.";
                }

                File.WriteAllText(configFilePath, defaultSettings);
            }

            try
            {
                Process process = new Process
                {
                    StartInfo =
                    {
                        FileName = "web.config",
                        Arguments = $"-siteName {siteName} -directoryPath {directoryPath}",
                        RedirectStandardOutput = true,
                        UseShellExecute = false,
                        CreateNoWindow = true
                    }
                };

                process.Start();
                string output = await process.StandardOutput.ReadToEndAsync();
                process.WaitForExit();

                if (process.ExitCode != 0)
                {
                    return $"Error: Failed to start site. Exit code: {process.ExitCode}. Output: {output}";
                }

                return "Site added and started successfully.";
            }
            catch (Exception ex)
            {
                return $"Error: An unexpected error occurred. {ex.Message}";
            }
        }
    }

