from typing import Optional
import os
import time
import requests

class DAO:
    def update_profile_picture(self, user_id: int, image_path: str) -> bool:
        pass

class ImageStorageService:
    def upload_image(self, image_data: bytes, file_format: str) -> str:
        pass

def is_valid_image_file(image_path: str) -> bool:
    valid_formats = {'jpeg', 'png'}
    max_size = 5 * 1024 * 1024  # 5MB
    _, file_extension = os.path.splitext(image_path)
    file_format = file_extension.lower().replace('.', '')
    return file_format in valid_formats and os.path.getsize(image_path) <= max_size

def retry_on_failure(func, retries=3):
    def wrapper(*args, **kwargs):
        attempt = 0
        while attempt < retries:
            try:
                return func(*args, **kwargs)
            except Exception as e:
                time.sleep(2 ** attempt)
                attempt += 1
        raise
    return wrapper

def cache_image(image_url: str) -> Optional[str]:
    # Implement caching logic here
    pass

@retry_on_failure
def update_profile_picture(user_id: int, image_path: str, dao: DAO, storage_service: ImageStorageService) -> bool:
    if not is_valid_image_file(image_path):
        raise ValueError("Invalid image file format or size")

    with open(image_path, 'rb') as f:
        image_data = f.read()

    try:
        image_url = storage_service.upload_image(image_data, os.path.splitext(image_path)[1].lower().replace('.', ''))
        if not image_url:
            raise ValueError("Failed to upload image")

        if cache_image(image_url):
            dao.update_profile_picture(user_id, image_url)
            return True
        else:
            raise ValueError("Failed to cache image")
    except Exception as e:
        # Log error here
        print(f"Error updating profile picture: {e}")
        return False

