using System;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class FileTransferService
{
    private readonly HttpClient _httpClient;
    private readonly string _tokenUrl;
    private readonly string _uploadUrl;

    public FileTransferService(string tokenUrl, string uploadUrl)
    {
        _tokenUrl = tokenUrl;
        _uploadUrl = uploadUrl;
        _httpClient = new HttpClient();
    }

    public async Task<UploadResult> UploadFileAsync(string filePath, byte[] encryptionKey, byte[] iv)
    {
        try
        {
            // Authenticate and obtain upload permissions
            var token = await ObtainTokenAsync();

            if (string.IsNullOrEmpty(token))
            {
                return new UploadResult { Success = false, ErrorMessage = "Failed to authenticate" };
            }

            using (var fileStream = File.OpenRead(filePath))
            {
                long fileSize = fileStream.Length;
                long chunkSize = 1024 * 1024; // 1 MB
                int chunks = (int)Math.Ceiling((double)fileSize / chunkSize);

                for (int i = 0; i < chunks; i++)
                {
                    byte[] buffer = new byte[chunkSize];
                    await fileStream.ReadAsync(buffer, 0, buffer.Length);

                    // Encrypt the chunk
                    using (Aes aes = Aes.Create())
                    {
                        aes.Key = encryptionKey;
                        aes.IV = iv;
                        ICryptoTransform encryptor = aes.CreateEncryptor(aes.Key, aes.IV);
                        using (MemoryStream msEncrypt = new MemoryStream())
                        {
                            using (CryptoStream csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
                            {
                                await csEncrypt.WriteAsync(buffer, 0, buffer.Length);
                                byte[] encryptedChunk = msEncrypt.ToArray();

                                // Upload the chunk
                                var uploadResponse = await _httpClient.PutAsync(_uploadUrl + "?token=" + token + "&chunkIndex=" + i, new ByteArrayContent(encryptedChunk));
                                if (!uploadResponse.IsSuccessStatusCode)
                                {
                                    return new UploadResult { Success = false, ErrorMessage = "Upload failed" };
                                }
                            }
                        }
                    }
                }

                return new UploadResult { Success = true };
            }
        }
        catch (Exception ex)
        {
            return new UploadResult { Success = false, ErrorMessage = $"An error occurred: {ex.Message}" };
        }
    }

    private async Task<string> ObtainTokenAsync()
    {
        var tokenRequest = new HttpRequestMessage(HttpMethod.Post, _tokenUrl);
        tokenRequest.Content = new StringContent("", Encoding.UTF8, "application/x-www-form-urlencoded");

        using (var response = await _httpClient.SendAsync(tokenRequest))
        {
            if (response.IsSuccessStatusCode)
            {
                return await response.Content.ReadAsStringAsync();
            }
            else
            {
                return null;
            }
        }
    }
}

public class UploadResult
{
    public bool Success { get; set; }
    public string ErrorMessage { get; set; }
}
