using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Serilog;

public class StringHasher : IDisposable
{
    private readonly ILogService _logService;
    private readonly HashAlgorithm _hashAlgorithm;
    private bool _disposed = false;

    public StringHasher(ILogService logService, HashAlgorithm hashAlgorithm)
    {
        _logService = logService ?? throw new ArgumentNullException(nameof(logService));
        _hashAlgorithm = hashAlgorithm ?? throw new ArgumentNullException(nameof(hashAlgorithm));
    }

    public string HashString(string input, HashType hashType = HashType.MD5)
    {
        if (input == null)
            throw new ArgumentNullException(nameof(input));

        using (var md5 = MD5.Create())
        {
            var bytes = Encoding.UTF8.GetBytes(input);
            var hashBytes = _hashAlgorithm.ComputeHash(bytes);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
    }

    public string[] HashStringsParallel(string[] inputs, HashType hashType = HashType.MD5)
    {
        if (inputs == null || inputs.Length == 0)
            throw new ArgumentException("Input array cannot be null or empty", nameof(inputs));

        return Parallel.ForEachAsync(inputs, async (input, ct) =>
        {
            try
            {
                var result = HashString(input, hashType);
                await _logService.LogAsync($"Hashed {input} to {result}");
                return result;
            }
            catch (Exception ex)
            {
                await _logService.LogErrorAsync($"Error hashing {input}: {ex.Message}");
                throw;
            }
        }).Result.ToArray();
    }

    public bool ValidateHash(string input, string expectedHash, HashType hashType = HashType.MD5)
    {
        var computedHash = HashString(input, hashType);
        return string.Equals(computedHash, expectedHash, StringComparison.OrdinalIgnoreCase);
    }

    public void Dispose()
    {
        _hashAlgorithm?.Dispose();
        _disposed = true;
    }

    public enum HashType
    {
        MD5,
        SHA256
    }
}

public interface ILogService
{
    Task LogAsync(string message);
    Task LogErrorAsync(string error);
}

public class FileLogService : ILogService
{
    private readonly string _logFilePath;

    public FileLogService(string logFilePath)
    {
        _logFilePath = logFilePath;
    }

    public async Task LogAsync(string message)
    {
        await File.AppendAllTextAsync(_logFilePath, $"{DateTime.Now}: {message}\n");
    }

    public async Task LogErrorAsync(string error)
    {
        await File.AppendAllTextAsync(_logFilePath, $"{DateTime.Now}: ERROR - {error}\n");
    }
}

public class SerilogLogService : ILogService
{
    private readonly ILogger _logger;

    public SerilogLogService(ILogger logger)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public Task LogAsync(string message)
    {
        _logger.Information(message);
        return Task.CompletedTask;
    }

    public Task LogErrorAsync(string error)
    {
        _logger.Error(error);
        return Task.CompletedTask;
    }
}

public class StringHasherSettings
{
    public string LogFilePath { get; set; }
    public HashType DefaultHashAlgorithm { get; set; } = HashType.MD5;
}
