```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

enum ResourceType { IMAGE, TEXT, AUDIO, NUM_TYPES };
typedef struct ResourceItem {
    enum ResourceType type;
    void* data;
} ResourceItem;

typedef struct ResourceBundle {
    ResourceItem* items;
    size_t itemCount[NUM_TYPES];
    size_t totalItemCount;
    pthread_mutex_t mutex; // For thread safety
} ResourceBundle;

ResourceBundle* loadResourceBundle(const char* filePath) {
    FILE* file = fopen(filePath, "rb");
    if (!file) {
        perror("Failed to open resource bundle file");
        return NULL;
    }

    // Validate the file header or schema here
    // ...

    pthread_mutex_init(&bundle->mutex, NULL);

    // Allocate memory for the resource bundle structure
    ResourceBundle* bundle = (ResourceBundle*)malloc(sizeof(ResourceBundle));
    if (!bundle) {
        perror("Failed to allocate memory for resource bundle");
        fclose(file);
        return NULL;
    }

    bundle->items = NULL;
    bundle->totalItemCount = 0;

    // Read and parse the resource file
    while (!feof(file)) {
        uint32_t type, size;
        if (fread(&type, sizeof(type), 1, file) != 1 || fread(&size, sizeof(size), 1, file) != 1) {
            perror("Failed to read resource entry");
            break;
        }

        ResourceItem* item = (ResourceItem*)malloc(sizeof(ResourceItem));
        if (!item) {
            perror("Failed to allocate memory for resource item");
            break;
        }

        item->type = type;
        item->data = malloc(size);
        if (!item->data) {
            free(item);
            perror("Failed to allocate memory for resource data");
            break;
        }

        if (fread(item->data, size, 1, file) != 1) {
            free(item->data);
            free(item);
            perror("Failed to read resource data");
            break;
        }

        bundle->items = realloc(bundle->items, (bundle->totalItemCount + 1) * sizeof(ResourceItem));
        if (!bundle->items) {
            free(item->data);
            free(item);
            perror("Failed to reallocate memory for resource items");
            break;
        }
        bundle->items[bundle->totalItemCount++] = *item;

        // Increment the count for this resource type
        pthread_mutex_lock(&bundle->mutex);
        bundle->itemCount[type]++;
        pthread_mutex_unlock(&bundle->mutex);
    }

    fclose(file);

    if (feof(file)) {
        return bundle;
    } else {
        freeResourceBundle(bundle);
        return NULL;
    }
}

void freeResourceBundle(ResourceBundle* bundle) {
    if (!bundle) {
        return;
    }

    for (size_t i = 0; i < bundle->totalItemCount; ++i) {
        free(bundle->items[i].data);
    }

    free(bundle->items);
    pthread_mutex_destroy(&bundle->mutex);
    free(bundle);
}
