import requests
from datetime import datetime, timedelta
from collections import defaultdict
from unittest.mock import MagicMock

# Mock API response
def mock_api_response(city):
    if city == 'New York':
        return {
            'main': {'temp': 280.37, 'humidity': 81},
            'wind': {'speed': 4.6}
        }
    elif city == 'Los Angeles':
        return {
            'main': {'temp': 290.32, 'humidity': 53},
            'wind': {'speed': 3.2}
        }
    else:
        raise ValueError("City not found in mock data")

# Weather API client
class WeatherAPI:
    def __init__(self, api_key):
        self.api_key = api_key
        self.cache = defaultdict(list)
        self.rate_limit_next_call = datetime.now()

    def get_weather(self, city):
        now = datetime.now()
        if city in self.cache and self.cache[city][-1]['time'] > now - timedelta(minutes=5):
            return self.cache[city][-1]

        if now < self.rate_limit_next_call:
            wait_time = (self.rate_limit_next_call - now).total_seconds()
            print(f"Rate limit exceeded. Waiting for {wait_time:.2f} seconds...")
            time.sleep(wait_time)

        try:
            response = requests.get(
                f'http://api.openweathermap.org/data/2.5/weather?q={city}&appid={self.api_key}',
                timeout=10
            )
            response.raise_for_status()
            weather_data = response.json()
            self.cache[city].append({'time': now, 'data': weather_data})
            return {'time': now, 'data': weather_data}
        except requests.RequestException as e:
            print(f"Failed to fetch weather for {city}: {e}")
            return None

# Weather data processor
class WeatherDataProcessor:
    def __init__(self, api_client):
        self.api_client = api_client

    def process_cities(self, cities, period_minutes=60):
        start_time = datetime.now() - timedelta(minutes=period_minutes)
        total_temp = 0
        total_humidity = 0
        total_wind_speed = 0
        count = 0

        for city in cities:
            weather_data = self.api_client.get_weather(city)
            if weather_data and weather_data['time'] > start_time:
                total_temp += weather_data['data']['main']['temp']
                total_humidity += weather_data['data']['main']['humidity']
                total_wind_speed += weather_data['data']['wind']['speed']
                count += 1

        if count == 0:
            return None

        avg_temp = total_temp / count
        avg_humidity = total_humidity / count
        avg_wind_speed = total_wind_speed / count

        return {
            'average_temperature': avg_temp,
            'average_humidity': avg_humidity,
            'average_wind_speed': avg_wind_speed
        }

# Example usage
api_key = 'your_api_key_here'
weather_api_client = WeatherAPI(api_key)
processor = WeatherDataProcessor(weather_api_client)

cities = ['New York', 'Los Angeles']
result = processor.process_cities(cities)
if result:
    print(f"Average temperature: {result['average_temperature']}")
    print(f"Average humidity: {result['average_humidity']}")
    print(f"Average wind speed: {result['average_wind_speed']}")

# Mocking the API response for testing
mock_response = MagicMock()
mock_response.json.return_value = mock_api_response('New York')
requests.get.return_value = mock_response

# Test the processor with mocked data
test_cities = ['New York', 'Los Angeles']
test_result = processor.process_cities(test_cities)
assert test_result['average_temperature'] == 280.37 + 290.32
```

