using System;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Logging;

public class PageService : IPageService
{
    private readonly IDistributedCache _cache;
    private readonly IMessageQueue _messageQueue;
    private readonly ILogger<PageService> _logger;

    public PageService(IDistributedCache cache, IMessageQueue messageQueue, ILogger<PageService> logger)
    {
        _cache = cache;
        _messageQueue = messageQueue;
        _logger = logger;
    }

    public async Task<IActionResult> UpdateElementAsync(string pageSectionId, string elementId, string htmlContent, HttpContext context)
    {
        try
        {
            // Validate input parameters
            if (string.IsNullOrEmpty(pageSectionId) || string.IsNullOrEmpty(elementId) || string.IsNullOrEmpty(htmlContent))
                return BadRequest("Invalid input parameters");

            // Check for well-formed HTML content
            if (!IsValidHtml(htmlContent))
                return StatusCode(StatusCodes.Status400BadRequest, "Invalid HTML content");

            // Update element's HTML content in the distributed cache
            var cacheKey = $"{pageSectionId}:{elementId}";
            await _cache.SetStringAsync(cacheKey, htmlContent);

            // Log successful update
            _logger.LogInformation("Element updated successfully. Cache key: {CacheKey}", cacheKey);

            // Send notification to message queue to trigger page refresh
            await _messageQueue.SendNotificationAsync(cacheKey);

            return Ok("Update successful");
        }
        catch (Exception ex)
        {
            // Log the error and return an appropriate response
            _logger.LogError(ex, "Error updating element: {Message}", ex.Message);
            return StatusCode(StatusCodes.Status500InternalServerError, "Internal server error");
        }
    }

    private bool IsValidHtml(string htmlContent)
    {
        try
        {
            var doc = new HtmlDocument();
            doc.LoadHtml(htmlContent);
            return true;
        }
        catch
        {
            return false;
        }
    }
}

public interface IPageService
{
    Task<IActionResult> UpdateElementAsync(string pageSectionId, string elementId, string htmlContent, HttpContext context);
}
