    public async Task AddAndStartWebsiteAsync(string directoryPath, string siteName, int basePort)
    {
        try
        {
            // Validate directory path and site name
            if (!Directory.Exists(directoryPath) || !IsValidSiteName(siteName))
                throw new ArgumentException("Invalid directory path or site name.");

            // Check for web.config file
            var configFilePath = Path.Combine(directoryPath, "web.config");
            if (!File.Exists(configFilePath))
            {
                // Integrate with external configuration management system to retrieve default settings
                var defaultConfig = await FetchDefaultWebServerSettingsAsync();
                File.WriteAllText(configFilePath, defaultConfig);
            }

            // Allocate a unique port number
            int port = GetUniquePort(basePort);

            // Log start of site addition process
            Console.WriteLine($"Starting website {siteName} on port {port}");

            // Start the website using Process class
            var startInfo = new ProcessStartInfo
            {
                FileName = "http://localhost:" + port,
                RedirectStandardOutput = true,
                UseShellExecute = false,
                CreateNoWindow = true
            };

            using (var process = new Process { StartInfo = startInfo })
            {
                process.Start();

                // Set a timeout for the site to start
                await Task.Delay(10000); // 10 seconds

                if (!process.HasExited)
                {
                    process.Kill();
                    throw new TimeoutException($"Website {siteName} failed to start within the specified time.");
                }

                // Log successful start of website
                Console.WriteLine($"Website {siteName} started successfully on port {port}");
            }
        }
        catch (Exception ex)
        {
            // Log any errors that occur during the process
            Console.WriteLine($"Error adding or starting website: {ex.Message}");

            // Clean up resources if an error occurs
            CleanupResources();
        }
    }

    private bool IsValidSiteName(string siteName)
    {
        // Regex to check for valid site name (no special characters)
