import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class DynamicResourcePoolManager {

    private final ConcurrentHashMap<String, ResourcePool> poolMap = new ConcurrentHashMap<>();
    private final ExecutorService executorService;

    public DynamicResourcePoolManager(int numThreads) {
        this.executorService = Executors.newFixedThreadPool(numThreads);
    }

    public void initializeResourcePool(String poolName, int minConnections, int maxConnections, long timeout) throws IllegalArgumentException {
        if (minConnections < 1 || maxConnections < minConnections || timeout <= 0) {
            throw new IllegalArgumentException("Invalid configuration parameters.");
        }
        ResourcePool pool = new ResourcePool(minConnections, maxConnections, timeout);
        poolMap.put(poolName, pool);
    }

    public void initializeResourcePoolWithSeed(String poolName, int minConnections, int maxConnections, long timeout, String seed) throws IllegalArgumentException {
        if (minConnections < 1 || maxConnections < minConnections || timeout <= 0) {
            throw new IllegalArgumentException("Invalid configuration parameters.");
        }
        ResourcePool pool = new ResourcePool(minConnections, maxConnections, timeout);
        pool.setSeed(seed);
        poolMap.put(poolName, pool);
    }

    public void setConnectionConfigCallback(String poolName, ConnectionConfigCallback callback) {
        ResourcePool pool = poolMap.get(poolName);
        if (pool != null) {
            pool.setConnectionConfigCallback(callback);
        }
    }

    public interface ConnectionConfigCallback {
        ConnectionConfig customize(ConnectionConfig config);
    }

    private static class ResourcePool {
        private int minConnections;
        private int maxConnections;
        private long timeout;
        private String seed;
        private ConnectionConfigCallback callback;

