class DecryptionService {
    private EncryptionService encryptionService;
    private Dictionary<string, string> keyCache = new Dictionary<string, string>();
    private Dictionary<string, string> ivCache = new Dictionary<string, string>();

    public DecryptionService(EncryptionService encryptionService) {
        this.encryptionService = encryptionService;
    }

    public async Task<byte[]> DecryptAsync(string ciphertext, string urlKey, string urlIV) {
        if (!keyCache.ContainsKey(urlKey)) {
            keyCache[urlKey] = await encryptionService.GetEncryptionKeyAsync(urlKey, "your_api_key_here");
        }

        if (!ivCache.ContainsKey(urlIV)) {
            ivCache[urlIV] = await encryptionService.GetIVAsync(urlIV, "your_api_key_here");
        }

        using (Aes aesAlg = Aes.Create()) {
            aesAlg.Key = Convert.FromBase64String(keyCache[urlKey]);
            aesAlg.IV = Convert.FromBase64String(ivCache[urlIV]);

            ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

            using (MemoryStream msDecrypt = new MemoryStream(Convert.FromBase64String(ciphertext))) {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read)) {
                    using (var resultMS = new MemoryStream()) {
                        await csDecrypt.CopyToAsync(resultMS);
                        return resultMS.ToArray();
                    }
                }
            }
        }
    }
}

