function renderFooter(scripts) {
    const renderedScripts = scripts.map(script => {
        if (!script.code || !script.type) return null;

        const scriptTag = document.createElement('script');
        scriptTag.innerHTML = script.code;
        scriptTag.async = true;
        scriptTag.key = `script-${Math.random().toString(36).substr(2, 9)}`;

        // Handle external API scripts
        if (script.src) {
            scriptTag.src = script.src;
        }

        return scriptTag.outerHTML;
    }).filter(Boolean).join('');

    const footerContainer = document.createElement('footer');
    footerContainer.innerHTML = renderedScripts;

    return footerContainer.outerHTML;
}
