```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <pthread.h>

#define MAX_URLS 1000
#define DEFAULT_THREADS 4

typedef struct {
    char *urls[MAX_URLS];
    int url_count;
    int thread_count;
    FILE *output_file;
    pthread_mutex_t mutex;
} WebScraper;

void* download_content(void* arg) {
    WebScraper *scraper = (WebScraper*)arg;
    CURL *curl;
    CURLcode res;

    for (int i = 0; i < scraper->url_count; i++) {
        curl = curl_easy_init();
        if(curl) {
            curl_easy_setopt(curl, CURLOPT_URL, scraper->urls[i]);
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
            curl_easy_setopt(curl, CURLOPT_WRITEDATA, scraper->output_file);

            res = curl_easy_perform(curl);

            if(res != CURLE_OK) {
                fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            }

            curl_easy_cleanup(curl);
        }
    }

    pthread_exit(NULL);
}

int main(int argc, char *argv[]) {
    WebScraper scraper;
    pthread_t threads[DEFAULT_THREADS];
    int thread_count = DEFAULT_THREADS;

    // Initialize scraper
    scraper.url_count = 0;
    scraper.thread_count = thread_count;
    scraper.output_file = fopen("output.txt", "w");
    if (scraper.output_file == NULL) {
        perror("Failed to open output file");
        return 1;
    }
    pthread_mutex_init(&scraper.mutex, NULL);

    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            thread_count = atoi(argv[i + 1]);
            i++;
        }
        else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            scraper.output_file = fopen(argv[i + 1], "w");
            if (scraper.output_file == NULL) {
                perror("Failed to open output file");
                return 1;
            }
            i++;
        }
    }

    // Populate URL list
    for (int i = 0; i < MAX_URLS; i++) {
        scraper.urls[i] = malloc(256 * sizeof(char));
        if (i % 2 == 0) {
            snprintf(scraper.urls[i], 256, "http://example.com/page%d", i);
        }
        else {
            snprintf(scraper.urls[i], 256, "http://example.org/resource%d", i);
        }
        scraper.url_count++;
    }

    // Create threads
    for (int i = 0; i < thread_count; i++) {
        if (pthread_create(&threads[i], NULL, download_content, &scraper) != 0) {
            fprintf(stderr, "Failed to create thread %d\n", i);
            return 1;
        }
    }

    // Join threads
    for (int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up
    for (int i = 0; i < MAX_URLS; i++) {
        free(scraper.urls[i]);
    }
    fclose(scraper.output_file);
    pthread_mutex_destroy(&scraper.mutex);

    return 0;
}
```

