    @lru_cache(maxsize=128)
    def parse_json(cls, json_data: str) -> Any:
        try:
            return json.loads(json_data)
        except json.JSONDecodeError as e:
            logging.error(f"Failed to decode JSON data: {e}")
            return None

    @classmethod
    async def load_and_parse_files(cls, file_paths: list) -> None:
        tasks = [cls.load_file_async(file_path) for file_path in file_paths]
        await asyncio.gather(*tasks)

    @classmethod
