// Node.js Application Code Example

const fs = require('fs');
const path = require('path');

class ModuleManager {
    constructor(config) {
        this.config = config;
        this.modules = [];
    }

    loadModules() {
        for (let moduleName of this.config.order) {
            const modulePath = path.join(__dirname, 'modules', `${moduleName}.js`);
            try {
                const module = require(modulePath);
                this.modules.push({ name: moduleName, module });
            } catch (error) {
                console.error(`Error loading ${moduleName}:`, error);
            }
        }
    }

    executeModules() {
        for (let i = 0; i < this.config.concurrency; i++) {
            while (this.modules.length > 0) {
                const module = this.modules.shift();
                try {
                    module.module.execute();
                } catch (error) {
                    console.error(`Error executing ${module.name}:`, error);
                }
            }
        }
    }
}

// Usage Example
const config = {
    order: ['module1', 'module2', 'module3'],
    concurrency: 2
};

const manager = new ModuleManager(config);
manager.loadModules();
manager.executeModules();
