import os
import tempfile
from contextlib import contextmanager

@contextmanager
def temp_directory():
    temp_dir = tempfile.mkdtemp()
    try:
        yield temp_dir
    finally:
        os.rmdir(temp_dir)

def create_directory_with_retry(directory_name, parent_dir=None, max_retries=5):
    for attempt in range(max_retries):
        try:
            if parent_dir:
                full_path = os.path.join(parent_dir, directory_name)
            else:
                full_path = directory_name

            with temp_directory() as temp_dir:
                os.mkdir(full_path, mode=0o755)
                os.environ[directory_name.upper()] = full_path
                return full_path

        except FileExistsError:
            if attempt == max_retries - 1:
                raise
        except PermissionError:
            if attempt == max_retries - 1:
                raise
        except OSError as e:
            if attempt == max_retries - 1:
                raise
