```javascript
// api.js

const express = require('express');
const bodyParser = require('body-parser');
const rateLimit = require('express-rate-limit');
const { Pool } = require('pg');

const app = express();
app.use(bodyParser.json());
app.use(rateLimit({ windowMs: 15 * 60 * 1000, max: 100 }));

const pool = new Pool({
  connectionString: 'your_database_connection_string',
});

async function updateResource(req, res) {
  const { id } = req.params;
  const data = req.body;
  const version = req.headers['if-match'];

  try {
    const client = await pool.connect();
    await client.query('BEGIN');

    const result = await client.query(
      'SELECT * FROM resources WHERE id = $1 FOR UPDATE',
      [id]
    );

    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Resource not found' });
    }

    const currentVersion = result.rows[0].version;

    if (version && version !== currentVersion.toString()) {
      return res.status(412).send();
    }

    await client.query(
      'UPDATE resources SET data = $1, version = version + 1 WHERE id = $2',
      [data, id]
    );

    await client.query('COMMIT');
    client.release();

    res.json({ message: 'Resource updated successfully' });
  } catch (error) {
    if (client) client.release();
    console.error(error);
    res.status(500).json({ error: 'Internal Server Error' });
  }
}

async function deleteResource(req, res) {
  const { id } = req.params;
  const timestamp = req.headers['if-unmodified-since'];

  try {
    const client = await pool.connect();
    await client.query('BEGIN');

    const result = await client.query(
      'SELECT * FROM resources WHERE id = $1 FOR UPDATE',
      [id]
    );

    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Resource not found' });
    }

    const currentTimestamp = result.rows[0].timestamp;

    if (timestamp && timestamp !== currentTimestamp.toString()) {
      return res.status(409).send();
    }

    await client.query('DELETE FROM resources WHERE id = $1', [id]);
    await client.query('COMMIT');
    client.release();

    res.json({ message: 'Resource deleted successfully' });
  } catch (error) {
    if (client) client.release();
    console.error(error);
    res.status(500).json({ error: 'Internal Server Error' });
  }
}

app.put('/resources/:id', updateResource);
app.delete('/resources/:id', deleteResource);

module.exports = app;
```

