```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function signature for progress callback
typedef void (*progress_callback_t)(int progress, int total);

// Structure to store encryption context
typedef struct {
    EVP_CIPHER_CTX *ctx;
    FILE *input_file;
    FILE *output_file;
    EVP_CIPHER *cipher;
    unsigned char key[32];
    unsigned char iv[16];
} EncryptionContext;

// Function to initialize encryption context
EncryptionContext* init_encryption_context(const char *file_path, const char *cipher_name, progress_callback_t callback) {
    EncryptionContext *ctx = (EncryptionContext*)malloc(sizeof(EncryptionContext));
    if (!ctx) return NULL;

    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) goto err;

    ctx->input_file = fopen(file_path, "rb");
    if (!ctx->input_file) goto err;

    // Initialize cipher and key/iv
    const EVP_CIPHER *cipher = EVP_get_cipherbyname(cipher_name);
    if (!cipher) goto err;
    if (RAND_bytes(ctx->key, sizeof(ctx->key)) != 1) goto err;
    if (RAND_bytes(ctx->iv, sizeof(ctx->iv)) != 1) goto err;

    if (EVP_EncryptInit_ex(ctx->ctx, cipher, NULL, ctx->key, ctx->iv) != 1) goto err;

    // Initialize output file
    char *output_path = malloc(strlen(file_path) + 5);
    snprintf(output_path, strlen(file_path) + 5, "%s.enc", file_path);
    ctx->output_file = fopen(output_path, "wb");
    if (!ctx->output_file) goto err;
    free(output_path);

    // Callback for progress
    callback(0, 100); // Assuming 100% complete for simplicity

    return ctx;

err:
    EVP_CIPHER_CTX_free(ctx->ctx);
    fclose(ctx->input_file);
    fclose(ctx->output_file);
    free(ctx);
    return NULL;
}

// Function to perform encryption
int encrypt_file(EncryptionContext *ctx, progress_callback_t callback) {
    unsigned char inbuf[4096], outbuf[4096];
    int len = 0, outlen = 0;

    while (fread(inbuf, 1, sizeof(inbuf), ctx->input_file) > 0) {
        if (!EVP_EncryptUpdate(ctx->ctx, outbuf, &outlen, inbuf, len)) goto err;
        fwrite(outbuf, 1, outlen, ctx->output_file);
        callback(len * 100 / 4096, 100); // Update progress
    }

    if (!EVP_EncryptFinal_ex(ctx->ctx, outbuf, &outlen)) goto err;
    fwrite(outbuf, 1, outlen, ctx->output_file);
    callback(100, 100); // Final update to indicate completion

    fclose(ctx->input_file);
    fclose(ctx->output_file);
    EVP_CIPHER_CTX_free(ctx->ctx);

    return 0;

err:
    fclose(ctx->input_file);
    fclose(ctx->output_file);
    EVP_CIPHER_CTX_free(ctx->ctx);
    return -1;
}

// Example usage
int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <file_path> <cipher_name>\n", argv[0]);
        return 1;
    }

    EncryptionContext *ctx = init_encryption_context(argv[1], argv[2], NULL);
    if (!ctx) {
        fprintf(stderr, "Failed to initialize encryption context\n");
        return 1;
    }

    if (encrypt_file(ctx, NULL)) {
        fprintf(stderr, "Encryption failed\n");
        free(ctx);
        return 1;
    }

    free(ctx);
    return 0;
}
