import json
from datetime import datetime
import payment_gateway_api

class HotelBookingManager:
    def __init__(self):
        self.database = {}  # Simulated database for booking data

    def validate_request(self, request):
        # Validate the request and check authentication using the token
        if 'token' in request and request['token'] == 'valid_token':
            return True
        return False

    def check_availability(self, hotel_id, room_type, check_in_date, check_out_date):
        # Check if the room is available within the specified dates
        for booking in self.database.get(hotel_id, {}).get(room_type, []):
            if check_in_date <= booking['check_out_date'] and check_out_date >= booking['check_in_date']:
                return False
        return True

    def book_room(self, request):
        # Reserve the room and save the booking details
        hotel_id = request['hotel_id']
        room_type = request['room_type']
        check_in_date = datetime.strptime(request['check_in_date'], '%Y-%m-%d')
        check_out_date = datetime.strptime(request['check_out_date'], '%Y-%m-%d')
        customer_name = request['customer_name']
        customer_email = request['customer_email']

        if self.check_availability(hotel_id, room_type, check_in_date, check_out_date):
            booking = {
                'hotel_id': hotel_id,
                'room_type': room_type,
                'check_in_date': check_in_date,
                'check_out_date': check_out_date,
                'customer_name': customer_name,
                'customer_email': customer_email
            }
            if hotel_id not in self.database:
                self.database[hotel_id] = {}
            if room_type not in self.database[hotel_id]:
                self.database[hotel_id][room_type] = []
            self.database[hotel_id][room_type].append(booking)
            payment_gateway_api.process_payment(customer_email, customer_name)
            return json.dumps({'status': 'success', 'message': 'Room booked successfully'})
        else:
            return json.dumps({'status': 'error', 'message': 'Room not available'})

    def cancel_booking(self, hotel_id, room_type):
        # Remove the booking from the database
        if hotel_id in self.database and room_type in self.database[hotel_id]:
            self.database[hotel_id][room_type] = [booking for booking in self.database[hotel_id][room_type] if not (self.check_availability(hotel_id, room_type, booking['check_in_date'], booking['check_out_date']))]
            return json.dumps({'status': 'success', 'message': 'Booking canceled successfully'})
        else:
            return json.dumps({'status': 'error', 'message': 'No such booking found'})

# Example usage
booking_manager = HotelBookingManager()
request = {
    'hotel_id': '123',
    'room_type': 'deluxe',
    'check_in_date': '2023-10-01',
    'check_out_date': '2023-10-05',
    'customer_name': 'John Doe',
    'customer_email': 'john.doe@example.com',
    'token': 'valid_token'
}
print(booking_manager.book_room(request))
