public class UpdateElementContent : IHttpHandler {
    private TripleDESCryptoServiceProvider desProvider = new TripleDESCryptoServiceProvider();
    private string key = "YourEncryptionKey";
    private string iv = "YourInitializationVector";

    public void ProcessRequest(HttpContext context) {
        if (context.Request.HttpMethod == "POST") {
            try {
                string pageSectionID = context.Request.Form["pageSectionID"];
                string elementID = context.Request.Form["elementID"];
                string htmlContent = context.Request.Form["htmlContent"];

                byte[] decryptedHtmlBytes = DecryptHTML(htmlContent);
                string validatedHtmlContent = ValidateHTML(decryptedHtmlBytes);

                UpdateElement(validatedHtmlContent, pageSectionID, elementID);

                LogUpdate(pageSectionID, elementID, validatedHtmlContent);

                context.Response.Write("Element content updated successfully.");
            } catch (Exception ex) {
                context.Response.StatusCode = 500;
                context.Response.StatusDescription = "Internal Server Error";
                context.Response.Write("An error occurred: " + ex.Message);
            }
        } else {
            context.Response.StatusCode = 405;
            context.Response.StatusDescription = "Method Not Allowed";
            context.Response.Write("Only POST requests are allowed.");
        }
    }

    private byte[] DecryptHTML(string htmlContent) {
        desProvider.Key = Convert.FromBase64String(key);
        desProvider.IV = Convert.FromBase64String(iv);

        using (MemoryStream msDecrypt = new MemoryStream(Convert.FromBase64String(htmlContent))) {
            using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, desProvider.CreateDecryptor(), CryptoStreamMode.Read)) {
                using (StreamReader srDecrypt = new StreamReader(csDecrypt)) {
                    return System.Text.Encoding.UTF8.GetBytes(srDecrypt.ReadToEnd());
                }
            }
        }
    }

    private string ValidateHTML(byte[] decryptedHtmlBytes) {
        string htmlContent = Encoding.UTF8.GetString(decryptedHtmlBytes);
        string pattern = @"<[^>]+>";
        string replacement = "";

        MatchCollection matches = Regex.Matches(htmlContent, pattern);

        foreach (Match match in matches) {
            if (IsAllowedTag(match.Value)) {
                replacement += match.Value;
            }
        }

        return replacement;
    }

    private bool IsAllowedTag(string tag) {
        // Implement logic to validate allowed tags and attributes
        // Return true if the tag is allowed, false otherwise
        return true;
    }

    private void UpdateElement(string htmlContent, string pageSectionID, string elementID) {
        using (SqlConnection connection = new SqlConnection("YourConnectionString")) {
            connection.Open();

            string query = "UPDATE YourTable SET HtmlContent = @HtmlContent WHERE PageSectionID = @PageSectionID AND ElementID = @ElementID";
            using (SqlCommand command = new SqlCommand(query, connection)) {
                command.Parameters.AddWithValue("@HtmlContent", htmlContent);
                command.Parameters.AddWithValue("@PageSectionID", pageSectionID);
                command.Parameters.AddWithValue("@ElementID", elementID);

                command.ExecuteNonQuery();
            }
        }
    }

    private void LogUpdate(string pageSectionID, string elementID, string updatedHtmlContent) {
        using (SqlConnection connection = new SqlConnection("YourConnectionString")) {
            connection.Open();

            string query = "INSERT INTO Logs (PageSectionID, ElementID, UpdatedHtmlContent, UpdateTime) VALUES (@PageSectionID, @ElementID, @UpdatedHtmlContent, GETDATE())";
