#include <iostream>
#include <vector>
#include <mutex>
#include <condition_variable>

struct Point {
    float x, y, z;
};

class OctreeNode {
public:
    std::vector<Point> data;
    std::mutex dataMutex;
    OctreeNode* children[8];

    OctreeNode() : data(), children{nullptr} {}

    ~OctreeNode() {
        for (auto& child : children) {
            if (child != nullptr) {
                delete child;
                child = nullptr;
            }
        }
    }

    bool insert(const Point& point, float min, float max) {
        std::lock_guard<std::mutex> lock(dataMutex);
        if (data.size() < data.capacity() * 0.8f) {
            data.push_back(point);
            return true;
        } else {
            if (!isLeaf()) {
                for (auto& child : children) {
                    if (child != nullptr && child->insert(point, min, max)) {
                        return true;
                    }
                }
            } else {
                split();
                for (auto& child : children) {
                    if (child != nullptr && child->insert(point, min, max)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    void split() {
        float halfSize = (max - min) / 2.0f;
        for (int i = 0; i < 8; ++i) {
            children[i] = new OctreeNode();
        }
        // Reinsert data points into child nodes based on their position
    }

    bool isLeaf() const {
        return children[0] == nullptr;
    }
};

class AdvancedOctree {
public:
    OctreeNode* root;

    AdvancedOctree(float min, float max) : root(new OctreeNode()), min(min), max(max) {}

    ~AdvancedOctree() {
        delete root;
    }

    bool insert(const Point& point) {
        return root->insert(point, min, max);
    }

private:
    float min, max;
};

int main() {
    AdvancedOctree octree(0.0f, 100.0f);
    octree.insert({50.0f, 50.0f, 50.0f});
    return 0;
}
