class JsonManager:
    _registry = {}

    @classmethod
    def register_factory(cls, factory_id, factory_function):
        cls._registry[factory_id] = factory_function

    @classmethod
    async def load_and_execute_json(cls, file_paths):
        tasks = [cls.load_file(file_path) for file_path in file_paths]
        results = await asyncio.gather(*tasks)

        for result in results:
            if isinstance(result, Exception):
                print(f"Error loading file: {result}")
            else:
                cls.execute_result(result)

    @classmethod
    async def load_file(cls, file_path):
        try:
            with open(file_path, 'r') as file:
                data = json.load(file)
                return data
        except Exception as e:
            return e

    @classmethod
    def execute_result(cls, result):
        if isinstance(result, dict) and 'factory_id' in result and 'data' in result:
            factory_function = cls._registry.get(result['factory_id'])
            if factory_function:
                instance = factory_function(**result['data'])
                print(f"Instance created: {instance}")
            else:
                print("Factory function not found for ID:", result['factory_id'])
        else:
            print("Invalid JSON structure", result)

    @classmethod
    def deserialize_and_hash(cls, byte_array, password):
        try:
