            random_string = cls.generate_random_string(obj)
            hashed_password = hashlib.sha256(password.encode('utf-8')).hexdigest()
            return random_string, hashed_password
        except Exception as e:
            print(f"Error deserializing or hashing: {e}")

    @classmethod
    def generate_random_string(cls, obj):
