#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>
#include <fcntl.h> 
#include <sys/stat.h> 
#include <errno.h>

sem_t* create_semaphore(const char *name, int initial_value) {
    sem_t *sem = sem_open(name, O_CREAT, 0644, initial_value);
    if (sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        return NULL;
    }
    return sem;
}

void delete_semaphore(sem_t *sem, const char *name) {
    if (sem_close(sem) == -1) {
        perror("Failed to close semaphore");
    }
    if (sem_unlink(name) == -1) {
        perror("Failed to unlink semaphore");
    }
}

int wait_on_semaphore(sem_t *sem, int timeout_ms) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += timeout_ms / 1000;
    ts.tv_nsec += (timeout_ms % 1000) * 1000000;
    if (sem_timedwait(sem, &ts) == -1 && errno != ETIMEDOUT) {
        perror("Failed to wait on semaphore");
        return -1;
    }
    return 0;
}

int post_semaphore(sem_t *sem) {
    if (sem_post(sem) == -1) {
        perror("Failed to post to semaphore");
        return -1;
    }
    return 0;
}

int get_semaphore_value(sem_t *sem, int *value) {
    if (sem_getvalue(sem, value) == -1) {
        perror("Failed to get semaphore value");
        return -1;
    }
    return 0;
}
