                .thenApply(v -> {
                    List<TaskResult> results = new ArrayList<>();
                    for (Future<TaskResult> future : futures) {
                        try {
                            results.add(future.get());
                        } catch (InterruptedException | ExecutionException e) {
                            // Handle exception, log error, and return failure result
