using System;
using System.Collections.Generic;
using System.Linq;
using System.Web.UI;

public class DataPointGenerator
{
    private int minValue;
    private int maxValue;
    private Random random = new Random();

    public DataPointGenerator(int min, int max)
    {
        SetRange(min, max);
    }

    public void SetRange(int min, int max)
    {
        if (min > max)
        {
            throw new ArgumentException("Minimum value must be less than or equal to maximum value.");
        }
        minValue = min;
        maxValue = max;
    }

    public float GetRandomFloat()
    {
        lock (random)
        {
            return (float)random.NextDouble() * (maxValue - minValue) + minValue;
        }
    }

    public int GetRandomInteger(bool inclusiveMax = true)
    {
        lock (random)
        {
            if (inclusiveMax)
                return random.Next(minValue, maxValue + 1);
            else
                return random.Next(minValue, maxValue);
        }
    }

    public IEnumerable<HtmlControl> SelectMatchingElements(HtmlNode node, string selector, Func<HtmlControl, bool> testFunction)
    {
        var matchingElements = new List<HtmlControl>();
        if (node == null || string.IsNullOrEmpty(selector))
            yield break;

        HtmlNodeCollection nodesToCheck = new HtmlNodeCollection(node.OwnerDocument, new[] { node });
        while (nodesToCheck.Count > 0)
        {
            foreach (var n in nodesToCheck)
            {
                if (n.NodeType == HtmlNodeType.Element && testFunction(n))
                    matchingElements.Add((HtmlControl)n);
            }

            var nextLevelNodes = nodesToCheck.SelectMany(n => n.ChildNodes).ToList();
            nodesToCheck.Clear();
            nodesToCheck.AddRange(nextLevelNodes);
        }

        foreach (var element in matchingElements)
            yield return element;
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }
}
