function authenticateUser($email, $password) {
    // Validate input
    if (!preg_match(EMAIL_PATTERN, $email)) {
        return 'Invalid email format';
    }

    // Check rate limit
    $lastAttempt = $_SESSION['auth_attempts'] ?? 0;
    if (time() - $lastAttempt < RATE_LIMIT_WINDOW && count($_SESSION['auth_attempts']) >= RATE_LIMIT_MAX_ATTEMPTS) {
        return 'Too many attempts. Please try again later.';
    }

    // Attempt to authenticate user using OAuth 2.0 client
    $code = getAuthorizationCode($email, $password);
    if ($code === false) {
        $_SESSION['auth_attempts'][] = time();
        return 'Invalid email or password';
    }

    // Store access token securely in session variable
    $_SESSION['access_token'] = $code;

    // Retrieve user information using access token
    $userInfo = getUserInfo($code);
    if ($userInfo === false) {
        unset($_SESSION['access_token']);
        return 'Failed to retrieve user information';
    }

    // Log authentication attempt
    logAuthenticationAttempt(true, $email, $userInfo['id'], $userInfo['name'], $userInfo['email']);

    // Sanitize and store user data safely in database for future reference
    saveUserData($userInfo);

    return 'Successfully authenticated';
}

