// PokemonService.java
package com.pokemon.service;

import java.io.IOException;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.google.common.collect.Lists;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

@Service
public class PokemonService {

    @Autowired
    private WeaknessConfig weaknessConfig;

    private static final String API_URL = "https://api.example.com/pokemon";
    private final ExecutorService executorService = Executors.newFixedThreadPool(10);
    private final OkHttpClient httpClient = new OkHttpClient();
    private final ObjectMapper objectMapper = new ObjectMapper();

    public void generateReport() {
        try {
            List<Pokemon> pokemonList = fetchPokemonList();
            for (Pokemon pokemon : pokemonList) {
                processPokemon(pokemon);
            }
        } catch (IOException e) {
            System.err.println("Error processing Pokemon data: " + e.getMessage());
        }
    }

    private List<Pokemon> fetchPokemonList() throws IOException {
        Request request = new Request.Builder().url(API_URL).build();
        Response response = httpClient.newCall(request).execute();
        if (!response.isSuccessful()) throw new IOException("Unexpected code " + response);

        return objectMapper.readValue(response.body().string(), objectMapper.getTypeFactory().constructCollectionType(List.class, Pokemon.class));
    }

    private void processPokemon(Pokemon pokemon) {
        executorService.submit(() -> {
            try {
                String weaknesses = determineWeaknesses(pokemon.getType());
                // Generate HTML report for each Pokemon
                generateHTMLReport(pokemon.getName(), weaknesses);
            } catch (IOException e) {
                System.err.println("Error processing Pokemon " + pokemon.getName() + ": " + e.getMessage());
            }
        });
    }

    private String determineWeaknesses(String type) throws IOException {
        // Implement logic to fetch type weaknesses from external API
        // For demonstration, using a local configuration for simplicity
        return weaknessConfig.getWeaknessForType(type);
    }

    private void generateHTMLReport(String name, String weaknesses) {
        // Generate HTML content and save it to a file or send over HTTP
        System.out.println("Generated report for " + name + ": " + weaknesses);
    }
}

