class ClinicManager {
    private $db;
    private static $factoryRegistry = [];

    public function __construct($db) {
        $this->db = $db;
    }

    public static function addFactoryFunction($id, callable $factoryFunction) {
        self::$factoryRegistry[$id] = $factoryFunction;
    }

    public static function createClinicInstance($id, ...$args) {
        if (!isset(self::$factoryRegistry[$id])) {
            throw new Exception("No factory function registered for ID: $id");
        }
        return call_user_func(self::$factoryRegistry[$id], ...$args);
    }

    public function updateClinicStatus($clinicId, $status, $ipAddress) {
        try {
            if (!is_numeric($clinicId)) {
                throw new Exception("Invalid clinic ID: $clinicId");
            }

            $this->db->beginTransaction();

            // Update clinic status
            $stmt = $this->db->prepare("UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = NOW() WHERE id = ?");
            $stmt->execute([$status, $ipAddress, $clinicId]);

            if ($stmt->rowCount() === 0) {
                throw new Exception("No clinic found with ID: $clinicId");
            }

            // Log the update
            $this->logUpdate($clinicId, $status, $ipAddress);

            $this->db->commit();
        } catch (Exception $e) {
            $this->db->rollBack();
            throw $e;
        }
    }

    private function logUpdate($clinicId, $status, $ipAddress) {
        // External logging service integration
        // Example: Log to a file or send an HTTP request to a logging API
    }

    public function clinicToJson(Clinic $clinic) {
        return json_encode([
            'id' => $clinic->getId(),
            'name' => $clinic->getName(),
            'status' => $clinic->getStatus(),
            // Add other relevant fields
        ]);
    }

    public function createClinicFromJson($jsonString) {
        $data = json_decode($jsonString, true);
        if (isset(self::$factoryRegistry[$data['id']])) {
            return call_user_func(self::$factoryRegistry[$data['id']], $data);
        }
        throw new Exception("No factory function registered for ID: {$data['id']}");
    }

    public function rateLimit($ipAddress) {
        // Rate limiting logic
        // Example: Use a Redis or Memcached cache to track requests per IP
    }
}

