public class SecureCipherService : IDisposable
{
    private readonly HttpClient _httpClient;
    private readonly ConcurrentDictionary<string, (byte[], DateTime)> _keyCache = new();
    private string _accessToken;
    private DateTime _tokenExpiryTime;

    public SecureCipherService(string tokenEndpoint, string clientId, string clientSecret)
    {
        _httpClient = new HttpClient();
        AuthenticateAsync(tokenEndpoint, clientId, clientSecret).GetAwaiter().GetResult();
    }

    public async Task<byte[]> DecryptMessageAsync(byte[] ciphertext, byte[] key, byte[] iv, int offset = 0)
    {
        if (ciphertext == null || key == null || iv == null)
            throw new ArgumentException("Ciphertext, key, and IV must not be null");

        // Authenticate if token is expired
        if (_tokenExpiryTime <= DateTime.UtcNow.AddSeconds(-30))
        {
            await AuthenticateAsync();
        }

        // Cache the key securely (for demonstration, not implemented here)

        using (Aes aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;

            ICryptoTransform decryptor = aes.CreateDecryptor();
            using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    byte[] decryptedBytes = new byte[ciphertext.Length - offset];
                    await csDecrypt.ReadAsync(decryptedBytes, 0, decryptedBytes.Length);
                    return decryptedBytes;
                }
            }
        }
    }

    private async Task AuthenticateAsync(string tokenEndpoint = null, string clientId = null, string clientSecret = null)
    {
        if (tokenEndpoint != null && clientId != null && clientSecret != null)
        {
            // Implement OAuth 2.0 token retrieval logic here
            var content = new FormUrlEncodedContent(new[]
            {
                new KeyValuePair<string, string>("grant_type", "client_credentials"),
                new KeyValuePair<string, string>("client_id", clientId),
                new KeyValuePair<string, string>("client_secret", clientSecret)
            });

            HttpResponseMessage response = await _httpClient.PostAsync(tokenEndpoint, content);
            if (!response.IsSuccessStatusCode)
            {
                throw new Exception($"Token retrieval failed: {await response.Content.ReadAsStringAsync()}");
            }

            // Parse the token and expiry time from the response
            var jsonResponse = await response.Content.ReadAsAsync<dynamic>();
            _accessToken = jsonResponse.access_token;
            _tokenExpiryTime = DateTime.UtcNow.AddSeconds(jsonResponse.expires_in);
        }
        else if (string.IsNullOrEmpty(_accessToken) || _tokenExpiryTime <= DateTime.UtcNow.AddSeconds(-30))
        {
            // Use an existing token or refresh it
            var content = new FormUrlEncodedContent(new[]
            {
                new KeyValuePair<string, string>("grant_type", "refresh_token"),
                new KeyValuePair<string, string>("client_id", clientId),
                new KeyValuePair<string, string>("refresh_token", _accessToken)
            });

            HttpResponseMessage response = await _httpClient.PostAsync(tokenEndpoint, content);
            if (!response.IsSuccessStatusCode)
            {
                throw new Exception($"Token refresh failed: {await response.Content.ReadAsStringAsync()}");
            }

            // Parse the token and expiry time from the response
            var jsonResponse = await response.Content.ReadAsAsync<dynamic>();
            _accessToken = jsonResponse.access_token;
            _tokenExpiryTime = DateTime.UtcNow.AddSeconds(jsonResponse.expires_in);
        }
    }

    public void Dispose()
    {
        _httpClient.Dispose();
        GC.SuppressFinalize(this);
    }
}
