import os
import logging
from collections import defaultdict
import csv
import statistics

# Configure logging
logging.basicConfig(filename='script.log', level=logging.INFO)

def process_directory(directory_path):
    file_stats = defaultdict(dict)
    for root, _, files in os.walk(directory_path):
        for file_name in files:
            file_extension = os.path.splitext(file_name)[1].lower()
            if file_extension in ['.txt', '.log', '.csv']:
                file_path = os.path.join(root, file_name)
                try:
                    with open(file_path, 'r', encoding='utf-8') as file:
                        if file_extension == '.txt':
                            text_stats = process_text_file(file)
                        elif file_extension == '.log':
                            log_stats = process_log_file(file)
                        elif file_extension == '.csv':
                            csv_stats = process_csv_file(file)
                    file_stats[file_extension].update(text_stats if file_extension == '.txt' else log_stats if file_extension == '.log' else csv_stats)
                except Exception as e:
                    logging.error(f"Error processing {file_path}: {e}")
    return file_stats

def process_text_file(file):
    lines = file.readlines()
    num_lines = len(lines)
    words = [word for line in lines for word in line.split()]
    num_words = len(words)
    num_chars = sum(len(line) for line in lines)
    return {'lines': num_lines, 'words': num_words, 'characters': num_chars}

def process_log_file(file):
    # Implement log file processing logic here
    pass

def process_csv_file(file):
    reader = csv.reader(file)
    headers = next(reader)
    data = list(reader)
    unique_values = {header: set(column) for header, column in zip(headers, zip(*data))}
    stats = {
        'unique_values': {header: len(unique_values[header]) for header in headers},
        **{f'{header}_mean': statistics.mean(column) if all(item.isdigit() for item in column) else None for header, column in zip(headers, zip(*data))},
        **{f'{header}_median': statistics.median(column) if all(item.isdigit() for item in column) else None for header, column in zip(headers, zip(*data))},
        **{f'{header}_mode': statistics.mode(column) if all(item.isdigit() for item in column) else None for header, column in zip(headers, zip(*data))}
    }
    return stats

if __name__ == "__main__":
    directory_path = input("Enter the path to the directory: ")
    file_stats = process_directory(directory_path)
    print(f"File statistics: {file_stats}")
