```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <algorithm>
#include <thread>
#include <mutex>
#include <condition_variable>

const int MAX_INT = 1000000;
const int MIN_INT = -1000000;

struct FileData {
    std::string filename;
    std::ifstream file;
    long long sum = 0;
    size_t count = 0;
};

std::mutex mtx;
long long global_sum = 0;
size_t global_count = 0;
std::condition_variable cv;
bool done = false;

void processFile(FileData& data) {
    int num;
    while (data.file >> num) {
        if (num >= MIN_INT && num <= MAX_INT) {
            std::lock_guard<std::mutex> lock(mtx);
            global_sum += num;
            ++global_count;
        }
    }
    cv.notify_one();
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " file1 [file2 ...]" << std::endl;
        return 1;
    }

    std::vector<FileData> files;
    for (int i = 1; i < argc; ++i) {
        FileData data;
        data.filename = argv[i];
        data.file.open(data.filename);
        if (!data.file.is_open()) {
            std::cerr << "Failed to open file: " << data.filename << std::endl;
            return 1;
        }
        files.push_back(data);
    }

    std::vector<std::thread> threads;
    for (auto& file : files) {
        threads.emplace_back(processFile, std::ref(file));
    }

    std::unique_lock<std::mutex> lock(mtx);
    cv.wait(lock, [] { return done && threads.empty(); });

    double average = global_count > 0 ? static_cast<double>(global_sum) / global_count : 0.0;
    long long max_value = *std::max_element(files.begin(), files.end(),
                                         [](const FileData& a, const FileData& b) {
                                             return a.sum < b.sum;
                                         });

    for (auto& file : files) {
        file.file.close();
    }

    std::cout << "Largest integer across all files: " << max_value << std::endl;
    std::cout << "Average of all integers: " << average << std::endl;

    return 0;
}
```

This code provides a basic structure for the program you've described. It uses threads to process each file concurrently, locks to synchronize access to shared variables, and a condition variable to wait for all files to be processed before printing the results. The `processFile` function reads integers from a file, validates them, and updates the global sum and count. The main function opens the input files, starts threads to process them, waits for their completion, and then calculates and prints the largest integer and average of all integers across all files.

