angular.module('dialogApp', []).service('DialogService', function($http, $q) {
    this.refreshFields = function(dialogFields, fieldsToRefresh, resourceId, apiUrl) {
        var promises = [];

        // Identify fields to refresh
        fieldsToRefresh.forEach(function(fieldName) {
            if (dialogFields[fieldName]) {
                // Create a promise for each field update
                promises.push(this.updateField(fieldName, resourceId, apiUrl));
            }
        }, this);

        return $q.all(promises).then(function(responses) {
            // Handle successful updates
            responses.forEach(function(response, index) {
                dialogFields[fieldsToRefresh[index]].value = response.data;
            });
            return dialogFields;
        }, function(error) {
            // Handle errors
            console.error('Error refreshing fields:', error);
            throw error;
        });
    };

    this.updateField = function(fieldName, resourceId, apiUrl) {
        var url = `${apiUrl}/${resourceId}/${fieldName}`;
        return $http.get(url).then(function(response) {
            return response.data;
        }, function(error) {
            if (error.status === 404) {
                console.warn(`Field ${fieldName} not found for resource ${resourceId}`);
            } else {
                console.error('Error updating field:', error);
            }
            throw error;
        });
    };
});

