using System;
using System.Net.Http;
using System.Threading.Tasks;

public class WebAppService : IWebAppService
{
    private readonly IElementUpdateService _elementUpdateService;
    private readonly ICacheInvalidationService _cacheInvalidationService;

    public WebAppService(IElementUpdateService elementUpdateService, ICacheInvalidationService cacheInvalidationService)
    {
        _elementUpdateService = elementUpdateService ?? throw new ArgumentNullException(nameof(elementUpdateService));
        _cacheInvalidationService = cacheInvalidationService ?? throw new ArgumentNullException(nameof(cacheInvalidationService));
    }

    public async Task<HttpResponseMessage> HandlePostRequestAsync(string pageSectionId, string elementId, string htmlContent)
    {
        try
        {
            // Validate input
            if (string.IsNullOrEmpty(pageSectionId) || string.IsNullOrEmpty(elementId))
                return new HttpResponseMessage(HttpStatusCode.BadRequest)
                {
                    Content = new StringContent("Invalid page section or element ID")
                };

            if (!HtmlIsValid(htmlContent))
                return new HttpResponseMessage(HttpStatusCode.BadRequest)
                {
                    Content = new StringContent("Malformed HTML content")
                };

            // Update the element's HTML content
            bool updateSuccess = await _elementUpdateService.UpdateElementAsync(pageSectionId, elementId, htmlContent);
            if (!updateSuccess)
                return new HttpResponseMessage(HttpStatusCode.InternalServerError)
                {
                    Content = new StringContent("Failed to update element content")
                };

            // Notify cache invalidation service asynchronously
            await _cacheInvalidationService.InvalidateCacheAsync(pageSectionId);

            return new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = new StringContent("Update successful. Refresh the page.")
            };
        }
        catch (Exception ex)
        {
            // Log the exception for further investigation
            Console.WriteLine($"An error occurred: {ex.Message}");

            // Return an internal server error response with a generic message
            return new HttpResponseMessage(HttpStatusCode.InternalServerError)
            {
                Content = new StringContent("Internal server error")
            };
        }
    }

    private bool HtmlIsValid(string htmlContent)
    {
        try
        {
            using (var reader = new System.Xml.Linq.XDocument())
            {
                reader.ReadFrom(new System.IO.StringReader(htmlContent));
            }
            return true;
        }
        catch (System.Xml.XmlException)
        {
            return false;
        }
    }
}

public interface IWebAppService
{
    Task<HttpResponseMessage> HandlePostRequestAsync(string pageSectionId, string elementId, string htmlContent);
}

public interface IElementUpdateService
{
    Task<bool> UpdateElementAsync(string pageSectionId, string elementId, string htmlContent);
}

public interface ICacheInvalidationService
{
    Task InvalidateCacheAsync(string pageSectionId);
}
