```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

typedef struct {
    char *key;
    union {
        int intValue;
        double floatValue;
        char *stringValue;
    } value;
    int type; // 0 for string, 1 for integer, 2 for float
} ResourceBundleItem;

ResourceBundleItem* load_resource_bundle(const char *path, int *numItems) {
    FILE *file = fopen(path, "r");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    struct json_object *parsed_json;
    parsed_json = json_tokener_parse_file(path);
    if (!parsed_json || json_type_array != json_object_get_type(parsed_json)) {
        fclose(file);
        fprintf(stderr, "Invalid JSON format in file\n");
        return NULL;
    }

    int count = json_object_array_length(parsed_json);
    *numItems = count;

    ResourceBundleItem *bundle = malloc(count * sizeof(ResourceBundleItem));
    if (!bundle) {
        json_object_put(parsed_json);
        fclose(file);
        perror("Error allocating memory for resource bundle");
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        struct json_object *item = json_object_array_get_idx(parsed_json, i);
        struct json_object *key_obj, *value_obj;
        if (!json_object_object_get_ex(item, "key", &key_obj) ||
            !json_object_object_get_ex(item, "value", &value_obj)) {
            free(bundle);
            json_object_put(parsed_json);
            fclose(file);
            fprintf(stderr, "Invalid item format in file\n");
            return NULL;
        }

        bundle[i].key = strdup(json_object_get_string(key_obj));
        if (!bundle[i].key) {
            for (int j = 0; j < i; j++) free(bundle[j].key);
            free(bundle);
            json_object_put(parsed_json);
            fclose(file);
            perror("Error allocating memory for key");
            return NULL;
        }

        int type = json_object_get_type(value_obj);
        if (type == json_type_int) {
            bundle[i].value.intValue = json_object_get_int(value_obj);
            bundle[i].type = 1;
        } else if (type == json_type_double) {
            bundle[i].value.floatValue = json_object_get_double(value_obj);
            bundle[i].type = 2;
        } else if (type == json_type_string) {
            bundle[i].value.stringValue = strdup(json_object_get_string(value_obj));
            if (!bundle[i].value.stringValue) {
                for (int j = 0; j <= i; j++) free(bundle[j].key);
                free(bundle);
                json_object_put(parsed_json);
                fclose(file);
                perror("Error allocating memory for string value");
                return NULL;
            }
            bundle[i].type = 0;
        } else {
            for (int j = 0; j <= i; j++) free(bundle[j].key);
            if (bundle[i].type == 0) free(bundle[i].value.stringValue);
            free(bundle);
            json_object_put(parsed_json);
            fclose(file);
            fprintf(stderr, "Invalid value type in file\n");
            return NULL;
        }
    }

    json_object_put(parsed_json);
    fclose(file);
    return bundle;
}

void serialize_resource_bundle(const char *path, ResourceBundleItem *bundle, int numItems) {
    struct json_object *parsed_json = json_object_new_array();
    for (int i = 0; i < numItems; i++) {
        struct json_object *item = json_object_new_object();
        json_object_object_add(item, "key", json_object_new_string(bundle[i].key));
        if (bundle[i].type == 1) {
            json_object_object_add(item, "value", json_object_new_int(bundle[i].value.intValue));
        } else if (bundle[i].type == 2) {
            json_object_object_add(item, "value", json_object_new_double(bundle[i].value.floatValue));
        } else {
            json_object_object_add(item, "value", json_object_new_string(bundle[i].value.stringValue));
        }
        json_object_array_add(parsed_json, item);
    }

    FILE *file = fopen(path, "w");
    if (!file) {
        perror("Error opening file for writing");
        json_object_put(parsed_json);
        return;
    }

    const char *json_str = json_object_to_json_string_ext(parsed_json, JSON_C_TO_STRING_PRETTY);
    fwrite(json_str, 1, strlen(json_str), file);

    fclose(file);
    json_object_put(parsed_json);
}

void free_resource_bundle(ResourceBundleItem *bundle, int numItems) {
    for (int i = 0; i < numItems; i++) {
        free(bundle[i].key);
        if (bundle[i].type == 0) free(bundle[i].value.stringValue);
    }
    free(bundle);
}
```

