        _cacheProvider.Setup(cp => cp.TryGetValue(It.IsAny<string>(), out It.Ref<object>.IsAny)).Returns(true).Callback<string, object>((key, value) => value = new List<CustomObject> { new CustomObject { Id = 1, Name = "Test" } });

