        Assert.Equal(1, result[0].Id);
        Assert.Equal("Test", result[0].Name);
    }

    [Fact]
    public async Task ExecuteAsync_WhenParametersDoNotMatchCache_ExecutesProcedureAndCachesResult()
    {
        var executor = new StoredProcedureExecutor("connection_string", GetMockCacheProvider(), GetMockLogger());
        _cacheProvider.Setup(cp => cp.TryGetValue(It.IsAny<string>(), out It.Ref<object>.IsAny)).Returns(false);
