```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class FileEncryptor
{
    private byte[] key;
    private byte[] salt;

    public FileEncryptor(byte[] encryptionKey, byte[] encryptionSalt)
    {
        key = encryptionKey;
        salt = encryptionSalt;
    }

    public void EncryptFile(string inputFilePath, string outputFilePath)
    {
        using (AesGcm aesGcm = new AesGcm(key))
        {
            byte[] iv = GenerateRandomBytes(12);
            byte[] tag = new byte[16];
            byte[] plaintext = File.ReadAllBytes(inputFilePath);

            using (FileStream fs = new FileStream(outputFilePath, FileMode.Create, FileAccess.Write, FileShare.None))
            {
                fs.Write(salt, 0, salt.Length);
                fs.Write(iv, 0, iv.Length);
                aesGcm.Encrypt(iv, plaintext, tag, fs, plaintext.Length);
                fs.Write(tag, 0, tag.Length);
            }
        }
    }

    public byte[] DecryptFile(string inputFilePath)
    {
        using (AesGcm aesGcm = new AesGcm(key))
        {
            byte[] salt = new byte[16];
            byte[] iv = new byte[12];
            byte[] tag = new byte[16];
            byte[] ciphertext;

            using (FileStream fs = new FileStream(inputFilePath, FileMode.Open, FileAccess.Read, FileShare.None))
            {
                salt = ReadBytes(fs, salt.Length);
                iv = ReadBytes(fs, iv.Length);
                ciphertext = ReadBytes(fs, (int)fs.Length - salt.Length - iv.Length - tag.Length);
                tag = ReadBytes(fs, tag.Length);
            }

            aesGcm.Decrypt(iv, ciphertext, tag, out byte[] plaintext);

            return plaintext;
        }
    }

    private static byte[] GenerateRandomBytes(int length)
    {
        using (RNGCryptoServiceProvider rng = new RNGCryptoServiceProvider())
        {
            byte[] bytes = new byte[length];
            rng.GetBytes(bytes);
            return bytes;
        }
    }

    private static byte[] ReadBytes(FileStream fs, int count)
    {
        byte[] buffer = new byte[count];
        int bytesRead = 0;

        while (bytesRead < count)
        {
            int result = fs.Read(buffer, bytesRead, count - bytesRead);
            if (result == 0)
                throw new EndOfStreamException("Unexpected end of stream");

            bytesRead += result;
        }

        return buffer;
    }
}
