#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <zlib.h> // For compression and decompression

enum ResourceType { IMAGE, TEXT, AUDIO, NUM_TYPES };
typedef struct ResourceItem {
    enum ResourceType type;
    void* data;
} ResourceItem;

typedef struct ResourceBundle {
    ResourceItem* items;
    size_t itemCount[NUM_TYPES];
    size_t totalItemCount;
    pthread_mutex_t mutex; // For thread safety
} ResourceBundle;

// Function to load resource based on file path and type
void* loadResource(const char* filePath, enum ResourceType type) {
    FILE* file = fopen(filePath, "rb");
    if (!file) return NULL;

    fseek(file, 0, SEEK_END);
    size_t fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    unsigned char* buffer = (unsigned char*)malloc(fileSize);
    if (!buffer) {
        fclose(file);
        return NULL;
    }

    fread(buffer, 1, fileSize, file);
    fclose(file);

    // Simulate compression and decompression
    uLong srcLen = fileSize;
    uLong destLen = compressBound(srcLen);
    unsigned char* destBuffer = (unsigned char*)malloc(destLen);
    if (!destBuffer) {
        free(buffer);
        return NULL;
    }

    if (compress2(destBuffer, &destLen, buffer, srcLen, Z_DEFAULT_COMPRESSION) != Z_OK) {
        free(buffer);
        free(destBuffer);
        return NULL;
    }

    // Simulate resource loading
    ResourceItem* item = (ResourceItem*)malloc(sizeof(ResourceItem));
    item->type = type;
    item->data = malloc(destLen);
    memcpy(item->data, destBuffer, destLen);

    free(buffer);
    free(destBuffer);

    return item;
}

ResourceBundle* loadResourceBundle(const char* filePath) {
    ResourceBundle* bundle = (ResourceBundle*)malloc(sizeof(ResourceBundle));
    if (!bundle) return NULL;

    pthread_mutex_init(&bundle->mutex, NULL);

    // Simulate loading resources
    ResourceItem* items[NUM_TYPES] = { NULL };
    size_t itemCount[NUM_TYPES] = { 0 };

    for (int i = 0; i < NUM_TYPES; ++i) {
        char fullPath[256];
        snprintf(fullPath, sizeof(fullPath), "%s_type%d", filePath, i);
        items[i] = loadResource(fullPath, (enum ResourceType)i);
        if (items[i]) itemCount[i]++;
    }

    bundle->items = items;
    memcpy(bundle->itemCount, itemCount, NUM_TYPES * sizeof(size_t));
    bundle->totalItemCount = itemCount[IMAGE] + itemCount[TEXT] + itemCount[AUDIO];

    return bundle;
}

void freeResourceBundle(ResourceBundle* bundle) {
    for (int i = 0; i < NUM_TYPES; ++i) {
        if (bundle->items[i]) {
            ResourceItem* item = bundle->items[i];
            free(item->data);
            free(item);
        }
    }
    pthread_mutex_destroy(&bundle->mutex);
    free(bundle);
}
