```rust
use std::env;
use std::fs::{self, File};
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

use tempfile;

struct WorkingDirectoryManager {
    dir_path: PathBuf,
    cleanup_interval: Duration,
}

impl WorkingDirectoryManager {
    fn new(cleanup_interval: Duration) -> Self {
        let work_dir = match env::var("WORK_DIR") {
            Ok(dir) => PathBuf::from(dir),
            Err(_) => tempfile::tempdir().expect("Failed to create temporary directory").into_path(),
        };

        if !work_dir.exists() {
            fs::create_dir_all(&work_dir).expect("Failed to create working directory");
        }

        WorkingDirectoryManager { dir_path: work_dir, cleanup_interval }
    }

    fn get_dir_path(&self) -> &Path {
        &self.dir_path
    }

    async fn start_cleanup_task(self: Arc<Self>) {
        loop {
            tokio::time::sleep(self.cleanup_interval).await;
            if self.is_empty().expect("Failed to check directory contents") {
                fs::remove_dir_all(&self.dir_path).expect("Failed to clean up working directory");
                break;
            }
        }
    }

    fn is_empty(&self) -> io::Result<bool> {
        Ok(self.dir_path.read_dir()?.next().is_none())
    }
}

fn main() {
    let cleanup_interval = Duration::from_secs(30);
    let manager = Arc::new(Mutex::new(WorkingDirectoryManager::new(cleanup_interval)));

    // Spawn a task to handle directory cleanup
    tokio::spawn(manager.clone().start_cleanup_task());

    // Example usage of the working directory
    let mut file_path = manager.lock().unwrap().dir_path.join("test.txt");
    let mut file = File::create(&file_path).expect("Failed to create test file");
    file.write_all(b"Hello, world!").expect("Failed to write to test file");

    // Simulate long-running pipeline task
    tokio::time::sleep(Duration::from_secs(60)).await;

    println!("Pipeline completed. Working directory: {:?}", manager.lock().unwrap().dir_path);
}
```

This code provides a basic implementation of the `WorkingDirectoryManager` struct, which manages a working directory for a CI/CD pipeline. It checks if the `WORK_DIR` environment variable is set and uses it if valid; otherwise, it creates a new temporary directory under `/tmp`. The manager includes a cleanup task that runs at a specified interval to remove the working directory when it becomes empty.

The main function demonstrates how to use the `WorkingDirectoryManager` in a simple pipeline scenario. It spawns a task for the cleanup process and simulates a long-running pipeline task by sleeping for 60 seconds.

