            RequireDigit = true,
            RequireLowercase = true,
            RequireUppercase = false
        };

        this.PasswordValidator = passwordValidator;

        // Customize validation logic based on user roles
        var roleBasedPasswordValidator = new RoleBasedPasswordValidator
        {
            DefaultRolePolicy = "Default",
            AdministratorRolePolicy = "Stronger"
        };

        this.PasswordValidator = roleBasedPasswordValidator;
    }

    private void ConfigureLockoutPolicies()
    {
        // Define lockout policies based on user roles
        var defaultLockoutPolicy = new LockoutOptions
        {
            DefaultAccountLockoutTimeSpan = TimeSpan.FromMinutes(30),
            MaxFailedAccessAttemptsBeforeLockout = 5
        };

        this.AccessFailedCountThreshold = defaultLockoutPolicy.MaxFailedAccessAttemptsBeforeLockout;

        // Customize lockout policies based on user roles
        var roleBasedLockoutPolicy = new RoleBasedLockoutPolicy
        {
            DefaultRolePolicy = defaultLockoutPolicy,
            AdministratorRolePolicy = new LockoutOptions
            {
                DefaultAccountLockoutTimeSpan = TimeSpan.FromHours(1),
                MaxFailedAccessAttemptsBeforeLockout = 3
            }
        };

        this.AccessFailedCountThreshold = roleBasedLockoutPolicy.GetLockoutPolicy("Administrator").MaxFailedAccessAttemptsBeforeLockout;
    }

