using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Net.NetworkInformation;
using System.Threading.Tasks;

class Program
{
    static async Task Main(string[] args)
    {
        if (args.Length == 0)
        {
            Console.WriteLine("No files specified.");
            return;
        }

        var filePaths = args.Select(Path.GetFullPath).ToList();
        var largestNumber = long.MinValue;
        double totalSum = 0;
        int numberOfNumbers = 0;

        foreach (var path in filePaths)
        {
            if (!Directory.Exists(path))
            {
                Console.WriteLine($"Error: Directory '{path}' does not exist.");
                continue;
            }

            if (!File.Exists(Path.Combine(path, "web.config")))
            {
                Console.WriteLine($"Error: web.config file missing in directory '{path}'.");
                continue;
            }

            try
            {
                var files = Directory.GetFiles(path, "*.txt", SearchOption.AllDirectories);
                var tasks = new List<Task<(long, int)>>();

                foreach (var file in files)
                {
                    tasks.Add(ProcessFileAsync(file));
                }

                await Task.WhenAll(tasks);

                foreach (var (maxNumber, count) in tasks.Select(t => t.Result))
                {
                    largestNumber = Math.Max(largestNumber, maxNumber);
                    totalSum += maxNumber;
                    numberOfNumbers += count;
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error processing directory '{path}': {ex.Message}");
            }
        }

        if (numberOfNumbers > 0)
        {
            Console.WriteLine($"Largest Number: {largestNumber}");
            Console.WriteLine($"Average: {totalSum / numberOfNumbers}");
        }
        else
        {
            Console.WriteLine("No numbers found.");
        }
    }

    static async Task<(long, int)> ProcessFileAsync(string filePath)
    {
        using (var reader = new StreamReader(filePath))
        {
            long maxNumber = long.MinValue;
            int count = 0;

            while (!reader.EndOfStream)
            {
                var line = await reader.ReadLineAsync();
                if (int.TryParse(line, out int number))
                {
                    maxNumber = Math.Max(maxNumber, number);
                    count++;
                }
            }

            return (maxNumber, count);
        }
    }
}
