import json
import asyncio
import importlib.util
import os
import sys
import logging

class JsonSerializable:
    @classmethod
    def from_json(cls, data):
        return cls(**data)

    def to_json(self):
        return self.__dict__

class User(JsonSerializable):
    pass

class Product(JsonSerializable):
    pass

class Order(JsonSerializable):
    pass

def create_factory(class_name):
    if class_name == 'User':
        return User.from_json
    elif class_name == 'Product':
        return Product.from_json
    elif class_name == 'Order':
        return Order.from_json
    else:
        raise ValueError(f"Unknown class: {class_name}")

async def load_file(file_path, factory):
    try:
        with open(file_path, 'r') as file:
            data = json.load(file)
            instance = factory(data)
            return instance
    except Exception as e:
        logging.error(f"Error loading file '{file_path}': {e}")
        return None

async def load_json_files(file_paths):
    tasks = [load_file(file_path, create_factory(os.path.splitext(os.path.basename(file_path))[0])) for file_path in file_paths]
    instances = await asyncio.gather(*tasks)
    return [instance for instance in instances if instance is not None]

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    json_files = ['user.json', 'product.json', 'order.json']
    instances = asyncio.run(load_json_files(json_files))
    for instance in instances:
        print(instance.to_json())
```

