    if directory_manager.create_directory("temp_dir", parent_dir="/path/to/parent"):
        print("Directory created successfully.")
    else:
        print("Failed to create directory.")

    EnvironmentVariableManager.set_environment_variable("TEMP_DIR_PATH", "/path/to/temp/dir")

