```php
<?php

class SecureSessionManager {
    private $db;
    private $salt;

    public function __construct($db) {
        $this->db = $db;
        // Generate a unique salt for password hashing
        $this->salt = bin2hex(random_bytes(16));
    }

    public function generateToken($length, $charset = 'alnum') {
        if (!in_array($charset, ['alnum', 'alpha', 'numeric'])) {
            throw new InvalidArgumentException('Invalid character set');
        }
        return substr(str_shuffle(str_repeat(str_pad('', $length, $charset), $length)), 1, $length);
    }

    public function hashPassword($password) {
        return password_hash($password . $this->salt, PASSWORD_BCRYPT);
    }

    public function verifyPassword($password, $hashedPassword) {
        return password_verify($password . $this->salt, $hashedPassword);
    }

    public function storeSession($userId, $token) {
        try {
            $stmt = $this->db->prepare('INSERT INTO sessions (user_id, token) VALUES (?, ?)');
            $stmt->execute([$userId, $token]);
        } catch (PDOException $e) {
            throw new RuntimeException('Failed to store session', 0, $e);
        }
    }

    public function checkSession($userId, $token) {
        try {
            $stmt = $this->db->prepare('SELECT * FROM sessions WHERE user_id = ? AND token = ?');
            $stmt->execute([$userId, $token]);
            return $stmt->fetch() !== false;
        } catch (PDOException $e) {
            throw new RuntimeException('Failed to check session', 0, $e);
        }
    }

    public function removeSession($userId) {
        try {
            $stmt = $this->db->prepare('DELETE FROM sessions WHERE user_id = ?');
            $stmt->execute([$userId]);
        } catch (PDOException $e) {
            throw new RuntimeException('Failed to remove session', 0, $e);
        }
    }
}

// Usage example:
$db = new PDO('mongodb:host=localhost;dbname=mydatabase', 'username', 'password');
$sessionManager = new SecureSessionManager($db);

$userToken = $sessionManager->generateToken(32);
$hashedPassword = $sessionManager->hashPassword('user_password');

try {
    $sessionManager->storeSession(1, $userToken);
    if ($sessionManager->checkSession(1, $userToken)) {
        echo "Session is valid.";
    }
    $sessionManager->removeSession(1);
} catch (RuntimeException $e) {
    echo "Error: " . $e->getMessage();
}
?>
```

