{
    connection.Open();
    var reader = ExecuteParameterizedQuery(connection, "SELECT * FROM Users WHERE Age > @age AND RegistrationDate <= @date", new List<object> { 25, DateTime.Now });
    while (reader.Read())
    {
        // Process the results
    }

    var results = ExecuteParameterizedQuery(connection, "SELECT * FROM Orders WHERE CustomerID = @id", new List<object> { 12345 }, true);
    foreach (var result in results)
    {
        // Process each order
    }
}
```

