```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Linq;
using System.Threading.Tasks;

public class SqlExecutor
{
    private static readonly Dictionary<string, SqlCommand> _commandCache = new Dictionary<string, SqlCommand>();
    private static readonly int CacheSize = 100; // Configurable threshold

    public static IDataReader ExecuteParameterizedQuery(SqlConnection connection, string sql, List<object> parameters, bool returnResultsAsList = false)
    {
        using (SqlCommand command = GetCommand(sql))
        {
            foreach (var param in parameters)
            {
                AddParameter(command, param);
            }

            if (!returnResultsAsList)
            {
                return command.ExecuteReader();
            }
            else
            {
                var results = new List<object>();
                using (SqlDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        // Assuming a single column for simplicity; adjust as needed
                        results.Add(reader.GetValue(0));
                    }
                }
                return results;
            }
        }
    }

    private static SqlCommand GetCommand(string sql)
    {
        lock (_commandCache)
        {
            if (!_commandCache.TryGetValue(sql, out SqlCommand cachedCommand))
            {
                if (_commandCache.Count >= CacheSize)
                {
                    _commandCache.Clear(); // Simple eviction policy
                }
                cachedCommand = new SqlCommand(sql);
                _commandCache[sql] = cachedCommand;
            }
            return cachedCommand.Clone() as SqlCommand; // Clone to avoid thread safety issues
        }
    }

    private static void AddParameter(SqlCommand command, object parameter)
    {
        var sqlParam = command.CreateParameter();
        if (parameter is int intValue)
        {
            sqlParam.DbType = DbType.Int32;
            sqlParam.Value = intValue;
        }
        else if (parameter is string stringValue)
        {
            sqlParam.DbType = DbType.String;
            sqlParam.Value = stringValue ?? DBNull.Value;
        }
        else if (parameter is DateTime dateTimeValue)
        {
            sqlParam.DbType = DbType.DateTime;
            sqlParam.Value = dateTimeValue;
        }
        else
        {
            throw new ArgumentException("Unsupported parameter type");
        }

        command.Parameters.Add(sqlParam);
    }
}
