#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <pthread.h>

#define MAX_URLS 1000
#define THREAD_POOL_SIZE 20

typedef struct {
    char urls[MAX_URLS][256];
    int url_count;
} URLList;

typedef struct {
    CURL *handle;
    FILE *output_file;
} DownloadThreadArgs;

URLList url_list;
pthread_t thread_pool[THREAD_POOL_SIZE];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int available_threads = THREAD_POOL_SIZE;

void* download_thread(void *arg) {
    DownloadThreadArgs *download_args = (DownloadThreadArgs *) arg;
    CURLcode res;

    while(1) {
        pthread_mutex_lock(&lock);
        if (available_threads == 0) {
            pthread_cond_wait(&cond, &lock);
        }

        if (url_list.url_count > 0) {
            strcpy(download_args->urls[0], url_list.urls[--url_list.url_count]);
            available_threads--;
            pthread_mutex_unlock(&lock);

            res = curl_easy_setopt(download_args->handle, CURLOPT_URL, download_args->urls[0]);
            if(res != CURLE_OK) {
                fprintf(stderr, "Failed to set URL: %s\n", curl_easy_strerror(res));
            }

            res = curl_easy_perform(download_args->handle);
            if(res != CURLE_OK) {
                fprintf(stderr, "Download failed for URL %s: %s\n", download_args->urls[0], curl_easy_strerror(res));
            }

            // Handle output and cleanup
        } else {
            pthread_mutex_unlock(&lock);
            break;
        }
    }

    pthread_exit(NULL);
}

int main(int argc, char **argv) {
    CURL *curl_handle;
    int concurrency_level = 5;

    if(argc > 1) {
        concurrency_level = atoi(argv[1]);
    }

    curl_global_init(CURL_GLOBAL_DEFAULT);

    for(int i=0; i<concurrency_level; i++) {
        DownloadThreadArgs *args = (DownloadThreadArgs *) malloc(sizeof(DownloadThreadArgs));
        args->handle = curl_easy_init();
        args->output_file = fopen("output.txt", "a");
        pthread_create(&thread_pool[i], NULL, download_thread, (void*) args);
    }

    // Populate url_list with URLs
    strcpy(url_list.urls[url_list.url_count++], "http://example.com");
    strcpy(url_list.urls[url_list.url_count++], "http://example.org");

    for(int i=0; i<concurrency_level; i++) {
        pthread_join(thread_pool[i], NULL);
    }

    curl_global_cleanup();
    return 0;
}
