```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

typedef struct SubNode {
    char *data;
    double value;
    struct SubNode *next;
} SubNode;

typedef struct Node {
    int value;
    SubNode *subList;
} Node;

void initRandom() {
    srand(time(0));
}

char* randomString(size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char *str = malloc(length + 1);
    if (str == NULL) {
        fprintf(stderr, "Memory allocation failed for string\n");
        exit(EXIT_FAILURE);
    }
    for(size_t i = 0; i < length; ++i) {
        str[i] = charset[rand() % sizeof(charset)];
    }
    str[length] = '\0';
    return str;
}

Node* createNode(int value, size_t subListSize) {
    Node *node = malloc(sizeof(Node));
    if (node == NULL) {
        fprintf(stderr, "Memory allocation failed for node\n");
        exit(EXIT_FAILURE);
    }
    node->value = value;

    // Initialize and populate linked list
    SubNode **subNodes = (SubNode **)malloc(subListSize * sizeof(SubNode *));
    if (subNodes == NULL) {
        fprintf(stderr, "Memory allocation failed for subNodes array\n");
        free(node);
        exit(EXIT_FAILURE);
    }
    node->subList = NULL;

    for(size_t i = 0; i < subListSize; ++i) {
        subNodes[i] = (SubNode *)malloc(sizeof(SubNode));
        if (subNodes[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for subNode\n");

            // Free already allocated subNodes
            for(size_t j = 0; j < i; ++j) {
                free(subNodes[j]->data);
                free(subNodes[j]);
            }
            free(subNodes);
            free(node);
            exit(EXIT_FAILURE);
        }

        subNodes[i]->data = randomString(rand() % 10 + 1); // Random string length between 1 and 10
        subNodes[i]->value = (double)rand() / RAND_MAX; // Random double value between 0.0 and 1.0

        // Link the new node to the previous one
        if (i == 0) {
            node->subList = subNodes[i];
        } else {
            subNodes[i - 1]->next = subNodes[i];
        }
    }
    subNodes[subListSize - 1]->next = NULL;

    free(subNodes); // Free the temporary array
    return node;
}

void destroyNode(Node *node) {
    SubNode *currentSubNode, *nextSubNode;
    currentSubNode = node->subList;

    while (currentSubNode != NULL) {
        nextSubNode = currentSubNode->next;
        free(currentSubNode->data);
        free(currentSubNode);
        currentSubNode = nextSubNode;
    }

    free(node);
}

void populateNodes(Node **nodes, size_t numNodes, int minValue, int maxValue) {
    for(size_t i = 0; i < numNodes; ++i) {
        nodes[i] = createNode(rand() % (maxValue - minValue + 1) + minValue, rand() % 5 + 1); // Random subList size between 1 and 5
    }
}

void serializeNodes(Node **nodes, size_t numNodes, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    // Write the number of nodes
    fwrite(&numNodes, sizeof(size_t), 1, file);

    for(size_t i = 0; i < numNodes; ++i) {
        Node *node = nodes[i];
        // Write node value
        fwrite(&node->value, sizeof(int), 1, file);

        SubNode *subNode = node->subList;
        size_t subListSize = 0;
        while (subNode != NULL) {
            subListSize++;
            subNode = subNode->next;
        }
        // Write the number of subNodes
        fwrite(&subListSize, sizeof(size_t), 1, file);

        subNode = node->subList;
        while (subNode != NULL) {
            // Write subNode data and value
            size_t dataSize = strlen(subNode->data) + 1;
            fwrite(&dataSize, sizeof(size_t), 1, file);
            fwrite(subNode->data, sizeof(char), dataSize, file);
            fwrite(&subNode->value, sizeof(double), 1, file);

            subNode = subNode->next;
        }
    }

    fclose(file);
}

int main() {
    initRandom();
    size_t numNodes = 5;
    Node **nodes = (Node **)malloc(numNodes * sizeof(Node *));

    populateNodes(nodes, numNodes, -100, 100);
    serializeNodes(nodes, numNodes, "nodes.dat");

    for(size_t i = 0; i < numNodes; ++i) {
        destroyNode(nodes[i]);
    }
    free(nodes);

    return 0;
}
```

This code provides a basic implementation of the task you described. It includes functions to create and populate `Node` structures, serialize them to a file, and clean up memory when done. The code also demonstrates error handling for memory allocation failures and ensures that all dynamically allocated memory is properly freed.

