import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.util.Iterator;

public class GameServerConnector {

    private static final long COOLDOWN_PERIOD = 9000; // 9 seconds
    private SocketChannel socketChannel;
    private Selector selector;
    private ByteBuffer buffer;
    private boolean isCooldown;
    private int lastAttackTime;

    public void connectToGameServer(String serverAddress, int port) throws IOException {
        selector = Selector.open();
        socketChannel = SocketChannel.open(new InetSocketAddress(serverAddress, port));
        socketChannel.configureBlocking(false);
        socketChannel.register(selector, SelectionKey.OP_CONNECT);

        while (true) {
            selector.select();
            Iterator<SelectionKey> keys = selector.selectedKeys().iterator();
            while (keys.hasNext()) {
                SelectionKey key = keys.next();

                if (!key.isValid()) {
                    continue;
                }

                if (key.isConnectable()) {
                    finishConnection(key);
                } else if (key.isWritable() && !isCooldown) {
                    handleAttack(key);
                }
            }
        }
    }

    private void finishConnection(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();
        if (!channel.finishConnect()) {
            return;
        }
        key.interestOps(SelectionKey.OP_WRITE);

        // Send initial connection message
        buffer = ByteBuffer.wrap("CONNECT".getBytes());
        channel.write(buffer);
    }

    private void handleAttack(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();

        if (lastAttackTime + COOLDOWN_PERIOD > System.currentTimeMillis()) {
            // Cooldown active, skip handling attack
            return;
        }

        int selectedAttack = getSelectedAttack(); // Implement logic to select an attack

        buffer = ByteBuffer.wrap(("ATTACK " + selectedAttack).getBytes());
        channel.write(buffer);

        lastAttackTime = (int) System.currentTimeMillis();
        isCooldown = true;

        new Thread(() -> {
            try {
                Thread.sleep(COOLDOWN_PERIOD);
            } catch (InterruptedException e) {
                // Handle interruption
            }
            isCooldown = false;
        }).start();

        logEvent("Selected attack: " + selectedAttack); // Implement logging method
    }

    private int getSelectedAttack() {
        // Implement logic to select an attack
        return 1; // Placeholder for actual selection logic
    }

    private void logEvent(String event) {
        // Implement logging to remote service
        System.out.println("Logging: " + event);
    }
}
