#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_CHUNK_SIZE 1024*1024*1024 // 1GB

void process_file(char *input_file, char *output_file, char *rules, int chunk_size) {
    FILE *in_fp = fopen(input_file, "rb");
    if (!in_fp) {
        fprintf(stderr, "Error opening input file: %s\n", input_file);
        return;
    }

    FILE *out_fp = fopen(output_file, "wb");
    if (!out_fp) {
        fclose(in_fp);
        fprintf(stderr, "Error opening output file: %s\n", output_file);
        return;
    }

    char *buffer = (char *)malloc(chunk_size);
    if (!buffer) {
        fclose(in_fp);
        fclose(out_fp);
