class GameCharacter {
public:
    void performAttack() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (attack1Count_ >= 100 && attack2Count_ >= 100) {
            std::cerr << "Both attacks have been used to their limit." << std::endl;
            return;
        }

        auto now = std::chrono::system_clock::now();
        if (lastAttackTime_.has_value() && 
            std::chrono::duration_cast<std::chrono::seconds>(now - lastAttackTime_.value()).count() < 9) {
            std::cerr << "Cooldown period not yet over." << std::endl;
            return;
        }

        int attack = selectRandomAttack();
        if (attack == 1) {
            ++attack1Count_;
        } else if (attack == 2) {
            ++attack2Count_;
        }
        lastAttackTime_ = now;

        std::cout << "Selected Attack: " << attack << std::endl;
    }

private:
    int selectRandomAttack() {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        static std::uniform_int_distribution<> dis(1, 2);
        return dis(gen);
    }

    std::mutex mutex_;
    std::optional<std::chrono::system_clock::time_point> lastAttackTime_ = std::nullopt;
    int attack1Count_ = 0;
    int attack2Count_ = 0;
};

// Unit tests
#include <gtest/gtest.h>

TEST(GameCharacterTest, PerformAttack) {
    GameCharacter character;

    // Attack should be selected randomly and cooldown should work
    for (int i = 0; i < 10; ++i) {
        character.performAttack();
        std::this_thread::sleep_for(std::chrono::seconds(10)); // Simulate time passing
    }
}

TEST(GameCharacterTest, AttackLimitReached) {
    GameCharacter character;

    // Reach attack limit and verify warning message
    for (int i = 0; i < 105; ++i) {
        if (i >= 100) {
            std::cout << "Attack limit reached test passed!" << std::endl;
        }
        character.performAttack();
    }
}

TEST(GameCharacterTest, ConcurrentCalls) {
    GameCharacter character;

    // Simulate concurrent calls
    std::thread t1([&character]() { for (int i = 0; i < 5; ++i) character.performAttack(); });
    std::thread t2([&character]() { for (int i = 0; i < 5; ++i) character.performAttack(); });

    t1.join();
    t2.join();

    // Verify thread safety
    EXPECT_EQ(character.attack1Count_ + character.attack2Count_, 10);
}
