const axios = require('axios');
const fs = require('fs');
const path = require('path');
const os = require('os');
const { promisify } = require('util');
const mkdirp = promisify(fs.mkdir);
const rimraf = promisify(fs.promises.rm);
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function uploadFile(url) {
    // Step 1: Check and set environment variable for the working directory
    const myDirPath = process.env.MY_DIR_PATH;
    let workingDir;

    if (myDirPath && fs.existsSync(myDirPath)) {
        workingDir = myDirPath;
    } else {
        workingDir = path.join(os.tmpdir(), 'my_dir');
        try {
            await mkdirp(workingDir);
        } catch (err) {
            console.error('Failed to create directory:', err.message);
            return null;
        }
        process.env.MY_DIR_PATH = workingDir;
    }

    // Step 2: Log actions with timestamps
    const log = (message) => console.log(`${new Date().toISOString()}: ${message}`);

    log(`Using directory: ${workingDir}`);

    // Step 3: Download the file and save it to the working directory
    try {
        const response = await axios.get(url, { responseType: 'stream' });
        const filePath = path.join(workingDir, path.basename(url));
        const writer = fs.createWriteStream(filePath);

        response.data.pipe(writer);
        await new Promise((resolve, reject) => {
            writer.on('finish', resolve);
            writer.on('error', reject);
        });

        log(`File uploaded to: ${filePath}`);

        // Step 4: Clean up the directory after 10 minutes
        setTimeout(async () => {
            try {
                await rimraf(workingDir, { recursive: true });
                log(`Directory cleaned up: ${workingDir}`);
            } catch (err) {
                console.error('Failed to clean up directory:', err.message);
            }
        }, 600000);

        // Step 5: Log cleanup attempts
        log('Cleanup attempt initiated');

        return filePath;
    } catch (error) {
        console.error('Failed to upload file:', error.message);
        return null;
    }
}

// Example usage:
uploadFile('https://example.com/file.txt').then((filePath) => {
    if (filePath) {
        console.log(`File uploaded successfully: ${filePath}`);
    } else {
        console.log('File upload failed');
    }
});
