```javascript
interface ElementMetadata {
    id: string;
    class: string;
    description: Promise<string>;
}

async function getMatchingElements(rootElement: HTMLElement, selector: string, filterFn: (element: ElementMetadata) => boolean): Promise<HTMLElement[]> {
    const matches = [];

    function traverse(element: HTMLElement) {
        if (!element) return;

        // Check if the element matches the selector
        if (element.matches(selector)) {
            const metadata: ElementMetadata = {
                id: element.id,
                class: element.className,
                description: fetchDescription(element)
            };

            if (filterFn(metadata)) {
                matches.push(element);
            }
        }

        // Recursively traverse child elements
        Array.from(element.children).forEach(child => traverse(child));
    }

    function fetchDescription(element: Element) {
        return new Promise<string>((resolve, reject) => {
            // Simulate asynchronous API call
            setTimeout(() => {
                const description = `Description for ${element.id}`;
                resolve(description);
            }, 100); // Simulated delay
        });
    }

    traverse(rootElement);
    return matches;
}
