using System;
using System.Data.SqlClient;
using Microsoft.AspNetCore.Identity;
using Microsoft.Extensions.Configuration;
using Azure.Storage.Blobs;
using Polly;
using Polly.Retry;

public class ManageDynamicWorkflows
{
    private readonly IConfiguration _configuration;
    private readonly UserManager<IdentityUser> _userManager;
    private readonly BlobServiceClient _blobServiceClient;

    public ManageDynamicWorkflows(IConfiguration configuration, UserManager<IdentityUser> userManager)
    {
        _configuration = configuration;
        _userManager = userManager;
        var connectionString = _configuration.GetConnectionString("DefaultConnection");
        _blobServiceClient = new BlobServiceClient(_configuration["AzureStorageConnectionString"]);
    }

    public void ExecuteModule(string moduleName)
    {
        var assemblyPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, $"{moduleName}.dll");
        var moduleAssembly = Assembly.LoadFrom(assemblyPath);
        var testTypes = moduleAssembly.GetTypes().Where(t => t.IsSubclassOf(typeof(NUnit.Framework.TestFixture)));

        foreach (var testType in testTypes)
        {
            var tests = testType.GetMethods().Where(m => m.GetCustomAttributes(typeof(NUnit.Framework.TestAttribute), false).Any());

            foreach (var test in tests)
            {
                LogTestStart(test.Name);
                try
                {
                    using (var transactionScope = new TransactionScope())
                    {
                        // Execute the test method
                        var instance = Activator.CreateInstance(testType);
                        test.Invoke(instance, null);

                        transactionScope.Complete();
                    }
                }
                catch (Exception ex)
                {
                    LogTestError(test.Name, ex.Message);
                }
                finally
                {
                    LogTestEnd(test.Name);
                }
            }
        }
    }

    public async Task UploadFileToBlobStorage(string filePath)
    {
        var blobContainerClient = _blobServiceClient.GetBlobContainerClient("testcontainer");
        await blobContainerClient.CreateIfNotExistsAsync();

        var retryPolicy = Policy
            .Handle<Exception>()
            .WaitAndRetryAsync(5, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));

        await retryPolicy.ExecuteAsync(async () =>
        {
            using (var fileStream = File.OpenRead(filePath))
            {
                var blobClient = blobContainerClient.GetBlobClient(Path.GetFileName(filePath));
                await blobClient.UploadAsync(fileStream);
            }
        });
    }

    public async Task ConfigureUserValidation()
    {
        _userManager.PasswordValidators.Add(new PasswordValidator<IdentityUser>
        {
            RequiredLength = 8,
            RequireNonAlphanumeric = true,
            RequireLowercase = true,
            RequireUppercase = true
        });

        _userManager.UserLockoutEnabledByDefault = true;
        _userManager.DefaultAccountLockoutTimeSpan = TimeSpan.FromMinutes(30);
    }

    public void EnsureEnvironmentSetup()
    {
        var envVariable = Environment.GetEnvironmentVariable("MY_ENV_VARIABLE");
        if (string.IsNullOrEmpty(envVariable))
        {
            var newDirectoryPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "new_directory");
            Directory.CreateDirectory(newDirectoryPath);
            Environment.SetEnvironmentVariable("MY_ENV_VARIABLE", newDirectoryPath);
        }
    }

    public void LogTestStart(string testName)
    {
        Console.WriteLine($"Starting test: {testName}");
    }

    public void LogTestEnd(string testName)
    {
        Console.WriteLine($"Ending test: {testName}");
    }

    public void LogTestError(string testName, string errorMessage)
    {
        Console.WriteLine($"Error in test {testName}: {errorMessage}");
    }
}
