#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_PERMITS 10
#define LOAD_CHECK_INTERVAL 5 // seconds

typedef struct {
    sem_t semaphore;
    int current_load;
    time_t last_check_time;
} SemaphoreManager;

void init_semaphore_manager(SemaphoreManager *manager, int initial_permits) {
    sem_init(&manager->semaphore, 0, initial_permits);
    manager->current_load = 0;
    manager->last_check_time = time(NULL);
}

void destroy_semaphore_manager(SemaphoreManager *manager) {
    sem_destroy(&manager->semaphore);
}

int acquire_semaphore(SemaphoreManager *manager) {
    int result = sem_wait(&manager->semaphore);
    if (result == -1) {
        perror("Semaphore wait failed");
        return -1;
    }
    manager->current_load++;
    return 0;
}

void release_semaphore(SemaphoreManager *manager) {
    sem_post(&manager->semaphore);
    manager->current_load--;
}

int adjust_permits(SemaphoreManager *manager) {
    time_t now = time(NULL);
    if (now - manager->last_check_time >= LOAD_CHECK_INTERVAL) {
        // Simulate load check with a random value
        int new_load = rand() % MAX_PERMITS + 1;
        printf("Current load: %d, Adjusting permits to %d\n", manager->current_load, new_load);
        sem_t temp_semaphore;
        sem_init(&temp_semaphore, 0, new_load);
        while (manager->current_load > new_load) {
            sem_wait(&manager->semaphore);
            manager->current_load--;
        }
        sem_destroy(&manager->semaphore);
        sem_init(&manager->semaphore, 0, new_load);
        manager->last_check_time = now;
    }
    return 0;
}

void *thread_task(void *arg) {
    SemaphoreManager *manager = (SemaphoreManager *)arg;

    for (int i = 0; i < 5; i++) {
        if (acquire_semaphore(manager) == -1) continue;
        printf("Thread %ld acquired semaphore\n", pthread_self());
        // Simulate work with a random delay
        usleep(rand() % 1000000);
        release_semaphore(manager);
        printf("Thread %ld released semaphore\n", pthread_self());

        adjust_permits(manager);

        usleep(rand() % 500000); // Sleep for a short duration before next task
    }

    return NULL;
}

int main() {
    srand(time(NULL));
    SemaphoreManager manager;
    init_semaphore_manager(&manager, MAX_PERMITS / 2);

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, thread_task, &manager);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    destroy_semaphore_manager(&manager);

    return 0;
}
