```csharp
using System;
using System.Security.Cryptography;
using BCrypt.Net;

public enum HashAlgorithmType { SHA256, Bcrypt }

public class PasswordManager
{
    private string _connectionString;

    public PasswordManager(string connectionString)
    {
        _connectionString = connectionString;
    }

    public string HashPassword(string plainTextPassword, HashAlgorithmType algorithmType = HashAlgorithmType.Bcrypt)
    {
        switch (algorithmType)
        {
            case HashAlgorithmType.SHA256:
                using (SHA256 sha256Hash = SHA256.Create())
                {
                    byte[] bytes = sha256Hash.ComputeHash(System.Text.Encoding.UTF8.GetBytes(plainTextPassword));
                    StringBuilder builder = new StringBuilder();
                    for (int i = 0; i < bytes.Length; i++)
                    {
                        builder.Append(bytes[i].ToString("x2"));
                    }
                    return builder.ToString();
                }
            case HashAlgorithmType.Bcrypt:
                return BCrypt.HashPassword(plainTextPassword);
            default:
                throw new ArgumentException("Unsupported hash algorithm type.");
        }
    }

    public bool VerifyHashedPassword(string plainTextPassword, string hashedPassword, HashAlgorithmType algorithmType = HashAlgorithmType.Bcrypt)
    {
        switch (algorithmType)
        {
            case HashAlgorithmType.SHA256:
                return HashPassword(plainTextPassword, algorithmType) == hashedPassword;
            case HashAlgorithmType.Bcrypt:
                return BCrypt.Verify(plainTextPassword, hashedPassword);
            default:
                throw new ArgumentException("Unsupported hash algorithm type.");
        }
    }

    public void StorePassword(string username, string plainTextPassword)
    {
        string salt = BCrypt.GenerateSalt();
        string hashedPassword = BCrypt.HashPassword(plainTextPassword, salt);

        using (var connection = new System.Data.SqlClient.SqlConnection(_connectionString))
        {
            connection.Open();
            using (var command = new System.Data.SqlClient.SqlCommand("INSERT INTO Users (Username, HashedPassword) VALUES (@Username, @HashedPassword)", connection))
            {
                command.Parameters.AddWithValue("@Username", username);
                command.Parameters.AddWithValue("@HashedPassword", hashedPassword);
                command.ExecuteNonQuery();
            }
        }
    }

    public bool VerifyUserPassword(string username, string plainTextPassword)
    {
        using (var connection = new System.Data.SqlClient.SqlConnection(_connectionString))
        {
            connection.Open();
            using (var command = new System.Data.SqlClient.SqlCommand("SELECT HashedPassword FROM Users WHERE Username = @Username", connection))
            {
                command.Parameters.AddWithValue("@Username", username);
                string hashedPasswordFromDb = (string)command.ExecuteScalar();

                if (hashedPasswordFromDb != null)
                {
                    return BCrypt.Verify(plainTextPassword, hashedPasswordFromDb);
                }
            }
        }

        return false;
    }

    public void UpdatePassword(string username, string newPlainTextPassword)
    {
        string salt = BCrypt.GenerateSalt();
        string newHashedPassword = BCrypt.HashPassword(newPlainTextPassword, salt);

        using (var connection = new System.Data.SqlClient.SqlConnection(_connectionString))
        {
            connection.Open();
            using (var command = new System.Data.SqlClient.SqlCommand("UPDATE Users SET HashedPassword = @NewHashedPassword WHERE Username = @Username", connection))
            {
                command.Parameters.AddWithValue("@Username", username);
                command.Parameters.AddWithValue("@NewHashedPassword", newHashedPassword);
                command.ExecuteNonQuery();
            }
        }
    }

    public void DeleteUser(string username)
