```java
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class DistributedCache {
    private Map<String, CacheEntry> cache;
    private AtomicInteger nodeCapacity;
    private int maxNodeCapacity;

    public DistributedCache(int initialCapacity) {
        this.cache = new ConcurrentHashMap<>();
        this.nodeCapacity = new AtomicInteger(initialCapacity);
        this.maxNodeCapacity = initialCapacity + (initialCapacity * 15 / 100);
    }

    public void set(String key, String value, int ttl) {
        if (key == null || value == null || ttl < 0) {
            throw new IllegalArgumentException("Invalid input parameters");
        }
        synchronized (cache) {
            while (cache.size() >= maxNodeCapacity) {
                try {
                    cache.wait();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
            CacheEntry entry = new CacheEntry(value, System.currentTimeMillis() + ttl);
            cache.put(key, entry);
            cache.notifyAll();
        }
    }

    public String get(String key) {
        if (key == null) {
            throw new IllegalArgumentException("Invalid input parameter");
        }
        synchronized (cache) {
            while (cache.size() > maxNodeCapacity * 90 / 100) {
                try {
                    cache.wait();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
            CacheEntry entry = cache.get(key);
            if (entry != null && System.currentTimeMillis() < entry.expiryTime) {
                return entry.value;
            } else {
                cache.remove(key);
                cache.notifyAll();
                return null;
            }
        }
    }

    public void evictExpiredEntries() {
        synchronized (cache) {
            for (String key : cache.keySet()) {
                CacheEntry entry = cache.get(key);
                if (System.currentTimeMillis() >= entry.expiryTime) {
                    cache.remove(key);
                }
            }
            cache.notifyAll();
        }
    }

    public int getCacheSize() {
        return cache.size();
    }

    private static class CacheEntry {
        String value;
        long expiryTime;

        CacheEntry(String value, long expiryTime) {
            this.value = value;
            this.expiryTime = expiryTime;
        }
    }
}
