```csharp
using System;
using System.Collections.Concurrent;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;

public class DynamicCloudStorageService
{
    private readonly string _authToken;
    private readonly HttpClient _httpClient;
    private readonly ConcurrentDictionary<string, UploadState> _uploadStates;

    public DynamicCloudStorageService(string authToken)
    {
        _authToken = authToken;
        _httpClient = new HttpClient();
        _uploadStates = new ConcurrentDictionary<string, UploadState>();
    }

    public async Task<UploadResult> UploadFileAsync(string filePath, string cloudPath)
    {
        if (string.IsNullOrEmpty(filePath) || string.IsNullOrEmpty(cloudPath))
            return new UploadResult { Success = false, ErrorMessage = "Invalid file path or cloud path" };

        var fileInfo = new FileInfo(filePath);
        if (!fileInfo.Exists)
            return new UploadResult { Success = false, ErrorMessage = "File not found" };

        using (var fileStream = fileInfo.OpenRead())
        {
            await UploadChunkAsync(fileStream, cloudPath, 0, await fileStream.Length);
        }

        return new UploadResult { Success = true };
    }

    public async Task<UploadResult> UploadBytesAsync(byte[] bytes, string cloudPath)
    {
        if (bytes == null || bytes.Length == 0)
            return new UploadResult { Success = false, ErrorMessage = "Invalid byte array" };

        await UploadChunkAsync(new MemoryStream(bytes), cloudPath, 0, bytes.Length);

        return new UploadResult { Success = true };
    }

    private async Task UploadChunkAsync(Stream fileStream, string cloudPath, long startByte, long length)
    {
        var chunkSize = GetChunkSize(length);
        if (startByte == length) return;

        using (var content = new ByteArrayContent(new byte[chunkSize]))
        {
            await fileStream.CopyToAsync(content.ReadAsStream(), chunkSize);

            var requestUri = $"https://cloudprovider.com/upload?path={Uri.EscapeDataString(cloudPath)}&offset={startByte}";
            var headers = _httpClient.DefaultRequestHeaders;
            headers.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", _authToken);
            headers.Add("Content-Length", chunkSize.ToString());

            using (var response = await _httpClient.PutAsync(requestUri, content))
            {
                if (!response.IsSuccessStatusCode)
                {
                    var errorMessage = await response.Content.ReadAsStringAsync();
                    throw new Exception($"Upload failed: {errorMessage}");
                }
            }

            _uploadStates.TryAdd(cloudPath, new UploadState { TotalBytes = length, UploadedBytes = startByte + chunkSize });
        }

        await UploadChunkAsync(fileStream, cloudPath, startByte + chunkSize, length);
    }

    private long GetChunkSize(long length)
    {
        // Implement dynamic chunking strategy based on file size and network conditions
        return Math.Min(1024 * 1024 * 5, length); // Example: Max chunk size of 5MB
    }
}

public class UploadResult
{
    public bool Success { get; set; }
    public string ErrorMessage { get; set; }
    public int ErrorCode { get; set; }
    public object Metadata { get; set; }
}

public class UploadState
{
    public long TotalBytes { get; set; }
    public long UploadedBytes { get; set; }
}
