    private readonly IDeserializationStrategy _strategy;
    private readonly IConfigService _configService;
    private readonly ILockService _lockService;
    private readonly ICachingService _cachingService;
    public DeserializationService(IDeserializationStrategy strategy, IConfigService configService, ILockService lockService, ICachingService cachingService)
    {
        _strategy = strategy;
        _configService = configService;
        _lockService = lockService;
        _cachingService = cachingService;
    }
    public object DeserializeData(byte[] data)
    {
        var fileType = GetFileType(data);
        var version = GetVersion(data);
        var cacheKey = $"{fileType}_{version}";
        if (_cachingService.IsCached(cacheKey))
        {
            return _cachingService.Get(cacheKey);
        }
        lock (_lockService.GetLock(cacheKey))
        {
            if (!_cachingService.IsCached(cacheKey))
            {
                var result = _strategy.Deserialize(data);
                _cachingService.Set(cacheKey, result);
                return result;
            }
        }
    }
