#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>
#include <pthread.h>

typedef struct {
    sem_t *sem;
    int permits;
} SemaphoreManager;

SemaphoreManager* create_semaphore_manager(int initial_permits) {
    SemaphoreManager *manager = (SemaphoreManager *)malloc(sizeof(SemaphoreManager));
    manager->sem = sem_open("/my_semaphore", O_CREAT, 0644, initial_permits);
    if (manager->sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        free(manager);
        return NULL;
    }
    manager->permits = initial_permits;
    return manager;
}

int destroy_semaphore_manager(SemaphoreManager *manager) {
    if (sem_close(manager->sem) != 0) {
        perror("Failed to close semaphore");
        return -1;
    }
    sem_unlink("/my_semaphore");
    free(manager);
    return 0;
}

void acquire SemaphoreManager *manager) {
    while(sem_wait(manager->sem) == -1 && errno == EAGAIN) {
        // Handle timeout or retry logic here
        printf("Semaphore unavailable, retrying...\n");
        sleep(1); // Sleep for a while before retrying
    }
}

void release_semaphore(SemaphoreManager *manager) {
    sem_post(manager->sem);
}

int main() {
    SemaphoreManager *manager = create_semaphore_manager(5);
    if (manager == NULL) {
        return 1;
    }

    pthread_t thread_ids[10];
    for (int i = 0; i < 10; ++i) {
        if (pthread_create(&thread_ids[i], NULL, thread_function, manager) != 0) {
            perror("Failed to create thread");
            destroy_semaphore_manager(manager);
            return 1;
        }
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(thread_ids[i], NULL);
    }

    destroy_semaphore_manager(manager);
    return 0;
}

void *thread_function(void *arg) {
    SemaphoreManager *manager = (SemaphoreManager *)arg;
    acquire semaphore manager;
    // Perform operations on the shared resource
    release_semaphore(manager);
    return NULL;
}
```

