#include <iostream>
#include <forward_list>
#include <fstream>
#include <sstream>

void insert_after_position(std::forward_list<std::string>& list, const std::string& search_str, const std::string& insert_str, int position = -1) {
    auto it = list.begin();
    int count = 0;

    // Search for the first occurrence of search_str
    while (it != list.end() && *it != search_str) {
        ++it;
        ++count;
    }

    if (it == list.end()) {
        // If not found, insert at the end or according to position index if specified
        if (position == -1 || count >= position) {
            list.push_front(insert_str);
        } else {
            std::cerr << "Error: Position index out of bounds." << std::endl;
        }
    } else {
        // Insert after the first occurrence of search_str
        ++it; // Move to the next element
        if (position == -1 || count + 1 >= position) {
            list.insert_after(it, insert_str);
        } else {
            std::cerr << "Error: Position index out of bounds." << std::endl;
        }
    }
}

void read_and_insert_from_file(std::forward_list<std::string>& list, const std::string& filename) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Error: Unable to open file." << std::endl;
        return;
    }

    std::string line;
    while (std::getline(file, line)) {
        std::istringstream iss(line);
        std::string search_str, insert_str;
        int position = -1;

        if (!(iss >> search_str >> insert_str)) {
            std::cerr << "Error: Invalid line format in file." << std::endl;
            continue;
        }

        if (iss >> position && position < 0) {
            std::cerr << "Error: Position index must be non-negative or -1." << std::endl;
            continue;
        }

        insert_after_position(list, search_str, insert_str, position);
    }

    file.close();
}

int main() {
    std::forward_list<std::string> list = {"apple", "banana", "cherry", "date"};

    // Example usage
    insert_after_position(list, "cherry", "orange", 2); // Inserts "orange" after "cherry" at position 2
    insert_after_position(list, "fig", "grape"); // Inserts "grape" at the end of the list since "fig" is not found

    // Read from file and insert
    read_and_insert_from_file(list, "insertions.txt");

    for (const auto& item : list) {
        std::cout << item << std::endl;
    }

    return 0;
}
```

This code snippet includes the function `insert_after_position` that inserts a string after the first occurrence of another string in a forward list based on an optional position index. It also handles errors and edge cases such as out-of-bounds positions and invalid inputs. The `read_and_insert_from_file` function reads string pairs from a text file and uses them to insert into the list. The `main` function demonstrates how to use these functions with example usage and reading from a file.

