using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Net;
using System.Threading.Tasks;

namespace RandomNumberGenerator
{
    public class Program : IDisposable
    {
        private static Random rnd = new Random();

        public Program()
        {
            // Constructor logic here
        }

        ~Program()
        {
            Dispose(false);
        }

        protected virtual void Dispose(bool disposing)
        {
            if (disposing)
            {
                // Cleanup code here
            }
        }

        public void Main(string[] args)
        {
            if (args.Length == 0)
            {
                Console.WriteLine("Please provide one or more file paths as arguments.");
                return;
            }

            List<int> allNumbers = new List<int>();

            foreach (string filePath in args)
            {
                try
                {
                    List<int> numbers = ReadNumbersFromFile(filePath);
                    if (numbers != null && numbers.Count > 0)
                    {
                        allNumbers.AddRange(numbers);
                    }
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error processing file {filePath}: {ex.Message}");
                }
            }

            if (allNumbers.Count == 0)
            {
                Console.WriteLine("No valid files found.");
                return;
            }

            int maxNumber = allNumbers.Max();
            double average = allNumbers.Average();

            Console.WriteLine($"Max Number: {maxNumber}");
            Console.WriteLine($"Average: {average}");

            Dispose();
        }

        private List<int> ReadNumbersFromFile(string filePath)
        {
            if (!Directory.Exists(Path.GetDirectoryName(filePath)))
            {
                Console.WriteLine($"Error: Directory {Path.GetDirectoryName(filePath)} does not exist.");
                return null;
            }

            string webConfigPath = Path.Combine(Path.GetDirectoryName(filePath), "web.config");
            if (!File.Exists(webConfigPath))
            {
                Console.WriteLine("Error: web.config file is missing.");
                return null;
            }

            List<int> numbers = new List<int>();

            try
            {
                using (StreamReader reader = new StreamReader(filePath))
                {
                    string line;
                    while ((line = reader.ReadLine()) != null)
                    {
                        if (int.TryParse(line, out int number))
                        {
                            numbers.Add(number);
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error reading file {filePath}: {ex.Message}");
                return null;
            }

            return numbers;
        }
    }
}
