class SecureTokenManager {
    private $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    private $hashAlgorithm = PASSWORD_BCRYPT;
    private $saltLength = 22;

    public function generateSecureString($length) {
        if ($length <= 0) {
            throw new InvalidArgumentException('Length must be greater than 0');
        }

        return substr(str_shuffle(str_repeat($this->charset, ceil($length / strlen($this->charset)))), 1, $length);
    }

    public function hashPassword($password, $salt = null) {
        if (is_null($salt)) {
            $salt = $this->generateSecureString($this->saltLength);
        }

        return password_hash($password . $salt, $this->hashAlgorithm);
    }

    public function verifyPassword($password, $hashedPassword, $salt) {
        return password_verify($password . $salt, $hashedPassword);
    }

