fn compile_files_with_custom_logging(file_paths: &[PathBuf], max_concurrent_compilations: usize) -> Vec<CompilationResult> {
    let ice_hook = SyncLazy::new(|| install_ice_hook());

    file_paths.par_chunks(max_concurrent_compilations).map(|chunk| {
        chunk.iter().map(|file_path| {
            let compile_time_start = Instant::now();
            let resident_set_size_before = get_resident_set_size();

            let mut errors = None;
            catch_with_exit_code(|| {
                // Simulate compilation process
                if file_path.exists() && file_path.is_file() {
                    // Simulate compilation logic here
                } else {
                    early_error(0, &format!("File not found: {}", file_path.display()));
                }
            }).map_err(|e| e.to_string()).ok();

            let compile_time = compile_time_start.elapsed().as_millis();
            let resident_set_size_after = get_resident_set_size();

            CompilationResult {
                file_path: file_path.to_string_lossy().to_string(),
                compile_time_ms: compile_time,
                resident_set_size_before_kb: resident_set_size_before.map(|size| size / 1024),
                resident_set_size_after_kb: resident_set_size_after.map(|size| size / 1024),
                errors,
