<?php
class SecureSessionManager {
    private $db;
    private $tokenCharset;

    public function __construct($db, $tokenCharset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') {
        $this->db = $db;
        $this->tokenCharset = $tokenCharset;
    }

    public function generateToken($length = 32) {
        $token = '';
        for ($i = 0; $i < $length; $i++) {
            $randomIndex = random_int(0, strlen($this->tokenCharset) - 1);
            $token .= $this->tokenCharset[$randomIndex];
        }
        return $token;
    }

    public function startSession($userId, $token) {
        try {
            $sessionData = [
                'user_id' => $userId,
                'token' => password_hash($token, PASSWORD_BCRYPT),
                'last_activity' => time()
            ];
            $this->db->insertOne('sessions', ['_id' => new MongoDB\BSON\ObjectId(), 'data' => $sessionData]);
        } catch (MongoDB\Exception\Exception $e) {
            // Handle database exception
        }
    }

    public function validateSession($token) {
        try {
            $result = $this->db->findOne('sessions', ['data.token' => ['$eq' => password_hash($token, PASSWORD_BCRYPT)]]);
            if ($result && time() - $result['data']['last_activity'] < 3600) { // Session expires after 1 hour
                return $result['data']['user_id'];
            }
        } catch (MongoDB\Exception\Exception $e) {
            // Handle database exception
        }
        return false;
    }

    public function updateSessionActivity($token) {
        try {
            $this->db->updateOne('sessions', ['data.token' => ['$eq' => password_hash($token, PASSWORD_BCRYPT)]], ['$set' => ['data.last_activity' => time()]]);
        } catch (MongoDB\Exception\Exception $e) {
            // Handle database exception
        }
    }

    public function destroySession($token) {
        try {
            $this->db->deleteOne('sessions', ['data.token' => ['$eq' => password_hash($token, PASSWORD_BCRYPT)]]);
        } catch (MongoDB\Exception\Exception $e) {
            // Handle database exception
        }
    }
}
