import subprocess
import time

def create_namespace(namespace_name, parent_namespace=None):
    lock_file = f"{namespace_name}.lock"
    while True:
        try:
            with open(lock_file, 'x'):
                break
        except FileExistsError:
            time.sleep(1)

    if not namespace_exists(namespace_name):
        retries = 5
        for _ in range(retries):
            try:
                subprocess.run(["kubectl", "create", "namespace", namespace_name], check=True)
                break
            except subprocess.CalledProcessError as e:
                print(f"Namespace creation failed: {e}")
                time.sleep(2)
        else:
            raise Exception("Failed to create namespace after retries")
    finally:
        import os
        os.remove(lock_file)

def namespace_exists(namespace_name):
    try:
        subprocess.run(["kubectl", "get", "namespace", namespace_name], check=True, stdout=subprocess.PIPE)
        return True
    except subprocess.CalledProcessError:
        return False

