```javascript
// Cache to store previously fetched scripts
const scriptCache = new Map();

// Function to fetch scripts from an external API
async function fetchScripts() {
    try {
        const response = await fetch('/api/scripts');
        if (!response.ok) throw new Error('Network response was not ok');
        return response.json();
    } catch (error) {
        console.error('Failed to fetch scripts:', error);
        return [];
    }
}

// Function to render scripts as HTML
function renderScripts(scripts) {
    const scriptHtml = scripts.map(script => 
        `<script type="${script.type || 'text/javascript'}">${script.code}</script>`
    ).join('');
    document.body.insertAdjacentHTML('beforeend', scriptHtml);
}

// Main function to handle fetching and rendering scripts
async function renderFooterScripts() {
    let cachedScripts = Array.from(scriptCache.values());

    if (cachedScripts.length === 0) {
        const fetchedScripts = await fetchScripts();
        scriptCache.clear();
        cachedScripts = fetchedScripts;

        // Cache the newly fetched scripts
        for (const script of fetchedScripts) {
            scriptCache.set(script.id, script);
        }
    }

    renderScripts(cachedScripts);
}

// Example usage: Call this function to render scripts at any point in your application
renderFooterScripts();
```

