```python
from flask import Flask, request, jsonify
from functools import wraps
import time
import uuid

app = Flask(__name__)

# In-memory cache for resources
cache = {}

# Mock database
database = {}

def cache_resource(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        key = args[0]
        if key not in cache:
            resource = func(*args, **kwargs)
            cache[key] = (resource, time.time(), uuid.uuid4())
        return cache[key][0], cache[key][1], cache[key][2]
    return wrapper

def check_version_and_timestamp(key):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            version = request.headers.get('If-Match')
            timestamp = request.headers.get('If-Unmodified-Since')

            if version and version != cache[key][2]:
                return jsonify({'error': 'Precondition Failed'}), 412
            if timestamp:
                last_modified = time.strftime('%a, %d %b %Y %H:%M:%S GMT', time.localtime(cache[key][1]))
                if last_modified < timestamp:
                    return jsonify({'error': 'Conflict'}), 409

            return func(*args, **kwargs)
        return wrapper
    return decorator

@app.route('/resource/<key>', methods=['PUT'])
@cache_resource
@check_version_and_timestamp('key')
def update_resource(key):
    data = request.json
    cache[key] = (data, time.time(), cache[key][2])
    return jsonify({'message': 'Resource updated successfully'}), 200

@app.route('/resource/<key>', methods=['DELETE'])
@cache_resource
@check_version_and_timestamp('key')
def delete_resource(key):
    del cache[key]
    return jsonify({'message': 'Resource deleted successfully'}), 204

if __name__ == '__main__':
    app.run(debug=True)
