# Redis setup for caching and rate limiting
cache = redis.Redis(host='localhost', port=6379, db=0)
rate_limiter_key = 'order_update_rate_limit'
rate_limit_duration = 60  # in seconds
max_requests_per_minute = 10

def rate_limited(max_calls=1, per=5):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            current_time = time()
            last_call_time = cache.get(rate_limiter_key + func.__name__)

            if last_call_time:
                elapsed_time = current_time - float(last_call_time)
                if elapsed_time < per:
                    return "Rate limit exceeded. Please try again later."

            result = func(*args, **kwargs)
            cache.setex(rate_limiter_key + func.__name__, per, current_time)
            return result
        return wrapper
    return decorator

