```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

// Define semaphore structure
typedef struct {
    sem_t *sem;
    int permits;
} SemaphoreManager;

// Function to create a new semaphore manager
SemaphoreManager* create_semaphore_manager(int initial_permits) {
    SemaphoreManager *manager = (SemaphoreManager*)malloc(sizeof(SemaphoreManager));
    if (!manager) return NULL;

    manager->permits = initial_permits;
    manager->sem = sem_open("/shared_semaphore", O_CREAT, 0644, initial_permits);
    if (manager->sem == SEM_FAILED) {
        free(manager);
        return NULL;
    }
    return manager;
}

// Function to destroy a semaphore manager
void destroy_semaphore_manager(SemaphoreManager *manager) {
    if (!manager) return;
    sem_close(manager->sem);
    sem_unlink("/shared_semaphore");
    free(manager);
}

// Function to acquire permits from the semaphore
int acquire_permits(SemaphoreManager *manager, int n) {
    if (!manager || manager->sem == SEM_FAILED) return -1;
    return sem_wait(manager->sem);
}

// Function to release permits back to the semaphore
int release_permits(SemaphoreManager *manager, int n) {
    if (!manager || manager->sem == SEM_FAILED) return -1;
    return sem_post(manager->sem);
}

// Main function for demonstration
int main() {
    SemaphoreManager *manager = create_semaphore_manager(5);
    if (!manager) {
        printf("Failed to create semaphore manager\n");
        return 1;
    }

    // Example usage of the semaphore manager
    acquire_permits(manager, 2);
    printf("Acquired 2 permits\n");

    release_permits(manager, 1);
    printf("Released 1 permit\n");

    destroy_semaphore_manager(manager);
    printf("Destroyed semaphore manager\n");

    return 0;
}
```

