class ClinicManager {
    private $db;
    private static $factoryRegistry = [];

    public function __construct($db) {
        $this->db = $db;
    }

    public static function addFactoryFunction($id, callable $function) {
        self::$factoryRegistry[$id] = $function;
    }

    public static function createInstance($id, ...$args) {
        if (isset(self::$factoryRegistry[$id])) {
            return call_user_func_array(self::$factoryRegistry[$id], $args);
        }
        throw new Exception("Factory function for ID {$id} not found.");
    }

    private function validateClinicId($clinicId) {
        // Validation logic here
        if (!is_numeric($clinicId)) {
            throw new Exception("Invalid clinic ID.");
        }
    }

    public function updateClinicStatus($clinicId, $status = null, $ipAddress = null) {
        $this->validateClinicId($clinicId);

        // Transaction handling logic here
        try {
            $stmt = $this->db->prepare("BEGIN;");
            $this->db->beginTransaction();

            if ($status !== null) {
                $stmt = $this->db->prepare("UPDATE clinics SET status = :status, last_modified_ip = :ipAddress, last_modified_date = NOW() WHERE id = :clinicId");
                $stmt->execute([':status' => $status, ':ipAddress' => $ipAddress, ':clinicId' => $clinicId]);
            }

            // Other updates can be added here

            $this->db->commit();
        } catch (Exception $e) {
            $this->db->rollBack();
            throw new Exception("Database error: " . $e->getMessage());
        }

        // Logging logic here
    }

    public function clinicToJson($clinicData) {
        return json_encode($clinicData);
    }

    public static function fromJson($jsonString) {
        $data = json_decode($jsonString, true);
        return self::createInstance($data['id'], $data);
    }
}

