async function uploadFileFromUrl(url, bucketName, userId) {
  try {
    // Validate user authentication
    if (!isAuthenticated(userId)) {
      return { error: 'User is not authenticated' };
    }

    // Log start of file upload
    console.log(`Starting file upload from ${url}`);

    // Fetch the file from the URL
    const response = await axios.get(url, { responseType: 'stream' });
    const contentType = response.headers['content-type'];
    const fileName = url.split('/').pop();

    // Validate file type
    if (!isFileTypeSupported(fileName)) {
      return { error: 'Unsupported file type' };
    }

    // Check cache for previously uploaded file metadata
    const cachedFileMetadata = getCachedFileMetadata(bucketName, fileName);
    if (cachedFileMetadata) {
      console.log('Using cached file metadata');
      return { publicUrl: cachedFileMetadata.publicUrl };
    }

    // Prepare the upload parameters
    const params = {
      Bucket: bucketName,
      Key: fileName,
      Body: response.data,
      ContentType: contentType,
      ACL: 'public-read'
    };

    // Upload the file with resumable support and exponential backoff
    let retries = 3;
    while (retries > 0) {
      try {
        const data = await s3.upload(params).promise();
        console.log('File uploaded successfully', data.Location);
        storeCache(bucketName, fileName, { publicUrl: data.Location });
        return { publicUrl: data.Location };
      } catch (error) {
        if (retries === 1) {
          console.error('File upload failed after retries', error);
          return { error: 'File upload failed' };
        }
        retries--;
        const backoff = Math.pow(2, retries) * 1000;
        await new Promise(resolve => setTimeout(resolve, backoff));
      }
    }
  } catch (error) {
    console.error('Error during file upload', error);
    return { error: 'Error during file upload' };
  }
}

