```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Function to perform encryption on a single file using OpenSSL library
void encrypt_file(const char *input_path, const char *output_path, const EVP_CIPHER *cipher, const unsigned char *key, const unsigned char *iv) {
    FILE *in = fopen(input_path, "rb");
    if (!in) {
        perror("Error opening input file");
        return;
    }

    FILE *out = fopen(output_path, "wb");
    if (!out) {
        perror("Error opening output file");
        fclose(in);
        return;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        fclose(in);
        fclose(out);
        return;
    }

    if (1 != EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv)) {
        fprintf(stderr, "Error initializing encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        fclose(in);
        fclose(out);
        return;
    }

    unsigned char inbuf[1024];
    unsigned char outbuf[1024 + EVP_CIPHER_BLOCK_SIZE];
    int len, written;

    while ((len = fread(inbuf, 1, sizeof(inbuf), in)) > 0) {
        if (1 != EVP_EncryptUpdate(ctx, outbuf, &len, inbuf, len)) {
            fprintf(stderr, "Error encrypting data\n");
            break;
        }
        written = fwrite(outbuf, 1, len, out);
        if (written != len) {
            fprintf(stderr, "Error writing encrypted data to output file\n");
            break;
        }
    }

    int final_len;
    if (1 != EVP_EncryptFinal_ex(ctx, outbuf, &final_len)) {
        fprintf(stderr, "Error finalizing encryption\n");
    } else {
        written = fwrite(outbuf, 1, final_len, out);
        if (written != final_len) {
            fprintf(stderr, "Error writing final encrypted data to output file\n");
        }
    }

    EVP_CIPHER_CTX_free(ctx);
    fclose(in);
    fclose(out);
}

// Function to handle progress and log all actions
void progress_callback(int percent_done) {
    printf("Progress: %d%%\n", percent_done);
}

// Main function to process a list of file paths for encryption
int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <output_file> <input_files...>\n", argv[0]);
        return 1;
    }

    const char *output_file = argv[1];
    int num_files = argc - 2;

    // Example encryption parameters
    EVP_CIPHER *cipher = EVP_aes_256_cbc();
    unsigned char key[32], iv[16];

    if (!RAND_bytes(key, sizeof(key)) || !RAND_bytes(iv, sizeof(iv))) {
        fprintf(stderr, "Error generating random bytes for key and IV\n");
        return 1;
    }

    FILE *log_file = fopen("encryption_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        return 1;
    }

    clock_t start_time = clock();
    int exit_codes[num_files];

    for (int i = 0; i < num_files; ++i) {
        char *input_path = argv[i + 2];
        char output_path[1024];
        snprintf(output_path, sizeof(output_path), "%s_encrypted", input_path);

        printf("Encrypting file: %s\n", input_path);
        encrypt_file(input_path, output_path, cipher, key, iv);

        FILE *in = fopen(output_path, "rb");
        if (!in) {
            fprintf(stderr, "Error opening encrypted file for logging\n");
            fclose(log_file);
            return 1;
        }

        fseek(in, 0L, SEEK_END);
        long file_size = ftell(in);
        fclose(in);

        time_t encryption_time = clock() - start_time;
        double time_taken = (double)encryption_time / CLOCKS_PER_SEC;

        fprintf(log_file, "File: %s, Exit Code: 0, Encryption Time: %.2f seconds, File Size: %ld bytes\n", output_path, time_taken, file_size);
        exit_codes[i] = 0;
    }

    fclose(log_file);

    printf("Encryption completed.\n");

    return 0;
}
