using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using log4net;

public class SqlExecutor
{
    private static readonly ILog _log = LogManager.GetLogger(typeof(SqlExecutor));

    public static IDataReader ExecuteSqlQuery(string connectionString, string sqlCommandTemplate, List<object> parameters, int timeout = 30, bool useBatchProcessing = false, int retryCount = 3)
    {
        if (string.IsNullOrEmpty(connectionString))
            throw new ArgumentException("Connection string cannot be null or empty.", nameof(connectionString));
        if (string.IsNullOrEmpty(sqlCommandTemplate))
            throw new ArgumentException("SQL command template cannot be null or empty.", nameof(sqlCommandTemplate));
        if (parameters == null || parameters.Count == 0)
            throw new ArgumentException("Parameters list cannot be null or empty.", nameof(parameters));

        for (int attempt = 0; attempt <= retryCount; attempt++)
        {
            try
            {
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();

                    if (useBatchProcessing)
                    {
                        // Implement batch processing logic here
                    }

                    var command = new SqlCommand(sqlCommandTemplate, connection);
                    foreach (var param in parameters)
                    {
                        command.Parameters.AddWithValue("@", param); // Ensure parameter names are unique
                    }
                    command.CommandTimeout = timeout;

                    return command.ExecuteReader(CommandBehavior.CloseConnection);
                }
            }
            catch (SqlException ex) when (ex.Number == -2 || attempt < retryCount) // Timeout or transient error
            {
                _log.Error($"SQL query execution failed. Attempt {attempt + 1} of {retryCount + 1}. Error: {ex.Message}");
            }
            catch (Exception ex)
            {
                _log.Fatal($"Critical SQL query execution failure. Error: {ex.Message}");
                throw;
            }
        }

        throw new InvalidOperationException("Failed to execute SQL query after multiple attempts.");
    }
}
