using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using System.Xml.XPath;

public class XmlParser
{
    private readonly HttpClient _httpClient;
    private readonly Dictionary<string, XPathDocument> _cache;
    private readonly string _schemaUrl;

    public XmlParser(string schemaUrl)
    {
        _httpClient = new HttpClient();
        _cache = new Dictionary<string, XPathDocument>();
        _schemaUrl = schemaUrl;
    }

    public async Task<XPathNavigator> GetElementAsync(string xpathQuery, string apiEndpoint)
    {
        var xmlDoc = await FetchAndValidateXmlAsync(apiEndpoint);
        return xmlDoc.SelectSingleNode(xpathQuery) as XPathNavigator;
    }

    private async Task<XPathDocument> FetchAndValidateXmlAsync(string apiEndpoint)
    {
        if (_cache.TryGetValue(apiEndpoint, out var xmlDoc))
        {
            return xmlDoc;
        }

        try
        {
            var xmlContent = await _httpClient.GetStringAsync(apiEndpoint);
            xmlDoc = new XPathDocument(new System.IO.StringReader(xmlContent));
            ValidateXmlSchema(xmlDoc);

            lock (_cache)
            {
                if (!_cache.ContainsKey(apiEndpoint) || _cache[apiEndpoint] != xmlDoc)
                {
                    _cache[apiEndpoint] = xmlDoc;
                }
            }

            return xmlDoc;
        }
        catch (HttpRequestException ex)
        {
            LogError($"Failed to fetch XML from {apiEndpoint}: {ex.Message}");
            throw new InvalidOperationException("Failed to fetch and validate XML.");
        }
    }

    private void ValidateXmlSchema(XPathDocument xmlDoc)
    {
        var schema = XPathDocument.Load(_schemaUrl);
        if (!xmlDoc.DocumentElement.SchemaInfo.Validity == XmlValidity.Valid)
        {
            LogError($"XML does not conform to the provided schema: {xmlDoc.DocumentElement.SchemaInfo.Error}");
            throw new InvalidOperationException("Invalid XML schema.");
        }
    }

    private void LogError(string message)
    {
        // Implement logging mechanism here
    }
}
