#include <iostream>
#include <vector>
#include <string>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include "rapidjson/document.h"
#include "rapidjson/writer.h"
#include "rapidjson/stringbuffer.h"
#include "sql_connection_pool.h"

struct Node {
    int key;
    std::string value;
};

class DynamicNodeArray {
private:
    std::vector<Node> nodes;
    size_t threshold;
    std::mutex mutex;
    std::condition_variable cv;

public:
    DynamicNodeArray(size_t initial_size, size_t resize_threshold)
        : nodes(initial_size), threshold(resize_threshold) {}

    void addNode(const Node& node) {
        std::unique_lock<std::mutex> lock(mutex);
        if (nodes.size() >= threshold) {
            cv.wait(lock, [this] { return nodes.size() < threshold; });
        }
        nodes.push_back(node);
    }

    // Add other methods as needed
};

void serializeNodes(const DynamicNodeArray& array, std::string& json_str) {
    rapidjson::Document doc;
    doc.SetObject();
    rapidjson::Document::AllocatorType& allocator = doc.GetAllocator();

    for (const auto& node : array.nodes) {
        rapidjson::Value item(rapidjson::kObjectType);
        item.AddMember("key", node.key, allocator);
        item.AddMember("value", rapidjson::StringBuffer(node.value.c_str()), allocator);
        doc.PushBack(item, allocator);
    }

    rapidjson::StringBuffer buffer;
    rapidjson::Writer<rapidjson::StringBuffer> writer(buffer);
    doc.Accept(writer);

    json_str = buffer.GetString();
}

void deserializeNodes(const std::string& json_str, DynamicNodeArray& array) {
    rapidjson::Document doc;
    doc.Parse(json_str.c_str());

    if (doc.IsArray()) {
        for (const auto& item : doc.GetArray()) {
            Node node;
            node.key = item["key"].GetInt();
            node.value = item["value"].GetString();
            array.addNode(node);
        }
    }
}

// Add other functions as needed
