using json = nlohmann::json;

class JSONParser {
public:
    static std::shared_ptr<JSONParser> fromString(const std::string& jsonString) {
        return std::make_shared<JSONParser>(json::parse(jsonString));
    }

    std::string toString() const {
        return obj.dump();
    }

private:
    json obj;

    JSONParser(const json& jsonObj) : obj(jsonObj) {}
};

class FactoryRegistry {
public:
    using FactoryFunc = std::function<std::shared_ptr<JSONParser>(const std::string&)>;
    void addFactory(int id, const FactoryFunc& factory) {
        factories[id] = factory;
    }

    std::shared_ptr<JSONParser> createInstance(int id, const std::string& jsonStr) {
        if (factories.find(id) != factories.end()) {
            return factories[id](jsonStr);
        }
        throw std::runtime_error("Factory not found for ID: " + std::to_string(id));
    }

private:
    std::unordered_map<int, FactoryFunc> factories;
};

class WebApplication {
public:
    void addFactory(int id, const FactoryRegistry::FactoryFunc& factory) {
        registry.addFactory(id, factory);
    }

    void loadFiles(const std::vector<std::string>& fileNames) {
        std::mutex mtx;
        std::condition_variable cv;
        bool allLoaded = false;

        auto worker = [&]() {
            for (const auto& fileName : fileNames) {
                try {
                    std::ifstream file(fileName);
                    std::stringstream buffer;
                    buffer << file.rdbuf();
                    std::string content = buffer.str();

                    // Simulate asynchronous loading
                    std::this_thread::sleep_for(std::chrono::milliseconds(100));
                    loadFileContent(fileName, content);
                } catch (const std::exception& e) {
                    std::cerr << "Error loading file: " << fileName << " - " << e.what() << std::endl;
                }
            }

            {
                std::lock_guard<std::mutex> lock(mtx);
                allLoaded = true;
            }
            cv.notify_all();
        };

        std::thread t(worker);

        {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [&]() { return allLoaded; });
        }

        t.join();

        checkCircularDependencies();
    }

    void executeFiles(const std::vector<int>& ids) {
        for (const auto& id : ids) {
            try {
                auto instance = registry.createInstance(id, "{}");
                std::cout << "Executing JSON with ID: " << id << std::endl;
                // Simulate execution
                std::this_thread::sleep_for(std::chrono::milliseconds(50));
            } catch (const std::exception& e) {
                std::cerr << "Error executing file with ID: " << id << " - " << e.what() << std::endl;
            }
        }
    }

private:
    FactoryRegistry registry;

    void loadFileContent(const std::string& fileName, const std::string& content) {
        // Process and cache the content
        std::cout << "Loaded file: " << fileName << std::endl;
    }

    void checkCircularDependencies() {
        // Logic to detect and handle circular dependencies
    }
};

int main() {
    WebApplication app;

    // Example factories
    app.addFactory(1, [](const std::string& jsonStr) {
        return JSONParser::fromString(jsonStr);
    });

    // Load files asynchronously
    app.loadFiles({"file1.json", "file2.json"});

    // Execute loaded instances
    app.executeFiles({1, 2});

    return 0;
}
```

