# Mock user database for demonstration purposes
user_db = {
    "1": {"name": "John Doe", "role": "admin"},
    "2": {"name": "Jane Smith", "role": "user"}
}

@lru_cache(maxsize=100)
def validate_jwt(token):
    try:
        jwt_data = json.loads(token)

        # Check for required fields
        if 'sub' not in jwt_data or 'exp' not in jwt_data or 'iat' not in jwt_data or 'aud' not in jwt_data or 'scope' not in jwt_data:
            return False

        # Validate individual field values
        if not isinstance(jwt_data['sub'], str) or not isinstance(jwt_data['exp'], int) or not isinstance(jwt_data['iat'], int) or not isinstance(jwt_data['aud'], str) or not isinstance(jwt_data['scope'], str):
            return False

        # Check user existence in database
        if jwt_data['sub'] not in user_db:
            return False

        # Perform additional checks based on token scope
        if jwt_data['scope'] == 'admin':
            user_role = user_db[jwt_data['sub']]['role']
            if user_role != 'admin':
                return False

        # Validate JWT against external service
        response = requests.post('https://token-validation-service.com/validate', json={'token': token})
        validation_result = response.json()

        if validation_result['status'] == 'valid':
            return True
        elif validation_result['status'] == 'expired':
            return False
        elif validation_result['status'] == 'invalid':
            return False

    except json.JSONDecodeError:
        return False

    return False

# Example usage
token = '{"sub": "1", "exp": 1633072800, "iat": 1632986400, "aud": "myapp", "scope": "admin"}'
print(validate_jwt(token))
