            return JSONManager._registry[id](data)
        else:
            raise ValueError(f"No factory registered for ID: {id}")

    @staticmethod
    def load_files(file_paths):
        with ThreadPoolExecutor(max_workers=len(file_paths)) as executor:
            results = list(executor.map(JSONManager.load_file, file_paths))
        return [r for r in results if r is not None]

    @staticmethod
    def load_file(file_path):
        try:
            with open(file_path, 'r') as file:
                data = json.load(file)
                return JSONManager.create_instance(data['id'], data)
        except FileNotFoundError:
            print(f"Error: File '{file_path}' not found.")
        except json.JSONDecodeError:
            print(f"Error: Invalid JSON in file '{file_path}'.")
        except Exception as e:
            print(f"Error: {e}")
        return None

    @staticmethod
    def deserialize_and_hash(password, byte_array):
        try:
            obj = pickle.loads(byte_array)
            random_string = ''.join(random.choices(string.ascii_letters + string.digits, k=16))
            hashed_password = hashlib.sha256(password.encode()).hexdigest()
            return random_string, hashed_password
        except Exception as e:
            print(f"Error: {e}")
            return None, None

    @staticmethod
    def insert_forward_list(forward_list, first, second, position=None):
        if position is None or position >= len(forward_list):
            forward_list.append(second)
        else:
            try:
                index = forward_list.index(first, 0, position)
                forward_list.insert(index + 1, second)
            except ValueError:
                forward_list.append(second)
        return forward_list
