```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class FileEncryptor
{
    private readonly byte[] _encryptionKey;
    private readonly byte[] _salt;
    private readonly HsmKeyManager _keyManager;

    public FileEncryptor(byte[] encryptionKey, byte[] salt)
    {
        _encryptionKey = encryptionKey;
        _salt = salt;
        _keyManager = new HsmKeyManager();
    }

    public async Task<byte[]> EncryptFileAsync(string filePath)
    {
        using (var aesGcm = Aes.Create())
        {
            aesGcm.Key = await _keyManager.GetEncryptionKeyAsync(_encryptionKey, _salt);
            aesGcm.GenerateNonce();
            aesGcm.GenerateIV();

            var ciphertext = new byte[aesGcm.BlockSize / 8];
            var tag = new byte[aesGcm.TagSize / 8];

            using (var input = File.OpenRead(filePath))
            {
                await aesGcm.EncryptAsync(input, ciphertext, tag, aesGcm.IV, CancellationToken.None);
            }

            return Combine(ciphertext, tag, aesGcm.Nonce, aesGcm.IV);
        }
    }

    public async Task<byte[]> DecryptFileAsync(string filePath)
    {
        using (var aesGcm = Aes.Create())
        {
            var combinedData = await File.ReadAllBytesAsync(filePath);
            var ciphertextTagNonceIv = Split(combinedData);

            aesGcm.Key = await _keyManager.GetEncryptionKeyAsync(_encryptionKey, _salt);
            aesGcm.Tag = ciphertextTagNonceIv.tag;
            aesGcm.Nonce = ciphertextTagNonceIv.nonce;
            aesGcm.IV = ciphertextTagNonceIv.iv;

            using (var input = new MemoryStream(ciphertextTagNonceIv.ciphertext))
            {
                var plaintext = await DecryptAsync(input, aesGcm);
                return plaintext;
            }
        }
    }

    private byte[] Combine(byte[] first, byte[] second, byte[] third, byte[] fourth)
    {
        using (var result = new MemoryStream())
        {
            result.Write(first, 0, first.Length);
            result.Write(second, 0, second.Length);
            result.Write(third, 0, third.Length);
            result.Write(fourth, 0, fourth.Length);
            return result.ToArray();
        }
    }

    private (byte[] ciphertext, byte[] tag, byte[] nonce, byte[] iv) Split(byte[] combinedData)
    {
        var aesGcm = Aes.Create();
        var length = aesGcm.BlockSize / 8;
        var tagLength = aesGcm.TagSize / 8;

        return (
            ciphertext: combinedData.Skip(length).Take(combinedData.Length - length - tagLength).ToArray(),
            tag: combinedData.Skip(length + combinedData.Length - tagLength).Take(tagLength).ToArray(),
            nonce: combinedData.Take(length).ToArray(),
            iv: new byte[0] // IV is not used in GCM mode
        );
    }

    private async Task<byte[]> DecryptAsync(Stream input, Aes aesGcm)
    {
        using (var output = new MemoryStream())
        {
            await aesGcm.DecryptAsync(input, output, CancellationToken.None);
            return output.ToArray();
        }
    }
}

