import java.util.List;
import java.util.concurrent.*;

public class TaskScheduler {
    private ExecutorService executorService;
    private ConcurrentHashMap<String, Future<?>> taskCache;

    public TaskScheduler(int maxConcurrentTasks) {
        this.executorService = Executors.newFixedThreadPool(maxConcurrentTasks);
        this.taskCache = new ConcurrentHashMap<>();
    }

    public void scheduleTask(String taskDescription) {
        if (taskCache.containsKey(taskDescription)) {
            return; // Use cached result
        }

        Future<?> future = executorService.submit(() -> executeTask(taskDescription));
        taskCache.put(taskDescription, future);
    }

    private void executeTask(String taskDescription) {
        try {
            ThirdPartyAPI api = new ThirdPartyAPI();
            Result result = api.executeTask(taskDescription);
            logTaskExecution(result);
        } catch (Exception e) {
            handleError(taskDescription, e);
        }
    }

    private void logTaskExecution(Result result) {
        // Log task execution details
    }

    private void handleError(String taskDescription, Exception e) {
        // Log error message and handle exception
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }
}
