function FindElementsBySelector(node, selector, callback) {
    if (!node || !selector || typeof callback !== 'function') {
        throw new Error('Invalid input');
    }

    let elements = [];

    function traverse(element) {
        if (element.nodeType === Node.ELEMENT_NODE) {
            if (callback(element)) {
                elements.push(element);
            }
            for (let child of element.childNodes) {
                traverse(child);
            }
        }
    }

    traverse(node);

    return elements;
}
