#include <iostream>
#include <string>
#include <random>
#include <openssl/sha.h>

namespace Security {
    class SecureRandomNumberGenerator {
    public:
        SecureRandomNumberGenerator() {
            std::random_device rd;
            rng.seed(rd());
        }

        ~SecureRandomNumberGenerator() = default;

        static std::string generateSessionId() {
            SecureRandomNumberGenerator& instance = getInstance();
            unsigned int randomInt = instance.rng();
            std::string sessionId = base64_encode(reinterpret_cast<const char*>(&randomInt), sizeof(randomInt));
            return sessionId.substr(0, 22);
        }

    private:
        static SecureRandomNumberGenerator& getInstance() {
            static SecureRandomNumberGenerator instance;
            return instance;
        }

        std::mt19937_64 rng;

        static std::string base64_encode(const unsigned char* data, size_t length) {
            BIO *bio, *b64;
            BUF_MEM *bufferPtr;
            b64 = BIO_new(BIO_f_base64());
            bio = BIO_new(BIO_s_mem());
            bio = BIO_push(b64, bio);
            BIO_write(bio, data, length);
            BIO_flush(bio);
            BIO_get_mem_ptr(bio, &bufferPtr);
            std::string result(bufferPtr->data, bufferPtr->length - 1); // remove the trailing newline
            BIO_free_all(bio);
            return result;
        }
    };
}

int main() {
    try {
        std::string sessionId = Security::SecureRandomNumberGenerator::generateSessionId();
        std::cout << "Generated Session ID: " << sessionId << std::endl;
        // Check if the session ID is already in use
        // ...
    } catch (const std::exception& e) {
        std::cerr << "Error generating session ID: " << e.what() << std::endl;
        return 1;
    }
    return 0;
}
