#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <pthread.h>

#define MAX_URLS 100
#define MAX_THREADS 20

typedef struct {
    char url[MAX_URLS][1024];
    int num_urls;
    pthread_mutex_t lock;
} UrlList;

typedef struct {
    UrlList *url_list;
    int thread_id;
    pthread_cond_t cond_var;
    pthread_mutex_t cond_lock;
    int exit_flag;
} ThreadData;

void* download_url(void* arg) {
    ThreadData* data = (ThreadData*)arg;
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);

    for (;;) {
        char url[1024];
        pthread_mutex_lock(&data->url_list->lock);
        if (data->exit_flag && data->url_list->num_urls == 0) {
            pthread_mutex_unlock(&data->url_list->lock);
            break;
        }
        if (data->url_list->num_urls > 0) {
            strncpy(url, data->url_list->url[--data->url_list->num_urls], sizeof(url));
        } else {
            pthread_cond_wait(&data->cond_var, &data->url_list->lock);
        }
        pthread_mutex_unlock(&data->url_list->lock);

        curl = curl_easy_init();
        if(curl) {
            curl_easy_setopt(curl, CURLOPT_URL, url);
            res = curl_easy_perform(curl);
            if(res != CURLE_OK)
                fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            curl_easy_cleanup(curl);
        }
    }

    pthread_exit(NULL);
}

int main(int argc, char *argv[]) {
    UrlList url_list = {0};
    pthread_t threads[MAX_THREADS];
    ThreadData thread_data[MAX_THREADS];
    int num_threads = 5; // Default number of threads

    if (argc > 1) {
        num_threads = atoi(argv[1]);
        if (num_threads > MAX_THREADS)
            num_threads = MAX_THREADS;
    }

    pthread_mutex_init(&url_list.lock, NULL);

    for (int i = 0; i < num_threads; i++) {
        thread_data[i].url_list = &url_list;
        thread_data[i].thread_id = i;
        pthread_cond_init(&thread_data[i].cond_var, NULL);
        pthread_mutex_init(&thread_data[i].cond_lock, NULL);
        thread_data[i].exit_flag = 0;
        pthread_create(&threads[i], NULL, download_url, &thread_data[i]);
    }

    // Add URLs to the list
    strncpy(url_list.url[0], "http://example.com", sizeof(url_list.url[0]));
    url_list.num_urls++;

    // Wait for all threads to finish
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&url_list.lock);

    return 0;
}
