<?php

class UserNotFoundException extends Exception {}

class UserAuthentication {
    private $database = [
        'john_doe' => ['salt' => 'base64:...', 'password_hash' => '...'],
        // Other users...
    ];
    private $cache;

    public function __construct() {
        $this->cache = new SimpleCache(); // Assuming a simple caching class is available
    }

    public function authenticateUser($username, $password) {
        try {
            $salt = $this->retrieveSalt($username);
            $hashedPassword = password_hash($password . $salt, PASSWORD_BCRYPT, ['cost' => 12]);
            if (isset($this->database[$username]['password_hash']) && 
                password_verify($hashedPassword, $this->database[$username]['password_hash'])) {
                return "Authentication successful.";
            } else {
                return "Invalid username or password.";
            }
        } catch (UserNotFoundException $e) {
            return "Username not found.";
        }
    }

    public function changeUserPassword($username, $newPassword) {
        $salt = base64_encode(random_bytes(16));
        $hashedPassword = password_hash($newPassword . $salt, PASSWORD_BCRYPT, ['cost' => 12]);

        // Simulate updating the database
        $this->database[$username] = ['salt' => $salt, 'password_hash' => $hashedPassword];

        return "Password changed successfully.";
    }

    public function forgotPassword($email) {
        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            return "Invalid email address.";
        }

        // Simulate checking if the email exists
        if (!isset($this->database[$email])) {
            return "Email does not exist.";
        }

        $token = bin2hex(random_bytes(32));
        $expirationTime = time() + 3600; // Token expires in 1 hour

        // Simulate updating the database
        $this->database['tokens'][$email] = ['token' => $token, 'expires_at' => $expirationTime];

        // Send password reset email (simulated)
        $this->sendPasswordResetEmail($email, $token);

        return "Password reset email sent.";
    }

    public function resetPasswordUsingToken($token, $newPassword) {
        foreach ($this->database['tokens'] as $user => $data) {
            if ($data['token'] === $token && time() < $data['expires_at']) {
                $salt = base64_encode(random_bytes(16));
                $hashedPassword = password_hash($newPassword . $salt, PASSWORD_BCRYPT, ['cost' => 12]);

                // Simulate updating the database
                $this->database[$user] = ['salt' => $salt, 'password_hash' => $hashedPassword];

                unset($this->database['tokens'][$user]); // Remove used token

                return "Password reset successfully.";
            }
        }

        return "Invalid or expired token.";
    }

    private function retrieveSalt($username) {
        if (isset($this->cache[$username])) {
            return $this->cache[$username];
        } else {
            if (!isset($this->database[$username])) {
                throw new UserNotFoundException();
            }

            $salt = $this->database[$username]['salt'];
            $this->cache[$username] = $salt; // Cache the salt

            return $salt;
        }
    }

    private function sendPasswordResetEmail($email, $token) {
        // Simulate sending an email (use a real API in production)
        echo "Sending password reset email to {$email} with token: {$token}";
    }
}
