    static async Task Main(string[] args)
    {
        if (args.Length == 0)
        {
            Console.WriteLine("Please provide file paths as command-line arguments.");
            return;
        }

        List<string> files = new List<string>(args);
        int largestNumber = int.MinValue;
        double average = 0;

        foreach (var file in files)
        {
            if (!File.Exists(file))
            {
                Console.WriteLine($"Error: File '{file}' does not exist.");
                continue;
            }

            try
            {
                var numbers = await ReadNumbersAsync(file);
                largestNumber = Math.Max(largestNumber, numbers.Max());
                average += numbers.Average();
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error processing file '{file}': {ex.Message}");
            }
        }

        average /= files.Length;
        Console.WriteLine($"Largest Number: {largestNumber}");
        Console.WriteLine($"Average of Numbers: {average}");

