    }

    static async Task<List<int>> ReadNumbersAsync(string filePath)
    {
        List<int> numbers = new List<int>();
        string[] lines = await File.ReadAllLinesAsync(filePath);

        foreach (var line in lines)
        {
            if (int.TryParse(line, out int number))
            {
                numbers.Add(number);
            }
        }

        return numbers;
    }

