class UserAuthentication {
    private $database = [];
    private $cache = [];

    public function authenticateUser($username, $password) {
        // Rate limiting logic here
        if ($this->isRateLimited($username)) {
            throw new RateLimitExceededException('Too many failed login attempts. Please try again later.');
        }

        if (!isset($this->database[$username])) {
            return 'Username not found.';
        }

        $storedHash = $this->database[$username]['hash'];
        $salt = $this->database[$username]['salt'];

        if (password_verify($password . $salt, $storedHash)) {
            return 'Authentication successful.';
        } else {
            return 'Password is incorrect.';
        }
    }

    public function changeUserPassword($username, $newPassword) {
        // Pessimistic locking logic here
        $this->lockUser($username);

        if (!isset($this->database[$username])) {
            throw new UserNotFoundException('User not found.');
        }

        $salt = base64_encode(random_bytes(22));
        $hashedPassword = password_hash($newPassword . $salt, PASSWORD_BCRYPT, ['cost' => 12]);

        $this->database[$username]['hash'] = $hashedPassword;
        $this->database[$username]['salt'] = $salt;

        $this->unlockUser($username);

        return 'Password changed successfully.';
    }

