```javascript
async function copyBufferChunks(chunks, byteCount) {
    try {
        const mergedBuffer = Buffer.alloc(byteCount);
        let bytesRead = 0;

        for (const chunk of chunks) {
            if (bytesRead + chunk.length < byteCount) {
                chunk.copy(mergedBuffer, bytesRead);
                bytesRead += chunk.length;
            } else {
                chunk.copy(mergedBuffer, bytesRead, 0, byteCount - bytesRead);
                break;
            }
        }

        if (bytesRead !== byteCount) {
            throw new Error('Requested byte count exceeds available data');
        }

        // Log to database
        await logToDatabase({ action: 'copy', bytesCopied: byteCount });

        return mergedBuffer;

    } catch (error) {
        console.error('Error copying buffer chunks:', error);
        throw error;
    }
}

async function logToDatabase(logData) {
    try {
        // Simulate database logging
        console.log('Logging to database:', logData);
        await new Promise(resolve => setTimeout(resolve, 10)); // Simulate async operation
    } catch (error) {
        console.error('Error logging to database:', error);
        throw error;
    }
}

// Example usage:
(async () => {
    const chunks = [Buffer.from('Hello'), Buffer.from(' World!'), Buffer.from(' This is a test.')];
    const byteCount = 10;
    try {
        const result = await copyBufferChunks(chunks, byteCount);
        console.log(result.toString()); // Output: Hello Wor
    } catch (error) {
        console.error('Error:', error);
    }
})();
