import json
import hashlib
import os
import time
from concurrent.futures import ThreadPoolExecutor
from typing import Dict, Any, Callable, Type, Optional

class JSONLoader:
    _registry: Dict[str, Callable[[Dict], Any]] = {}
    _cache: Dict[str, Any] = {}

    @classmethod
    def register_factory(cls, id: str, factory: Callable[[Dict], Any]):
        cls._registry[id] = factory

    @classmethod
    def create_instance(cls, id: str, data: Dict) -> Any:
        if id in cls._registry:
            return cls._registry[id](data)
        raise ValueError(f"No factory registered for ID: {id}")

    @staticmethod
    def _get_cache_key(file_path: str) -> str:
        with open(file_path, 'rb') as file:
            return hashlib.md5(file.read()).hexdigest()

    @classmethod
    def load_json(cls, file_path: str) -> Any:
        cache_key = cls._get_cache_key(file_path)
        if cache_key in cls._cache:
            return cls._cache[cache_key]

        with open(file_path, 'r') as file:
            data = json.load(file)

        instance = JSONLoader.create_instance(data['id'], data['data'])
        cls._cache[cache_key] = instance
        return instance

    @classmethod
    def load_json_async(cls, file_path: str) -> Any:
        with ThreadPoolExecutor() as executor:
            future = executor.submit(cls.load_json, file_path)
            return future.result()

# Example usage:
class Person(JSONLoader):
    @staticmethod
    def create_from_data(data: Dict):
        return Person(name=data['name'], age=data['age'])

JSONLoader.register_factory('person', Person.create_from_data)

# Load a JSON file asynchronously
person = JSONLoader.load_json_async('path/to/person.json')
