using System;
using Microsoft.AspNetCore.Identity;
using Amazon.S3;

public class ImageUploader
{
    private readonly IAmazonS3 _s3Client;
    private readonly UserManager<IdentityUser> _userManager;

    public ImageUploader(IAmazonS3 s3Client, UserManager<IdentityUser> userManager)
    {
        _s3Client = s3Client;
        _userManager = userManager;
    }

    public async Task UploadImageAsync(string imageUrl, string bucketName, string userId)
    {
        var user = await _userManager.FindByIdAsync(userId);
        if (user == null) throw new ArgumentException("User not found.");

        var imageBytes = await DownloadImageAsync(imageUrl);
        var cacheKey = $"{userId}_{imageUrl}";
        var cachedTimestamp = MemoryCache.Get(cacheKey) as DateTime?;

        if (cachedTimestamp.HasValue && DateTime.UtcNow - cachedTimestamp.Value <= TimeSpan.FromDays(1))
            return;

        var fileStream = new MemoryStream(imageBytes);
        var putObjectRequest = new PutObjectRequest
        {
            BucketName = bucketName,
            Key = $"{user.UserName}_{Path.GetFileName(imageUrl)}",
            InputStream = fileStream
        };

        await _s3Client.PutObjectAsync(putObjectRequest);

        MemoryCache.Set(cacheKey, DateTime.UtcNow, TimeSpan.FromDays(1));
    }

    private async Task<byte[]> DownloadImageAsync(string imageUrl)
    {
        using (var client = new HttpClient())
        {
            var response = await client.GetAsync(imageUrl);
            return await response.Content.ReadAsByteArrayAsync();
        }
    }
}
