```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.nio.channels.SocketChannel;
import java.util.Iterator;

public class SecureConnectionServer {
    private static final int PORT = 8443;
    private static final String SSL_KEY_STORE = "path/to/keystore.jks";
    private static final char[] SSL_KEY_STORE_PASSWORD = "password".toCharArray();

    public void start() throws IOException {
        ServerSocketChannel serverChannel = ServerSocketChannel.open();
        serverChannel.bind(new InetSocketAddress(PORT));
        serverChannel.configureBlocking(false);

        Selector selector = Selector.open();
        serverChannel.register(selector, SelectionKey.OP_ACCEPT);

        while (true) {
            selector.select();
            Iterator<SelectionKey> keys = selector.selectedKeys().iterator();

            while (keys.hasNext()) {
                SelectionKey key = keys.next();

                if (key.isAcceptable()) {
                    handleConnection(serverChannel, selector);
                } else if (key.isReadable()) {
                    handleRequest(key);
                }

                keys.remove();
            }
        }
    }

    private void handleConnection(ServerSocketChannel serverChannel, Selector selector) throws IOException {
        SocketChannel clientChannel = serverChannel.accept();
        clientChannel.configureBlocking(false);

        SSLEngine sslEngine = createSslEngine();
        SSLContext sslContext = SSLContext.getInstance("TLS");
        sslContext.init(null, null, new SecureRandom());

        SSLSocket socket = (SSLSocket) sslContext.getSocketFactory().createSocket(clientChannel.socket());
        socket.setSSLParameters(sslEngine.getSessionParameters());

        clientChannel.register(selector, SelectionKey.OP_READ);
    }

    private void handleRequest(SelectionKey key) throws IOException {
        SocketChannel clientChannel = (SocketChannel) key.channel();
        SSLSession sslSession = getSSLSession(clientChannel);

        if (sslSession != null) {
            ByteBuffer buffer = ByteBuffer.allocate(1024);
            int bytesRead = clientChannel.read(buffer);

            if (bytesRead == -1) {
                clientChannel.close();
            } else {
                buffer.flip();
                byte[] data = new byte[buffer.remaining()];
                buffer.get(data);

                String request = new String(data);
                String response = handleRequest(request, sslSession);

                ByteBuffer responseBuffer = ByteBuffer.wrap(response.getBytes());
                clientChannel.write(responseBuffer);
            }
        }
    }

    private SSLEngine createSslEngine() throws SSLException {
        SSLContext sslContext = SSLContext.getInstance("TLS");
        sslContext.init(null, null, new SecureRandom());

