#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h> // Assuming json-c library is used for JSON parsing
#include <curl/curl.h>   // Assuming libcurl is used for remote server communication

#define MAX_RETRIES 3
#define BACKOFF_FACTOR 2

typedef struct {
    char *access_token;
    int expires_in;
    char *token_type;
    char *refresh_token;
} OAuthToken;

// Function to parse JSON and validate token
int validate_oauth_token(const char *json_str, OAuthToken *token) {
    json_object *parsed_json = json_tokener_parse(json_str);
    if (!parsed_json) {
        fprintf(stderr, "Invalid JSON\n");
        return -1;
    }

    // Extract required fields
    json_object *access_token_obj;
    if (json_object_object_get_ex(parsed_json, "access_token", &access_token_obj)) {
        token->access_token = strdup(json_object_get_string(access_token_obj));
    } else {
        fprintf(stderr, "Missing access_token field\n");
        json_object_put(parsed_json);
        return -1;
    }

    json_object *expires_in_obj;
    if (json_object_object_get_ex(parsed_json, "expires_in", &expires_in_obj)) {
        token->expires_in = json_object_get_int(expires_in_obj);
        if (token->expires_in <= 0) {
            fprintf(stderr, "Invalid expires_in value\n");
            free(token->access_token);
            json_object_put(parsed_json);
            return -1;
        }
    } else {
        fprintf(stderr, "Missing expires_in field\n");
        free(token->access_token);
        json_object_put(parsed_json);
        return -1;
    }

    json_object *token_type_obj;
    if (json_object_object_get_ex(parsed_json, "token_type", &token_type_obj)) {
        token->token_type = strdup(json_object_get_string(token_type_obj));
        if (strcmp(token->token_type, "Bearer") != 0) {
            fprintf(stderr, "Invalid token_type value\n");
            free(token->access_token);
            free(token->token_type);
            json_object_put(parsed_json);
            return -1;
        }
    } else {
        fprintf(stderr, "Missing token_type field\n");
        free(token->access_token);
        free(token->token_type);
        json_object_put(parsed_json);
        return -1;
    }

    // Optional refresh_token
    json_object *refresh_token_obj;
    if (json_object_object_get_ex(parsed_json, "refresh_token", &refresh_token_obj)) {
        token->refresh_token = strdup(json_object_get_string(refresh_token_obj));
        if (!token->refresh_token) {
            fprintf(stderr, "Invalid refresh_token value\n");
            free(token->access_token);
            free(token->token_type);
            json_object_put(parsed_json);
            return -1;
        }
    } else {
        token->refresh_token = NULL;
    }

    json_object_put(parsed_json);
    return 0;
}

// Function to fetch validation rules from a remote server
int fetch_validation_rules(const char *url, char **rules) {
    CURL *curl;
    CURLcode res;

    for (int i = 0; i < MAX_RETRIES; i++) {
        curl_global_init(CURL_GLOBAL_ALL);
        curl = curl_easy_init();
        if(curl) {
            struct curl_slist *headers = NULL;
            headers = curl_slist_append(headers, "Accept: application/json");

            curl_easy_setopt(curl, CURLOPT_URL, url);
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_memory_callback);

            res = curl_easy_perform(curl);
            if(res != CURLE_OK) {
                fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
                curl_easy_cleanup(curl);
                curl_global_cleanup();
                if (i < MAX_RETRIES - 1) {
                    usleep(BACKOFF_FACTOR * (1 << i) * 1000); // Exponential backoff
                } else {
                    return -1;
                }
            } else {
                curl_easy_cleanup(curl);
                curl_global_cleanup();
                *rules = strdup(write_buf.memory);
                return 0;
            }
        }
    }

    return -1;
}

// Callback function for libcurl to handle data received from the remote server
size_t write_memory_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    struct MemoryStruct *mem = (struct MemoryStruct *)userp;

    char *ptr = realloc(mem->memory, mem->size + realsize + 1);
    if(ptr == NULL) {
        // out of memory!
        printf("not enough memory (realloc returned NULL)\n");
        return 0;
    }

    mem->memory = ptr;
    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = 0;

    return realsize;
}

// Struct to store data received from the remote server
struct MemoryStruct {
    char *memory;
    size_t size;
};

int main() {
    OAuthToken token;
    memset(&token, 0, sizeof(OAuthToken));

    // Fetch validation rules (in a real scenario, this would be done asynchronously)
    char *validation_rules;
    if (fetch_validation_rules("https://api.example.com/validation_rules", &validation_rules) != 0) {
        fprintf(stderr, "Failed to fetch validation rules\n");
        return -1;
    }

    // Validate token
    if (validate_oauth_token("{\"access_token\":\"abc123\",\"expires_in\":3600,\"token_type\":\"Bearer\"}", &token) == 0) {
        printf("Token is valid.\n");
    } else {
        printf("Token is invalid.\n");
    }

    // Clean up
    free(token.access_token);
    free(token.token_type);
    if (token.refresh_token) {
        free(token.refresh_token);
    }
    free(validation_rules);

    return 0;
}
