using System;
using System.Collections.Concurrent;
using System.Data.Common;
using System.Diagnostics;
using System.Linq;
using System.Threading.Tasks;

public abstract class DynamicDatabaseConnectionManager<T> where T : DbProviderFactory, new()
{
    private static readonly ConcurrentDictionary<string, ConnectionPool> Pools = new ConcurrentDictionary<string, ConnectionPool>();
    private static readonly Random SeedGenerator = new Random();
    private static readonly object SeedLock = new object();

    public int MaxPoolSize { get; set; }
    public string ExternalConfigSource { get; set; }

    protected DynamicDatabaseConnectionManager(int maxPoolSize, string externalConfigSource)
    {
        MaxPoolSize = maxPoolSize;
        ExternalConfigSource = externalConfigSource;
    }

    public async Task<DbConnection> GetConnectionAsync(string connectionString)
    {
        if (string.IsNullOrEmpty(connectionString))
            throw new ArgumentException("Connection string cannot be null or empty.", nameof(connectionString));

        var poolKey = connectionString.GetHashCode().ToString();
        var pool = Pools.GetOrAdd(poolKey, _ => new ConnectionPool(this, MaxPoolSize));
        return await pool.GetConnectionAsync(connectionString);
    }

    public void Seed(int seed)
    {
        lock (SeedLock)
        {
            SeedGenerator.Seed(seed);
        }
    }

    protected virtual async Task<DbConnectionStringBuilder> LoadConfigurationsAsync(string connectionString)
    {
        // Implement logic to load configurations from external systems
        // Return a DbConnectionStringBuilder with the loaded settings or default values
        return new DbConnectionStringBuilder();
    }

    protected abstract Task<DbConnection> CreateConnectionAsync(string connectionString);

    private class ConnectionPool
    {
        private readonly DynamicDatabaseConnectionManager<T> Manager;
        private readonly int MaxSize;
        private readonly ConcurrentQueue<DbConnection> Pool = new ConcurrentQueue<DbConnection>();
        private readonly object Lock = new object();

        public ConnectionPool(DynamicDatabaseConnectionManager<T> manager, int maxSize)
        {
            Manager = manager;
            MaxSize = maxSize;
        }

        public async Task<DbConnection> GetConnectionAsync(string connectionString)
        {
            if (Pool.TryDequeue(out var connection))
                return connection;

            if (Pool.Count < MaxSize)
            {
                lock (Lock)
                {
                    if (Pool.Count < MaxSize)
                    {
                        var newConnection = await Manager.CreateConnectionAsync(connectionString);
                        Pool.Enqueue(newConnection);
                        return newConnection;
                    }
                }
            }

            // Handle pool overflow or other scenarios
            throw new InvalidOperationException("Connection pool is full.");
        }

        public void ReturnConnection(DbConnection connection)
        {
            if (Pool.Count < MaxSize)
                Pool.Enqueue(connection);
            else
                connection.Dispose();
        }
    }
}
