import java.io.IOException;
import java.net.URI;
import java.security.KeyManagementException;
import java.security.NoSuchAlgorithmException;
import java.security.cert.X509Certificate;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import javax.net.ssl.*;
import org.apache.http.client.HttpClient;
import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.client.methods.HttpGet;
import org.apache.http.conn.ssl.NoopHostnameVerifier;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.ssl.SSLContextBuilder;

public class SecureConnectionPool {

    private final ConcurrentHashMap<String, SSLEngine> sslEngines = new ConcurrentHashMap<>();
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private final int maxConnections = 1000;
    private final long idleTimeoutMillis = 60000; // 1 minute

    public SecureConnectionPool() {
        scheduler.scheduleAtFixedRate(this::reclaimIdleConnections, idleTimeoutMillis / 2, idleTimeoutMillis, TimeUnit.MILLISECONDS);
    }

    public SSLEngine getSSLEngine(String host) throws NoSuchAlgorithmException, KeyManagementException {
        return sslEngines.computeIfAbsent(host, h -> createSSLEngine(h));
    }

    private SSLEngine createSSLEngine(String host) throws NoSuchAlgorithmException, KeyManagementException {
        SSLContext sslContext = new SSLContextBuilder()
                .loadTrustMaterial(null, (chain, authType) -> true)
                .build();

        SSLParameters sslParameters = new SSLParameters();
        sslParameters.setEndpointIdentificationAlgorithm("HTTPS");

        SSLEngine sslEngine = sslContext.createSSLEngine(host, 443);
        sslEngine.setSSLParameters(sslParameters);
        sslEngine.setUseClientMode(true);

        return sslEngine;
    }

    public void executeRequest(String url) throws IOException {
        URI uri = new URI(url);
        SSLEngine sslEngine = getSSLEngine(uri.getHost());

        SSLSessionContext serverSessionCtx = sslEngine.getSession().getSessionContext();
        SSLSession previousSession = serverSessionCtx.getClientSessionCache().getSession(uri.getHost() + ":" + 443);

        HttpClient httpClient = HttpClients.custom()
                .setSSLHostnameVerifier(NoopHostnameVerifier.INSTANCE)
                .build();

        HttpGet request = new HttpGet(url);
        try (CloseableHttpResponse response = httpClient.execute(request)) {
            // Handle response
        }
    }

    private void reclaimIdleConnections() {
        long currentTimeMillis = System.currentTimeMillis();
        sslEngines.entrySet().removeIf(entry -> entry.getValue().getSession().getLastAccessedTime() < currentTimeMillis - idleTimeoutMillis);
    }
}
```

This code snippet demonstrates a basic implementation of a secure connection pool using Java NIO channels, SSL/TLS session resumption, and connection pooling. It includes methods for obtaining an SSLEngine, executing HTTP requests over the pooled connections, and reclaiming idle connections. The solution uses a ConcurrentHashMap to store SSLEngines for each host and a ScheduledExecutorService to periodically check and reclaim idle connections. Note that this is a simplified example and may require additional error handling, logging, and configuration for production use.

```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <filesystem>
#include <thread>
#include <mutex>
#include <numeric>

namespace fs = std::filesystem;

std::mutex logMutex;
void log(const std::string& message) {
    std::lock_guard<std::mutex> lock(logMutex);
    std::cout << "LOG: " << message << std::endl;
}

struct DataProcessor {
    int maxInt = INT_MIN;
    long totalSum = 0;
    size_t totalCount = 0;

    void processFile(const std::string& filename) {
        log("Processing file: " + filename);
        std::ifstream file(filename);
        if (!file.is_open()) {
            log("Error opening file: " + filename);
            return;
        }

        int num;
        while (file >> num) {
            maxInt = std::max(maxInt, num);
            totalSum += num;
            ++totalCount;
        }
        file.close();
        log("Processed file: " + filename);
    }
};

void processDirectory(const fs::path& directoryPath, DataProcessor& processor) {
    if (!fs::exists(directoryPath)) {
        log("Directory does not exist: " + directoryPath.string());
        return;
    }

    if (!fs::is_directory(directoryPath)) {
        log("Not a directory: " + directoryPath.string());
        return;
    }

    std::vector<std::thread> threads;

    for (const auto& entry : fs::directory_iterator(directoryPath)) {
        if (entry.is_regular_file() && entry.path().extension() == ".txt") {
            threads.emplace_back(&DataProcessor::processFile, &processor, entry.path().string());
        }
    }

    for (auto& thread : threads) {
        thread.join();
    }
}

double calculateAverage(const DataProcessor& processor) {
    return static_cast<double>(processor.totalSum) / processor.totalCount;
}

int main(int argc, char* argv[]) {
    if (argc < 3) {
        std::cerr << "Usage: " << argv[0] << " <input_directory> <output_file>" << std::endl;
        return 1;
    }

    fs::path inputDirectory = argv[1];
    std::string outputFile = argv[2];

    DataProcessor processor;
    processDirectory(inputDirectory, processor);

    log("Calculating average and max value");
    double average = calculateAverage(processor);
    log("Max value: " + std::to_string(processor.maxInt));
    log("Average value: " + std::to_string(average));

    log("Writing results to output file");
    std::ofstream outFile(outputFile);
    if (outFile.is_open()) {
        outFile << "Max Value: " << processor.maxInt << "\n";
        outFile << "Average Value: " << average << "\n";
        outFile.close();
    } else {
        log("Error opening output file: " + outputFile);
    }

    return 0;
}
