                .short('c')
                .long("config")
                .value_name("FILE")
                .takes_value(true)
                .help("Sets a custom config file"),
        )
        .get_matches();

    let config_path = matches.value_of("config").unwrap_or("default_config.json");
    let config_content = read_config(config_path).await?;
    let config: Config = serde_json::from_str(&config_content)?;

    run_function(&config.api_settings).await?;

