const renderFooterScripts = async (scripts) => {
  const cache = new Map();
  const spinnerElement = document.createElement('div');
  spinnerElement.textContent = 'Loading...';
  document.body.appendChild(spinnerElement);

  const fetchScript = async (scriptUrl) => {
    if (cache.has(scriptUrl)) {
      return cache.get(scriptUrl);
    }

    try {
      const response = await fetch(scriptUrl, { method: 'GET', mode: 'cors' });
      if (!response.ok) {
        throw new Error('Network response was not ok');
      }
      const scriptContent = await response.text();
      cache.set(scriptUrl, scriptContent);
      return scriptContent;
    } catch (error) {
      console.error(`Failed to fetch script from ${scriptUrl}:`, error);
      throw error;
    }
  };

  const renderScript = (script) => {
    const scriptElement = document.createElement('script');
    scriptElement.type = script.type || 'text/javascript';

    if (script.src) {
      scriptElement.src = script.src;
      scriptElement.async = true;
      scriptElement.onload = () => {
        spinnerElement.remove();
      };
      scriptElement.onerror = (error) => {
        console.error('Failed to load external script:', error);
        spinnerElement.remove();
      };
    } else {
      scriptElement.text = script.code || '';
      spinnerElement.remove();
    }

    document.body.appendChild(scriptElement);
  };

  const checkDependencies = (scripts) => {
    // Implement dependency checking logic here
    return scripts;
  };

  try {
    scripts = await fetch('/api/scripts');
    scripts = await scripts.json();
    scripts = checkDependencies(scripts);

    for (const script of scripts) {
      if (script.src) {
        const scriptContent = await fetchScript(script.src);
        renderScript({ ...script, code: scriptContent });
      } else {
        renderScript(script);
      }
    }
  } catch (error) {
    console.error('Failed to load scripts:', error);
    spinnerElement.remove();
  }
};

// Example usage
const exampleScripts = [
  { code: 'console.log("Hello from inline script");' },
  { src: '/path/to/external/script.js', type: 'application/javascript' }
];
renderFooterScripts(exampleScripts);
