using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Diagnostics;
using System.Numerics;
using System.Threading.Tasks;

namespace RandomNumberGeneratorAndFileProcessor
{
    public class RandomNumberGenerator
    {
        private static readonly Random _random = new Random();

        public int GenerateRandomNumber(int min, int max)
        {
            return _random.Next(min, max);
        }

        ~RandomNumberGenerator()
        {
            // Cleanup code if needed
        }
    }

    public class FileProcessor
    {
        private readonly string[] _filePaths;
        private readonly RandomNumberGenerator _rng;

        public FileProcessor(string[] filePaths)
        {
            _filePaths = filePaths;
            _rng = new RandomNumberGenerator();
        }

        ~FileProcessor()
        {
            _rng?.Dispose(); // Ensure proper cleanup
        }

        public async Task<(int? LargestNumber, double Average)> ProcessFilesAsync()
        {
            int largestNumber = int.MinValue;
            long totalSum = 0;
            int totalCount = 0;

            foreach (var filePath in _filePaths)
            {
                if (!Directory.Exists(Path.GetDirectoryName(filePath)) || !File.Exists(filePath))
                {
                    Console.WriteLine($"Error: Invalid file or directory path - {filePath}");
                    continue;
                }

                string webConfigPath = Path.Combine(Path.GetDirectoryName(filePath), "web.config");
                if (!File.Exists(webConfigPath))
                {
                    Console.WriteLine($"Error: Missing web.config in directory - {filePath}");
                    continue;
                }

                try
                {
                    var numbers = await ReadNumbersFromFileAsync(filePath);
                    if (numbers == null)
                    {
                        Console.WriteLine($"Error: Failed to read numbers from file - {filePath}");
                        continue;
                    }

                    largestNumber = Math.Max(largestNumber, numbers.Max());
                    totalSum += numbers.Sum();
                    totalCount += numbers.Count;
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error processing file - {filePath}: {ex.Message}");
                }
            }

            return totalCount > 0 ? (largestNumber, (double)totalSum / totalCount) : (null, 0.0);
        }

        private async Task<List<int>> ReadNumbersFromFileAsync(string filePath)
        {
            List<int> numbers = new List<int>();

            try
            {
                string[] lines = await File.ReadAllLinesAsync(filePath);
                foreach (string line in lines)
                {
                    if (int.TryParse(line, out int number))
                    {
                        numbers.Add(number);
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error reading file - {filePath}: {ex.Message}");
                return null;
            }

            return numbers;
        }
    }

    class Program
    {
        static async Task Main(string[] args)
        {
            if (args.Length == 0)
            {
                Console.WriteLine("Usage: RandomNumberGeneratorAndFileProcessor <file1> <file2> ...");
                return;
            }

            FileProcessor fileProcessor = new FileProcessor(args);
            var result = await fileProcessor.ProcessFilesAsync();

            Console.WriteLine($"Largest Number: {result.LargestNumber}");
            Console.WriteLine($"Average: {result.Average:F2}");
        }
    }
}
