import requests
from bs4 import BeautifulSoup
from threading import Lock
from collections import OrderedDict
from typing import List, Dict, Any

class ImageCache:
    def __init__(self, max_size=500):
        self.cache = OrderedDict()
        self.max_size = max_size
        self.lock = Lock()

    def get(self, key):
        with self.lock:
            if key in self.cache:
                self.cache.move_to_end(key)
                return self.cache[key]
        return None

    def set(self, key, value):
        with self.lock:
            if key in self.cache:
                self.cache.move_to_end(key)
            self.cache[key] = value
            if len(self.cache) > self.max_size:
                self.cache.popitem(last=False)

class ImageProcessor:
    @staticmethod
    def is_valid_image(image_url, min_width=None, max_width=None, min_height=None, max_height=None, file_types=None):
        response = requests.get(image_url)
        img = Image.open(BytesIO(response.content))
        width, height = img.size
        if (min_width and width < min_width) or (max_width and width > max_width) or \
           (min_height and height < min_height) or (max_height and height > max_height):
            return False
        file_extension = image_url.split('.')[-1].lower()
        if file_types and file_extension not in file_types:
            return False
        return True

    @staticmethod
    def fetch_image(image_url):
        response = requests.get(image_url)
        return Image.open(BytesIO(response.content))

def fetch_and_process_images(url: str, min_width: int = None, max_width: int = None, min_height: int = None, max_height: int = None, file_types: List[str] = None) -> List[Dict[str, Any]]:
    cache_key = (url, min_width, max_width, min_height, max_height, tuple(file_types))
    image_cache = ImageCache()

    cached_images = image_cache.get(cache_key)
    if cached_images:
        logging.info(f"Cache hit for {cache_key}")
        return cached_images

    try:
        response = requests.get(url, headers={'Accept-Charset': 'utf-8, iso-8859-1, gbk'})
        soup = BeautifulSoup(response.content, 'html.parser')
        images = [img['src'] for img in soup.find_all('img') if 'src' in img.attrs]
    except Exception as e:
        logging.error(f"Failed to fetch {url}: {e}")
        return []

    processed_images = []
    for image_url in images:
        try:
            if ImageProcessor.is_valid_image(image_url, min_width, max_width, min_height, max_height, file_types):
                img = ImageProcessor.fetch_image(image_url)
                processed_images.append({'url': image_url, 'width': img.width, 'height': img.height})
        except Exception as e:
            logging.error(f"Failed to process {image_url}: {e}")

    image_cache.set(cache_key, processed_images)
    logging.info(f"Cache miss for {cache_key}, fetched {len(processed_images)} images")

    return processed_images
