// Define a simple logger structure for demonstration purposes
typedef struct {
    FILE* logFile;
    int level;
} Logger;

Logger* create_logger(const char* filename, int level) {
    Logger* logger = malloc(sizeof(Logger));
    logger->logFile = fopen(filename, "a");
    if (logger->logFile == NULL) {
        perror("Failed to open log file");
        free(logger);
        return NULL;
    }
    logger->level = level;
    return logger;
}

void destroy_logger(Logger* logger) {
    if (logger != NULL && logger->logFile != NULL) {
        fclose(logger->logFile);
        free(logger);
    }
}

void log_message(Logger* logger, int level, const char* message) {
    if (logger == NULL || logger->logFile == NULL) return;
    if (level > logger->level) return;

    time_t now = time(NULL);
    fprintf(logger->logFile, "[%s] %s\n", ctime(&now), message);
    fflush(logger->logFile);
}

