#include <stdlib.h>
#include <string.h>

// Define the structure for the FSA state
typedef struct FSAState {
    int id;
    struct FSAState** transitions; // Array of pointers to child states
    int numTransitions;
} FSAState;

// Function prototype for selector matching
int matchesSelector(FSAState* element, const char* selector);

// Recursive function to traverse the DOM tree and collect matching states
FSAState** traverseDOM(FSAState* state, const char* selector, FSAState** currentList, int* listSize) {
    if (state == NULL || selector == NULL) {
        return NULL; // Error handling for invalid input
    }

    if (matchesSelector(state, selector)) {
        currentList[*listSize] = state;
        (*listSize)++;
        currentList = realloc(currentList, (*listSize + 1) * sizeof(FSAState*));
        if (currentList == NULL) {
            return NULL; // Memory allocation failure
        }
    }

    for (int i = 0; i < state->numTransitions; i++) {
        FSAState** newList = traverseDOM(state->transitions[i], selector, currentList, listSize);
        if (newList == NULL) {
            return NULL; // Propagate memory allocation failure
        }
    }

    return currentList;
}

// Function to free the allocated memory for the state list
void freeStateList(FSAState** stateList, int size) {
    free(stateList);
}
```

