class CustomJSON:
    _factory_registry = {}
    _schema_cache = {}

    @staticmethod
    def register_factory(factory_id, factory_func):
        CustomJSON._factory_registry[factory_id] = factory_func

    @staticmethod
    def get_factory(factory_id):
        return CustomJSON._factory_registry.get(factory_id)

    @staticmethod
    def add_to_cache(key, value):
        CustomJSON._schema_cache[key] = value

    @staticmethod
    def get_from_cache(key):
        return CustomJSON._schema_cache.get(key)

    @staticmethod
    def parse_json(json_str):
        try:
            data = json.loads(json_str)
            if 'schema_version' in data:
                schema_key = f"{data['schema_version']}"
                cached_schema = CustomJSON.get_from_cache(schema_key)
                if not cached_schema or CustomJSON.schema_needs_upgrade(cached_schema, data['schema_version']):
                    # Upgrade logic here
                    pass
                # Validate against cached schema
            return CustomJSON(data)
        except json.JSONDecodeError as e:
            raise ValueError("Invalid JSON format") from e

    @staticmethod
    def schema_needs_upgrade(current_schema, new_version):
        # Logic to check if upgrade is needed
        return False

    def __init__(self, data):
        self.data = data

    def to_json(self):
        return json.dumps(self.data)

class JSONLoader:
    _cache = {}
    _lock = threading.Lock()
    _update_interval = timedelta(minutes=10)
    _last_update_time = datetime.now() - _update_interval * 2

    @staticmethod
    def load_json(file_path):
        if not os.path.exists(file_path):
            raise FileNotFoundError(f"File not found: {file_path}")

        key = hashlib.md5(file_path.encode()).hexdigest()
        data = JSONLoader._cache.get(key)
        if data and datetime.now() - JSONLoader._last_update_time < JSONLoader._update_interval:
            return data

        with open(file_path, 'r') as file:
            json_str = file.read()
            instance = CustomJSON.parse_json(json_str)
            JSONLoader._cache[key] = instance
            JSONLoader._last_update_time = datetime.now()

        return instance

    @staticmethod
    def update_cache():
        with JSONLoader._lock:
            if datetime.now() - JSONLoader._last_update_time < JSONLoader._update_interval:
                return

            for root, _, files in os.walk('.'):
                for file in files:
                    if file.endswith('.json'):
                        file_path = os.path.join(root, file)
                        try:
                            instance = JSONLoader.load_json(file_path)
                            print(f"Loaded and updated: {file_path}")
                        except Exception as e:
                            logging.error(f"Error loading {file_path}: {e}")

    @staticmethod
    def start_update_thread():
        threading.Thread(target=JSONLoader.update_cache, daemon=True).start()

class JSONConfigManager:
    @staticmethod
    def fetch_and_load_json(url):
        try:
            with urlopen(url) as response:
                json_str = response.read().decode('utf-8')
                instance = CustomJSON.parse_json(json_str)
                return instance
        except Exception as e:
            raise RuntimeError(f"Failed to fetch or parse JSON from {url}") from e

# Example usage
if __name__ == "__main__":
    CustomJSON.register_factory("example", lambda data: CustomJSON(data))
    JSONLoader.start_update_thread()

    # Load local JSON file
    instance = JSONLoader.load_json('path_to_your_local_file.json')
    print(instance.to_json())

    # Fetch and load remote JSON file
    remote_instance = JSONConfigManager.fetch_and_load_json('http://example.com/path_to_remote_file.json')
    print(remote_instance.to_json())
