class JSONHandler:
    registry = {}

    @staticmethod
    def register_factory(id, factory):
        JSONHandler.registry[id] = factory

    @staticmethod
    async def load_json_files(file_paths):
        tasks = [asyncio.to_thread(json.load, open(path)) for path in file_paths]
        return await asyncio.gather(*tasks)

    @staticmethod
    def create_instance(id, *args, **kwargs):
        if id not in JSONHandler.registry:
            raise ValueError(f"No factory registered for ID: {id}")
        return JSONHandler.registry[id](*args, **kwargs)

class ForwardList:
    def __init__(self, elements=None):
        self.elements = elements if elements else []

    def insert(self, first, second, position=None):
        try:
            index = self.elements.index(first)
            if position is None or position == len(self.elements):
                self.elements.insert(index + 1, second)
            elif 0 <= position < len(self.elements):
                self.elements.insert(position, second)
            else:
                raise IndexError("Invalid position index")
        except ValueError:
            self.elements.append(second)

class JSONManager:
    def __init__(self, file_paths):
        self.file_paths = file_paths
        self.json_objects = []
        self.forward_list = ForwardList()

    async def load_files(self):
        json_data = await JSONHandler.load_json_files(self.file_paths)
        for data in json_data:
            obj = JSONHandler.create_instance(data['type'], **data['data'])
            self.json_objects.append(obj)

    def deserialize_from_byte_array(self, byte_array):
        # Placeholder for deserialization logic
        return None

    def hash_password(self, password):
        hashed_password = hashlib.sha256(password.encode()).hexdigest()
        return hashed_password

async def main():
