        algorithms[*num_algorithms].algorithm_name[strcspn(algorithms[*num_algorithms].algorithm_name, "\r\n")] = 0; // Remove newline character
        (*num_algorithms)++;
    }

    fclose(file);
}

void load_cryptography_modules(AlgorithmConfig algorithms[], int num_algorithms) {
    for (int i = 0; i < num_algorithms; i++) {
