            EVP_add_cipher(EVP_aes_256_cbc());
        } else if (strcmp(algorithms[i].algorithm_name, "Camellia") == 0) {
            EVP_add_cipher(EVP_camellia_256_cbc());
        } else if (strcmp(algorithms[i].algorithm_name, "MD5") == 0) {
            EVP_add_digest(EVP_md5());
        } else if (strcmp(algorithms[i].algorithm_name, "SHA-256") == 0) {
            EVP_add_digest(EVP_sha256());
        } else if (strcmp(algorithms[i].algorithm_name, "SHA-512") == 0) {
            EVP_add_digest(EVP_sha512());
        } else if (strcmp(algorithms[i].algorithm_name, "RSA-SHA1") == 0) {
            // Add RSA key exchange and signature verification
        }
    }
}

void handle_errors() {
    ERR_print_errors_fp(stderr);
}

int cryptoLibInit(const char* config_file_path) {
    AlgorithmConfig algorithms[MAX_ALGORITHMS];
    int num_algorithms = 0;

    load_algorithm_config(config_file_path, algorithms, &num_algorithms);

    if (num_algorithms == 0) {
        fprintf(stderr, "No cryptographic algorithms configured.\n");
        return -1;
    }

    load_cryptography_modules(algorithms, num_algorithms);

    handle_errors();

    return 0;
}

// Example usage
