#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_FILENAME_LENGTH 256

typedef struct {
    char *allowed_extensions[];
    int num_digits;
} Config;

Config config = {
    .allowed_extensions = {"txt", "log", "csv"},
    .num_digits = 3
};

int is_valid_filename(const char *filename) {
    // Implement validation logic here
    return filename && strlen(filename) > 0 && !strchr(filename, '\0');
}

void modify_filename(const char *input_filename, const char *prefix, const char *suffix, char *output_filename) {
    if (!is_valid_filename(input_filename)) {
        fprintf(stderr, "Invalid input filename\n");
        return;
    }

    char *base = strdup(input_filename);
    if (!base) {
        perror("strdup");
        return;
    }

    // Remove the last extension
    char *last_dot = strrchr(base, '.');
    if (last_dot) {
        *last_dot = '\0';
    }

    // Construct new filename
    sprintf(output_filename, "%s%s%d.%s%s", prefix ? prefix : "", base, config.num_digits, last_dot + 1, suffix ? suffix : "");

    if (strlen(output_filename) >= MAX_FILENAME_LENGTH) {
        fprintf(stderr, "New filename exceeds maximum length\n");
        free(base);
        return;
    }

    // Validate new filename
    if (!is_valid_filename(output_filename)) {
        fprintf(stderr, "Invalid new filename\n");
        free(base);
        return;
    }

    free(base);
}

int main() {
    const char *input_filename = "example.txt";
    char output_filename[MAX_FILENAME_LENGTH];

    modify_filename(input_filename, "new", "_backup", output_filename);

    printf("New filename: %s\n", output_filename);

    return 0;
}
