import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class DynamicResourcePoolManager {

    private ConcurrentHashMap<String, ResourcePool> poolMap = new ConcurrentHashMap<>();
    private AtomicInteger nextPoolId = new AtomicInteger(0);

    public void initializeResourcePool(int minConnections, int maxConnections, long connectionTimeout) {
        if (minConnections < 1 || maxConnections < minConnections || connectionTimeout <= 0) {
            throw new IllegalArgumentException("Invalid pool configuration");
        }
        ResourcePool pool = new ResourcePool(minConnections, maxConnections, connectionTimeout);
        String poolId = "pool-" + nextPoolId.getAndIncrement();
        poolMap.put(poolId, pool);
    }

    public void initializeResourcePool(int minConnections, int maxConnections, long connectionTimeout, long seed) {
        if (minConnections < 1 || maxConnections < minConnections || connectionTimeout <= 0 || seed <= 0) {
            throw new IllegalArgumentException("Invalid pool configuration");
        }
        ResourcePool pool = new ResourcePool(minConnections, maxConnections, connectionTimeout);
        pool.setSeed(seed);
        String poolId = "pool-" + nextPoolId.getAndIncrement();
        poolMap.put(poolId, pool);
    }

    public <T> void initializeResourcePool(int minConnections, int maxConnections, long connectionTimeout, ConnectionConfigCallback<T> configCallback) {
        if (minConnections < 1 || maxConnections < minConnections || connectionTimeout <= 0) {
            throw new IllegalArgumentException("Invalid pool configuration");
        }
        ResourcePool pool = new ResourcePool(minConnections, maxConnections, connectionTimeout);
        pool.setConnectionConfig(configCallback.apply(pool.getConnectionConfig()));
        String poolId = "pool-" + nextPoolId.getAndIncrement();
        poolMap.put(poolId, pool);
    }

    public void removeResourcePool(String poolId) {
        poolMap.remove(poolId);
    }

    public ResourcePool getResourcePool(String poolId) {
        return poolMap.get(poolId);
    }
}

@FunctionalInterface
interface ConnectionConfigCallback<T> {
    T apply(T config);
}

class ResourcePool {
    // Implementation of ResourcePool with all required methods and fields
}
