#include <iostream>
#include <forward_list>
#include <memory>
#include <string>
#include <stdexcept>

// Define LogEntry structure
struct LogEntry {
    std::string level;
    std::string message;

    LogEntry(const std::string& lvl, const std::string& msg)
        : level(lvl), message(msg) {}
};

// Forward declare the external logging function
void sendLogToAPI(const LogEntry& entry);

namespace {
    const int MAX_API_RETRIES = 5;
}

class Logger {
public:
    static void insertAndLog(std::forward_list<std::shared_ptr<LogEntry>>& logList,
                             std::string level,
                             std::string message,
                             size_t numInsertions = 1) {
        try {
            auto it = std::find_if(logList.begin(), logList.end(),
                                   [&level](const std::shared_ptr<LogEntry>& entry) {
                                       return entry->level == level;
                                   });

            if (it != logList.end()) {
                for (size_t i = 0; i < numInsertions; ++i) {
                    it = logList.insert_after(it, std::make_shared<LogEntry>(level, message));
                }
            } else {
                auto lastIt = logList.before_begin();
                for (size_t i = 0; i < numInsertions; ++i) {
                    lastIt = logList.insert_after(lastIt, std::make_shared<LogEntry>(level, message));
                }
            }

            // Log to API
            int retries = 0;
            while (retries < MAX_API_RETRIES) {
                try {
                    for (auto& entry : logList) {
                        sendLogToAPI(*entry);
                    }
                    break;
                } catch (const std::runtime_error& e) {
                    if (++retries == MAX_API_RETRIES) {
                        throw std::runtime_error("Failed to log entries to API after " + std::to_string(retries) + " retries");
                    }
                    std::this_thread::sleep_for(std::chrono::seconds(1)); // Wait before retrying
                }
            }
        } catch (const std::exception& e) {
            std::cerr << "Error: " << e.what() << std::endl;
        }
    }
};
