using System;
using System.Data;
using System.Data.SqlClient;
using System.Data.Linq;

public class DatabaseManager
{
    public static DataTable ExecuteSqlQuery(string connectionString, string query)
    {
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            SqlCommand command = new SqlCommand(query, connection);
            SqlDataAdapter adapter = new SqlDataAdapter(command);
            DataTable dataTable = new DataTable();
            try
            {
                connection.Open();
                adapter.Fill(dataTable);
            }
            catch (Exception ex)
            {
                // Log the exception details
                Console.WriteLine("Error executing SQL query: " + ex.Message);
            }
            return dataTable;
        }
    }

    public static void ExecuteNoSqlQuery(string connectionString, string query)
    {
        using (var client = new MongoClient(connectionString))
        {
            var database = client.GetDatabase("yourDatabaseName");
            var collection = database.GetCollection<BsonDocument>("yourCollectionName");

            try
            {
                // Execute NoSQL query here
                var result = collection.Find(query).ToList();
            }
            catch (Exception ex)
            {
                // Log the exception details
                Console.WriteLine("Error executing NoSQL query: " + ex.Message);
            }
        }
    }

    public static void SynchronizeData(string sqlConnectionString, string noSqlConnectionString)
    {
        DataTable sqlData = ExecuteSqlQuery(sqlConnectionString, "SELECT * FROM YourTable");
        using (var client = new MongoClient(noSqlConnectionString))
        {
            var database = client.GetDatabase("yourNoSqlDatabaseName");
            var collection = database.GetCollection<BsonDocument>("yourNoSqlCollectionName");

            try
            {
                // Synchronize data from SQL to NoSQL
                foreach (DataRow row in sqlData.Rows)
                {
                    var document = new BsonDocument
                    {
                        { "Id", row["Id"].ToString() },
                        { "Column1", row["Column1"].ToString() },
                        { "Column2", row["Column2"].ToString() }
                    };
                    collection.InsertOne(document);
                }
            }
            catch (Exception ex)
            {
                // Log the exception details
                Console.WriteLine("Error synchronizing data: " + ex.Message);
            }
        }
    }
}
