```rust
use std::fs;
use std::path::Path;
use std::sync::{Arc, Mutex};
use std::thread;
use log::{info, error, warn};

struct CompilationTask {
    file_path: String,
}

fn compile_file(file_path: &str) -> Result<(), String> {
    // Simulate compilation process
    if file_path.contains("error") {
        Err(format!("Failed to compile {}", file_path))
    } else {
        Ok(())
    }
}

fn parallel_compile_files(tasks: Vec<CompilationTask>, max_threads: usize) -> Vec<String> {
    let mut handles = vec![];
    let results = Arc::new(Mutex::new(vec![]));

    for task in tasks {
        let results_clone = Arc::clone(&results);
        let handle = thread::spawn(move || {
            match compile_file(&task.file_path) {
                Ok(_) => info!("Compiled {}", task.file_path),
                Err(e) => error!("Error compiling {}: {}", task.file_path, e),
            }
            results_clone.lock().unwrap().push(task.file_path.clone());
        });
        handles.push(handle);
    }

    for handle in handles {
        if let Err(e) = handle.join() {
            warn!("Thread panicked: {:?}", e);
        }
    }

    Arc::try_unwrap(results)
        .expect("Too many threads")
        .into_inner()
}

fn main() {
    let file_paths = vec![
        "src/main.rs",
        "src/lib.rs",
        "tests/unit_tests.rs",
        "tests/integration_tests.rs",
        // Add more file paths as needed
    ];

    let tasks: Vec<CompilationTask> = file_paths.iter().map(|&p| CompilationTask { file_path: p.to_string() }).collect();

    info!("Starting compilation with {} threads", thread::available_parallelism().unwrap_or(1).get());
    parallel_compile_files(tasks, thread::available_parallelism().unwrap_or(1).get());
}
```

