```csharp
using System;

public class HighPerformanceRandomValueGenerator
{
    private double minValue;
    private double maxValue;
    private Random random;
    private string distributionType;

    public HighPerformanceRandomValueGenerator(double min, double max, string distribution)
    {
        if (min >= max) throw new ArgumentException("Min value must be less than max value.");
        minValue = min;
        maxValue = max;
        random = new Random();
        distributionType = distribution.ToLower();

        if (!IsValidDistribution(distributionType))
        {
            throw new ArgumentException("Unsupported distribution type.");
        }
    }

    private bool IsValidDistribution(string distribution)
    {
        return distribution == "uniform" || distribution == "normal";
    }

    public double GenerateRandomValue()
    {
        switch (distributionType)
        {
            case "uniform":
                return random.NextDouble() * (maxValue - minValue) + minValue;
            case "normal":
                double mean = (minValue + maxValue) / 2;
                double stdDev = Math.Abs(maxValue - minValue) / 4; // Assuming a rough approximation
                double value;
                do
                {
                    value = random.NextDouble() * (maxValue - minValue) + minValue;
                } while ((value - mean) * (value - mean) > 2 * stdDev * stdDev);
                return value;
            default:
                throw new ArgumentException("Invalid distribution type.");
        }
    }

    public double GenerateRandomQuantile(double quantile)
    {
        if (quantile < 0 || quantile > 1) throw new ArgumentException("Quantile must be between 0 and 1.");
        double[] quantiles = { minValue, maxValue };
        Array.Sort(quantiles);
        return quantiles[Math.Min((int)(quantiles.Length * quantile), quantiles.Length - 1)];
    }

    public int GenerateRandomStandardDeviation(int standardDeviations)
    {
        if (standardDeviations < 0) throw new ArgumentException("Standard deviations must be non-negative.");
        double mean = (minValue + maxValue) / 2;
        double stdDev = Math.Abs(maxValue - minValue) / 4; // Assuming a rough approximation
        double value;
        do
        {
            value = random.NextDouble() * (maxValue - minValue) + minValue;
        } while ((value - mean) * (value - mean) > standardDeviations * standardDeviations * stdDev * stdDev);
        return (int)value;
    }

    public override string ToString()
    {
        return $"Range: {minValue}-{maxValue}, Distribution: {distributionType}";
    }
}
