#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <pthread.h>

// Define the URL structure
typedef struct {
    char *url;
} URL;

// Define the worker thread function
void* worker_thread(void* arg) {
    URL *url = (URL *)arg;
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url->url);
        res = curl_easy_perform(curl);

        if(res != CURLE_OK)
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));

        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();
    free(url->url);
    free(url);

    pthread_exit(NULL);
}

// Define the dynamic thread pool manager
void manage_thread_pool(URL *urls, int num_urls, int concurrency) {
    pthread_t threads[concurrency];

    for(int i = 0; i < num_urls; i++) {
        if(i % concurrency == 0 && i != 0) {
            // Wait for all threads to finish
            for(int j = 0; j < concurrency; j++)
                pthread_join(threads[j], NULL);
        }

        URL *url = (URL *)malloc(sizeof(URL));
        url->url = strdup(urls[i].url);
        int rc = pthread_create(&threads[i % concurrency], NULL, worker_thread, (void*)url);
        if(rc) {
            fprintf(stderr, "Error: unable to create thread %d\n", rc);
            exit(-1);
        }
    }

    // Wait for all remaining threads
    for(int i = 0; i < num_urls % concurrency; i++)
        pthread_join(threads[i], NULL);
}

int main() {
    URL urls[] = {{"http://example.com"}, {"http://example.org"}};
    int num_urls = sizeof(urls) / sizeof(urls[0]);
    int concurrency = 2;

    manage_thread_pool(urls, num_urls, concurrency);

    return 0;
}
