public class RandomValueGenerator
{
    private static readonly ILog log = LogManager.GetLogger(typeof(RandomValueGenerator));

    public float GenerateRandomFloat(float min, float max)
    {
        lock (this)
        {
            var random = new Random();
            var value = (float)(random.NextDouble() * (max - min) + min);
            log.Info($"Generated random float: {value}");
            return value;
        }
    }

    public double GenerateRandomFloatNormal(double mean, double standardDeviation)
    {
        lock (this)
        {
            var random = new Random();
            var value = random.NextDouble() * 2.0 - 1.0;
            value = Math.Sqrt(-2.0 * Math.Log(1.0 - value)) * standardDeviation + mean;
            log.Info($"Generated random float from normal distribution: {value}");
            return value;
        }
    }

    public double GenerateRandomFloatLogarithmic(double scale)
    {
        lock (this)
        {
            var random = new Random();
            var value = Math.Exp(random.NextDouble() * scale);
            log.Info($"Generated random float from logarithmic distribution: {value}");
            return value;
        }
    }
}

