            if (elements == null || !elements.Any())
            {
                log.Error($"No elements found for selector: {selector}");
                throw new InvalidOperationException("Element not found");
            }
            return elements;
        }
        catch (Exception ex)
        {
            log.Error($"Error finding elements by selector: {ex.Message}", ex);
