#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <time.h>

#define MAX_LINE_LENGTH 1024
#define LOG_FILE "application.log"

typedef struct {
    double *values;
    int count;
} LineData;

void log_message(int level, const char *format, ...) {
    time_t current_time = time(NULL);
    char formatted_time[80];
    strftime(formatted_time, sizeof(formatted_time), "%Y-%m-%d %H:%M:%S", localtime(&current_time));

    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        printf("Error opening log file\n");
        return;
    }

    fprintf(log, "[%s] ", formatted_time);
    if (level == 1) fprintf(log, "[INFO] ");
    else if (level == 2) fprintf(log, "[WARNING] ");
    else fprintf(log, "[ERROR] ");

    va_list args;
    va_start(args, format);
    vfprintf(log, format, args);
    va_end(args);

    fprintf(log, "\n");
    fclose(log);
}

LineData* parse_line(const char *line) {
    LineData *data = (LineData *)malloc(sizeof(LineData));
    data->values = NULL;
    data->count = 0;

    char *token = strtok((char *)line, " ");
    while (token != NULL && isdigit(*token)) {
        data->values = realloc(data->values, (data->count + 1) * sizeof(double));
        data->values[data->count] = atof(token);
        data->count++;
        token = strtok(NULL, " ");
    }

    return data;
}

void process_line(const LineData *line_data, FILE *output_file) {
    if (line_data->count < 3) {
        log_message(2, "Skipping line with less than three numerical values: %s", line_data->values);
        return;
    }

    double sum = line_data->values[line_data->count - 1] +
                 line_data->values[line_data->count - 2] +
                 line_data->values[line_data->count - 3];
    double average = sum / 3.0;

    fprintf(output_file, "%.2f\n", average);
}

void process_file(const char *input_file, const char *output_file) {
    FILE *in_file = fopen(input_file, "r");
    if (in_file == NULL) {
        log_message(1, "Error opening input file: %s", input_file);
        return;
    }

    FILE *out_file = fopen(output_file, "w");
    if (out_file == NULL) {
        log_message(1, "Error opening output file: %s", output_file);
        fclose(in_file);
        return;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), in_file) != NULL) {
        LineData *line_data = parse_line(line);
        if (line_data == NULL) {
            log_message(1, "Error parsing line: %s", line);
            continue;
        }

        process_line(line_data, out_file);

        free(line_data->values);
        free(line_data);
    }

    fclose(in_file);
    fclose(out_file);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s <input_file> <output_file>\n", argv[0]);
        return 1;
    }

    process_file(argv[1], argv[2]);

    return 0;
}
