import json
from typing import Any, Callable, Dict, Type, TypeVar

T = TypeVar('T')

class JSONParser:
    _registry: Dict[str, Callable[[Dict], T]] = {}

    @classmethod
    def add_factory(cls, obj_type_id: str, factory_func: Callable[[Dict], T]) -> None:
        cls._registry[obj_type_id] = factory_func

    @classmethod
    def get_factory(cls, obj_type_id: str) -> Callable[[Dict], T]:
        return cls._registry.get(obj_type_id)

    @staticmethod
    def serialize(obj: Any) -> str:
        if isinstance(obj, dict):
            return json.dumps(obj)
        elif hasattr(obj, '__dict__'):
            return json.dumps(obj.__dict__)
        else:
            raise TypeError(f"Unsupported type for serialization: {type(obj)}")

    @classmethod
    def deserialize(cls, json_str: str) -> Any:
        data = json.loads(json_str)
        obj_type_id = data.get('obj_type')
        if obj_type_id in cls._registry:
            factory_func = cls._registry[obj_type_id]
            return factory_func(data)
        else:
            raise ValueError(f"Unknown object type ID: {obj_type_id}")

# Example usage
class User(JSONParser):
    def __init__(self, name: str, age: int):
        self.name = name
        self.age = age

    @classmethod
    def from_json(cls, data: Dict) -> 'User':
        return cls(name=data['name'], age=data['age'])

JSONParser.add_factory('user', User.from_json)

# Serialization
user = User("John Doe", 30)
json_str = JSONParser.serialize(user)
print(json_str)  # Output: {"obj_type": "user", "name": "John Doe", "age": 30}

# Deserialization
new_user = JSONParser.deserialize(json_str)
print(new_user.name, new_user.age)  # Output: John Doe 30
