#include <iostream>
#include <string>
#include <random>
#include <chrono>
#include <fstream>
#include <redis++.h>
#include <memcached/memcache.h>

class SessionIDManager {
public:
    SessionIDManager(const std::string& serverIP, const std::string& memcachedServer)
        : generator_(std::random_device()()),
          dist_(0, 127),
          redisClient_(serverIP + ":6379"),
          memcacheClient_(memcachedServer.c_str()) {}

    std::string generateSessionID() {
        try {
            // Generate a unique session ID
            std::string sessionId = generateUniqueID();
            if (sessionId.empty()) {
                throw std::runtime_error("Failed to generate unique session ID.");
            }

            // Cache the session ID in Memcached
            memcacheClient_.set(sessionId, "1");

            return sessionId;
        } catch (const std::exception& e) {
            std::cerr << "Error generating session ID: " << e.what() << std::endl;
            // Fallback mechanism
            return generateFallbackSessionID();
        }
    }

private:
    std::mt19937_64 generator_;
    std::uniform_int_distribution<int> dist_;

    redis::client redisClient_;
    memcached_st* memcacheClient_;

    std::string generateUniqueID() {
        // Generate a secure random string
        std::string sessionId;
        for (int i = 0; i < 22; ++i) {
            sessionId += static_cast<char>(dist_(generator_));
        }

        // Check if the session ID already exists in Redis
        redis::value value = redisClient_.get(sessionId);
        if (!value.empty()) {
            return ""; // Duplicate, generate again
        }

        return sessionId;
    }

    std::string generateFallbackSessionID() {
        // Fallback mechanism to generate a random string
        std::string fallbackId;
        for (int i = 0; i < 22; ++i) {
            fallbackId += static_cast<char>(dist_(generator_));
        }
        return fallbackId;
    }
};

int main() {
    SessionIDManager manager("192.168.1.1", "127.0.0.1:11211");
    std::string sessionId = manager.generateSessionID();
    if (!sessionId.empty()) {
        std::cout << "Generated session ID: " << sessionId << std::endl;
    } else {
        std::cerr << "Failed to generate session ID." << std::endl;
    }
    return 0;
}
