import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class ServiceManager {
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(2);
    private boolean isRunning = false;
    private long heartbeatInterval = 10; // in seconds

    public void startService() {
        if (isRunning) return;
        isRunning = true;
        scheduler.scheduleAtFixedRate(this::monitorService, 0, heartbeatInterval, TimeUnit.SECONDS);
        System.out.println("Service started.");
    }

    public void stopService() {
        if (!isRunning) return;
        isRunning = false;
        scheduler.shutdown();
        System.out.println("Service stopped.");
    }

    private void monitorService() {
        try {
            // Simulate API call
            fetchConfigFromAPI();
            logStatusToMonitoringSystem();
            sendHeartbeatMessage();
        } catch (Exception e) {
            handleFailure(e);
        }
    }

    private void fetchConfigFromAPI() throws Exception {
        System.out.println("Fetching config from API...");
        // Code to interact with external API
    }

    private void logStatusToMonitoringSystem() {
        System.out.println("Logging status to monitoring system...");
        // Code to send logs
    }

    private void sendHeartbeatMessage() {
        System.out.println("Sending heartbeat message...");
        // Code to send heartbeat
