### C++ Code for Octree Initialization

```cpp
#include <mutex>
#include <vector>
#include <memory>

class Node {
public:
    std::array<std::shared_ptr<Node>, 8> children;
    // Other members and methods
};

Node* createOctree(size_t sizeLimit, const std::vector<Point>& points) {
    if (points.size() > sizeLimit) return nullptr;

    std::lock_guard<std::mutex> lock(mutex);
    auto root = std::make_shared<Node>();
    // Initialize the octree with the given points
    for (const auto& point : points) {
        insert(root, point);
    }
    return root.get();
}

void insert(std::shared_ptr<Node>& node, const Point& point) {
    if (!node) {
        node = std::make_shared<Node>();
    }

    // Determine the child node based on the point's coordinates
    int index = 0;
    for (int i = 0; i < 3; ++i) {
        index |= ((point[i] > node->bounds.min[i]) << i);
    }

    if (!node->children[index]) {
        node->children[index] = std::make_shared<Node>();
    }
    insert(node->children[index], point);
}

// Other methods for the octree (e.g., search, remove)
