class DynamicOctreeSpatialPartitioner {
public:
    struct Node {
        std::vector<Node*> children;
        std::vector<DataPoint> data;
        std::mutex lock;

        Node() : children(8), data() {}
    };

    struct DataPoint {
        // Define the structure of a data point
    };

    DynamicOctreeSpatialPartitioner(double minBound, double maxBound) 
        : root(new Node()), minBound(minBound), maxBound(maxBound) {}

    ~DynamicOctreeSpatialPartitioner() {
        deleteTree(root);
    }

    void addDataPoint(const DataPoint& point) {
        std::lock_guard<std::mutex> lock(root->lock);
        insert(point, root, minBound, maxBound);
    }

    std::vector<DataPoint> query(double x, double y, double z, double radius) {
        std::lock_guard<std::mutex> lock(root->lock);
        return search(queryNode(x, y, z), radius);
    }

private:
    Node* root;
    double minBound;
    double maxBound;

    void deleteTree(Node* node) {
        for (auto child : node->children)
            deleteTree(child);
        delete node;
    }

    void insert(const DataPoint& point, Node* node, double minX, double maxX, double minY, double maxY, double minZ, double maxZ) {
        if (node->data.size() < MAX_NODE_CAPACITY && !node->children[0]) {
            node->data.push_back(point);
        } else {
            subdivide(node, minX, maxX, minY, maxY, minZ, maxZ);
            int index = determineChildIndex(point, minX, maxX, minY, maxY, minZ, maxZ);
            insert(point, node->children[index], minX, maxX, minY, maxY, minZ, maxZ);
        }
    }

    void subdivide(Node* node, double minX, double maxX, double minY, double maxY, double minZ, double maxZ) {
        double sizeX = (maxX - minX) / 2;
        double sizeY = (maxY - minY) / 2;
        double sizeZ = (maxZ - minZ) / 2;

        for (int i = 0; i < 8; ++i) {
            int xIndex = (i & 1) ? 1 : 0;
            int yIndex = (i & 2) ? 1 : 0;
            int zIndex = (i & 4) ? 1 : 0;

            node->children[i] = new Node();
            node->children[i]->lock = std::mutex();

            double xMin = minX + xIndex * sizeX;
            double xMax = xMin + sizeX;
            double yMin = minY + yIndex * sizeY;
            double yMax = yMin + sizeY;
            double zMin = minZ + zIndex * sizeZ;
            double zMax = zMin + sizeZ;

            subdivide(node->children[i], xMin, xMax, yMin, yMax, zMin, zMax);
        }
    }

    int determineChildIndex(const DataPoint& point, double minX, double maxX, double minY, double maxY, double minZ, double maxZ) {
        int index = 0;

        if (point.x > (minX + maxX) / 2) index |= 1;
        if (point.y > (minY + maxY) / 2) index |= 2;
        if (point.z > (minZ + maxZ) / 2) index |= 4;

        return index;
    }

