```javascript
function findElementsBySelector(element, selector, callback) {
    if (!element || !selector || typeof callback !== 'function')
        throw new Error('Invalid input');

    let result = [];

    function traverse(node) {
        if (node.nodeType === Node.ELEMENT_NODE && (node.classList.contains(selector) || node.id === selector)) {
            if (callback(node)) {
                result.push(node);
            }
        }

        for (let child of Array.from(node.children)) {
            traverse(child);
        }
    }

    traverse(element);
    return result;
}
