```c
#include <stdio.h>
#include <stdlib.h>

#define MAX_NODES 1000

typedef struct Node {
    int data;
    struct Node* next;
} Node;

typedef struct GraphNode {
    Node* head;
} GraphNode;

typedef struct QueueNode {
    int data;
    struct QueueNode* next;
} QueueNode;

void enqueue(QueueNode** front, QueueNode** rear, int item) {
    QueueNode* temp = (QueueNode*)malloc(sizeof(QueueNode));
    temp->data = item;
    temp->next = NULL;
    if (*front == NULL)
        *front = *rear = temp;
    else {
        (*rear)->next = temp;
        *rear = temp;
    }
}

int dequeue(QueueNode** front, QueueNode** rear) {
    if (*front == NULL)
        return -1; // Empty queue
    int item = (*front)->data;
    QueueNode* temp = *front;
    *front = (*front)->next;
    if (*front == NULL)
        *rear = NULL;
    free(temp);
    return item;
}

int* bfsReachableNodes(GraphNode* graph, int totalNodes, int startNode, int maxHops) {
    if (startNode < 0 || startNode >= totalNodes) {
        printf("Invalid starting node.\n");
        return NULL;
    }

    Node** visited = (Node**)calloc(totalNodes, sizeof(Node*));
    QueueNode* queueFront = NULL, *queueRear = NULL;

    enqueue(&queueFront, &queueRear, startNode);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = startNode;
    newNode->next = NULL;
    visited[startNode] = newNode;

    int currentHops = 0;
    while (queueFront != NULL && currentHops < maxHops) {
        int queueSize = queueRear - queueFront + 1;
        for (int i = 0; i < queueSize; i++) {
            int currentNode = dequeue(&queueFront, &queueRear);
            Node* temp = graph[currentNode].head;

            while (temp != NULL) {
                if (!visited[temp->data]) {
                    visited[temp->data] = (Node*)malloc(sizeof(Node));
                    visited[temp->data]->data = temp->data;
                    visited[temp->data]->next = newNode->next;
                    newNode->next = visited[temp->data];
                    enqueue(&queueFront, &queueRear, temp->data);
                }
                temp = temp->next;
            }
        }
        currentHops++;
    }

    int* result = (int*)malloc((newNode->next == NULL) ? 1 : (newNode->next->data + 1) * sizeof(int));
    if (result == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    Node* temp = newNode->next;
    int index = 0;
    while (temp != NULL) {
        result[index++] = temp->data;
        Node* nextTemp = temp->next;
        free(temp);
        temp = nextTemp;
    }
    newNode->next = NULL;

    return result;
}
