    _registry = {}

    class ForwardList:
        def __init__(self):
            self.items = []

        def insert(self, after, new_item, position=None):
            if position is None or position < 0 or position > len(self.items) - self.items[::-1].index(after) - 1:
                position = len(self.items)
            index = self.items.index(after) + 1
            for _ in range(position - index):
