<?php

/**
 * Generates a secure random string using a given character set.
 *
 * @param int $length The desired length of the token.
 * @param string $charset The character set to use for generating the token.
 * @return string A secure random string.
 */
function generateSecureToken($length, $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') {
    if ($length <= 0) {
        throw new InvalidArgumentException('Length must be a positive integer.');
    }

    if (empty($charset)) {
        throw new InvalidArgumentException('Character set cannot be empty.');
    }

    $token = '';
    $charCount = strlen($charset);

    for ($i = 0; $i < $length; $i++) {
        $index = random_int(0, $charCount - 1);
        $token .= $charset[$index];
    }

    return $token;
}

/**
 * Hashes a password using the specified algorithm and salt.
 *
 * @param string $password The password to hash.
 * @param string $algorithm The hashing algorithm (e.g., 'bcrypt', 'argon2id').
 * @return string The hashed password.
 */
function hashPassword($password, $algorithm = PASSWORD_BCRYPT) {
    $salt = bin2hex(random_bytes(16));
    return password_hash($password . $salt, $algorithm);
}

/**
 * Validates the strength of a token based on specified criteria.
 *
 * @param string $token The token to validate.
 * @return bool True if the token meets the criteria, false otherwise.
 */
function validateTokenStrength($token) {
    // Add your validation logic here
    return true; // Replace with actual validation logic
}

/**
 * Regenerates a session token periodically for security reasons.
 *
 * @param string $sessionName The name of the session to regenerate.
 * @return void
 */
function regenerateSessionToken($sessionName = 'PHPSESSID') {
    if (isset($_SESSION[$sessionName])) {
        $_SESSION[$sessionName] = generateSecureToken(session_id());
    }
}

/**
 * Implements rate limiting to prevent brute-force attacks on token generation.
 *
 * @param int $maxAttempts The maximum number of attempts allowed.
 * @param int $interval The time interval in seconds for the rate limit.
 * @return bool True if the request is allowed, false otherwise.
 */
function applyRateLimit($maxAttempts = 10, $interval = 60) {
    $currentTimestamp = time();
    $attemptCount = filter_input(INPUT_SESSION, 'rate_limit_attempts', FILTER_SANITIZE_NUMBER_INT) ?: 0;
    $lastAttemptTime = filter_input(INPUT_SESSION, 'rate_limit_time', FILTER_SANITIZE_NUMBER_INT) ?: 0;

    if ($currentTimestamp - $lastAttemptTime >= $interval) {
        $attemptCount = 1;
        $_SESSION['rate_limit_attempts'] = $attemptCount;
        $_SESSION['rate_limit_time'] = $currentTimestamp;
    } elseif ($attemptCount >= $maxAttempts) {
        return false; // Exceeded rate limit
    }

    $_SESSION['rate_limit_attempts']++;
    return true;
}

