const fs = require('fs');
const path = require('path');

/**
 * Reads a file synchronously from a directory and returns its contents as a string.
 *
 * @param {string} filePath - The path to the file to read.
 * @returns {Promise<string>} A promise that resolves with the file's content or rejects on error.
 */
function readFileAsync(filePath) {
    return new Promise((resolve, reject) => {
        fs.readFile(filePath, (err, data) => {
            if (err) {
                if (err.code === 'ENOENT') {
                    reject(new Error('File not found.'));
                } else if (err.code === 'EACCES') {
                    reject(new Error('Permission denied.'));
                } else {
                    reject(new Error(`Read error: ${err.message}`));
                }
            } else {
                const fileExtension = path.extname(filePath).toLowerCase();
                let content;

                switch (fileExtension) {
                    case '.txt':
                        content = data.toString();
                        break;
                    // Add support for other file types here
                    default:
                        reject(new Error('Unsupported file type.'));
                        return;
                }

                resolve(content);
            }
        });
    });
}

module.exports = { readFileAsync };
