// Function to initialize and use semaphore for thread synchronization
void use_semaphore(sem_t *sem, int size) {
    sem_init(sem, 0, 1); // Initialize semaphore

    for (int i = 0; i < size; i++) {
        sem_wait(sem);
        // Perform operations on shared resource here
        sem_post(sem);
    }

    sem_destroy(sem);
}

// Function to handle dynamic memory allocation and initialization of arrays
void initialize_arrays(int *long_offsets, int *keys, int size) {
    long_offsets = (long *)malloc(size * sizeof(long));
    keys = (int *)malloc(size * sizeof(int));

    if (long_offsets == NULL || keys == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Populate arrays with random values
    for (int i = 0; i < size; i++) {
        long_offsets[i] = rand();
        keys[i] = rand() % 100; // Random value within range [0, 99]
    }
}

// Function to handle asynchronous file loading
void load_files_async(char **file_list, int num_files) {
    sem_t sem;

    sem_init(&sem, 0, 1); // Initialize semaphore

    for (int i = 0; i < num_files; i++) {
        sem_wait(&sem);

        FILE *file = fopen(file_list[i], "r");
        if (file == NULL) {
            fprintf(stderr, "Error opening file %s\n", file_list[i]);
            exit(EXIT_FAILURE);
        }

        // Perform file loading operations here

        fclose(file);
        sem_post(&sem);
    }

    sem_destroy(&sem);
}

