import os
import argparse
import re
from datetime import datetime

def parse_log_files(directory, exclude_extensions):
    device_stats = {}

    for root, _, files in os.walk(directory):
        for file in files:
            if any(file.endswith(ext) for ext in exclude_extensions):
                continue

            file_path = os.path.join(root, file)
            try:
                with open(file_path, 'r') as f:
                    lines = f.readlines()

                    device_id_match = re.search(r'DeviceID=([\w-]+)', lines[0])
                    if device_id_match:
                        device_id = device_id_match.group(1)

                        time_stamp_match = re.search(r'TimeStamp=(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})', lines[0])
                        if time_stamp_match:
                            time_stamp = datetime.strptime(time_stamp_match.group(1), '%Y-%m-%d %H:%M:%S')

                            device_stats.setdefault(device_id, {'total_lines': 0, 'total_words': 0, 'total_chars': 0, 'logs': []})
                            log_entry = {
                                'file_path': file_path,
                                'time_stamp': time_stamp
                            }
                            device_stats[device_id]['logs'].append(log_entry)

                            for line in lines:
                                device_stats[device_id]['total_lines'] += 1
                                words = line.split()
                                device_stats[device_id]['total_words'] += len(words)
                                device_stats[device_id]['total_chars'] += len(line)
            except (FileNotFoundError, PermissionError) as e:
                print(f"Error processing file {file_path}: {e}")

    return device_stats

def main():
    parser = argparse.ArgumentParser(description='Process IoT log files')
    parser.add_argument('directory', type=str, help='Directory containing the log files')
    parser.add_argument('--output_file', type=str, help='Optional output file for results')
    parser.add_argument('--exclude_extensions', nargs='+', default=['.log', '.txt'], help='File extensions to exclude')

    args = parser.parse_args()

    device_stats = parse_log_files(args.directory, args.exclude_extensions)

    if args.output_file:
        with open(args.output_file, 'w') as f:
            for device_id, stats in device_stats.items():
                f.write(f"Device ID: {device_id}\n")
                f.write(f"Total Lines: {stats['total_lines']}\n")
                f.write(f"Total Words: {stats['total_words']}\n")
                f.write(f"Total Characters: {stats['total_chars']}\n")
                f.write("Logs:\n")
                for log in stats['logs']:
                    f.write(f"  File Path: {log['file_path']}, Time Stamp: {log['time_stamp']}\n")
    else:
        for device_id, stats in device_stats.items():
            print(f"Device ID: {device_id}")
            print(f"Total Lines: {stats['total_lines']}")
            print(f"Total Words: {stats['total_words']}")
            print(f"Total Characters: {stats['total_chars']}")
            print("Logs:")
            for log in stats['logs']:
                print(f"  File Path: {log['file_path']}, Time Stamp: {log['time_stamp']}")

if __name__ == '__main__':
    main()
```

```c
#include <stdio.h>
#include <string.h>
#include <arpa/inet.h>

typedef unsigned char u_char;
#define MAX_IP_LENGTH 40

int resolveHostWithTimeout(const char *hostname, u_char *ipAddress, size_t ipAddressLength, const char *dnsServers[], int timeout) {
    if (!hostname || !ipAddress || !dnsServers || timeout <= 0) {
        return -1; // Invalid input
    }

    struct addrinfo hints, *res = NULL;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 and IPv6
    hints.ai_socktype = SOCK_STREAM;

    int status = getaddrinfo(hostname, NULL, &hints, &res);
    if (status != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -2; // DNS resolution failed
    }

    for (struct addrinfo *p = res; p != NULL; p = p->ai_next) {
        void *addr;
        char ipstr[INET6_ADDRSTRLEN];

        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        inet_ntop(p->ai_family, addr, ipstr, sizeof(ipstr));

        if (strlen(ipstr) > ipAddressLength - 1) {
            freeaddrinfo(res);
            return -3; // Insufficient space for IP address
        }

        strcpy((char *)ipAddress, ipstr);
        break;
    }

    freeaddrinfo(res);
    return 0; // Success
}

// Example usage
int main() {
    u_char ipAddress[MAX_IP_LENGTH];
    const char *hostname = "www.example.com";
    const char *dnsServers[] = {"8.8.8.8", "8.8.4.4"};

    int result = resolveHostWithTimeout(hostname, ipAddress, sizeof(ipAddress), dnsServers, 5);
    if (result == 0) {
        printf("Resolved IP: %s\n", ipAddress);
    } else {
        printf("Failed to resolve host.\n");
    }

    return 0;
}
