using namespace std;
using websocketpp::server<websocketpp::config::asio> server;

// Function to fetch attack names from the external database
vector<string> fetchAttacksFromDatabase(const string& characterType) {
    vector<string> attacks;
    CURL *curl;
    CURLcode res;
    curl = curl_easy_init();
    if(curl) {
        string url = "http://example.com/attacks?type=" + characterType;
        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, [](void* contents, size_t size, size_t nmemb, void* userp){
            ((string*)userp)->append((char*)contents, size * nmemb);
            return size * nmemb;
        });
        string response;
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);
        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            cerr << "cURL error: " << curl_easy_strerror(res) << endl;
        } else {
            regex attackRegex("\"name\":\"([^\"]+)\"");
            sregex_iterator iter(response.begin(), response.end(), attackRegex), end;
            while(iter != end) {
                attacks.push_back((*iter)[1]);
                ++iter;
            }
        }
        curl_easy_cleanup(curl);
    }
    return attacks;
}

// Function to select an attack based on the cooldown period and user-provided text
string selectAttack(const string& characterType, const string& userInput, unordered_map<string, int>& cooldowns) {
    static mutex mtx;
    lock_guard<mutex> guard(mtx); // Ensure thread safety

    vector<string> attacks = fetchAttacksFromDatabase(characterType);

    regex inputRegex("([a-zA-Z]+)");
    sregex_iterator iter(userInput.begin(), userInput.end(), inputRegex), end;
    string selectedAttack;

    while(iter != end) {
        for(const auto& attack : attacks) {
            if(regex_match((*iter)[1], regex(attack))) {
                int currentCooldown = cooldowns[attack];
                if(currentCooldown <= 0) {
                    selectedAttack = attack;
                    cooldowns[attack] = 5; // Set a cooldown period
                    break;
                }
            }
        }
        if(!selectedAttack.empty()) break;
        ++iter;
    }

    return selectedAttack.empty() ? "No valid attacks found" : selectedAttack;
}

// WebSocket server for real-time updates
void on_message(server* s, websocketpp::connection_hdl hdl, server::message_ptr msg) {
    string payload = msg->get_payload();
    // Broadcast the new attack database to all connected clients
}

int main() {
    server echo_server;
    echo_server.init_asio();

    echo_server.set_message_handler(bind(&on_message, &echo_server, ::_1, ::_2));

    echo_server.listen(9002);
    echo_server.start_accept();
