<?php
class SecureTokenManager {
    private $characterSet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
    private $salt;

    public function __construct($salt) {
        $this->salt = $salt;
    }

    /**
     * Generates a secure random string of specified length.
     *
     * @param int $length The length of the token to generate.
     * @return string A securely generated token.
     */
    public function generateToken($length = 32) {
        if ($length <= 0) {
            throw new InvalidArgumentException("Length must be greater than zero.");
        }

        return substr(str_shuffle(str_repeat($this->characterSet, ceil($length / strlen($this->characterSet)))), 1, $length);
    }

    /**
     * Hashes a password using bcrypt.
     *
     * @param string $password The plaintext password to hash.
     * @return string A hashed password.
     */
    public function hashPassword($password) {
        if (strlen($password) < 8) {
            throw new InvalidArgumentException("Password must be at least 8 characters long.");
        }

        return password_hash($password, PASSWORD_BCRYPT);
    }

    /**
     * Verifies a plain text password against a hashed password.
     *
     * @param string $password The plaintext password to verify.
     * @param string $hashedPassword The hashed password to compare against.
     * @return bool True if the passwords match, false otherwise.
     */
    public function verifyPassword($password, $hashedPassword) {
        return password_verify($password, $hashedPassword);
    }

    /**
     * Securely deletes a session token or hashed password by setting it to null.
     *
     * @param mixed &$token Reference to the token or password to delete.
     */
    public function securelyDelete(&$token) {
        unset($token);
    }
}
