const fs = require('fs');

/**
 * Synchronously reads a file from a specified directory and returns its contents.
 *
 * @param {string} filePath - The path to the file to read.
 * @returns {string} The contents of the file as a string.
 */
function readFileSync(filePath) {
    try {
        return fs.readFileSync(filePath, 'utf8');
    } catch (error) {
        if (error.code === 'ENOENT') {
            throw new Error(`File not found: ${filePath}`);
        } else if (error.code === 'EACCES') {
            throw new Error(`Permission denied to read file: ${filePath}`);
        } else if (error.code === 'EMFILE' || error.code === 'ENFILE') {
            throw new Error('Too many open files. Please try again later.');
        } else {
            throw new Error(`An error occurred while reading file: ${filePath}`);
        }
    }
}

module.exports = { readFileSync };
