```rust
use chrono::Utc;
use std::fs::{self, DirBuilder};
use std::path::{Path, PathBuf};
use log::{info, error};

struct DirectoryManager {
    parent_dir: PathBuf,
    external_logger: Box<dyn ExternalLogger>,
}

trait ExternalLogger {
    fn log(&self, message: &str);
    fn error_log(&self, error: &std::io::Error);
}

impl DirectoryManager {
    pub fn new(parent_dir: PathBuf, logger: Box<dyn ExternalLogger>) -> Self {
        DirectoryManager { parent_dir, external_logger: logger }
    }

    pub fn create_directory(&self, name: &str) -> Result<PathBuf, std::io::Error> {
        let full_path = self.parent_dir.join(name);
        match DirBuilder::new().create(full_path) {
            Ok(_) => {
                info!("Directory created successfully: {:?}", full_path);
                Ok(full_path)
            }
            Err(e) => {
                error!("Failed to create directory: {:?}", e);
                self.external_logger.error_log(&e);
                Err(e)
            }
        }
    }

    pub fn cleanup_old_directories(&self, threshold_days: u32) -> Result<(), std::io::Error> {
        let now = Utc::now();
        for entry in fs::read_dir(&self.parent_dir)? {
            let entry = entry?;
            if let Ok(metadata) = entry.metadata() {
                if metadata.is_dir() {
                    let path = entry.path();
                    let dir_name = path.file_stem().and_then(|f| f.to_str()).unwrap_or("");
                    if let Ok(created_time) = fs::metadata(&path).and_then(|m| m.created()) {
                        if now.signed_duration_since(created_time).num_days() > threshold_days as i64 {
                            match fs::remove_dir_all(&path) {
                                Ok(_) => info!("Directory cleaned up successfully: {:?}", path),
                                Err(e) => {
                                    error!("Failed to clean up directory: {:?}", e);
                                    self.external_logger.error_log(&e);
                                }
                            }
                        }
                    }
                }
            }
        }
        Ok(())
    }
}

struct StdOutLogger;

impl ExternalLogger for StdOutLogger {
    fn log(&self, message: &str) {
        println!("Log: {}", message);
    }

    fn error_log(&self, error: &std::io::Error) {
        eprintln!("Error Log: {:?}", error);
    }
}

fn main() {
    let parent_dir = PathBuf::from("/path/to/parent/directory");
    let logger = Box::new(StdOutLogger);
    let dir_manager = DirectoryManager::new(parent_dir, logger);

    if let Err(e) = dir_manager.create_directory(&format!("dir_{}", Utc::now().timestamp_nanos())) {
        eprintln!("Failed to create directory: {:?}", e);
    }

    if let Err(e) = dir_manager.cleanup_old_directories(30) {
        eprintln!("Failed to cleanup old directories: {:?}", e);
    }
}
```

This code snippet provides a basic structure for a Rust-based directory management utility. It includes the `DirectoryManager` struct, which handles directory creation and cleanup, as well as an external logger trait and implementation. The main function demonstrates how to use these components to create a new directory with a timestamped name and clean up directories older than 30 days.

To integrate with a real external logging service, you would need to implement the `ExternalLogger` trait for your chosen logging provider (e.g., AWS CloudWatch Logs, ELK Stack). Additionally, consider adding more sophisticated error handling, performance optimization, and other features as required.

