```javascript
function readDirectoryFiles(directory, callback) {
    const fs = require('fs');
    let contents = '';

    function readDir(dirPath) {
        fs.readdir(dirPath, (err, files) => {
            if (err) {
                console.error(`Error reading directory: ${err}`);
                return;
            }
            files.forEach(file => {
                const filePath = `${dirPath}/${file}`;
                fs.stat(filePath, (err, stats) => {
                    if (err) {
                        console.error(`Error getting file stats: ${err}`);
                        return;
                    }
                    if (stats.isDirectory()) {
                        readDir(filePath);
                    } else {
                        fs.readFile(filePath, 'utf8', (err, data) => {
                            if (err) {
                                console.error(`Error reading file: ${err}`);
                                return;
                            }
                            contents += data;
                            if (dirPath === directory && !files.some(f => f !== file)) {
                                callback(contents);
                            }
                        });
                    }
                });
            });
        });
    }

    readDir(directory);
}

// Usage
readDirectoryFiles('/path/to/directory', (contents) => {
    console.log('All files contents:', contents);
});
```

