import logging

class Widget:
    def __init__(self, widget_type, size, content):
        self.widget_type = widget_type
        self.size = size
        self.content = content

def render_widget_container(widgets):
    html = "<div class='widget-container'>\n"
    for widget in widgets:
        if widget.widget_type == 'text':
            html += f"  <p class='widget-text' style='font-size: {widget.size}px;'>{widget.content}</p>\n"
        elif widget.widget_type == 'image':
            html += f"  <img class='widget-image' src='{widget.content}' alt='' style='width: {widget.size}px; height: {widget.size}px;'>\n"
        elif widget.widget_type == 'button':
            html += f"  <button class='widget-button' style='font-size: {widget.size}px;'>{widget.content}</button>\n"
        else:
            logging.error(f"Invalid widget type: {widget.widget_type}")
    html += "</div>"
    return html
