import time
from functools import lru_cache
import requests

# Define predefined business rules and error messages
VALID_STATUSES = {
    'Preparing': ['Delivered'],
    # Add more statuses as needed
}

ERROR_MESSAGES = {
    'InvalidStatusTransition': "Order cannot be updated from '{current_status}' to '{new_status}'.",
    # Add other error messages as needed
}

# External API rate limiting constants
EXTERNAL_API_MAX_RETRIES = 3
EXTERNAL_API_DELAY = 1

# Rate limiting for individual order updates
ORDER_UPDATE_RATE_LIMIT = 60 / 10  # 10 requests per minute

# Rate limiting for batch processing
BATCH_PROCESSING_RATE_LIMIT = 300 / 100  # 100 orders in 5 minutes

# Cache expiration times for different order statuses
CACHE_EXPIRATION = {
    'Preparing': 60,  # 1 minute
    'Delivered': 3600,  # 1 hour
}

# Dummy database and cache implementations
db = {}
cache = {}

def log_to_audit_system(message):
    print(f"Audit Log: {message}")

def fetch_delivery_person(delivery_id):
    for attempt in range(EXTERNAL_API_MAX_RETRIES + 1):
        try:
            response = requests.get(f"https://api.deliveryservice.com/person/{delivery_id}")
            response.raise_for_status()
            return response.json()
        except requests.RequestException as e:
            if attempt < EXTERNAL_API_MAX_RETRIES:
                time.sleep(EXTERNAL_API_DELAY)
            else:
                log_to_audit_system(f"Failed to fetch delivery person with ID {delivery_id}: {str(e)}")
                raise
    return None

def update_order(order_id, new_status, delivery_person):
    if order_id not in db or db[order_id]['status'] != new_status:
        if new_status not in VALID_STATUSES.get(db[order_id]['status'], []):
            log_to_audit_system(ERROR_MESSAGES['InvalidStatusTransition'].format(
                current_status=db[order_id]['status'],
                new_status=new_status
            ))
            return False
    db[order_id].update({
        'status': new_status,
        'delivery_person': delivery_person,
        'timestamp': time.time()
    })
    cache[order_id] = db[order_id]
    log_to_audit_system(f"Order {order_id} updated to status {new_status}")
    return True

@lru_cache(maxsize=1024)
def get_order(order_id):
    if order_id in cache:
        return cache[order_id]
    if order_id not in db:
        db[order_id] = {
            'status': 'Preparing',
            'delivery_person': None,
            'timestamp': time.time()
        }
        log_to_audit_system(f"Order {order_id} created")
    return db[order_id]

def batch_process_orders(order_ids, updates):
    start_time = time.time()
    successful_updates = 0
    updated_orders = []

    for order_id in order_ids:
        if (time.time() - start_time) > BATCH_PROCESSING_RATE_LIMIT:
            raise Exception("Batch processing rate limit exceeded")

        order = get_order(order_id)
        new_status = updates.get(order_id, {}).get('status')
        delivery_person_id = updates.get(order_id, {}).get('delivery_person')

        if new_status and delivery_person_id is not None:
            delivery_person = fetch_delivery_person(delivery_person_id)
            if delivery_person:
                try:
                    if update_order(order_id, new_status, delivery_person):
                        successful_updates += 1
                        updated_orders.append((order_id, new_status))
                except Exception as e:
                    log_to_audit_system(f"Failed to update order {order_id}: {str(e)}")
            else:
                log_to_audit_system(f"Invalid delivery person ID for order {order_id}")

    return f"{successful_updates}/{len(order_ids)} orders updated successfully.", updated_orders, successful_updates
