    private readonly IAuditLogService _auditLogService;
    private readonly IVersioningService _versioningService;
    private readonly IRateLimitingService _rateLimitingService;

    public ElementUpdater(IDistributedCacheService cacheService, 
                          IMessageQueueService messageQueueService, 
                          IAuditLogService auditLogService, 
                          IVersioningService versioningService, 
                          IRateLimitingService rateLimitingService)
    {
        _cacheService = cacheService;
        _messageQueueService = messageQueueService;
        _auditLogService = auditLogService;
        _versioningService = versioningService;
        _rateLimitingService = rateLimitingService;
    }

    public async Task<IActionResult> UpdateElementContentAsync(int pageSectionId, int elementId, string htmlContent, string userId)
    {
        try
        {
            if (!_rateLimitingService.IsRequestAllowed(userId))
                return new StatusCodeResult((int)HttpStatusCode.TooManyRequests);

            var currentVersion = await _cacheService.GetVersionAsync(pageSectionId, elementId);
            if (!_versioningService.IsValidVersion(htmlContent, currentVersion))
                return new BadRequestObjectResult(new { error = "Invalid version ID" });

            if (!IsValidHtml(htmlContent))
                return new BadRequestObjectResult(new { error = "Invalid HTML content" });

            await _cacheService.UpdateElementAsync(pageSectionId, elementId, htmlContent);

            var oldVersion = currentVersion;
            var newVersion = _versioningService.GetNextVersion(oldVersion);
            await _auditLogService.LogUpdateAttemptAsync(userId, oldVersion, newVersion, DateTime.UtcNow);

            await _messageQueueService.SendPageRefreshNotificationAsync(pageSectionId);

            return Ok();
        }
        catch (Exception ex)
        {
            // Log the exception and send an error response
