```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <errno.h>

#define MAX_SEMAPHORES 100
#define RETRY_DELAY 500 // milliseconds

typedef struct {
    char name[50];
    int value;
    pthread_mutex_t lock;
} Semaphore;

Semaphore semaphores[MAX_SEMAPHORES];
int semaphore_count = 0;

void initialize_semaphore(char *name, int initial_value) {
    if (semaphore_count >= MAX_SEMAPHORES) {
        fprintf(stderr, "Error: Maximum number of semaphores reached\n");
        return;
    }
    Semaphore new_semaphore;
    strncpy(new_semaphore.name, name, sizeof(new_semaphore.name));
    new_semaphore.value = initial_value;
    pthread_mutex_init(&new_semaphore.lock, NULL);
    semaphores[semaphore_count++] = new_semaphore;
}

int acquire_semaphore(char *name) {
    for (int i = 0; i < semaphore_count; ++i) {
        if (strcmp(semaphores[i].name, name) == 0) {
            pthread_mutex_lock(&semaphores[i].lock);
            while (semaphores[i].value <= 0) {
                pthread_mutex_unlock(&semaphores[i].lock);
                usleep(RETRY_DELAY * 1000); // Wait with exponential backoff
                pthread_mutex_lock(&semaphores[i].lock);
            }
            semaphores[i].value--;
            pthread_mutex_unlock(&semaphores[i].lock);
            return 0;
        }
    }
    fprintf(stderr, "Error: Semaphore not found\n");
    return -1;
}

int release_semaphore(char *name) {
    for (int i = 0; i < semaphore_count; ++i) {
        if (strcmp(semaphores[i].name, name) == 0) {
            pthread_mutex_lock(&semaphores[i].lock);
            semaphores[i].value++;
            pthread_mutex_unlock(&semaphores[i].lock);
            return 0;
        }
    }
    fprintf(stderr, "Error: Semaphore not found\n");
    return -1;
}

void delete_semaphore(char *name) {
    for (int i = 0; i < semaphore_count; ++i) {
        if (strcmp(semaphores[i].name, name) == 0) {
            pthread_mutex_destroy(&semaphores[i].lock);
            memmove(&semaphores[i], &semaphores[i + 1], sizeof(Semaphore) * (semaphore_count - i - 1));
            semaphore_count--;
            return;
        }
    }
    fprintf(stderr, "Error: Semaphore not found\n");
}

void *thread_function(void *arg) {
    char *name = (char *)arg;
    acquire_semaphore(name);
    // Simulate database operation
    sleep(1);
    release_semaphore(name);
    return NULL;
}

int main() {
    initialize_semaphore("database_access", 2);

    pthread_t threads[50];
    for (int i = 0; i < 50; ++i) {
        pthread_create(&threads[i], NULL, thread_function, "database_access");
    }

    for (int i = 0; i < 50; ++i) {
        pthread_join(threads[i], NULL);
    }

    delete_semaphore("database_access");

    return 0;
}
```

This code provides a basic implementation of a distributed semaphore management system in C. It includes functions to initialize, acquire, release, and delete semaphores. The `thread_function` demonstrates how threads can use the semaphore for accessing a shared resource. This example can be expanded with additional features such as retry mechanisms, error handling, and performance optimizations.

