import os
import threading
import hashlib
from concurrent.futures import ThreadPoolExecutor, as_completed
import requests
from queue import Queue
import logging

# Constants
LOG_DIR = '/path/to/log/directory'
DATABASE_POOL_SIZE = 10
CACHE_EXPIRY_TIME = 3600  # in seconds
ERROR_LOG_PATH = '/path/to/error/log'
RATE_LIMIT_INTERVAL = 60  # in seconds

# External Monitoring System API details
MONITORING_API_URL = 'https://api.monitoring.com/logs/check'

# Configuration management system
config = {
    'log_directory': LOG_DIR,
    'database_pool_size': DATABASE_POOL_SIZE,
    'cache_expiry_time': CACHE_EXPIRY_TIME,
    'error_log_path': ERROR_LOG_PATH,
    'rate_limit_interval': RATE_LIMIT_INTERVAL,
    'exclusion_patterns': ['*.tmp', '*.bak'],
}

# Initialize logging
logging.basicConfig(filename=ERROR_LOG_PATH, level=logging.ERROR, format='%(asctime)s - %(levelname)s - %(message)s')

class LogIntegrityChecker:
    def __init__(self):
        self.file_queue = Queue()
        self.hash_cache = {}
        self.lock = threading.Lock()

    def enqueue_files(self, log_dir):
        for root, _, files in os.walk(log_dir):
            for file in files:
                if not any(pattern in file for pattern in config['exclusion_patterns']):
                    file_path = os.path.join(root, file)
                    self.file_queue.put(file_path)

    def check_integrity(self, file_path):
        try:
            with open(file_path, 'rb') as f:
                sha256_hash = hashlib.sha256(f.read()).hexdigest()
            return sha256_hash
        except Exception as e:
            logging.error(f"Error reading file {file_path}: {e}")
            raise

    def update_cache(self, file_path, hash_value):
        with self.lock:
            self.hash_cache[file_path] = (hash_value, time.time())

    def report_to_monitoring_system(self, file_path, hash_value):
        try:
            response = requests.post(MONITORING_API_URL, json={'file_path': file_path, 'hash_value': hash_value})
            response.raise_for_status()
        except requests.RequestException as e:
            logging.error(f"Error reporting to monitoring system for {file_path}: {e}")
            raise

    def worker(self):
        while True:
            file_path = self.file_queue.get()
            if file_path is None:
                break
            try:
                hash_value = self.check_integrity(file_path)
                current_time = time.time()
                if file_path not in self.hash_cache or (current_time - self.hash_cache[file_path][1]) > config['cache_expiry_time']:
                    self.update_cache(file_path, hash_value)
                if config['rate_limit_interval'] is not None:
                    time.sleep(config['rate_limit_interval'])
                self.report_to_monitoring_system(file_path, hash_value)
            except Exception as e:
                logging.error(f"Error processing file {file_path}: {e}")
            finally:
                self.file_queue.task_done()

    def run(self):
        self.enqueue_files(config['log_directory'])
        with ThreadPoolExecutor(max_workers=config['database_pool_size']) as executor:
            for _ in range(config['database_pool_size']):
                executor.submit(self.worker)
        self.file_queue.join()

if __name__ == "__main__":
    checker = LogIntegrityChecker()
    checker.run()
