const express = require('express');
const axios = require('axios');
const fs = require('fs');
const path = require('path');

const app = express();
const port = 3000;

// Load configuration from a JSON file
const configPath = path.join(__dirname, 'config.json');
let config;
try {
  config = JSON.parse(fs.readFileSync(configPath, 'utf8'));
} catch (error) {
  console.error('Failed to load configuration:', error);
  process.exit(1);
}

// Define the routes
app.get('/weather/:location', async (req, res) => {
  const { location } = req.params;
  try {
    const weatherData = await fetchWeatherData(location);
    res.json(weatherData);
  } catch (error) {
    res.status(500).json({ error: 'Failed to retrieve weather data' });
  }
});

// Function to fetch weather data from multiple APIs
async function fetchWeatherData(location) {
  const apiKeys = config.apiKeys;
  const results = [];

  for (const apiKey of apiKeys) {
    try {
      const response = await axios.get(`https://api.example.com/weather`, {
        params: {
          q: location,
          appid: apiKey
        }
      });
      results.push(response.data);
    } catch (error) {
      console.error('API error:', error.message);
      // Fallback mechanism if one API fails
      results.push({ fallbackData: true });
    }
  }

  return aggregateWeatherData(results);
}

// Function to aggregate weather data from multiple sources
function aggregateWeatherData(data) {
  const aggregatedData = {
    currentTemperature: null,
    humidity: null,
    windSpeed: null,
    forecast: []
  };

  for (const apiData of data) {
    if (!apiData.fallbackData) {
      aggregatedData.currentTemperature = apiData.main.temp;
      aggregatedData.humidity = apiData.main.humidity;
      aggregatedData.windSpeed = apiData.wind.speed;

      apiData.forecast.forEach(forecast => {
        const forecastExists = aggregatedData.forecast.some(aForecast => aForecast.date === forecast.date);
        if (!forecastExists) {
          aggregatedData.forecast.push({
            date: forecast.date,
            condition: forecast.condition
          });
        }
      });
    }
  }

  return aggregatedData;
}

// Start the server
app.listen(port, () => {
  console.log(`Weather service running on http://localhost:${port}`);
});
