class FileUploader:
    _factories = {}

    @staticmethod
    def register_factory(factory_id, factory_function):
        FileUploader._factories[factory_id] = factory_function

    @staticmethod
    def create_instance(factory_id, data):
        if factory_id in FileUploader._factories:
            return FileUploader._factories[factory_id](data)
        else:
            raise ValueError(f"No factory registered for ID: {factory_id}")

class JSONFile(FileUploader):
    def __init__(self, data):
        self.data = data

    @classmethod
    def from_json(cls, json_str):
        return cls(json.loads(json_str))

    def to_json(self):
        return json.dumps(self.data)

async def load_file_async(file_path):
    try:
        with open(file_path, 'r') as file:
            data = await asyncio.to_thread(file.read)
            return JSONFile.from_json(data)
    except Exception as e:
        logging.error(f"Error loading file {file_path}: {e}")
        raise

async def process_file_async(file_path):
    try:
        file_instance = await load_file_async(file_path)
        # Add your processing logic here
        processed_data = {"status": "processed", "data": file_instance.data}
        return json.dumps(processed_data)
    except Exception as e:
        logging.error(f"Error processing file {file_path}: {e}")
        raise

async def main():
    file_paths = ['file1.json', 'file2.json']
    async with ThreadPoolExecutor() as executor:
        tasks = [process_file_async(path) for path in file_paths]
        results = await asyncio.gather(*tasks)
        for result in results:
            print(result)

if __name__ == "__main__":
