// Function to load and run tests for plugins in parallel
async function runTests(label, f, plugins) {
    if (isMainThread) {
        // Create a worker pool for concurrent testing
        const workers = plugins.map((plugin, index) => new Worker(__filename, { workerData: { plugin, index } }));

        // Collect results from workers
        let results = await Promise.all(workers.map(worker => new Promise(resolve => worker.on('message', resolve))));

        // Log detailed execution logs and handle errors
        results.forEach((result, index) => {
            if (result.error) {
                console.error(`Plugin ${plugins[index]} test failed:`, result.error);
            } else {
                console.log(`Plugin ${plugins[index]} test passed in ${result.duration}ms`);
            }
        });

        // Clean up resources
        workers.forEach(worker => worker.terminate());
    } else {
        const { plugin, index } = workerData;
        try {
            const start = Date.now();
            await f(plugin);
            parentPort.postMessage({ duration: Date.now() - start });
        } catch (error) {
            parentPort.postMessage({ error: error.message });
        }
    }
}

