#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pthread.h>

// Define constants and data structures
#define MAX_LINE_LENGTH 4096
#define NUM_THREADS 4

typedef struct {
    FILE *input_file;
    FILE *output_file;
    int line_number;
} ThreadData;

// Function prototypes
void* process_file(void* arg);
int read_line(FILE* file, char** buffer, size_t* length);
int parse_numbers(const char* line, float* numbers, int max_numbers);
float calculate_average(float numbers[], int count);
void write_result(FILE* file, const char* result);

// Signal handler
void handle_signal(int signum) {
    printf("Received signal %d, terminating gracefully...\n", signum);
    exit(1);
}

int main(int argc, char *argv[]) {
    if (argc < 5) {
        fprintf(stderr, "Usage: %s <input_dir> <output_dir> <log_level> <delimiter>\n", argv[0]);
        return 1;
    }

    // Setup signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize thread pool
    pthread_t threads[NUM_THREADS];
    ThreadData data[NUM_THREADS];

    for (int i = 0; i < NUM_THREADS; i++) {
        data[i].input_file = NULL;
        data[i].output_file = NULL;
        data[i].line_number = 1;

        if (pthread_create(&threads[i], NULL, process_file, &data[i]) != 0) {
            fprintf(stderr, "Failed to create thread %d\n", i);
            return 1;
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

void* process_file(void* arg) {
    ThreadData *data = (ThreadData*)arg;

    char buffer[MAX_LINE_LENGTH];
    size_t length = sizeof(buffer);

    while ((length = read_line(data->input_file, &buffer, &length)) > 0) {
        float numbers[3] = {0.0};
        int count = parse_numbers(buffer, numbers, 3);

        if (count >= 3) {
            float average = calculate_average(numbers, count);
            write_result(data->output_file, buffer);
        }
    }

    fclose(data->input_file);
    fclose(data->output_file);

    return NULL;
}

int read_line(FILE* file, char** buffer, size_t* length) {
    *length = getline(buffer, length, file);
    if (*length == -1) {
        return 0; // End of file or error
    }
    return 1;
}

int parse_numbers(const char* line, float* numbers, int max_numbers) {
    const char* delimiter = " ";
    char* token = strtok((char*)line, delimiter);
    int count = 0;

    while (token != NULL && count < max_numbers) {
        if (sscanf(token, "%f", &numbers[count]) == 1) {
            count++;
        } else {
            printf("Warning: Non-numeric value encountered\n");
        }
        token = strtok(NULL, delimiter);
    }

    return count;
}

float calculate_average(float numbers[], int count) {
    float sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += numbers[i];
    }
    return sum / count;
}

void write_result(FILE* file, const char* result) {
    fprintf(file, "%s\n", result);
}
