#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
} record;

record** create_records(int num_elements) {
    record **records = (record **)malloc(num_elements * sizeof(record *));
    if (!records) {
        perror("Failed to allocate memory for records pointers");
        return NULL;
    }

    pthread_mutex_t *mutexes = (pthread_mutex_t *)malloc(num_elements * sizeof(pthread_mutex_t));
    if (!mutexes) {
        perror("Failed to allocate memory for mutexes");
        free(records);
        return NULL;
    }

    long *offsets = (long *)malloc(num_elements * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        free(records);
        free(mutexes);
        return NULL;
    }

    int *keys = (int *)malloc(num_elements * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        free(records);
        free(mutexes);
        free(offsets);
        return NULL;
    }

    for (int i = 0; i < num_elements; ++i) {
        records[i] = (record *)malloc(sizeof(record));
        if (!records[i]) {
            perror("Failed to allocate memory for record");
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);
            free(mutexes);
            free(offsets);
            free(keys);
            return NULL;
        }

        pthread_mutex_init(&mutexes[i], NULL);

        records[i]->offset = offsets[i];
        records[i]->key = keys[i];
    }

    // Example usage of mutexes
    for (int i = 0; i < num_elements; ++i) {
        pthread_mutex_lock(&mutexes[i]);
        // Perform operations on records[i]
        pthread_mutex_unlock(&mutexes[i]);
    }

    free(mutexes);
    free(offsets);
    free(keys);

    return records;
}

void free_records(record **records, int num_elements) {
    for (int i = 0; i < num_elements; ++i) {
        if (records[i]) {
            free(records[i]);
        }
    }
    free(records);
}
