        IEnumerable<IPasswordValidator<ApplicationUser>> passwordValidators, ILookupNormalizer keyNormalizer,
        IdentityErrorDescriber errors, IHttpContextAccessor contextAccessor, ILogger<UserManager<ApplicationUser>> logger)
        : base(store, optionsAccessor, passwordHasher, userValidators, passwordValidators, keyNormalizer, errors, contextAccessor, logger)
    {
    }

    public async Task<ProductDetails> GetProductDetailsAsync(string category, string subcategory, int productId)
