        if (!_productCache.TryGetValue(cacheKey, out var productDetails))
        {
            productDetails = await _productRepository.GetProductDetailsAsync(category, subcategory, productId);
            _productCache.TryAdd(cacheKey, productDetails);
        }
        return productDetails;
    }

    public async Task LockUserAccountAsync(string userId)
    {
        var user = await FindByIdAsync(userId);
        if (user != null && !await IsLockedOutAsync(user.Id))
        {
            await AccessFailedAsync(user);
            await UpdateSecurityStampAsync(user);
        }
    }

    public async Task UnlockUserAccountAsync(string userId)
    {
        var user = await FindByIdAsync(userId);
        if (user != null && await IsLockedOutAsync(user.Id))
        {
            ResetAccessFailedCountAsync(user).Wait();
            UpdateSecurityStampAsync(user).Wait();
        }
    }
