import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class UserProfileFetcher {

    private static final Logger logger = LoggerFactory.getLogger(UserProfileFetcher.class);
    private static final ConcurrentHashMap<String, UserProfile> userProfileCache = new ConcurrentHashMap<>();

    public static CompletableFuture<List<UserProfile>> fetchUserProfilesAsync(List<String> userIds, ApiClient apiClient, CacheManager cacheManager) {
        return CompletableFuture.supplyAsync(() -> {
            List<UserProfile> userProfiles = userProfileCache.getAll(userIds);

            for (String userId : userIds) {
                if (!userProfiles.contains(userId)) {
                    try {
                        UserProfile userProfile = apiClient.fetchUserProfile(userId);
                        userProfileCache.put(userId, userProfile);
                    } catch (NetworkTimeoutException e) {
                        logger.error("Network timeout while fetching user profile: {}", userId, e);
                    } catch (ApiRateLimitException e) {
                        logger.warn("API rate limit exceeded for user profile: {}", userId, e);
                    } catch (InvalidUserIdException e) {
                        logger.warn("Invalid user ID provided: {}", userId, e);
                    }
                }
            }

            return userProfileCache.getAll(userIds);
        }, CompletableFuture::runAsync);
    }

    public static void main(String[] args) {
        ApiClient apiClient = new ApiClient();
        CacheManager cacheManager = new CacheManager();

        List<String> userIds = List.of("user1", "user2", "user3");

        fetchUserProfilesAsync(userIds, apiClient, cacheManager)
            .thenAccept(userProfiles -> {
                userProfiles.forEach(userProfile -> logger.info("Fetched user profile: {}", userProfile));
            });
    }
}

class UserProfile {
    // UserProfile class implementation
}

class ApiClient {
    public UserProfile fetchUserProfile(String userId) throws NetworkTimeoutException, ApiRateLimitException, InvalidUserIdException {
        // API client implementation
        return new UserProfile();
    }
}

class CacheManager {
    public void dispose() {
        // Cache manager disposal implementation
    }

    public List<UserProfile> getAll(List<String> userIds) {
        // Get all user profiles from cache
        return userIds.stream()
            .map(userProfileCache::get)
            .filter(profile -> profile != null)
            .toList();
    }

    public void put(String key, UserProfile value) {
        userProfileCache.put(key, value);
    }
}

class NetworkTimeoutException extends Exception {
    // Custom exception implementation
}

class ApiRateLimitException extends Exception {
    // Custom exception implementation
}

class InvalidUserIdException extends Exception {
    // Custom exception implementation
}
