const aws = require('aws-sdk');
const s3 = new aws.S3();
const crypto = require('crypto');

function uploadFileFromUrl(url, userId) {
  // Check if the user is authenticated
  if (!isUserAuthenticated(userId)) {
    return Promise.reject(new Error('User not authenticated'));
  }

  // Validate file type and extension
  const fileType = getFileTypeFromUrl(url);
  if (!isFileTypeSupported(fileType)) {
    return Promise.reject(new Error(`File type ${fileType} is not supported`));
  }

  // Create a unique file name based on the user ID and current timestamp
  const fileName = `${userId}-${crypto.randomBytes(16).toString('hex')}`;

  // Download the file from the URL
  const response = await fetch(url);
  if (!response.ok) {
    return Promise.reject(new Error(`Failed to download file from ${url}`));
  }
  const blob = await response.blob();

  // Split large files into chunks (if necessary)
  const chunks = [];
  for (let i = 0; i < blob.size; i += chunkSize) {
    chunks.push(blob.slice(i, i + chunkSize));
  }

  let uploadPromises = chunks.map((chunk, index) => {
    return s3.upload({
      Bucket: 'your-bucket-name',
      Key: fileName + (chunks.length > 1 ? `-${index}` : ''),
      Body: chunk,
      ContentType: fileType,
      ContentDisposition: 'inline',
      CacheControl: 'max-age=86400', // 24 hours
      Metadata: {
        userId: userId
      }
    }).promise();
  });

  return Promise.all(uploadPromises)
    .then(() => {
      if (chunks.length > 1) {
        return stitchChunks(fileName);
      } else {
        return fileName;
      }
    })
    .catch((error) => {
      // Retry mechanism with increasing backoff intervals
      let retries = 5;
      let delay = 2000; // Initial delay of 2 seconds
      let retryPromise = null;

      function retryUpload() {
        if (retries > 0) {
          retries--;
          return s3.upload({
            Bucket: 'your-bucket-name',
            Key: fileName,
            Body: blob,
            ContentType: fileType,
            ContentDisposition: 'inline',
            CacheControl: 'max-age=86400',
            Metadata: {
              userId: userId
            }
          }).promise()
          .catch((error) => {
            if (retryPromise) {
              clearTimeout(retryPromise);
            }
            retryPromise = setTimeout(() => retryUpload(), delay);
            delay *= 2;
            return Promise.reject(error);
          });
        } else {
          return Promise.reject(new Error('Failed to upload file after multiple retries'));
        }
      }

      return retryUpload();
    });
}

function isUserAuthenticated(userId) {
