    if not filename:
        raise ValueError("Filename cannot be empty")
    if len(filename) > 255:
        raise ValueError("Filename too long")
    if re.search(r'[^a-zA-Z0-9._-]', filename):
        raise ValueError("Invalid characters in filename")

def get_new_filename(file_path, extension, prefix=None, suffix=None, max_length=255):
    validate_filename(os.path.basename(file_path))
    directory, base = os.path.split(file_path)
    name, ext = os.path.splitext(base)
    new_name = f"{name}_{prefix}{extension}" if prefix else f"{name}{extension}"
    new_name = f"{new_name}_{suffix}" if suffix else new_name
    new_filename = os.path.join(directory, new_name)
    if len(new_filename) > max_length:
        raise ValueError("New filename too long")
    return new_filename

