    private static final int CACHE_EXPIRATION_TIME = 24 * 60 * 60; // 24 hours in seconds
    private static final String EXCLUSION_PATTERN = ".tmp";
    private static final String ERROR_LOG_PATH = "error.log";

    private ExecutorService executorService;
    private DatabaseConnectionPool dbConnectionPool;
    private MetadataCache metadataCache;
