        File directory = new File(directoryPath);
        if (!directory.exists() || !directory.isDirectory()) {
            System.err.println("Invalid directory path: " + directoryPath);
            return;
        }

        for (File file : directory.listFiles((dir, name) -> !name.matches(EXCLUSION_PATTERN))) {
            try {
                executorService.submit(() -> processImage(file));
            } catch (Exception e) {
                System.err.println("Error submitting image processing task for " + file.getName());
                e.printStackTrace();
            }
        }

        executorService.shutdown();
