// Node.js application that dynamically loads and executes multiple JavaScript modules

const fs = require('fs');
const path = require('path');
const childProcess = require('child_process');

class ModuleLoader {
  constructor(configPath) {
    this.configPath = configPath;
    this.modules = {};
    this.loadConfig();
  }

  loadConfig() {
    try {
      const config = JSON.parse(fs.readFileSync(this.configPath, 'utf8'));
      config.modules.forEach(module => this.registerModule(module));
    } catch (error) {
      console.error('Error loading configuration:', error);
    }
  }

  registerModule(module) {
    if (!this.modules[module.name]) {
      try {
        const modulePath = path.join(__dirname, 'modules', module.name);
        const moduleFunc = require(modulePath);
        this.modules[module.name] = { func: moduleFunc, dependencies: module.dependencies };
        this.loadDependencies(module);
      } catch (error) {
        console.error(`Failed to load module ${module.name}:`, error);
      }
    }
  }

  loadDependencies(moduleInfo) {
    moduleInfo.dependencies.forEach(dep => {
      if (!this.modules[dep]) {
        this.registerModule({ name: dep });
      }
    });
  }

  executeAll() {
    Object.keys(this.modules).forEach(moduleName => {
      const module = this.modules[moduleName];
      try {
        console.log(`Executing ${moduleName}`);
        module.func();
      } catch (error) {
        console.error(`Error executing ${moduleName}:`, error);
      }
    });
  }
}

// Example usage
const loader = new ModuleLoader('config.json');
loader.executeAll();
```

