class PaymentProcessor:
    def __init__(self):
        self.payment_gateways = {}
        self.orders_db = {}
        self.customers_cache = {}

    def processPayment(self, order_id, payment_method, amount):
        if not self.validate_order(order_id) or not self.validate_amount(amount):
            return "Validation failed"

        gateway = self.get_payment_gateway(payment_method)
        if not gateway:
            return "Unsupported payment method"

        attempt = 0
        max_attempts = 3
        while attempt < max_attempts:
            try:
                result = gateway.process_transaction(order_id, amount)
                if result == "success":
                    return "Payment processed successfully"
                elif result == "pending":
                    return "Payment processing pending"
            except (ConnectionError, TimeoutError):
                time.sleep(2 ** attempt)
                attempt += 1
        return "Payment processing failed"

    def refundPayment(self, order_id, refund_amount):
        if not self.validate_order(order_id) or not self.validate_amount(refund_amount):
            return "Validation failed"

        transaction = self.orders_db.get(order_id, {}).get("transaction")
        if not transaction:
            return "Transaction not found for this order"

        if refund_amount > transaction["amount"]:
            return "Insufficient funds to refund"

        gateway = self.get_payment_gateway(transaction["payment_method"])
        if not gateway:
            return "Unsupported payment method"

        result = gateway.refund_transaction(order_id, refund_amount)
        if result == "success":
            return "Refund processed successfully"
        elif result == "partial":
            return "Partial refund processed"
        else:
            return "Refund processing failed"

    def createOrder(self, customer_id, items, total_amount):
