public class DecryptionSystem
{
    private static int tileWidth;
    private static int tileHeight;
    private static int worldWidth;
    private static int worldHeight;
    private static double cameraSpeed;

    public static void Main(string[] args)
    {
        LoadConfiguration();
        string ciphertext = "your_ciphertext_here";
        byte[] key = Convert.FromBase64String("your_key_here");
        byte[] iv = Convert.FromBase64String("your_iv_here");
        byte[] decryptedBytes = DecryptCiphertext(ciphertext, key, iv);
        string decryptedText = System.Text.Encoding.UTF8.GetString(decryptedBytes);
        Console.WriteLine(decryptedText);

        // Additional functionality can be added here
    }

    private static void LoadConfiguration()
    {
        try
        {
            XmlDocument configXml = new XmlDocument();
            string configPath = Environment.GetEnvironmentVariable("CONFIG_PATH") ?? "config.xml";
            configXml.Load(configPath);

            tileWidth = int.Parse(configXml.SelectSingleNode("//tileWidth").InnerText);
            tileHeight = int.Parse(configXml.SelectSingleNode("//tileHeight").InnerText);
            worldWidth = int.Parse(configXml.SelectSingleNode("//worldWidth").InnerText);
            worldHeight = int.Parse(configXml.SelectSingleNode("//worldHeight").InnerText);
            cameraSpeed = double.Parse(configXml.SelectSingleNode("//cameraSpeed").InnerText);

            // Additional configuration loading logic can be added here
        }
        catch (Exception ex)
        {
            LogError("Failed to load configuration: " + ex.Message);
        }
    }

    public static byte[] DecryptCiphertext(string ciphertext, byte[] key, byte[] iv)
    {
        if (key.Length != 32 || !IsBase64Encoded(key))
        {
            throw new ArgumentException("Invalid key length or format.");
        }

        if (iv.Length != 16 || !IsBase64Encoded(iv))
        {
            throw new ArgumentException("Invalid IV length or format.");
        }

        using (Aes aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            aes.Mode = CipherMode.CBC;

            ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
            byte[] ciphertextBytes = Convert.FromBase64String(ciphertext);

            using (MemoryStream msDecrypt = new MemoryStream(ciphertextBytes))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    using (MemoryStream msOutput = new MemoryStream())
                    {
                        csDecrypt.CopyTo(msOutput);
                        return msOutput.ToArray();
                    }
                }
            }
        }
    }

    private static bool IsBase64Encoded(byte[] data)
    {
        try
        {
            Convert.ToBase64String(data);
            return true;
        }
        catch
        {
            return false;
        }
    }

    private static void LogError(string message)
    {
        // External logging system integration logic can be added here
        Console.WriteLine("ERROR: " + message);
    }
}
