import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.AsynchronousServerSocketChannel;
import java.nio.channels.AsynchronousSocketChannel;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;

public class GameCharacter {

    private AsynchronousServerSocketChannel serverChannel;
    private boolean isAttacking = false;
    private long lastAttackTime = 0;

    public void start() {
        // Initialize the server channel
        try {
            serverChannel = AsynchronousServerSocketChannel.open();
            InetSocketAddress address = new InetSocketAddress("localhost", 8080);
            serverChannel.bind(address);

            // Start listening for connections in a separate thread
            listenForConnections();

            // Main loop to handle attacks and connection retries
            while (true) {
                try {
                    Thread.sleep(1000); // Check every second

                    if (!isAttacking && canAttack()) {
                        int attackNumber = selectRandomAttack();
                        performAttack(attackNumber);
                    }
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void listenForConnections() {
        serverChannel.accept(null, new CompletionHandler<AsynchronousSocketChannel, Void>() {
            @Override
            public void completed(AsynchronousSocketChannel result, Void attachment) {
                // Handle connection and accept another one
                try {
                    InetSocketAddress clientAddress = (InetSocketAddress) result.getRemoteAddress();
                    System.out.println("Accepted connection from " + clientAddress);
                    // Continue accepting connections
                    serverChannel.accept(null, this);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }

            @Override
            public void failed(Throwable exc, Void attachment) {
                // Handle connection failure and retry
                System.out.println("Failed to accept connection: " + exc.getMessage());
                try {
                    Thread.sleep(5000); // Wait before retrying
                    listenForConnections();
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
            }
        });
    }

    private int selectRandomAttack() {
        // Implement random selection with synchronization to avoid race conditions
        synchronized (this) {
            int attackNumber = ThreadLocalRandom.current().nextInt(1, 3);
            return attackNumber;
        }
    }

    private boolean canAttack() {
        // Check if the cooldown period has expired
        long currentTime = System.currentTimeMillis();
        return (currentTime - lastAttackTime) >= 9000;
    }

    private void performAttack(int attackNumber) {
        // Simulate attack and update last attack time
        synchronized (this) {
            lastAttackTime = System.currentTimeMillis();
            System.out.println("Performing attack " + attackNumber);
            // Log the attack to a file or external service
        }
    }

    public static void main(String[] args) {
        GameCharacter character = new GameCharacter();
        character.start();
    }
}
