import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cloud.stream.annotation.EnableBinding;
import org.springframework.data.jpa.repository.config.EnableJpaRepositories;

@SpringBootApplication
@EnableBinding(LogStream.class)
@EnableJpaRepositories(basePackages = "com.example.logservice.repository")
public class LogServiceApplication {
    public static void main(String[] args) {
        SpringApplication.run(LogServiceApplication.class, args);
    }
}

// Log processing component
@Service
public class LogProcessor {
    @Autowired
    private LogRepository logRepository;

    @Autowired
    private CacheManager cacheManager;

    @StreamListener("logStream")
    public void processLog(String logEntry) {
        // Filter and aggregate logs based on custom-defined rules
        if (isError(logEntry)) {
            incrementErrorCount();
        }
        saveToArchive(logEntry);
    }

    private boolean isError(String logEntry) {
        // Implement error detection logic
        return logEntry.contains("ERROR");
    }

    private void incrementErrorCount() {
        String key = "errorCount";
        Integer count = cacheManager.getCache(key).get(key, Integer.class);
        if (count == null) {
            count = 0;
        }
        cacheManager.getCache(key).put(key, count + 1);
    }

    private void saveToArchive(String logEntry) {
        // Save log entry to the database for long-term archival
        Log log = new Log(logEntry);
        logRepository.save(log);
    }
}

// RESTful API component for querying log data
@RestController
@RequestMapping("/api/logs")
public class LogController {
    @Autowired
    private LogService logService;

    @GetMapping
    public ResponseEntity<List<Log>> getLogs(@RequestParam(required = false) String filter,
                                            @RequestParam(required = false, defaultValue = "0") int page,
                                            @RequestParam(required = false, defaultValue = "10") int size) {
        // Implement pagination and filtering logic
        Pageable pageable = PageRequest.of(page, size);
        List<Log> logs = logService.getLogs(filter, pageable);
        return ResponseEntity.ok(logs);
    }
}

