        return std::uniform_int_distribution<>(min, max)(gen);
    }

    double RandomGenerator::generateUniformDouble(double min, double max) {
        return std::uniform_real_distribution<>(min, max)(gen);
    }

    double RandomGenerator::generateNormal(double mean, double stddev) {
        return std::normal_distribution<>(mean, stddev)(gen);
    }

    double RandomGenerator::generateExponential(double lambda) {
        return std::exponential_distribution<>(lambda)(gen);
    }

    unsigned RandomGenerator::generatePoisson(double lambda) {
        return std::poisson_distribution<>(lambda)(gen);
    }

    unsigned RandomGenerator::generateGeometric(double p) {
        return std::geometric_distribution<>(p)(gen);
    }

