class ClinicUpdateManager {
    private $db;
    private $logger;
    private $rateLimiter;

    public function __construct($db, $logger, $rateLimiter) {
        $this->db = $db;
        $this->logger = $logger;
        $this->rateLimiter = $rateLimiter;
    }

    public function updateClinicStatus($clinicId, $newStatus, $userId, $reason, $emailAdmins = false) {
        try {
            // Rate limiting
            if (!$this->rateLimiter->allowUpdate($clinicId)) {
                throw new Exception("Rate limit exceeded. Please try again later.");
            }

            // Validate clinic ID
            if (!$this->validateClinicId($clinicId)) {
                throw new Exception("Invalid clinic ID.");
            }

            $this->db->beginTransaction();

            // Fetch old status for logging
            $oldStatus = $this->db->fetchColumn("SELECT status FROM clinics WHERE id = :id", ['id' => $clinicId]);

            // Update the database
            $stmt = $this->db->prepare("UPDATE clinics SET status = :status, last_modified_ip = :ip, last_modified_date = NOW() WHERE id = :id");
            $stmt->execute(['status' => $newStatus, 'ip' => $_SERVER['REMOTE_ADDR'], 'id' => $clinicId]);

            // Log the update
            $this->logger->logUpdate($userId, $clinicId, $oldStatus, $newStatus, $reason);

            if ($emailAdmins) {
                $this->sendEmailNotification($clinicId, $oldStatus, $newStatus, $userId);
            }

            $this->db->commit();
        } catch (Exception $e) {
            if ($this->db->inTransaction()) {
