#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/rsa.h>
#include <openssl/sha.h>
#include <openssl/x509v3.h>
#include <curl/curl.h>

typedef enum {
    ALGO_AES_256,
    ALGO_RSA_2048,
    ALGO_SHA_256
} CryptoAlgorithm;

typedef struct {
    CURL *curl;
    char *api_endpoint;
} LibraryConfig;

int init_library(LibraryConfig *config) {
    int err = 0;

    // Initialize OpenSSL EVP library
    if (!EVP_add_cipher(EVP_aes_256_cbc())) {
        err = -1;
        goto cleanup;
    }
    if (!EVP_add_digest(EVP_sha256())) {
        err = -2;
        goto cleanup;
    }

    // Add RSA method
    RSA_METHOD *rsa_meth = RSA_PKCS1_OpenSSL();
    if (RSA_set_method(RSA_get0_key(rsa_meth), rsa_meth) != 1) {
        err = -3;
        goto cleanup;
    }
    EVP_add_digest_alias("SHA256", "sha256");

    // Initialize CURL for API interaction
    config->curl = curl_easy_init();
    if (!config->curl) {
        err = -4;
        goto cleanup;
    }

    // Set API endpoint
    if (curl_easy_setopt(config->curl, CURLOPT_URL, config->api_endpoint) != CURLE_OK) {
        err = -5;
        goto cleanup;
    }

cleanup:
    if (err != 0) {
        // Clean up on error
        if (config->curl) {
            curl_easy_cleanup(config->curl);
        }
    }

    return err;
}

void deinit_library(LibraryConfig *config) {
    if (config->curl) {
        curl_easy_cleanup(config->curl);
        config->curl = NULL;
    }
}
