using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Distributed;
using Newtonsoft.Json;

public class DynamicWebService : IDynamicWebService
{
    private readonly HttpClient _httpClient;
    private readonly IDistributedCache _cache;
    private readonly ILogger<DynamicWebServiceProvider> _logger;

    public DynamicWebService(HttpClient httpClient, IDistributedCache cache, ILogger<DynamicWebServiceProvider> logger)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task UpdateElementAsync(string pageSectionId, string elementId, string updatedHtmlContent)
    {
        // Validate input parameters
        if (string.IsNullOrEmpty(pageSectionId) || string.IsNullOrEmpty(elementId))
        {
            _logger.LogError("Invalid input: Page section ID and element ID cannot be null or empty.");
            throw new ArgumentException("Page section ID and element ID must not be null or empty.");
        }

        try
        {
            // Authenticate with external REST API (Example: Get a token)
            var authToken = await AuthenticateAsync();

            // Lock mechanism to handle concurrent updates (Optional, replace with optimistic concurrency control if preferred)
            string lockKey = $"lock:{pageSectionId}:{elementId}";
            using (var semaphoreSlim = new SemaphoreSlim(1))
            {
                await semaphoreSlim.WaitAsync();
                try
                {
                    // Retrieve current HTML content from cache
                    var cachedHtml = await _cache.GetStringAsync($"{pageSectionId}_{elementId}");
                    if (string.IsNullOrEmpty(cachedHtml))
                    {
                        cachedHtml = "<div></div>"; // Default to empty div if not found
                    }

                    // Parse and update the HTML content
                    var doc = new HtmlDocument();
                    doc.LoadHtml(cachedHtml);
                    var element = doc.DocumentNode.SelectSingleNode($"//*[@id='{elementId}']");
                    if (element != null)
                    {
                        element.InnerHtml = updatedHtmlContent;
                    }
                    else
                    {
                        _logger.LogError("Element not found in the HTML content.");
                        throw new InvalidOperationException("Element not found in the HTML content.");
                    }

                    // Store the updated HTML content back to cache
                    await _cache.SetStringAsync($"{pageSectionId}_{elementId}", doc.DocumentNode.OuterHtml, new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10) });
                }
                finally
                {
                    semaphoreSlim.Release();
                }
            }

            // Log successful update
            _logger.LogInformation($"Element {elementId} in page section {pageSectionId} updated successfully.");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while updating the element.");
            throw;
        }
    }

    private async Task<string> AuthenticateAsync()
    {
        // Implement authentication logic with external REST API
        var tokenRequest = new
        {
            Username = "your_username",
            Password = "your_password"
        };

        var content = JsonConvert.SerializeObject(tokenRequest);
        var requestContent = new StringContent(content, System.Text.Encoding.UTF8, "application/json");
        var response = await _httpClient.PostAsync("https://api.example.com/authenticate", requestContent);

        if (response.IsSuccessStatusCode)
        {
            var tokenResponse = await response.Content.ReadAsAsync<TokenResponse>();
            return tokenResponse.Token;
        }
        else
        {
            throw new Exception("Failed to authenticate with external REST API.");
        }
    }

    // TokenResponse class for deserializing authentication response
    public class TokenResponse
    {
        public string Token { get; set; }
    }
}
