import json
from typing import Optional, Callable, TypeVar

class DynamicResourcePoolManager:
    _registry = {}

    @staticmethod
    def register_factory(id: str, factory: Callable):
        if id in DynamicResourcePoolManager._registry:
            raise ValueError(f"Factory already registered under ID: {id}")
        DynamicResourcePoolManager._registry[id] = factory

    @classmethod
    def create_instance(cls, resource_type_id: str, *args, **kwargs):
        if resource_type_id not in cls._registry:
            raise ValueError(f"No factory registered under ID: {resource_type_id}")
        return cls._registry[resource_type_id](*args, **kwargs)

    def __init__(self):
        self.resource_pool = []

    def initializeResourcePool(self, min_connections: int, max_connections: int, connection_timeout: int, seeded: bool, seed: Optional[int], callback: Optional[Callable[[ConnectionConfig], ConnectionConfig]]):
        if not isinstance(min_connections, int) or not isinstance(max_connections, int) or not isinstance(connection_timeout, int):
            raise ValueError("min_connections, max_connections, and connection_timeout must be integers")
        # Additional validation logic can be added here
        self.min_connections = min_connections
        self.max_connections = max_connections
        self.connection_timeout = connection_timeout
        if seeded:
            for _ in range(min_connections):
                conn = Connection(seed=seed)
                if callback:
                    conn = callback(conn)
                self.resource_pool.append(conn)

    def getConnection(self) -> 'Connection':
        if not self.resource_pool:
            raise RuntimeError("No connections available in the pool")
        return self.resource_pool.pop()

    def returnConnection(self, conn: 'Connection'):
        if len(self.resource_pool) < self.max_connections:
            self.resource_pool.append(conn)
        else:
            conn.close()  # Assuming Connection has a close method

# Example usage
class ConnectionConfig:
    pass

class Connection:
    def __init__(self, seed=None):
        self.seed = seed

    def close(self):
        print("Connection closed")

def create_db_connection(config: ConnectionConfig) -> 'DatabaseConnection':
    return DatabaseConnection()

DynamicResourcePoolManager.register_factory('db', create_db_connection)

# Creating an instance of DynamicResourcePoolManager using the registered factory
resource_pool_manager = DynamicResourcePoolManager.create_instance('db')
resource_pool_manager.initializeResourcePool(min_connections=2, max_connections=5, connection_timeout=30, seeded=True, seed=42)
connection = resource_pool_manager.getConnection()
resource_pool_manager.returnConnection(connection)
