namespace SessionManagement {

class SecureSessionIDGenerator {
public:
    SecureSessionIDGenerator() {
        std::mt19937_64 generator;
        uint64_t seed = time(nullptr);
        if (!RAND_bytes(reinterpret_cast<unsigned char*>(&seed), sizeof(seed))) {
            throw std::runtime_error("Failed to generate secure seed");
        }
        generator.seed(seed);

        // Seed with system entropy
        generator.discard(RAND_get_entropy());

        // Seed with Redis node ID (hypothetical function)
        uint64_t nodeId = getRedisNodeID();
        if (nodeId != 0) {
            generator.discard(nodeId);
        }

        sessionIDGenerator = std::make_shared<std::mt19937_64>(generator);
    }

    ~SecureSessionIDGenerator() {}

    std::string generateSessionID() {
        while (true) {
            std::uniform_int_distribution<uint64_t> distribution;
            uint64_t sessionId = distribution(*sessionIDGenerator);

            if (!isSessionIDDuplicate(sessionId)) {
                return base64Encode(sessionId);
            }
        }
    }

private:
    std::shared_ptr<std::mt19937_64> sessionIDGenerator;

    std::string base64Encode(uint64_t sessionId) {
        std::stringstream ss;
        ss << std::hex << sessionId;
        std::string hexString = ss.str();
        std::string base64Encoded;
        for (size_t i = 0; i < hexString.length(); i += 3) {
            uint8_t firstByte = std::stoi(hexString.substr(i, 1), nullptr, 16);
            uint8_t secondByte = std::stoi(hexString.substr(i + 1, 1), nullptr, 16);
            uint8_t thirdByte = (i + 2 < hexString.length()) ? std::stoi(hexString.substr(i + 2, 1), nullptr, 16) : 0;

            base64Encoded += (char)((firstByte >> 2) & 0x3F);
            base64Encoded += (char)(((firstByte << 4) | (secondByte >> 4)) & 0x3F);
            base64Encoded += (i + 1 < hexString.length()) ? (char)(((secondByte << 2) | (thirdByte >> 6)) & 0x3F) : '=';
            base64Encoded += (i + 2 < hexString.length()) ? (char)(thirdByte & 0x3F) : '=';
        }

        while (base64Encoded.length() % 4 != 0) {
            base64Encoded += '=';
        }

        return base64Encoded;
    }

    bool isSessionIDDuplicate(uint64_t sessionId) {
        // Use Redis to check for duplicates (hypothetical function)
        redis::Client client("tcp://127.0.0.1:6379");
        redis::SimpleKeyVal<std::string, std::string> key(client, "sessionIDs");

        if (key.exists(std::to_string(sessionId))) {
            return true;
        }

        key.set(std::to_string(sessionId), "used");
        return false;
    }
};

