// Function to concurrently process log files within a specified directory
void process_log_files(const char *directory_path, const char *service_endpoint) {
    DIR *dir = opendir(directory_path);
    if (dir == NULL) {
        perror("Failed to open directory");
        return;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        // Check if the entry is a log file
        if (strcmp(entry->d_type, DT_REG) == 0 && strstr(entry->d_name, ".log") != NULL) {
            char log_file_path[1024];
            snprintf(log_file_path, sizeof(log_file_path), "%s/%s", directory_path, entry->d_name);

            // Process the log file using a separate thread
            pthread_t thread_id;
            if (pthread_create(&thread_id, NULL, process_log_file_thread, log_file_path) != 0) {
                perror("Failed to create thread");
            }
        }
    }

    closedir(dir);
}

// Thread function to process a single log file
void *process_log_file_thread(void *arg) {
    const char *log_file_path = (const char *) arg;

    // Open the log file
    FILE *log_file = fopen(log_file_path, "r");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return NULL;
    }

    double sum = 0.0;
    int count = 0;

    // Read and process each line of the log file
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), log_file)) {
        // Extract the last two numerical fields from the line
        double field1, field2;
        int num_fields = sscanf(buffer, "%*[^ ] %lf %lf", &field1, &field2);

        if (num_fields == 2) {
            sum += field2;
            count++;
        }
    }

    // Calculate the average of the last two numerical fields
    double average = count > 0 ? sum / count : 0.0;

    // Close log file and return the result
    fclose(log_file);
    pthread_exit((void *) (long) average);
}

// Main function to handle command-line arguments and call the appropriate functions
int main(int argc, char *argv[]) {
    if (argc < 5) {
        fprintf(stderr, "Usage: %s <input_binary_file> <output_file> <rules> <directory_path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *input_binary_file = argv[1];
    const char *output_file = argv[2];
    const char *rules = argv[3];
    const char *directory_path = argv[4];

    // Process the input binary file
    read_binary_file(input_binary_file, output_file, rules);

    // Process the log files concurrently
    process_log_files(directory_path, "http://example.com/log-service");

    return EXIT_SUCCESS;
}
