#include <iostream>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>
#include <cstdlib>

class SemaphoreManager {
public:
    SemaphoreManager(int initialCount, int maxCount) 
        : available(initialCount), max(maxCount) {}

    void acquire() {
        std::unique_lock<std::mutex> lock(mutex);
        condition.wait(lock, [this] { return available > 0; });
        --available;
    }

    void release() {
        std::unique_lock<std::mutex> lock(mutex);
        ++available;
        condition.notify_one();
    }

private:
    int available;
    int max;
    std::mutex mutex;
    std::condition_variable condition;
};

class DistributedSemaphoreManager {
public:
    void createSemaphore(const std::string& semaphoreId, int initialCount, int maxCount) {
        semaphores[semaphoreId] = std::make_shared<SemaphoreManager>(initialCount, maxCount);
    }

    void deleteSemaphore(const std::string& semaphoreId) {
        semaphores.erase(semaphoreId);
    }

    void acquire(const std::string& semaphoreId) {
        if (auto it = semaphores.find(semaphoreId); it != semaphores.end()) {
            it->second->acquire();
        } else {
            throw std::runtime_error("Semaphore not found");
        }
    }

    void release(const std::string& semaphoreId) {
        if (auto it = semaphores.find(semaphoreId); it != semaphores.end()) {
            it->second->release();
        } else {
            throw std::runtime_error("Semaphore not found");
        }
    }

private:
    std::unordered_map<std::string, std::shared_ptr<SemaphoreManager>> semaphores;
};

int main() {
    DistributedSemaphoreManager manager;

    // Example usage
    manager.createSemaphore("dbConnection", 10, 10);

    std::thread t1([&manager]() { 
        for (int i = 0; i < 5; ++i) {
            manager.acquire("dbConnection");
            // Simulate database operation
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
            manager.release("dbConnection");
        }
    });

    std::thread t2([&manager]() { 
        for (int i = 0; i < 5; ++i) {
            manager.acquire("dbConnection");
            // Simulate database operation
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
            manager.release("dbConnection");
        }
    });

    t1.join();
    t2.join();

    return 0;
}
