app.config['SECRET_KEY'] = 'your_secret_key'
app.config['SESSION_TYPE'] = 'filesystem'
oauth = OAuth(app)
Session(app)

db = SQLAlchemy(app)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password_hash = db.Column(db.String(120), nullable=False)
    tenant_id = db.Column(db.Integer, db.ForeignKey('tenant.id'), nullable=False)

class Tenant(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(80), unique=True, nullable=False)

class Role(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(80), unique=True, nullable=False)
    permissions = db.relationship('Permission', backref='role')

class Permission(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    action = db.Column(db.String(80), nullable=False)
    role_id = db.Column(db.Integer, db.ForeignKey('role.id'), nullable=False)

oauth.register(
    name='oauth2_provider',
    client_id='your_client_id',
    client_secret='your_client_secret',
    access_token_url='https://provider.com/oauth/token',
    access_token_params=None,
    authorize_url='https://provider.com/oauth/authorize',
    authorize_params=None,
    api_base_url='https://provider.com/api/',
    client_kwargs={'scope': 'openid profile email'}
)

@app.before_request
def before_request():
    if request.endpoint not in ['login', 'oauth2_provider.authorize']:
        access_token = request.headers.get('Authorization')
        if not access_token:
            return jsonify({'error': 'Unauthorized'}), 401
        user_info = oauth.oauth2_provider.userinfo(token=access_token)
        if not user_info:
            return jsonify({'error': 'Unauthorized'}), 401
        g.current_user = User.query.filter_by(username=user_info['username']).first()
        if not g.current_user:
            return jsonify({'error': 'User not found'}), 404

@app.route('/login', methods=['POST'])
def login():
    username = request.form.get('username')
    password = request.form.get('password')
    user = User.query.filter_by(username=username).first()
    if user and user.password_hash == password:
        return jsonify({'message': 'Login successful'}), 200
    else:
        return jsonify({'error': 'Invalid credentials'}), 401

@app.route('/protected', methods=['GET'])
def protected():
    if g.current_user:
        return jsonify({'message': f'Welcome, {g.current_user.username}!'})
    else:
        return jsonify({'error': 'Unauthorized'}), 401

if __name__ == '__main__':
    app.run(debug=True)
