    def __init__(self, storage):
        self.storage = storage

    def compress_file(self, input_path, output_path, level=6):
        with open(input_path, 'rb') as f_in:
            compressed_data = lz4.frame.compress(f_in.read(), compression_level=level)
        with open(output_path, 'wb') as f_out:
            f_out.write(compressed_data)

        # Store metadata in the storage system
        metadata = {'compression_level': level}
        self.storage.store_metadata(input_path, metadata)

    def decompress_file(self, input_path, output_path):
        with open(input_path, 'rb') as f_in:
            compressed_data = f_in.read()
        try:
            decompressed_data = lz4.frame.decompress(compressed_data)
        except lz4.exceptions.LZ4Error:
            raise ValueError("Decompression failed")

        # Retrieve metadata and verify integrity
        metadata = self.storage.retrieve_metadata(input_path)
        if not metadata:
            raise ValueError("Metadata not found for file")

        with open(output_path, 'wb') as f_out:
            f_out.write(decompressed_data)

