```rust
use std::env;
use std::fs::{create_dir_all, remove_dir_all};
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;

struct FileManager {
    working_dir: Arc<Mutex<PathBuf>>,
}

impl FileManager {
    fn new() -> Self {
        let mut fm = FileManager {
            working_dir: Arc::new(Mutex::new(None)),
        };
        fm.initialize_working_directory().unwrap();
        fm
    }

    fn initialize_working_directory(&self) -> Result<(), std::io::Error> {
        if let Ok(work_dir) = env::var("WORK_DIR") {
            if Self::is_valid_directory(&work_dir) {
                self.working_dir.lock().unwrap().replace(PathBuf::from(work_dir));
            }
        }

        if self.working_dir.lock().unwrap().is_none() {
            let new_dir = PathBuf::from("/tmp").join(format!("ci_workdir_{}", uuid::Uuid::new_v4()));
            create_dir_all(&new_dir)?;
            self.working_dir.lock().unwrap().replace(new_dir);
        }

        Ok(())
    }

    fn is_valid_directory(path: &str) -> bool {
        let path = PathBuf::from(path);
        if !path.exists() {
            return false;
        }
        if !path.is_dir() {
            return false;
        }
        // Check permissions and space availability here
        true
    }

    fn get_working_directory(&self) -> Result<PathBuf, std::io::Error> {
        let dir = self.working_dir.lock().unwrap().as_ref().cloned();
        if dir.is_none() {
            return Err(std::io::Error::new(
                std::io::ErrorKind::Other,
                "Working directory not initialized",
            ));
        }
        Ok(dir.unwrap())
    }

    fn cleanup_directory(&self) -> Result<(), std::io::Error> {
        let mut dir = self.working_dir.lock().unwrap();
        if let Some(d) = dir.take() {
            remove_dir_all(&d)?;
        }
        Ok(())
    }

    fn spawn_cleanup_thread(&self, interval: Duration) {
        let fm = Arc::clone(&self.working_dir);
        thread::spawn(move || loop {
            thread::sleep(interval);
            if let Err(e) = fm.lock().unwrap().take() {
                eprintln!("Error cleaning up directory: {:?}", e);
            }
        });
    }
}

fn main() {
    let file_manager = FileManager::new();
    println!("Working Directory: {:?}", file_manager.get_working_directory());

    // Simulate cleanup after some time
    file_manager.spawn_cleanup_thread(Duration::from_secs(60));
}
