    }

    @Test
    public void testCacheFunctionality() {
        String result = loadBalancer.cache.get("cacheableType").result;
        assertNull(result, "Expected cache entry to be null initially");

        loadBalancer.submitTask("cacheableType", task -> "cachedResult");
        assertNotNull(loadBalancer.cache.get("cacheableType"), "Expected cache entry to be populated");

        loadBalancer.submitTask("cacheableType", task -> "shouldNotUpdateCache");
        assertEquals("cachedResult", loadBalancer.cache.get("cacheableType").result, "Expected cache not to update with new result");
    }
}
