```javascript
function copyBufferChunks(chunks, numBytes, sourceId, encoding) {
    // Validate input parameters
    if (!Array.isArray(chunks)) {
        throw new Error('Invalid input: chunks must be an array');
    }
    if (typeof numBytes !== 'number' || numBytes < 0) {
        throw new Error('Invalid input: numBytes must be a non-negative number');
    }
    if (typeof sourceId !== 'string' || sourceId.trim() === '') {
        throw new Error('Invalid input: sourceId must be a non-empty string');
    }
    if (!['utf8', 'utf16le'].includes(encoding)) {
        throw new Error('Invalid input: encoding must be either "utf8" or "utf16le"');
    }

    // Calculate total available bytes
    let totalBytes = chunks.reduce((acc, chunk) => acc + (chunk instanceof Buffer ? chunk.length : 0), 0);

    if (numBytes > totalBytes) {
        throw new Error('Requested byte count exceeds available data');
    }

    // Merge chunks into a single buffer
    let mergedBuffer = Buffer.alloc(numBytes);
    let bytesRead = 0;

    for (let i = 0; bytesRead < numBytes && i < chunks.length; i++) {
        if (!(chunks[i] instanceof Buffer)) {
            throw new Error(`Invalid chunk at index ${i}: expected a buffer`);
        }

        let bytesToCopy = Math.min(numBytes - bytesRead, chunks[i].length);
        chunks[i].copy(mergedBuffer, bytesRead, 0, bytesToCopy);
        bytesRead += bytesToCopy;
    }

    // Log to external database
    logToDatabase({
        timestamp: new Date().toISOString(),
        sourceId,
        dataLength: mergedBuffer.length,
        encoding
    });

    return mergedBuffer;
}

function logToDatabase(logEntry) {
    // Placeholder for logging implementation
    console.log('Log Entry:', logEntry);
}
