from typing import Dict, Any, Optional

class SessionData:
    def __init__(self, user_id: int, last_activity: datetime, ip_address: str, device_type: str):
        self.user_id = user_id
        self.last_activity = last_activity
        self.ip_address = ip_address
        self.device_type = device_type

class UserSessionManager(ABC):
    _session_cache: Dict[str, SessionData] = {}
    _factory_functions: Dict[str, Any] = {}

    @abstractmethod
    def update_session_data(self, session_id: str, data: Dict[str, Any]) -> None:
        pass

    @abstractmethod
    def validate_user_session(self, session_id: str) -> bool:
        pass

    @staticmethod
    def convert_to_json(session_data: SessionData) -> str:
        return json.dumps({
            'user_id': session_data.user_id,
            'last_activity': session_data.last_activity.isoformat(),
            'ip_address': session_data.ip_address,
            'device_type': session_data.device_type
        })

    @staticmethod
    def from_json(json_str: str) -> SessionData:
        data = json.loads(json_str)
        return SessionData(
            user_id=data['user_id'],
            last_activity=datetime.fromisoformat(data['last_activity']),
            ip_address=data['ip_address'],
            device_type=data['device_type']
        )

    @classmethod
    def register_factory_function(cls, session_type: str, factory_func: Any) -> None:
        cls._factory_functions[session_type] = factory_func

    @classmethod
    def create_session_instance(cls, session_type: str, *args, **kwargs) -> Any:
        if session_type in cls._factory_functions:
            return cls._factory_functions[session_type](*args, **kwargs)
        raise ValueError(f"Factory function not registered for session type: {session_type}")

