```c
#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>
#include <pthread.h>

typedef struct {
    sem_t *sem;
    int permits;
} semaphore_manager;

semaphore_manager* create_semaphore_manager(int initial_permits) {
    semaphore_manager *manager = (semaphore_manager*)malloc(sizeof(semaphore_manager));
    manager->permits = initial_permits;
    if (sem_init(manager->sem, 0, initial_permits) != 0) {
        perror("Semaphore initialization failed");
        free(manager);
        return NULL;
    }
    return manager;
}

void destroy_semaphore_manager(semaphore_manager *manager) {
    sem_destroy(manager->sem);
    free(manager);
}

int adjust_semaphore_permits(semaphore_manager *manager, int new_permits) {
    if (new_permits < 0) {
        perror("Invalid number of permits");
        return -1;
    }
    manager->permits = new_permits;
    sem_init(manager->sem, 0, new_permits);
    return 0;
}

int acquire_semaphore(semaphore_manager *manager) {
    if (sem_wait(manager->sem) == 0) {
        return 0;
    } else {
        perror("Semaphore acquisition failed");
        return -1;
    }
}

int release_semaphore(semaphore_manager *manager) {
    if (sem_post(manager->sem) == 0) {
        return 0;
    } else {
        perror("Semaphore release failed");
        return -1;
    }
}

int main() {
    semaphore_manager *manager = create_semaphore_manager(5);
    if (manager != NULL) {
        printf("Semaphore created with %d permits\n", manager->permits);

        for (int i = 0; i < 3; i++) {
            if (acquire_semaphore(manager) == 0) {
                printf("Thread %d acquired semaphore\n", i);
            } else {
                printf("Thread %d failed to acquire semaphore\n", i);
            }
        }

        adjust_semaphore_permits(manager, 10);

        for (int i = 3; i < 6; i++) {
            if (acquire_semaphore(manager) == 0) {
                printf("Thread %d acquired semaphore\n", i);
            } else {
                printf("Thread %d failed to acquire semaphore\n", i);
            }
        }

        release_semaphore(manager);
        release_semaphore(manager);
        release_semaphore(manager);

        destroy_semaphore_manager(manager);
    }

    return 0;
}
