```javascript
const MongoClient = require('mongodb').MongoClient;
const stream = require('stream');

class DataSaver {
  constructor(url, dbName) {
    this.url = url;
    this.dbName = dbName;
    this.client = null;
    this.collection = null;
    this.paused = false;
    this.stream = new stream.PassThrough();
  }

  async connect() {
    try {
      this.client = await MongoClient.connect(this.url, { useNewUrlParser: true, useUnifiedTopology: true });
      this.collection = this.client.db(this.dbName).collection('data');
    } catch (error) {
      console.error('Error connecting to MongoDB:', error);
    }
  }

  async saveData() {
    if (!this.stream.readable || !this.stream.writable) return;

    try {
      for await (const chunk of this.stream) {
        const document = { data: chunk.toString() };
        await this.collection.insertOne(document);
      }
    } catch (error) {
      console.error('Error saving data to MongoDB:', error);
    }
  }

  pause() {
    this.paused = true;
    this.stream.pause();
  }

  resume() {
    if (!this.paused) return;
    this.paused = false;
    this.stream.resume();
  }

  async close() {
    try {
      await this.collection.insertOne({ status: 'stream end' });
      this.stream.end();
      await this.client.close();
    } catch (error) {
      console.error('Error closing connection:', error);
    }
  }
}

// Usage example:
const saver = new DataSaver('mongodb://localhost:27017', 'mydatabase');
saver.connect().then(() => {
  // Connect to the stream and pipe it to the saver
  const networkStream = ...; // Assume this is a readable stream from a network source
  networkStream.pipe(saver.stream);

  // To pause saving data:
  saver.pause();

  // To resume saving data:
  saver.resume();

  // When done, close the connection and save the end status to MongoDB
  saver.close();
});
