typedef struct {
    char *access_token;
    int expires_in;
    char *token_type;
    char *refresh_token;
} OAuthToken;

typedef struct {
    CURL *handle;
    struct curl_slist *headers;
} RequestBuilder;

bool is_valid_oauth_token(const char *json) {
    // Streaming JSON parser logic
    // ...

    if (!has_required_fields(token)) {
        return false;
    }

    if (strcmp(token->token_type, "Bearer") != 0) {
        return false;
    }

    if (token->expires_in <= 0) {
        return false;
    }

    return true;
}

RequestBuilder* create_request_builder(const char *url, bool disable_ssl) {
    CURL *handle = curl_easy_init();
    if (!handle) {
        fprintf(stderr, "Failed to initialize libcurl\n");
        return NULL;
    }

    RequestBuilder *builder = (RequestBuilder*)malloc(sizeof(RequestBuilder));
    builder->handle = handle;
    builder->headers = NULL;

    curl_easy_setopt(handle, CURLOPT_URL, url);

    if (disable_ssl) {
        curl_easy_setopt(handle, CURLOPT_SSL_VERIFYPEER, 0L);
        curl_easy_setopt(handle, CURLOPT_SSL_VERIFYHOST, 0L);
    }

    return builder;
}

void free_request_builder(RequestBuilder *builder) {
    if (builder->headers) {
        curl_slist_free_all(builder->headers);
    }
    curl_easy_cleanup(builder->handle);
    free(builder);
}
