```javascript
class ScriptLoader {
  constructor() {
    this.scripts = [];
    this.loadedScripts = new Set();
    this.errorHandlers = [];
    this.loadingIndicators = {};
    this.cachingEnabled = true;
  }

  addScript(url, options) {
    if (this.scripts.some(s => s.url === url)) return;

    this.scripts.push({
      url,
      ...options
    });
  }

  setCacheState(state) {
    this.cachingEnabled = state;
  }

  onError(callback) {
    this.errorHandlers.push(callback);
  }

  onLoadingIndicator(scriptUrl, element) {
    this.loadingIndicators[scriptUrl] = element;
  }

  loadAllScripts() {
    const promises = this.scripts.map(this.loadScript.bind(this));
    Promise.all(promises).then(() => {
      console.log('All scripts loaded successfully');
    }).catch((error) => {
      console.error('Error loading scripts:', error);
      this.errorHandlers.forEach(handler => handler(error));
    });
  }

  async loadScript(script) {
    if (this.loadedScripts.has(script.url)) return;

    const element = document.createElement('script');
    element.src = script.url;
    element.async = true;
    element.defer = !!script.defer;
    element.onload = () => {
      this.loadedScripts.add(script.url);
      console.log(`Script loaded successfully: ${script.url}`);
      delete this.loadingIndicators[script.url];
    };
    element.onerror = (error) => {
      if (this.errorHandlers.length > 0) {
        const errorHandler = this.errorHandlers.shift();
        errorHandler(error, () => this.retryLoad(script));
      }
    };

    document.head.appendChild(element);

    if (this.cachingEnabled && script.cacheKey) {
      localStorage.setItem(script.cacheKey, JSON.stringify({ url: script.url, timestamp: Date.now() }));
    }
  }

  async retryLoad(script) {
    const cachedData = localStorage.getItem(script.cacheKey);
    if (cachedData) {
      const { url } = JSON.parse(cachedData);
      if (url === script.url) return this.loadScript(script); // Retry loading from cache
    }

    this.onError(new Error(`Failed to load script: ${script.url}`));
  }
}

// Usage Example:
const scriptLoader = new ScriptLoader();
scriptLoader.addScript('https://example.com/lib.js', { defer: true });
scriptLoader.addScript('https://example.com/custom-script.js');
scriptLoader.setCacheState(true);

scriptLoader.onError((error, retry) => {
  console.error(error);
  retry(); // Retry loading the script
});

const spinnerElement = document.createElement('div');
spinnerElement.textContent = 'Loading...';
document.body.appendChild(spinnerElement);
scriptLoader.onLoadingIndicator('https://example.com/lib.js', spinnerElement);

scriptLoader.loadAllScripts();
