// Function to collect data from network stream and save to MongoDB
async function collectDataFromNetworkAndSaveToMongo(networkStreamUrl, mongoDbConfig) {
  try {
    // Load available protocols dynamically
    const protocolDirectory = './protocols';
    const protocols = await loadAvailableProtocols(protocolDirectory);

    // Select a suitable protocol based on the network stream URL
    const selectedProtocol = selectSuitableProtocol(protocols, networkStreamUrl);

    // Initialize MongoDB connection
    const dbConnection = await initializeMongoDb(mongoDbConfig);

    // Pause and resume functionality variables
    let isPaused = false;

    // Function to pause data collection
    function pauseDataCollection() {
      isPaused = true;
    }

    // Function to resume data collection
    function resumeDataCollection() {
      isPaused = false;
    }

    // Stream data from network using selected protocol
    const networkStream = await selectedProtocol.streamData(networkStreamUrl);

    for await (const chunk of networkStream) {
      if (isPaused) {
        continue; // Skip processing if paused
      }

      try {
        // Save chunk to MongoDB database
        await dbConnection.saveData(chunk);
      } catch (error) {
        console.error('Error saving data to MongoDB:', error);
      }
    }

    // Close MongoDB connection
    await dbConnection.close();

    return 'Data collection and saving completed successfully';
  } catch (error) {
    console.error('Error collecting data from network and saving to MongoDB:', error);
    throw error;
  }
}

// Function to load available protocols dynamically from a directory
async function loadAvailableProtocols(directory) {
  const fs = require('fs');
  const path = require('path');

  return new Promise((resolve, reject) => {
    fs.readdir(directory, (err, files) => {
      if (err) {
        return reject(err);
      }

      const protocolPromises = files.map(file => loadProtocol(path.join(directory, file)));

      Promise.all(protocolPromises)
        .then(protocols => resolve(protocols))
        .catch(reject);
    });
  });
}

// Function to load a single protocol implementation
function loadProtocol(protocolPath) {
  return new Promise((resolve, reject) => {
    try {
      const protocol = require(protocolPath);
      resolve(protocol);
    } catch (error) {
      console.error('Error loading protocol:', error);
      reject(error);
    }
  });
}

