```c
#include <stdio.h>
#include <stdlib.h>

typedef void (*TaskFunction)(void);

typedef struct Task {
    int id;
    int priority;
    long deadline;
    TaskFunction function;
    struct Task* next;
} Task;

Task* create_task(int id, int priority, long deadline, TaskFunction function) {
    Task* new_task = (Task*)malloc(sizeof(Task));
    if (new_task == NULL) {
        return NULL; // Handle memory allocation failure
    }
    new_task->id = id;
    new_task->priority = priority;
    new_task->deadline = deadline;
    new_task->function = function;
    new_task->next = NULL;
    return new_task;
}

Task* filter_tasks(Task* tasks, int num_tasks, int min_priority, long current_time) {
    if (num_tasks == 0 || min_priority < 0 || current_time < 0) {
        return NULL; // Handle invalid input
    }

    Task* filtered_head = NULL;
    Task** last_task_ptr = &filtered_head;

    for (int i = 0; i < num_tasks; ++i) {
        if (tasks[i].priority >= min_priority && tasks[i].deadline > current_time) {
            Task* new_task = create_task(tasks[i].id, tasks[i].priority, tasks[i].deadline, tasks[i].function);
            if (new_task == NULL) {
                // Handle memory allocation failure
                while (*last_task_ptr != NULL) {
                    Task* temp = *last_task_ptr;
                    *last_task_ptr = (*last_task_ptr)->next;
                    free(temp);
                }
                return NULL;
            }
            *last_task_ptr = new_task;
            last_task_ptr = &new_task->next;
        }
    }

    return filtered_head;
}
