use std::sync::{Arc, Mutex};
use std::time::Instant;

#[derive(Debug)]
enum CompilationResult {
    Success(String),
    Failure(String),
}

fn compile_file(file_path: &str, language: &str) -> CompilationResult {
    let start_time = Instant::now();
    match language {
        "rust" => {
            // Replace with actual Rust compilation command
            let output = Command::new("rustc")
                .arg(file_path)
                .output()
                .expect("Failed to execute command");

            if output.status.success() {
                CompilationResult::Success(format!(
                    "Compiled successfully in {} ms",
                    start_time.elapsed().as_millis()
                ))
            } else {
                CompilationResult::Failure(String::from_utf8_lossy(&output.stderr).to_string())
            }
        }
        // Add support for other languages here
        _ => CompilationResult::Failure("Language not supported".to_string()),
    }
}

fn main() {
    let file_paths = vec![
        "src/main.rs",
        "src/utils.rs",
        // Add more file paths as needed
    ];

    let results = Arc::new(Mutex::new(Vec::new()));

    for file_path in file_paths {
        let results_clone = Arc::clone(&results);
        std::thread::spawn(move || {
            let result = compile_file(file_path, "rust");
            results_clone.lock().unwrap().push(result);
        });
    }

    // Wait for all threads to finish
    for _ in 0..file_paths.len() {
        std::thread::sleep(std::time::Duration::from_millis(100));
    }

    let compilation_results = results.lock().unwrap();
    println!("{:?}", compilation_results);
}
