#include <openssl/err.h>

class SandeshClient {
public:
    void Connect(const std::string& server, int port) {}
    void FetchMetadata(const std::string& ip, std::string& metadata) {}
};

class ConnectionPool {
private:
    std::vector<SandeshClient*> pool;
    std::mutex mutex;
    std::condition_variable cv;

public:
    ConnectionPool(int size) {
        for (int i = 0; i < size; ++i) {
            pool.push_back(new SandeshClient());
        }
    }

    ~ConnectionPool() {
        for (auto& client : pool) {
            delete client;
        }
    }

    SandeshClient* GetClient() {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this] { return !pool.empty(); });
        SandeshClient* client = pool.back();
        pool.pop_back();
        return client;
    }

    void ReturnClient(SandeshClient* client) {
        std::unique_lock<std::mutex> lock(mutex);
        pool.push_back(client);
        cv.notify_one();
    }
};

class InterfaceTable {
public:
    virtual std::string FindVmUuidFromMetadataIp(const std::string& ip) = 0;
};

