        mockData.push_back({"192.168.1.2", "vm-uuid-2"});
        // Add more entries as needed
    }

    std::string FindVmUuidFromMetadataIp(const std::string& ip) override {
        for (const auto& entry : mockData) {
            if (entry.first == ip) {
                return entry.second;
            }
        }
        return ""; // Return empty string if IP not found in mock data
    }
};

class MetadataFetcher {
private:
