    InterfaceTable* interfaceTable;
    std::mutex logMutex;

public:
    MetadataFetcher(ConnectionPool& pool, InterfaceTable* interfaceTable)
        : pool(pool), interfaceTable(interfaceTable) {}

    void FetchMetadata(const std::vector<std::string>& ips) {
        for (const auto& ip : ips) {
            SandeshClient* client = pool.GetClient();
            std::string metadata;
            try {
                // Simulate network conditions and server-side failures
                if (ip == "192.168.1.3") {
                    throw std::runtime_error("Server-side error");
                }
                client->FetchMetadata(ip, metadata);
                std::cout << "Successfully fetched metadata for IP: " << ip << std::endl;
            } catch (const std::exception& e) {
                std::cerr << "Error fetching metadata for IP " << ip << ": " << e.what() << std::endl;
            }
            pool.ReturnClient(client);
        }
    }

    void LogStats(int successfulRequests, int proxySessions) {
        std::lock_guard<std::mutex> lock(logMutex);
        std::cout << "Successful requests: " << successfulRequests << std::endl;
        std::cout << "Proxy sessions: " << proxySessions << std::endl;
    }
};

int main() {
    ConnectionPool pool(10); // Create a connection pool of 10 clients
    MockInterfaceTable mockInterfaceTable;

    MetadataFetcher fetcher(pool, &mockInterfaceTable);
    std::vector<std::string> ips = {"192.168.1.1", "192.168.1.2", "192.168.1.3"};
    fetcher.FetchMetadata(ips);

    // Simulate logging statistics
    fetcher.LogStats(2, 0); // Assuming 2 successful requests and no proxy sessions

    return 0;
}
