// JavaScript function to dynamically render a footer based on script objects

function renderFooter(scripts) {
    let html = '<footer>';

    // Check if scripts array is empty or not defined
    if (!scripts || !Array.isArray(scripts)) {
        console.error('Invalid scripts input');
        return '</footer>';
    }

    for (const [index, script] of scripts.entries()) {
        const key = `script-${index}`;

        // Ensure necessary properties exist in the script object
        if (!script.type && !script.src) {
            console.warn(`Script ${key} is missing essential properties`);
            continue;
        }

        html += `<script`;
        html += script.type ? ` type="${script.type}"` : '';
        html += script.src ? ` src="${script.src}" async></script>` : ``;
        if (script.code) {
            const escapedCode = escapeHTML(script.code);
            html += `<script id="${key}" innerHTML="${escapedCode}"></script>`;
        }
        html += '</script>';
    }

    html += '</footer>';
    return html;

    function escapeHTML(str) {
        return str.replace(/&/g, '&amp;')
                  .replace(/</g, '&lt;')
                  .replace(/>/g, '&gt;')
                  .replace(/"/g, '&quot;')
                  .replace(/'/g, '&#039;');
    }
}
