using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;

public class FileMetadataProcessor
{
    private string directoryPath;
    private long minSizeThreshold;
    private long maxSizeThreshold;
    private ILogger logger;

    public FileMetadataProcessor(string directoryPath, long minSizeThreshold, long maxSizeThreshold, ILogger logger)
    {
        this.directoryPath = directoryPath;
        this.minSizeThreshold = minSizeThreshold;
        this.maxSizeThreshold = maxSizeThreshold;
        this.logger = logger ?? throw new ArgumentNullException(nameof(logger));
        ValidateFileSizeRange();
    }

    private void ValidateFileSizeRange()
    {
        if (minSizeThreshold > maxSizeThreshold)
        {
            throw new ArgumentException("Minimum file size threshold must be less than or equal to the maximum file size threshold.");
        }
    }

    public IEnumerable<FileMetadata> GetFileMetadatas(int batchSize = 100, int parallelismLevel = Environment.ProcessorCount)
    {
        var filePaths = Directory.GetFiles(directoryPath).ToList();
        var fileMetadatas = new List<FileMetadata>();

        int totalFiles = filePaths.Count;
        for (int i = 0; i < totalFiles; i += batchSize)
        {
            var batch = filePaths.Skip(i).Take(batchSize).ToList();
            Parallel.For(0, batch.Count, index =>
            {
                try
                {
                    var filePath = batch[index];
                    if (File.Exists(filePath) && File.GetAttributes(filePath).HasFlag(FileAttributes.Directory))
                        return;

                    var fileInfo = new FileInfo(filePath);
                    if (fileInfo.Length >= minSizeThreshold && fileInfo.Length <= maxSizeThreshold)
                    {
                        fileMetadatas.Add(new FileMetadata
                        {
                            FilePath = filePath,
                            Size = fileInfo.Length,
                            CreationTime = fileInfo.CreationTime,
                            LastWriteTime = fileInfo.LastWriteTime
                        });
                    }
                }
                catch (Exception ex)
                {
                    logger.LogError(ex, $"Error processing file: {batch[index]}");
                }
            }, new ParallelOptions { MaxDegreeOfParallelism = parallelismLevel });

            if ((i + batchSize) >= totalFiles)
                break;
        }

        return fileMetadatas.AsEnumerable();
    }

    public override string ToString()
    {
        return $"Size Range: [{minSizeThreshold}, {maxSizeThreshold}] KB";
    }
}

public class FileMetadata
{
    public string FilePath { get; set; }
    public long Size { get; set; }
    public DateTime CreationTime { get; set; }
    public DateTime LastWriteTime { get; set; }
}

public interface ILogger
{
    void LogError(Exception ex, string message);
}
