using System;
using System.Collections.Generic;

public class ValueGenerator : MonoBehaviour
{
    private int _minValue;
    private int _maxValue;
    private float[] _floatBuffer;
    private int[] _intBuffer;

    public ValueGenerator(int minValue, int maxValue)
    {
        if (minValue > maxValue) throw new ArgumentException("Min value must be less than or equal to max value");
        _minValue = minValue;
        _maxValue = maxValue;
        _floatBuffer = new float[1024];
        _intBuffer = new int[1024];
    }

    public float GetRandomFloat(float min = 0f, float max = 1f)
    {
        return UnityEngine.Random.Range(min, max);
    }

    public int GetRandomInt(int min = 0, int max = int.MaxValue)
    {
        return UnityEngine.Random.Range(min, max + 1);
    }

    public int[] GetRandomIntArray(int size, bool usePool = true)
    {
        if (size > _intBuffer.Length) throw new ArgumentException("Size exceeds buffer capacity");
        for (int i = 0; i < size; i++)
        {
            _intBuffer[i] = GetRandomInt(_minValue, _maxValue);
        }
        return usePool ? _intBuffer : new int[size];
    }

    public int[] GetWeightedRandomIntArray(int size, float[] weights)
    {
        if (size > _intBuffer.Length) throw new ArgumentException("Size exceeds buffer capacity");
        for (int i = 0; i < size; i++)
        {
            _intBuffer[i] = GetRandomInt(_minValue, _maxValue);
        }
        return usePool ? _intBuffer : new int[size];
    }

    public float[] GetRandomFloatArray(int size, bool withinBounds = true)
    {
        if (size > _floatBuffer.Length) throw new ArgumentException("Size exceeds buffer capacity");
        for (int i = 0; i < size; i++)
        {
            _floatBuffer[i] = GetRandomFloat(withinBounds ? _minValue : float.MinValue, withinBounds ? _maxValue : float.MaxValue);
        }
        return usePool ? _floatBuffer : new float[size];
    }

    public float[] GetGaussianRandomFloatArray(int size, float mean = 0f, float stdDev = 1f)
    {
        if (size > _floatBuffer.Length) throw new ArgumentException("Size exceeds buffer capacity");
        for (int i = 0; i < size; i++)
        {
            // Box-Muller transform
            float u1 = UnityEngine.Random.value;
            float u2 = UnityEngine.Random.value;
            float z0 = Mathf.Sqrt(-2.0f * Mathf.Log(u1)) * Mathf.Cos(2.0f * Mathf.PI * u2);
            _floatBuffer[i] = mean + stdDev * z0;
        }
        return usePool ? _floatBuffer : new float[size];
    }

    public override string ToString()
    {
        return $"ValueGenerator: {_minValue}-{_maxValue}";
    }

    // Serialization and deserialization methods go here
}
