import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class FileHashValidator {

    private static final int MAX_RETRIES = 3;

    public Map<String, String> validateFileHashes(List<Path> filePaths) throws HashMismatchException {
        ExecutorService executorService = Executors.newFixedThreadPool(filePaths.size());
        Map<String, String> fileHashMap = new HashMap<>();
        for (Path path : filePaths) {
            executorService.submit(() -> {
                try {
                    String hash = computeMD5(path);
                    String apiHash = getApiMd5Hash(path.toString());
                    if (!hash.equals(apiHash)) {
                        throw new HashMismatchException("Hash mismatch for file: " + path, path.toString(), hash, apiHash);
                    }
                    synchronized (fileHashMap) {
                        fileHashMap.put(path.toString(), hash);
                    }
                } catch (IOException | NoSuchAlgorithmException | InterruptedException e) {
                    Thread.currentThread().interrupt();
                    throw new RuntimeException(e);
                }
            });
        }
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(1, TimeUnit.HOURS)) {
                executorService.shutdownNow();
                throw new RuntimeException("Hash validation timed out");
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException(e);
        }
        return fileHashMap;
    }

    private String computeMD5(Path path) throws IOException, NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("MD5");
        Files.walk(path)
             .filter(Files::isRegularFile)
             .forEach(file -> {
                 try (var fis = Files.newInputStream(file)) {
                     byte[] buffer = new byte[8192];
                     int bytesRead;
                     while ((bytesRead = fis.read(buffer)) != -1) {
                         digest.update(buffer, 0, bytesRead);
                     }
                 } catch (IOException e) {
                     throw new RuntimeException(e);
                 }
             });
        return bytesToHex(digest.digest());
    }

    private String getApiMd5Hash(String filePath) throws IOException, InterruptedException {
        // Implement the logic to call the external hashing service API
        // Example: Use HttpClient or similar library to make a GET request
        // Parse the response and extract the MD5 hash value
        // Retry on transient errors up to MAX_RETRIES times
        throw new UnsupportedOperationException("API validation logic is not implemented");
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static class HashMismatchException extends Exception {
        private final String filePath;
        private final String expectedHash;
        private final String actualHash;

        public HashMismatchException(String message, String filePath, String expectedHash, String actualHash) {
            super(message);
            this.filePath = filePath;
            this.expectedHash = expectedHash;
            this.actualHash = actualHash;
        }

        // Getters and setters
    }
}
