using System.Security.Cryptography;

public class SqlQueryExecutor
{
    public IDataReader ExecuteDynamicSql(string connectionString, string sqlTemplate, List<object> parameters, CipherMode cipherMode)
    {
        // Validate input values
        if (string.IsNullOrEmpty(connectionString) || string.IsNullOrEmpty(sqlTemplate))
        {
            throw new ArgumentException("Connection string and SQL template are required.");
        }
        if (parameters == null || parameters.Count == 0)
        {
            throw new ArgumentException("At least one parameter is required.");
        }

        // Create a parameterized SQL command
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            SqlCommand command = new SqlCommand(sqlTemplate, connection);
            foreach (var param in parameters)
            {
                command.Parameters.AddWithValue("@", param);
            }

            try
            {
                // Open the connection and execute the command
                connection.Open();
                return command.ExecuteReader(CommandBehavior.CloseConnection);
            }
            catch (SqlException ex)
            {
                // Log the error and rethrow if necessary
                Console.WriteLine($"SQL Error: {ex.Message}");
                throw;
            }
        }
    }

    public CipherHandle GetCipherHandle(CipherMode cipherMode)
    {
        using (DESCryptoServiceProvider des = new DESCryptoServiceProvider())
        {
            des.Mode = cipherMode;

            IntPtr handle = Marshal.AllocHGlobal(Marshal.SizeOf(des));
            Marshal.StructureToPtr(des, handle, false);
            return new CipherHandle(handle);
        }
    }

    public void Configure(string connectionString, string sqlTemplate, CipherMode cipherMode)
    {
        // Placeholder for configuration logic
    }
}

public struct CipherHandle : IDisposable
{
    private IntPtr _handle;

    internal CipherHandle(IntPtr handle)
    {
        _handle = handle;
    }

    public bool IsValid => _handle != IntPtr.Zero;

    public void Dispose()
    {
        if (_handle != IntPtr.Zero)
        {
            Marshal.FreeHGlobal(_handle);
            _handle = IntPtr.Zero;
        }
    }
}
