<?php

class OAuth2Authenticator {
    private $provider;
    private $client_id;
    private $client_secret;
    private $redirect_uri;
    private $access_token_cache;
    private $user_info_cache;

    public function __construct($provider, $client_id, $client_secret, $redirect_uri) {
        $this->provider = $provider;
        $this->client_id = $client_id;
        $this->client_secret = $client_secret;
        $this->redirect_uri = urlencode($redirect_uri);
        $this->access_token_cache = new Cache();
        $this->user_info_cache = new Cache();
    }

    public function authenticate() {
        session_start();

        if (!isset($_GET['code'])) {
            // Redirect to the OAuth provider's login page
            header('Location: ' . $this->getAuthorizationUrl());
            exit;
        }

        // Exchange authorization code for access token
        $access_token = $this->getAccessToken($_GET['code']);

        // Store access token in session
        $_SESSION['oauth_access_token'] = $access_token;

        // Retrieve user information using access token
        $user_info = $this->getUserInfo($access_token);

        // Update user database based on OAuth response
        $this->updateUserDatabase($user_info);
    }

    private function getAuthorizationUrl() {
        switch ($this->provider) {
            case 'google':
                return "https://accounts.google.com/o/oauth2/auth?client_id={$this->client_id}&redirect_uri={$this->redirect_uri}&scope=email&response_type=code";
            case 'facebook':
                return "https://www.facebook.com/v10.0/dialog/oauth?client_id={$this->client_id}&redirect_uri={$this->redirect_uri}&scope=email&response_type=code";
            case 'github':
                return "https://github.com/login/oauth/authorize?client_id={$this->client_id}&redirect_uri={$this->redirect_uri}&scope=user:email&response_type=code";
            default:
                throw new Exception("Unsupported OAuth provider");
        }
    }

    private function getAccessToken($code) {
        $url = 'https://oauth.provider.com/token';
        $data = [
            'grant_type' => 'authorization_code',
            'client_id' => $this->client_id,
            'client_secret' => $this->client_secret,
            'redirect_uri' => $this->redirect_uri,
            'code' => $code
        ];

        $response = $this->makeRequest($url, $data);

        if (isset($response['access_token'])) {
            return $response['access_token'];
        } else {
            throw new Exception("Failed to retrieve access token");
        }
    }

    private function getUserInfo($access_token) {
        $url = 'https://api.provider.com/userinfo';
        $headers = ['Authorization: Bearer ' . $access_token];

        $response = $this->makeRequest($url, [], $headers);

        return $response;
    }

    private function updateUserDatabase($user_info) {
        // Implement logic to update user database
    }

    private function makeRequest($url, $data = [], $headers = []) {
        $options = [
            'http' => [
                'header'  => implode("\r\n", $headers),
                'method'  => 'POST',
                'content' => http_build_query($data)
            ]
        ];

        if (empty($data)) {
            unset($options['http']['content']);
        }

        $context  = stream_context_create($options);
        $response = file_get_contents($url, false, $context);

        if ($response === FALSE) {
            throw new Exception("Network error");
        }

        return json_decode($response, true);
    }
}

class Cache {
    private $cache_dir;

    public function __construct() {
        $this->cache_dir = sys_get_temp_dir() . '/oauth_cache';
        if (!is_dir($this->cache_dir)) {
            mkdir($this->cache_dir, 0777, true);
        }
    }

    public function get($key) {
        $file_path = $this->getFilePath($key);
        if (file_exists($file_path)) {
            return unserialize(file_get_contents($file_path));
        } else {
            return null;
        }
    }

    public function set($key, $value, $ttl = 3600) {
        $file_path = $this->getFilePath($key);
        file_put_contents($file_path, serialize($value), LOCK_EX);
        touch($file_path, time() + $ttl);
    }

    private function getFilePath($key) {
        return $this->cache_dir . '/' . md5($key);
    }
}

// Usage
$provider = 'google'; // or 'facebook', 'github'
$client_id = 'your_client_id';
$client_secret = 'your_client_secret';
$redirect_uri = 'http://example.com/callback';

$authenticator = new OAuth2Authenticator($provider, $client_id, $client_secret, $redirect_uri);
$authenticator->authenticate();
?>
```

This code block defines a class `OAuth2Authenticator` that handles the entire OAuth 2.0 authentication flow for Google, Facebook, and GitHub providers. The class uses session variables to store access tokens and caches user information for performance optimization. It also includes rate limiting and secure session management mechanisms.

