```python
import os
import time
import logging
from threading import Lock

class DirectoryManager:
    def __init__(self, base_path, log_level=logging.INFO):
        self.base_path = base_path
        self.logger = logging.getLogger('DirectoryManager')
        self.logger.setLevel(log_level)
        self.lock = Lock()
        self.cache = {}

    def create_directory(self, directory_name, parent=None, retries=3):
        with self.lock:
            full_path = os.path.join(parent or self.base_path, directory_name)
            if full_path in self.cache and os.path.exists(full_path):
                return full_path
            for _ in range(retries):
                try:
                    os.makedirs(full_path)
                    self.cache[full_path] = True
                    return full_path
                except FileExistsError:
                    break  # Directory already exists, no need to retry
                except (OSError, PermissionError) as e:
                    self.logger.error(f"Error creating directory {full_path}: {e}")
                    time.sleep(1)
            raise Exception(f"Failed to create directory {full_path} after {retries} attempts")

    def delete_directory(self, directory_name):
        full_path = os.path.join(self.base_path, directory_name)
        if full_path in self.cache:
            del self.cache[full_path]
        try:
            os.rmdir(full_path)
        except OSError as e:
            self.logger.error(f"Error deleting directory {full_path}: {e}")

    def list_directories(self):
        return [d for d in os.listdir(self.base_path) if os.path.isdir(os.path.join(self.base_path, d))]

# Example usage
dm = DirectoryManager('/tmp/mydir', logging.DEBUG)
new_dir = dm.create_directory('worker1')
print(f"Created directory: {new_dir}")
dm.delete_directory('worker1')
