using System;
using System.IO;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public class DataProcessor<T>
{
    private readonly ILogger<DataProcessor<T>> _logger;
    private readonly string _filePath;
    private readonly ISerializationFramework _serializationFramework;

    public DataProcessor(ILogger<DataProcessor<T>> logger, string filePath, ISerializationFramework serializationFramework)
    {
        _logger = logger;
        _filePath = filePath;
        _serializationFramework = serializationFramework;
    }

    public async Task<T> LoadAndDeserializeAsync()
    {
        try
        {
            using (var fileStream = new FileStream(_filePath, FileMode.Open, FileAccess.Read, FileShare.Read, bufferSize: 4096, useAsync: true))
            {
                var data = await _serializationFramework.DeserializeAsync<T>(fileStream);
                return data;
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error loading and deserializing data from file.");
            throw;
        }
    }

    public async Task SaveAndSerializeAsync(T data)
    {
        try
        {
            using (var fileStream = new FileStream(_filePath, FileMode.Create, FileAccess.Write, FileShare.None, bufferSize: 4096, useAsync: true))
            {
                await _serializationFramework.SerializeAsync(data, fileStream);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error saving and serializing data to file.");
            throw;
        }
    }
}

public interface ISerializationFramework
{
    Task<T> DeserializeAsync<T>(Stream stream);
    Task SerializeAsync(object data, Stream stream);
}

// Example implementation of ISerializationFramework using BinaryFormatter
public class BinarySerializationFramework : ISerializationFramework
{
    public async Task<T> DeserializeAsync<T>(Stream stream)
    {
        using (var binaryReader = new BinaryReader(stream))
        {
            return (T)binaryReader.Deserialize(stream);
        }
    }

    public async Task SerializeAsync(object data, Stream stream)
    {
        using (var binaryWriter = new BinaryWriter(stream))
        {
            binaryWriter.Write(data);
        }
    }
}
