const fs = require('fs');
const path = require('path');

class ModuleLoader {
  constructor(packagePath) {
    this.packagePath = packagePath;
    this.moduleCache = {};
  }

  loadModule(moduleName, dependencies = [], isAsync = false) {
    const modulePath = path.join(this.packagePath, moduleName);

    if (this.moduleCache[moduleName]) {
      console.log(`Loading cached module: ${moduleName}`);
      return this.moduleCache[moduleName];
    }

    try {
      let module;
      if (isAsync) {
        module = require(modulePath).default || require(modulePath);
      } else {
        module = require(modulePath);
      }

      dependencies.forEach(dep => {
        const depModule = this.loadModule(dep, [], isAsync);
        Object.assign(module, { [dep]: depModule });
      });

      this.moduleCache[moduleName] = module;
      console.log(`Loaded module: ${moduleName}`);
      return module;
    } catch (error) {
      console.error(`Failed to load module: ${moduleName}`, error);
      throw error;
    }
  }

  executeModule(moduleName, context = {}, isAsync = false) {
    const module = this.loadModule(moduleName, [], isAsync);

    try {
      if (isAsync) {
        return module.default(context) || module(context);
      } else {
        return module(context);
      }
    } catch (error) {
      console.error(`Failed to execute module: ${moduleName}`, error);
      throw error;
    }
  }
}

// Example usage:
const loader = new ModuleLoader('/path/to/your/package');
loader.executeModule('mainModule', { customContext: 'value' });
