#include <stdlib.h>
#include <stdio.h>

typedef struct FSA {
    int** transitions;
    int num_states;
    // Other FSA attributes
} FSA;

typedef struct StateList {
    int* states;
    int length;
    int capacity;
} StateList;

StateList* create_state_list(int* states, int num_states, FSA* fsa, int last_state) {
    if (states == NULL || num_states <= 0 || fsa == NULL || last_state < 0) {
        return NULL; // Invalid input
    }

    StateList* state_list = malloc(sizeof(StateList));
    if (state_list == NULL) {
        return NULL; // Out of memory
    }

    state_list->states = malloc(num_states * sizeof(int));
    if (state_list->states == NULL) {
        free(state_list);
        return NULL; // Out of memory
    }

    state_list->length = 0;
    state_list->capacity = num_states;

    int visited[num_states];
    for (int i = 0; i < num_states; i++) {
        visited[i] = 0;
    }

    void dfs(int state) {
        if (!visited[state]) {
            visited[state] = 1;
            for (int i = 0; i < num_states; i++) {
                int next_state = fsa->transitions[state][i];
                if (next_state != -1 && !visited[next_state]) {
                    dfs(next_state);
                }
            }
            state_list->states[state_list->length++] = state;
        }
    }

    dfs(last_state);

    return state_list;
}

void free_state_list(StateList* state_list) {
    if (state_list != NULL) {
        free(state_list->states);
        free(state_list);
    }
}

// Example usage
int main() {
    // Initialize FSA and other necessary data structures

    int states[] = {0, 1, 2};
    int num_states = sizeof(states) / sizeof(states[0]);
    FSA fsa; // Initialize the FSA structure
    int last_state = 2;

    StateList* result = create_state_list(states, num_states, &fsa, last_state);
    if (result != NULL) {
        printf("State list created successfully with %d states.\n", result->length);
        free_state_list(result);
    } else {
        printf("Failed to create state list.\n");
    }

    return 0;
}
```

