using System;
using System.IO;
using System.Xml;
using System.Xml.Schema;
using System.Xml.XPath;

public class XmlManager
{
    private readonly string _xsdSchemaPath;
    private XmlDocument _cachedXmlDocument;
    private DateTime _cacheExpiryTime;
    private readonly TimeSpan _cacheDuration;
    private readonly ILogger _logger;

    public XmlManager(string xsdSchemaPath, ILogger logger, TimeSpan cacheDuration = default)
    {
        _xsdSchemaPath = xsdSchemaPath;
        _logger = logger;
        _cacheDuration = cacheDuration;
        _cacheExpiryTime = DateTime.MinValue;
    }

    public void ParseAndValidateXml(string xmlData)
    {
        XmlDocument xmlDoc = new XmlDocument();
        XmlReaderSettings settings = new XmlReaderSettings
        {
            Schemas = new XmlSchemaSet(),
            ValidationType = ValidationType.Schema,
            ValidateOnParse = true
        };

        try
        {
            xmlDoc.Schemas.Add(null, _xsdSchemaPath);
            using (XmlReader reader = XmlReader.Create(new StringReader(xmlData), settings))
            {
                xmlDoc.Load(reader);
            }
        }
        catch (XmlSchemaValidationException ex)
        {
            _logger.LogError($"XML validation failed: {ex.Message}");
            throw;
        }

        if (_cacheDuration != default && DateTime.Now >= _cacheExpiryTime)
        {
            _cachedXmlDocument = xmlDoc;
            _cacheExpiryTime = DateTime.Now + _cacheDuration;
        }
    }

    public XmlNode GetElementByName(string xpathExpression)
    {
        if (string.IsNullOrEmpty(xpathExpression))
        {
            throw new ArgumentException("XPath expression cannot be null or empty.", nameof(xpathExpression));
        }

        XmlDocument xmlDoc = GetCurrentXmlDocument();
        XPathNavigator navigator = xmlDoc.CreateNavigator();
        XPathNodeIterator nodes = navigator.Select(xpathExpression);

        if (!nodes.MoveNext())
        {
            _logger.LogError($"No element found for the given XPath: {xpathExpression}");
            throw new InvalidOperationException("No matching element found.");
        }

        if (nodes.MoveNext())
        {
            _logger.LogError($"Multiple elements found for the given XPath: {xpathExpression}");
            throw new InvalidOperationException("Multiple matching elements found.");
        }

        return nodes.Current.Clone();
    }

    private XmlDocument GetCurrentXmlDocument()
    {
        if (_cachedXmlDocument != null && DateTime.Now < _cacheExpiryTime)
        {
            return _cachedXmlDocument;
        }
        else
        {
            // Fetch and parse the XML document from external API here
            // For demonstration purposes, assume it's fetched as a string
            string xmlData = FetchXmlFromApi();
            ParseAndValidateXml(xmlData);
            return _cachedXmlDocument;
        }
    }

    private string FetchXmlFromApi()
    {
        // Implement logic to fetch XML data from an external API
        // Return the XML data as a string
        throw new NotImplementedException();
    }
}

public interface ILogger
{
    void LogError(string message);
}
