package main

import (
    "fmt"
    "os"
    "path/filepath"
    "time"
)

func checkAndLinkConfig() {
    configPath := "/etc/myapp/config"
    defaultConfigPath := "/usr/local/etc/myapp/default.conf"

    if _, err := os.Stat(configPath); os.IsNotExist(err) {
        os.MkdirAll(filepath.Dir(configPath), 0755)
        if err := os.Symlink(defaultConfigPath, configPath); err != nil {
            fmt.Printf("Failed to link configuration: %v\n", err)
        } else {
            fmt.Println("Configuration linked successfully.")
        }
    } else {
        // Add code to validate configuration file integrity here
        fmt.Println("Configuration already exists.")
    }
}

func main() {
    checkAndLinkConfig()
}
