import requests
from concurrent.futures import ThreadPoolExecutor
from functools import lru_cache, wraps
from time import sleep, time
from datetime import timedelta

# Configuration settings
API_KEY = 'your_openweathermap_api_key'
CACHING_DURATION = 3600  # Cache for 1 hour
RATE_LIMIT_INTERVAL = 5  # Rate limit every 5 seconds
MAX_CONCURRENT_REQUESTS = 10

def fetch_weather_data(city, timezone=None):
    """Fetch weather data for a given city using the OpenWeatherMap API."""
    if not city:
        raise ValueError("City cannot be None")

    url = f"http://api.openweathermap.org/data/2.5/weather?q={city}&appid={API_KEY}"
    if timezone:
        url += f"&timezone={timezone}"

    response = requests.get(url)
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception(f"Failed to fetch weather data for {city}: {response.text}")

@lru_cache(maxsize=1000)
def cached_weather_data(city, timezone=None):
    """Cache weather data using lru_cache decorator."""
    return fetch_weather_data(city, timezone)

def rate_limited(func):
    """Rate limit the function calls to prevent overloading the API."""
    last_call_time = 0

    @wraps(func)
    def wrapper(*args, **kwargs):
        nonlocal last_call_time
        current_time = time()
        if current_time - last_call_time < RATE_LIMIT_INTERVAL:
            sleep(RATE_LIMIT_INTERVAL - (current_time - last_call_time))
        last_call_time = time()
        return func(*args, **kwargs)

    return wrapper

@rate_limited
def fetch_weather_data_with_retry(city, timezone=None):
    """Fetch weather data with exponential backoff for retries."""
    max_retries = 5
    delay = 1

    for attempt in range(max_retries + 1):
        try:
            return cached_weather_data(city, timezone)
        except Exception as e:
            if attempt == max_retries:
                raise
            sleep(delay)
            delay *= 2

def fetch_multiple_cities(cities, timezone=None):
    """Fetch weather data for multiple cities concurrently."""
    with ThreadPoolExecutor(max_workers=MAX_CONCURRENT_REQUESTS) as executor:
        future_to_city = {executor.submit(fetch_weather_data_with_retry, city, timezone): city for city in cities}
        results = {}
        for future in concurrent.futures.as_completed(future_to_city):
            city = future_to_city[future]
            try:
                data = future.result()
                results[city] = data
            except Exception as exc:
                print(f"Failed to fetch weather data for {city}: {exc}")
        return results

# Example usage
cities = ['New York', 'London', 'Tokyo']
weather_data = fetch_multiple_cities(cities)
print(weather_data)
