const fs = require('fs');
const path = require('path');
const { Worker, isMainThread, parentPort } = require('worker_threads');
const jest = require('jest');

async function loadModules(directory) {
  const modules = [];
  const files = fs.readdirSync(directory);

  for (const file of files) {
    try {
      const modulePath = path.join(directory, file);
      const module = await import(modulePath);
      modules.push(module.default);
    } catch (error) {
      console.error(`Failed to load module ${file}:`, error);
    }
  }

  return modules;
}

async function runTests(testSuites) {
  for (const testSuite of testSuites) {
    try {
      const { default: suite, ...config } = testSuite;
      await jest.runInNodeEnvironment(config, async () => {
        await suite();
      });
    } catch (error) {
      console.error(`Test suite failed:`, error);
    }
  }
}

async function main() {
  const config = {
    moduleDirectory: './modules',
    testSuites: [
      { default: require('./tests/testSuite1'), timeout: 5000 },
      { default: require('./tests/testSuite2'), retries: 3 },
    ],
    concurrency: 5,
    logLevel: 'info',
    performanceOptimization: true,
  };

  const modules = await loadModules(config.moduleDirectory);
  const testSuites = [];

  for (const module of modules) {
    if (module.tests && Array.isArray(module.tests)) {
      testSuites.push(...module.tests.map(test => ({ ...test, config })));
    }
  }

  for (let i = 0; i < config.concurrency; i++) {
    const worker = new Worker(__filename, { workerData: testSuites.slice(i * Math.ceil(testSuites.length / config.concurrency), (i + 1) * Math.ceil(testSuites.length / config.concurrency)) });
    worker.on('message', message => console.log(message));
    worker.on('error', error => console.error(`Worker error:`, error));
    worker.on('exit', code => {
      if (code !== 0) {
        console.error(`Worker stopped with exit code ${code}`);
      }
    });
  }
}

if (isMainThread) {
  main();
} else {
  const testSuites = workerData;
  runTests(testSuites).then(() => parentPort.postMessage('Test suite completed'));
}
