const { MongoClient } = require('mongodb');
const fs = require('fs');
const path = require('path');

class DroneManager {
  constructor(config) {
    this.config = config;
    this.clients = {};
    this.protocolCache = new Map();
    this.missionQueue = [];
    this.isPaused = false;
    this.mongoClient = new MongoClient(config.databaseUrl, { useNewUrlParser: true, useUnifiedTopology: true });
    this.logService = require('log-service-client');
  }

  async loadDroneConfigurations(filePath) {
    const data = await fs.promises.readFile(filePath, 'utf8');
    const configData = JSON.parse(data);
    for (const droneConfig of configData.drones) {
      this.clients[droneConfig.name] = new droneConfig.implementationClass(droneConfig.config);
    }
  }

  async connectToDatabase() {
    await this.mongoClient.connect();
    console.log('Connected to MongoDB database');
  }

  async saveData(data) {
    const collection = this.mongoClient.db().collection(this.config.databaseCollection);
    try {
      await collection.insertMany(data);
      console.log('Data saved successfully');
    } catch (error) {
      console.error('Error saving data:', error);
    }
  }

  async loadProtocolImplementation(protocolName) {
    if (!this.protocolCache.has(protocolName)) {
      const protocolPath = path.join(__dirname, 'protocols', `${protocolName}.js`);
      const protocolModule = require(protocolPath);
      this.protocolCache.set(protocolName, protocolModule);
    }
    return this.protocolCache.get(protocolName);
  }

  async collectData() {
    for (const droneName in this.clients) {
      if (!this.isPaused) {
        const data = await this.clients[droneName].collect();
        this.missionQueue.push({ droneName, data });
      }
    }
    while (!this.isPaused && this.missionQueue.length > 0) {
      const mission = this.missionQueue.shift();
      await this.saveData(mission.data);
      await this.logService.logEvent(`Drone ${mission.droneName} data saved`);
    }
  }

  pauseMission() {
    this.isPaused = true;
    console.log('Mission paused');
  }

  resumeMission() {
    this.isPaused = false;
    this.collectData();
    console.log('Mission resumed');
  }

  async handleErrors(error) {
    if (error instanceof MongoError) {
      // Handle MongoDB connection errors
    } else if (error instanceof NetworkError) {
      // Handle network disruptions
    }
    await this.logService.logEvent(`Error: ${error.message}`);
  }

  async start() {
    await this.loadDroneConfigurations(this.config.droneConfigFilePath);
    await this.connectToDatabase();
    setInterval(() => this.collectData(), this.config.collectionInterval);
  }
}

module.exports = DroneManager;
