        // Asynchronously load file content
        std::thread([file_path, &result]() {
            try {
                std::ifstream file(file_path);
                if (file.is_open()) {
                    std::string content((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
                    result.set_value(content);
                } else {
                    result.set_exception(std::make_exception_ptr(std::runtime_error("File not found")));
