```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;

namespace DatabaseManagement
{
    public class DatabaseConnectionManager
    {
        private string _connectionStringTemplate;
        private Dictionary<string, string> _tenantConnectionStringMapping;
        private List<SqlConnection> _connectionPool;

        public DatabaseConnectionManager(string connectionStringTemplate, Dictionary<string, string> tenantConnectionStringMapping)
        {
            _connectionStringTemplate = connectionStringTemplate;
            _tenantConnectionStringMapping = tenantConnectionStringMapping;
            _connectionPool = new List<SqlConnection>();
        }

        public async Task<SqlConnection> EstablishConnectionAsync(string tenantIdentifier)
        {
            if (!_tenantConnectionStringMapping.ContainsKey(tenantIdentifier))
            {
                throw new ArgumentException("Tenant identifier not found.");
            }

            string connectionString = GetTenantConnectionString(tenantIdentifier);

            if (_connectionPool.Count > 0)
            {
                SqlConnection connection = _connectionPool[0];
                _connectionPool.RemoveAt(0);
                return await ReopenConnectionAsync(connection, connectionString);
            }

            return new SqlConnection(connectionString);
        }

        public async Task<DataTable> ExecuteQueryAsync(string tenantIdentifier, string query)
        {
            using (SqlConnection connection = await EstablishConnectionAsync(tenantIdentifier))
            {
                SqlCommand command = new SqlCommand(query, connection);
                SqlDataAdapter adapter = new SqlDataAdapter(command);
                DataTable dataTable = new DataTable();
                await adapter.FillAsync(dataTable);
                return dataTable;
            }
        }

        public async Task<SqlTransaction> BeginTransactionAsync(string tenantIdentifier)
        {
            using (SqlConnection connection = await EstablishConnectionAsync(tenantIdentifier))
            {
                SqlTransaction transaction = await connection.BeginTransactionAsync();
                return transaction;
            }
        }

        public async Task CommitTransactionAsync(SqlTransaction transaction)
        {
            if (transaction != null && !transaction.Connection.State.Equals(ConnectionState.Closed))
            {
                await transaction.CommitAsync();
                CloseConnection(transaction.Connection);
            }
        }

        public async Task RollbackTransactionAsync(SqlTransaction transaction)
        {
            if (transaction != null && !transaction.Connection.State.Equals(ConnectionState.Closed))
            {
                await transaction.RollbackAsync();
                CloseConnection(transaction.Connection);
            }
        }

        private string GetTenantConnectionString(string tenantIdentifier)
        {
            return _tenantConnectionStringMapping[tenantIdentifier];
        }

        private async Task<SqlConnection> ReopenConnectionAsync(SqlConnection connection, string connectionString)
        {
            if (connection != null && !string.IsNullOrEmpty(connectionString))
            {
                try
                {
                    await connection.OpenAsync();
                }
                catch (SqlException ex)
                {
                    // Log error and throw exception
                    throw new InvalidOperationException("Failed to reopen database connection.", ex);
                }
            }

            return connection;
        }

        private void CloseConnection(SqlConnection connection)
        {
            if (connection != null && connection.State == ConnectionState.Open)
            {
                try
                {
                    connection.Close();
                    _connectionPool.Add(connection);
                }
                catch (SqlException ex)
                {
                    // Log error and handle exception
                    Console.WriteLine("Error closing database connection: " + ex.Message);
                }
            }
        }

        public override string ToString()
        {
            return $"Active Connection: {(_connectionPool.Count > 0 ? _connectionPool[0].ConnectionString : "None")}";
        }
    }
}
