import json
import asyncio
from hashlib import sha256

class JSONManager:
    factories = {}

    @classmethod
    def add_factory(cls, class_id, factory):
        cls.factories[class_id] = factory

    @classmethod
    def create_instance(cls, class_id, data):
        if class_id in cls.factories:
            return cls.factories[class_id](data)
        else:
            raise ValueError(f"No factory registered for class ID: {class_id}")

class JSONObject:
    def __init__(self, **kwargs):
        self.__dict__.update(kwargs)

    @classmethod
    def from_json(cls, json_str):
        data = json.loads(json_str)
        return cls(**data)

    def to_json(self):
        return json.dumps(self.__dict__)

async def load_files(file_paths):
    tasks = []
    for file_path in file_paths:
        task = asyncio.create_task(load_file_async(file_path))
        tasks.append(task)
    results = await asyncio.gather(*tasks)
    return [r for r in results if r is not None]

async def load_file_async(file_path):
    try:
        with open(file_path, 'r') as file:
            data = await asyncio.to_thread(json.load, file)
            handle_data(data)
            return True
    except Exception as e:
        print(f"Error loading {file_path}: {e}")
        return None

def handle_data(data):
    if isinstance(data, dict) and "class_id" in data:
        class_id = data["class_id"]
        factory_function = get_factory_from_json(data)
        JSONManager.add_factory(class_id, factory_function)

def get_factory_from_json(json_data):
    # This function should create a subclass of JSONObject based on the provided json_data
    # For simplicity, assume it returns a class with attributes from json_data
    class DynamicClass(JSONObject):
        def __init__(self, **kwargs):
            super().__init__(**kwargs)

    return lambda data: DynamicClass(**data)

def deserialize_and_hash(password, byte_array):
    # Implement deserialization and hashing logic here
    random_string = generate_random_string()
    hashed_password = hash_password(password)
    return random_string, hashed_password

def generate_random_string():
    # Generate a random string (e.g., UUID or similar)
    import uuid
    return str(uuid.uuid4())

def hash_password(password):
    # Hash the password using SHA-256
    return sha256(password.encode()).hexdigest()

# Example usage
async def main():
    file_paths = ['path_to_json_file1.json', 'path_to_json_file2.json']
    await load_files(file_paths)

    data = {"class_id": "example_class", "key": "value"}
    instance = JSONManager.create_instance("example_class", data)
    print(instance.to_json())

    random_string, hashed_password = deserialize_and_hash("my_password", b"some_byte_array")
    print(random_string, hashed_password)

asyncio.run(main())
