import asyncio
import json
import logging
from collections import defaultdict, deque

# Set up logging configuration
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class JSONParser:
    _registry = {}

    @classmethod
    def register_factory(cls, id, factory):
        cls._registry[id] = factory

    @classmethod
    def create_instance(cls, data):
        if 'id' not in data or data['id'] not in cls._registry:
            raise ValueError("Invalid JSON data for instance creation")
        return cls._registry[data['id']]().from_json(data)

    def to_json(self):
        return json.dumps(self.__dict__)

    @classmethod
    def from_json(cls, data):
        return cls(**data)

class BaseSubClass(JSONParser):
    pass

class SubClass1(BaseSubClass):
    pass

class SubClass2(BaseSubClass):
    pass

# Register factory functions for subclasses
JSONParser.register_factory('subclass1', SubClass1)
JSONParser.register_factory('subclass2', SubClass2)

async def load_file(file_path, file_stream):
    try:
        data = await asyncio.to_thread(json.load, file_stream)
        instance = JSONParser.create_instance(data)
        logger.info(f"Loaded instance: {instance}")
        return instance
    except Exception as e:
        logger.error(f"Failed to load file {file_path}: {e}")
        raise

async def process_files(file_paths):
    async with asyncio.Semaphore(10):  # Limit number of concurrent file loads
        tasks = [load_file(path, open(path, 'r')) for path in file_paths]
        instances = await asyncio.gather(*tasks)
        return instances

# Example usage
if __name__ == "__main__":
    file_paths = ['file1.json', 'file2.json']
    loop = asyncio.get_event_loop()
    try:
        instances = loop.run_until_complete(process_files(file_paths))
        print(instances)
    except Exception as e:
        logger.error(f"Error processing files: {e}")
