#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define MAX_RESOURCE_TYPES 10
#define MAX_THREADS 100

typedef struct {
    sem_t *sem;
    int max_permits;
    int current_permits;
} SemaphoreManager;

SemaphoreManager resource_pools[MAX_RESOURCE_TYPES];
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;
int num_resource_types = 0;

void initialize_semaphore_pool(const char *resource_type, int max_permits) {
    pthread_mutex_lock(&pool_lock);
    if (num_resource_types >= MAX_RESOURCE_TYPES) {
        fprintf(stderr, "Too many resource types\n");
        return;
    }
    SemaphoreManager *manager = &resource_pools[num_resource_types++];
    manager->sem = malloc(sizeof(sem_t));
    sem_init(manager->sem, 0, max_permits);
    manager->max_permits = max_permits;
    manager->current_permits = max_permits;
    pthread_mutex_unlock(&pool_lock);
}

void acquire_semaphore(const char *resource_type) {
    int index = -1;
    for (int i = 0; i < num_resource_types; i++) {
        if (!strcmp(resource_pools[i].semaphore_name, resource_type)) {
            index = i;
            break;
        }
    }
    if (index == -1) {
        fprintf(stderr, "Resource type not found\n");
        return;
    }
    sem_wait(&resource_pools[index].sem);
}

void release_semaphore(const char *resource_type) {
    int index = -1;
    for (int i = 0; i < num_resource_types; i++) {
        if (!strcmp(resource_pools[i].semaphore_name, resource_type)) {
            index = i;
            break;
        }
    }
    if (index == -1) {
        fprintf(stderr, "Resource type not found\n");
        return;
    }
    sem_post(&resource_pools[index].sem);
}

void *worker_thread(void *arg) {
    char *resource_type = arg;
    while (1) {
        acquire_semaphore(resource_type);
        // Simulate work
        printf("Working with resource: %s\n", resource_type);
        sleep(1);
        release_semaphore(resource_type);
        sleep(1); // Delay between requests
    }
}

int main() {
    initialize_semaphore_pool("database_connection", 50);
    initialize_semaphore_pool("api_call", 100);

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; i++) {
        if (pthread_create(&threads[i], NULL, worker_thread, "database_connection") != 0) {
            fprintf(stderr, "Failed to create thread\n");
            return 1;
        }
        if (pthread_create(&threads[i + MAX_THREADS / 2], NULL, worker_thread, "api_call") != 0) {
            fprintf(stderr, "Failed to create thread\n");
            return 1;
        }
    }

    for (int i = 0; i < MAX_THREADS * 2; i++) {
        pthread_join(threads[i], NULL);
    }

    for (int i = 0; i < num_resource_types; i++) {
        sem_destroy(resource_pools[i].sem);
        free(resource_pools[i].sem);
    }
    return 0;
}
```

This code provides a basic implementation of a semaphore manager in C. It includes functions to initialize semaphore pools, acquire and release semaphores, and simulate worker threads using these semaphores. The actual cloud service interaction and advanced features like dynamic load balancing, smart throttling, caching, logging, failover strategies, and threat modeling are not included in this code but would be necessary for a fully functional solution.

