    @PutMapping("/upgrade")
    public void upgradeAccount(@RequestParam String tenantId,
                                @RequestParam String userId,
                                @RequestParam String subscriptionTier,
                                @RequestParam String expirationDate) {

        // Validate inputs
        if (tenantId == null || userId == null || subscriptionTier == null || expirationDate == null) {
            throw new IllegalArgumentException("Invalid input parameters");
        }

        try {
            // Update user account plan in the database
            accountService.updateUserPlan(tenantId, userId, subscriptionTier, expirationDate);

            // Notify other services through service mesh
            notificationService.notifyUpgrade(tenantId, userId, subscriptionTier, expirationDate);
