template <typename T>
class FactoryRegistry {
private:
    static std::map<int, T*> factories;
    static std::mutex mutex;

public:
    static void registerFactory(int id, T* factory) {
        std::lock_guard<std::mutex> lock(mutex);
        factories[id] = factory;
    }

    static T* createInstance(int id) {
        std::lock_guard<std::mutex> lock(mutex);
        if (factories.find(id) != factories.end()) {
            return factories[id]->clone();
        }
        return nullptr;
    }
};

template <typename T>
std::map<int, T*> FactoryRegistry<T>::factories;

template <typename T>
std::mutex FactoryRegistry<T>::mutex;

class ConfigLoader {
private:
    static std::map<std::string, nlohmann::json> cache;
    static std::mutex mutex;

public:
    static nlohmann::json loadConfig(const std::string& url) {
        std::lock_guard<std::mutex> lock(mutex);
        if (cache.find(url) != cache.end()) {
            return cache[url];
        }

        CURL* curl = curl_easy_init();
        if(curl) {
            struct MemoryStruct chunk;
            chunk.memory = NULL;
            chunk.size = 0;

            curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
            curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void*)&chunk);

            CURLcode res = curl_easy_perform(curl);
            if(res != CURLE_OK) {
                std::cerr << "curl_easy_perform() failed: " << curl_easy_strerror(res) << std::endl;
            } else {
                cache[url] = JsonParser::fromJson(chunk.memory);
            }

            free(chunk.memory);
            curl_easy_cleanup(curl);
        }
        return cache[url];
    }

private:
    static size_t WriteMemoryCallback(void* contents, size_t size, size_t nmemb, void* userp) {
        size_t realsize = size * nmemb;
        struct MemoryStruct *mem = (struct MemoryStruct *)userp;

        char *ptr = (char*)realloc(mem->memory, mem->size + realsize + 1);
        if(ptr == NULL) {
            return 0;    /* out of memory! */
        }

        mem->memory = ptr;
        memcpy(&(mem->memory[mem->size]), contents, realsize);
        mem->size += realsize;
        mem->memory[mem->size] = 0;

        return realsize;
    }
};

std::map<std::string, nlohmann::json> ConfigLoader::cache;

class AesDecryption {
public:
    static std::vector<unsigned char> decrypt(const std::vector<unsigned char>& ciphertext, const unsigned char* key, const unsigned char* iv) {
        std::vector<unsigned char> plaintext(ciphertext.size());
        AES_KEY aesKey;
        AES_set_decrypt_key(key, 256, &aesKey);
        AES_cbc_encrypt(ciphertext.data(), plaintext.data(), ciphertext.size(), &aesKey, iv, AES_DECRYPT);
        return plaintext;
    }
};

int main() {
