#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>

#define MAX_FILE_PATH 1024

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int file_exists(const char *path) {
    struct stat buffer;
    return (stat(path, &buffer) == 0);
}

int convert_jpeg_to_pdf(const char *config_file, const char **input_files, int num_files) {
    if (!file_exists(config_file)) {
        log_error("Configuration file does not exist.");
        return -1;
    }

    for (int i = 0; i < num_files; ++i) {
        if (!file_exists(input_files[i])) {
            log_error("Input file does not exist: ");
            log_error(input_files[i]);
            return -1;
        }
    }

    char command[MAX_FILE_PATH];
    snprintf(command, MAX_FILE_PATH, "jpeg2pdf --config %s", config_file);

    for (int i = 0; i < num_files; ++i) {
        strncat(command, " ", MAX_FILE_PATH);
        strncat(command, input_files[i], MAX_FILE_PATH - strlen(command));
    }

    int result = system(command);
    if (result != 0) {
        log_error("Failed to convert JPEG to PDF.");
        return -1;
    }

    return 0;
}

int main() {
    const char *config_file = "path/to/config.txt";
    const char *input_files[] = {"image1.jpg", "image2.jpg", "image3.jpg"};
    int num_files = sizeof(input_files) / sizeof(input_files[0]);

    if (convert_jpeg_to_pdf(config_file, input_files, num_files) == 0) {
        printf("Conversion successful.\n");
    } else {
        printf("Conversion failed.\n");
    }

    return 0;
}
