        return isset($this->sessionData[$key]) ? $this->sessionData[$key] : null;
    }

    public function remove($key) {
        unset($this->sessionData[$key]);
    }
}

class CacheManager {
    private $cacheData = [];

    public function set($key, $value, $ttl) {
        $this->cacheData[$key] = [
            'value' => $value,
            'expiry' => time() + $ttl
        ];
    }

    public function get($key) {
        if (isset($this->cacheData[$key]) && time() < $this->cacheData[$key]['expiry']) {
            return $this->cacheData[$key]['value'];
        }
        return null;
    }

    public function exists($key) {
        return isset($this->cacheData[$key]);
    }
}
