using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Distributed;
using Microsoft.Extensions.Logging;

public class UserProfileFetcher
{
    private readonly HttpClient _httpClient;
    private readonly IDistributedCache _cache;
    private readonly ILogger<UserProfileFetcher> _logger;
    private readonly string _apiEndpoint;
    private readonly string _apiKey;

    public UserProfileFetcher(HttpClient httpClient, IDistributedCache cache, ILogger<UserProfileFetcher> logger, string apiEndpoint, string apiKey)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _apiEndpoint = apiEndpoint ?? throw new ArgumentNullException(nameof(apiEndpoint));
        _apiKey = apiKey ?? throw new ArgumentNullException(nameof(apiKey));
    }

    public async Task<List<UserProfile>> FetchUserProfilesAsync(List<string> userIds, TimeSpan? cacheExpiry = null)
    {
        var userProfiles = new List<UserProfile>();

        foreach (var userId in userIds)
        {
            try
            {
                if (!IsValidUserId(userId))
                {
                    _logger.LogWarning("Invalid user ID: {UserId}", userId);
                    continue;
                }

                var cachedProfile = await GetCachedUserProfileAsync(userId, cacheExpiry);
                if (cachedProfile != null)
                {
                    userProfiles.Add(cachedProfile);
                    continue;
                }

                var profile = await FetchUserProfileFromApiAsync(userId);
                if (profile == null)
                {
                    _logger.LogError("Failed to fetch profile for user ID: {UserId}", userId);
                    continue;
                }

                await CacheUserProfileAsync(userId, profile, cacheExpiry);
                userProfiles.Add(profile);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing user ID: {UserId}", userId);
            }
        }

        return userProfiles;
    }

    private async Task<UserProfile> FetchUserProfileFromApiAsync(string userId)
    {
        var url = $"{_apiEndpoint}/{userId}?key={_apiKey}";
        for (int attempt = 0; attempt < 4; attempt++)
        {
            try
            {
                _logger.LogInformation("Fetching user profile from API for user ID: {UserId}, Attempt: {Attempt}", userId, attempt);
                var response = await _httpClient.GetAsync(url, HttpCompletionOption.ResponseHeadersRead);
                response.EnsureSuccessStatusCode();
                return await response.Content.ReadAsAsync<UserProfile>();
            }
            catch (HttpRequestException ex)
            {
                _logger.LogWarning(ex, "Failed to fetch user profile from API for user ID: {UserId}, Attempt: {Attempt}", userId, attempt);
                if (attempt == 3) throw;
                await Task.Delay(TimeSpan.FromSeconds(Math.Pow(2, attempt))); // Exponential backoff
            }
        }

        return null;
    }

    private async Task<UserProfile> GetCachedUserProfileAsync(string userId, TimeSpan? cacheExpiry)
    {
        var cachedKey = $"user_profile:{userId}";
        var cachedData = await _cache.GetStringAsync(cachedKey);
        if (cachedData != null)
        {
            _logger.LogInformation("Fetching user profile from cache for user ID: {UserId}", userId);
            return JsonConvert.DeserializeObject<UserProfile>(cachedData);
        }

        return null;
    }

    private async Task CacheUserProfileAsync(string userId, UserProfile profile, TimeSpan? cacheExpiry = null)
    {
        var cachedKey = $"user_profile:{userId}";
        var options = new DistributedCacheEntryOptions
        {
            AbsoluteExpirationRelativeToNow = cacheExpiry ?? TimeSpan.FromMinutes(10)
        };

        await _cache.SetStringAsync(cachedKey, JsonConvert.SerializeObject(profile), options);
        _logger.LogInformation("Caching user profile for user ID: {UserId}", userId);
    }

    private bool IsValidUserId(string userId)
    {
        // Implement your validation logic here
        return !string.IsNullOrEmpty(userId) && userId.Length == 24; // Example validation
    }
}
