using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Distributed;
using StackExchange.Redis;

public class HtmlContentService
{
    private readonly HttpClient _httpClient;
    private readonly IDistributedCache _cache;
    private readonly ConnectionMultiplexer _redisConnection;

    public HtmlContentService(HttpClient httpClient, IDistributedCache cache, ConnectionMultiplexer redisConnection)
    {
        _httpClient = httpClient;
        _cache = cache;
        _redisConnection = redisConnection;
    }

    [HttpPost("api/htmlcontent/update")]
    public async Task<IActionResult> UpdateHtmlContent([FromQuery] string pageSectionId, [FromQuery] string elementId, [FromBody] string htmlContent)
    {
        try
        {
            // Validate input
            if (string.IsNullOrEmpty(pageSectionId) || string.IsNullOrEmpty(elementId) || string.IsNullOrEmpty(htmlContent))
                return BadRequest("Invalid input");

            // Check rate limiting
            if (!await IsRateLimitExceeded())
                return StatusCode(429, "Too many requests");

            // Fine-grained locking using distributed cache
            var lockKey = $"lock:{pageSectionId}:{elementId}";
            if (await _cache.GetStringAsync(lockKey) != null)
                return StatusCode(503, "Service unavailable");

            await _cache.SetStringAsync(lockKey, "locked", new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromSeconds(10) });

            try
            {
                // Fetch current HTML content from storage
                var currentHtmlContent = await GetHtmlContentFromStorage(pageSectionId, elementId);

                if (string.IsNullOrEmpty(currentHtmlContent))
                    return NotFound("HTML content not found");

                // Update specific element with new HTML content
                var updatedHtmlContent = ReplaceElementInHtml(currentHtmlContent, elementId, htmlContent);

                // Save updated HTML content to storage
                await SaveHtmlContentToStorage(pageSectionId, elementId, updatedHtmlContent);

                return Ok("HTML content updated successfully");
            }
            finally
            {
                // Release lock
                await _cache.RemoveAsync(lockKey);
            }
        }
        catch (Exception ex)
        {
            LogError(ex);
            return StatusCode(500, "Internal server error");
        }
    }

    private async Task<string> GetHtmlContentFromStorage(string pageSectionId, string elementId)
    {
        try
        {
            var cacheKey = $"html:{pageSectionId}:{elementId}";
            var cachedHtmlContent = await _cache.GetStringAsync(cacheKey);

            if (!string.IsNullOrEmpty(cachedHtmlContent))
                return cachedHtmlContent;

            var response = await _httpClient.GetAsync($"https://storage.googleapis.com/{pageSectionId}/{elementId}.html");
            if (response.IsSuccessStatusCode)
            {
                cachedHtmlContent = await response.Content.ReadAsStringAsync();
                await _cache.SetStringAsync(cacheKey, cachedHtmlContent, new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10) });
            }

            return cachedHtmlContent;
        }
        catch (Exception ex)
        {
            LogError(ex);
            throw;
        }
    }

    private string ReplaceElementInHtml(string htmlContent, string elementId, string newHtmlContent)
    {
        // Use a HTML parsing library to replace specific element with new content
        // Example: HtmlAgilityPack or AngleSharp
        return htmlContent.Replace($"<div id=\"{elementId}\">", $"<div id=\"{elementId}\">{newHtmlContent}");
    }

    private async Task SaveHtmlContentToStorage(string pageSectionId, string elementId, string htmlContent)
    {
        try
        {
            var response = await _httpClient.PutAsync($"https://storage.googleapis.com/{pageSectionId}/{elementId}.html", new StringContent(htmlContent));
            if (!response.IsSuccessStatusCode)
                throw new Exception("Failed to save HTML content to storage");
        }
        catch (Exception ex)
        {
            LogError(ex);
            throw;
        }
    }

    private async Task<bool> IsRateLimitExceeded()
    {
        try
        {
            var cacheKey = "rate-limit";
            var currentCount = await _cache.GetStringAsync(cacheKey);

            if (string.IsNullOrEmpty(currentCount))
                await _cache.SetStringAsync(cacheKey, "1", new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromSeconds(60) });
            else
            {
                int count = Convert.ToInt32(currentCount);
                if (count >= 10)
                    return true;

                await _cache.SetStringAsync(cacheKey, count.ToString(), new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromSeconds(60) });
            }

            return false;
        }
        catch (Exception ex)
        {
            LogError(ex);
            throw;
        }
    }

    private void LogError(Exception ex)
    {
        // Log error details using a logging framework like NLog or Serilog
    }
}
