    factories = {}

    @classmethod
    def register_factory(cls, id, factory):
        cls.factories[id] = factory

    @classmethod
    def create_instance(cls, id, data):
        if id in cls.factories:
            return cls.factories[id](data)
        raise ValueError("Factory not registered")

    @staticmethod
    def to_json_string(data):
        return json.dumps(data)

