class ForwardList:
    def __init__(self, initial_elements=None):
        self.elements = initial_elements if initial_elements else []

    def insert(self, search_term, insert_term, position_index=0):
        try:
            index = self.elements.index(search_term, position_index)
            self.elements.insert(index + 1, insert_term)
        except ValueError:
            if position_index < len(self.elements):
                self.elements.insert(position_index, insert_term)
            else:
                raise IndexError("Position index out of bounds")

    def extend_insertions(self, search_terms, insert_terms, positions):
        for search_term, insert_term, position in zip(search_terms, insert_terms, positions):
            self.insert(search_term, insert_term, position)

