#include <stdio.h>
#include <stdlib.h>

#define MAX_MEMORY_USAGE (50 * 1024 * 1024) // 50MB in bytes

int readInt() {
    int num;
    if (scanf("%d", &num) != 1) {
        printf("Invalid input. Please enter a valid integer.\n");
        exit(1);
    }
    return num;
}

void findAndPrintMax(int *arr, size_t size) {
    if (size == 0) {
        printf("The list is empty.\n");
        return;
    }

    int max = arr[0];
    for (size_t i = 1; i < size; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    printf("The largest integer in the list is: %d\n", max);
}

int main() {
    int *arr = NULL;
    size_t capacity = 0;
    size_t size = 0;

    while (1) {
        if (size >= capacity) {
            capacity += 10000; // Increase capacity by 10,000 each time
            arr = realloc(arr, capacity * sizeof(int));
            if (arr == NULL) {
                printf("Memory allocation failed.\n");
                free(arr);
                return 1;
            }
        }

        int num = readInt();
        if (num == -1) { // Assuming -1 is a sentinel value to stop input
            break;
        }

        arr[size++] = num;

        // Check memory usage
        if ((size_t)(arr - capacity * sizeof(int)) > MAX_MEMORY_USAGE) {
            printf("Memory limit exceeded. Truncating list.\n");
            size -= (size - capacity); // Truncate to the last allocated size
            break;
        }
    }

    findAndPrintMax(arr, size);
    free(arr);

    return 0;
}
