using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

public class SqlQueryExecutor
{
    private readonly string _connectionString;
    private readonly string _commandTemplate;
    private readonly Dictionary<string, object> _parameters;
    private readonly IExternalAuthenticationService _authService;
    private readonly ICachingMechanism _cache;

    public SqlQueryExecutor(string connectionString, string commandTemplate, Dictionary<string, object> parameters, IExternalAuthenticationService authService, ICachingMechanism cache)
    {
        _connectionString = connectionString;
        _commandTemplate = commandTemplate;
        _parameters = parameters;
        _authService = authService;
        _cache = cache;
    }

    public async Task<DataSet> ExecuteAsync()
    {
        if (!_authService.IsUserAuthorized(_parameters["user"].ToString()))
        {
            throw new UnauthorizedAccessException("User is not authorized to execute this query.");
        }

        string cachedQuery = _cache.Get(_commandTemplate);
        if (cachedQuery != null)
        {
            return await ExecuteCachedQueryAsync(cachedQuery);
        }

        string query = ReplaceParameters(_commandTemplate, _parameters);
        _cache.Set(query);

        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();
            using (var command = new SqlCommand(query, connection))
            {
                foreach (var param in _parameters)
                {
                    command.Parameters.AddWithValue(param.Key, param.Value);
                }

                using (var adapter = new SqlDataAdapter(command))
                {
                    var dataSet = new DataSet();
                    await adapter.FillAsync(dataSet);
                    return dataSet;
                }
            }
        }
    }

    private string ReplaceParameters(string queryTemplate, Dictionary<string, object> parameters)
    {
        foreach (var param in parameters)
        {
            queryTemplate = queryTemplate.Replace("{" + param.Key + "}", Convert.ToString(param.Value));
        }
        return queryTemplate;
    }

    private async Task<DataSet> ExecuteCachedQueryAsync(string cachedQuery)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();
            using (var command = new SqlCommand(cachedQuery, connection))
            {
                using (var adapter = new SqlDataAdapter(command))
                {
                    var dataSet = new DataSet();
                    await adapter.FillAsync(dataSet);
                    return dataSet;
                }
            }
        }
    }
}

public interface IExternalAuthenticationService
{
    bool IsUserAuthorized(string userId);
}

public interface ICachingMechanism
{
    string Get(string key);
    void Set(string key, int duration = 3600); // Default cache duration is 1 hour
}
