import java.io.FileInputStream;
import java.io.IOException;
import java.net.SocketException;
import java.nio.ByteBuffer;
import java.nio.channels.AsynchronousServerSocketChannel;
import java.nio.channels.AsynchronousSocketChannel;
import java.nio.channels.CompletionHandler;
import java.security.KeyStore;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class NioConnectionPool {
    private final AsynchronousServerSocketChannel _serverChannel;
    private final ExecutorService _executorService;
    private int _activeConnections = 0;
    private int _idleConnections = 100; // Default pool size

    public NioConnectionPool(String address, int port) throws IOException {
        KeyStore keyStore = loadKeyStore("path/to/keystore.jks", "password");
        SSLContext sslContext = SSLContext.getInstance("TLSv1.2");
        sslContext.init(null, new javax.net.ssl.TrustManager[]{new X509TrustManager() {
            public java.security.cert.X509Certificate[] getAcceptedIssuers() { return null; }
            public void checkClientTrusted(X509Certificate[] certs, String authType) {}
            public void checkServerTrusted(X509Certificate[] certs, String authType) {}
        }}, new SecureRandom());

        SSLParameters sslParams = new SSLParameters();
        sslParams.setNeedClientAuth(true);
        sslParams.setCipherSuites(sslContext.getDefaultSSLParameters().getCipherSuites());
        sslParams.setProtocols(new String[]{"TLSv1.2"});

        _serverChannel = AsynchronousServerSocketChannel.open(sslContext.getServerSocketFactory());
        _serverChannel.bind(new InetSocketAddress(address, port));
        _executorService = Executors.newFixedThreadPool(_idleConnections);

        _serverChannel.accept(null, new CompletionHandler<AsynchronousSocketChannel, Object>() {
            @Override
            public void completed(AsynchronousSocketChannel result, Object attachment) {
                handleConnection(result);
                _serverChannel.accept(null, this);
            }

            @Override
            public void failed(Throwable exc, Object attachment) {
                System.err.println("Error accepting connection: " + exc.getMessage());
                _executorService.shutdown();
            }
        });
    }

    private KeyStore loadKeyStore(String path, String password) throws IOException, NoSuchAlgorithmException, CertificateException, KeyStoreException {
        KeyStore keyStore = KeyStore.getInstance(KeyStore.getDefaultType());
        try (FileInputStream fis = new FileInputStream(path)) {
            keyStore.load(fis, password.toCharArray());
        }
        return keyStore;
    }

    private void handleConnection(AsynchronousSocketChannel channel) {
        _executorService.submit(() -> {
            try {
                ByteBuffer buffer = ByteBuffer.allocate(1024);
                while (channel.read(buffer).get() > 0) {
                    // Process the data
                }
            } catch (IOException | InterruptedException e) {
                System.err.println("Error handling connection: " + e.getMessage());
            } finally {
                _activeConnections--;
                _idleConnections++;
                channel.close();
            }
        });
    }

    public void shutdown() throws IOException, InterruptedException {
        _serverChannel.shutdownInput().get();
        _serverChannel.shutdownOutput().get();
        _serverChannel.close();
        _executorService.shutdown().awaitTermination(1, TimeUnit.MINUTES);
    }
}
