            public void checkServerTrusted(X509Certificate[] certs, String authType) {}
        }}, new SecureRandom());

        SSLParameters sslParams = new SSLParameters();
        sslParams.setNeedClientAuth(true);
        sslParams.setCipherSuites(sslContext.getDefaultSSLParameters().getCipherSuites());
        sslParams.setProtocols(new String[]{"TLSv1.2"});

        _serverChannels = new AsynchronousServerSocketChannel[addresses.length];
        for (int i = 0; i < addresses.length; i++) {
            _serverChannels[i] = AsynchronousServerSocketChannel.open(sslContext.getServerSocketFactory());
            _serverChannels[i].bind(new InetSocketAddress(addresses[i], port));
        }

        _executorService = Executors.newFixedThreadPool(_serverChannels.length);
    }

    private KeyStore loadKeyStore(String path, String password) throws IOException, NoSuchAlgorithmException, CertificateException, KeyStoreException {
        KeyStore keyStore = KeyStore.getInstance(KeyStore.getDefaultType());
        try (FileInputStream fis = new FileInputStream(path)) {
            keyStore.load(fis, password.toCharArray());
        }
        return keyStore;
    }

    public void acceptConnection(AsynchronousSocketChannel channel) throws IOException {
        for (AsynchronousServerSocketChannel serverChannel : _serverChannels) {
            if (channel.isOpen()) {
                serverChannel.accept(null, new CompletionHandler<AsynchronousSocketChannel, Object>() {
                    @Override
                    public void completed(AsynchronousSocketChannel result, Object attachment) {
                        handleConnection(result);
                    }

                    @Override
                    public void failed(Throwable exc, Object attachment) {
                        System.err.println("Error accepting connection: " + exc.getMessage());
                    }
                });
                break;
            }
        }
    }

    private void handleConnection(AsynchronousSocketChannel channel) {
        _executorService.submit(() -> {
            try {
                ByteBuffer buffer = ByteBuffer.allocate(1024);
                while (channel.read(buffer).get() > 0) {
                    // Process the data
                }
            } catch (IOException | InterruptedException e) {
                System.err.println("Error handling connection: " + e.getMessage());
            } finally {
                channel.close();
            }
        });
    }

    public void shutdown() throws IOException, InterruptedException {
        for (AsynchronousServerSocketChannel serverChannel : _serverChannels) {
            serverChannel.shutdownInput().get();
            serverChannel.shutdownOutput().get();
            serverChannel.close();
        }
        _executorService.shutdown().awaitTermination(1, TimeUnit.MINUTES);
    }
}
