// JavaScript Function to Dynamically Render Script Objects as a Footer

function renderScripts(scripts) {
    const footer = document.querySelector('footer');

    if (!scripts || !Array.isArray(scripts)) {
        console.error('Invalid scripts array');
        return '';
    }

    let html = '';

    scripts.forEach(script => {
        if (script.code && script.type) {
            html += `<script key="${script.key}" type="${script.type}">${script.code}</script>`;
        } else {
            console.warn(`Missing essential properties in script: ${JSON.stringify(script)}`);
        }
    });

    footer.innerHTML = html;

    // Fetch and render new scripts asynchronously
    fetch('https://api.example.com/scripts')
        .then(response => response.json())
        .then(newScripts => {
            newScripts.forEach(script => renderScripts([script]));
        })
        .catch(error => console.error('Error fetching scripts:', error));

    return html;
}
