impl FileManager {
    // Create a new instance of FileManager
    pub fn new() -> Result<Self, Box<dyn std::error::Error>> {
        let work_dir = match std::env::var("WORK_DIR") {
            Ok(path) => {
                let path = std::path::Path::new(&path);
                if path.exists() && path.is_dir() && path.readable() {
                    path.to_path_buf()
                } else {
                    return Err(format!("Invalid WORK_DIR: {}", path.display()).into());
                }
            }
            Err(_) => {
                let temp_dir = std::env::temp_dir().join("unique_name");
                if std::fs::create_dir_all(&temp_dir).is_err() {
                    return Err("Failed to create temporary directory".into());
                }
                temp_dir
            }
        };
        Ok(FileManager { work_dir })
    }

    // Method to clean up the working directory
    pub fn cleanup(&self) -> Result<(), Box<dyn std::error::Error>> {
        if self.work_dir.exists() && self.work_dir.is_dir() {
            std::fs::remove_dir_all(&self.work_dir)?;
        }
        Ok(())
    }

