class DynamicLoader {
public:
    using FactoryFunction = std::function<std::shared_ptr<void>()>;

    // Add factory function to registry
    void addFactory(const std::string& id, const FactoryFunction& factory) {
        factories[id] = factory;
    }

    // Load and create an instance of a class
    std::shared_ptr<void> loadAndCreateInstance(const std::string& id) {
        if (auto it = factories.find(id); it != factories.end()) {
            return it->second();
        }
        throw std::runtime_error("Factory not found for ID: " + id);
    }

private:
    std::map<std::string, FactoryFunction> factories;
