```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentLinkedQueue;
import org.apache.commons.pool2.BasePooledObjectFactory;
import org.apache.commons.pool2.PooledObject;
import org.apache.commons.pool2.impl.DefaultPooledObject;
import org.apache.commons.pool2.impl.GenericObjectPool;
import org.apache.commons.pool2.impl.GenericObjectPoolConfig;

public class NonBlockingConnectionPool {

    private final ConcurrentHashMap<String, GenericObjectPool<NonBlockingChannel>> poolMap = new ConcurrentHashMap<>();

    public NonBlockingConnectionPool(int maxTotalPerRoute) {
        for (String server : servers) { // Assume 'servers' is a list of remote addresses
            GenericObjectPoolConfig<NonBlockingChannel> config = new GenericObjectPoolConfig<>();
            config.setMaxTotal(maxTotalPerRoute);
            poolMap.put(server, new GenericObjectPool<>(new ChannelFactory(), config));
        }
    }

    public NonBlockingChannel getConnection(String server) throws IOException {
        return poolMap.get(server).borrowObject();
    }

    public void releaseConnection(NonBlockingChannel channel) {
        for (GenericObjectPool<NonBlockingChannel> pool : poolMap.values()) {
            if (pool.contains(channel)) {
                pool.returnObject(channel);
                break;
            }
        }
    }

    private static class ChannelFactory extends BasePooledObjectFactory<NonBlockingChannel> {

        @Override
        public NonBlockingChannel create() throws Exception {
            return new NonBlockingChannel(new InetSocketAddress("serverAddress", port)); // Replace with actual server and port
        }

        @Override
        public PooledObject<NonBlockingChannel> wrap(NonBlockingChannel channel) {
            return new DefaultPooledObject<>(channel);
        }
    }
}
