c_lib.monitor_resources.restype = ctypes.c_int

def create_namespace(namespace_name):
    try:
        api_instance = k8s_client.CoreV1Api()
        namespace = k8s_client.V1Namespace(metadata=k8s_client.V1ObjectMeta(name=namespace_name))
        api_response = api_instance.create_namespace(body=namespace)
        print(f"Namespace '{api_response.metadata.name}' created")
    except ApiException as e:
        print(f"Failed to create namespace: {e}")

def deploy_application(namespace, manifest_path):
    try:
        api_instance = k8s_client.AppsV1Api()
        with open(manifest_path, 'r') as file:
            deployment_manifest = file.read()
        api_response = api_instance.create_namespaced_deployment(body=deployment_manifest, namespace=namespace)
        print(f"Deployment '{api_response.metadata.name}' created in namespace '{namespace}'")
    except ApiException as e:
        print(f"Failed to deploy application: {e}")

def monitor_resources(namespace):
    try:
        pod_list = api_instance.list_namespaced_pod(namespace=namespace)
        for pod in pod_list.items:
            cpu_usage, memory_usage = c_lib.monitor_resources(pod.metadata.name.encode())
            resource_gauges['cpu'].labels(pod_name=pod.metadata.name).set(cpu_usage)
            resource_gauges['memory'].labels(pod_name=pod.metadata.name).set(memory_usage)
    except ApiException as e:
        print(f"Failed to monitor resources: {e}")

if __name__ == "__main__":
    start_http_server(8000)  # Start Prometheus metrics server
    resource_gauges = {
        'cpu': Gauge('kubernetes_pod_cpu_usage', 'CPU usage in milli-cores'),
        'memory': Gauge('kubernetes_pod_memory_usage', 'Memory usage in bytes')
    }

    create_namespace("my-namespace")
    deploy_application("my-namespace", "path/to/deployment.yaml")

    while True:
        monitor_resources("my-namespace")
        time.sleep(5)
