        // Simulate database operation with retries
        int attempts = 0;
        while (attempts < retryCount) {
            try {
                orders.put(orderId, "cancelled");
                log("Order cancelled for order ID: " + orderId);
                break;
            } catch (Exception e) {
                attempts++;
                log("Failed to cancel order for order ID: " + orderId + ". Attempt " + (attempts + 1));
            }
        }

        if (attempts == retryCount) {
            log("Max retries reached. Failed to cancel order for order ID: " + orderId);
