```javascript
const fetch = require('node-fetch');
const fs = require('fs');
const path = require('path');

class ScriptLoader {
  constructor(options) {
    this.options = options;
    this.cache = {};
    this.loadingScripts = new Set();
  }

  async loadScript(url, filePath) {
    if (this.cache[filePath]) return Promise.resolve();

    if (this.loadingScripts.has(filePath)) {
      return await new Promise((resolve, reject) => {
        const listener = () => {
          if (!this.loadingScripts.has(filePath)) {
            resolve();
            this.loadingScripts.delete(listener);
          }
        };
        this.loadingScripts.add(listener);
      });
    }

    try {
      console.log(`Loading ${filePath}`);
      this.loadingScripts.add(filePath);

      if (url.startsWith('http')) {
        const response = await fetch(url);
        if (!response.ok) throw new Error(`Failed to load script from URL: ${url}`);

        const scriptContent = await response.text();
        fs.writeFileSync(filePath, scriptContent);
      } else {
        // Assuming local file path
        const content = fs.readFileSync(url, 'utf8');
        fs.writeFileSync(filePath, content);
      }

      this.cache[filePath] = true;
      console.log(`Loaded and cached ${filePath}`);

      return await this.executeScript(filePath);
    } catch (error) {
      console.error(`Error loading script ${filePath}:`, error);
      throw error;
    } finally {
      this.loadingScripts.delete(filePath);
    }
  }

  async executeScript(filePath) {
    try {
      const code = fs.readFileSync(filePath, 'utf8');
      eval(code); // Be cautious with using eval!
      console.log(`Executed script ${filePath}`);
    } catch (error) {
      console.error(`Error executing script ${filePath}:`, error);
      throw error;
    }
  }

  async loadScripts(urls) {
    const filePaths = urls.map(url => path.resolve(__dirname, `scripts/${path.basename(url)}.js`));

    await Promise.all(filePaths.map(filePath => this.loadScript(urls.find(u => u === filePath), filePath)));
  }
}

// Usage
const loader = new ScriptLoader({ /* options */ });
loader.loadScripts(['http://example.com/script1.js', 'http://example.com/script2.js']);
