        double performanceMetric = 0.0; // Calculate performance metric
        results.emplace_back(exitCode, performanceMetric);

        // Log operation details
        std::lock_guard<std::mutex> lock(logMutex);
        logManager.logMessage("Encrypted file: " + filePath + ", Exit Code: " + std::to_string(exitCode));
    }

    return results;
}

// Asynchronous mode using message queue
std::vector<std::tuple<int, double>> encryptFilesAsync(const std::vector<std::string>& filePaths, const ConfigReader& config) {
    // Message queue implementation
    std::queue<std::pair<std::string, int>> taskQueue;
    std::mutex queueMutex;
    std::condition_variable queueCondVar;

    // Worker thread for processing tasks
    auto worker = [&]() {
        while (true) {
            std::string filePath;
            int exitCode;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                queueCondVar.wait(lock, []{ return !taskQueue.empty(); });
                filePath = taskQueue.front().first;
                exitCode = taskQueue.front().second;
                taskQueue.pop();
            }
            // Encryption logic using OpenSSL
        }
    };

    std::vector<std::thread> threads;
    for (size_t i = 0; i < std::thread::hardware_concurrency(); ++i) {
        threads.emplace_back(worker);
    }

    // Enqueue tasks
    for (const auto& filePath : filePaths) {
        int exitCode = encryptFile(filePath, config.getCipher(), config.getMode(), std::mutex{}, std::ofstream{});
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            taskQueue.emplace(filePath, exitCode);
        }
        queueCondVar.notify_one();
    }

    // Join worker threads
    for (auto& thread : threads) {
        thread.join();
    }

    return results;
}
