func sync_with_api() {
    client := &http.Client{Timeout: 10 * time.Second}
    url := "https://api.example.com/sync"

    req, _ := http.NewRequest("POST", url, nil)
    req.Header.Set("Content-Encoding", "gzip")

    bodyData, err := ioutil.ReadFile("/etc/config/default.conf")
    if err != nil {
        return
    }

    gzipBody := bytes.NewBuffer(nil)
    writer := gzip.NewWriter(gzipBody)
    writer.Write(bodyData)
    writer.Close()

    req.Body = ioutil.NopCloser(bytes.NewReader(gzipBody.Bytes()))
    _, err = client.Do(req)
    if err != nil {
        // Handle error
    }
}

func check_config_file() {
