import requests
from datetime import timedelta, datetime
from apscheduler.schedulers.background import BackgroundScheduler
from cachetools import TTLCache, cached

# API Configuration
API_KEYS = {
    'weatherapi': 'your_api_key_here',
    'openweathermap': 'your_api_key_here'
}

BASE_URLS = {
    'weatherapi': 'https://api.weatherapi.com/v1/',
    'openweathermap': 'https://api.openweathermap.org/data/2.5/'
}

# Cache Configuration
CACHE_TTL = 3600  # seconds (1 hour)
data_cache = TTLCache(maxsize=100, ttl=CACHE_TTL)

def get_weather_data(api_name, location):
    url = f"{BASE_URLS[api_name]}current.json"
    headers = {'Authorization': f'Bearer {API_KEYS[api_name]}'}
    params = {'key': API_KEYS[api_name], 'q': location, 'aqi': 'no'}

    @cached(cache=data_cache)
    def fetch_data():
        response = requests.get(url, headers=headers, params=params)
        if response.status_code == 200:
            return response.json()
        else:
            raise Exception(f"Failed to fetch data from {api_name}: {response.status_code}")

    try:
        weather_data = fetch_data()
        # Transform data for consistency
        consistent_data = {
            'location': weather_data['location']['name'],
            'temperature': weather_data['current']['temp_c'],
            'humidity': weather_data['current']['humidity']
        }
        return consistent_data
    except Exception as e:
        print(f"Error fetching {api_name} data: {e}")
        return None

# Background Scheduler for periodic updates
scheduler = BackgroundScheduler()
def update_cache():
    locations = ['New York', 'London', 'Tokyo']
    for location in locations:
        get_weather_data('weatherapi', location)
        get_weather_data('openweathermap', location)

scheduler.add_job(update_cache, 'interval', hours=1)
scheduler.start()

# Main function to fetch and display weather data
def main():
    try:
        nyc_weather = get_weather_data('weatherapi', 'New York')
        print(f"New York Weather: {nyc_weather}")

        ldn_weather = get_weather_data('openweathermap', 'London')
        print(f"London Weather: {ldn_weather}")

        tokyo_weather = get_weather_data('weatherapi', 'Tokyo')
        print(f"Tokyo Weather: {tokyo_weather}")
    except Exception as e:
        print(f"Error in main function: {e}")

if __name__ == "__main__":
    main()
