// Import required modules
const fs = require('fs');
const path = require('path');

// Define a class for managing module loading and execution
class ModuleManager {
  constructor(configPath) {
    this.configPath = configPath;
    this.modules = {};
    this.moduleQueue = [];
    this.concurrencyLevel = 1;
    this.logger = console.log;
  }

  setConcurrencyLevel(level) {
    this.concurrencyLevel = level;
  }

  log(message) {
    this.logger(`[ModuleManager] ${message}`);
  }

  loadModules() {
    const config = require(this.configPath);
    for (const module of config.modules) {
      this.moduleQueue.push(module);
    }
    this.processQueue();
  }

  processQueue() {
    while (this.moduleQueue.length > 0 && Object.keys(this.modules).length < this.concurrencyLevel) {
      const moduleName = this.moduleQueue.shift();
      if (!this.modules[moduleName]) {
        try {
          this.loadModule(moduleName);
        } catch (error) {
          this.log(`Error loading module ${moduleName}: ${error.message}`);
        }
      }
    }

    if (this.moduleQueue.length > 0) {
      setTimeout(() => this.processQueue(), 100); // Check queue again after a short delay
    }
  }

  loadModule(moduleName) {
    const modulePath = path.join(__dirname, 'modules', `${moduleName}.js`);
    const module = require(modulePath);
    this.modules[moduleName] = module;
    this.log(`Loaded module ${moduleName}`);
  }
}

// Define an asynchronous function for reducing an array of numbers
function asyncReduce(array, initialValue, callback) {
  let result = initialValue;
  return new Promise((resolve, reject) => {
    (async () => {
      try {
        for (const value of array) {
          result = await callback(result, value);
        }
        resolve(result);
      } catch (error) {
        reject(error);
      }
    })();
  });
}

