import time
import threading
import queue
from collections import defaultdict

# Define categories and statistics
categories = ['Error', 'Warning', 'Info']
stats = {
    'total_lines': 0,
    'total_words': 0,
    'total_chars': 0
}

# Initialize log processing queues
log_queues = {category: queue.Queue() for category in categories}

# Define a function to categorize and process logs
def process_log(log_line):
    try:
        device_id, timestamp, severity, message = log_line.split(',')
        category = get_category(severity)
        log_queue = log_queues[category]
        log_queue.put((device_id, timestamp, severity, message))
        update_stats(category, len(message))
    except Exception as e:
        handle_error(log_line, str(e))

# Define a function to retrieve the appropriate category based on severity
def get_category(severity):
    if severity == '1':
        return 'Error'
    elif severity == '2':
        return 'Warning'
    else:
        return 'Info'

# Define a function to update statistics for each log category
def update_stats(category, message_length):
    stats['total_lines'] += 1
    stats['total_words'] += len(message.split())
    stats['total_chars'] += message_length

# Define a function to handle errors in log processing
def handle_error(log_line, error_message):
    print(f"Error processing log line: {log_line}, Error: {error_message}")

# Define a function to process logs from a device
def device_log_processor(device_id):
    while True:
        log_line = receive_log_from_device(device_id)
        if not log_line:
            break
        process_log(log_line)

# Define a function to simulate receiving logs from an IoT device
def receive_log_from_device(device_id):
    # Simulate log data
    time.sleep(0.1)  # Simulate delay in receiving logs
    return f"{device_id},{time.time()},{get_random_severity()}," \
           f"Log message from device {device_id}"

# Define a function to simulate getting a random severity level
def get_random_severity():
    import random
    return str(random.randint(1, 3))

# Define a function to start log processing threads for multiple devices
def start_device_log_processors(device_ids):
    threads = []
    for device_id in device_ids:
        thread = threading.Thread(target=device_log_processor, args=(device_id,))
        threads.append(thread)
        thread.start()
    return threads

# Define a function to wait for all threads to complete
def join_threads(threads):
    for thread in threads:
        thread.join()

# Main function to run the log processing system
if __name__ == "__main__":
    device_ids = ['device1', 'device2', 'device3']
    threads = start_device_log_processors(device_ids)
    try:
        while True:
            time.sleep(5)  # Check statistics every 5 seconds
            print(f"Total lines: {stats['total_lines']}, Total words: {stats['total_words']}, Total chars: {stats['total_chars']}")
    except KeyboardInterrupt:
        join_threads(threads)
        print("Log processing stopped.")
```

