app = Flask(__name__)

# Cache to store fetched data
data_cache = {}

def loadAndRenderCharts(charts):
    # HTML template for loading spinner and container for charts
    html_template = '''
        <div id="loading-spinner">Loading...</div>
        <div id="chart-container">
            {% for chart in charts %}
                <div id="{{ chart['id'] }}"></div>
            {% endfor %}
        </div>
    '''

    # Render the HTML template with initial data
    html_content = render_template_string(html_template, charts=charts)

    # Asynchronously load and render each chart
    for index, chart in enumerate(charts):
        chart_id = chart.get('id', f'chart-{index}')
        chart_type = chart.get('chart_type', 'line')
        data_source = chart.get('data_source', '')
        options = chart.get('options', {})

        # Check if data is already cached
        if data_source in data_cache:
            data = data_cache[data_source]
        else:
            try:
                response = requests.get(data_source)
                response.raise_for_status()
                data = response.json()
                data_cache[data_source] = data
            except requests.RequestException as e:
                print(f"Error fetching data from {data_source}: {e}")
                continue

        # Render chart using JavaScript and fetched data
        html_content += f'''
            <script>
                document.getElementById('{chart_id}').innerHTML = '<canvas id="canvas-{chart_id}"></canvas>';
                var ctx = document.getElementById('canvas-{chart_id}').getContext('2d');
                var my{capitalize(chart_type.capitalize())}Chart = new Chart(ctx, {{
                    type: '{chart_type}',
                    data: {json.dumps(data)},
                    options: {json.dumps(options)}
                }});
            </script>
        '''

    return html_content

def capitalize(s):
    """Helper function to capitalize the first letter of a string."""
    return s[0].upper() + s[1:]

