```java
import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class FileProcessor {

    public void processFileBatchWithValidationAndMetadata(String inputDirectory, String outputDirectory, List<Rule> validationRules, MetadataExtractionService metadataService) {
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

        try (Files.walk(Paths.get(inputDirectory)))
            .filter(Files::isRegularFile)
            .forEach(filePath -> executor.submit(() -> processFile(filePath, outputDirectory, validationRules, metadataService)));

        executor.shutdown();
        try {
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            System.err.println("File processing interrupted");
        }
    }

    private void processFile(Path filePath, String outputDirectory, List<Rule> validationRules, MetadataExtractionService metadataService) {
        try {
            System.out.println("Starting file processing: " + filePath);

            // Extract metadata asynchronously
            CompletableFuture<Void> metadataFuture = CompletableFuture.runAsync(() -> 
                metadataService.extractMetadata(filePath).ifPresent(metadata -> {
                    Path outputFilePath = Paths.get(outputDirectory, "metadata_" + filePath.getFileName());
                    try (BufferedWriter writer = Files.newBufferedWriter(outputFilePath)) {
                        writer.write(metadata.toString());
                    } catch (IOException e) {
                        System.err.println("Error writing metadata: " + e.getMessage());
                    }
                })
            );

            // Validate file with each rule
            for (Rule rule : validationRules) {
                String ruleName = rule.getClass().getSimpleName();
                try {
                    if (!rule.validate(filePath)) {
                        System.out.println("Validation failed for file: " + filePath + " using rule: " + ruleName);
                    } else {
                        System.out.println("Validation passed for file: " + filePath + " using rule: " + ruleName);
                    }
                } catch (Exception e) {
                    System.err.println("Error during validation with rule " + ruleName + ": " + e.getMessage());
                }
            }

            metadataFuture.get(); // Wait for metadata extraction to complete

        } catch (IOException | InterruptedException | ExecutionException e) {
            System.err.println("Error processing file: " + filePath + " - " + e.getMessage());
        }
    }
}
