public enum RangeType { Inclusive, Exclusive }

public interface IRandomGenerator
{
    double GenerateDouble(double min, double max, RangeType range);
    int GenerateInt(int min, int max, RangeType range);
}

public class CustomRandomGenerator : IRandomGenerator
{
    private Random random;
    private Dictionary<string, Tuple<double, double>> rangeCache;

    public CustomRandomGenerator()
    {
        random = new Random();
        rangeCache = new Dictionary<string, Tuple<double, double>>();
    }

    public void SetSeed(long seed)
    {
        random = new Random(seed);
    }

    public double GenerateDouble(double min, double max, RangeType range)
    {
        if (range == RangeType.Inclusive)
        {
            return UnityEngine.Random.Range(min, max + 0.0001); // Ensure inclusivity
        }
        else
        {
            return UnityEngine.Random.Range(min, max);
        }
    }

    public int GenerateInt(int min, int max, RangeType range)
    {
        if (range == RangeType.Inclusive)
        {
            return UnityEngine.Random.Range(min, max + 1); // Ensure inclusivity
        }
        else
        {
            return UnityEngine.Random.Range(min, max);
        }
    }

