```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class AESGCMEncryptionService
{
    private readonly IKeyManagementService _keyManagementService;

    public AESGCMEncryptionService(IKeyManagementService keyManagementService)
    {
        _keyManagementService = keyManagementService ?? throw new ArgumentNullException(nameof(keyManagementService));
    }

    public byte[] Encrypt(byte[] data, byte[] aad, string keyId)
    {
        var encryptionKey = _keyManagementService.GetKey(keyId);
        if (encryptionKey == null)
            throw new KeyNotFoundException("Encryption key not found.");

        using (var aesGcm = Aes.Create())
        {
            aesGcm.Key = encryptionKey;
            aesGcm.GcmMode = CipherMode.GCM;
            aesGcm.GenerateNonce();
            aesGcm.AdditionalAuthenticatedData = aad;

            byte[] encryptedData;
            using (var ms = new MemoryStream())
            {
                using (var cs = new CryptoStream(ms, aesGcm.CreateEncryptor(), CryptoStreamMode.Write))
                {
                    cs.Write(data, 0, data.Length);
                    cs.FlushFinalBlock();
                }
                encryptedData = ms.ToArray();
            }

            return Combine(encryptedData, aesGcm.Tag);
        }
    }

    public byte[] Decrypt(byte[] encryptedDataWithTag, byte[] aad, string keyId)
    {
        var encryptionKey = _keyManagementService.GetKey(keyId);
        if (encryptionKey == null)
            throw new KeyNotFoundException("Encryption key not found.");

        using (var aesGcm = Aes.Create())
        {
            aesGcm.Key = encryptionKey;
            aesGcm.GcmMode = CipherMode.GCM;
            var tagLength = aad.Length > 0 ? 16 : 12; // Default GCM tag length is 12 bytes
            byte[] encryptedData = new byte[encryptedDataWithTag.Length - tagLength];
            Buffer.BlockCopy(encryptedDataWithTag, 0, encryptedData, 0, encryptedData.Length);
            aesGcm.AdditionalAuthenticatedData = aad;
            aesGcm.Tag = new byte[tagLength];
            Buffer.BlockCopy(encryptedDataWithTag, encryptedData.Length, aesGcm.Tag, 0, tagLength);

            using (var ms = new MemoryStream())
            {
                using (var cs = new CryptoStream(ms, aesGcm.CreateDecryptor(), CryptoStreamMode.Write))
                {
                    cs.Write(encryptedData, 0, encryptedData.Length);
                    cs.FlushFinalBlock();
                }
                return ms.ToArray();
            }
        }
    }

    private byte[] Combine(byte[] a, byte[] b)
    {
        var result = new byte[a.Length + b.Length];
        Buffer.BlockCopy(a, 0, result, 0, a.Length);
        Buffer.BlockCopy(b, 0, result, a.Length, b.Length);
        return result;
    }
}

public interface IKeyManagementService
{
    byte[] GetKey(string keyId);
}
```

