// JavaScript non-recursive function named FindElementsBySelector with a callback function
function findElementsBySelectorWithCallback(node, selector, callback) {
    if (!node || !selector || typeof callback !== 'function') return [];

    const elements = [];
    const stack = [node];

    while (stack.length > 0) {
        const currentNode = stack.pop();
        if (currentNode.nodeType === Node.ELEMENT_NODE) {
            if (currentNode.matches(selector) && callback(currentNode)) {
                elements.push(currentNode);
            }
            for (let i = 0; i < currentNode.childNodes.length; ++i) {
                stack.push(currentNode.childNodes[i]);
            }
        }
    }

    return elements;
}
