    [HttpPost]
    public IHttpActionResult UpdateHtmlContent(int pageSectionId, int elementId, string htmlContent)
    {
        try
        {
            // Apply rate limiting logic here if needed

            var decryptedHtmlContent = DecryptionService.Decrypt(htmlContent, _decryptionKey, _iv);

            // Validate the updated HTML content against a whitelist of tags and attributes
            if (!ValidationService.Validate(decryptedHtmlContent))
            {
                return BadRequest("Invalid HTML content");
