using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Xml.Linq;
using System.Xml.Schema;

public class DynamicXmlManager
{
    private readonly ConcurrentDictionary<string, XDocument> _xmlCache = new ConcurrentDictionary<string, XDocument>();
    private readonly string _xsdSchemaPath;
    private readonly HttpClient _httpClient;
    private bool _isLoggingEnabled;

    public DynamicXmlManager(string xsdSchemaPath)
    {
        _xsdSchemaPath = xsdSchemaPath;
        _httpClient = new HttpClient();
    }

    public void EnableLogging(bool isEnabled)
    {
        _isLoggingEnabled = isEnabled;
    }

    public void ParseAndValidateXml(string xmlUrl, string cacheKey)
    {
        if (!_xmlCache.TryGetValue(cacheKey, out var document))
        {
            document = DownloadXmlDocument(xmlUrl);
            ValidateXmlDocument(document);
            _xmlCache.TryAdd(cacheKey, document);
        }
    }

    private XDocument DownloadXmlDocument(string url)
    {
        var response = _httpClient.GetAsync(url).Result;
        response.EnsureSuccessStatusCode();
        var xmlContent = response.Content.ReadAsStringAsync().Result;
        return XDocument.Parse(xmlContent);
    }

    private void ValidateXmlDocument(XDocument document)
    {
        var schemaSet = new XmlSchemaSet();
        schemaSet.Add(null, _xsdSchemaPath);

        var settings = new XmlReaderSettings
        {
            Schemas = schemaSet,
            ValidationType = ValidationType.Schema
        };

        settings.ValidationEventHandler += (sender, e) =>
        {
            if (_isLoggingEnabled)
                Log($"Validation error: {e.Message}");
            throw new InvalidOperationException("XML document is not valid.");
        };

        using (var reader = XmlReader.Create(new StringReader(document.ToString()), settings))
        {
            while (reader.Read()) ;
        }
    }

    public XElement GetFirstElement(string xpath, string cacheKey)
    {
        var document = _xmlCache[cacheKey];
        var element = document.XPathSelectElements(xpath).FirstOrDefault();
        if (element == null)
            throw new InvalidOperationException("No element found or multiple elements match the XPath query.");
        return element;
    }

    private void Log(string message)
    {
        // Implement logging logic here
        Console.WriteLine(message);
    }
}
