logging.basicConfig(level=logging.INFO)

class JSONBase:
    factory_registry = {}

    @staticmethod
    def register_factory(id, factory):
        JSONBase.factory_registry[id] = factory

    @classmethod
    def from_json(cls, json_str):
        data = json.loads(json_str)
        return cls.from_dict(data)

    @classmethod
    def from_dict(cls, data):
        return cls(**data)

    def to_json(self):
        return json.dumps(self.__dict__)

    def insert_after(self, forward_list, str1, str2, position_index=None):
        if position_index is None:
            forward_list.append(str2)
        else:
            try:
                index = forward_list.index(str1, position_index)
                forward_list.insert(index + 1, str2)
            except ValueError:
                logging.error(f"'{str1}' not found in the list")
                return False
        return True

async def load_json_files(file_paths):
    tasks = [load_file_async(path) for path in file_paths]
    results = await asyncio.gather(*tasks, return_exceptions=True)
    return results

def load_file_async(file_path):
    try:
        with open(file_path, 'r') as file:
            return json.load(file)
    except Exception as e:
        logging.error(f"Failed to load {file_path}: {e}")
        return None

async def main():
