// Main Application Class
@SpringBootApplication
@EnableAsync
public class TaskManagementServiceApplication {
    public static void main(String[] args) {
        SpringApplication.run(TaskManagementServiceApplication.class, args);
    }
}

// Task Manager Service
@Service
public class TaskManagerService {

    @Autowired
    private JobSchedulingApi jobSchedulingApi;

    @Autowired
    private CacheManager cacheManager;

    @Async("taskThreadPool")
    public CompletableFuture<String> executeTask(String taskId) {
        try {
            // Check cache first
            String cachedResult = cacheManager.get(taskId);
            if (cachedResult != null) {
                return CompletableFuture.completedFuture(cachedResult);
            }

            // Fetch task details from API and execute
            TaskDetails taskDetails = jobSchedulingApi.fetchTaskDetails(taskId);
            String result = taskDetails.execute();

            // Cache the result
            cacheManager.put(taskId, result);

            return CompletableFuture.completedFuture(result);
        } catch (Exception e) {
            log.error("Failed to execute task: {}", taskId, e);
            throw new RuntimeException("Task execution failed", e);
        }
    }

    @PostConstruct
    public void init() {
        // Initialize thread pool with dynamic scaling based on system load and available resources
        ThreadFactory namedThreadFactory = r -> new Thread(r, "Task-Worker");
        ExecutorService taskThreadPool = Executors.newCachedThreadPool(namedThreadFactory);

        // Configure caching mechanism with intelligent eviction strategies
        CacheBuilder<String, String> cacheBuilder = CacheBuilder.newBuilder()
                .maximumSize(1000)  // Limit cache size to avoid memory overflow
                .expireAfterWrite(30, TimeUnit.MINUTES);  // Evict entries after 30 minutes of last write

        this.cacheManager = cacheBuilder.build();
    }
}

// Job Scheduling API Interface
public interface JobSchedulingApi {
    TaskDetails fetchTaskDetails(String taskId) throws Exception;
}

// Task Details Class
public class TaskDetails {
    private String command;

    public TaskDetails(String command) {
        this.command = command;
    }

    public String execute() {
        // Simulate task execution
        try {
            ProcessBuilder processBuilder = new ProcessBuilder(command.split(" "));
            Process process = processBuilder.start();
            int exitCode = process.waitFor();
            return "Task completed with exit code: " + exitCode;
        } catch (IOException | InterruptedException e) {
            throw new RuntimeException("Failed to execute task", e);
        }
    }

    // Getters and setters
}

// Cache Manager Interface
public interface CacheManager<K, V> {
    V get(K key);
    void put(K key, V value);
    void remove(K key);
}
