class SpatialDataProcessor {
private:
    std::mutex octreeMutex; // Mutex for thread-safe operations on the octree
    int sizeLimit;          // Maximum number of data points allowed
    int currentSize;        // Current number of data points stored

public:
    // Constructor to initialize the spatial data processor with a size limit
    SpatialDataProcessor(int maxPoints) : sizeLimit(maxPoints), currentSize(0) {}

    // Method to add a new data point to the octree
    bool addDataPoint(const SpatialData& data) {
        std::lock_guard<std::mutex> lock(octreeMutex);
        if (currentSize >= sizeLimit) {
            return false; // Return false if adding more points would exceed the limit
        }
        // Add data point to the octree and update current size
        ++currentSize;
        return true;
    }

    // Other methods for managing spatial data points, initializing the octree, etc.
};

// Class to encapsulate the result of an image processing task
