        return {}

def aggregate_statistics(file_stats):
    stats_by_type = defaultdict(lambda: {'lines': 0, 'words': 0, 'characters': 0})
    for file_stat in file_stats:
        stats_by_type[file_stat['file_type']]['lines'] += file_stat['lines']
        stats_by_type[file_stat['file_type']]['words'] += file_stat['words']
        stats_by_type[file_stat['file_type']]['characters'] += file_stat['characters']
    return dict(stats_by_type)

def export_to_csv(data, output_path):
    with open(output_path, 'w', newline='') as csvfile:
        fieldnames = ['file_type', 'lines', 'words', 'characters']
        writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
        writer.writeheader()
        for row in data.values():
            writer.writerow(row)

def process_directory(directory):
    try:
        file_paths = [os.path.join(directory, f) for f in os.listdir(directory) if os.path.isfile(os.path.join(directory, f))]
        with ThreadPoolExecutor(max_workers=10) as executor:
            results = list(executor.map(process_file, file_paths))
        return aggregate_statistics(results)
    except Exception as e:
        logger.error(f"Error processing directory {directory}: {e}")
        return {}

def main():
    directory_path = 'path/to/directory'  # Replace with the path to your directory
    output_csv = 'output.csv'
    stats = process_directory(directory_path)
    export_to_csv(stats, output_csv)
    logger.info(f"Statistics exported to {output_csv}")

if __name__ == "__main__":
    main()
```

This code provides a basic structure for processing files in a specified directory and exporting the results. It uses threading to handle concurrent file reading and logging to record all operations. Error handling is implemented to manage issues like invalid paths, non-readable files, and unsupported file types. The script aggregates statistics by file type and exports them to a CSV file. Further enhancements can be made to support additional file formats, chunking for large `.csv` files, and dynamic data extraction from CSV files as required.

```python
import sys
import time
import threading

class LogProcessor:
    def __init__(self, input_files, output_file, keywords):
        self.input_files = input_files
        self.output_file = output_file
        self.keywords = keywords
        self.current_timestamps = {}
        self.failure_events = []

    def read_lines(self, file_path):
        with open(file_path, 'r') as file:
            for line in file:
                yield line.strip()

    def parse_line(self, line):
        timestamp, service_name, log_message = line.split(',')
        return time.strptime(timestamp, '%Y-%m-%d %H:%M:%S'), service_name, log_message

    def analyze_log_message(self, log_message):
        for keyword in self.keywords:
            if keyword in log_message:
                return keyword
        return None

    def calculate_latency(self, current_timestamp, previous_timestamp):
        return int((current_timestamp - previous_timestamp) * 1000)

    def process_log_files(self):
        threads = []
        for file_path in self.input_files:
            thread = threading.Thread(target=self.process_file, args=(file_path,))
            threads.append(thread)
            thread.start()
        for thread in threads:
            thread.join()

    def process_file(self, file_path):
        previous_timestamp = None
        with open(file_path, 'r') as file:
            for line in self.read_lines(file_path):
                current_timestamp, service_name, log_message = self.parse_line(line)
                keyword = self.analyze_log_message(log_message)
                if keyword is not None and previous_timestamp is not None:
                    latency = self.calculate_latency(current_timestamp, previous_timestamp)
                    self.failure_events.append((service_name, log_message, keyword, latency, current_timestamp))
                previous_timestamp = current_timestamp
                self.current_timestamps[file_path] = previous_timestamp

    def write_results(self):
        with open(self.output_file, 'w') as file:
            for event in self.failure_events:
                file.write(f"{event[0]},{event[1]},{event[2]},{event[3]},{time.strftime('%Y-%m-%d %H:%M:%S', event[4])}\n")

if __name__ == "__main__":
    if len(sys.argv) != 5:
        print("Usage: python log_processor.py <input_files> <output_file> <keywords>")
        sys.exit(1)

    input_files = sys.argv[1].split(',')
    output_file = sys.argv[2]
    keywords = sys.argv[3].split(',')

    processor = LogProcessor(input_files, output_file, keywords)
    try:
        processor.process_log_files()
        processor.write_results()
    except Exception as e:
        print(f"Error: {e}")
```

This code snippet defines a `LogProcessor` class that reads log files, processes each line to extract relevant information, and writes the results to an output file. The program uses threading to handle multiple input files concurrently and includes error handling for file operations.

