```javascript
function getElementListBySelector(rootElement, selector, ...filterCriteria) {
  const matches = [];

  function traverse(node) {
    if (!node || node.nodeType !== Node.ELEMENT_NODE) return;

    if (node.matches(selector)) {
      let shouldInclude = true;
      for (const criterion of filterCriteria) {
        const [attr, value] = Object.entries(criterion)[0];
        if (node.getAttribute(attr) !== value) {
          shouldInclude = false;
          break;
        }
      }
      if (shouldInclude) matches.push(node);
    }

    node.childNodes.forEach(traverse);
  }

  traverse(rootElement);
  return matches;
}
