```javascript
const { exec } = require('child_process');
const fs = require('fs');
const db = require('./database'); // Assuming a separate database module

function executeAndFilter(command, pattern) {
    return new Promise((resolve, reject) => {
        const child = exec(command, (error, stdout, stderr) => {
            if (error) {
                console.error(`Error executing command: ${command}`);
                fs.appendFile('error.log', `Error at ${new Date()}: ${error.message}\n`, (err) => {
                    if (err) throw err;
                });
                reject(error);
            } else {
                const filteredOutput = stdout.split('\n').filter(line => line.includes(pattern));
                resolve(filteredOutput);
            }
        });

        child.stderr.on('data', (data) => {
            console.error(`Stderr: ${data}`);
            fs.appendFile('error.log', `Stderr at ${new Date()}: ${data}\n`, (err) => {
                if (err) throw err;
            });
        });

        // Optional: Set a timeout to prevent excessive resource consumption
        setTimeout(() => {
            child.kill();
            reject(new Error('Command execution timed out'));
        }, 10000); // Adjust the timeout as needed
    });
}

function integrateWithDatabase(data, tableName) {
    return new Promise((resolve, reject) => {
        const insertQuery = db.getInsertQuery(tableName, data);
        db.query(insertQuery, (error, results) => {
            if (error) {
                console.error(`Error integrating with database: ${error.message}`);
                fs.appendFile('error.log', `Database error at ${new Date()}: ${error.message}\n`, (err) => {
                    if (err) throw err;
                });
                reject(error);
            } else {
                resolve(results);
            }
        });
    });
}

// Example usage
const command = 'ls -l'; // Replace with the actual command
const pattern = 'txt'; // Replace with the specific pattern to filter

executeAndFilter(command, pattern)
    .then(data => integrateWithDatabase(data, 'files'))
    .then(results => console.log('Data integrated into database:', results))
    .catch(error => console.error('Error during execution or integration:', error));
```

Please note that this code assumes the existence of a `database` module with methods like `getInsertQuery` and `query`. You will need to implement these methods based on your actual database setup and ORM.

