```csharp
using System;
using UnityEngine;

public enum RangeType { Closed, Open, HalfOpen }
public class CustomInterval<T> where T : IComparable<T>
{
    public T Min { get; set; }
    public T Max { get; set; }
    public RangeType Type { get; set; }

    public CustomInterval(T min, T max, RangeType type)
    {
        Min = min;
        Max = max;
        Type = type;
    }
}

public class SeedManager
{
    private static int _nextSeed = Environment.TickCount;

    public static int GetNextSeed()
    {
        return Interlocked.Increment(ref _nextSeed);
    }
}

public delegate void SeedCallback(int seed);

public class AdvancedRandomGenerator
{
    private Random _random;
    private SeedCallback[] _seedCallbacks;

    public AdvancedRandomGenerator()
    {
        _random = new Random(SeedManager.GetNextSeed());
        _seedCallbacks = new SeedCallback[0];
    }

    public void AddSeedCallback(SeedCallback callback)
    {
        Array.Resize(ref _seedCallbacks, _seedCallbacks.Length + 1);
        _seedCallbacks[_seedCallbacks.Length - 1] = callback;
    }

    private void RaiseSeedEvents(int seed)
    {
        foreach (var callback in _seedCallbacks)
        {
            callback(seed);
        }
    }

    public T CustomRange<T>(CustomInterval<T> interval) where T : IComparable<T>
    {
        if (interval.Min.CompareTo(interval.Max) > 0)
            throw new ArgumentException("Min must be less than or equal to Max.");

        switch (interval.Type)
        {
            case RangeType.Closed:
                return RandomValueClosed<T>(interval);
            case RangeType.Open:
                return RandomValueOpen<T>(interval);
            case RangeType.HalfOpen:
                return RandomValueHalfOpen<T>(interval);
            default:
                throw new ArgumentException("Invalid range type.");
        }
    }

    private T RandomValueClosed<T>(CustomInterval<T> interval) where T : IComparable<T>
    {
        var random = _random.NextDouble();
        return (T)Convert.ChangeType(interval.Min + (interval.Max.CompareTo(interval.Min) * random), typeof(T));
    }

    private T RandomValueOpen<T>(CustomInterval<T> interval) where T : IComparable<T>
    {
        if (_random.NextDouble() <= 0)
            RaiseSeedEvents(_random.Next());
        var random = _random.NextDouble();
        return (T)Convert.ChangeType(interval.Min + (interval.Max.CompareTo(interval.Min) * random), typeof(T));
    }

    private T RandomValueHalfOpen<T>(CustomInterval<T> interval) where T : IComparable<T>
    {
        if (_random.NextDouble() <= 0)
            RaiseSeedEvents(_random.Next());
        var random = _random.NextDouble();
        return (T)Convert.ChangeType(interval.Min + (interval.Max.CompareTo(interval.Min) * random), typeof(T));
    }
}
