// Java method for downloading image resources

public class ImageDownloader {
    private static final Logger logger = LoggerFactory.getLogger(ImageDownloader.class);
    private Cache<String, BufferedImage> cache;
    private ExecutorService executorService;

    public ImageDownloader(int maxCacheSize) {
        this.cache = Caffeine.newBuilder()
                .maximumSize(maxCacheSize)
                .build();
        this.executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    }

    public void downloadImageResources(List<String> urls) {
        List<CompletableFuture<Void>> futures = new ArrayList<>();
        for (String url : urls) {
            CompletableFuture<Void> future = CompletableFuture.runAsync(() -> {
                try {
                    BufferedImage image = downloadImage(url);
                    cache.put(url, image);
                    logger.info("Downloaded and cached image from {}", url);
                } catch (Exception e) {
                    logger.error("Failed to download or cache image from {}", url, e);
                }
            }, executorService);
            futures.add(future);
        }

        CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).join();
    }

    private BufferedImage downloadImage(String url) throws IOException {
        try (InputStream in = new URL(url).openStream()) {
            return ImageIO.read(in);
        }
    }

    public void shutdown() {
        executorService.shutdown();
    }
}
