public class DynamicDatabaseConnectionManager : IDisposable {
    private readonly ConcurrentDictionary<string, IDbConnection> _connections = new();
    private readonly SemaphoreSlim _semaphore;
    private Timer _performanceMonitorTimer;

    public DynamicDatabaseConnectionManager(int poolSize) {
        _semaphore = new SemaphoreSlim(poolSize);
        _performanceMonitorTimer = new Timer(ReportPerformanceMetrics, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
    }

    public IDbConnection GetConnection(string connectionString) {
        string key = connectionString;
        if (!_connections.TryGetValue(key, out IDbConnection connection)) {
            lock (_connections) {
                if (!_connections.TryGetValue(key, out connection)) {
                    connection = CreateConnection(connectionString);
                    _connections[key] = connection;
                }
            }
        }

        return connection;
    }

    private IDbConnection CreateConnection(string connectionString) {
        // Implement database connection creation based on the provided connection string
        throw new NotImplementedException();
    }

    public void ReportPerformanceMetrics(object state) {
        // Collect and report performance metrics such as connection request latency, pool size, and idle connection counts
        throw new NotImplementedException();
    }

    public void Dispose() {
        _performanceMonitorTimer.Dispose();
        foreach (var connection in _connections.Values)
            connection.Dispose();
        _connections.Clear();
    }
}
