using System;
using System.Collections.Concurrent;
using System.Data;
using System.Data.Common;
using System.Diagnostics;
using System.Threading.Tasks;

public class DatabaseConnectionManager
{
    private readonly ConcurrentDictionary<string, DbProviderFactory> _factories = new();
    private readonly ConcurrentDictionary<string, Queue<DbConnection>> _connectionPools = new();
    private readonly object _poolLock = new();

    public DatabaseConnectionManager()
    {
        InitializeProviders();
    }

    public IDbConnection GetConnection(string provider, string connectionString)
    {
        var poolKey = $"{provider}_{connectionString}";
        if (!_connectionPools.TryGetValue(poolKey, out var pool))
        {
            lock (_poolLock)
            {
                if (!_connectionPools.TryGetValue(poolKey, out pool))
                {
                    _connectionPools[poolKey] = new Queue<DbConnection>();
                }
            }
        }

        while (pool.Count > 0 && !pool.Peek().CanContinueReading())
        {
            pool.Dequeue();
        }

        if (pool.Count > 0)
        {
            return pool.Dequeue();
        }

        var factory = _factories[provider];
        return factory.CreateConnection() { ConnectionString = connectionString };
    }

    public void ReleaseConnection(IDbConnection connection)
    {
        var provider = connection.GetType().Namespace.Split('.').Last();
        var poolKey = $"{provider}_{connection.ConnectionString}";
        if (_connectionPools.TryGetValue(poolKey, out var pool))
        {
            lock (pool)
            {
                if (connection.CanContinueReading())
                {
                    pool.Enqueue(connection);
                }
                else
                {
                    connection.Dispose();
                }
            }
        }
    }

    public override string ToString()
    {
        return $"ConnectionManager: Pools - {string.Join(", ", _connectionPools.Keys)}";
    }

    public void InitializeFromConfiguration(string configSource)
    {
        // Logic to load configuration from the specified source
    }

    private void InitializeProviders()
    {
        var providers = new[]
        {
            "MySql.Data.MySqlClient",
            "Npgsql",
            "System.Data.SQLite"
        };

        foreach (var provider in providers)
        {
            var factoryType = Type.GetType($"{provider}.DbProviderFactory");
            if (factoryType != null && typeof(DbProviderFactory).IsAssignableFrom(factoryType))
            {
                _factories[provider] = (DbProviderFactory)Activator.CreateInstance(factoryType);
            }
        }
    }

    private static bool CanContinueReading(this DbConnection connection)
    {
        try
        {
            return !connection.State.Equals(ConnectionState.Closed);
        }
        catch (Exception ex)
        {
            // Log the exception and handle accordingly
            Console.WriteLine($"Error checking connection state: {ex.Message}");
            return false;
        }
    }
}
