```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_CHAR_LENGTH 100

typedef struct Node {
    int value;
    struct SubNode* subList;
} Node;

typedef struct SubNode {
    char* strValue;
    double dblValue;
    struct NestedSubNode* nestedSubList;
    struct SubNode* next;
} SubNode;

typedef struct NestedSubNode {
    char* charArray;
    float floatValue;
    struct NestedSubNode* next;
} NestedSubNode;

void freeMemory(Node* nodes, int nodeCount) {
    for (int i = 0; i < nodeCount; i++) {
        SubNode* currentSub = nodes[i].subList;
        while (currentSub != NULL) {
            NestedSubNode* nestedCurrent = currentSub->nestedSubList;
            while (nestedCurrent != NULL) {
                free(nestedCurrent->charArray);
                free(nestedCurrent);
                nestedCurrent = nestedCurrent->next;
            }
            free(currentSub->strValue);
            free(currentSub);
            currentSub = currentSub->next;
        }
    }
    free(nodes);
}

Node* createNodes(int nodeCount, int subListSize, int nestedSubListSize, int valueRange) {
    if (nodeCount <= 0 || subListSize <= 0 || nestedSubListSize <= 0 || valueRange <= 0) {
        return NULL;
    }

    Node* nodes = malloc(nodeCount * sizeof(Node));
    if (nodes == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < nodeCount; i++) {
        nodes[i].value = rand() % valueRange + 1;

        nodes[i].subList = malloc(subListSize * sizeof(SubNode));
        if (nodes[i].subList == NULL) {
            freeMemory(nodes, i);
            fprintf(stderr, "Memory allocation failed.\n");
            return NULL;
        }

        for (int j = 0; j < subListSize; j++) {
            nodes[i].subList[j].strValue = malloc(MAX_CHAR_LENGTH * sizeof(char));
            if (nodes[i].subList[j].strValue == NULL) {
                freeMemory(nodes, i + 1);
                fprintf(stderr, "Memory allocation failed.\n");
                return NULL;
            }

            nodes[i].subList[j].dblValue = ((double)rand() / RAND_MAX) * 2.0 - 1.0;
            nodes[i].subList[j].nestedSubList = malloc(nestedSubListSize * sizeof(NestedSubNode));
            if (nodes[i].subList[j].nestedSubList == NULL) {
                freeMemory(nodes, i + 1);
                fprintf(stderr, "Memory allocation failed.\n");
                return NULL;
            }

            for (int k = 0; k < nestedSubListSize; k++) {
                nodes[i].subList[j].nestedSubList[k].charArray = malloc(MAX_CHAR_LENGTH * sizeof(char));
                if (nodes[i].subList[j].nestedSubList[k].charArray == NULL) {
                    freeMemory(nodes, i + 1);
                    fprintf(stderr, "Memory allocation failed.\n");
                    return NULL;
                }

                snprintf(nodes[i].subList[j].nestedSubList[k].charArray, MAX_CHAR_LENGTH, "%d", rand() % 1000);
                nodes[i].subList[j].nestedSubList[k].floatValue = ((float)rand() / RAND_MAX) * 2.0 - 1.0;

                if (k < nestedSubListSize - 1) {
                    nodes[i].subList[j].nestedSubList[k].next = &nodes[i].subList[j].nestedSubList[k + 1];
                } else {
                    nodes[i].subList[j].nestedSubList[k].next = NULL;
                }
            }

            if (j < subListSize - 1) {
                nodes[i].subList[j].next = &nodes[i].subList[j + 1];
            } else {
                nodes[i].subList[j].next = NULL;
            }
        }
    }

    return nodes;
}
