    while (stack.length > 0) {
        let node = stack.pop();

        if (node.nodeType === Node.ELEMENT_NODE && testFunc(node)) {
            result.push(node);
        }

        for (let i = node.children.length - 1; i >= 0; i--) {
            stack.push(node.children[i]);
        }
    }

    return result;
}
