```cpp
#include <iostream>
#include <thread>
#include <random>
#include <vector>
#include <atomic>

namespace RandomService {
    class ThreadSafeGenerator {
        static thread_local std::mt19937_64 rng;
        static uint64_t SeedFromThreadID();

    public:
        ThreadSafeGenerator() = default;
        ~ThreadSafeGenerator() noexcept = default;

        static uint64_t GetSeedForThread();
        static double GenerateRandomDouble();
        static int GenerateRandomInt(int min, int max);
    };

    thread_local std::mt19937_64 ThreadSafeGenerator::rng = std::mt19937_64();

    uint64_t ThreadSafeGenerator::SeedFromThreadID() {
        return std::hash<std::thread::id>{}(std::this_thread::get_id());
    }

    uint64_t ThreadSafeGenerator::GetSeedForThread() {
        return SeedFromThreadID();
    }

    double ThreadSafeGenerator::GenerateRandomDouble() {
        return rng() / (double)(rng.max() + 1);
    }

    int ThreadSafeGenerator::GenerateRandomInt(int min, int max) {
        std::uniform_int_distribution<int> dist(min, max);
        return dist(rng);
    }
}

void RunThreadFunction() {
    for (int i = 0; i < 1000; ++i) {
        double randomDouble = RandomService::ThreadSafeGenerator::GenerateRandomDouble();
        int randomInt = RandomService::ThreadSafeGenerator::GenerateRandomInt(1, 100);
        std::cout << "Thread ID: " << std::this_thread::get_id() 
                  << ", Double: " << randomDouble 
                  << ", Int: " << randomInt << std::endl;
    }
}

int main() {
    std::vector<std::thread> threads;
    for (int i = 0; i < 10; ++i) {
        threads.emplace_back(RunThreadFunction);
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
