// Node.js program for dynamic module loading, execution, and error handling

const fs = require('fs');
const path = require('path');

function loadModule(modulePath) {
  try {
    const module = require(modulePath);
    return { success: true, module };
  } catch (error) {
    console.error(`Failed to load module ${modulePath}:`, error);
    return { success: false, module: null };
  }
}

function executeModules(sequence, context) {
  const loadedModules = {};
  sequence.forEach(modulePath => {
    if (!loadedModules[modulePath]) {
      const moduleResult = loadModule(modulePath);
      if (moduleResult.success) {
        try {
          Object.assign(context, moduleResult.module.execute(context));
          console.log(`Executed ${modulePath}`);
        } catch (error) {
          console.error(`Failed to execute module ${modulePath}:`, error);
        }
        loadedModules[modulePath] = true;
      }
    }
  });
}

// Example usage:
const sequence = ['path/to/module1.js', 'path/to/module2.js'];
const context = {};
executeModules(sequence, context);
