#include <tiffio.h>
#include <stdio.h>

typedef struct {
    int bitsPerSample;
    int samplesPerPixel;
} ImageInfo;

ImageInfo parseTIFF(const char* filePath) {
    FILE* file = fopen(filePath, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open TIFF file: %s\n", filePath);
        return (ImageInfo){-1, -1};
    }

    tdata_t data;
    uint32_t width, height, samplesPerPixel, bitsPerSample;

    Tiff* tif = TIFFOpen(filePath, "r");
    if (!tif) {
        fclose(file);
        fprintf(stderr, "Failed to open TIFF file: %s\n", filePath);
        return (ImageInfo){-1, -1};
    }

    TIFFGetField(tif, TIFFTAG_IMAGEWIDTH, &width);
    TIFFGetField(tif, TIFFTAG_IMAGELENGTH, &height);
    TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel);
    TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bitsPerSample);

    fclose(file);
    TIFFClose(tif);

    ImageInfo info = {bitsPerSample, samplesPerPixel};
    return info;
}
