// Asynchronous reduce implementation in JavaScript

function asyncReduce(numbers, initialValue, callback) {
  const reducer = (acc, value, index, array) => {
    if (index === array.length - 1) {
      Promise.resolve().then(() => {
        try {
          acc = callback(acc, value);
          resolve(acc);
        } catch (error) {
          reject(error);
        }
      });
    } else {
      Promise.resolve().then(() => {
        acc = callback(acc, value);
        reducer(acc, array[index + 1], index + 1, array);
      });
    }
  };

  return new Promise((resolve, reject) => {
    try {
      reducer(initialValue, numbers[0], 0, numbers);
    } catch (error) {
      reject(error);
    }
  });
}

// Example usage:
const numbers = [1, 2, 3, 4, 5];
asyncReduce(numbers, 0, (acc, num) => acc + num)
  .then(result => console.log('Reduced value:', result))
  .catch(error => console.error('Error during reduction:', error));
