<?php

class OAuth2Authenticator {
    private $client;
    private $accessToken;
    private $userInfo;
    private $rateLimitCounter;

    public function __construct($providerConfig) {
        // Initialize the OAuth client using provider configuration
        $this->client = new League\OAuth2\Client\Provider\GenericProvider([
            'clientId'                => $providerConfig['clientId'],
            'clientSecret'            => $providerConfig['clientSecret'],
            'redirectUri'             => $providerConfig['redirectUri'],
            'urlAuthorize'          => $providerConfig['urlAuthorize'],
            'urlAccessToken'        => $providerConfig['urlAccessToken'],
            'urlResourceOwnerDetails' => $providerConfig['urlResourceOwnerDetails']
        ]);
    }

    public function authenticate() {
        // Check if session is already authenticated
        if (isset($_SESSION['accessToken'])) {
            return true;
        }

        // Handle OAuth flow and store access token in session
        try {
            // Check rate limit before proceeding
            if ($this->rateLimitExceeded()) {
                throw new Exception('Rate limit exceeded. Please try again later.');
            }

            // Redirect to authorization URL
            $authorizationUrl = $this->client->getAuthorizationUrl();
            $_SESSION['oauth2state'] = $this->client->getState();

            header('Location: ' . $authorizationUrl);
            exit;

            // Handle redirect back from provider
            if ($_GET['state'] !== $_SESSION['oauth2state']) {
                unset($_SESSION['oauth2state']);
                throw new Exception('Invalid state parameter');
            }

            $token = $this->client->getAccessToken('authorization_code', [
                'code' => $_GET['code']
            ]);

            // Store access token securely in session
            $_SESSION['accessToken'] = $token->getToken();
        } catch (Exception $e) {
            // Log failed authentication attempt
            error_log('Authentication failed: ' . $e->getMessage());
            return false;
        }

        // Retrieve user information using the access token
        try {
            $this->userInfo = $this->client->getResourceOwner($token);
        } catch (Exception $e) {
            // Log failed retrieval of user info
            error_log('Failed to retrieve user info: ' . $e->getMessage());
            unset($_SESSION['accessToken']);
            return false;
        }

        // Reset rate limit counter on successful authentication
        $this->rateLimitCounter = 0;

        // Log successful authentication attempt
        error_log('Authentication succeeded for user: ' . $this->userInfo->getEmail());

        return true;
    }

    public function getUserInfo() {
        return $this->userInfo;
    }

    private function rateLimitExceeded() {
        if (!isset($_SESSION['rateLimitCounter'])) {
            $_SESSION['rateLimitCounter'] = 0;
        }

        // Increment rate limit counter
        $_SESSION['rateLimitCounter']++;

        // Set rate limit threshold
        $threshold = 10;

        return $_SESSION['rateLimitCounter'] >= $threshold;
    }
}

// Example usage:
$providerConfig = [
    'clientId' => 'your-client-id',
    'clientSecret' => 'your-client-secret',
    'redirectUri' => 'http://example.com/callback.php',
    'urlAuthorize' => 'https://oauth-provider.com/authorize',
    'urlAccessToken' => 'https://oauth-provider.com/token',
    'urlResourceOwnerDetails' => 'https://oauth-provider.com/userinfo'
];

$authenticator = new OAuth2Authenticator($providerConfig);
if ($authenticator->authenticate()) {
    $userInfo = $authenticator->getUserInfo();
    echo "Welcome, " . htmlspecialchars($userInfo->getEmail());
} else {
    echo "Authentication failed.";
}
?>
