class RandomNumberGenerator {
private:
    mutable std::mt19937 gen;
    std::mutex mtx;

public:
    RandomNumberGenerator(unsigned int seed) : gen(seed) {}

    // Generate a uniform random number between min and max
    double generateUniform(double min, double max) {
        std::lock_guard<std::mutex> lock(mtx);
        return std::uniform_real_distribution<>(min, max)(gen);
    }

    // Generate a normal (Gaussian) random number with mean and stddev
    double generateNormal(double mean, double stddev) {
        std::lock_guard<std::mutex> lock(mtx);
        return std::normal_distribution<>(mean, stddev)(gen);
    }

    // Generate an exponential random number with lambda
    double generateExponential(double lambda) {
        std::lock_guard<std::mutex> lock(mtx);
        return std::exponential_distribution<>(lambda)(gen);
    }
};

