    public void ProcessUserTransactions(List<string> transactionIds, Dictionary<string, TransactionUpdate> updates)
    {
        var cache = new MemoryCache();
        var riskAssessmentClient = new HttpClient { Timeout = TimeSpan.FromMilliseconds(_riskAssessmentApiTimeout) };
        var rateLimiter = new RateLimiter(_rateLimitPeriodMilliseconds);
        var batchProcessor = new BatchProcessor(_batchProcessingMaxTransactions, _batchProcessingMaxIntervalMilliseconds);

        foreach (var transactionId in transactionIds)
        {
            if (!updates.ContainsKey(transactionId))
                continue;

            var update = updates[transactionId];
            var currentStatus = GetTransactionStatus(cache, transactionId);
            var riskLevel = AssessRisk(update.UserId, transactionId, riskAssessmentClient, rateLimiter);

            if (rateLimiter.IsRateLimited(update.TransactionId))
            {
                LogError(transactionId, "Rate limit exceeded");
                continue;
            }

            if (batchProcessor.IsBatchLimitReached())
            {
                batchProcessor.ProcessBatch();
            }

            var newStatus = ValidateAndUpdateTransaction(currentStatus, update, riskLevel, cache);
            if (!newStatus)
            {
                LogError(transactionId, "Validation error or database issue");
                continue;
            }

            batchProcessor.AddToBatch(new TransactionUpdateLog
            {
                Timestamp = DateTime.Now,
                TransactionId = transactionId,
                UpdatedFields = JsonConvert.SerializeObject(update),
                Status = newStatus ? "Success" : "Failure"
            });
        }

        batchProcessor.ProcessBatch();
    }

    private string GetTransactionStatus(MemoryCache cache, string transactionId)
    {
        if (cache.Contains(transactionId))
            return cache.Get(transactionId) as string;

        var status = LoadTransactionStatusFromDatabase(transactionId);
        cache.Add(transactionId, status, DateTimeOffset.UtcNow.AddMinutes(10)); // Cache for 10 minutes
        return status;
    }

    private async Task<int> AssessRisk(string userId, string transactionId, HttpClient client, RateLimiter rateLimiter)
    {
        if (rateLimiter.IsRateLimited(userId))
        {
            LogError(transactionId, "User risk assessment rate limit exceeded");
            return -1;
        }

        var response = await client.GetAsync($"https://riskapi.com/assess?userId={userId}");
        if (!response.IsSuccessStatusCode)
        {
            LogError(transactionId, $"Risk assessment API failed with status code: {response.StatusCode}");
            return -1;
        }

        return await response.Content.ReadAsAsync<int>();
    }

    private bool ValidateAndUpdateTransaction(string currentStatus, TransactionUpdate update, int riskLevel, MemoryCache cache)
    {
        if (riskLevel == -1) // Risk assessment failure
            return false;

        switch (currentStatus)
        {
            case "Pending":
                if (update.Status == "Approved" && IsHighRisk(riskLevel))
                    return false;
