class RateLimiter
{
    private readonly int _periodMilliseconds;
    private readonly Dictionary<string, DateTimeOffset> _lastRequestTimes;

    public RateLimiter(int periodMilliseconds)
    {
        _periodMilliseconds = periodMilliseconds;
        _lastRequestTimes = new Dictionary<string, DateTimeOffset>();
    }

    public bool IsRateLimited(string key)
    {
        if (_lastRequestTimes.ContainsKey(key))
        {
            var timeElapsed = DateTime.UtcNow - _lastRequestTimes[key];
            return timeElapsed.TotalMilliseconds < _periodMilliseconds;
        }

        _lastRequestTimes[key] = DateTime.UtcNow;
        return false;
    }
}

class BatchProcessor
{
    private readonly int _maxTransactions;
    private readonly int _maxIntervalMilliseconds;
    private readonly Queue<TransactionUpdateLog> _batch;

    public BatchProcessor(int maxTransactions, int maxIntervalMilliseconds)
    {
        _maxTransactions = maxTransactions;
        _maxIntervalMilliseconds = maxIntervalMilliseconds;
        _batch = new Queue<TransactionUpdateLog>();
    }

    public bool IsBatchLimitReached()
    {
        return _batch.Count >= _maxTransactions;
    }

    public void AddToBatch(TransactionUpdateLog log)
    {
        if (_batch.Count < _maxTransactions)
            _batch.Enqueue(log);
    }

    public void ProcessBatch()
    {
        var batch = new List<TransactionUpdateLog>();
        while (_batch.Count > 0 && DateTime.UtcNow - _batch.Peek().Timestamp.TotalMilliseconds < _maxIntervalMilliseconds)
        {
            batch.Add(_batch.Dequeue());
        }

        if (batch.Count > 0)
        {
            // Simulate batch processing
            Console.WriteLine($"Processing {batch.Count} transactions in a batch.");
        }
    }
}
