using System;
using System.Collections.Concurrent;
using System.Data;
using System.Data.SqlClient;
using System.Diagnostics;
using System.Linq;
using System.Threading.Tasks;

public class StoredProcedureService<T> where T : new()
{
    private readonly string _connectionString;
    private readonly ConcurrentDictionary<string, Func<SqlConnection, SqlCommand, T>> _procedureCache = new();
    private readonly IExternalLogger _logger;

    public StoredProcedureService(string connectionString, IExternalLogger logger)
    {
        _connectionString = connectionString;
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task<List<T>> ExecuteAsync(string procedureName, object parameters)
    {
        var cacheKey = $"{procedureName}_{JsonConvert.SerializeObject(parameters)}";
        if (!_procedureCache.TryGetValue(cacheKey, out var procedure))
        {
            procedure = CreateProcedureDelegate(procedureName);
            _procedureCache.TryAdd(cacheKey, procedure);
        }

        using (var connection = new SqlConnection(_connectionString))
        using (var command = new SqlCommand(procedureName, connection) { CommandType = CommandType.StoredProcedure })
        {
            foreach (var param in parameters.GetType().GetProperties())
            {
                command.Parameters.Add(new SqlParameter(param.Name, param.GetValue(parameters)));
            }

            await _logger.LogExecutionAsync(procedureName, parameters);
            var results = await Task.Run(() => procedure(connection, command));
            return results;
        }
    }

    private Func<SqlConnection, SqlCommand, T> CreateProcedureDelegate(string procedureName)
    {
        return (connection, command) =>
        {
            connection.Open();
            using (var reader = command.ExecuteReader())
            {
                var result = new List<T>();
                while (reader.Read())
                {
                    var item = new T();
                    foreach (var prop in typeof(T).GetProperties())
                    {
                        if (reader.HasColumn(prop.Name))
                            prop.SetValue(item, Convert.ChangeType(reader[prop.Name], prop.PropertyType));
                    }
                    result.Add(item);
                }
                return result;
            }
        };
    }

    public async Task CheckHealthAsync()
    {
        try
        {
            using (var connection = new SqlConnection(_connectionString))
            {
                await connection.OpenAsync();
                _logger.LogHealthCheckSuccess();
            }
        }
        catch (Exception ex)
        {
            _logger.LogHealthCheckFailure(ex);
        }
    }
}

public interface IExternalLogger
{
    Task LogExecutionAsync(string procedureName, object parameters);
    Task LogHealthCheckSuccess();
    Task LogHealthCheckFailure(Exception exception);
}
