struct DirectoryManager {
    path: PathBuf,
    cleanup_interval: Duration,
}

impl DirectoryManager {
    fn new(custom_prefix: Option<&str>) -> Result<DirectoryManager, io::Error> {
        let mut env_path = env::var("MY_DIR_PATH").ok().and_then(|p| p.into());
        if env_path.is_none() {
            let prefix = custom_prefix.unwrap_or("my_dir");
            env_path = Some(format!("/tmp/{}-{}", prefix, Instant::now().duration_since(UNIX_EPOCH).as_secs()));
            env::set_var("MY_DIR_PATH", &env_path);
        }

        let path = PathBuf::from(env_path.unwrap());
        if !path.exists() {
            fs::create_dir_all(&path)?;
        }

        Ok(DirectoryManager {
            path,
            cleanup_interval: Duration::from_secs(600),
        })
    }

    fn start_cleanup_thread(&self) {
        let manager = Arc::new(Mutex::new(self.clone()));
        thread::spawn(move || loop {
            std::thread::sleep(manager.lock().unwrap().cleanup_interval);
            manager.lock().unwrap().cleanup();
        });
    }

    fn cleanup(&self) {
        // Simulated cleanup logic
        println!("Cleaning up directory: {:?}", self.path);
        // Add actual cleanup code here, e.g., removing files and directories
    }
}

fn main() -> Result<(), io::Error> {
    let manager = DirectoryManager::new(None)?;
    manager.start_cleanup_thread();
    // Main application logic goes here

    Ok(())
}
