impl CompilerOrchestrationTool {
    fn new(files: Vec<File>) -> Self {
        CompilerOrchestrationTool {
            files,
            cache: Cache::new(),
        }
    }

    async fn compile_files(&self) -> Result<(), Rejection> {
        let mut handles = vec![];

        for file in &self.files {
            let cache = self.cache.clone();
            handles.push(tokio::spawn(async move {
                if let Some(result) = cache.get(&file.path).await {
                    match result {
                        Ok(_) => return,
                        Err(_) => {}
                    }
                }

                let result = file.fetch_from_vcs().await.and_then(|content| {
                    File {
                        path: file.path.clone(),
                        language: file.language,
                    }
                    .compile()
                });

                cache.set(file.path.clone(), result).await;
            }));
        }

        for handle in handles {
            handle.await?;
        }

        Ok(())
    }
}

