```csharp
using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

public class SecureCipherService : IDisposable
{
    private readonly HttpClient _httpClient;
    private readonly ConcurrentDictionary<string, (byte[], DateTimeOffset)> _cache;
    private readonly string _tokenEndpoint;
    private readonly string _clientId;
    private readonly string _clientSecret;
    private readonly TimeSpan _tokenRefreshInterval;
    private DateTime _lastTokenRefresh;

    public SecureCipherService(string tokenEndpoint, string clientId, string clientSecret, TimeSpan tokenRefreshInterval)
    {
        _httpClient = new HttpClient();
        _cache = new ConcurrentDictionary<string, (byte[], DateTimeOffset)>();
        _tokenEndpoint = tokenEndpoint;
        _clientId = clientId;
        _clientSecret = clientSecret;
        _tokenRefreshInterval = tokenRefreshInterval;
        _lastTokenRefresh = DateTime.MinValue;

        // Initialize the cache and start a background task for token refresh
        var initialToken = FetchNewToken();
        _cache.TryAdd("CurrentKey", (initialToken, DateTimeOffset.UtcNow));
        Task.Run(() => RefreshTokenPeriodically());
    }

    public async Task<byte[]> DecryptMessageAsync(byte[] ciphertext, byte[] key, byte[] iv, long offset, CancellationToken cancellationToken)
    {
        if (!ValidateCacheAndRefreshToken(ciphertext))
            throw new InvalidOperationException("Invalid decryption keys or tokens.");

        using (Aes aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

            // Create a memory stream with the ciphertext and specify the offset
            using (MemoryStream msDecrypt = new MemoryStream(ciphertext, (int)offset))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    using (MemoryStream msOutput = new MemoryStream())
                    {
                        await csDecrypt.CopyToAsync(msOutput, cancellationToken);
                        return msOutput.ToArray();
                    }
                }
            }
        }
    }

    private bool ValidateCacheAndRefreshToken(byte[] ciphertext)
    {
        if (!_cache.TryGetValue("CurrentKey", out var cachedData) || DateTimeOffset.UtcNow > cachedData.Item2 + _tokenRefreshInterval)
        {
            byte[] newKey = FetchNewToken();
            _cache.TryUpdate("CurrentKey", (newKey, DateTimeOffset.UtcNow), cachedData);
            return false;
        }
        return true;
    }

    private async Task<byte[]> FetchNewToken()
    {
        try
        {
            var content = new FormUrlEncodedContent(new[]
            {
                new KeyValuePair<string, string>("grant_type", "client_credentials"),
                new KeyValuePair<string, string>("client_id", _clientId),
                new KeyValuePair<string, string>("client_secret", _clientSecret)
            });

            HttpResponseMessage response = await _httpClient.PostAsync(_tokenEndpoint, content);
            if (!response.IsSuccessStatusCode)
            {
                throw new Exception($"Failed to fetch token: {response.ReasonPhrase}");
            }

            var json = await response.Content.ReadAsStringAsync();
            var tokenResponse = Newtonsoft.Json.Linq.JObject.Parse(json);
            byte[] tokenBytes = Encoding.UTF8.GetBytes(tokenResponse["access_token"].ToString());
            return tokenBytes;
        }
        catch (Exception ex)
        {
            // Log the error and retry
            Console.WriteLine($"Token fetch failed: {ex.Message}");
            return await FetchNewToken();
        }
    }

    private async Task RefreshTokenPeriodically()
    {
        while (true)
        {
            await Task.Delay(_tokenRefreshInterval);
            byte[] newKey = FetchNewToken();
            _cache.TryUpdate("CurrentKey", (newKey, DateTimeOffset.UtcNow), _cache["CurrentKey"]);
        }
    }

    public void Dispose()
    {
        _httpClient.Dispose();
    }
}
