// Function to load a dynamic resource bundle from a configurable file path
ErrorCode loadResourceBundle(const char* filePath, const char* format, ResourceBundle** bundle) {
    // Load resource bundle based on the specified format
    if (strcmp(format, "JSON") == 0) {
        *bundle = loadJsonResource(filePath);
    } else if (strcmp(format, "XML") == 0) {
        *bundle = loadXmlResource(filePath);
    } else if (strcmp(format, "BINARY") == 0) {
        *bundle = loadBinaryResource(filePath);
    } else {
        return ERROR_INVALID_FORMAT;
    }

    if (*bundle == NULL) {
        return ERROR_MEMORY_ALLOCATION_FAILED;
    }

    return ERROR_NONE;
}

// Function to unload a resource bundle
void unloadResourceBundle(ResourceBundle* bundle) {
    // Free the memory allocated for the resource bundle
    free(bundle);
}

// Function to update a part of the resource bundle without restarting the application
ErrorCode updateResourceBundle(const char* filePath, const char* format, ResourceBundle** bundle) {
    // Unload the current resource bundle
    unloadResourceBundle(*bundle);

    // Load the updated resource bundle
    ErrorCode errorCode = loadResourceBundle(filePath, format, bundle);
    if (errorCode != ERROR_NONE) {
        return errorCode;
    }

    return ERROR_NONE;
