public class RandomStringGenerator {
    private static final String DEFAULT_API_URL = "https://api.example.com/config";
    private static final int DEFAULT_STRING_LENGTH = 16;
    private static final Set<Character> DEFAULT_CHARACTERS = new HashSet<>(Arrays.asList('a', 'b', 'c', 'd', 'e'));

    private static final Map<String, String> HASH_ALGORITHMS = new HashMap<>();
    static {
        HASH_ALGORITHMS.put("bcrypt", "BCRYPT");
        HASH_ALGORITHMS.put("scrypt", "SCRYPT");
        HASH_ALGORITHMS.put("argon2", "ARGON2");
    }

    private final HttpClient httpClient;
    private final Cache<String, String> cache;

    public RandomStringGenerator(HttpClient httpClient, Cache<String, String> cache) {
        this.httpClient = httpClient;
        this.cache = cache;
    }

    public String generateRandomString(int length, Set<Character> characters, String hashAlgorithm) throws Exception {
        // Fetch configuration from external API
        String config = fetchConfigFromApi();

        // Deserialize object to get string length and allowed characters
        RandomStringConfig randomStringConfig = deserializeObject(config);

        // Use default values if not provided
        length = (length <= 0) ? DEFAULT_STRING_LENGTH : length;
        characters = (characters == null || characters.isEmpty()) ? DEFAULT_CHARACTERS : new HashSet<>(characters);

        // Generate random string
        String randomString = generateRandomString(length, characters);

        // Hash the string using selected algorithm
        String hashedString = hashString(randomString, hashAlgorithm);

        return hashedString;
    }

    private String fetchConfigFromApi() throws IOException {
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(DEFAULT_API_URL))
                .GET()
                .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

        if (response.statusCode() != 200) {
            throw new IOException("Failed to fetch configuration from API");
        }

        return response.body();
    }

    @SuppressWarnings("unchecked")
    private RandomStringConfig deserializeObject(String config) throws Exception {
        ByteArrayInputStream bis = new ByteArrayInputStream(Base64.getDecoder().decode(config));
        ObjectInputStream ois = new ObjectInputStream(bis);
        Object obj = ois.readObject();
        ois.close();

        return (RandomStringConfig) obj;
    }

    private String generateRandomString(int length, Set<Character> characters) {
        Random random = ThreadLocalRandom.current();
        StringBuilder sb = new StringBuilder(length);

        for (int i = 0; i < length; i++) {
            char ch = characters.toArray(new Character[0])[random.nextInt(characters.size())];
            sb.append(ch);
        }

        return sb.toString();
    }

    private String hashString(String string, String algorithm) throws Exception {
        if (!HASH_ALGORITHMS.containsKey(algorithm)) {
            throw new IllegalArgumentException("Invalid hashing algorithm");
        }

        byte[] salt = generateSalt();
        MessageDigest md = MessageDigest.getInstance(HASH_ALGORITHMS.get(algorithm));
        md.update(salt);
        byte[] hashBytes = md.digest(string.getBytes());

        return Base64.getEncoder().encodeToString(hashBytes) + "$" + Base64.getEncoder().encodeToString(salt);
    }

    private byte[] generateSalt() {
        SecureRandom random = new SecureRandom();
        byte[] salt = new byte[16];
        random.nextBytes(salt);
        return salt;
    }
}
