        auto cachedEntry = findCachedEntry(selector);

        if (cachedEntry != cache.end()) {
            for (auto state : cachedEntry->states) {
                (*stateList)[lastStateIndex].next = new State(state->value, nullptr);
                lastStateIndex++;
            }
            return;
        }

        vector<State*> matchingStates = findMatchingStates(fsa, selector);

        for (auto state : matchingStates) {
            (*stateList)[lastStateIndex].next = new State(state->value, nullptr);
            lastStateIndex++;
        }

        cacheEntry.cache.push_back({selector, matchingStates});
    }

