using System.Threading.Tasks;
using NLog;

public class XmlParser
{
    private static readonly Logger Logger = LogManager.GetCurrentClassLogger();
    private static readonly Cache<string, XPathNavigator> cache = new LRUCache<string, XPathNavigator>(100);

    public async Task<XPathNavigator> ParseXmlAsync(string url, string xpath)
    {
        try
        {
            var startTime = DateTime.Now;
            var cached = cache.Get(url);
            if (cached != null)
            {
                Logger.Info("Cache hit");
                return cached.SelectSingleNode(xpath);
            }

            var request = WebRequest.CreateHttp(url);
            using (var response = await request.GetResponseAsync() as HttpWebResponse)
            {
                using (var stream = response.GetResponseStream())
                using (var reader = new StreamReader(stream))
                {
                    var xmlDoc = new XPathDocument(reader);
                    var navigator = xmlDoc.CreateNavigator();

                    var result = navigator.SelectSingleNode(xpath);
                    if (result == null)
                    {
                        throw new Exception($"No element found with XPath '{xpath}'");
                    }

                    if (navigator.SelectNodes(xpath).Count > 1)
                    {
                        throw new Exception($"Multiple elements found with XPath '{xpath}'");
                    }

                    cache.Add(url, navigator);
                    Logger.Info("Cache miss and successful fetch from API");
                    return result;
                }
            }
        }
        catch (WebException ex) when ((ex.Status == WebExceptionStatus.Timeout || ex.Status == WebExceptionStatus.ProtocolError))
        {
            Logger.Error($"API call timed out or protocol error: {ex.Message}");
            await Task.Delay(1000); // Exponential backoff
            return await ParseXmlAsync(url, xpath);
        }
        catch (Exception ex)
        {
            Logger.Error($"Failed to parse XML: {ex.Message}");
            throw;
        }
    }

