public class LRUCache<TKey, TValue> : IDisposable
{
    private readonly Dictionary<TKey, LinkedListNode<KeyValuePair<TKey, TValue>>> _cache = new();
    private readonly LinkedList<KeyValuePair<TKey, TValue>> _list = new();
    private readonly int _capacity;

    public LRUCache(int capacity)
    {
        _capacity = capacity;
    }

    public TValue Get(TKey key)
    {
        if (_cache.TryGetValue(key, out var node))
        {
            _list.Remove(node);
            _list.AddLast(node);
            return node.Value.Value;
        }
        return default;
    }

    public void Add(TKey key, TValue value)
    {
        if (_cache.ContainsKey(key))
        {
            Get(key); // Update the position
        }
        else if (_cache.Count == _capacity)
        {
            var first = _list.First;
            _cache.Remove(first.Value.Key);
            _list.RemoveFirst();
        }

        var node = new LinkedListNode<KeyValuePair<TKey, TValue>>(new KeyValuePair<TKey, TValue>(key, value));
        _cache[key] = node;
        _list.AddLast(node);
    }

    public void Dispose()
    {
        _cache.Clear();
        _list.Clear();
    }
}

