import json
from flask import Flask, request, jsonify
from threading import Lock
from functools import lru_cache

app = Flask(__name__)
entity_factories = {}
lock = Lock()

class JsonSerializable:
    @classmethod
    def from_json(cls, data):
        return cls(**data)

    def to_json(self):
        return json.dumps(self.__dict__)

def register_entity(entity_type, factory_function):
    with lock:
        entity_factories[entity_type] = factory_function

@app.route('/load_entities', methods=['POST'])
def load_entities():
    try:
        data = request.json
        entities = [JsonSerializable.from_json(item) for item in data]
        return jsonify([e.to_json() for e in entities]), 200
    except Exception as e:
        app.logger.error(f"Error loading entities: {e}")
        return jsonify({"error": str(e)}), 500

@app.route('/entities', methods=['GET'])
def get_entities():
    try:
        entity_type = request.args.get('type')
        if entity_type not in entity_factories:
            return jsonify({"error": f"Entity type '{entity_type}' not found"}), 404

        factory_function = entity_factories[entity_type]
        instance = factory_function()
        return jsonify(instance.to_json()), 200
    except Exception as e:
        app.logger.error(f"Error retrieving entity: {e}")
        return jsonify({"error": str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)
