const fs = require('fs');
const path = require('path');
const vm = require('vm');
const { promisify } = require('util');

const readFileAsync = promisify(fs.readFile);

async function loadModules(configPath) {
  const config = JSON.parse(await readFileAsync(configPath, 'utf8'));
  const context = {};
  const loadedModules = new Set();

  for (const moduleConfig of config.modules) {
    if (!moduleConfig.condition || process.env[moduleConfig.condition]) {
      try {
        if (!loadedModules.has(moduleConfig.name)) {
          await loadModule(moduleConfig.path, context);
          loadedModules.add(moduleConfig.name);
        }
        if (typeof moduleConfig.execute === 'function') {
          await moduleConfig.execute(context);
        }
      } catch (error) {
        console.error(`Error loading or executing module ${moduleConfig.name}:`, error);
      }
    }
  }
}

async function loadModule(modulePath, context) {
  const moduleCode = await readFileAsync(modulePath, 'utf8');
  const script = new vm.Script(moduleCode, { filename: modulePath });
  script.runInNewContext(context);
}

// Example usage
loadModules('./config.json').then(() => {
  console.log('All modules loaded and executed successfully.');
}).catch((error) => {
  console.error('Error during module loading:', error);
});
