public class ConfigLoader
{
    private readonly HttpClient _httpClient;
    private readonly string _xmlUrl;
    private XDocument _configXml;

    public ConfigLoader(string xmlUrl)
    {
        _httpClient = new HttpClient();
        _xmlUrl = xmlUrl;
    }

    public async Task LoadConfigAsync()
    {
        try
        {
            var response = await _httpClient.GetAsync(_xmlUrl);
            response.EnsureSuccessStatusCode();
            _configXml = XDocument.Load(await response.Content.ReadAsStreamAsync());
        }
        catch (HttpRequestException ex)
        {
            // Log error and retry logic here
            throw;
        }
    }

    public string DecryptCiphertextAsync(string ciphertext, byte[] key, byte[] iv)
    {
        using var aes = Aes.Create();
        aes.Key = key;
        aes.IV = iv;
        aes.Mode = CipherMode.CBC;

        using var decryptor = aes.CreateDecryptor();
        using var memoryStream = new MemoryStream(Convert.FromBase64String(ciphertext));
        using var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read);
        using var reader = new StreamReader(cryptoStream);

        return reader.ReadToEnd();
    }
}

public class ConfigManager
{
    private readonly ConfigLoader _configLoader;

    public ConfigManager(string xmlUrl)
    {
        _configLoader = new ConfigLoader(xmlUrl);
    }

    public async Task LoadConfigurationAsync()
    {
        await _configLoader.LoadConfigAsync();
    }

    public string GetDecryptedValue(string key, byte[] aesKey, byte[] aesIv)
    {
        var encryptedValue = (string)_configLoader._configXml.Element("Configuration").Element(key).Attribute("value");
        return _configLoader.DecryptCiphertextAsync(encryptedValue, aesKey, aesIv);
