using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;

public class GraphQLClient
{
    private readonly HttpClient _httpClient;

    public GraphQLClient(HttpClient httpClient)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
    }

    public async Task<GraphQLResponse> ExecuteQueryAsync(string query, Dictionary<string, object> variables)
    {
        if (string.IsNullOrEmpty(query))
            throw new ArgumentException("The query cannot be null or empty.", nameof(query));

        if (variables == null)
            throw new ArgumentNullException(nameof(variables));

        var requestContent = CreateRequestContent(query, variables);

        using (var response = await _httpClient.PostAsync("/graphql", requestContent))
        {
            response.EnsureSuccessStatusCode();

            var content = await response.Content.ReadAsStringAsync();
            return new GraphQLResponse(content);
        }
    }

    private HttpContent CreateRequestContent(string query, Dictionary<string, object> variables)
    {
        var jsonContent = new
        {
            query = query,
            variables = variables
        };

        return new StringContent(Newtonsoft.Json.JsonConvert.SerializeObject(jsonContent), System.Text.Encoding.UTF8, "application/json");
    }
}

public class GraphQLResponse
{
    public string Data { get; }

    public GraphQLResponse(string data)
    {
        Data = data;
    }
}
