class OrderSummaryProcessor:
    def __init__(self, validation_plugins=None):
        self.validation_plugins = validation_plugins or []
        self.cached_results = {}
        self.executor = ThreadPoolExecutor()

    async def process_json_file(self, file_path, criteria, output_format):
        try:
            with open(file_path, 'r') as file:
                data = json.load(file)
        except json.JSONDecodeError:
            logging.error("Malformed JSON in the input file.")
            return

        filtered_orders = await self.filter_orders(data, criteria)
        summary = self.aggregate_data(filtered_orders)

        if output_format == 'CSV':
            self.output_csv(summary)
        elif output_format == 'PDF':
            self.output_pdf(summary)
        else:
            logging.warning(f"Unsupported output format: {output_format}")

    async def filter_orders(self, data, criteria):
        filtered = []
        for order in data['orders']:
            if await asyncio.to_thread(self.apply_criteria, order, criteria):
                filtered.append(order)
        return filtered

    @staticmethod
    def apply_criteria(order, criteria):
        for criterion, value in criteria.items():
            plugin = next((p for p in self.validation_plugins if p.name == criterion), None)
            if plugin:
                if not plugin.validate(order, value):
                    return False
            elif order.get(criterion) != value:
                return False
        return True

