int dns_server_count = 0;
pthread_mutex_t cache_lock;
struct sockaddr_in servers[MAX_DNS_SERVERS];

void init_dns_library(char* dns_servers[], int count) {
    for (int i = 0; i < count; i++) {
        struct sockaddr_in server;
        inet_pton(AF_INET, dns_servers[i], &server.sin_addr);
        server.sin_family = AF_INET;
        server.sin_port = htons(53);
        servers[i] = server;
        dns_server_count++;
    }
    pthread_mutex_init(&cache_lock, NULL);
}

void* resolve_dns(void* arg) {
    char* domain = (char*)arg;
    DNSRecord record;

    for (int i = 0; i < dns_server_count; i++) {
        int sock = socket(AF_INET, SOCK_DGRAM, 0);
        if (sock < 0) {
            perror("Socket creation failed");
            continue;
        }

        struct timeval timeout;
        timeout.tv_sec = TIMEOUT;
        timeout.tv_usec = 0;
        setsockopt(sock, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout));

        sendto(sock, domain, strlen(domain), 0, (struct sockaddr*)&servers[i], sizeof(servers[i]));
        socklen_t server_len = sizeof(servers[i]);
        recvfrom(sock, &record, sizeof(DNSRecord), 0, (struct sockaddr*)&servers[i], &server_len);

        close(sock);
        if (record.ttl > 0) {
            pthread_mutex_lock(&cache_lock);
            for (int j = 0; j < CACHE_SIZE; j++) {
                if (strcmp(cache[j].ip, record.ip) == 0) {
                    cache[j] = record;
                    break;
                }
            }
            pthread_mutex_unlock(&cache_lock);
            return &record;
        }
    }

    return NULL;
}

int validate_ip(const char* ip) {
    // Implement IP validation logic here
    return 1; // Return 1 for valid, 0 for invalid
}
