function renderFooterScripts(scripts, options = {}) {
  const defaults = {
    timeout: 5000,
    cachePolicy: 'session',
    fallbackUrl: '',
    retryInterval: 1000,
    maxRetries: 3,
    onError: (error) => console.error(error),
    onSuccess: () => {},
    onLoading: () => {}
  };

  const settings = { ...defaults, ...options };
  let loadingCount = scripts.length;

  function fetchScript(scriptUrl) {
    return new Promise((resolve, reject) => {
      const scriptElement = document.createElement('script');
      scriptElement.src = scriptUrl;
      scriptElement.type = 'text/javascript';
      scriptElement.async = true;

      scriptElement.onload = () => resolve();
      scriptElement.onerror = (error) => reject(error);

      document.head.appendChild(scriptElement);
    });
  }

  function checkCacheAndFetch(url, cacheKey) {
    const cachedScript = localStorage.getItem(cacheKey);
    if (cachedScript && settings.cachePolicy === 'session') {
      eval(cachedScript); // Assuming scripts are simple and safe
      resolve();
    } else {
      fetchScript(url)
        .then(() => {
          if (settings.cachePolicy === 'session') {
            localStorage.setItem(cacheKey, scriptElement.outerHTML);
          }
        })
        .catch((error) => reject(error));
    }
  }

  function handleScriptLoad(script, index) {
    loadingCount--;
    settings.onLoading(loadingCount);

    if (loadingCount === 0) {
      settings.onSuccess();
    }
  }

  function renderScripts() {
    scripts.forEach((script, index) => {
      const scriptUrl = script.src || '';
      const cacheKey = `script_cache_${index}`;

      checkCacheAndFetch(scriptUrl, cacheKey)
        .then(() => handleScriptLoad(script, index))
        .catch((error) => {
          if (settings.maxRetries > 0) {
            setTimeout(() => renderScripts(), settings.retryInterval);
          } else {
            settings.onError(error);
          }
        });
    });

    if (scripts.length === 0) {
      settings.onSuccess();
    }
  }

  settings.onLoading(loadingCount);
  renderScripts();
}
