```cpp
#include <iostream>
#include <mutex>
#include <condition_variable>
#include <vector>
#include <atomic>

struct OctreeNode {
    std::mutex mutex;
    std::condition_variable cv;
    bool isLeaf;
    int capacity;
    std::vector<int> data;
    std::array<OctreeNode*, 8> children;

    OctreeNode(int c) : isLeaf(true), capacity(c), data(), children() {}

    ~OctreeNode() {
        for (auto& child : children) {
            delete child;
        }
    }

    bool insert(int point) {
        std::lock_guard<std::mutex> lock(mutex);
        if (isLeaf && data.size() < capacity * 0.85) {
            data.push_back(point);
            return true;
        } else if (isLeaf) {
            isLeaf = false;
            split();
            return insert(point);
        }
        for (auto& child : children) {
            if (child && child->insert(point)) {
                return true;
            }
        }
        return false;
    }

    void split() {
        std::lock_guard<std::mutex> lock(mutex);
        int newSize = capacity / 2;
        for (int i = 0; i < 8; ++i) {
            children[i] = new OctreeNode(newSize);
        }
        for (auto point : data) {
            insert(point);
        }
        data.clear();
    }

    bool query(int point, int& result) {
        std::lock_guard<std::mutex> lock(mutex);
        if (isLeaf) {
            for (auto p : data) {
                if (p == point) {
                    result = p;
                    return true;
                }
            }
        } else {
            for (auto child : children) {
                if (child && child->query(point, result)) {
                    return true;
                }
            }
        }
        return false;
    }

    void rebalance() {
        std::lock_guard<std::mutex> lock(mutex);
        if (!isLeaf) {
            std::array<OctreeNode*, 8> tempChildren = children;
            for (auto& child : children) {
                delete child;
            }
            isLeaf = true;
            capacity *= 2;
            data.clear();
            for (auto child : tempChildren) {
                if (child) {
                    for (auto point : child->data) {
                        insert(point);
                    }
                    delete child;
                }
            }
        }
    }

    void prune() {
        std::lock_guard<std::mutex> lock(mutex);
        if (!isLeaf) {
            for (auto& child : children) {
                if (child && !child->isLeaf && child->data.empty()) {
                    delete child;
                    child = nullptr;
                } else if (child) {
                    child->prune();
                }
            }
        }
    }
};

OctreeNode* initializeOctree(int initialCapacity, int maxDepth) {
    try {
        OctreeNode* root = new OctreeNode(initialCapacity);
        for (int i = 0; i < maxDepth; ++i) {
            root->split();
        }
        return root;
    } catch (const std::bad_alloc& e) {
        std::cerr << "Memory allocation failed: " << e.what() << std::endl;
        return nullptr;
    }
}

int main() {
    OctreeNode* octree = initializeOctree(10, 3);
    if (!octree) {
        return 1;
    }

    int result;
    bool inserted = octree->insert(42);
    if (inserted) {
        std::cout << "Insertion successful!" << std::endl;
    } else {
        std::cerr << "Insertion failed." << std::endl;
    }

    bool found = octree->query(42, result);
    if (found) {
        std::cout << "Point found: " << result << std::endl;
    } else {
        std::cerr << "Point not found." << std::endl;
    }

    octree->rebalance();
    octree->prune();

    delete octree;
    return 0;
}
```

This code provides a basic structure for an advanced distributed octree data structure in C++. It includes methods for inserting, querying, rebalancing, and pruning the tree. The `initializeOctree` function creates a root node with initial capacity and splits it recursively up to a specified depth to demonstrate dynamic resizing. The main function demonstrates inserting a point, querying for a point, and performing basic operations like rebalancing and pruning.

