public void establishConnection(Channel channel) throws IOException
{
    channel.connect();
    channel.configureBlocking(false);

    SelectionKey key = channel.register(selector, SelectionKey.OP_CONNECT | SelectionKey.OP_READ | SelectionKey.OP_WRITE);

    while (key.isValid())
    {
        if ((key.readyOps() & SelectionKey.OP_CONNECT) != 0)
        {
            if (!channel.finishConnect())
            {
                throw new IOException("Connection failed");
            }
            key.interestOps(SelectionKey.OP_READ | SelectionKey.OP_WRITE);
        }

        if ((key.readyOps() & (SelectionKey.OP_READ | SelectionKey.OP_WRITE)) != 0)
        {
            handleReadAndWrite(channel, key);
        }
    }
}
