void initializeOctree()
{
    root = new Node();
    root->capacity = defaultCapacity;

    queue<Node*> nodesToInsert;
    nodesToInsert.push(root);

    while (!nodesToInsert.empty())
    {
        Node* node = nodesToInsert.front();
        nodesToInsert.pop();

        if (node->leafNodes.size() > 2 * node->capacity)
        {
            splitNode(node);
            for (auto child : node->children)
            {
                nodesToInsert.push(child);
            }
        }

        // Precompute BVH in a background thread
        std::thread([=]() { precomputeBVH(node); }).detach();
    }
}
