import json
from abc import ABC, abstractmethod
from typing import Dict, Any, Type, Callable, List
import threading
import queue

class ConfigLoader(ABC):
    _registry: Dict[str, Callable] = {}

    @abstractmethod
    def to_json(self) -> str:
        pass

    @abstractmethod
    def from_json(json_str: str) -> 'ConfigLoader':
        pass

    @classmethod
    def register(cls, id_: str, factory_func: Callable):
        cls._registry[id_] = factory_func

    @classmethod
    def get_instance(cls, id_: str, **kwargs) -> 'ConfigLoader':
        factory_func = cls._registry.get(id_)
        if factory_func:
            return factory_func(**kwargs)
        raise ValueError(f"No factory function registered for ID: {id_}")

class DatabaseConfig(ConfigLoader):
    def __init__(self, connection_string: str):
        self.connection_string = connection_string

    def to_json(self) -> str:
        return json.dumps({'type': 'database', 'connection_string': self.connection_string})

    @classmethod
    def from_json(cls, json_str: str) -> 'DatabaseConfig':
        data = json.loads(json_str)
        if data['type'] == 'database':
            return cls(data['connection_string'])
        raise ValueError("Invalid JSON format for DatabaseConfig")

class APIIntegrationConfig(ConfigLoader):
    # Implement similar methods as DatabaseConfig
    pass

class CachingMechanismConfig(ConfigLoader):
    # Implement similar methods as DatabaseConfig
    pass

# Register factory functions
ConfigLoader.register('database', DatabaseConfig.from_json)
ConfigLoader.register('api_integration', APIIntegrationConfig.from_json)
ConfigLoader.register('caching_mechanism', CachingMechanismConfig.from_json)

def load_configs(file_paths: List[str]) -> None:
    threads = []
    for file_path in file_paths:
        thread = threading.Thread(target=_load_config, args=(file_path,))
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()

def _load_config(file_path: str) -> None:
    with open(file_path, 'r') as file:
        config_data = json.load(file)

    try:
        config_instance = ConfigLoader.get_instance(config_data['type'], **config_data)
        # Process the loaded configuration instance
        pass
    except Exception as e:
        print(f"Error loading config from {file_path}: {e}")

# Example usage
if __name__ == "__main__":
    file_paths = ['database_config.json', 'api_integration_config.json', 'caching_mechanism_config.json']
    load_configs(file_paths)
