```python
import time
import random

class PaymentGatewayIntegration:
    def __init__(self):
        self.payment_status = {}

    def processPayment(self, orderId, cardNumber, expirationDate, cvv):
        try:
            self.validateCardDetails(cardNumber, expirationDate, cvv)
            attempt_count = 0
            while True:
                if random.choice([True, False]):
                    raise Exception("Transient error from payment gateway")
                time.sleep(2 ** attempt_count)
                attempt_count += 1
                return f"Payment processed for order {orderId}"
        except Exception as e:
            return str(e)

    def capturePayment(self, orderId):
        if orderId not in self.payment_status or self.payment_status[orderId] != "authorized":
            return f"Cannot capture payment for order {orderId}. Payment is not authorized."
        if self.payment_status.get(orderId + "_captured", False):
            return f"Payment for order {orderId} has already been captured."
        self.payment_status[orderId + "_captured"] = True
        return f"Payment for order {orderId} captured."

    def refundPayment(self, orderId):
        if orderId not in self.payment_status or self.payment_status[orderId] != "authorized":
            return f"Cannot refund payment for order {orderId}. Payment is not authorized."
        if self.payment_status.get(orderId + "_refunded", False):
            return f"Payment for order {orderId} has already been refunded."
        self.payment_status[orderId + "_refunded"] = True
        return f"Payment for order {orderId} refunded."

    def updatePaymentStatus(self, orderId, status):
        if orderId not in self.payment_status:
            raise ValueError(f"No payment found for order ID {orderId}")
        current_status = self.payment_status[orderId]
        if current_status == "failed":
            raise Exception("Cannot update status of a failed payment")
        if current_status == status:
            return f"Payment status for order {orderId} is already {status}"
        # Simulate optimistic locking by checking expected version
        if self.payment_status.get(orderId + "_version", 0) != 1:
            raise Exception("Concurrent update detected. Please retry the operation.")
        self.payment_status[orderId] = status
        self.payment_status[orderId + "_version"] = 2
        return f"Payment status for order {orderId} updated to {status}"

    def validateCardDetails(self, cardNumber, expirationDate, cvv):
        if not (len(cardNumber) == 16 and cardNumber.isdigit()):
            raise ValueError("Invalid card number")
        if not (len(expirationDate) == 5 and "/" in expirationDate):
            raise ValueError("Invalid expiration date format. Use MM/YY.")
        if not (len(cvv) == 3 and cvv.isdigit()):
            raise ValueError("Invalid CVV")
```

