        private static Dictionary<string, object> cache = new Dictionary<string, object>();

        public static T GetFromCache<T>(string key) where T : class
        {
            if (cache.ContainsKey(key))
            {
                return cache[key] as T;
            }
            return null;
        }

        public static void SetInCache<T>(string key, T value)
        {
            cache[key] = value;
        }

        public static void ClearCache()
        {
            cache.Clear();
        }
    }

    static class TimeoutHandler
    {
        private static readonly object lockObject = new object();
        private static DateTime timeoutTime;

        public static bool IsTimeoutExpired()
        {
            lock (lockObject)
            {
                if (timeoutTime == null || DateTime.Now >= timeoutTime)
                {
                    return true;
                }
                return false;
            }
        }

        public static void SetTimeout(int millisecondsTimeout)
        {
            lock (lockObject)
            {
                timeoutTime = DateTime.Now.AddMilliseconds(millisecondsTimeout);
            }
        }

        public static void ResetTimeout()
        {
            lock (lockObject)
            {
                timeoutTime = null;
            }
        }
    }
}
```

