```python
import requests
from concurrent.futures import ThreadPoolExecutor

def fetch_user_data(api_url: str, filters: dict) -> list:
    def fetch_page(page_number):
        params = {**filters, 'page': page_number}
        response = requests.get(api_url, params=params)
        if response.status_code == 200:
            return response.json()
        else:
            raise Exception(f"Failed to fetch data from API: {response.status_code} - {response.text}")

    def process_data(data):
        filtered_users = []
        for user in data['users']:
            if all(user.get(key) == value for key, value in filters.items()):
                filtered_users.append(user)
        return filtered_users

    try:
        total_pages = requests.get(api_url).json()['total_pages']
        with ThreadPoolExecutor(max_workers=5) as executor:
            pages_futures = [executor.submit(fetch_page, page) for page in range(1, total_pages + 1)]
            data_chunks = [future.result() for future in pages_futures]

        users = []
        for data_chunk in data_chunks:
            users.extend(process_data(data_chunk))

        return users
    except Exception as e:
        print(f"Error processing user data: {e}")
        return []

# Example usage
api_url = 'https://example.com/api/users'
filters = {'age': '25-30', 'location': 'New York'}
result = fetch_user_data(api_url, filters)
print(result)
```

