```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the FSA state structure
typedef struct State {
    int id;
    char* class;
    char* id;
    struct State** children;
    int numChildren;
    struct State* next;
} State;

// Define the Selector function type
typedef int (*SelectorFunc)(State*, const char*);

// Recursive traversal function to find matching states
void traverseAndFind(State* state, SelectorFunc selector, const char* selectorStr, State** result, int* count) {
    if (selector(state, selectorStr)) {
        result[*count] = (State*)malloc(sizeof(State));
        result[(*count)]->id = state->id;
        strcpy(result[(*count++)]->class, state->class);
        strcpy(result[(*count++)]->id, state->id);
        result[*count - 1]->next = NULL;
    }
    for (int i = 0; i < state->numChildren; i++) {
        traverseAndFind(state->children[i], selector, selectorStr, result, count);
    }
}

// Function to dynamically load and execute modules
void loadAndExecuteModules(const char* moduleNames[], int numModules) {
    for (int i = 0; i < numModules; i++) {
        // Load the module
        void (*moduleFunction)();
        moduleFunction = dlsym(RTLD_DEFAULT, moduleNames[i]);
        if (!moduleFunction) {
            fprintf(stderr, "Error loading module: %s\n", dlerror());
            return;
        }
        // Execute the module function
        moduleFunction();
    }
}

// Function to set up and execute the application with a command-line interface
int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <module1> [<module2> ...]\n", argv[0]);
        return 1;
    }
    const char** moduleNames = (const char**)malloc((argc - 1) * sizeof(const char*));
    for (int i = 1; i < argc; i++) {
        moduleNames[i - 1] = argv[i];
    }
    loadAndExecuteModules(moduleNames, argc - 1);
    free(moduleNames);
    return 0;
}
```

This code provides a basic structure for the function and application described in the task. It includes a recursive traversal function that matches states based on a selector and dynamically loads and executes modules using a command-line interface. You can further develop this code by adding more features and error handling as needed.

