import time
from collections import OrderedDict

class StockCache:
    def __init__(self, max_size=100):
        self.cache = OrderedDict()
        self.max_size = max_size

    def get(self, key):
        if key not in self.cache:
            return None
        else:
            # Move the recently accessed item to the end
            self.cache.move_to_end(key)
            return self.cache[key]

    def set(self, key, value):
        if key in self.cache:
            # Move the updated item to the end
            self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.max_size:
            # Evict the least recently used item
            self.cache.popitem(last=False)

    def update_cache(self, data):
        for ticker, price in data.items():
            try:
                self.set(ticker, price)
            except Exception as e:
                print(f"Failed to update cache for {ticker}: {e}")

# Example usage:
cache = StockCache(max_size=50)
data_to_update = {
    'AAPL': 145.23,
    'GOOGL': 2897.34,
    # ... more data ...
}
cache.update_cache(data_to_update)

# Retrieve stock price
price = cache.get('AAPL')
print(f"Current AAPL price: {price}")
