#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <pthread.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/types.h>

#define MAX_LOG_FILES 1000
#define MAX_THREADS 50
#define LOG_FILE_SIZE (1 * 1024 * 1024 * 1024) // 1GB

typedef struct {
    char* log_data;
    size_t data_size;
} LogEntry;

LogEntry log_entries[MAX_LOG_FILES];
int log_count = 0;

pthread_mutex_t log_lock;

void* process_log_file(void* arg) {
    int file_index = *(int*)arg;
    const char* filename = log_entries[file_index].log_data;

    // Open the log file
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open log file");
        return NULL;
    }

    // Memory-map the log file
    LogEntry* entry = &log_entries[file_index];
    entry->data_size = lseek(fd, 0, SEEK_END);
    if (entry->data_size > LOG_FILE_SIZE) {
        printf("Log file is too large: %s\n", filename);
        close(fd);
        return NULL;
    }
    entry->log_data = mmap(NULL, entry->data_size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (entry->log_data == MAP_FAILED) {
        perror("Failed to memory-map log file");
        close(fd);
        return NULL;
    }

    // Process the log data
    printf("Processing log file: %s\n", filename);

    // Unmap and close the log file
    munmap(entry->log_data, entry->data_size);
    close(fd);

    return NULL;
}

void process_log_files(const char* directory) {
    pthread_t threads[MAX_THREADS];
    int thread_ids[MAX_THREADS];

    DIR* dir = opendir(directory);
    if (dir == NULL) {
        perror("Failed to open directory");
        return;
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL && log_count < MAX_LOG_FILES) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        char filepath[1024];
        snprintf(filepath, sizeof(filepath), "%s/%s", directory, entry->d_name);

        // Allocate memory for the log file path
        log_entries[log_count].log_data = strdup(filepath);
        log_count++;
    }

    closedir(dir);

    // Create worker threads to process log files concurrently
    int thread_count = 0;
    for (int i = 0; i < log_count && thread_count < MAX_THREADS; i++) {
        thread_ids[thread_count] = i;
        if (pthread_create(&threads[thread_count], NULL, process_log_file, &thread_ids[thread_count]) != 0) {
            perror("Failed to create thread");
            return;
        }
        thread_count++;
    }

    // Wait for all threads to complete
    for (int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free memory allocated for log file paths
    for (int i = 0; i < log_count; i++) {
        free(log_entries[i].log_data);
    }
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <directory>\n", argv[0]);
        return 1;
    }

    const char* directory = argv[1];
    process_log_files(directory);

    return 0;
}
