#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

// Define the Product structure
typedef struct Product {
    char name[100];
    double price;
    struct Review *reviews;
} Product;

// Define the Review structure
typedef struct Review {
    int rating;
    char text[256];
    struct Review *next;
} Review;

// Function to create a new product
Product* create_product(const char *name, double price) {
    Product *product = (Product*)malloc(sizeof(Product));
    if (!product) return NULL;
    strcpy(product->name, name);
    product->price = price;
    product->reviews = NULL;
    return product;
}

// Function to add a review to a product
void add_review(Product *product, int rating, const char *text) {
    Review *new_review = (Review*)malloc(sizeof(Review));
    if (!new_review) return;
    new_review->rating = rating;
    strcpy(new_review->text, text);
    new_review->next = product->reviews;
    product->reviews = new_review;
}

// Function to calculate the average rating of a product
double calculate_average_rating(Product *product) {
    Review *review = product->reviews;
    int total_rating = 0;
    int count = 0;
    while (review != NULL) {
        total_rating += review->rating;
        count++;
        review = review->next;
    }
    return count > 0 ? (double)total_rating / count : 0.0;
}

// Function to free the memory of a product and its reviews
void free_product(Product *product) {
    Review *review = product->reviews;
    while (review != NULL) {
        Review *temp = review;
        review = review->next;
        free(temp);
    }
    free(product);
}
