EVP_CIPHER_CTX* aes_cipher_ctx_new(const char* cipher_str, int key_size, const unsigned char* salt,
                                    const unsigned char* user_key, size_t user_key_len,
                                    int iv_length, const unsigned char* iv) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        return NULL; // Handle error
    }

    EVP_CIPHER* cipher = EVP_get_cipherbyname(cipher_str);
    if (!cipher) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL; // Handle error
    }

    unsigned char derived_key[32];
    int derived_key_len;
    if (!PKCS5_PBKDF2_HMAC(user_key, user_key_len, salt, 16, key_size / 8, EVP_sha256(), derived_key_len, derived_key)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL; // Handle error
    }

    if (key_size == 128) {
        if (!EVP_EncryptInit_ex(ctx, cipher, NULL, derived_key, iv)) {
            EVP_CIPHER_CTX_free(ctx);
            return NULL; // Handle error
        }
    } else if (key_size == 192) {
        if (!EVP_EncryptInit_ex(ctx, cipher, NULL, derived_key, iv)) {
            EVP_CIPHER_CTX_free(ctx);
            return NULL; // Handle error
        }
    } else if (key_size == 256) {
        if (!EVP_EncryptInit_ex(ctx, cipher, NULL, derived_key, iv)) {
            EVP_CIPHER_CTX_free(ctx);
            return NULL; // Handle error
        }
    } else {
        EVP_CIPHER_CTX_free(ctx);
        return NULL; // Handle invalid key size
    }

    if (strcmp(cipher_str, "aes-128-gcm") == 0 || strcmp(cipher_str, "aes-192-gcm") == 0 || strcmp(cipher_str, "aes-256-gcm") == 0) {
        // Set GCM-specific parameters
    } else if (strcmp(cipher_str, "aes-128-cbc") == 0 || strcmp(cipher_str, "aes-192-cbc") == 0 || strcmp(cipher_str, "aes-256-cbc") == 0) {
        // Set CBC-specific parameters
    } else {
        EVP_CIPHER_CTX_free(ctx);
        return NULL; // Handle invalid cipher mode
    }

    return ctx;
}
