```java
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class FileHasher {
    private static final Logger logger = LoggerFactory.getLogger(FileHasher.class);
    private Map<String, String> hashCache = new ConcurrentHashMap<>();
    private Map<String, Long> cacheTimestamps = new HashMap<>();

    public String calculateMD5(String filePath) throws IOException, NoSuchAlgorithmException {
        if (hashCache.containsKey(filePath) && System.currentTimeMillis() - cacheTimestamps.get(filePath) < 3600000) {
            return hashCache.get(filePath);
        }
        try (FileInputStream fis = new FileInputStream(new File(filePath))) {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
            byte[] digest = md.digest();
            StringBuilder sb = new StringBuilder();
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            String hash = sb.toString();
            hashCache.put(filePath, hash);
            cacheTimestamps.put(filePath, System.currentTimeMillis());
            return hash;
        } catch (IOException | NoSuchAlgorithmException e) {
            logger.error("Error calculating MD5 hash for file: {}", filePath, e);
            throw e;
        }
    }

    public static void main(String[] args) {
        FileHasher hasher = new FileHasher();
        try {
            String hash = hasher.calculateMD5("/path/to/file.txt");
            System.out.println("File hash: " + hash);
        } catch (IOException | NoSuchAlgorithmException e) {
            e.printStackTrace();
        }
    }
}
