using System;
using System.Collections.Concurrent;
using System.IO;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

public class MediaAssetManager
{
    private readonly HttpClient _httpClient;
    private string _token;
    private DateTime _tokenExpiryTime;
    private readonly ConcurrentQueue<UploadRequest> _uploadQueue = new ConcurrentQueue<UploadRequest>();

    public MediaAssetManager(string tokenUrl, string clientId, string clientSecret)
    {
        _httpClient = new HttpClient();
        Authenticate(tokenUrl, clientId, clientSecret);
    }

    private async Task Authenticate(string tokenUrl, string clientId, string clientSecret)
    {
        // Fetch and store the initial token
        var response = await _httpClient.PostAsync(tokenUrl, new FormUrlEncodedContent(new[]
        {
            new KeyValuePair<string, string>("client_id", clientId),
            new KeyValuePair<string, string>("client_secret", clientSecret)
        }));
        if (response.IsSuccessStatusCode)
        {
            var content = await response.Content.ReadAsStringAsync();
            // Parse token and expiry time from response
            _token = content;
            _tokenExpiryTime = DateTime.UtcNow.AddMinutes(59); // Assuming token expires in 60 minutes
        }
    }

    public async Task UploadAsync(string filePath)
    {
        var request = new UploadRequest(filePath, null);
        _uploadQueue.Enqueue(request);
        await ProcessUploadQueue();
    }

    public async Task UploadAsync(byte[] fileData)
    {
        var request = new UploadRequest(null, fileData);
        _uploadQueue.Enqueue(request);
        await ProcessUploadQueue();
    }

    private async Task ProcessUploadQueue()
    {
        while (_uploadQueue.TryDequeue(out var request))
        {
            try
            {
                if (DateTime.UtcNow > _tokenExpiryTime)
                {
                    // Refresh token
                    await Authenticate("https://api.example.com/auth", "clientId", "clientSecret");
                }
                await UploadFileAsync(request);
            }
            catch (Exception ex)
            {
                // Handle error and retry mechanism
                Console.WriteLine($"Upload failed: {ex.Message}");
            }
        }
    }

    private async Task UploadFileAsync(UploadRequest request)
    {
        var content = new MultipartFormDataContent();
        if (request.FilePath != null)
        {
            using (var fileStream = File.OpenRead(request.FilePath))
            {
                var fileContent = new StreamContent(fileStream);
                fileContent.Headers.ContentDisposition = new System.Net.Http.Headers.ContentDispositionHeaderValue("form-data")
                {
                    Name = "file",
                    FileName = Path.GetFileName(request.FilePath)
                };
                content.Add(fileContent);
            }
        }
        else if (request.FileData != null)
        {
            var fileContent = new ByteArrayContent(request.FileData);
            fileContent.Headers.ContentDisposition = new System.Net.Http.Headers.ContentDispositionHeaderValue("form-data")
            {
                Name = "file",
                FileName = "media_asset.bin"
            };
            content.Add(fileContent);
        }

        // Send upload request to cloud storage
        var response = await _httpClient.PostAsync("https://api.example.com/upload", content, CancellationToken.None);
        if (!response.IsSuccessStatusCode)
        {
            throw new Exception($"Upload failed with status code: {response.StatusCode}");
        }
    }
}

public class UploadRequest
{
    public string FilePath { get; private set; }
    public byte[] FileData { get; private set; }

    public UploadRequest(string filePath, byte[] fileData)
    {
        FilePath = filePath;
        FileData = fileData;
    }
}
