import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.util.Iterator;
import java.util.Set;

public class NetworkedCharacter {
    private SocketChannel channel;
    private Selector selector;
    private ByteBuffer buffer = ByteBuffer.allocate(1024);
    private int energyLevel = 100;
    private int cooldown = 5; // Default cooldown in seconds

    public void connectToServer(String serverAddress, int port) throws IOException {
        channel = SocketChannel.open(new InetSocketAddress(serverAddress, port));
        channel.configureBlocking(false);
        selector = Selector.open();
        channel.register(selector, SelectionKey.OP_CONNECT | SelectionKey.OP_READ);

        while (true) {
            selector.select();
            Set<SelectionKey> selectedKeys = selector.selectedKeys();
            Iterator<SelectionKey> keyIterator = selectedKeys.iterator();

            while (keyIterator.hasNext()) {
                SelectionKey key = keyIterator.next();

                if (!key.isValid()) {
                    continue;
                }

                if (key.isConnectable()) {
                    channel.register(selector, SelectionKey.OP_READ);
                    channel.finishConnect();
                    System.out.println("Connected to server at " + serverAddress + ":" + port);
                } else if (key.isReadable()) {
                    buffer.clear();
                    int bytesRead = channel.read(buffer);
                    if (bytesRead == -1) {
                        channel.close();
                        selector.close();
                        break;
                    }
                    buffer.flip();
                    while (buffer.hasRemaining()) {
                        System.out.print((char) buffer.get());
                    }
                }

                keyIterator.remove();
            }
        }
    }

    public void attack() {
        if (!canAttack()) {
            return;
        }

        String selectedAttack = selectAttack(energyLevel);
        int power = getAttackPower(selectedAttack);

        // Log attack event
        System.out.println("Attacking with " + selectedAttack + " for " + power + " power");

        // Send attack command to server through NIO channel
        try {
            ByteBuffer sendBuffer = ByteBuffer.wrap(("ATTACK," + selectedAttack + "," + power).getBytes());
            channel.write(sendBuffer);
        } catch (IOException e) {
            System.err.println("Failed to send attack command: " + e.getMessage());
        }

        // Decrease energy based on attack power
        energyLevel -= getEnergyConsumption(selectedAttack);

        // Update cooldown for selected attack
        setCooldown(selectedAttack, calculateCooldown(power));
    }

    private boolean canAttack() {
        return System.currentTimeMillis() >= nextAttackTime;
    }

    private String selectAttack(int energy) {
        // Implement dynamic attack selection logic here based on character's resources, attack history, and server conditions
        // Prioritize less resource-intensive attacks when the character's energy is low
        // Return the selected attack type as a string
        return "Light Punch";
    }

    private int getAttackPower(String attack) {
        // Implement logic to calculate the power level of the selected attack based on its attributes
        return 10;
    }

    private int getEnergyConsumption(String attack) {
        // Implement logic to determine the energy consumption of the selected attack based on its attributes
        return 5;
    }

    private void setCooldown(String attack, long newCooldown) {
        // Update the cooldown period for the selected attack based on server's load, network latency, and character's energy level
        nextAttackTime = System.currentTimeMillis() + newCooldown * 1000;
    }

    private long calculateCooldown(int power) {
        // Implement logic to adjust the cooldown period based on attack power
        return Math.max(2, 5 - (power / 10));
    }

    public void updateEnergyLevel(int amount) {
