template<typename T>
class OctreeNode {
public:
    std::array<OctreeNode<T>*, 8> children;
    T data;

    OctreeNode() : data(T()), children{nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr} {}
};

template<typename T>
class Octree {
private:
    OctreeNode<T>* root;
    std::mutex mutex;
    std::condition_variable cv;
    bool running;

public:
    Octree() : root(new OctreeNode<T>()), running(true) {}

    ~Octree() {
        clear(root);
        delete root;
    }

    void insert(const T& data, const Vector3& position) {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this] { return running; });
        // Insert logic here
    }

    bool query(const Vector3& min, const Vector3& max, std::vector<T>& results) {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this] { return running; });
        // Query logic here
        return false;
    }

private:
    void clear(OctreeNode<T>* node) {
        for (auto& child : node->children) {
            if (child) {
                clear(child);
                delete child;
                child = nullptr;
            }
        }
    }
};
