import os
import time
import py_compile
import psutil
from functools import lru_cache

# Assume logger is an external logging system that supports info, warn, and error methods
from external_logger import logger

@lru_cache(maxsize=None)
def compile_file(file_path):
    try:
        start_time = time.time()
        process = psutil.Popen(['python', '-m', 'py_compile', file_path], stdout=psutil.DEVNULL, stderr=psutil.STDOUT)
        _, output = process.communicate()
        end_time = time.time()

        compile_duration = end_time - start_time
        memory_usage = process.memory_info().rss / (1024 * 1024)  # Convert bytes to MB

        logger.info(f"File: {file_path}, Compile Duration: {compile_duration:.2f}s, Memory Usage: {memory_usage:.2f}MB")

    except Exception as e:
        logger.error(f"Error compiling file {file_path}: {e}")
        raise

def compile_directory(directory):
    try:
        total_time = 0
        peak_memory = 0

        for root, _, files in os.walk(directory):
            for file in files:
                if file.endswith('.py'):
                    file_path = os.path.join(root, file)
                    compile_file(file_path)

        logger.info(f"Total Compilation Time: {total_time:.2f}s")

    except Exception as e:
        logger.error(f"Error compiling directory {directory}: {e}")
        raise

# Example usage
if __name__ == "__main__":
    try:
        compile_directory('/path/to/directory')
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
```

This code snippet provides a Python function `compile_directory` that recursively compiles all `.py` files within a specified directory using the `py_compile` module. It measures the total time taken for the compilation process and logs relevant metrics such as file name, compile duration, and memory usage using an external logging system. The function uses a lazy initialization mechanism to optimize repeated compilations of the same file through Python's `functools.lru_cache`. Error handling is implemented to catch and log any exceptions that may occur during the compilation process.

```python
from aiohttp import web, ClientSession, ClientConnectorError
import aioredis
import asyncio
import logging

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class APIGateway:
    def __init__(self, config):
        self.config = config
        self.session = ClientSession()
        self.redis_client = None
        self.initialize_redis()

    async def initialize_redis(self):
        try:
            self.redis_client = await aioredis.create_redis_pool(self.config['redis']['url'])
        except Exception as e:
            logger.error(f"Failed to connect to Redis: {e}")
            raise

    async def route_request(self, request):
        path_parts = request.path.split('/')
        version = path_parts[1] if len(path_parts) > 1 else 'v1'
        backend_key = f"{version}_{request.method}_{request.path}"

        # Check cache
        cached_response = await self.redis_client.get(backend_key)
        if cached_response:
            logger.info(f"Returning cached response for {backend_key}")
            return web.Response(text=cached_response, content_type='application/json')

        backend_url = self.config['backends'].get(backend_key)
        if not backend_url:
            logger.error(f"No backend configured for {backend_key}")
            return web.HTTPNotFound()

        try:
            async with self.session.request(request.method, backend_url, headers=request.headers, data=request.body) as resp:
                response_data = await resp.text()
                # Cache the response
                await self.redis_client.set(backend_key, response_data, expire=self.config['cache']['expiration'])
                logger.info(f"Cached response for {backend_key}")
                return web.Response(text=response_data, content_type=resp.content_type)
        except ClientConnectorError:
            logger.error(f"Failed to connect to backend: {backend_url}")
            return web.HTTPServiceUnavailable()

    async def shutdown(self):
        await self.session.close()
        if self.redis_client:
            self.redis_client.close()
            await self.redis_client.wait_closed()

async def handle_request(request, api_gateway):
    return await api_gateway.route_request(request)

if __name__ == '__main__':
    config = {
        'redis': {'url': 'redis://localhost'},
        'backends': {
            'v1_GET_/api/v1/users': 'http://users-service:8080/api/v1/users',
            'v2_GET_/api/v1/users': 'http://new-users-service:8080/api/v1/users'
        },
        'cache': {'expiration': 3600}
    }

    app = web.Application()
    api_gateway = APIGateway(config)
    app.router.add_route('*', '/{tail:.*}', handle_request, partial=True, kwargs={'api_gateway': api_gateway})
    runner = web.AppRunner(app)
    await runner.setup()
    site = web.TCPSite(runner, '0.0.0.0', 8081)
    await site.start()

    try:
        while True:
            await asyncio.sleep(3600)
    except KeyboardInterrupt:
        pass

    await api_gateway.shutdown()
