using System;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Caching.Distributed;
using Microsoft.Extensions.Logging;
using StackExchange.Redis;

[ApiController]
public class HtmlContentService : ControllerBase
{
    private readonly HttpClient _httpClient;
    private readonly IDistributedCache _cache;
    private readonly ILogger<HtmlContentService> _logger;
    private static readonly string _redisConnectionString = "your_redis_connection_string";
    private static readonly string _azureStorageConnectionString = "your_azure_storage_connection_string";

    public HtmlContentService(HttpClient httpClient, IDistributedCache cache, ILogger<HtmlContentService> logger)
    {
        _httpClient = httpClient;
        _cache = cache;
        _logger = logger;
    }

    [HttpPost("update-html")]
    public async Task<IActionResult> UpdateHtml(string pageSectionId, string elementId, string htmlContent)
    {
        try
        {
            var lockKey = $"lock:{pageSectionId}:{elementId}";
            if (await TryAcquireLockAsync(lockKey))
            {
                try
                {
                    var cacheKey = $"html:{pageSectionId}:{elementId}";
                    var cachedHtml = await _cache.GetStringAsync(cacheKey);

                    if (!string.IsNullOrEmpty(cachedHtml) && cachedHtml == htmlContent)
                    {
                        return Ok("No changes detected.");
                    }

                    // Fetch the current HTML content from Azure Blob Storage
                    var currentHtml = await FetchHtmlFromStorage(pageSectionId, elementId);

                    if (currentHtml != null)
                    {
                        // Perform optimistic concurrency control
                        if (!string.IsNullOrEmpty(cachedHtml) && cachedHtml == currentHtml)
                        {
                            // Update the HTML content in Azure Blob Storage
                            await UpdateHtmlInStorage(pageSectionId, elementId, htmlContent);

                            // Invalidate the cache
                            await _cache.RemoveAsync(cacheKey);

                            // Log the update
                            _logger.LogInformation($"Updated HTML for page section {pageSectionId} and element {elementId}");

                            return Ok("HTML updated successfully.");
                        }
                        else
                        {
                            return Conflict("Conflict detected. Please refresh your data and try again.");
                        }
                    }
                    else
                    {
                        // Handle the case when the element does not exist in storage
                        _logger.LogError($"Element {elementId} not found for page section {pageSectionId}");
                        return NotFound();
                    }
                }
                finally
                {
                    ReleaseLockAsync(lockKey);
                }
            }
            else
            {
                return StatusCode(429, "Too Many Requests. Please try again later.");
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while updating HTML content.");
            return StatusCode(500, "Internal Server Error");
        }
    }

    private async Task<string> FetchHtmlFromStorage(string pageSectionId, string elementId)
    {
        using var storageClient = new BlobServiceClient(_azureStorageConnectionString);
        var containerName = $"html-content";
        var blobContainerClient = storageClient.GetBlobContainerClient(containerName);

        if (await blobContainerClient.ExistsAsync())
        {
            var blobClient = blobContainerClient.GetBlobClient($"{pageSectionId}/{elementId}.html");
            return await blobClient.DownloadTextAsync();
        }

        return null;
    }

    private async Task UpdateHtmlInStorage(string pageSectionId, string elementId, string htmlContent)
    {
        using var storageClient = new BlobServiceClient(_azureStorageConnectionString);
        var containerName = $"html-content";
        var blobContainerClient = storageClient.GetBlobContainerClient(containerName);

        if (!await blobContainerClient.ExistsAsync())
        {
            await blobContainerClient.CreateIfNotExistsAsync();
        }

        var blobClient = blobContainerClient.GetBlobClient($"{pageSectionId}/{elementId}.html");
        await blobClient.UploadTextAsync(htmlContent);
    }

    private async Task<bool> TryAcquireLockAsync(string lockKey)
    {
        using (var connectionMultiplexer = ConnectionMultiplexer.Connect(_redisConnectionString))
        {
            var db = connectionMultiplexer.GetDatabase();
            return await db.StringSetAsync(lockKey, "locked", TimeSpan.FromSeconds(30));
        }
    }

    private void ReleaseLockAsync(string lockKey)
    {
        using (var connectionMultiplexer = ConnectionMultiplexer.Connect(_redisConnectionString))
        {
            var db = connectionMultiplexer.GetDatabase();
            db.KeyDelete(lockKey);
        }
    }
}
