public enum DataSourceType { CSV, JSON, SQL }

public class DataLoader
{
    private DataSourceType dataSourceType;
    private string connectionString;
    private Dictionary<string, Type> schemaDefinition;

    public DataLoader(DataSourceType sourceType, string connString, Dictionary<string, Type> schema)
    {
        dataSourceType = sourceType;
        connectionString = connString;
        schemaDefinition = schema;
    }

    public List<Dictionary<string, object>> LoadDataFromSource()
    {
        switch (dataSourceType)
        {
            case DataSourceType.CSV:
                return LoadCsvData();
            case DataSourceType.JSON:
                return LoadJsonData();
            case DataSourceType.SQL:
                return LoadSqlData();
            default:
                throw new InvalidOperationException("Unsupported data source type.");
        }
    }

    private List<Dictionary<string, object>> LoadCsvData()
    {
        // Implementation for loading CSV data
        return new List<Dictionary<string, object>>();
    }

    private List<Dictionary<string, object>> LoadJsonData()
    {
        using (var client = new HttpClient())
        {
            var jsonContent = client.GetStringAsync("your_json_url").Result;
            return JsonConvert.DeserializeObject<List<Dictionary<string, object>>>(jsonContent);
        }
    }

    private List<Dictionary<string, object>> LoadSqlData()
    {
        using (var connection = new SqlConnection(connectionString))
        {
            connection.Open();
            var command = new SqlCommand("SELECT * FROM your_table", connection);
            using (var reader = command.ExecuteReader())
            {
                return ConvertDataReaderToList(reader);
            }
        }
    }

    private List<Dictionary<string, object>> ConvertDataReaderToList(SqlDataReader reader)
    {
        var result = new List<Dictionary<string, object>>();
        while (reader.Read())
        {
            var row = new Dictionary<string, object>();
            for (int i = 0; i < reader.FieldCount; i++)
            {
                row[reader.GetName(i)] = reader[i];
            }
            result.Add(row);
        }
        return result;
    }

    public List<Dictionary<string, object>> PreprocessData(List<Dictionary<string, object>> data)
    {
        // Implement data preprocessing logic here
        ValidateSchema(data);
        NormalizeData(data);
        HandleMissingValues(data);
        ApplyTransformations(data);
        return data;
    }

    private void ValidateSchema(List<Dictionary<string, object>> data)
    {
        foreach (var row in data)
        {
            if (!row.Keys.SequenceEqual(schemaDefinition.Keys))
                throw new SchemaMismatchException("Schema mismatch detected.");
            foreach (var key in row.Keys)
            {
                var value = row[key];
                if (value == null && schemaDefinition[key] != typeof(string))
                    throw new MissingValueException($"Missing value for {key} which is required.");
                // Additional type checks can be added here
            }
        }
    }

    private void NormalizeData(List<Dictionary<string, object>> data)
    {
        // Implement normalization logic here
    }

    private void HandleMissingValues(List<Dictionary<string, object>> data)
    {
        // Implement missing value handling logic here
    }

    private void ApplyTransformations(List<Dictionary<string, object>> data)
    {
        // Implement transformation logic based on schema definition
    }

    public Dictionary<string, object> GetSampleData(int sampleSize = 10)
    {
        var data = LoadDataFromSource();
        return data.OrderBy(x => Guid.NewGuid()).Take(sampleSize).First();
    }

    public void SavePreprocessedData(List<Dictionary<string, object>> data, string filePath)
    {
        using (var writer = new StreamWriter(filePath))
        {
            writer.WriteLine(JsonConvert.SerializeObject(data));
        }
    }

    public override string ToString()
    {
        return $"DataSourceType: {dataSourceType}, ConnectionString: {connectionString}, SchemaDefinition: {string.Join(", ", schemaDefinition.Select(kv => $"{kv.Key}: {kv.Value}"))}";
    }
}
