class FileStorageManager {
    private $storage = [];
    private $cache = [];

    public function uploadFile($filename, $fileContent) {
        if (isset($this->storage[$filename])) {
            throw new Exception("File already exists.");
        }
        $this->storage[$filename] = $fileContent;
        unset($this->cache[$filename]); // Clear cache for the file
    }

    public function downloadFile($filename) {
        if (!isset($this->storage[$filename])) {
            throw new Exception("File not found.");
        }
        if (isset($this->cache[$filename])) {
            return $this->cache[$filename];
        }
        $fileContent = $this->storage[$filename];
        $this->cache[$filename] = $fileContent; // Cache the file for future access
        return $fileContent;
    }

    public function listFiles() {
        return array_keys($this->storage);
    }

    public function deleteFile($filename) {
        if (isset($this->storage[$filename])) {
            unset($this->storage[$filename]);
            unset($this->cache[$filename]); // Clear cache for the file
        }
    }

    public function renameFile($oldFilename, $newFilename) {
        if (!isset($this->storage[$oldFilename])) {
            throw new Exception("Old filename not found.");
        }
        if (isset($this->storage[$newFilename])) {
            throw new Exception("New filename already exists.");
        }
        $fileContent = $this->storage[$oldFilename];
        unset($this->storage[$oldFilename]);
        $this->storage[$newFilename] = $fileContent;
        unset($this->cache[$newFilename]); // Clear cache for the old filename
    }
}
