import software.amazon.awssdk.auth.credentials.ProfileCredentialsProvider;
import software.amazon.awssdk.regions.Region;
import software.amazon.awssdk.services.s3.S3Client;
import software.amazon.awssdk.services.s3.model.*;
import java.io.File;
import java.nio.file.Files;
import java.util.concurrent.CompletableFuture;

public class FileTransferManager {

    private final S3Client s3Client;
    private final String localDirectory;
    private final String bucketName;

    public FileTransferManager(String region, String localDirectory, String bucketName) {
        this.s3Client = S3Client.builder()
                .region(Region.of(region))
                .credentialsProvider(ProfileCredentialsProvider.create())
                .build();
        this.localDirectory = localDirectory;
        this.bucketName = bucketName;
    }

    public void startSyncTransfer(boolean upload, File file) throws Exception {
        if (upload) {
            uploadFile(file);
        } else {
            downloadFile(file);
        }
    }

    private void uploadFile(File file) throws Exception {
        String key = file.getName();
        long fileSize = file.length();
        long chunkSize = 5 * 1024 * 1024; // 5MB chunk size
        long offset = 0;

        while (offset < fileSize) {
            long remainingBytes = fileSize - offset;
            long currentChunkSize = Math.min(chunkSize, remainingBytes);

            CompletableFuture<UploadPartResponse> future = s3Client.uploadPartPaginator(
                    UploadPartRequest.builder()
                            .bucket(bucketName)
                            .key(key)
                            .uploadId(getUploadId(key))
                            .partNumber((int) (offset / chunkSize + 1))
                            .body(Files.newInputStream(file.toPath().subpath(0, currentChunkSize)))
                            .build())
                    .iterable()
                    .findFirst()
                    .get();

            PartETag partETag = future.get();
            // Log progress and handle errors
        }
    }

    private void downloadFile(File file) throws Exception {
        String key = file.getName();
        long fileSize = s3Client.headObject(HeadObjectRequest.builder().bucket(bucketName).key(key).build()).contentLength();
        long chunkSize = 5 * 1024 * 1024; // 5MB chunk size
        long offset = 0;

        while (offset < fileSize) {
            long remainingBytes = fileSize - offset;
            long currentChunkSize = Math.min(chunkSize, remainingBytes);

            CompletableFuture<GetObjectResponse> future = s3Client.getObjectPaginator(
                    GetObjectRequest.builder()
                            .bucket(bucketName)
                            .key(key)
                            .range("bytes=" + offset + "-" + (offset + currentChunkSize - 1))
                            .build())
                    .iterable()
                    .findFirst()
                    .get();

            // Write the chunk to the file
            // Log progress and handle errors
        }
    }

    private String getUploadId(String key) {
        // Implement logic to retrieve or initiate an upload ID
        return "some-upload-id";
    }
}
