// Function to dynamically render secure footer scripts
function renderSecureFooterScripts(scripts) {
    // Check for essential properties in each script object
    const filteredScripts = scripts.filter(script => 
        script.code && script.type && (script.src || !script.code.includes('<script'))
    );

    // Initialize variables
    let html = '';
    const scriptCache = {};
    const spinner = document.createElement('div');
    spinner.innerHTML = 'Loading...';
    document.body.appendChild(spinner);

    // Function to fetch scripts from external API
    async function fetchScripts() {
        try {
            const response = await fetch('/api/scripts', { method: 'GET' });
            if (!response.ok) throw new Error('Network response was not ok');
            return await response.json();
        } catch (error) {
            console.error('Error fetching scripts:', error);
            throw error;
        }
    }

    // Function to manage cache
    function manageCache(script) {
        if (scriptCache[script.src]) {
            const cachedScript = document.querySelector(`script[src="${script.src}"]`);
            if (cachedScript) {
                document.body.removeChild(cachedScript);
            }
        }
        scriptCache[script.src] = true;
    }

    // Function to render scripts
    async function renderScripts() {
        spinner.style.display = 'none';
        for (let i = 0; i < filteredScripts.length; i++) {
            const script = filteredScripts[i];
            manageCache(script);
            if (!script.src) {
                const scriptTag = document.createElement('script');
                scriptTag.type = script.type;
                scriptTag.innerHTML = script.code;
                document.body.appendChild(scriptTag);
            } else {
                try {
                    const response = await fetch(script.src, { method: 'GET', cache: 'reload' });
                    if (!response.ok) throw new Error('Network response was not ok');
                    const scriptText = await response.text();
                    const scriptTag = document.createElement('script');
                    scriptTag.type = script.type;
                    scriptTag.innerHTML = scriptText;
                    document.body.appendChild(scriptTag);
                } catch (error) {
                    console.error('Error rendering script:', error);
                }
            }
        }
    }

    // Fetch and render scripts
    fetchScripts().then(renderScripts).catch(error => {
        spinner.style.display = 'none';
        console.error('Error fetching or rendering scripts:', error);
    });

    return html;
}

