<?php
// Function to generate a secure random string for URL tokens
function generateSecureToken($length = 32, $characters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') {
    if ($length < 1) {
        throw new InvalidArgumentException('Length must be greater than 0');
    }
    if (empty($characters)) {
        throw new InvalidArgumentException('Character set cannot be empty');
    }

    $token = '';
    for ($i = 0; $i < $length; $i++) {
        $token .= $characters[rand(0, strlen($characters) - 1)];
    }

    return $token;
}

// Function to hash a password using a customizable algorithm
function hashPassword($password, $algorithm = 'bcrypt', $salt = null) {
    if (!in_array($algorithm, ['bcrypt', 'argon2id'])) {
        throw new InvalidArgumentException('Invalid hashing algorithm');
    }
    if ($salt === null) {
        $salt = generateSecureToken();
    }

    switch ($algorithm) {
        case 'bcrypt':
            return password_hash($password . $salt, PASSWORD_BCRYPT);
        case 'argon2id':
            return password_hash($password . $salt, PASSWORD_ARGON2ID);
        default:
            throw new Exception('Error hashing password');
    }
}

// Example usage:
$password = 'my_secure_password';
$hashedPassword = hashPassword($password, 'bcrypt');
echo 'Hashed Password: ' . $hashedPassword;
?>
