{
    private readonly string _kmsUrl;
    private readonly ILogger _logger;

    public FileEncryptor(string kmsUrl, ILogger logger)
    {
        _kmsUrl = kmsUrl;
        _logger = logger;
    }

    public async Task EncryptFilesAsync(List<string> filePaths, string cipher, string mode, bool isAsync = false, int timeout = 30)
    {
        if (!Directory.Exists(Path.GetDirectoryName(filePaths.First())))
        {
            _logger.LogError("Invalid directory path.");
            return;
        }

        var webConfigPath = Path.Combine(Directory.GetCurrentDirectory(), "web.config");
        if (!File.Exists(webConfigPath))
        {
            _logger.LogError("Web.config file not found.");
            return;
        }

        var validSites = ValidateSiteNames();
        if (validSites == null)
        {
            _logger.LogError("Invalid site names.");
            return;
        }

        foreach (var filePath in filePaths)
        {
            try
            {
                using (var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, 4096, true))
                {
                    var encryptedFilePath = Path.ChangeExtension(filePath, ".enc");
                    using (var encryptor = CreateEncryptor(cipher, mode))
                    {
                        using (var outputFile = new FileStream(encryptedFilePath, FileMode.Create, FileAccess.Write, FileShare.None, 4096, true))
                        {
                            await fileStream.CopyToAsync(outputFile, encryptor);
                        }
                    }

                    _logger.LogInformation($"File encrypted: {filePath}");
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
            }
        }
    }

    private ICryptoTransform CreateEncryptor(string cipher, string mode)
    {
        using (var kmsClient = new KmsClient(_kmsUrl))
        {
            var key = kmsClient.GetEncryptionKey(cipher, mode);
            return Aes.Create().CreateEncryptor(key.KeyBytes, key.IvBytes);
        }
    }

