import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ImageMetadataProcessor {
    public static void main(String[] args) {
        // Parse command-line arguments
        String directoryPath = args[0];
        Path outputPath = args.length > 1 ? Paths.get(args[1]) : null;

        // Validate directory path
        if (!Files.isDirectory(Paths.get(directoryPath))) {
            System.out.println("Invalid directory path.");
            return;
        }

        // Create executor service for multi-threaded image processing
        ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

        try (DirectoryStream<Path> stream = Files.newDirectoryStream(Paths.get(directoryPath), "*.{jpg,jpeg,png}")) {
            for (Path path : stream) {
                if (!path.toString().toLowerCase().endsWith(".svg") && !path.toString().toLowerCase().endsWith(".psd")) {
                    executorService.submit(() -> processImage(path, outputPath));
                }
            }
        } catch (IOException e) {
            System.out.println("Error reading directory: " + e.getMessage());
        }

        // Shutdown executor service and await completion
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }

        System.out.println("Image processing complete.");
    }

    private static void processImage(Path path, Path outputPath) {
        try {
            // Trigger C++ function to resize image
            long startTime = System.currentTimeMillis();
            ImageResizer.resize(path.toFile(), 800, 600);
            long endTime = System.currentTimeMillis();

            // Log processing time and status
            System.out.println("Processed " + path.getFileName() + " in " + (endTime - startTime) + " ms");

            // Write metadata report to output file if specified
            if (outputPath != null) {
                Files.write(outputPath, ("Processed: " + path.getFileName() + "\n").getBytes());
            }
        } catch (Exception e) {
            System.err.println("Error processing " + path.getFileName() + ": " + e.getMessage());
        }
    }

    // Native method declaration for C++ function
    static {
        System.loadLibrary("image_resizer");
    }
}

// C++ code for ImageResizer::resize function would be implemented separately
```

