import java.util.concurrent.*;
import org.springframework.web.multipart.MultipartFile;

public class FileUploader {

    private final ExecutorService uploadThreadPool;
    private final StorageHandlerFactory storageHandlerFactory;

    public FileUploader(int maxConcurrency, StorageHandlerFactory storageHandlerFactory) {
        this.uploadThreadPool = Executors.newFixedThreadPool(maxConcurrency);
        this.storageHandlerFactory = storageHandlerFactory;
    }

    public void processFileUploads(Queue<MultipartFile> uploadQueue, int maxConcurrency) throws InterruptedException {
        for (int i = 0; i < maxConcurrency; i++) {
            uploadThreadPool.submit(() -> {
                while (!uploadQueue.isEmpty()) {
                    MultipartFile file = uploadQueue.poll();
                    if (file == null) break;
                    processFileUpload(file);
                }
            });
        }

        // Shutdown and await termination of the thread pool
        uploadThreadPool.shutdown();
        uploadThreadPool.awaitTermination(1, TimeUnit.HOURS);
    }

    private void processFileUpload(MultipartFile file) {
        try {
            long startTime = System.currentTimeMillis();
            StorageHandler storageHandler = storageHandlerFactory.createStorageHandler();

            // Simulate file upload logic using asynchronous I/O or other efficient methods
            boolean isUploaded = storageHandler.upload(file);

            long duration = System.currentTimeMillis() - startTime;
            logUploadDetails(file, duration, isUploaded);
        } catch (Exception e) {
            handleFileUploadFailure(file, e);
        }
    }

    private void logUploadDetails(MultipartFile file, long duration, boolean isSuccessful) {
        // Log start and completion of each upload
        String status = isSuccessful ? "Success" : "Failed";
        System.out.println("File: " + file.getOriginalFilename() + " - Status: " + status + ", Duration: " + duration + "ms");
    }

    private void handleFileUploadFailure(MultipartFile file, Exception e) {
