class CachingMechanism {
    std::unordered_map<std::string, std::pair<int, std::chrono::time_point<std::chrono::system_clock>>> cache;
    std::mutex mtx;
    const std::chrono::seconds ttl;

public:
    CachingMechanism(std::chrono::seconds timeout) : ttl(timeout) {}

    void put(const std::string& key, int value) {
        std::lock_guard<std::mutex> lock(mtx);
        cache[key] = {value, std::chrono::system_clock::now()};
    }

    std::optional<int> get(const std::string& key) {
        std::lock_guard<std::mutex> lock(mtx);
        auto now = std::chrono::system_clock::now();
        if (cache.find(key) != cache.end() && 
            cache[key].second + ttl > now) {
            return cache[key].first;
        }
        return std::nullopt;
    }

    void remove(const std::string& key) {
        std::lock_guard<std::mutex> lock(mtx);
        cache.erase(key);
    }
};

