        if (resultOpt.has_value()) {
            std::cout << "Cache hit: Result=" << resultOpt.value() << std::endl;
            logger.logSuccess(resultOpt.value(), connStr);
            return;
        }

        int result = client.callStoredProc(connStr, params, procName);
        cache.put(connStr + procName, result);

