import sqlite3

app = Flask(__name__)
API_KEY = 'your_api_key_here'
CACHE = {}
CACHE_EXPIRY = timedelta(hours=1)
DATABASE = 'weather.db'

# Initialize database connection
def init_db():
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute('CREATE TABLE IF NOT EXISTS locations (id INTEGER PRIMARY KEY, city TEXT)')
    conn.commit()
    conn.close()

# Decorator for rate limiting
def limit_calls(max_per_minute=10):
    count = 0
    last_reset = datetime.now()

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal count, last_reset
            now = datetime.now()

            if (now - last_reset) > timedelta(minutes=1):
                count = 0
                last_reset = now

            if count >= max_per_minute:
                return jsonify({'error': 'Rate limit exceeded'}), 429

            count += 1
            return func(*args, **kwargs)
        return wrapper
    return decorator

# Function to fetch weather data
@limit_calls()
def get_weather(city):
    url = f'https://api.openweathermap.org/data/2.5/weather?q={city}&appid={API_KEY}'

    if city in CACHE and (datetime.now() - CACHE[city]['timestamp']) < CACHE_EXPIRY:
        return CACHE[city]

    response = requests.get(url)
    if response.status_code == 200:
        weather_data = response.json()
        CACHE[city] = {'data': weather_data, 'timestamp': datetime.now()}
        return CACHE[city]
    else:
        return None

# Function to update cache periodically
def update_cache():
    for city in CACHE.keys():
        get_weather(city)
    Timer(CACHE_EXPIRY.total_seconds(), update_cache).start()

# API endpoint to fetch weather
@app.route('/weather/<city>', methods=['GET'])
def weather(city):
    result = get_weather(city)
    if result:
        return jsonify(result['data'])
    else:
        return jsonify({'error': 'Weather data not available'}), 404

# Function to store user location preferences
def save_location(city):
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute('INSERT INTO locations (city) VALUES (?)', (city,))
    conn.commit()
    conn.close()

# Route to save user location
@app.route('/save_location', methods=['POST'])
def save_location_route():
    city = request.form['city']
    save_location(city)
    return jsonify({'message': 'Location saved successfully'})

# Initialize cache and database
init_db()
update_cache()

if __name__ == '__main__':
    app.run(debug=True, threaded=True)
