```python
import os
import time
from threading import Lock
from contextlib import contextmanager

class DirectoryManager:
    def __init__(self, base_dir):
        self.base_dir = base_dir
        self.lock = Lock()
        self.cache = {}

    @contextmanager
    def create_directory(self, dir_name, parent=None, retries=5, delay=1):
        full_path = os.path.join(self.base_dir, parent, dir_name) if parent else os.path.join(self.base_dir, dir_name)
        for _ in range(retries + 1):
            try:
                with self.lock:
                    if not os.path.exists(full_path):
                        os.makedirs(full_path)
                        yield full_path
                        self.cache[full_path] = time.time()
                break
            except (OSError, PermissionError) as e:
                if _ < retries:
                    time.sleep(delay)
                else:
                    raise e

    def delete_directory(self, dir_name, parent=None):
        full_path = os.path.join(self.base_dir, parent, dir_name) if parent else os.path.join(self.base_dir, dir_name)
        with self.lock:
            if os.path.exists(full_path):
                os.rmdir(full_path)

class EnvironmentVariableManager:
    def set_variable(self, name, value):
        os.environ[name] = value

    def get_variable(self, name):
        return os.getenv(name)

    def delete_variable(self, name):
        os.unsetenv(name)
