function extractBibleBooks(text, language = 'English') {
    const oldTestamentBooks = [
        // List of Old Testament book names here
    ];
    const newTestamentBooks = [
        // List of New Testament book names here
    ];

    const translations = {
        English: {
            // Translations for English books here
        },
        Spanish: {
            // Translations for Spanish books here
        },
        French: {
            // Translations for French books here
        },
        German: {
            // Translations for German books here
        }
    };

    const regexPatterns = [
        // Regular expression patterns for matching book names here
    ];

    const results = {};

    for (const pattern of regexPatterns) {
        const matches = text.match(pattern);
        if (matches) {
            for (const match of matches) {
                const normalizedMatch = match.toLowerCase();
                if (oldTestamentBooks.includes(normalizedMatch) || newTestamentBooks.includes(normalizedMatch)) {
                    const translatedBookName = translations[language][normalizedMatch] || normalizedMatch;
                    if (!results[translatedBookName]) {
                        results[translatedBookName] = 0;
                    }
                    results[translatedBookName]++;
                } else {
                    console.warn(`Unknown book: ${match}`);
                }
            }
        }
    }

    return Object.entries(results)
        .sort((a, b) => b[1] - a[1])
        .reduce((acc, [key, value]) => ({ ...acc, [key]: value }), {});
}
