const fs = require('fs');
const path = require('path');

function loadModule(modulePath) {
  try {
    const module = require(modulePath);
    return module;
  } catch (error) {
    console.error(`Failed to load module ${modulePath}:`, error);
    throw error;
  }
}

function executeModules(modules, order, context) {
  modules.forEach((module, index) => {
    try {
      const resolvedModule = require.resolve(module);
      if (order.includes(resolvedModule)) {
        const loadedModule = loadModule(resolvedModule);
        loadedModule(context);
      } else {
        console.error(`Module ${resolvedModule} is not in the specified order.`);
      }
    } catch (error) {
      console.error(`Failed to execute module ${module}:`, error);
    }
  });
}

