#include <iostream>
#include <string>
#include <random>
#include <chrono>
#include <mutex>
#include <unordered_set>

class SessionIDGenerator {
public:
  std::string generateSessionID() {
    std::lock_guard<std::mutex> lock(mutex_);
    while (true) {
      std::string sessionID = generateRandomString();
      if (!isDuplicate(sessionID)) {
        addSessionID(sessionID);
        return sessionID;
      }
      std::this_thread::sleep_for(std::chrono::milliseconds(10)); // Retry after delay
    }
  }

  void invalidateSessionID(const std::string& sessionID) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (sessionIDs_.find(sessionID) != sessionIDs_.end()) {
      invalidatedSessionIDs_.insert(sessionID);
    }
  }

private:
  std::mt19937_64 generator_;
  std::uniform_int_distribution<> distribution_;
  std::unordered_set<std::string> sessionIDs_;
  std::unordered_set<std::string> invalidatedSessionIDs_;
  std::mutex mutex_;

  SessionIDGenerator() : generator_(std::random_device{}()), distribution_(0, 63) {}

  std::string generateRandomString() {
    std::string sessionID;
    for (int i = 0; i < 22; ++i) {
      sessionID += base64Alphabet_[distribution_(generator_)];
    }
    return sessionID;
  }

  bool isDuplicate(const std::string& sessionID) {
    return sessionIDs_.find(sessionID) != sessionIDs_.end() || invalidatedSessionIDs_.find(sessionID) != invalidatedSessionIDs_.end();
  }

  void addSessionID(const std::string& sessionID) {
    sessionIDs_.insert(sessionID);
  }

  static const char* base64Alphabet_;
};

const char* SessionIDGenerator::base64Alphabet_ = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

int main() {
  SessionIDGenerator generator;
  std::cout << "Generated Session ID: " << generator.generateSessionID() << std::endl;
  return 0;
}
