// Define the FSA structure
typedef struct {
    int* states;
    int numStates;
    // Other relevant members of the FSA structure
} FSA;

// Define the transition function callback type
typedef int* (*TransitionFunc)(int currentState, int inputSymbol);

// Function to create a new state list based on a specific transition condition
int* createStateList(int* initialStates, int numInitialStates, FSA* fsa, TransitionFunc transFunc, int lastState, int terminationState) {
    // Dynamically allocate memory for the new state list
    int* newStateList = (int*)malloc(numInitialStates * sizeof(int));
    if (newStateList == NULL) {
        return NULL;  // Memory allocation failed
    }

    // Initialize the new state list with initial states
    for (int i = 0; i < numInitialStates; i++) {
        newStateList[i] = initialStates[i];
    }

    // Find the next states based on the transition function
    for (int i = 0; i < numInitialStates; i++) {
        int currentState = newStateList[i];
        if (currentState == terminationState) {
            continue;  // Skip termination state
        }
        int* nextStates = transFunc(currentState, /* inputSymbol */);
        if (nextStates == NULL) {
            free(newStateList);  // Free partially allocated memory
            return NULL;  // Transition function failed
        }

        // Add the next states to the new state list
        for (int j = 0; nextStates[j] != -1; j++) {  // Assuming -1 indicates end of array
            newStateList[lastState + i + j] = nextStates[j];
        }

        free(nextStates);  // Free the temporary next states array
    }

    // Update the 'next' pointer of the last state to point to the new state list
    int* lastStatePointer = &fsa->states[fsa->numStates - 1];
    *lastStatePointer = newStateList;

    return newStateList;
}
