    private readonly Dictionary<string, string> _namespacePrefixes;
    private readonly HttpClient _httpClient;
    private readonly int _maxRetryAttempts;
    private readonly TimeSpan _initialBackoffDelay;

    public DynamicXPathProcessor(Dictionary<string, string> namespacePrefixes, HttpClient httpClient, int maxRetryAttempts, TimeSpan initialBackoffDelay)
    {
        _namespacePrefixes = namespacePrefixes;
        _httpClient = httpClient;
        _maxRetryAttempts = maxRetryAttempts;
        _initialBackoffDelay = initialBackoffDelay;
    }

    public async Task<XElement> GetFirstMatchAsync(string apiEndpoint, string schemaUri, string xpathQuery, string language)
    {
        // Validate user input for XPath queries
        var syntaxTree = XPathNavigator.Parse(xpathQuery);

        // Sanitize input and validate documents against known schemas to protect against XXE attacks

        var documentKey = $"{apiEndpoint}_{schemaUri}";
        XDocument document;

        if (!_documentCache.TryGetValue(documentKey, out document))
        {
            document = await FetchAndCacheDocumentAsync(apiEndpoint, schemaUri);
        }

        try
        {
            // Optimized parsing for large files through streaming
            var xpathCompiled = XPathExpression.Compile(xpathQuery, _namespacePrefixes);
            using (var reader = document.CreateReader())
            {
                while (reader.Read())
                {
                    if (reader.NodeType == XmlNodeType.Element && reader.Name == syntaxTree.Root.Name)
                    {
                        return reader.ReadElementContentAs<XElement>();
                    }
                }
            }
        }
        catch (Exception ex)
        {
            // Handle exceptions and retry logic with exponential backoff
            throw new InvalidOperationException("Error processing XPath query", ex);
        }

        throw new InvalidOperationException("No match found or multiple matches");
    }

    private async Task<XDocument> FetchAndCacheDocumentAsync(string apiEndpoint, string schemaUri)
    {
        for (int attempt = 0; attempt < _maxRetryAttempts; attempt++)
        {
            try
            {
                var response = await _httpClient.GetAsync(apiEndpoint);
                response.EnsureSuccessStatusCode();
                var xmlString = await response.Content.ReadAsStringAsync();

                // Validate document against schema

                return XDocument.Parse(xmlString, LoadOptions.SetLineInfo);
            }
            catch (HttpRequestException ex)
            {
                if (attempt == _maxRetryAttempts - 1)
                    throw new InvalidOperationException("Failed to fetch and cache document after retries", ex);

                await Task.Delay(_initialBackoffDelay * Math.Pow(2, attempt));
            }
        }

        throw new InvalidOperationException("Failed to fetch and cache document");
