using System;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

public class FileTransferService
{
    private readonly HttpClient _httpClient;
    private readonly string _tokenEndpoint;
    private readonly byte[] _encryptionKey;
    private readonly byte[] _iv;
    private readonly int _chunkSize;

    public FileTransferService(HttpClient httpClient, string tokenEndpoint, byte[] encryptionKey, byte[] iv, int chunkSize)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _tokenEndpoint = tokenEndpoint ?? throw new ArgumentNullException(nameof(tokenEndpoint));
        _encryptionKey = encryptionKey ?? throw new ArgumentNullException(nameof(encryptionKey));
        _iv = iv ?? throw new ArgumentNullException(nameof(iv));
        _chunkSize = chunkSize > 0 ? chunkSize : throw new ArgumentException("Chunk size must be greater than 0", nameof(chunkSize));
    }

    public async Task UploadFileAsync(string filePath, CancellationToken cancellationToken)
    {
        if (string.IsNullOrEmpty(filePath))
            throw new ArgumentException("File path cannot be null or empty", nameof(filePath));

        using var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read);
        await UploadFileAsync(fileStream, cancellationToken);
    }

    public async Task UploadFileAsync(Stream fileStream, CancellationToken cancellationToken)
    {
        try
        {
            var token = await AuthenticateAsync();
            var uploadUrl = await GetUploadUrlAsync(token);

            using (var content = new MultipartFormDataContent())
            {
                var encryptedFileStream = EncryptStream(fileStream);
                var streamContent = new StreamContent(encryptedFileStream);
                streamContent.Headers.ContentDisposition = new System.Net.Http.Headers.ContentDispositionHeaderValue("form-data")
                {
                    Name = "file",
                    FileName = Path.GetFileName(encryptedFileStream.Name)
                };
                content.Add(streamContent);

                using (var response = await _httpClient.PostAsync(uploadUrl, content, cancellationToken))
                {
                    response.EnsureSuccessStatusCode();
                }
            }
        }
        catch (Exception ex) when (ex is HttpRequestException || ex is IOException)
        {
            throw new FileTransferException("Failed to upload file due to network or I/O issues", ex);
        }
        catch (Exception ex)
        {
            throw new FileTransferException("Failed to upload file", ex);
        }
    }

    private async Task<string> AuthenticateAsync()
    {
        var response = await _httpClient.GetAsync(_tokenEndpoint, HttpCompletionOption.ResponseHeadersRead);
        response.EnsureSuccessStatusCode();

        using var content = await response.Content.ReadAsByteArrayAsync();
        // Parse token from response
        return Encoding.UTF8.GetString(content);
    }

    private async Task<string> GetUploadUrlAsync(string token)
    {
        var headers = new Dictionary<string, string>
        {
            { "Authorization", $"Bearer {token}" }
        };

        var response = await _httpClient.GetAsync("https://api.cloudstorageprovider.com/upload/geturl", new CancellationTokenSource().Token, headers);
        response.EnsureSuccessStatusCode();

        using var content = await response.Content.ReadAsStringAsync();
        // Parse upload URL from response
        return content;
    }

    private Stream EncryptStream(Stream fileStream)
    {
        var memoryStream = new MemoryStream();
        using (var aes = Aes.Create())
        {
            aes.Key = _encryptionKey;
            aes.IV = _iv;

            using (var encryptor = aes.CreateEncryptor(aes.Key, aes.IV))
            using (var cryptoStream = new CryptoStream(memoryStream, encryptor, CryptoStreamMode.Write))
            {
                await fileStream.CopyToAsync(cryptoStream);
            }
        }

        memoryStream.Position = 0;
        return memoryStream;
    }

    public class FileTransferException : Exception
    {
        public FileTransferException(string message, Exception innerException) : base(message, innerException)
        {
        }
    }
}
