    public static List<Integer> simulateFSAMachine(int[] states, int size, StateMachine stateMachine, int currentStateIndex) throws Exception {
        // Simulate FSA and handle loops and dead ends
        List<Integer> reachableStates = new ArrayList<>();
        Set<Integer> visitedStates = new HashSet<>();

        while (currentStateIndex >= 0 && !visitedStates.contains(currentStateIndex)) {
            reachableStates.add(currentStateIndex);
            visitedStates.add(currentStateIndex);

            int nextStateIndex = stateMachine.getNextState(currentStateIndex);
            if (nextStateIndex == currentStateIndex) { // Dead end
                break;
            }
            if (visitedStates.contains(nextStateIndex)) { // Loop detected
                throw new Exception("Infinite loop detected");
            }
            currentStateIndex = nextStateIndex;
        }

        return reachableStates;
    }
