using System;
using System.IO;
using Microsoft.Web.Administration;

public enum WebsiteOperation
{
    Add,
    Start,
    Stop,
    Remove
}

public class DirectoryPath
{
    public string Path { get; set; }
    public string ApplicationPoolName { get; set; }
    public string Bindings { get; set; }
    // Other properties as needed
}

public class TaskResult
{
    public bool Success { get; set; }
    public string Message { get; set; }

    public static TaskResult Failed(string message)
    {
        return new TaskResult { Success = false, Message = message };
    }

    public static TaskResult Succeeded(string message)
    {
        return new TaskResult { Success = true, Message = message };
    }
}

public class WebsiteManager
{
    private ServerManager _serverManager;

    public WebsiteManager()
    {
        _serverManager = new ServerManager();
    }

    public async Task<TaskResult> ManageWebsiteLifecycle(WebsiteOperation operation, DirectoryPath directory)
    {
        if (!Directory.Exists(directory.Path))
        {
            return TaskResult.Failed("Directory does not exist.");
        }

        string configFilePath = Path.Combine(directory.Path, "web.config");
        if (!File.Exists(configFilePath))
        {
            return TaskResult.Failed("web.config file is missing.");
        }

        string siteName = Path.GetFileName(directory.Path);

        switch (operation)
        {
            case WebsiteOperation.Add:
                if (_serverManager.Sites[siteName] != null)
                    return TaskResult.Failed("Site already exists.");

                Site newSite = _serverManager.Sites.CreateElement("site");
                newSite.Name = siteName;
                newSite.physicalPath = directory.Path;

                if (!string.IsNullOrEmpty(directory.ApplicationPoolName))
                {
                    ApplicationPool appPool = _serverManager.ApplicationPools[directory.ApplicationPoolName];
                    if (appPool == null)
                        return TaskResult.Failed("Application pool does not exist.");
                }

                _serverManager.Sites.Add(newSite);
                break;

            case WebsiteOperation.Start:
                Site existingSite = _serverManager.Sites[siteName];
                if (existingSite != null && existingSite.state == ObjectState.Stopped)
                    existingSite.Stop();
                else
                    return TaskResult.Failed("Site is already running or does not exist.");
                break;

            case WebsiteOperation.Stop:
                existingSite = _serverManager.Sites[siteName];
                if (existingSite != null && existingSite.state == ObjectState.Started)
                    existingSite.Stop();
                else
                    return TaskResult.Failed("Site is already stopped or does not exist.");
                break;

            case WebsiteOperation.Remove:
                existingSite = _serverManager.Sites[siteName];
                if (existingSite != null)
                {
                    foreach (var appPool in _serverManager.ApplicationPools)
                    {
                        if (appPool.applications.Count > 0 && appPool.name.Contains(siteName))
                            appPool.Stop();
                    }
                    existingSite.Delete();
                }
                else
                    return TaskResult.Failed("Site does not exist.");
                break;
        }

        await _serverManager.CommitChangesAsync();
        return TaskResult.Succeeded($"Operation {operation} completed successfully for site {siteName}.");
    }
}
