import importlib
import unittest
import logging
import threading
from concurrent.futures import ThreadPoolExecutor, TimeoutError
from html_reporter import HTMLTestRunner

def execute_unit_tests(module_name, parallelism=1, skip_tests=None, flaky_threshold=3):
    try:
        module = importlib.import_module(module_name)
        loader = unittest.TestLoader()
        suite = loader.discover(start_dir='.', pattern=f'{module_name}*.py')

        if skip_tests:
            suite = unittest.TestSuite(filter(lambda test: not any(skip in test.id() for skip in skip_tests), suite))

        with ThreadPoolExecutor(max_workers=parallelism) as executor:
            results = list(executor.map(run_test, suite, timeout=30))

        flaky_tests = [test for test, result in results if isinstance(result, FlakyTestResult)]
        for test, result in flaky_tests:
            attempt = 1
            while attempt < flaky_threshold and not result.success:
                logging.warning(f"Flaky test detected: {test.id()}. Retrying...")
                result = run_test(test)
                attempt += 1

        with open('test_report.html', 'wb') as f:
            HTMLTestRunner(output=f).run(suite)

    except Exception as e:
        logging.error(f"Error executing tests for module '{module_name}': {e}")

def run_test(test):
    try:
        test()
        return TestResult(success=True, exception=None)
    except AssertionError as e:
        return TestResult(success=False, exception=str(e))
    except Exception as e:
        return FlakyTestResult(success=False, exception=str(e))

class TestResult:
    def __init__(self, success, exception):
        self.success = success
        self.exception = exception

class FlakyTestResult(TestResult):
    pass
