#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pem.h>
#include <openssl/err.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    int cipher_type;
    int key_size;
    int mode;
} CryptoContext;

CryptoContext* create_cipher_context(int cipher_type, int key_size, int mode) {
    CryptoContext *context = malloc(sizeof(CryptoContext));
    context->cipher_type = cipher_type;
    context->key_size = key_size;
    context->mode = mode;

    context->ctx = EVP_CIPHER_CTX_new();
    if (!context->ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        free(context);
        return NULL;
    }

    // Initialize the cipher context with the chosen algorithm
    switch (cipher_type) {
        case EVP_aes_128_gcm:
        case EVP_aes_192_gcm:
        case EVP_aes_256_gcm:
            if (!EVP_EncryptInit_ex(context->ctx, cipher_type, NULL, NULL, NULL)) {
                fprintf(stderr, "Failed to initialize GCM mode\n");
                EVP_CIPHER_CTX_free(context->ctx);
                free(context);
                return NULL;
            }
            break;
        case EVP_aes_128_cbc:
        case EVP_aes_192_cbc:
        case EVP_aes_256_cbc:
            if (!EVP_EncryptInit_ex(context->ctx, cipher_type, NULL, NULL, NULL)) {
                fprintf(stderr, "Failed to initialize CBC mode\n");
                EVP_CIPHER_CTX_free(context->ctx);
                free(context);
                return NULL;
            }
            break;
        default:
            fprintf(stderr, "Invalid cipher type\n");
            EVP_CIPHER_CTX_free(context->ctx);
            free(context);
            return NULL;
    }

    // Generate a random IV
    unsigned char iv[EVP_CIPHER_block_size(cipher_type)];
    if (!RAND_bytes(iv, sizeof(iv))) {
        fprintf(stderr, "Failed to generate IV\n");
        EVP_CIPHER_CTX_free(context->ctx);
        free(context);
        return NULL;
    }

    // Set the IV
    if (mode == EVP_EncryptMode) {
        if (!EVP_EncryptInit_ex(context->ctx, NULL, NULL, NULL, iv)) {
            fprintf(stderr, "Failed to set IV for encryption\n");
            EVP_CIPHER_CTX_free(context->ctx);
            free(context);
            return NULL;
        }
    } else if (mode == EVP_DecryptMode) {
        if (!EVP_EncryptInit_ex(context->ctx, NULL, NULL, NULL, iv)) {
            fprintf(stderr, "Failed to set IV for decryption\n");
            EVP_CIPHER_CTX_free(context->ctx);
            free(context);
            return NULL;
        }
    }

    return context;
}

void destroy_cipher_context(CryptoContext *context) {
    if (context) {
        EVP_CIPHER_CTX_free(context->ctx);
        free(context);
    }
}
