from concurrent.futures import ThreadPoolExecutor, as_completed
import time

class AsyncTaskQueueManager:
    class TaskCustomizerCallback:
        def __call__(self, task):
            raise NotImplementedError("This method should be overridden by subclasses")

    class TaskHealthChecker:
        def isHealthy(self, task):
            raise NotImplementedError("This method should be overridden by subclasses")

    def __init__(self, max_size=100, concurrency_level=5, task_customizer=None, health_checker=None):
        self.max_size = max_size
        self.concurrency_level = concurrency_level
        self.task_customizer = task_customizer or (lambda x: x)
        self.health_checker = health_checker or (lambda x: True)
        self.executor = ThreadPoolExecutor(max_workers=concurrency_level)
        self.queue = []

    def initialize_task_queue(self, max_size=None, concurrency_level=None):
        if max_size is not None:
            self.max_size = max_size
        if concurrency_level is not None:
            self.concurrency_level = concurrency_level
            self.executor = ThreadPoolExecutor(max_workers=concurrency_level)

    def submit_task(self, task):
        if len(self.queue) >= self.max_size:
            raise ValueError("Task queue is at maximum capacity")
        custom_task = self.task_customizer(task)
        future = self.executor.submit(custom_task.run)
        self.queue.append((future, custom_task))
        return future

    def wait_for_all_tasks(self):
        for future, task in self.queue:
            try:
                result = future.result()
                if not self.health_checker.isHealthy(result):
                    # Handle failed tasks with backoff or retry logic
                    time.sleep(1)  # Simple backoff example
            except Exception as e:
                print(f"Task failed: {e}")
        self.queue = []

    def shutdown(self):
        self.executor.shutdown()
