class ScriptManager {
  constructor(apiUrl) {
    this.apiUrl = apiUrl;
    this.scriptCache = {};
  }

  async fetchScripts() {
    try {
      const response = await fetch(this.apiUrl);
      if (!response.ok) throw new Error('Network response was not ok');
      return await response.json();
    } catch (error) {
      console.error('Error fetching scripts:', error);
      throw error;
    }
  }

  manageCache(scripts) {
    const now = Date.now();
    for (const script of scripts) {
      if (script.cache && script.version) {
        this.scriptCache[script.src] = { version: script.version, lastFetched: now };
      }
    }
  }

  async renderScripts(containerId) {
    const container = document.getElementById(containerId);
    const scripts = await this.fetchScripts();
    this.manageCache(scripts);

    for (const script of scripts) {
      if (!script.src && !script.code) continue;
      try {
        const scriptElement = document.createElement('script');
        scriptElement.type = script.type || 'text/javascript';

        if (script.src) {
          scriptElement.src = script.src;
          if (this.scriptCache[script.src] && this.scriptCache[script.src].version !== script.version) {
            scriptElement.async = true; // Fetch and execute asynchronously
            scriptElement.defer = false; // Execute before window.onload
            delete this.scriptCache[script.src]; // Evict old cache entry
          } else if (this.scriptCache[script.src]) {
            continue; // Skip loading if already cached and up-to-date
          }
        } else if (script.code) {
          scriptElement.innerHTML = script.code;
        }

        container.appendChild(scriptElement);
      } catch (error) {
        console.error('Error rendering script:', error);
      }
    }
  }
}

// Usage example:
const scriptManager = new ScriptManager('/api/scripts');
scriptManager.renderScripts('footer-scripts');
