        }

        std::vector<std::pair<int, std::string>> keyValuePairs;
        int key;
        std::string value;
        while (file >> key >> value) {
            keyValuePairs.push_back({key, value});
        }

        for (const auto& pair : keyValuePairs) {
            addNode(pair.first, pair.second);
        }

        file.close();
        return true;
    }

    bool resizeNodes(size_t newCapacity) {
        std::lock_guard<std::mutex> lock(mutex);
        if (newCapacity <= capacity) {
            return false;
        }

        nodes.resize(newCapacity);
        capacity = newCapacity;

        logInfo("Node array resized to " + std::to_string(capacity));

        return true;
    }

    bool serializeToJson(rapidjson::Document& doc) const {
        rapidjson::Value nodeArray(rapidjson::kArrayType);

        for (const auto& node : nodes) {
            rapidjson::Value nodeObj(rapidjson::kObjectType);
            nodeObj.AddMember("key", node.key, doc.GetAllocator());
            nodeObj.AddMember("value", node.value.c_str(), doc.GetAllocator());
            nodeArray.PushBack(nodeObj, doc.GetAllocator());
        }

        doc.SetObject();
        doc.AddMember("nodes", nodeArray, doc.GetAllocator());

        return true;
    }

    bool deserializeFromJson(const rapidjson::Document& doc) {
        if (!doc.IsObject()) {
            return false;
        }

        const rapidjson::Value& nodeArray = doc["nodes"];
        if (!nodeArray.IsArray()) {
            return false;
        }

        nodes.clear();
        for (const auto& nodeObj : nodeArray.GetArray()) {
            Node node;
            node.key = nodeObj["key"].GetInt();
            node.value = nodeObj["value"].GetString();
            // Initialize creation and last access times
            nodes.push_back(node);
        }

        return true;
    }

    bool addNode(int key, const std::string& value) {
        if (nodes.size() >= capacity) {
            if (!resizeNodes(capacity * 2)) {
                logError("Failed to resize node array during node addition");
                return false;
            }
        }

        Node node = {key, value, std::chrono::system_clock::now(), std::chrono::system_clock::now()};
        nodes.push_back(node);

        logInfo("Node added with key: " + std::to_string(key));

        return true;
    }

    bool removeNode(int key) {
        auto it = std::find_if(nodes.begin(), nodes.end(), [key](const Node& node) { return node.key == key; });
        if (it != nodes.end()) {
            nodes.erase(it);
            logInfo("Node removed with key: " + std::to_string(key));
            return true;
        }

        logWarning("Node not found with key: " + std::to_string(key));
        return false;
    }

    bool updateNode(int key, const std::string& value) {
        auto it = std::find_if(nodes.begin(), nodes.end(), [key](const Node& node) { return node.key == key; });
        if (it != nodes.end()) {
            it->value = value;
            it->lastAccessTime = std::chrono::system_clock::now();
            logInfo("Node updated with key: " + std::to_string(key));
            return true;
        }

        logWarning("Node not found with key: " + std::to_string(key));
        return false;
    }

    bool saveNodesToDatabase() {
        for (const auto& node : nodes) {
            redisClient.set(std::to_string(node.key), node.value);
        }
        logInfo("Nodes saved to database");

        return true;
    }

    bool loadNodesFromDatabase() {
        nodes.clear();
        std::vector<std::string> keys = redisClient.keys("*");
        for (const auto& key : keys) {
            std::string value = redisClient.get(key);
            if (!value.empty()) {
                addNode(std::stoi(key), value);
            }
        }
        logInfo("Nodes loaded from database");

        return true;
    }

    void logInfo(const std::string& message) {
        log(message, "INFO");
    }

    void logWarning(const std::string& message) {
        log(message, "WARNING");
    }

    void logError(const std::string& message) {
        log(message, "ERROR");
    }

private:
    void log(const std::string& message, const std::string& level) {
        std::chrono::system_clock::time_point now = std::chrono::system_clock::now();
        std::time_t nowTime = std::chrono::system_clock::to_time_t(now);
        std::tm nowTm = *std::localtime(&nowTime);

        logFile << std::put_time(&nowTm, "%Y-%m-%d %H:%M:%S") << " [" << level << "] " << message << std::endl;
    }
};

int main() {
    NodeManager nodeManager(10);
    if (!nodeManager.loadNodesFromConfig("config.txt")) {
        return 1;
    }

    // Example operations
    nodeManager.addNode(1, "value1");
    nodeManager.updateNode(1, "new_value1");
    nodeManager.removeNode(1);

    nodeManager.saveNodesToDatabase();
    if (!nodeManager.loadNodesFromDatabase()) {
        return 1;
    }

    return 0;
}
