### Python File Statistics Program

```python
import os
from pathlib import Path
import logging
from multiprocessing import Pool

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def count_file_stats(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            text = file.read()
            lines = len(text.splitlines())
            words = len(text.split())
            characters = len(text)
            return lines, words, characters
    except Exception as e:
        logging.error(f"Error processing {file_path}: {e}")
        return 0, 0, 0

def process_directory(directory, output_file=None, exclude_types=['.md', '.pdf']):
    total_lines, total_words, total_characters = 0, 0, 0
    directory_path = Path(directory)

    with Pool() as pool:
        results = pool.map(count_file_stats, [str(path) for path in directory_path.rglob('*') if not any(path.suffix == ext for ext in exclude_types)])

    for lines, words, characters in results:
        total_lines += lines
        total_words += words
        total_characters += characters

    if output_file:
        with open(output_file, 'w', encoding='utf-8') as out_file:
            out_file.write(f"Total Lines: {total_lines}\n")
            out_file.write(f"Total Words: {total_words}\n")
            out_file.write(f"Total Characters: {total_characters}\n")

    return total_lines, total_words, total_characters
```

