import os
import threading
from typing import Optional

class DirectoryManager:
    def __init__(self, base_dir: str):
        self.base_dir = base_dir
        self.lock = threading.Lock()
        self.retry_attempts = 3
        self.retry_delay = 2

    def create_directory(self, directory_name: str) -> bool:
        full_path = os.path.join(self.base_dir, directory_name)
        attempt = 0
        while attempt < self.retry_attempts:
            try:
                with self.lock:
                    if not os.path.exists(full_path):
                        os.makedirs(full_path)
                        return True
            except OSError as e:
                print(f"Error creating directory: {e}")
                attempt += 1
                time.sleep(self.retry_delay)
        return False

    def delete_directory(self, directory_name: str) -> bool:
        full_path = os.path.join(self.base_dir, directory_name)
        try:
            with self.lock:
                if os.path.exists(full_path):
                    os.rmdir(full_path)
                    return True
        except OSError as e:
            print(f"Error deleting directory: {e}")
        return False

    def create_temp_file(self) -> Optional[str]:
        temp_dir = self.create_directory("temp")
        if temp_dir:
            return os.path.join(temp_dir, "tempfile.tmp")
        return None

    def delete_temp_file(self, file_path: str) -> bool:
        try:
            os.remove(file_path)
            return True
        except OSError as e:
            print(f"Error deleting temporary file: {e}")
        return False
```

