```c
#include <stdlib.h>
#include <string.h>
#include <errno.h>

/**
 * Appends a directory path to a given file path, handling size limits and edge cases.
 *
 * @param filePath The existing file path to which the directory will be appended.
 * @param directoryPath The directory path to append.
 * @param resultSize The maximum size of the resulting full path including null terminator.
 * @return A dynamically allocated string containing the truncated or complete path,
 *         or NULL if memory allocation fails. Caller must free the returned string.
 */
char* appendDirectoryWithLimit(const char* filePath, const char* directoryPath, size_t resultSize) {
    if (filePath == NULL || directoryPath == NULL) {
        errno = EINVAL;
        return NULL;
    }

    // Calculate necessary space for new path
    size_t dirLength = strlen(directoryPath);
    size_t fileLength = strlen(filePath);

    if (dirLength + fileLength + 2 > resultSize) {
        errno = ENAMETOOLONG;
        return NULL; // Not enough space to append directory without exceeding limit
    }

    char* newPath = malloc(resultSize * sizeof(char));
    if (newPath == NULL) {
        return NULL; // Memory allocation failed
    }

    strcpy(newPath, filePath);
    size_t totalLength = strlen(newPath);

    // Ensure there's no trailing '/' before appending
    if (filePath[totalLength - 1] != '/') {
        newPath[totalLength++] = '/';
    }
    strncpy(newPath + totalLength, directoryPath, resultSize - totalLength - 1);
    newPath[resultSize - 1] = '\0'; // Ensure null-termination

    return newPath;
}
