```javascript
// Define the renderFooterScripts function
function renderFooterScripts(scripts) {
    // Initialize variables
    const cache = {};
    let spinner;

    // Helper function to fetch scripts from an external API
    async function fetchScripts(url, retries = 3, delay = 1000) {
        try {
            const response = await fetch(url);
            if (!response.ok) throw new Error('Network response was not ok');
            return response.json();
        } catch (error) {
            if (retries > 0) {
                setTimeout(() => fetchScripts(url, retries - 1, delay), delay);
            } else {
                console.error('Failed to fetch scripts after multiple attempts:', error);
                throw error;
            }
        }
    }

    // Helper function to check script usage
    function isScriptInUse(script) {
        return document.querySelector(`script[src="${script.src}"]`) !== null;
    }

    // Helper function to render scripts
    function renderScripts() {
        const footer = document.createElement('footer');
        scripts.forEach(script => {
            const scriptElement = document.createElement('script');
            scriptElement.type = script.type || 'text/javascript';
            scriptElement.src = script.src || '';
            if (script.code) {
                scriptElement.textContent = script.code;
            }
            scriptElement.async = true;
            footer.appendChild(scriptElement);
        });
        document.body.appendChild(footer);
    }

    // Main function to orchestrate the rendering process
    async function main() {
        try {
            spinner = document.createElement('div');
            spinner.textContent = 'Loading scripts...';
            document.body.appendChild(spinner);

            let fetchedScripts = cache.scripts || await fetchScripts('/api/scripts');
            cache.scripts = fetchedScripts;

            const usedScripts = fetchedScripts.filter(script => isScriptInUse(script));
            const newScripts = fetchedScripts.filter(script => !isScriptInUse(script));

            if (newScripts.length > 0) {
                renderScripts(newScripts);
                console.log('New scripts rendered:', newScripts.map(s => s.src));
            } else {
                console.log('No new scripts to render.');
            }

            if (spinner.parentNode) spinner.parentNode.removeChild(spinner);
        } catch (error) {
            console.error('Error rendering scripts:', error);
            if (spinner.parentNode) spinner.parentNode.removeChild(spinner);
        }
    }

    // Call the main function
    main();
}

// Example usage:
const scripts = [
    { code: 'console.log("Hello, world!");', type: 'text/javascript' },
    { src: '/path/to/external/script.js' }
];
renderFooterScripts(scripts);
