public class SecurePasswordManager : IDisposable
{
    private readonly ILogger<SecurePasswordManager> _logger;
    private readonly IMemoryCache _cache;
    private readonly ConcurrentDictionary<string, Func<string, string>> _hashers;
    private int _selectedHasherIndex = 0;

    public SecurePasswordManager(ILogger<SecurePasswordManager> logger, IMemoryCache cache)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));

        _hashers = new ConcurrentDictionary<string, Func<string, string>>
        {
            { "SHA-256", GenerateSha256Hash },
            { "bcrypt", BCrypt.Net.BCrypt.HashPassword },
            { "Argon2", Argon2.Default.CreateHash }
        };
    }

    public void AddUser(string username, string password)
    {
        if (string.IsNullOrEmpty(username) || string.IsNullOrEmpty(password))
        {
            _logger.LogError("Username and password cannot be null or empty.");
            throw new ArgumentException("Username and password cannot be null or empty.");
        }

        var hasher = _hashers.ElementAt(_selectedHasherIndex).Value;
        var salt = GenerateSalt();
        var hashedPassword = hasher($"{password}{salt}");
        var userHashEntry = new UserHashEntry { Username = username, HashedPassword = hashedPassword, Salt = salt };

        // Simulate database storage
        Database.AddUserHash(userHashEntry);
    }

    public bool VerifyPassword(string username, string password)
    {
        if (string.IsNullOrEmpty(username) || string.IsNullOrEmpty(password))
        {
            _logger.LogError("Username and password cannot be null or empty.");
            throw new ArgumentException("Username and password cannot be null or empty.");
        }

        var userHashEntry = Database.GetUserHashByUsername(username);
        if (userHashEntry == null)
        {
            return false;
        }

        var hasher = _hashers.ElementAt(_selectedHasherIndex).Value;
        var hashedPassword = hasher($"{password}{userHashEntry.Salt}");

        // Simulate database verification
        return userHashEntry.HashedPassword == hashedPassword;
    }

    public void SwitchToNextHashAlgorithm()
    {
        _selectedHasherIndex = (_selectedHasherIndex + 1) % _hashers.Count;
    }

    private string GenerateSha256Hash(string input)
    {
        // Implementation of SHA-256 hash generation
        throw new NotImplementedException();
    }

    private string GenerateSalt()
    {
        return BCrypt.Net.BCrypt.GenerateSalt();
    }

    public void Dispose()
    {
        // Cleanup resources if necessary
    }
}

public class UserHashEntry
{
    public string Username { get; set; }
    public string HashedPassword { get; set; }
    public string Salt { get; set; }
}

public static class Database
{
    private static readonly ConcurrentDictionary<string, UserHashEntry> _userHashes = new ConcurrentDictionary<string, UserHashEntry>();

    public static void AddUserHash(UserHashEntry userHash)
    {
        _userHashes[userHash.Username] = userHash;
    }

    public static UserHashEntry GetUserHashByUsername(string username)
    {
        if (_userHashes.TryGetValue(username, out var userHash))
        {
            return userHash;
        }
        return null;
    }
}
