#include <stdio.h>
#include <stdlib.h>
#include <dirent.h>
#include <string.h>
#include <zlib.h>

#define MAX_LINE_LENGTH 1024
#define MAX_FIELDS 100
#define MAX_RETRIES 3

typedef struct {
    char filename[256];
    FILE *file;
} LogFile;

LogFile* open_log_files(const char *directory, int *num_files) {
    DIR *dir = opendir(directory);
    if (!dir) {
        perror("Failed to open directory");
        return NULL;
    }

    // Count the number of files
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;
        (*num_files)++;
    }
    closedir(dir);

    LogFile *files = malloc((*num_files) * sizeof(LogFile));
    if (!files) {
        perror("Failed to allocate memory for files");
        return NULL;
    }

    // Open the files
    dir = opendir(directory);
    int i = 0;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        snprintf(files[i].filename, sizeof(files[i].filename), "%s/%s", directory, entry->d_name);

        // Check for compressed files
        char *ext = strrchr(files[i].filename, '.');
        if (ext && (strcmp(ext, ".gz") == 0)) {
            gzFile file = gzdopen(open(files[i].filename, "rb"), "r");
            if (!file) {
                perror("Failed to open compressed file");
                free(files);
                return NULL;
            }
            files[i].file = (FILE *)file;
        } else {
            files[i].file = fopen(files[i].filename, "r");
            if (!files[i].file) {
                perror("Failed to open log file");
                free(files);
                return NULL;
            }
        }

        i++;
    }
    closedir(dir);

    return files;
}

void close_log_files(LogFile *files, int num_files) {
    for (int i = 0; i < num_files; i++) {
        if (files[i].file) {
            fclose(files[i].file);
        }
    }
    free(files);
}

double process_log_file(FILE *file) {
    char line[MAX_LINE_LENGTH];
    double sum = 0.0;
    int count = 0;

    while (fgets(line, MAX_LINE_LENGTH, file)) {
        char *fields[MAX_FIELDS];
        int num_fields = 0;

        // Split the line into fields
        char *token = strtok(line, " \t");
        while (token && num_fields < MAX_FIELDS) {
            fields[num_fields++] = token;
            token = strtok(NULL, " \t");
        }

        if (num_fields >= 2) {
            char *endptr;
            double value1 = strtod(fields[num_fields - 2], &endptr);
            double value2 = strtod(fields[num_fields - 1], &endptr);

            // Check for successful conversion
            if (*endptr == '\0') {
                sum += (value1 + value2) / 2.0;
                count++;
            }
        }
    }

    return count > 0 ? sum / count : 0.0;
}

int main() {
    const char *directory = "log_directory";
    int num_files;

    LogFile *files = open_log_files(directory, &num_files);
    if (!files)
        return EXIT_FAILURE;

    for (int i = 0; i < num_files; i++) {
        double average = process_log_file(files[i].file);
        printf("Average of %s: %.2f\n", files[i].filename, average);
    }

    close_log_files(files, num_files);
    return EXIT_SUCCESS;
}
