@app.route('/login/authorized')
@google.authorized_handler
def authorized(resp):
    resp = google.authorized_response()
    if resp is None or resp.get('access_token') is None:
        return 'Access denied: reason={0} error={1}'.format(
            request.args['error_reason'],
            request.args['error_description']
        )
    session['google_token'] = (resp['access_token'], '')
    me = google.get('userinfo')
    user_info = me.data
    user = User.query.filter_by(email=user_info['email']).first()
    if not user:
        new_user = User(
            email=user_info['email'],
            password=password_policy.generate_password(),
            active=True,
        )
        db.session.add(new_user)
        db.session.commit()
        user = new_user
    login_user(user)
    return 'You are logged in as: {0}'.format(user.email)

@app.route('/logout')
@login_required
def logout():
    logout_user()
    return 'You are logged out'

@app.route('/')
@login_required
def index():
    return 'Welcome to the secure application!'

@app.route('/command', methods=['POST'])
@login_required
def run_command():
    command_chain = request.form['commands']
    commands = command_chain.split('&&')
    for command in commands:
        process = subprocess.Popen(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        try:
            output, error = process.communicate(timeout=30)  # Timeout of 30 seconds
            if process.returncode != 0:
                raise Exception(f"Command failed: {error.decode('utf-8')}")
        except subprocess.TimeoutExpired:
            os.kill(process.pid, signal.SIGKILL)
            raise Exception("Command timed out")
    return 'All commands executed successfully'

if __name__ == '__main__':
    db.create_all()
    app.run(debug=True)
```

