from typing import Callable, Optional

class AsyncTaskQueueManager:
    def __init__(self, max_size: int = 100, concurrency_level: int = 5):
        self.max_size = max_size
        self.concurrency_level = concurrency_level
        self.task_queue = asyncio.Queue(maxsize=self.max_size)
        self.executor = asyncio.Semaphore(self.concurrency_level)
        self.logger = asyncio.get_event_loop().create_task(self.log_operations())

    async def log_operations(self):
        while True:
            operation, details = await asyncio.to_thread(self.task_queue.get)
            if operation == 'enqueue':
                self.logger.info(f"Enqueued task: {details}")
            elif operation == 'dequeue':
                self.logger.info(f"Dequeued task: {details}")
            elif operation == 'error':
                self.logger.error(f"Error in task: {details}")
            self.task_queue.task_done()

    def initialize_task_queue(self, max_size: Optional[int] = None, concurrency_level: Optional[int] = None):
        if max_size is not None:
            self.max_size = max_size
        if concurrency_level is not None:
            self.concurrency_level = concurrency_level
        self.task_queue = asyncio.Queue(maxsize=self.max_size)
        self.executor = asyncio.Semaphore(self.concurrency_level)

    def set_task_customizer(self, customizer: Callable):
        # Placeholder for task customization logic
        pass

    async def enqueue_task(self, task: asyncio.Task):
        if not await self.task_queue.put(task):
            raise ValueError("Task queue is full")
        await self.logger.info(f"Enqueued task: {task}")

    async def dequeue_task(self) -> asyncio.Task:
        try:
            task = await self.task_queue.get()
            await self.logger.info(f"Dequeued task: {task}")
            return task
        except asyncio.QueueEmpty:
            raise ValueError("Task queue is empty")

    def set_task_customizer_callback(self, callback: Callable):
        # Placeholder for external customization logic
        pass

    async def run_tasks(self):
        while True:
            task = await self.dequeue_task()
            try:
                async with self.executor:
                    await asyncio.ensure_future(task)
            except Exception as e:
                await self.logger.error(f"Error in task: {e}")
