<?php

// Define constants for configuration
define('DB_HOST', 'localhost');
define('DB_NAME', 'auth_db');
define('DB_USER', 'root');
define('DB_PASS', '');

// Include necessary libraries
require_once 'vendor/autoload.php';

use Firebase\JWT\JWT;
use Firebase\JWT\Key;

class Authentication {
    private $db;
    private $salt_length = 16;
    private $token_algorithm = 'HS256';
    private $token_expiration = 3600; // 1 hour

    public function __construct() {
        $this->db = new PDO("mysql:host=" . DB_HOST . ";dbname=" . DB_NAME, DB_USER, DB_PASS);
        $this->db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
    }

    private function generateSalt($length) {
        return bin2hex(random_bytes($length));
    }

    private function hashPassword($password, $salt) {
        return password_hash($password . $salt, PASSWORD_BCRYPT);
    }

    public function registerUser($username, $password) {
        $salt = $this->generateSalt($this->salt_length);
        $hashed_password = $this->hashPassword($password, $salt);

        $stmt = $this->db->prepare("INSERT INTO users (username, password, salt) VALUES (:username, :password, :salt)");
        $stmt->execute(['username' => $username, 'password' => $hashed_password, 'salt' => $salt]);

        return $stmt->rowCount();
    }

    public function loginUser($username, $password) {
        $stmt = $this->db->prepare("SELECT id, password, salt FROM users WHERE username = :username");
        $stmt->execute(['username' => $username]);
        $user = $stmt->fetch(PDO::FETCH_ASSOC);

        if ($user && password_verify($password . $user['salt'], $user['password'])) {
            $token = JWT::encode([
                'sub' => $user['id'],
                'iat' => time(),
                'exp' => time() + $this->token_expiration
            ], Key::createKey('your_secret_key', $this->token_algorithm));

            return ['status' => 'success', 'token' => $token];
        } else {
            return ['status' => 'error', 'message' => 'Invalid credentials'];
        }
    }

    public function generateToken($length = 32) {
        $characters = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
        $token = '';
        for ($i = 0; $i < $length; $i++) {
            $index = rand(0, strlen($characters) - 1);
            $token .= $characters[$index];
        }
        return $token;
    }

    public function authenticateToken($token) {
        try {
            JWT::decode($token, Key::createKey('your_secret_key', $this->token_algorithm), [$this->token_algorithm]);
            return true;
        } catch (Exception $e) {
            return false;
        }
    }

    // Other methods for session management, caching, rate limiting can be implemented here
}

// Example usage:
$auth = new Authentication();
$user_id = $auth->registerUser('john_doe', 'password123');
if ($user_id) {
    echo "User registered successfully!";
} else {
    echo "Failed to register user.";
}

$result = $auth->loginUser('john_doe', 'password123');
if ($result['status'] === 'success') {
    echo "Login successful! Token: " . $result['token'];
} else {
    echo $result['message'];
}
?>
