#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <functional>
#include <unordered_map>
#include <mutex>
#include <condition_variable>

class JSONParser {
public:
    static std::string objectToString(const nlohmann::json& obj) {
        return obj.dump();
    }

    static nlohmann::json stringToObject(const std::string& str) {
        return nlohmann::json::parse(str);
    }
};

class FactoryRegistry {
private:
    std::unordered_map<std::string, std::function<nlohmann::json()>> registry;
    std::mutex mutex;
    std::condition_variable cv;

public:
    void registerFactory(const std::string& key, const std::function<nlohmann::json()>& factory) {
        std::unique_lock<std::mutex> lock(mutex);
        if (registry.find(key) == registry.end()) {
            registry[key] = factory;
            cv.notify_all();
        }
    }

    bool unregisterFactory(const std::string& key) {
        std::unique_lock<std::mutex> lock(mutex);
        auto it = registry.find(key);
        if (it != registry.end()) {
            registry.erase(it);
            return true;
        }
        return false;
    }

    nlohmann::json createInstance(const std::string& key) {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this, &key] { return registry.find(key) != registry.end(); });
        return registry[key]();
    }

    bool validateRegistry() {
        for (const auto& pair : registry) {
            nlohmann::json instance = pair.second();
            // Add validation logic here
            std::cout << "Validating: " << JSONParser::objectToString(instance) << std::endl;
        }
        return true; // Placeholder return
    }
};

class AsyncFileLoader {
public:
    static void loadFiles(const std::vector<std::string>& fileNames, std::function<void()> onComplete) {
        std::vector<std::thread> threads;
        for (const auto& fileName : fileNames) {
            threads.emplace_back([fileName, &onComplete]() {
                // Simulate file loading
                std::this_thread::sleep_for(std::chrono::seconds(1));
                std::cout << "Loaded: " << fileName << std::endl;
                onComplete();
            });
        }

        for (auto& thread : threads) {
            thread.join();
        }
    }
};

class CircularDependencyDetector {
public:
    static bool detectCircularDependencies(const std::unordered_map<std::string, std::vector<std::string>>& dependencies) {
        std::unordered_set<std::string> visited;
        std::unordered_set<std::string> stack;

        for (const auto& pair : dependencies) {
            if (!visited.count(pair.first)) {
                if (detectCycleUtil(pair.first, dependencies, visited, stack)) {
                    return true;
                }
            }
        }

        return false;
    }

private:
    static bool detectCycleUtil(const std::string& node, const std::unordered_map<std::string, std::vector<std::string>>& dependencies, std::unordered_set<std::string>& visited, std::unordered_set<std::string>& stack) {
        if (stack.count(node)) {
            return true;
        }

        if (visited.count(node)) {
            return false;
        }

        visited.insert(node);
        stack.insert(node);

        for (const auto& neighbor : dependencies.at(node)) {
            if (detectCycleUtil(neighbor, dependencies, visited, stack)) {
                return true;
            }
        }

        stack.erase(node);
        return false;
    }
};

int main() {
    FactoryRegistry registry;

    // Register factory functions
    registry.registerFactory("example", []() -> nlohmann::json {
        return {{"key", "value"}};
    });

    // Load files asynchronously
    std::vector<std::string> fileNames = {"file1.json", "file2.js"};
    AsyncFileLoader::loadFiles(fileNames, [&registry]() {
        // Execute loaded files
        nlohmann::json instance = registry.createInstance("example");
        std::cout << "Created instance: " << JSONParser::objectToString(instance) << std::endl;
    });

    // Validate registry and detect circular dependencies
    if (registry.validateRegistry()) {
        std::unordered_map<std::string, std::vector<std::string>> dependencies = {{"file1.json", {"file2.js"}}};
        if (!CircularDependencyDetector::detectCircularDependencies(dependencies)) {
            std::cout << "No circular dependencies detected." << std::endl;
        } else {
            std::cout << "Circular dependency detected!" << std::endl;
        }
    }

    return 0;
}
