import boto3
from google.cloud import storage as gcs
from azure.storage.blob import BlobServiceClient, ContainerClient, BlobClient
from cachetools import TTLCache

class FileStorageManager:
    def __init__(self, providers, default_provider_index=0):
        self.providers = providers
        self.default_provider_index = default_provider_index

    def upload_file(self, file_path, bucket_name, object_name=None):
        provider_index = self.default_provider_index
        while True:
            try:
                return self.providers[provider_index].upload_file(file_path, bucket_name, object_name)
            except Exception as e:
                if provider_index + 1 < len(self.providers):
                    provider_index += 1
                else:
                    raise e

    def download_file(self, bucket_name, object_name, file_path):
        provider_index = self.default_provider_index
        while True:
            try:
                return self.providers[provider_index].download_file(bucket_name, object_name, file_path)
            except Exception as e:
                if provider_index + 1 < len(self.providers):
                    provider_index += 1
                else:
                    raise e

class MultiProviderCache:
    def __init__(self, maxsize=100, ttl=300):
        self.cache = TTLCache(maxsize=maxsize, ttl=ttl)

    def get_metadata(self, key):
        return self.cache.get(key, None)

    def set_metadata(self, key, value):
        self.cache[key] = value

class AWSProvider:
    def __init__(self, aws_access_key_id, aws_secret_access_key):
        self.s3_client = boto3.client('s3', aws_access_key_id=aws_access_key_id, aws_secret_access_key=aws_secret_access_key)

    def upload_file(self, file_path, bucket_name, object_name=None):
        if object_name is None:
            object_name = file_path.split('/')[-1]
        self.s3_client.upload_file(file_path, bucket_name, object_name)
        return f"Uploaded to s3://{bucket_name}/{object_name}"

    def download_file(self, bucket_name, object_name, file_path):
        self.s3_client.download_file(bucket_name, object_name, file_path)
        return f"Downloaded from s3://{bucket_name}/{object_name} to {file_path}"

class GCPProvider:
    def __init__(self, credentials=None):
        if credentials is None:
            credentials = gcs.Credentials()
        self.storage_client = gcs.Client(credentials=credentials)

    def upload_file(self, file_path, bucket_name, object_name=None):
        if object_name is None:
            object_name = file_path.split('/')[-1]
        bucket = self.storage_client.bucket(bucket_name)
        blob = bucket.blob(object_name)
        blob.upload_from_filename(file_path)
        return f"Uploaded to gs://{bucket_name}/{object_name}"

    def download_file(self, bucket_name, object_name, file_path):
        bucket = self.storage_client.bucket(bucket_name)
        blob = bucket.blob(object_name)
        blob.download_to_filename(file_path)
        return f"Downloaded from gs://{bucket_name}/{object_name} to {file_path}"

class AzureProvider:
    def __init__(self, connection_string):
        self.blob_service_client = BlobServiceClient.from_connection_string(connection_string)

    def upload_file(self, file_path, container_name, blob_name=None):
        if blob_name is None:
            blob_name = file_path.split('/')[-1]
        container_client = self.blob_service_client.get_container_client(container_name)
        blob_client = container_client.get_blob_client(blob_name)
        with open(file_path, "rb") as data:
            blob_client.upload_blob(data)
        return f"Uploaded to azure://{container_name}/{blob_name}"

    def download_file(self, container_name, blob_name, file_path):
        container_client = self.blob_service_client.get_container_client(container_name)
        blob_client = container_client.get_blob_client(blob_name)
        with open(file_path, "wb") as download_file:
            download_file.write(blob_client.download_blob().readall())
        return f"Downloaded from azure://{container_name}/{blob_name} to {file_path}"
