import json
import hashlib
import requests
from flask import Flask, request, jsonify, WebSocket
from threading import Lock
from redis import Redis

app = Flask(__name__)
redis_client = Redis(host='localhost', port=6379, db=0)
lock = Lock()

class ConfigManager:
    def __init__(self):
        self.configs = {}
        self.lock = Lock()

    def load_config(self, config_id):
        with lock:
            if config_id not in self.configs:
                response = requests.get(f'https://config-server.com/{config_id}.json')
                if response.status_code == 200:
                    config_data = response.json()
                    self.configs[config_id] = config_data
                    redis_client.set(config_id, json.dumps(config_data))
            return self.configs[config_id]

    def save_config(self, config_id, config_data):
        with lock:
            self.configs[config_id] = config_data
            redis_client.set(config_id, json.dumps(config_data))

    def delete_config(self, config_id):
        with lock:
            if config_id in self.configs:
                del self.configs[config_id]
                redis_client.delete(config_id)

    def get_all_configs(self):
        return self.configs

class ConfigService:
    @app.route('/load/<config_id>', methods=['GET'])
    def load_config_route(config_id):
        config_manager = ConfigManager()
        config_data = config_manager.load_config(config_id)
        return jsonify(config_data)

    @app.route('/save', methods=['POST'])
    def save_config_route():
        data = request.get_json()
        config_id = data['config_id']
        config_data = data['config_data']
        config_manager = ConfigManager()
        config_manager.save_config(config_id, config_data)
        return jsonify({'status': 'success'})

    @app.route('/delete/<config_id>', methods=['DELETE'])
    def delete_config_route(config_id):
        config_manager = ConfigManager()
        config_manager.delete_config(config_id)
        return jsonify({'status': 'success'})

if __name__ == '__main__':
    app.run(debug=True)
