import xml.etree.ElementTree as ET
import requests

class StreamingXmlFilter:
    def __init__(self, xml_file_path, xpath_expression):
        self.xml_file_path = xml_file_path
        self.xpath_expression = xpath_expression
        self.iterable = None

    def filter_elements(self):
        self.iterable = self._iterate_filtered_elements()

    def _iterate_filtered_elements(self):
        context = ET.iterparse(self.xml_file_path, events=('start',))
        for event, elem in context:
            if event == 'start' and elem.tag.endswith(self.xpath_expression.split('/')[-1]):
                yield elem
                # Clear the element to free memory
                elem.clear()

    def validate_elements(self, api_url):
        try:
            for elem in self.iterable:
                validation_response = requests.post(api_url, json={'xml_element': ET.tostring(elem)})
                if validation_response.status_code != 200:
                    print(f"Validation failed for element: {ET.tostring(elem)}")
                else:
                    print(f"Validation successful for element: {ET.tostring(elem)}")
        except requests.exceptions.RequestException as e:
            print(f"Network error during API validation: {e}")

# Example usage
xml_file_path = 'path_to_large_xml.xml'
xpath_expression = '//example_element'  # Replace with your XPath expression
api_url = 'http://example.com/api/validate'

filter = StreamingXmlFilter(xml_file_path, xpath_expression)
filter.filter_elements()
filter.validate_elements(api_url)
