```csharp
using UnityEngine;

public class ValueGenerator : MonoBehaviour
{
    private int min;
    private int max;

    public ValueGenerator(int min, int max)
    {
        if (min > max)
            throw new ArgumentOutOfRangeException(nameof(max), "Max must be greater than or equal to min.");
        this.min = min;
        this.max = max;
    }

    public float GenerateFloat()
    {
        return UnityEngine.Random.Range(min, max + 1);
    }

    public int GenerateInt()
    {
        return UnityEngine.Random.Range(min, max + 1);
    }

    public int[] GenerateIntArray(int size)
    {
        if (size > 1000)
            throw new ArgumentOutOfRangeException(nameof(size), "Array size cannot exceed 1000.");

        int[] array = new int[size];
        for (int i = 0; i < size; i++)
        {
            array[i] = GenerateInt();
        }
        return array;
    }

    public float[] GenerateFloatArray(int size)
    {
        if (size > 1000)
            throw new ArgumentOutOfRangeException(nameof(size), "Array size cannot exceed 1000.");

        float[] array = new float[size];
        for (int i = 0; i < size; i++)
        {
            array[i] = GenerateFloat();
        }
        return array;
    }

    public override string ToString()
    {
        return $"Range: {min}-{max}";
    }

    public int[] GenerateIntPermutation(int count)
    {
        if (count > (max - min + 1))
            throw new ArgumentOutOfRangeException(nameof(count), "Count must be less than or equal to the range size.");

        List<int> numbers = Enumerable.Range(min, max - min + 1).ToList();
        int[] permutation = new int[count];
        Random rng = new System.Random();

        for (int i = 0; i < count; i++)
        {
            int randomIndex = rng.Next(numbers.Count);
            permutation[i] = numbers[randomIndex];
            numbers.RemoveAt(randomIndex);
        }

        return permutation;
    }
}
