using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Security.Cryptography;
using System.Text;

public class AccountManager
{
    private readonly string _connectionString;

    public AccountManager(string connectionString)
    {
        _connectionString = connectionString;
    }

    public void CreateUser(User user, string role)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            connection.Open();
            var command = new SqlCommand("INSERT INTO Users (Username, PasswordHash, Salt, Role) VALUES (@Username, @PasswordHash, @Salt, @Role)", connection);
            command.Parameters.AddWithValue("@Username", user.Username);
            command.Parameters.AddWithValue("@PasswordHash", user.PasswordHash);
            command.Parameters.AddWithValue("@Salt", user.Salt);
            command.Parameters.AddWithValue("@Role", role);
            command.ExecuteNonQuery();
        }
    }

    public bool ValidateUserLogin(string username, string password)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            connection.Open();
            var command = new SqlCommand("SELECT PasswordHash, Salt FROM Users WHERE Username = @Username", connection);
            command.Parameters.AddWithValue("@Username", username);

            using (var reader = command.ExecuteReader())
            {
                if (!reader.Read()) return false;

                var storedPasswordHash = reader.GetString(0);
                var salt = reader.GetString(1);

                return VerifyPassword(password, storedPasswordHash, salt);
            }
        }
    }

    public void EnrollMFA(string username)
    {
        // Logic to enroll MFA for the user
    }

    public bool VerifyMFAToken(string token)
    {
        // Logic to verify MFA token with external service
        return true;
    }

    private bool VerifyPassword(string password, string storedHash, string salt)
    {
        var hash = SHA256.Create().ComputeHash(Encoding.UTF8.GetBytes(password + salt));
        return BitConverter.ToString(hash).Replace("-", "").ToLower() == storedHash.ToLower();
    }
}

public class User
{
    public string Username { get; set; }
    public byte[] PasswordHash { get; set; }
    public byte[] Salt { get; set; }
    public string Role { get; set; }
}
