import importlib.util
import json
from typing import Dict, List, Any, Optional

def load_protocol_protocols(directory_path: str) -> Dict[str, Dict]:
    protocols = {}
    for filename in os.listdir(directory_path):
        if filename.endswith(".py"):
            module_name = filename[:-3]
            spec = importlib.util.spec_from_file_location(module_name, os.path.join(directory_path, filename))
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)
            for name in dir(module):
                obj = getattr(module, name)
                if isinstance(obj, type) and hasattr(obj, "PROTOCOL_NAME"):
                    protocol_name = obj.PROTOCOL_NAME
                    protocols[protocol_name] = {
                        "name": protocol_name,
                        "implementation_class": obj,
                        "description": obj.DESCRIPTION if hasattr(obj, "DESCRIPTION") else "",
                        "supported_features": obj.SUPPORTED_FEATURES if hasattr(obj, "SUPPORTED_FEATURES") else [],
                        "default_config": obj.DEFAULT_CONFIG if hasattr(obj, "DEFAULT_CONFIG") else {},
                        "feature_flags": obj.FEATURE_FLAGS if hasattr(obj, "FEATURE_FLAGS") else {}
                    }
    return protocols
