// Define custom exceptions
class RateLimitExceededException : public std::exception {
public:
    const char* what() const noexcept override {
        return "Rate limit exceeded";
    }
};

class UserAuthentication {
private:
    struct Credentials {
        std::string username;
        std::string passwordHash;
        int failedAttempts;
        time_t lastFailedAttempt;
    };

    std::unordered_map<std::string, Credentials> userCredentials;
    mutable std::mutex credentialsMutex;

    static constexpr int MAX_FAILED_ATTEMPTS = 3;
    static constexpr time_t RATE_LIMIT_WINDOW = 5 * 60; // 5 minutes

    bool isRateLimitExceeded(const std::string& username) {
        auto it = userCredentials.find(username);
        if (it != userCredentials.end()) {
            return it->second.failedAttempts >= MAX_FAILED_ATTEMPTS &&
                   time(nullptr) - it->second.lastFailedAttempt < RATE_LIMIT_WINDOW;
        }
        return false;
    }

public:
    void authenticateUser(const std::string& username, const std::string& password) {
        std::lock_guard<std::mutex> lock(credentialsMutex);

        if (isRateLimitExceeded(username)) {
            throw RateLimitExceededException();
        }

        auto it = userCredentials.find(username);
        if (it == userCredentials.end()) {
            // User not found
            ++userCredentials[username].failedAttempts;
            userCredentials[username].lastFailedAttempt = time(nullptr);
            throw std::runtime_error("Username not found");
        } else {
            // Password verification logic here
            // For example, using a secure hashing algorithm to compare hashes
            if (it->second.passwordHash != hashPassword(password)) {
                ++userCredentials[username].failedAttempts;
                userCredentials[username].lastFailedAttempt = time(nullptr);
                throw std::runtime_error("Incorrect password");
            }
        }

        // Reset failed attempts on successful authentication
        it->second.failedAttempts = 0;
    }

    void changeUserPassword(const std::string& username, const std::string& newPassword) {
        std::lock_guard<std::mutex> lock(credentialsMutex);

        auto it = userCredentials.find(username);
        if (it == userCredentials.end()) {
            throw std::runtime_error("Username not found");
        }

        // Update password hash
        it->second.passwordHash = hashPassword(newPassword);
    }

private:
    std::string hashPassword(const std::string& password) {
        // Placeholder for actual hashing logic
        return "hashed_" + password;
    }
};
