```cpp
#include <iostream>
#include <random>
#include <mutex>
#include <thread>

class GameCharacter {
public:
    void Attack();
private:
    static std::mt19937 rng;
    static std::uniform_int_distribution<> attackDist;
    static int energy;
    static int attackCount[4];
    static std::mutex mtx;

    int CalculateCooldown(int attack) const;
    bool CanUseAttack(int attack);
    void UseAttack(int attack);
};

std::mt19937 GameCharacter::rng(std::random_device{}());
std::uniform_int_distribution<> GameCharacter::attackDist(1, 3);
int GameCharacter::energy = 50; // Initial energy
int GameCharacter::attackCount[4] = {0}; // Array to track attack usage (index 0 unused)
std::mutex GameCharacter::mtx;

void GameCharacter::Attack() {
    std::lock_guard<std::mutex> lock(mtx);

    if (energy < 10) {
        std::cerr << "Not enough energy for any attack.\n";
        return;
    }

    int attack = attackDist(rng);

    while (!CanUseAttack(attack)) {
        attack = attackDist(rng); // Randomly select another attack if the current one is on cooldown
    }

    UseAttack(attack);
}

int GameCharacter::CalculateCooldown(int attack) const {
    switch (attack) {
        case 1: return 5;
        case 2: return 7;
        case 3: return 10;
        default: return -1; // Invalid attack
    }
}

bool GameCharacter::CanUseAttack(int attack) {
    if (attackCount[attack] >= 100) {
        std::cerr << "Attack " << attack << " has reached the maximum usage limit.\n";
        return false;
    }

    int cooldown = CalculateCooldown(attack);
    if (energy < cooldown) {
        return false;
    }

    return true;
}

void GameCharacter::UseAttack(int attack) {
    switch (attack) {
        case 1:
            std::cout << "Using Attack 1.\n";
            energy -= 10;
            break;
        case 2:
            std::cout << "Using Attack 2.\n";
            energy -= 15;
            break;
        case 3:
            std::cout << "Using Attack 3.\n";
            energy -= 20;
            break;
    }

    attackCount[attack]++;
    if (energy < 0) {
        energy = 100; // Enforce global energy cap
    }
}

// Unit tests would go here, testing various scenarios including edge cases and performance under load.
