import os
import tempfile
from datetime import datetime

def initialize_logging_directory(config):
    log_dir = config.get('log_dir')
    if log_dir:
        if not os.path.exists(log_dir) and not os.access(log_dir, os.W_OK):
            try:
                os.makedirs(log_dir)
            except OSError as e:
                print(f"Failed to create directory: {e}")
                return
        elif not os.access(log_dir, os.W_OK):
            print("Logging directory exists but is not writable.")
            return

    if 'LOG_DIR' in os.environ and not os.access(os.environ['LOG_DIR'], os.W_OK):
        print("Environment variable LOG_DIR set but is not writable.")
        return

    new_log_dir = f"{log_dir}/{datetime.now().strftime('%Y-%m-%d-%H-%M')}"
    try:
        if not os.path.exists(new_log_dir):
            os.makedirs(new_log_dir)
        os.environ['LOG_DIR'] = new_log_dir
    except OSError as e:
        print(f"Failed to create new directory: {e}")

# Example usage:
config = {'log_dir': 'logs'}
initialize_logging_directory(config)
