import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class NotificationEmailer {

    private ExecutorService executorService;
    private SMTPClient smtpClient;

    public NotificationEmailer(int threadPoolSize, String smtpHost, int smtpPort, String oauthToken) {
        this.executorService = Executors.newFixedThreadPool(threadPoolSize);
        this.smtpClient = new SMTPClient(smtpHost, smtpPort, oauthToken);
    }

    public void sendNotificationEmails(List<Recipient> recipients, NotificationRule rule) throws InterruptedException {
        for (Recipient recipient : recipients) {
            executorService.submit(() -> {
                try {
                    String emailContent = createEmailContent(rule, recipient);
                    boolean sent = smtpClient.sendEmail(recipient.getEmail(), emailContent);
                    logResult("Success", "Email sent to " + recipient.getEmail());
                } catch (SMTPException e) {
                    retryWithBackoff(e, rule.getRetryInterval(), rule.getMaxRetries());
                    logResult("Failure", "Failed to send email to " + recipient.getEmail() + ": " + e.getMessage());
                } catch (NetworkException e) {
                    logError("Network error: " + e.getMessage());
                }
            });
        }
    }

    private String createEmailContent(NotificationRule rule, Recipient recipient) {
        // Logic to generate email content based on the rule and recipient
        return "<html><body><h1>Notification</h1><p>Dear " + recipient.getName() + ",</p></body></html>";
    }

    private void retryWithBackoff(SMTPException e, int initialInterval, int maxRetries) {
        for (int i = 0; i < maxRetries; i++) {
            try {
                Thread.sleep(initialInterval * Math.pow(2, i));
                smtpClient.sendEmail(e.getFailedRecipient(), createEmailContent(e.getNotificationRule(), e.getFailedRecipient()));
                return;
            } catch (InterruptedException | SMTPException ex) {
                // Retry or log error
            }
        }
    }

    private void logResult(String status, String message) {
        // Log success/failure with timestamp and message
    }

    private void logError(String error) {
        // Log error with timestamp and details
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }

