#include <json/json.h> // Assuming you have a JSON library like nlohmann_json

class DynamicLoader {
public:
    using FactoryFunction = std::function<void()>;

    void addFactory(const std::string& id, const FactoryFunction& factory) {
        std::lock_guard<std::mutex> lock(mutex_);
        factories_[id] = factory;
    }

    void removeFactory(const std::string& id) {
        std::lock_guard<std::mutex> lock(mutex_);
        factories_.erase(id);
    }

    void loadFileAsync(const std::string& filename) {
        auto task = [this, filename]() {
            std::ifstream file(filename);
            if (file.is_open()) {
                std::stringstream buffer;
                buffer << file.rdbuf();
                std::string content = buffer.str();
                // Parse the JSON and create objects
                Json::Value root = Json::parse(content);
                // Instantiate objects using factory functions
                for (const auto& item : root) {
                    if (item.isMember("id") && item["id"].isString()) {
                        std::string id = item["id"].asString();
                        if (factories_.find(id) != factories_.end()) {
                            factories_[id]();
                        }
                    }
                }
            } else {
                std::cerr << "Error opening file: " << filename << std::endl;
            }
        };
        futures_.push_back(std::async(std::launch::async, task));
    }

    void waitAll() {
        for (auto& future : futures_) {
            if (future.valid()) {
                future.wait();
            }
        }
        futures_.clear();
    }

private:
    std::unordered_map<std::string, FactoryFunction> factories_;
    std::vector<std::future<void>> futures_;
    std::mutex mutex_;
};
