import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.util.Iterator;
import java.util.Set;

public class ConnectionPool {

    private Selector selector;
    private int poolSize;

    public ConnectionPool(int poolSize) throws IOException {
        this.selector = Selector.open();
        this.poolSize = poolSize;
        initializeConnections();
    }

    private void initializeConnections() throws IOException {
        for (int i = 0; i < poolSize; i++) {
            SocketChannel channel = SocketChannel.open(new InetSocketAddress("example.com", 80));
            channel.configureBlocking(false);
            channel.register(selector, SelectionKey.OP_CONNECT);
        }
    }

    public ByteBuffer getResponse() throws IOException {
        selector.select();
        Set<SelectionKey> keys = selector.selectedKeys();
        Iterator<SelectionKey> iterator = keys.iterator();

        while (iterator.hasNext()) {
            SelectionKey key = iterator.next();

            if (!key.isValid()) {
                continue;
            }

            SocketChannel channel = (SocketChannel) key.channel();

            if (key.isConnectable()) {
                try {
                    channel.finishConnect();
                    key.interestOps(SelectionKey.OP_READ);
                } catch (IOException e) {
                    handleConnectionFailure(channel);
                }
            } else if (key.isReadable()) {
                ByteBuffer buffer = ByteBuffer.allocate(1024);
                int bytesRead = channel.read(buffer);

                if (bytesRead == -1) {
                    handleConnectionFailure(channel);
                } else {
                    return buffer;
                }

                key.interestOps(SelectionKey.OP_READ);
            }

            iterator.remove();
        }

        return null;
    }

    private void handleConnectionFailure(SocketChannel channel) throws IOException {
        channel.close();
        selector.wakeup();
    }

    public void close() throws IOException {
        selector.close();
    }
}
