using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class HashService : IDisposable
{
    private readonly ConcurrentDictionary<string, string> _cache = new ConcurrentDictionary<string, string>();
    private readonly object _lock = new object();
    private bool _disposed = false;
    private readonly ILogger _logger;

    public HashService(ILogger logger)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task<string> ComputeHashAsync(string input)
    {
        if (_disposed) throw new ObjectDisposedException(nameof(HashService));

        if (!_cache.TryGetValue(input, out var hash))
        {
            lock (_lock)
            {
                if (!_cache.TryGetValue(input, out hash))
                {
                    hash = await ComputeHashInternalAsync(input);
                    _cache.TryAdd(input, hash);
                }
            }
        }

        return hash;
    }

    private async Task<string> ComputeHashInternalAsync(string input)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            byte[] bytes = Encoding.UTF8.GetBytes(input);
            byte[] hashBytes = await Task.Run(() => sha256.ComputeHash(bytes));
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
        }
    }

    public void Dispose()
    {
        _disposed = true;
        _cache.Clear();
    }
}

public interface ILogger
{
    void Log(string message);
}

public class ConsoleLogger : ILogger
{
    public void Log(string message)
    {
        Console.WriteLine(message);
    }
}
