// JavaScript Application for Dynamically Loading Multiple Third-Party Libraries

class ScriptLoader {
  constructor() {
    this.cache = {};
  }

  loadScripts(urls) {
    urls.forEach(url => {
      if (this.cache[url]) {
        console.log(`Loading from cache: ${url}`);
        this.executeScript(this.cache[url]);
      } else {
        this.fetchScript(url);
      }
    });
  }

  fetchScript(url) {
    const script = document.createElement('script');
    script.src = url;
    script.onload = () => {
      this.cache[url] = script;
      console.log(`Loaded: ${url}`);
      this.executeScript(script);
    };
    script.onerror = (error) => {
      console.error(`Failed to load: ${url}`, error);
      // Retry mechanism
      setTimeout(() => this.fetchScript(url), 5000);
    };
    document.head.appendChild(script);
  }

  executeScript(script) {
    try {
      eval(script.text); // Execute the script in the context of the web page
    } catch (error) {
      console.error('Runtime error:', error);
    }
  }
}

// Usage Example:
const loader = new ScriptLoader();
loader.loadScripts([
  'https://example.com/library1.js',
  'https://example.com/library2.js'
]);
```

