import json
import asyncio
import hashlib
import os
from abc import ABC, abstractmethod
from typing import Any, Callable, Dict, List, Optional

class JSONHandler(ABC):
    _registry: Dict[str, Callable[[str], 'JSONHandler']] = {}

    @abstractmethod
    def to_json(self) -> str:
        pass

    @classmethod
    def from_json(cls, json_str: str) -> 'JSONHandler':
        data = json.loads(json_str)
        handler_type = data.get('type')
        if handler_type not in cls._registry:
            raise ValueError(f"Unknown handler type: {handler_type}")
        return cls._registry[handler_type](json_str)

    @classmethod
    def register_handler(cls, handler_id: str, handler_class: type):
        cls._registry[handler_id] = handler_class

    @abstractmethod
    def forward_list_insert(self, elements: List[str], target: str, second: str, position: Optional[int] = None) -> None:
        pass

class ForwardList(JSONHandler):
    def __init__(self, items: List[str]):
        self.items = items

    def to_json(self) -> str:
        return json.dumps({'type': 'forward_list', 'items': self.items})

    @classmethod
    def from_json(cls, json_str: str) -> 'ForwardList':
        data = json.loads(json_str)
        if data['type'] != 'forward_list':
            raise ValueError("Invalid JSON format for ForwardList")
        return cls(data['items'])

    def forward_list_insert(self, elements: List[str], target: str, second: str, position: Optional[int] = None) -> None:
        if position is None:
            position = 0
        found_indices = [i for i, item in enumerate(self.items) if item == target]
        for idx in found_indices:
            if idx + position < len(self.items):
                self.items.insert(idx + position, second)
            else:
                self.items.append(second)

def load_json_files(file_paths: List[str]) -> None:
    tasks = [asyncio.to_thread(json.load, open(file_path)) for file_path in file_paths]
    results = asyncio.gather(*tasks)
    for result in results:
        try:
            json_handler = JSONHandler.from_json(json.dumps(result))
            # Process the loaded JSON handler
            pass
        except Exception as e:
            print(f"Error processing JSON file: {e}")

def deserialize_and_hash_password(byte_array: bytes, password: str) -> str:
    obj = json.loads(byte_array.decode('utf-8'))
    random_string = ''.join([chr(random.randint(32, 126)) for _ in range(10)])
    hashed_password = hashlib.sha256(password.encode('utf-8')).hexdigest()
    return random_string + ':' + hashed_password

# Example usage
file_paths = ['file1.json', 'file2.json']
asyncio.run(load_json_files(file_paths))

data = b'{"type": "forward_list", "items": ["apple", "banana"]}'
random_str, hashed_pw = deserialize_and_hash_password(data, 'my_password')
print(f"Random String: {random_str}")
print(f"Hashed Password: {hashed_pw}")

ForwardList.register_handler('forward_list', ForwardList)
