# MQTT message processor function
def process_mqtt_message(topic, payload, qos):
    import json
    from validate_email_address import validate_email
    import redis

    # Initialize Redis for deduplication and caching
    r = redis.Redis(host='localhost', port=6379, db=0)

    # Define a schema for the payload using JSON Schema
    schema = {
        "type": "object",
        "properties": {
            "actionType": {"type": "string"},
            "data": {}
        },
        "required": ["actionType", "data"]
    }

    try:
        # Validate the payload against the schema
        if not validate_json(payload, schema):
            raise ValueError("Invalid payload format")

        # Deduplicate messages based on their hash
        message_hash = hash(f"{topic}{payload}")
        if r.sismember('processed_messages', message_hash):
            return "Message already processed"
        else:
            r.sadd('processed_messages', message_hash)

        # Dispatch the message to the appropriate handler based on the topic
        handlers = {
            'light_control': handle_light_control,
            'thermostat_setpoint': handle_thermostat_setpoint,
            'alert_trigger': handle_alert_trigger
        }

        if topic in handlers:
            handlers[topic](payload)
        else:
            raise ValueError("Unknown topic")

    except Exception as e:
        import logging
        logging.error(f"Error processing message: {e}")
        return str(e)

# JavaScript function for dynamically loading and executing user scripts
def load_and_execute_script(script_url):
    from jsdom import JSDOM
    import asyncio

    # Define a cache for executed scripts
    script_cache = {}

    async def fetch_script(url):
        if url in script_cache:
            return script_cache[url]
        else:
            response = await asyncio.to_thread(requests.get, url)
            script_cache[url] = response.text
            return response.text

    async def execute_script(script):
        dom = JSDOM.from_string(script)
        window = dom.window
        with window.eval_context:
            exec(script)

    try:
        script_text = await fetch_script(script_url)

        if 'actionType' not in json.loads(script_text) or 'scriptId' not in json.loads(script_text):
            raise ValueError("Script is missing essential properties")

        await execute_script(script_text)
        return "Script executed successfully"

    except Exception as e:
        import logging
        logging.error(f"Error loading and executing script: {e}")
        return str(e)

# Example usage of the MQTT message processor function
process_mqtt_message('light_control', '{"actionType": "turn_on", "data": {"room": "living room"}}', 0)

# Example usage of the JavaScript function for dynamically loading and executing user scripts
load_and_execute_script('http://example.com/path/to/script.js')
