#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function prototypes
void readFiles(char* inputDir, char* outputDir);
void loadAndExecuteJavaScript(char* jsFilePaths[], int count);
float computeAverage(float arr[], int n);
int parseLine(const char* line, float arr[]);
void writeToFile(FILE* file, float average);

int main(int argc, char* argv[]) {
    if (argc != 4) {
        printf("Usage: %s <input_directory> <output_directory> <log_level>\n", argv[0]);
        return 1;
    }

    char* inputDir = argv[1];
    char* outputDir = argv[2];
    int logLevel = atoi(argv[3]);

    // Initialize logging system with specified log level

    readFiles(inputDir, outputDir);

    return 0;
}

void readFiles(char* inputDir, char* outputDir) {
    DIR *dir;
    struct dirent *entry;

    if ((dir = opendir(inputDir)) != NULL) {
        while ((entry = readdir(dir)) != NULL) {
            if (entry->d_type == DT_REG && strstr(entry->d_name, ".txt") != NULL) {
                char filePath[256];
                snprintf(filePath, sizeof(filePath), "%s/%s", inputDir, entry->d_name);

                FILE* file = fopen(filePath, "r");
                if (file == NULL) {
                    printf("Error opening file: %s\n", filePath);
                    continue;
                }

                char line[1024];
                while (fgets(line, sizeof(line), file)) {
                    float data[3];
                    int count = parseLine(line, data);

                    if (count >= 3) {
                        float average = computeAverage(data, count);
                        char outputFilePath[256];
                        snprintf(outputFilePath, sizeof(outputFilePath), "%s/%s_out.txt", outputDir, entry->d_name);
                        FILE* outputFile = fopen(outputFilePath, "a");
                        if (outputFile == NULL) {
                            printf("Error opening output file: %s\n", outputFilePath);
                            continue;
                        }

                        writeToFile(outputFile, average);
                        fclose(outputFile);
                    }
                }

                fclose(file);
            }
        }

        closedir(dir);
    } else {
        perror("Error opening directory");
    }
}

void loadAndExecuteJavaScript(char* jsFilePaths[], int count) {
    for (int i = 0; i < count; i++) {
        char* filePath = jsFilePaths[i];
        FILE* file = fopen(filePath, "r");
        if (file == NULL) {
            printf("Error opening JavaScript file: %s\n", filePath);
            continue;
        }

        // Load and execute JavaScript code here

        fclose(file);
    }
}

float computeAverage(float arr[], int n) {
    float sum = 0.0;
    for (int i = 0; i < n; i++) {
        sum += arr[i];
    }
    return sum / n;
}

int parseLine(const char* line, float arr[]) {
    const char* delimiter = " ";
    char* token = strtok((char*)line, delimiter);
    int count = 0;

    while (token != NULL && count < 3) {
        arr[count] = atof(token);
        count++;
        token = strtok(NULL, delimiter);
    }

    return count;
}

void writeToFile(FILE* file, float average) {
    fprintf(file, "Average: %.2f\n", average);
}
