#include <stdio.h>
#include <stdarg.h>
#include <time.h>
#include <string.h>

#define MAX_LOG_LENGTH 256

typedef enum {
    LOG_ERROR,
    LOG_WARNING,
    LOG_INFO
} LogLevel;

int logToFile(const char *filename, const char *logLevel, const char *message) {
    FILE *file = fopen(filename, "a");
    if (!file) return -1;

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "[%s] [%s] %s\n", timestamp, logLevel, message);
    fclose(file);
    return 0;
}

void logFormattedError(const char *logLevel, const char *format, ...) {
    va_list args;
    va_start(args, format);

    char formattedMessage[MAX_LOG_LENGTH];
    vsnprintf(formattedMessage, sizeof(formattedMessage), format, args);

    if (strcmp(logLevel, "ERROR") == 0) {
        logToFile("error.log", logLevel, formattedMessage);
    } else if (strcmp(logLevel, "WARNING") == 0) {
        logToFile("warning.log", logLevel, formattedMessage);
    } else if (strcmp(logLevel, "INFO") == 0) {
        logToFile("info.log", logLevel, formattedMessage);
    }

    va_end(args);
}

// Example usage:
int main() {
    logFormattedError("ERROR", "File %s could not be opened.", "config.txt");
    return 0;
}
