```javascript
class ScriptLoader {
  constructor() {
    this.cache = {};
    this.fetchingPromises = {};
  }

  async fetchScript(scriptUrl) {
    if (this.cache[scriptUrl] && !this.isCacheExpired(this.cache[scriptUrl].lastFetched)) {
      return this.cache[scriptUrl].content;
    }

    if (this.fetchingPromises[scriptUrl]) {
      return this.fetchingPromises[scriptUrl];
    }

    const promise = fetch(scriptUrl)
      .then(response => response.text())
      .then(data => {
        this.cache[scriptUrl] = { content: data, lastFetched: new Date() };
        return data;
      })
      .catch(error => {
        console.error(`Failed to fetch script from ${scriptUrl}:`, error);
        throw error;
      });

    this.fetchingPromises[scriptUrl] = promise;

    promise.finally(() => {
      delete this.fetchingPromises[scriptUrl];
    });

    return promise;
  }

  isCacheExpired(lastFetched, expirationTime = 24 * 60 * 60 * 1000) {
    const now = new Date();
    return now - lastFetched > expirationTime;
  }
}

function renderFooterScripts(scriptObjects, apiEndpoint) {
  const scriptLoader = new ScriptLoader();

  function createScriptElement(code, type) {
    const script = document.createElement('script');
    script.textContent = code;
    script.type = type;
    return script;
  }

  async function fetchAndRenderScripts(scripts) {
    for (const script of scripts) {
      try {
        let content;
        if (script.src) {
          content = await scriptLoader.fetchScript(script.src);
        } else {
          content = script.code || '';
        }
        const scriptElement = createScriptElement(content, script.type || 'text/javascript');
        document.body.appendChild(scriptElement);
      } catch (error) {
        console.error('Failed to render script:', error);
      }
    }
  }

  return fetchAndRenderScripts(scriptObjects);
}
