<?php

class OAuthAuthenticator {
    private $redisClient;
    private $oauthConfig;

    public function __construct($redisClient, $oauthConfig) {
        $this->redisClient = $redisClient;
        $this->oauthConfig = $oauthConfig;
    }

    public function authenticateUser($provider, $code) {
        try {
            $accessToken = $this->getAccessTokenFromProvider($provider, $code);
            if ($accessToken) {
                $userId = $this->fetchUserId($provider, $accessToken);
                $userInfo = $this->getUserInfo($provider, $accessToken);

                if ($this->isSessionValid($userId)) {
                    $this->updateSessionCache($userId, $accessToken);
                } else {
                    $this->storeNewSession($userId, $accessToken, $userInfo);
                }
            }
        } catch (Exception $e) {
            $this->logError($provider, $_SERVER['REMOTE_ADDR'], $_SERVER['HTTP_USER_AGENT'], $e->getMessage());
        }
    }

    private function getAccessTokenFromProvider($provider, $code) {
        // Fetch access token from provider using code
        // Use cURL or Guzzle HTTP client to make request
        return 'ACCESS_TOKEN';
    }

    private function fetchUserId($provider, $accessToken) {
        // Fetch user ID from provider using access token
        return 'USER_ID';
    }

    private function getUserInfo($provider, $accessToken) {
        // Retrieve user information from provider API
        // Use cURL or Guzzle HTTP client to make request
        return [
            'name' => 'John Doe',
            'email' => 'john.doe@example.com'
        ];
    }

    private function isSessionValid($userId) {
        $sessionId = $this->getSessionId($userId);
        return $this->redisClient->exists($sessionId);
    }

    private function updateSessionCache($userId, $accessToken) {
        $sessionId = $this->getSessionId($userId);
        $ttl = 3600; // Session TTL in seconds
        $this->redisClient->setex($sessionId, $ttl, $accessToken);
        $this->logSuccess($provider, $_SERVER['REMOTE_ADDR'], $_SERVER['HTTP_USER_AGENT']);
    }

    private function storeNewSession($userId, $accessToken, $userInfo) {
        $sessionId = $this->getSessionId($userId);
        $ttl = 3600; // Session TTL in seconds
        $userData = json_encode(['info' => $userInfo]);
        $this->redisClient->setex($sessionId, $ttl, $accessToken . '|' . $userData);
        $this->logSuccess($provider, $_SERVER['REMOTE_ADDR'], $_SERVER['HTTP_USER_AGENT']);
    }

    private function getSessionId($userId) {
        return 'session:' . md5($userId . '-' . time());
    }

    private function logSuccess($provider, $ipAddress, $userAgent) {
        // Log successful authentication attempt
        echo "Authentication successful for provider: {$provider}, IP: {$ipAddress}, User Agent: {$userAgent}\n";
    }

    private function logError($provider, $ipAddress, $userAgent, $errorMessage) {
        // Log failed authentication attempt
        echo "Authentication failed for provider: {$provider}, IP: {$ipAddress}, User Agent: {$userAgent}, Error: {$errorMessage}\n";
    }
}

// Usage example:
$redis = new Redis();
$redis->connect('127.0.0.1', 6379);

$oauthConfig = [
    'client_id' => 'your_client_id',
    'client_secret' => 'your_client_secret',
    'redirect_uri' => 'http://yourdomain.com/callback'
];

$authenticator = new OAuthAuthenticator($redis, $oauthConfig);
$authenticator->authenticateUser('provider', $_GET['code']);
?>
