```javascript
class ApiClient {
    private url: string;

    constructor(url: string) {
        this.url = url;
    }

    async fetchData(id: string): Promise<any> {
        try {
            const response = await fetch(`${this.url}/${id}`);
            if (!response.ok) throw new Error(`API error: ${response.statusText}`);
            return await response.json();
        } catch (error) {
            console.error(`Failed to fetch data for ID ${id}:`, error);
            throw error;
        }
    }
}

class ApiClientFactory {
    createApiClient(url: string): Promise<ApiClient> {
        return new ApiClient(url);
    }
}

interface ElementMetadata {
    id: string;
    class: string;
    descriptions: Map<string, string>;
    images: Map<string, string>;
    isFetched: boolean;
}

class MetadataCache {
    private cache: Map<string, ElementMetadata>;

    constructor() {
        this.cache = new Map();
    }

    async fetchAndCacheMetadata(apiClientFactory: ApiClientFactory, elements: HTMLElement[]): Promise<void> {
        const clients = await Promise.all(elements.map(element => apiClientFactory.createApiClient('https://api.example.com')));
        const tasks = elements.flatMap((element, index) => [
            this.fetchDescription(clients[index], element),
            this.fetchImage(clients[index], element)
        ]);
        await Promise.all(tasks);
    }

    async fetchDescription(client: ApiClient, element: HTMLElement): Promise<void> {
        if (!this.cache.has(element.id)) return;
        const metadata = this.cache.get(element.id)!;
        if (metadata.descriptions.has(metadata.class)) return;

        try {
            const data = await client.fetchData(element.id);
            metadata.descriptions.set(metadata.class, data.description || '');
            metadata.isFetched = true;
        } catch (error) {
            console.error(`Failed to fetch description for element ID ${element.id}:`, error);
        }
    }

    async fetchImage(client: ApiClient, element: HTMLElement): Promise<void> {
        if (!this.cache.has(element.id)) return;
        const metadata = this.cache.get(element.id)!;
        if (metadata.images.has(metadata.class)) return;

        try {
            const data = await client.fetchData(element.id);
            metadata.images.set(metadata.class, data.image || '');
            metadata.isFetched = true;
        } catch (error) {
            console.error(`Failed to fetch image for element ID ${element.id}:`, error);
        }
    }

    getElementMetadata(element: HTMLElement): ElementMetadata | null {
        return this.cache.get(element.id) || null;
    }
}

async function fetchAndFilterDynamicContent(selector: string, apiClientFactory: ApiClientFactory): Promise<void> {
    const elements = document.querySelectorAll<HTMLElement>(selector);
    const cache = new MetadataCache();

    await cache.fetchAndCacheMetadata(apiClientFactory, Array.from(elements));

    elements.forEach(element => {
        const metadata = cache.getElementMetadata(element);
        if (metadata && metadata.isFetched) {
            // Apply filtering logic based on metadata
            console.log(`Element ${element.id} filtered with description: ${metadata.descriptions.get(metadata.class)} and image: ${metadata.images.get(metadata.class)}`);
        }
    });
}
