            if not self.Validate(payload):
                return json.dumps({'message': 'error', 'data': None})

            action = payload.get('action')
            product_id = payload.get('product_id')
            quantity = payload.get('quantity')
            price = payload.get('price')
            category = payload.get('category')

            if action == 'add' or product_id:
                new_product = {
                    'id': product_id,
                    'quantity': quantity,
                    'price': price,
                    'category': category
                }
                self.Save(new_product)
                self.ExternalAPI(action, product_id)
            elif action == 'update':
                updated_product = {
                    'id': product_id,
                    'quantity': quantity,
                    'price': price,
                    'category': category
                }
                self.Save(updated_product)
                self.ExternalAPI(action, product_id)
            elif action == 'delete':
                self.Save({'id': product_id})
                self.ExternalAPI(action, product_id)

            return json.dumps({'message': 'success', 'data': None})
        except Exception as e:
            return json.dumps({'message': 'error', 'data': str(e)})
