        if re.match(pattern, file_path):
            return True
    return False

def calculate_sha256(file_path):
    sha256_hash = hashlib.sha256()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b''):
            sha256_hash.update(chunk)
    return sha256_hash.hexdigest()

def perform_integrity_check(file_path):
    try:
        if is_excluded(file_path):
            logger.info(f'Skipping excluded file: {file_path}')
            return

        sha256_hash = calculate_sha256(file_path)

        if cache.get(file_path) == sha256_hash:
            logger.info(f'File unchanged: {file_path}')
        else:
            logger.info(f'Integrity check passed for: {file_path}')
            report_integrity_check_to_external_system(file_path, sha256_hash)
            cache.set(file_path, sha256_hash, timeout=3600)

