WEATHER_APIS = {
    'OpenWeatherMap': 'http://api.openweathermap.org/data/2.5/weather',
    'WeatherAPI': 'http://api.weatherapi.com/v1/current.json',
    'AccuWeather': 'http://dataservice.accuweather.com/currentconditions/v1/{location}.json'
}
CACHE = {}
CACHE_EXPIRATION = timedelta(hours=1)

# Function to fetch weather data from APIs
def fetch_weather_data(cities):
    results = []
    for city in cities:
        for api, url in WEATHER_APIS.items():
            response = requests.get(url.format(city=city), params={'appid': 'your_api_key'})
            if response.status_code == 200:
                weather_data = response.json()
                weather_data['source'] = api
                results.append(weather_data)
    return results

# Function to merge buffered data chunks in JavaScript
def merge_buffered_data(chunks, num_bytes):
    merged_data = bytearray()
    for chunk in chunks:
        if len(merged_data) + len(chunk) <= num_bytes:
            merged_data.extend(chunk)
        else:
            break
    return bytes(merged_data)

# Function to render a footer of a web page using JavaScript
def render_footer(scripts):
    script_tags = []
    for i, script in enumerate(scripts):
        if 'src' in script and 'innerHTML' in script:
            script_tag = f'<script key="{i}" src="{script["src"]}" innerHTML="{script["innerHTML"]}"></script>'
            script_tags.append(script_tag)
        elif 'code' in script:
            script_tag = f'<script key="{i}">{script["code"]}</script>'
            script_tags.append(script_tag)
    return '\n'.join(script_tags)

# Function to fetch and cache weather data with a configurable expiration time
def fetch_cached_weather_data(cities, expiration=CACHE_EXPIRATION):
    current_time = datetime.now()
    if 'weather_data' in CACHE and (current_time - CACHE['last_updated']) < expiration:
        return CACHE['weather_data']
    else:
        weather_data = fetch_weather_data(cities)
        CACHE['weather_data'] = weather_data
        CACHE['last_updated'] = current_time
        return weather_data

