        { "img", "src" }
    };

    public async Task RunModuleTestsAsync(string moduleName, List<string> testFunctions)
    {
        var module = Assembly.Load(moduleName).CreateInstance(moduleName);
        foreach (var functionName in testFunctions)
        {
            var method = module.GetType().GetMethod(functionName);
            if (method != null)
            {
                try
                {
                    await ExecuteTestAsync(method, module);
                }
                catch (Exception ex)
                {
                    LogError(ex.Message);
                }
            }
            else
            {
                LogError($"Test function {functionName} not found in module.");
            }
        }
    }

    private static async Task ExecuteTestAsync(MethodInfo method, object instance)
    {
        var stopwatch = Stopwatch.StartNew();
        await Task.Run(() => method.Invoke(instance, null));
        stopwatch.Stop();
        LogExecutionTime(stopwatch.Elapsed);
    }

    private void LogError(string message)
    {
        // Log error to a file or database
    }

    private void LogExecutionTime(TimeSpan elapsedTime)
    {
        // Log execution time to a file or database
    }
}
