using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class FileEncryptor
{
    private readonly byte[] encryptionKey;
    private readonly byte[] salt;

    public FileEncryptor(byte[] key, byte[] salt)
    {
        this.encryptionKey = key;
        this.salt = salt;
    }

    public async Task<byte[]> EncryptFileAsync(string filePath)
    {
        using (var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
        using (var cryptoStream = new CryptoStream(fileStream, CreateEncryptor(), CryptoStreamMode.Write))
        {
            await fileStream.CopyToAsync(cryptoStream);
            return await Task.FromResult(await ReadCryptoStreamToEndAsync(cryptoStream));
        }
    }

    public async Task<byte[]> DecryptFileAsync(string filePath)
    {
        using (var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
        using (var cryptoStream = new CryptoStream(fileStream, CreateDecryptor(), CryptoStreamMode.Read))
        {
            return await ReadCryptoStreamToEndAsync(cryptoStream);
        }
    }

    private AesGcm CreateEncryptor()
    {
        var aes = Aes.Create();
        aes.KeySize = 256;
        aes.GenerateIV();
        aes.Key = encryptionKey;
        aes.IV = aes.GenerateIV();

        var encryptor = new AesGcm(aes);
        return encryptor;
    }

    private AesGcm CreateDecryptor()
    {
        var aes = Aes.Create();
        aes.KeySize = 256;
        aes.Key = encryptionKey;

        var decryptor = new AesGcm(aes);
        return decryptor;
    }

    private async Task<byte[]> ReadCryptoStreamToEndAsync(CryptoStream cryptoStream)
    {
        using (var memoryStream = new MemoryStream())
        {
            await cryptoStream.CopyToAsync(memoryStream);
            return memoryStream.ToArray();
        }
    }
}
