import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.nio.channels.SocketChannel;
import java.util.Iterator;

public class NetworkCommunicationFramework {

    private ServerSocketChannel serverSocketChannel;
    private Selector selector;
    private int port;
    private SSLContext sslContext;

    public NetworkCommunicationFramework(int port, String keystorePath, String keystorePassword) throws IOException {
        this.port = port;
        this.sslContext = initializeSSL(keystorePath, keystorePassword);
        setupServerSocketChannel();
        setupSelector();
    }

    private SSLContext initializeSSL(String keystorePath, String keystorePassword) throws Exception {
        KeyManagerFactory keyManagerFactory = KeyManagerFactory.getInstance("SunX509");
        keyManagerFactory.init(new FileInputStream(keystorePath), keystorePassword.toCharArray());
        SSLContext sslContext = SSLContext.getInstance("TLS");
        sslContext.init(keyManagerFactory.getKeyManagers(), null, new SecureRandom());
        return sslContext;
    }

    private void setupServerSocketChannel() throws IOException {
        serverSocketChannel = ServerSocketChannel.open();
        serverSocketChannel.bind(new InetSocketAddress(port));
        serverSocketChannel.configureBlocking(false);
        serverSocketChannel.register(selector, SelectionKey.OP_ACCEPT);
    }

    private void setupSelector() throws IOException {
        selector = Selector.open();
    }

    public void start() throws IOException {
        while (true) {
            selector.select();
            Iterator<SelectionKey> selectedKeys = selector.selectedKeys().iterator();
            while (selectedKeys.hasNext()) {
                SelectionKey key = selectedKeys.next();
                if (key.isAcceptable()) {
                    handleAccept(key);
                } else if (key.isReadable()) {
                    handleRead(key);
                }
                selectedKeys.remove();
            }
        }
    }

    private void handleAccept(SelectionKey key) throws IOException {
        ServerSocketChannel serverSocket = (ServerSocketChannel) key.channel();
        SocketChannel clientSocket = serverSocket.accept();
        clientSocket.configureBlocking(false);
        SSLEngine sslEngine = sslContext.createSSLEngine();
        sslEngine.setUseClientMode(false);
        SSLParameters sslParams = sslEngine.getSSLParameters();
        sslParams.setNeedClientAuth(true);
        sslEngine.setSSLParameters(sslParams);
        SSLEngineResult result;
        ByteBuffer wrapBuffer = ByteBuffer.allocate(8192);
        do {
            result = sslEngine.wrap(wrapBuffer, wrapBuffer);
        } while (result.getStatus() == Status.BUFFER_OVERFLOW);
        SSLSession session = sslEngine.getSession();
        clientSocket.register(selector, SelectionKey.OP_READ, new SSLEngineWrapper(sslEngine, session));
    }

    private void handleRead(SelectionKey key) throws IOException {
        SSLEngineWrapper sslEngineWrapper = (SSLEngineWrapper) key.attachment();
        SocketChannel clientSocket = (SocketChannel) key.channel();
        ByteBuffer buffer = ByteBuffer.allocateDirect(8192);
        int bytesRead;
        try {
            while ((bytesRead = clientSocket.read(buffer)) > 0) {
                buffer.flip();
                SSLEngineResult result;
                do {
                    result = sslEngineWrapper.sslEngine.unwrap(buffer, buffer);
                } while (result.getStatus() == Status.BUFFER_UNDERFLOW || result.getStatus() == Status.NEED_UNWRAP);
                if (result.getHandshakeStatus() == HandshakeStatus.NOT_HANDSHAKING) {
                    // Handle the data received
                }
                buffer.clear();
            }
        } catch (IOException e) {
            sslEngineWrapper.sslEngine.closeOutbound();
        }
    }

    private static class SSLEngineWrapper {
        final SSLEngine sslEngine;
        final SSLSession session;

        public SSLEngineWrapper(SSLEngine sslEngine, SSLSession session) {
            this.sslEngine = sslEngine;
            this.session = session;
        }
    }

    public static void main(String[] args) throws Exception {
        NetworkCommunicationFramework framework = new NetworkCommunicationFramework(8080, "path/to/keystore.jks", "password");
        framework.start();
    }
}
