<?php
class APIAuthenticator {
    private $client;
    private $accessToken;

    public function __construct($clientId, $clientSecret, $redirectUri) {
        $this->client = new League\OAuth2\Client\Provider\GenericProvider([
            'clientId'                => $clientId,
            'clientSecret'              => $clientSecret,
            'redirectUri'               => $redirectUri,
            'urlAuthorize'              => 'https://example.com/oauth/authorize',
            'urlAccessToken'            => 'https://example.com/oauth/token',
            'urlResourceOwnerDetails'   => 'https://example.com/api/user'
        ]);
    }

    public function authenticate($code) {
        $token = $this->client->getAccessToken('authorization_code', ['code' => $code]);
        $_SESSION['access_token'] = $token->getToken();
        return $token;
    }

    public function updateResource($resourceId, $data) {
        if (!isset($_SESSION['access_token'])) {
            throw new Exception("Authentication required");
        }
        $this->accessToken = $_SESSION['access_token'];

        try {
            $response = $this->client->request('PUT', 'https://example.com/api/resource/' . $resourceId, [
                'headers' => ['Authorization' => 'Bearer ' . $this->accessToken],
                'json'    => $data
            ]);
            return json_decode($response->getBody(), true);
        } catch (\Exception $e) {
            // Fallback mechanism for failed authentications
            if ($e->getCode() == 401) {
                unset($_SESSION['access_token']);
                throw new Exception("Authentication failed, please try again", 401);
            }
            throw $e;
        }
    }

    public function deleteResource($resourceId) {
        if (!isset($_SESSION['access_token'])) {
            throw new Exception("Authentication required");
        }
        $this->accessToken = $_SESSION['access_token'];

        try {
            $response = $this->client->request('DELETE', 'https://example.com/api/resource/' . $resourceId, [
                'headers' => ['Authorization' => 'Bearer ' . $this->accessToken]
            ]);
            return json_decode($response->getBody(), true);
        } catch (\Exception $e) {
            // Fallback mechanism for failed authentications
            if ($e->getCode() == 401) {
                unset($_SESSION['access_token']);
                throw new Exception("Authentication failed, please try again", 401);
            }
            throw $e;
        }
    }

    public function getUserInfo() {
        if (!isset($_SESSION['access_token'])) {
            return null;
        }
        $this->accessToken = $_SESSION['access_token'];

        try {
            $response = $this->client->getAccessToken('user_info', [
                'access_token' => $this->accessToken
            ]);
            return json_decode($response->getBody(), true);
        } catch (\Exception $e) {
            // Fallback mechanism for failed authentications
            if ($e->getCode() == 401) {
                unset($_SESSION['access_token']);
                throw new Exception("Authentication failed, please try again", 401);
            }
            throw $e;
        }
    }
}

// Example usage:
$authenticator = new APIAuthenticator('client_id', 'client_secret', 'http://example.com/callback');
$accessToken = $authenticator->authenticate($_GET['code']);

try {
    $updatedResource = $authenticator->updateResource(123, ['name' => 'New Name']);
    echo json_encode($updatedResource);
} catch (Exception $e) {
