// Recursive traversal function
State* traverseDOM(FSA* fsa, int lastState, char* selector) {
    State* result = NULL;
    for (int i = 0; i < fsa->edges[lastState].destination; ++i) {
        if (matchSelector(&fsa->states[i], selector)) {
            State* newState = malloc(sizeof(State));
            if (!newState) return NULL; // Handle memory allocation failure
            newState->id = i;
            newState->next = result;
            result = newState;
        }
    }
    return result;
}

// Example usage
int main() {
    // Initialize FSA and states (omitted for brevity)
    FSA fsa;
    State* states = malloc(sizeof(State) * 10);
    fsa.stateCount = 10;
    fsa.states = states;

    // Define a selector
    char* selector = ".example-class";

    // Traverse the DOM tree
    State* matchedStates = traverseDOM(&fsa, 0, selector);

    // Free allocated memory and handle exceptions
    while (matchedStates) {
        State* temp = matchedStates;
        matchedStates = matchedStates->next;
        free(temp);
    }

    return 0;
}
