import boto3
from botocore.exceptions import NoCredentialsError, PartialCredentialsError
from PIL import Image
import requests
import io
import hashlib
import datetime
import os

s3_client = boto3.client('s3')
cache_table = boto3.resource('dynamodb').Table('ImageCache')

def upload_image_to_s3(image_data, image_name):
    try:
        response = s3_client.put_object(
            Bucket=os.getenv('S3_BUCKET_NAME'),
            Key=image_name,
            Body=image_data,
            ContentType='image/png'
        )
        return response
    except (NoCredentialsError, PartialCredentialsError) as e:
        print("Failed to upload image to S3:", str(e))
        return None

def generate_image_hash(image_data):
    sha1 = hashlib.sha1()
    sha1.update(image_data)
    return sha1.hexdigest()

def resize_and_convert_image_to_png(image_url):
    try:
        response = requests.get(image_url, stream=True)
        image = Image.open(io.BytesIO(response.content))
        resized_image = image.resize((800, 600), Image.ANTIALIAS)
        output_buffer = io.BytesIO()
        resized_image.save(output_buffer, format='PNG')
        return output_buffer.getvalue()
    except Exception as e:
        print("Failed to resize and convert image:", str(e))
        return None

def process_and_upload_image(image_url):
    image_data = resize_and_convert_image_to_png(image_url)
    if not image_data:
        return None
    image_hash = generate_image_hash(image_data)

    # Check cache
    response = cache_table.get_item(Key={'Hash': image_hash})
    if 'Item' in response and (datetime.datetime.now() - response['Item']['Timestamp']).days < 1:
        print("Image already uploaded within the last 24 hours.")
        return None

    # Upload to S3
    image_name = f"{image_hash}.png"
    upload_response = upload_image_to_s3(image_data, image_name)
    if not upload_response:
        return None

    # Update cache
    cache_table.put_item(Item={
        'Hash': image_hash,
        'Timestamp': datetime.datetime.now()
    })

    # Return public URL and metadata
    return {
        'PublicURL': f"https://{os.getenv('S3_BUCKET_NAME')}.s3.amazonaws.com/{image_name}",
        'Metadata': {
            'Size': len(image_data),
            'Format': 'PNG',
            'UploadTimestamp': datetime.datetime.now().isoformat()
        }
    }

def lambda_handler(event, context):
    try:
        image_url = event['body-json']['url']
        result = process_and_upload_image(image_url)
        if not result:
            return {
                'statusCode': 400,
                'body': json.dumps({'error': 'Failed to upload or process image.'})
            }
        else:
            return {
                'statusCode': 200,
                'headers': {'Content-Type': 'application/json'},
                'body': json.dumps(result)
            }
    except KeyError as e:
        return {
            'statusCode': 400,
            'body': json.dumps({'error': f'Missing key in request: {str(e)}'})
        }
