import json
import requests
from functools import wraps
from threading import Lock
from queue import Queue, Empty

# Simulated distributed database connection
db = {}
supplier_ids = {'1': 'Supplier A', '2': 'Supplier B'}
cache = {}
lock = Lock()
request_queue = Queue()

def validate_request(request):
    if not isinstance(request.get('quantity'), int) or request['quantity'] <= 0:
        return False, "Invalid quantity"
    if not isinstance(request.get('price'), (int, float)) or request['price'] <= 0:
        return False, "Invalid price"
    if 'supplier_id' in request and request['supplier_id'] not in supplier_ids:
        return False, "Invalid supplier ID"
    return True, None

def save_to_db(product):
    with lock:
        db[product['product_id']] = product
    cache[product['product_id']] = product

def sync_with_apis(product):
    try:
        requests.post('https://api1.sales.com/update', json=product)
        requests.post('https://api2.sales.com/update', json=product)
    except requests.RequestException as e:
        print(f"Error syncing with API: {e}")

def handle_request(request):
    is_valid, error_message = validate_request(request)
    if not is_valid:
        return {'message': 'error', 'data': {'error': error_message}}

    product_id = request.get('product_id')
    action = request['action']
    quantity = request['quantity']
    price = request['price']
    category = request.get('category')
    supplier_id = request.get('supplier_id')

    if action == 'add':
        product = {'product_id': str(len(db) + 1), 'quantity': quantity, 'price': price, 'category': category, 'supplier_id': supplier_id}
        save_to_db(product)
    elif action == 'update':
        if product_id not in db:
            return {'message': 'error', 'data': {'error': 'Product not found'}}
        product = db[product_id]
        product['quantity'] += quantity
        product['price'] = price
        product['category'] = category or product['category']
        product['supplier_id'] = supplier_id or product['supplier_id']
        save_to_db(product)
    elif action == 'delete':
        if product_id not in db:
            return {'message': 'error', 'data': {'error': 'Product not found'}}
        del db[product_id]
        del cache[product_id]

    sync_with_apis(product)

    return {'message': 'success', 'data': {}}

def worker():
    while True:
        try:
            request = request_queue.get(timeout=1)
            handle_request(request)
            request_queue.task_done()
        except Empty:
            pass

# Start worker threads
for _ in range(5):
    import threading
    threading.Thread(target=worker).start()

def distributed_inventory_handler(request):
    request_queue.put(request)
    return json.dumps({'message': 'success', 'data': {}})
