    static double requests_per_second = RATE_LIMIT;
    static int current_requests = 0;
    static auto start_time = std::chrono::system_clock::now();
    auto now = std::chrono::system_clock::now();
    auto elapsed_time = std::chrono::duration_cast<std::chrono::seconds>(now - last_request_time).count();

    if (elapsed_time > 1) {
        current_requests = 0;
        start_time = now;
    }

    current_requests++;
    return static_cast<double>(current_requests) / elapsed_time <= requests_per_second;
