public class SecureAuthenticator
{
    private readonly Dictionary<string, Func<string, string>> _hashers = new Dictionary<string, Func<string, string>>
    {
        { "SHA-256", (password) => SHA256.Create().ComputeHash(System.Text.Encoding.UTF8.GetBytes(password)).ToArray() },
        { "bcrypt", BCrypt.HashPassword },
        { "Argon2", Argon2.Default.HashPassword }
    };

    public string HashPassword(string password, string algorithm = "SHA-256")
    {
        if (!_hashers.ContainsKey(algorithm))
            throw new ArgumentException("Unsupported hashing algorithm");

        return BitConverter.ToString(_hashers[algorithm](password)).Replace("-", "").ToLower();
