```cpp
#include <iostream>
#include <random>
#include <future>
#include <string>
#include <fstream>

enum class AttackType {
    Basic,
    Special
};

struct AttackDetails {
    std::string name;
    int damage;
    int cooldown;
};

class GameCharacter {
public:
    explicit GameCharacter(int maxCooldown) : nextAttackTime(0), currentCooldown(maxCooldown) {}

    AttackType selectAttack(std::mt19937& rng, const std::string& dbUrl) {
        if (std::chrono::system_clock::now() < nextAttackTime) {
            return AttackType::Basic; // Basic attack on cooldown
        }

        std::future<AttackDetails> future = fetchAttackDetailsAsync(dbUrl);
        try {
            AttackDetails details = future.get();
            nextAttackTime = std::chrono::system_clock::now() + std::chrono::seconds(details.cooldown);
            currentCooldown = details.cooldown;
            logAttackSelection(details.name, details.damage);
            return details.type;
        } catch (const std::exception& e) {
            logError(e.what());
            return AttackType::Basic; // Fallback to basic attack on error
        }
    }

private:
    std::chrono::time_point<std::chrono::system_clock> nextAttackTime;
    int currentCooldown;

    std::future<AttackDetails> fetchAttackDetailsAsync(const std::string& dbUrl) {
        return std::async(std::launch::async, [dbUrl]() -> AttackDetails {
            // Simulate fetching attack details from the database
            std::this_thread::sleep_for(std::chrono::seconds(1)); // Simulating network latency
            return AttackDetails{"Fireball", 50, 3}; // Example data
        });
    }

    void logAttackSelection(const std::string& name, int damage) {
        std::ofstream log("attack_log.txt", std::ios_base::app);
        if (log.is_open()) {
            log << "Selected attack: " << name << ", Damage: " << damage << std::endl;
            log.close();
        }
    }

    void logError(const std::string& error) {
        std::ofstream log("error_log.txt", std::ios_base::app);
        if (log.is_open()) {
            log << "Error: " << error << std::endl;
            log.close();
        }
    }
};
