const { loadModule } = require('./moduleLoader');
const mock = require('mock-require');
const Mocha = require('mocha');

async function runTestsAsync(moduleLabel, testSuite) {
    try {
        const module = await loadModule(moduleLabel);
        mock.on('*').restore();

        const mocha = new Mocha();
        testSuite(mocha);

        console.log(`Running tests for ${moduleLabel}`);
        const runner = mocha.run((failures) => {
            if (failures > 0) {
                console.error(`${failures} tests failed.`);
            } else {
                console.log('All tests passed!');
            }
        });

        return new Promise((resolve, reject) => {
            runner.on('end', () => resolve());
            runner.on('error', (err) => reject(err));
        });
    } catch (error) {
        console.error(`Error loading module ${moduleLabel}:`, error);
        throw error;
    }
}

module.exports = runTestsAsync;
