    private readonly IXmlParser parser;
    private readonly IXmlValidator validator;
    private readonly IUserInputHandler userInputHandler;
    private readonly ILogger logger;
    private readonly IExternalApiFetcher apiFetcher;

    public XmlManager(ICachingMechanism cache, IXmlParser parser, IXmlValidator validator, IUserInputHandler userInputHandler, ILogger logger, IExternalApiFetcher apiFetcher)
    {
        this.cache = cache;
        this.parser = parser;
        this.validator = validator;
        this.userInputHandler = userInputHandler;
        this.logger = logger;
        this.apiFetcher = apiFetcher;
    }

    public XNode GetElement(string xpath, string xmlContent, string xsdSchemaContent)
    {
        try
        {
            XNode node = parser.Parse(xmlContent);
            if (!userInputHandler.IsValidXPath(xpath))
            {
                throw new ArgumentException("Invalid XPath query.", nameof(xpath));
            }
            node = node.XPathSelectElement(xpath);
            if (node == null)
                throw new InvalidOperationException($"No element found for XPath '{xpath}'.");
            if (validator != null && xsdSchemaContent != null)
            {
                node = validator.Validate(node, xsdSchemaContent);
            }
            return node;
        }
        catch (Exception ex)
        {
            logger.LogError(ex.Message);
            throw;
        }
    }

    public void RefreshCache(string key, string url)
    {
        try
        {
            byte[] data = apiFetcher.FetchData(url);
            cache.Add(key, data);
        }
        catch (Exception ex)
        {
            logger.LogError(ex.Message);
        }
    }
}

