[ApiController]
[Route("[controller]")]
public class PageController : ControllerBase
{
    private readonly IPageService _pageService;
    private readonly IMessagingService _messagingService;
    private readonly ILogger<PageController> _logger;
    private static readonly SemaphoreSlim _semaphore = new SemaphoreSlim(1, 1);
    private static readonly Dictionary<string, string> _cache = new Dictionary<string, string>();

    public PageController(IPageService pageService, IMessagingService messagingService, ILogger<PageController> logger)
    {
        _pageService = pageService;
        _messagingService = messagingService;
        _logger = logger;
    }

    [HttpPost("update")]
    public async Task<IActionResult> UpdateElement(int sectionId, int elementId, string htmlContent, [Optional] string comment)
    {
        if (!_cache.TryGetValue($"{sectionId}_{elementId}", out var cachedHtml) || DateTime.UtcNow - new DateTime(1970, 1, 1).AddMilliseconds(Convert.ToDouble(cachedHtml.Split('|')[2])) > TimeSpan.FromSeconds(60))
        {
            await ValidateInput(sectionId, elementId, htmlContent, comment);
            _cache[$"{sectionId}_{elementId}"] = $"{htmlContent}|{comment}|{DateTime.UtcNow.Ticks}";
        }

        try
        {
            await _semaphore.WaitAsync();
            if (await _pageService.UpdateElement(sectionId, elementId, htmlContent, comment))
            {
                await _messagingService.SendNotification(sectionId);
                return Ok("Update successful");
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to update element");
            return StatusCode(500, "Internal server error");
        }
        finally
        {
            _semaphore.Release();
        }

        return BadRequest("Update failed");
    }

    private async Task ValidateInput(int sectionId, int elementId, string htmlContent, string comment)
    {
        if (sectionId < 1 || elementId < 1) throw new ArgumentException("Invalid section or element ID");

        // Add HTML validation logic here

        if (!string.IsNullOrEmpty(comment) && comment.Length > 255) throw new ArgumentException("Comment exceeds length limit");
    }
}

public interface IPageService
{
    Task<bool> UpdateElement(int sectionId, int elementId, string htmlContent, string comment);
}

public class PageService : IPageService
{
    private readonly IDistributedCache _cache;

    public PageService(IDistributedCache cache)
    {
        _cache = cache;
    }

    public async Task<bool> UpdateElement(int sectionId, int elementId, string htmlContent, string comment)
    {
        // Implement logic to update HTML content in distributed cache
        // Return true if update is successful, false otherwise

        return await _cache.SetStringAsync($"page_{sectionId}_{elementId}", $"{htmlContent}|{comment}|{DateTime.UtcNow.Ticks}");
    }
}

public interface IMessagingService
{
    Task SendNotification(int sectionId);
}

public class MessagingService : IMessagingService
{
    public async Task SendNotification(int sectionId)
    {
        // Implement logic to send notification message to queue

        using (var connection = ConnectionMultiplexer.Connect("localhost"))
        {
            var channel = connection.GetSubscriber();
            await channel.PublishAsync($"page_{sectionId}", DateTime.UtcNow.Ticks);
        }
    }
}
