```javascript
const express = require('express');
const mongoose = require('mongoose');
const bcrypt = require('bcrypt');
const bodyParser = require('body-parser');
const { Stripe, PayPal } = require('./paymentGateways');

const app = express();
app.use(bodyParser.json());

// MongoDB connection
mongoose.connect('mongodb://localhost:27017/paymentApp', {
  useNewUrlParser: true,
  useUnifiedTopology: true,
});

// User model
const userSchema = new mongoose.Schema({
  username: { type: String, required: true },
  passwordHash: { type: String, required: true },
  email: { type: String, required: true, unique: true },
  transactions: [{ type: mongoose.Schema.Types.ObjectId, ref: 'Transaction' }],
});

const User = mongoose.model('User', userSchema);

// Transaction model
const transactionSchema = new mongoose.Schema({
  amount: { type: Number, required: true },
  currency: { type: String, required: true },
  status: { type: String, enum: ['pending', 'completed', 'failed'], default: 'pending' },
  paymentMethod: { type: String, required: true },
  paymentGatewayResponse: { type: Object },
});

const Transaction = mongoose.model('Transaction', transactionSchema);

// Middleware to authenticate users
const authenticateUser = async (req, res, next) => {
  const { username, password } = req.headers;
  try {
    const user = await User.findOne({ username });
    if (!user || !bcrypt.compareSync(password, user.passwordHash)) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }
    req.user = user;
    next();
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
};

// Payment gateway instances
const paymentGateways = {
  stripe: new Stripe(),
  paypal: new PayPal(),
};

// Route to create a new user
app.post('/users', async (req, res) => {
  const { username, password, email } = req.body;
  try {
    const salt = await bcrypt.genSalt(10);
    const passwordHash = await bcrypt.hash(password, salt);
    const newUser = new User({ username, passwordHash, email });
    await newUser.save();
    res.status(201).json(newUser);
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Route to initiate a transaction
app.post('/transactions', authenticateUser, async (req, res) => {
  const { amount, currency, paymentMethod } = req.body;
  try {
    const user = req.user;
    const paymentGateway = paymentGateways[paymentMethod.toLowerCase()];
    if (!paymentGateway) {
      return res.status(400).json({ error: 'Invalid payment method' });
    }
    const response = await paymentGateway.charge(amount, currency);
    const newTransaction = new Transaction({
      amount,
      currency,
      status: response.status,
      paymentMethod,
      paymentGatewayResponse: response.data,
    });
    user.transactions.push(newTransaction._id);
    await Promise.all([newTransaction.save(), user.save()]);
    res.json(newTransaction);
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
