#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_LOG_SIZE 1024

typedef enum { DEBUG, INFO, ERROR } LogLevel;

void logMessage(LogLevel level, const char* format, ...) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    time_t t = time(NULL);
    struct tm *tm_info = localtime(&t);

    pthread_mutex_lock(&lock);
    printf("[%s] %s ", strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info), level == DEBUG ? "DEBUG" : level == INFO ? "INFO" : "ERROR");
    va_list args;
    va_start(args, format);
    vprintf(format, args);
    va_end(args);
    printf("\n");
    pthread_mutex_unlock(&lock);
}

char* secureTrimAndAppendSlash(char* input, size_t limit) {
    if (input == NULL || limit <= 0) {
        logMessage(ERROR, "Invalid input or limit: %s, %zu", input, limit);
        return NULL;
    }

    // Trim leading whitespace
    char* start = input;
    while (*start && isspace((unsigned char)*start)) {
        start++;
    }

    // Find trailing whitespace
    char* end = input + strlen(input) - 1;
    while (end > start && isspace((unsigned char)*end)) {
        end--;
    }

    // Null-terminate the string at the new end
    *(end + 1) = '\0';

    size_t trimmedLength = end - start + 1;

    if (trimmedLength >= limit) {
        logMessage(INFO, "Trimmed string too long: %s", input);
        return NULL;
    }

    // Append a slash if not already present
    if (*(end + 1) != '/') {
        *(end + 2) = '\0';
        *(end + 1) = '/';
    } else {
        *(end + 1) = '\0';
    }

    logMessage(INFO, "Trimmed and appended: %s", input);
    return input;
}
