    private long _seed;

    public SeedManager(long seed)
    {
        _random = new Random(seed);
        _seed = seed;
    }

    public long GetSeed()
    {
        return Interlocked.Read(ref _seed);
    }

    public void SetSeed(long seed)
    {
        Interlocked.Exchange(ref _seed, seed);
        _random = new Random(seed);
    }
}

