    {
        if (!_rangeCache.ContainsKey(rangeKey))
        {
            LoadRangeConfigFromSource(rangeKey);
        }

        var rangeConfig = _rangeCache[rangeKey];
        return GenerateValueInRange(rangeConfig.Min, rangeConfig.Max, rangeConfig.Type);
    }

    private void LoadRangeConfigFromSource(string rangeKey)
    {
        // Simulate fetching from an external data source
        var fetchedRangeConfig = FetchRangeConfigFromExternalSource(rangeKey);
        _rangeCache[rangeKey] = fetchedRangeConfig;
