#include <stdio.h>
#include <stdlib.h>

// Define the structure for an FSA state
typedef struct State {
    int id;
    struct State *next;
} State;

// Function to create a new state and return its pointer
State* createState(int id) {
    State* newState = (State*)malloc(sizeof(State));
    if (newState == NULL) {
        fprintf(stderr, "Memory allocation failed for state %d\n", id);
        exit(1);
    }
    newState->id = id;
    newState->next = NULL;
    return newState;
}

// Function to integrate and optimize the FSA creator
int integrateAndOptimizeFSACreator(int* states, int numStates, State** fsa, int lastStateId) {
    // Allocate memory for new states
    State* newStates = (State*)malloc(numStates * sizeof(State));
    if (newStates == NULL) {
        fprintf(stderr, "Memory allocation failed for %d new states\n", numStates);
        return -1;
    }

    // Initialize the new states with IDs from the input array
    for (int i = 0; i < numStates; i++) {
        newStates[i].id = states[i];
        newStates[i].next = NULL;
    }

    // Connect the last state of the FSA to the first new state
    if (*fsa != NULL) {
        State* current = *fsa;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = &newStates[0];
    } else {
        // If no states in FSA, start with the first new state
        *fsa = &newStates[0];
    }

    // Free the memory for the original states array if it's no longer needed
    free(newStates);

    return 0; // Success
}
