using System;
using System.Xml;
using System.IO;

public class XmlParser
{
    public static XmlNode GetFirstElement(string xml, string xpath)
    {
        using (XmlReader reader = XmlReader.Create(new StringReader(xml)))
        {
            XmlDocument doc = new XmlDocument();
            try
            {
                doc.Load(reader);
            }
            catch (XmlException ex)
            {
                throw new InvalidOperationException("XML document is not well-formed.", ex);
            }

            XmlNode node = doc.SelectSingleNode(xpath);
            if (node == null)
            {
                throw new InvalidOperationException($"No element found for XPath '{xpath}'.");
            }

            XmlNodeList nodes = doc.SelectNodes(xpath);
            if (nodes.Count > 1)
            {
                throw new InvalidOperationException($"Multiple elements found for XPath '{xpath}'.");
            }

            return node;
        }
    }
}

public class Program
{
    public static void Main(string[] args)
    {
        if (args.Length != 2)
        {
            Console.WriteLine("Usage: XmlParser.exe <xml> <xpath>");
            return;
        }

        string xml = File.ReadAllText(args[0]);
        string xpath = args[1];

        try
        {
