from flask import Flask, request, jsonify
import asyncio
from celery import Celery
import requests

app = Flask(__name__)
celery_app = Celery('tasks', broker='redis://localhost:6379/0')

# Dummy payment gateways and their transaction fields
payment_gateways = {
    'gateway1': {'fields': ['amount', 'currency'], 'url': 'https://api.gateway1.com/transaction'},
    'gateway2': {'fields': ['amount', 'currency', 'card_number'], 'url': 'https://api.gateway2.com/transaction'}
}

# Authentication tokens and refresh mechanisms
auth_tokens = {}
token_refresh_times = {}

@celery_app.task
def process_transaction(transaction_id, gateway):
    gateway_config = payment_gateways[gateway]
    url = gateway_config['url']
    fields = gateway_config['fields']

    # Collect transaction data based on field requirements
    transaction_data = {field: request.form[field] for field in fields}

    # Make a secure API call to the payment gateway
    headers = {'Authorization': f'Bearer {auth_tokens[gateway]}', 'Content-Type': 'application/json'}
    response = requests.post(url, json=transaction_data, headers=headers)

    if response.status_code == 200:
        return jsonify({'status': 'success', 'message': 'Transaction processed successfully'}), 200
    else:
        return jsonify({'status': 'error', 'message': 'Failed to process transaction'}), 500

@app.route('/process_transaction', methods=['POST'])
async def handle_transaction():
    transaction_ids = request.form.getlist('transaction_id[]')
    gateway = request.form['gateway']

    tasks = [process_transaction.delay(transaction_id, gateway) for transaction_id in transaction_ids]
    results = await asyncio.gather(*tasks)

    return jsonify(results), 200

if __name__ == '__main__':
    app.run(debug=True)
```

