// AngularJS Service for Dialog Field Refresh
angular.module('dialogService', []).factory('DialogRefreshService', ['$http', '$q', function($http, $q) {
    return {
        refreshFields: function(resourceId, fieldNames, authToken) {
            var deferred = $q.defer();
            var batchSize = 10;
            var fetchedData = {};

            // Split field names into batches
            for (var i = 0; i < fieldNames.length; i += batchSize) {
                var batch = fieldNames.slice(i, i + batchSize);
                this.fetchBatch(resourceId, batch, authToken).then(function(data) {
                    angular.extend(fetchedData, data);
                });
            }

            // Check if all batches are completed
            $q.all(fieldNames.map(function(fieldName) {
                return fetchedData[fieldName] !== undefined;
            })).then(function() {
                deferred.resolve(fetchedData);
            }, function(error) {
                deferred.reject(error);
            });

            return deferred.promise;
        },

        fetchBatch: function(resourceId, fieldNames, authToken) {
            var data = {};
            var promises = [];

            angular.forEach(fieldNames, function(fieldName) {
                promises.push($http.get('https://api.example.com/refresh?resourceId=' + resourceId + '&fieldName=' + fieldName, {
                    headers: {
                        'Authorization': 'Bearer ' + authToken
                    }
                }).then(function(response) {
                    data[fieldName] = response.data;
                }, function(error) {
                    console.error('Error fetching field:', fieldName, error);
                }));
            });

            return $q.all(promises).then(function() {
                return data;
            });
        }
    };
}]);

// Example Usage in Controller
angular.module('dialogApp', ['dialogService']).controller('DialogController', ['$scope', 'DialogRefreshService', function($scope, DialogRefreshService) {
    $scope.refreshFields = function() {
        var fieldNames = ['field1', 'field2', 'field3'];
        var resourceId = 'resource123';
        var authToken = 'your-auth-token';

        DialogRefreshService.refreshFields(resourceId, fieldNames, authToken).then(function(data) {
            angular.forEach(fieldNames, function(fieldName) {
                $scope[fieldName] = data[fieldName];
            });
        }, function(error) {
            console.error('Failed to refresh fields:', error);
        });
    };
}]);
