import { GameEngineAPI } from 'game-engine';
import { UIWebLibrary } from 'web-ui-library';
import { Logger } from 'logging-framework';

class DynamicGameEventGenerator {
    private gameEngine: GameEngineAPI;
    private uiLibrary: UIWebLibrary;
    private logger: Logger;

    constructor(gameEngine: GameEngineAPI, uiLibrary: UIWebLibrary, logger: Logger) {
        this.gameEngine = gameEngine;
        this.uiLibrary = uiLibrary;
        this.logger = logger;
    }

    public GenerateRandomFloat(min: number, max: number): number {
        const value = Math.random() * (max - min) + min;
        this.logger.log(`Generated random float between ${min} and ${max}: ${value}`);
        return value;
    }

    public GenerateRandomFloatNormal(mean: number, stdDev: number): number {
        let u1 = Math.random();
        let u2 = Math.random();
        while (u1 === 0) u1 = Math.random(); // Avoid zero for logarithmic distribution
        let z = Math.sqrt(-2.0 * Math.log(u1)) * Math.cos(2.0 * Math.PI * u2);
        const value = mean + stdDev * z;
        this.logger.log(`Generated random float from normal distribution with mean ${mean} and stdDev ${stdDev}: ${value}`);
        return value;
    }

    public GenerateRandomFloatLogarithmic(min: number, max: number): number {
        let u = Math.random();
        const value = min * Math.exp(Math.log(max / min) * u);
        this.logger.log(`Generated random float from logarithmic distribution between ${min} and ${max}: ${value}`);
        return value;
    }

    public async FindElementsBySelector(selector: string): Promise<NodeList> {
        try {
            const elements = await this.uiLibrary.queryDOMAsync(selector);
            if (elements.length === 0) {
                throw new Error(`No elements found for selector: ${selector}`);
            }
            this.logger.log(`Found ${elements.length} elements using selector: ${selector}`);
            return elements;
        } catch (error) {
            this.logger.error(`Error finding elements with selector ${selector}: ${error.message}`);
            throw error;
        }
    }

    public async GenerateGameEvent() {
        try {
            const eventType = Math.random() < 0.5 ? 'Uniform' : 'Normal';
            let value: number;

            if (eventType === 'Uniform') {
                value = this.GenerateRandomFloat(1, 10);
            } else {
                value = this.GenerateRandomFloatNormal(5, 2);
            }

            const elements = await this.FindElementsBySelector('.game-object');
            if (elements.length > 0) {
                const randomElement = elements[Math.floor(Math.random() * elements.length)];
                // Simulate game event based on generated value and element
                this.gameEngine.updateGameObject(randomElement, value);
                this.logger.log(`Game event generated with value ${value} for element: ${randomElement}`);
            }
        } catch (error) {
            this.logger.error(`Error generating game event: ${error.message}`);
        }
    }
}
