#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_FILENAME_LENGTH 255

char* dynamicFileNameUpdate(const char* filename, const char* fileType, int version) {
    if (filename == NULL || fileType == NULL) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    // Calculate the length of the new filename
    size_t len = strlen(filename);
    size_t dotPos = len - 1;

    // Find the last dot to determine the extension position
    while (dotPos > 0 && filename[dotPos] != '.') {
        dotPos--;
    }

    // Check for versioning suffix like ".vX"
    char* versionSuffix = strstr(filename + dotPos, ".v");
    if (versionSuffix) {
        // Extract version number
        int existingVersion = atoi(versionSuffix + 2);
        version = existingVersion + 1;
        // Shift the position past the current version suffix
        dotPos += strlen(versionSuffix);
    }

    // Allocate memory for the new filename
    size_t newLen = len - (dotPos - len) + strlen(fileType) + 3; // Extra space for ".vX"
    char* newFilename = (char*)malloc(newLen * sizeof(char));
    if (newFilename == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    // Construct the new filename
    strncpy(newFilename, filename, dotPos);
    newFilename[dotPos] = '\0';
    strcat(newFilename, ".v");
    char versionStr[12];
    snprintf(versionStr, sizeof(versionStr), "%d", version);
    strcat(newFilename, versionStr);
    strcat(newFilename, ".");
    strcat(newFilename, fileType);

    return newFilename;
}

int main() {
    char* result = dynamicFileNameUpdate("image.jpg", "png", 1);
    if (result != NULL) {
        printf("%s\n", result); // Output: image.v1.png
        free(result);
    }

    result = dynamicFileNameUpdate("report1.txt.v2", "pdf", 2);
    if (result != NULL) {
        printf("%s\n", result); // Output: report1.txt.v3
        free(result);
    }

    return 0;
}
```

