<?php

// PHP Function to Generate Secure Random String
function generateSecureToken($length = 16, $characters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') {
    // Validate Input Parameters
    if ($length <= 0) {
        throw new InvalidArgumentException('Length must be greater than zero.');
    }
    if (empty($characters)) {
        throw new InvalidArgumentException('Character set cannot be empty.');
    }

    $token = '';
    for ($i = 0; $i < $length; $i++) {
        $randomIndex = random_int(0, strlen($characters) - 1);
        $token .= $characters[$randomIndex];
    }
    return $token;
}

// PHP Function to Hash Passwords
function hashPassword($password, $algo = 'bcrypt', $cost = 12) {
    // Validate Input Parameters
    if (empty($password)) {
        throw new InvalidArgumentException('Password cannot be empty.');
    }

    // Salt and Hash the Password
    return password_hash($password, constant('PASSWORD_' . strtoupper($algo)), ['cost' => $cost]);
}

// PHP Function to Securely Store and Retrieve Tokens/Hashed Passwords in Sessions
function secureStorageSession($key, $value = null) {
    if ($value !== null) {
        // Store Value in Session
        $_SESSION[$key] = $value;
    } else {
        // Retrieve Value from Session
        return isset($_SESSION[$key]) ? $_SESSION[$key] : null;
    }
}

