const fs = require('fs');
const request = require('request-promise');

// JavaScript Function to Read a File Synchronously
function readFile(url) {
    return new Promise((resolve, reject) => {
        // Validate Input Parameter
        if (typeof url !== 'string' || url.trim() === '') {
            throw new Error('URL must be a non-empty string.');
        }

        request(url)
            .then(response => resolve(response))
            .catch(error => reject(error));
    });
}

// JavaScript Function to Upload a File Linked from a Given URL
function uploadFile(url) {
    return new Promise((resolve, reject) => {
        // Validate Input Parameter
        if (typeof url !== 'string' || url.trim() === '') {
            throw new Error('URL must be a non-empty string.');
        }

        request.get(url).pipe(fs.createWriteStream('/path/to/save/file'))
            .on('finish', () => resolve(`/path/to/save/file`))
            .on('error', (err) => reject(err));
    });
}

