```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

public interface IDistributionFunction
{
    double GenerateRandom();
}

public abstract class DistributionFunction : IDistributionFunction
{
    public abstract double GenerateRandom();
}

public class UniformDistribution : DistributionFunction
{
    private readonly Random _random = new Random();
    private readonly double _min, _max;

    public UniformDistribution(double min, double max)
    {
        _min = min;
        _max = max;
    }

    public override double GenerateRandom()
    {
        return _random.NextDouble() * (_max - _min) + _min;
    }
}

public class NormalDistribution : DistributionFunction
{
    private readonly Random _random = new Random();
    private readonly double _mean, _stdDev;

    public NormalDistribution(double mean, double stdDev)
    {
        _mean = mean;
        _stdDev = stdDev;
    }

    public override double GenerateRandom()
    {
        return _stdDev * Math.Sqrt(-2.0 * Math.Log(_random.NextDouble())) * Math.Cos(2.0 * Math.PI * _random.NextDouble()) + _mean;
    }
}

public class DynamicRandomGenerator
{
    private readonly Dictionary<string, IDistributionFunction> _distributionFunctions = new Dictionary<string, IDistributionFunction>();
    private readonly Random _random;

    public DynamicRandomGenerator()
    {
        _random = new Random();
    }

    public void AddDistributionFunction(string name, IDistributionFunction distribution)
    {
        _distributionFunctions[name] = distribution;
    }

    public double GenerateRandomValue(string distributionName)
    {
        if (_distributionFunctions.TryGetValue(distributionName, out var distribution))
        {
            return distribution.GenerateRandom();
        }
        throw new ArgumentException("Invalid distribution function name");
    }
}
