public class DynamicSQLExecutor
{
    private readonly string _connectionString;
    private readonly IAuthenticationService _authService;
    private readonly IDistributedCache _cache;
    private readonly ILogger _logger;

    public DynamicSQLExecutor(string connectionString, IAuthenticationService authService, IDistributedCache cache, ILogger logger)
    {
        _connectionString = connectionString;
        _authService = authService;
        _cache = cache;
        _logger = logger;
    }

    public async Task<DataSet> ExecuteAsync(string sqlCommandTemplate, Dictionary<string, object> parameters)
    {
        if (!await _authService.IsUserAuthorized())
        {
            throw new UnauthorizedAccessException("User is not authorized to execute this query.");
        }

        var sqlQuery = string.Format(sqlCommandTemplate, parameters.Values.ToArray());

        try
        {
            var cacheKey = $"query:{sqlQuery}";
            if (await _cache.TryGetValueAsync(cacheKey, out var cachedResult))
            {
                return DeserializeDataSet(cachedResult);
            }

            using (var connection = new SqlConnection(_connectionString))
            {
                await connection.OpenAsync();
                using (var command = new SqlCommand(sqlQuery, connection))
                {
                    foreach (var param in parameters)
                    {
                        command.Parameters.AddWithValue(param.Key, param.Value);
                    }

                    using (var reader = await command.ExecuteReaderAsync())
                    {
                        var dataSet = new DataSet();
                        dataSet.Load(reader);

                        var serializedResult = SerializeDataSet(dataSet);
                        await _cache.SetAsync(cacheKey, serializedResult, TimeSpan.FromMinutes(10));

                        return dataSet;
                    }
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while executing the query.");
            throw;
        }
    }

