import os
import time
from concurrent.futures import ThreadPoolExecutor
from functools import wraps

class DirectoryManager:
    def __init__(self, root_dir, max_workers=5):
        self.root_dir = root_dir
        self.max_workers = max_workers
        self.executor = ThreadPoolExecutor(max_workers=max_workers)

    def create_directory(self, dir_name, retries=3, delay=1):
        @wraps(create_directory)
        def wrapper(*args, **kwargs):
            for _ in range(retries):
                try:
                    os.makedirs(os.path.join(self.root_dir, dir_name))
                    return True
                except (FileExistsError, PermissionError) as e:
                    print(f"Failed to create directory: {e}. Retrying...")
                    time.sleep(delay)
                except Exception as e:
                    raise e
            return False

        self.executor.submit(wrapper)

    def delete_directory(self, dir_name):
        os.rmdir(os.path.join(self.root_dir, dir_name))

# Example usage
dir_manager = DirectoryManager("/path/to/root/directory")
dir_manager.create_directory("new_folder")
