use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 5 {
        eprintln!("Usage: {} <directory> <output_file> <extension>", args[0]);
        return;
    }

    let directory = &args[1];
    let output_file = &args[2];
    let extension = &args[3];

    match generate_llvm_ir(directory, output_file, extension) {
        Ok(_) => println!("LLVM IR generation successful."),
        Err(e) => eprintln!("Error: {}", e),
    }
}

fn generate_llvm_ir(directory: &str, output_file: &str, extension: &str) -> Result<(), String> {
    let dir_path = Path::new(directory);
    if !dir_path.exists() || !dir_path.is_dir() {
        return Err(format!("Directory '{}' does not exist or is not a directory.", directory));
    }

    let mut llvm_ir_code = String::new();

    for entry in fs::read_dir(dir_path).map_err(|e| format!("Failed to read directory '{}': {}", directory, e))? {
        let entry = entry.map_err(|e| format!("Failed to read directory entry: {}", e))?;
        let path = entry.path();
        if path.is_file() && path.extension().and_then(|ext| ext.to_str()) == Some(extension) {
            match generate_ir_for_file(&path)? {
                Some(ir) => llvm_ir_code.push_str(&ir),
                None => continue,
            }
        } else if path.is_dir() {
            let sub_path = path.display();
            for sub_entry in fs::read_dir(sub_path).map_err(|e| format!("Failed to read subdirectory '{}': {}", sub_path, e))? {
                let sub_entry = sub_entry.map_err(|e| format!("Failed to read subdirectory entry: {}", e))?;
                if sub_entry.path().is_file() && sub_entry.path().extension().and_then(|ext| ext.to_str()) == Some(extension) {
                    match generate_ir_for_file(&sub_entry.path())? {
                        Some(ir) => llvm_ir_code.push_str(&ir),
                        None => continue,
                    }
                }
            }
        }
    }

    let result = Command::new("llc")
        .arg("-filetype=asm")
        .arg("-o")
        .arg(output_file)
        .arg("-verify-function")
        .arg("-S")
        .output()
        .map_err(|e| format!("Failed to validate LLVM IR: {}", e))?;

    if result.status.success() {
        Ok(())
    } else {
        Err(format!("LLVM IR validation failed. stderr: {}", String::from_utf8_lossy(&result.stderr)))
    }
}

fn generate_ir_for_file(path: &Path) -> Result<Option<String>, String> {
    let contents = fs::read_to_string(path).map_err(|e| format!("Failed to read file '{}': {}", path.display(), e))?;
    // Placeholder for lexer and parser logic
    let parsed_nodes = parse_contents(&contents)?;
    // Placeholder for LLVM IR generation logic
    let ir_code = generate_llvm_ir_for_nodes(&parsed_nodes);
    Ok(Some(ir_code))
}

fn parse_contents(contents: &str) -> Result<Vec<String>, String> {
