import asyncio
from collections import deque
import requests

class DynamicTaskQueueManager:
    def __init__(self, api_url, auth_token):
        self.api_url = api_url
        self.auth_token = auth_token
        self.task_queue = deque()
        self.dependency_map = {}
        self.task_cache = {}

    async def submit_task(self, task_id, task_type, dependencies=None):
        if dependencies:
            for dep in dependencies:
                if dep not in self.dependency_map or self.dependency_map[dep] != task_id:
                    raise ValueError(f"Circular dependency detected: {dep} -> {task_id}")
            self.dependency_map[task_id] = dependencies
        else:
            self.dependency_map[task_id] = None

        if task_type not in self.task_cache:
            response = await self._fetch_task_config(task_type)
            if response.status_code == 200:
                self.task_cache[task_type] = response.json()
            else:
                raise Exception(f"Failed to fetch task config for type: {task_type}")

        # Submit task to external API
        headers = {
            'Authorization': f'Bearer {self.auth_token}',
            'Content-Type': 'application/json'
        }
        payload = {
            'task_id': task_id,
            'task_type': task_type,
            'config': self.task_cache[task_type]
        }
        async with requests.post(self.api_url + '/tasks', headers=headers, json=payload) as response:
            if response.status_code == 201:
                self.task_queue.append(task_id)
            else:
                raise Exception(f"Failed to submit task {task_id} to the external system")

    async def process_tasks(self):
        while True:
            if not self.task_queue:
                await asyncio.sleep(1)
                continue

            task_id = self.task_queue.popleft()
            try:
                # Process task (simulated with sleep for demonstration)
                await asyncio.sleep(0.1)
                print(f"Processing task {task_id}")
                response = requests.post(self.api_url + '/tasks/' + task_id, headers={'Authorization': f'Bearer {self.auth_token}'})
                if response.status_code == 200:
                    print(f"Task {task_id} processed successfully")
                else:
                    print(f"Failed to process task {task_id}")
            except Exception as e:
                print(f"Error processing task {task_id}: {e}")

    async def _fetch_task_config(self, task_type):
        # Simulate fetching task config from a database or external source
        await asyncio.sleep(0.1)
        return requests.get('http://example.com/task_configs/' + task_type)

# Example usage:
async def main():
    manager = DynamicTaskQueueManager('https://api.example.com', 'your_auth_token')
    await manager.submit_task('task1', 'typeA', dependencies=None)
    await manager.submit_task('task2', 'typeB', dependencies=['task1'])
    task_processor = asyncio.create_task(manager.process_tasks())
    await asyncio.sleep(5)  # Simulate running for a while
    task_processor.cancel()

asyncio.run(main())
