#include <json-c/json.h>
#include <stdbool.h>

bool validate_oauth_token(const char* json_str) {
    struct json_object *parsed_json;
    parsed_json = json_tokener_parse(json_str);

    if (parsed_json == NULL) {
        return false; // JSON parsing failed
    }

    // Check for required fields and their types
    struct json_object *access_token_obj, *expires_in_obj, *token_type_obj;
    struct json_object *refresh_token_obj = NULL;

    if (!json_object_object_get_ex(parsed_json, "access_token", &access_token_obj) ||
        !json_object_is_type(access_token_obj, json_type_string)) {
        return false; // Missing or invalid access_token
    }

    if (!json_object_object_get_ex(parsed_json, "expires_in", &expires_in_obj) ||
        !json_object_is_type(expires_in_obj, json_type_int)) {
        return false; // Missing or invalid expires_in
    }

    if (!json_object_object_get_ex(parsed_json, "token_type", &token_type_obj) ||
        !json_object_is_type(token_type_obj, json_type_string)) {
        return false; // Missing or invalid token_type
    }

    // Validate additional constraints
    const char *access_token = json_object_get_string(access_token_obj);
    if (strlen(access_token) < 8) {
        return false; // access_token too short
    }

    int expires_in = json_object_get_int(expires_in_obj);
    if (expires_in > 3600 || expires_in <= 0) {
        return false; // Invalid expires_in value
    }

    const char *token_type = json_object_get_string(token_type_obj);
    if (strcmp(token_type, "Bearer") != 0) {
        return false; // Invalid token_type
    }

    if (json_object_object_get_ex(parsed_json, "refresh_token", &refresh_token_obj)) {
        if (!json_object_is_type(refresh_token_obj, json_type_string)) {
            return false; // Missing or invalid refresh_token
        }
        const char *refresh_token = json_object_get_string(refresh_token_obj);
        if (strlen(refresh_token) < 16) {
            return false; // refresh_token too short
        }
    }

    json_object_put(parsed_json); // Clean up the parsed JSON object
    return true;
}
