            cv_.wait(lock, [this] { return !workQueue_.empty(); });
            auto task = workQueue_.front();
            workQueue_.pop();
            lock.unlock();

            // Execute the operation (insertion, deletion, balancing)
        }
    }

    void scheduleOperation(int type, int nodeId) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (workQueue_.size() >= maxConcurrentOperations_) {
            throw std::runtime_error("Max concurrent operations exceeded");
        }
        workQueue_.push({type, nodeId});
        cv_.notify_one();
    }

