// moduleManager.js
class ModuleManager {
  constructor(moduleConfig) {
    this.moduleConfig = moduleConfig;
    this.modules = {};
  }

  async loadModules() {
    for (const module of this.moduleConfig) {
      try {
        const mod = require(module.path);
        if (!this.modules[module.name]) {
          this.modules[module.name] = mod;
        }
      } catch (error) {
        console.error(`Failed to load module ${module.name}:`, error);
      }
    }
  }

  async executeModules() {
    for (const [name, mod] of Object.entries(this.modules)) {
      try {
        await mod.execute();
      } catch (error) {
        console.error(`Failed to execute module ${name}:`, error);
      }
    }
  }
}

module.exports = ModuleManager;
