public static class TestRunner
{
    private static readonly object _lock = new object();

    public static void PerformUnitTests(string moduleName)
    {
        lock (_lock)
        {
            // Dynamically load and execute tests from the specified module
            var assembly = System.Reflection.Assembly.LoadFrom(moduleName);
            var testClasses = assembly.GetTypes()
                .Where(t => t.GetCustomAttributes(typeof(TestClassAttribute), false).Length > 0);

            foreach (var testClass in testClasses)
            {
                var constructorInfo = testClass.GetConstructor(Type.EmptyTypes);
                var instance = constructorInfo.Invoke(null) as ITestFramework;
                if (instance != null)
                {
                    instance.RunTests();
                }
            }
        }
    }

    public static void RunTests(this ITestFramework framework, int numThreads = 1)
    {
        var tasks = new List<Task>();
        for (int i = 0; i < numThreads; i++)
        {
            tasks.Add(framework.RunTestAsync());
        }
        Task.WhenAll(tasks).Wait();
    }

    public static async Task RunTestAsync(this ITestFramework framework)
    {
        // Execute tests asynchronously
        await framework.ExecuteTestsAsync();
    }
}

