import os
import json
import yaml
import threading
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler

class ConfigManager:
    def __init__(self, config_paths):
        self.configs = {}
        self.lock = threading.Lock()
        self.load_configs(config_paths)
        self.setup_watcher(config_paths)

    def load_configs(self, config_paths):
        for path in config_paths:
            _, ext = os.path.splitext(path)
            with open(path, 'r') as file:
                if ext == '.json':
                    self.configs[path] = json.load(file)
                elif ext == '.yaml' or ext == '.yml':
                    self.configs[path] = yaml.safe_load(file)
                elif ext == '.env':
                    self.configs[path] = self.parse_env_file(file)

    def parse_env_file(self, file):
        config = {}
        for line in file:
            key, value = line.strip().split('=')
            config[key] = value
        return config

    def setup_watcher(self, config_paths):
        event_handler = ConfigChangeHandler(self.load_configs, config_paths)
        observer = Observer()
        for path in config_paths:
            observer.schedule(event_handler, os.path.dirname(path), recursive=False)
        observer.start()

    def get_config(self, key):
        with self.lock:
            return self.configs.get(key)

    def update_config(self, key, value):
        with self.lock:
            if key in self.configs:
                self.configs[key] = value
                self.notify_observers()

class ConfigChangeHandler(FileSystemEventHandler):
    def __init__(self, reload_func, config_paths):
        self.reload_func = reload_func
        self.config_paths = config_paths

    def on_modified(self, event):
        if any(event.src_path.endswith(ext) for ext in ['.json', '.yaml', '.yml', '.env']):
            self.reload_func(self.config_paths)

# Example usage:
config_manager = ConfigManager(['config.json', 'settings.yaml'])
api_key = config_manager.get_config('API_KEY')
