// app.js
const express = require('express');
const fs = require('fs');
const path = require('path');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const cache = require('memory-cache');

const app = express();
app.use(cors());
app.use(express.json());

// Load API keys from environment variables
const apiKeys = {
  weatherApi: process.env.WEATHER_API_KEY,
  // Add other API keys here
};

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Caching middleware
function cacheMiddleware(key) {
  return (req, res, next) => {
    const data = cache.get(key);
    if (data) {
      res.send(data);
    } else {
      res.set('X-Content-Type-Options', 'nosniff');
      res.on('finish', () => {
        if (res.statusCode === 200) {
          cache.put(key, res.body, 15 * 60 * 1000); // Cache for 15 minutes
        }
      });
      next();
    }
  };
}

// Load and process weather data from external APIs
app.get('/weather', (req, res) => {
  const city = req.query.city || 'New York';
  const apiKey = apiKeys.weatherApi;
  const url = `https://api.openweathermap.org/data/2.5/weather?q=${city}&appid=${apiKey}`;

  // Cache the key based on the city and API
  const cacheKey = `weather:${city}`;
  const cachedData = cache.get(cacheKey);

  if (cachedData) {
    res.send(cachedData);
  } else {
    fetch(url)
      .then(response => response.json())
      .then(data => {
        // Transform data as needed
        const transformedData = {
          city: data.name,
          temperature: data.main.temp,
          description: data.weather[0].description,
        };
        cache.put(cacheKey, transformedData, 15 * 60 * 1000); // Cache for 15 minutes
        res.send(transformedData);
      })
      .catch(error => {
        res.status(500).send('Error fetching weather data');
      });
  }
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send('Something broke!');
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
