#include <iostream>
#include <list>
#include <memory>
#include <mutex>
#include <string>

// Define Task struct within DynamicTaskScheduler class
struct Task {
    int id;
    int priority;
    long deadline;
    void (*taskFunction)();
    Task* next;

    Task(int id, int priority, long deadline, void (*taskFunction)()) 
        : id(id), priority(priority), deadline(deadline), taskFunction(taskFunction), next(nullptr) {}
};

class DynamicTaskScheduler {
private:
    std::list<Task*> tasks;
    std::mutex tasksMutex;

public:
    // Method to add a task if it meets the criteria
    void addTask(int id, int priority, long deadline, void (*taskFunction)()) {
        std::lock_guard<std::mutex> lock(tasksMutex);
        Task* newTask = new Task(id, priority, deadline, taskFunction);
        tasks.push_back(newTask);
    }

    // Method to remove a task
    bool removeTask(int id) {
        std::lock_guard<std::mutex> lock(tasksMutex);
        for (auto it = tasks.begin(); it != tasks.end(); ++it) {
            if ((*it)->id == id) {
                delete *it;
                tasks.erase(it);
                return true;
            }
        }
        return false;
    }

    // Method to retrieve tasks based on priority and deadline
    std::list<Task*> getTasks(int minPriority, long currentTime) {
        std::lock_guard<std::mutex> lock(tasksMutex);
        std::list<Task*> result;
        for (auto task : tasks) {
            if (task->priority >= minPriority && task->deadline <= currentTime) {
                result.push_back(task);
            }
        }
        return result;
    }

    // Destructor to clean up dynamically allocated memory
    ~DynamicTaskScheduler() {
        std::lock_guard<std::mutex> lock(tasksMutex);
        for (auto task : tasks) {
            delete task;
        }
        tasks.clear();
    }
};

// Example usage of DynamicTaskScheduler class
void sampleTaskFunction() {
    std::cout << "Executing a sample task!" << std::endl;
}

int main() {
    DynamicTaskScheduler scheduler;

    // Adding tasks
    scheduler.addTask(1, 2, 1633072800, sampleTaskFunction);
    scheduler.addTask(2, 1, 1633072800, sampleTaskFunction);

    // Getting tasks based on criteria
    auto eligibleTasks = scheduler.getTasks(1, 1633072800);

    for (auto task : eligibleTasks) {
        task->taskFunction();
    }

    return 0;
}
```

This code snippet provides a basic implementation of the `DynamicTaskScheduler` class with methods to add, remove, and retrieve tasks based on priority and deadline criteria. The example usage in the `main` function demonstrates how to use the class by adding tasks and executing those that meet the specified criteria.

