function asyncReduce(numbers, initialValue, callback) {
  return new Promise((resolve, reject) => {
    let accumulator = initialValue;
    for (const num of numbers) {
      callback(accumulator, num)
        .then(result => {
          accumulator = result;
        })
        .catch(error => {
          reject(error);
        });
    }
    resolve(accumulator);
  });
}

// Example usage
asyncReduce([1, 2, 3, 4], 0, (acc, num) => Promise.resolve(acc + num))
  .then(result => console.log("Reduced result:", result)) // Output: Reduced result: 10
  .catch(error => console.error("Error during reduction:", error));
