@Service
public class WeatherService {

    @Autowired
    private WebClient.Builder webClientBuilder;

    @Autowired
    private CacheManager cacheManager;

    public Mono<WeatherData> getWeatherData(String location, String date) {
        // Check if the weather data is already cached
        return Mono.fromCallable(() -> cacheManager.getCache("weather").get(location + date))
            .onErrorResume(throwable -> fetchWeatherDataFromAPI(location, date)
                .doOnNext(data -> cacheManager.getCache("weather").put(location + date, data)))
            .cast(WeatherData.class);
    }

    private Mono<WeatherData> fetchWeatherDataFromAPI(String location, String date) {
        WebClient webClient = webClientBuilder.build();
        return webClient.get()
            .uri("https://api.openweathermap.org/data/2.5/weather?q=" + location + "&appid=YOUR_API_KEY")
            .retrieve()
            .bodyToMono(WeatherData.class);
    }
}

