// lambda/ImageProcessorLambda.js
const AWS = require('aws-sdk');
const s3 = new AWS.S3();

exports.handler = async (event) => {
  const { fileKey, transformations, uniqueId } = event;

  try {
    // Download original image from S3
    const getObjectParams = {
      Bucket: process.env.ORIGINAL_IMAGE_BUCKET,
      Key: fileKey,
    };

    const data = await s3.getObject(getObjectParams).promise();
    const originalImageBuffer = data.Body;

    // Apply transformations (resize, crop, watermark)
    let transformedImageBuffer = applyTransformations(originalImageBuffer, transformations);

    // Upload processed image to S3
    const putObjectParams = {
      Bucket: process.env.PROCESSED_IMAGE_BUCKET,
      Key: `processed/${uniqueId}.jpg`,
      Body: transformedImageBuffer,
      ContentType: 'image/jpeg',
    };

    await s3.putObject(putObjectParams).promise();

    return {
      statusCode: 200,
      body: JSON.stringify({ message: 'Processing complete' }),
    };
  } catch (error) {
    // Retry or fallback strategy
    if (error.statusCode === 500 && error.retryable) {
      // Retry logic here
      console.error('Retrying image processing...');
      return await lambda.invoke({
        FunctionName: 'ImageProcessorLambda',
        InvocationType: 'RequestResponse',
        Payload: JSON.stringify(event),
      }).promise();
    } else {
      console.error('Error processing image:', error);
      throw new Error('Failed to process image');
    }
  }
};

