namespace Security {
    class SessionIDGenerator {
    public:
        SessionIDGenerator() : global_seed(0), rng(std::mt19937_64()) {
            secure_seed();
            generate_unique_session_id();
        }

        ~SessionIDGenerator() = default;

        static std::string generate_session_id(const Security::SessionIDGenerator& generator) {
            // Implement session ID generation logic here
            return base64_encode(generator.rng());
        }

        bool is_duplicate(const std::string& session_id) const {
            std::lock_guard<std::mutex> lock(mutex);
            return recently_generated_ids.find(session_id) != recently_generated_ids.end();
        }

    private:
        uint64_t global_seed;
        std::mt19937_64 rng;
        static constexpr size_t session_id_length = 22;
        static constexpr size_t cache_size = 1000;
        std::unordered_set<std::string> recently_generated_ids;
        mutable std::mutex mutex;

        void secure_seed() {
            // Seed the generator with current time and system entropy
            auto seed_time = std::chrono::system_clock::now().time_since_epoch().count();
            rng.seed(seed_time);

            std::ifstream urandom("/dev/urandom", std::ios::binary);
            if (urandom) {
                uint64_t additional_entropy;
                urandom.read(reinterpret_cast<char*>(&additional_entropy), sizeof(additional_entropy));
                rng.seed(global_seed ^ additional_entropy);
            }
        }

        void generate_unique_session_id() {
            std::string session_id;
            do {
                session_id = Security::SessionIDGenerator::generate_session_id(*this);
            } while (is_duplicate(session_id));

            std::lock_guard<std::mutex> lock(mutex);
            recently_generated_ids.insert(session_id);

            if (recently_generated_ids.size() > cache_size) {
                auto it = recently_generated_ids.begin();
                recently_generated_ids.erase(it);
            }
        }

        static std::string base64_encode(const uint64_t& number) {
            // Implement base64 encoding logic here
            return "base64_encoded_string";
        }
    };
}

int main() {
    Security::SessionIDGenerator generator;
    std::cout << "Generated Session ID: " << Security::SessionIDGenerator::generate_session_id(generator) << std::endl;
    return 0;
}
