#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>
#include <pthread.h>

typedef struct {
    sem_t *sem;
    pthread_mutex_t lock;
} Semaphore;

Semaphore* create_semaphore(int initial_value) {
    Semaphore *new_sem = malloc(sizeof(Semaphore));
    new_sem->sem = sem_open("/my_semaphore", O_CREAT, 0644, initial_value);
    if (new_sem->sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        free(new_sem);
        return NULL;
    }
    pthread_mutex_init(&new_sem->lock, NULL);
    return new_sem;
}

void acquire_semaphore(Semaphore *sem) {
    pthread_mutex_lock(&sem->lock);
    sem_wait(sem->sem);
    pthread_mutex_unlock(&sem->lock);
}

void release_semaphore(Semaphore *sem) {
    pthread_mutex_lock(&sem->lock);
    sem_post(sem->sem);
    pthread_mutex_unlock(&sem->lock);
}

void destroy_semaphore(Semaphore *sem) {
    sem_close(sem->sem);
    pthread_mutex_destroy(&sem->lock);
    free(sem);
}
