// Function to run performance-critical tests for traffic monitoring module
void runModuleTests(
    const std::string& moduleLabel,
    const std::vector<TestConfiguration>& testSuite,
    const std::string& loggingLevel,
    int cooldown,
    ResourceManager& resourceManager,
    DatabaseConnection& databaseConnection,
    int maxConcurrentTests,
    int testTimeout) {

    MockingLibrary mockingLib;
    std::mutex mutex;
    std::condition_variable cv;
    std::atomic<int> runningTests(0);

    for (const auto& config : testSuite) {
        if (runningTests >= maxConcurrentTests) {
            cv.wait(mutex, [&]() { return runningTests < maxConcurrentTests; });
        }

        ++runningTests;
        std::thread([&, &config](){
            resourceManager.manageResources(moduleLabel, [&]() {
                mockingLib.mockPart(moduleLabel, config.attackFunction);
                // Execute the test
                // Store results in the database
                databaseConnection.storeTestConfig(config.label);
            });
            mockingLib.resetMocking();
            --runningTests;
            cv.notify_all();
        }).detach();
    }
}

