using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Text.Json;
using System.Threading.Tasks;

public enum HashingAlgorithm { SHA256, Bcrypt, Argon2 }

public class SecurePasswordManager
{
    private Dictionary<string, string> userHashes = new();
    private Dictionary<string, object> resourceBundle = new();

    public void LoadResourceBundle(string filePath)
    {
        try
        {
            using (var reader = new StreamReader(filePath))
            {
                var jsonString = reader.ReadToEnd();
                resourceBundle = JsonSerializer.Deserialize<Dictionary<string, object>>(jsonString);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading resource bundle: {ex.Message}");
        }
    }

    public int GetResourceItemCount()
    {
        return resourceBundle.Count;
    }

    public void HashPassword(string username, string plainTextPassword, HashingAlgorithm algorithm)
    {
        byte[] salt = GenerateSalt();
        byte[] hashedPassword;

        switch (algorithm)
        {
            case HashingAlgorithm.SHA256:
                hashedPassword = ComputeSHA256Hash(plainTextPassword + Encoding.UTF8.GetString(salt));
                break;
            case HashingAlgorithm.Bcrypt:
                hashedPassword = BCrypt.Net.BCrypt.HashPassword(plainTextPassword, salt);
                break;
            case HashingAlgorithm.Argon2:
                using (var argon2 = new Argon2Hasher())
                {
                    hashedPassword = argon2.GetBytes(salt.Concat(Encoding.UTF8.GetBytes(plainTextPassword)).ToArray());
                }
                break;
            default:
                throw new ArgumentException("Unsupported hashing algorithm");
        }

        userHashes[username] = Convert.ToBase64String(hashedPassword);
    }

    public bool VerifyPassword(string username, string plainTextPassword)
    {
        if (!userHashes.ContainsKey(username))
        {
            return false;
        }

        byte[] salt = GenerateSalt();
        byte[] storedHash = Convert.FromBase64String(userHashes[username]);

        switch (GetUsedAlgorithm(storedHash))
        {
            case HashingAlgorithm.SHA256:
                return ComputeSHA256Hash(plainTextPassword + Encoding.UTF8.GetString(salt)).SequenceEqual(storedHash);
            case HashingAlgorithm.Bcrypt:
                return BCrypt.Net.BCrypt.Verify(plainTextPassword, storedHash);
            case HashingAlgorithm.Argon2:
                using (var argon2 = new Argon2Hasher())
                {
                    byte[] computedHash = argon2.GetBytes(salt.Concat(Encoding.UTF8.GetBytes(plainTextPassword)).ToArray());
                    return computedHash.SequenceEqual(storedHash);
                }
            default:
                throw new InvalidOperationException("Unsupported hashing algorithm");
        }
    }

    private static byte[] GenerateSalt()
    {
        using (var rng = RandomNumberGenerator.Create())
        {
            var salt = new byte[16];
            rng.GetBytes(salt);
            return salt;
        }
    }

    private static byte[] ComputeSHA256Hash(string input)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            return sha256.ComputeHash(Encoding.UTF8.GetBytes(input));
        }
    }

    private HashingAlgorithm GetUsedAlgorithm(byte[] hash)
    {
        // This is a simple check based on the length of the hash. Adjust as necessary.
        if (hash.Length == 32) return HashingAlgorithm.SHA256;
        else if (hash.Length > 32 && BCrypt.Net.BCrypt.Verify("", hash)) return HashingAlgorithm.Bcrypt;
        else if (hash.Length > 32 && !BCrypt.Net.BCrypt.Verify("", hash)) return HashingAlgorithm.Argon2;
        throw new InvalidOperationException("Unsupported hashing algorithm");
    }
}
