#include <stdlib.h>
#include <string.h>

char *appendSlashIfWithinLimit(const char *input, size_t sizeLimit) {
    if (input == NULL || sizeLimit == 0) {
        return NULL;
    }

    // Calculate the length of the input string
    size_t len = strlen(input);

    // Check if appending a slash would exceed the size limit
    if (len + 2 > sizeLimit) { // Extra space for '/' and '\0'
        return NULL;
    }

    // Allocate memory for the new string
    char *result = (char *)malloc(len + 2); // len + 1 for '/', and +1 for '\0'
    if (result == NULL) {
        return NULL; // Memory allocation failed
    }

    // Copy the input string to the new buffer
    strcpy(result, input);

    // Append a slash to the end of the string
    result[len] = '/';
    result[len + 1] = '\0';

    return result;
}
