    private readonly HttpClient _httpClient;
    private readonly IDistributedCache _cache;

    public HtmlService(HttpClient httpClient, IDistributedCache cache)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
    }

    public async Task UpdateHtmlContentAsync(string pageSectionId, string elementId, string updatedHtml, string revisionComment = null, int maxAttempts = 3)
    {
        if (string.IsNullOrEmpty(pageSectionId))
            throw new ArgumentException("Page section ID cannot be empty", nameof(pageSectionId));

        if (string.IsNullOrEmpty(elementId))
            throw new ArgumentException("Element ID cannot be empty", nameof(elementId));

        if (string.IsNullOrEmpty(updatedHtml))
            throw new ArgumentException("Updated HTML content cannot be empty", nameof(updatedHtml));

        string cacheKey = $"{pageSectionId}:{elementId}";

        while (maxAttempts > 0)
        {
            try
            {
                // Authenticate with external REST API
                await AuthenticateWithApiAsync();

                // Get current HTML content from cache
                string currentHtml = await _cache.GetStringAsync(cacheKey);
                if (string.IsNullOrEmpty(currentHtml))
                {
                    throw new InvalidOperationException("HTML content not found in cache");
                }

                // Validate versioning scheme and update HTML content
                if (!ValidateVersioning(currentHtml, updatedHtml))
                {
                    throw new InvalidOperationException("Invalid versioning detected");
                }

                string newHtml = UpdateElementHtmlContent(currentHtml, elementId, updatedHtml);

                // Store updated HTML content in cache with revision history
                await StoreUpdatedHtmlAsync(cacheKey, newHtml, revisionComment);

                break;
            }
            catch (Exception ex)
            {
                if (--maxAttempts == 0)
                    throw;

                // Log error and retry after a delay
                Console.WriteLine($"Error updating HTML content: {ex.Message}. Retrying...");
                await Task.Delay(1000);
            }
        }
