    private async Task StoreUpdatedHtmlAsync(string cacheKey, string htmlContent, string revisionComment)
    {
        var options = new DistributedCacheEntryOptions
        {
            AbsoluteExpirationRelativeToNow = TimeSpan.FromHours(1),
            SlidingExpiration = TimeSpan.FromMinutes(5),
            MaxSizeInBytes = 1024 * 1024 // 1 MB
        };

        await _cache.SetStringAsync(cacheKey, htmlContent, options);

        if (!string.IsNullOrEmpty(revisionComment))
        {
            var revisionKey = $"{cacheKey}:revisions";
            var currentRevisions = await _cache.GetStringAsync(revisionKey) ?? "[]";
            var revisions = JsonHelper.Deserialize<List<Revision>>(currentRevisions);
            revisions.Add(new Revision { Timestamp = DateTime.UtcNow, Comment = revisionComment });
            await _cache.SetStringAsync(revisionKey, JsonHelper.Serialize(revisions), options);
        }
    }
