use std::env;
use std::fs::{self, DirBuilder};
use std::path::Path;

fn create_directory_and_set_env_var(dir_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    if let Ok(env_value) = env::var(dir_name) {
        // Use existing environment variable value
    } else {
        // Create new directory with given name
        let path = Path::new(&dir_name);
        DirBuilder::new().recursive(true).create(path)?;

        // Set environment variable to the path of the newly created directory
        env::set_var(dir_name, path.to_str().unwrap());
    }

    Ok(())
}
