    public async Task<string> FetchAndCacheXmlAsync(Uri xmlUri)
    {
        if (_cache.TryGetValue(xmlUri.ToString(), out var cachedXml))
            return cachedXml;

        try
        {
            using (var response = await _httpClient.GetAsync(xmlUri, HttpCompletionOption.ResponseHeadersRead))
            {
                response.EnsureSuccessStatusCode();
                var xmlContent = await response.Content.ReadAsStringAsync();
                _cache.Add(xmlUri.ToString(), xmlContent);
                return xmlContent;
            }
        }
        catch (HttpRequestException ex)
        {
            // Handle network errors and retry logic here
            throw new RetryableException(ex.Message);
        }
    }

    public void Dispose()
    {
        _httpClient.Dispose();
        _cache.Dispose();
        _dhtClient.Dispose();
    }
}

