namespace RandomGenerator {
    class SecureMersenneTwister {
    public:
        SecureMersenneTwister(const std::string& seed) {
            // Seed the generator using a secure method
            seed_generator(seed);
        }

        ~SecureMersenneTwister() = default;

        static uint64_t generateUniformRandomNumber(uint64_t min, uint64_t max) {
            return distribution(generator()) % (max - min + 1) + min;
        }

        static double generateNormalRandomNumber(double mean, double stddev) {
            std::normal_distribution<> normal_dist(mean, stddev);
            return normal_dist(generator());
        }

    private:
        static std::mt19937_64 generator;
        static std::uniform_int_distribution<uint64_t> distribution;

        void seed_generator(const std::string& seed) {
            std::seed_seq seq(seed.begin(), seed.end());
            generator.seed(seq);
        }
    };

    // Initialize static members
    std::mt19937_64 SecureMersenneTwister::generator;
    std::uniform_int_distribution<uint64_t> SecureMersenneTwister::distribution(0, UINT64_MAX);
}
