// C code to modify filename extension based on original filename

#include <stdio.h>
#include <string.h>

void modify_filename(char *filename, int num_digits, const char *file_type) {
    char new_filename[256];
    strcpy(new_filename, filename);
    strcat(new_filename, "_");
    sprintf(new_filename + strlen(new_filename), "%d", num_digits);
    strcat(new_filename, ".");
    strcat(new_filename, file_type);

    // Copy the modified filename back to the original buffer
    strncpy(filename, new_filename, sizeof(new_filename) - 1);
}

int main() {
    char filename[256] = "example.txt";
    int num_digits = 3;
    const char *file_type = "log";

    modify_filename(filename, num_digits, file_type);

    printf("Original filename: %s\n", filename);

    return 0;
}
