// Function to fetch scripts from an external API endpoint
async function fetchScripts(url) {
    try {
        const response = await fetch(url);
        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }
        return await response.json();
    } catch (error) {
        console.error('Error fetching scripts:', error);
        throw error;
    }
}

// Function to render scripts as <script> tags
function renderScripts(scripts) {
    const scriptElements = [];
    for (const script of scripts) {
        const defaultType = 'text/javascript';
        const scriptElement = document.createElement('script');
        scriptElement.innerHTML = script.code || '';
        scriptElement.type = script.type || defaultType;
        if (script.key) {
            scriptElement.setAttribute('data-key', script.key);
        }
        scriptElements.push(scriptElement);
    }
    return scriptElements.map(el => el.outerHTML).join('');
}

// Function to manage and clean up old or unused script elements
function cleanupScripts() {
    const usedKeys = new Set();
    document.querySelectorAll('[data-key]').forEach(el => {
        usedKeys.add(el.getAttribute('data-key'));
    });
    document.querySelectorAll(`script:not([data-key])`).forEach(el => el.remove());
}

// Main function to fetch, render, and manage scripts
async function loadScripts(url) {
    try {
        const scripts = await fetchScripts(url);
        cleanupScripts();
        const renderedHtml = renderScripts(scripts);
        document.body.innerHTML += renderedHtml;
        // Trigger callback once all scripts have been successfully rendered
        onAllScriptsLoaded();
    } catch (error) {
        console.error('Error loading scripts:', error);
        // Display appropriate user feedback for network issues, timeouts, and unexpected responses from the external API
    }
}

// Event handler for script load completion
function onAllScriptsLoaded() {
    // Trigger a callback function once all scripts have been successfully rendered
}

// Function to manage script timeout values based on content type
function getScriptTimeout(contentType) {
    const timeouts = {
        'text/javascript': 5000,
        'application/json+script': 10000
    };
    return timeouts[contentType] || 3000;
}

// Example usage
const scriptUrl = 'https://api.example.com/scripts';
loadScripts(scriptUrl);
