// Configuration object for customization
const config = {
  cacheExpiry: 3600, // Cache expiry time in seconds
  defaultErrorMessage: 'Failed to load script',
  loadingSpinner: '<div>Loading...</div>',
};

// Cache object to store fetched scripts
const scriptCache = {};

// Function to fetch scripts from an external API
async function fetchScripts(urls) {
  const cachedScripts = urls.filter(url => scriptCache[url]);
  const newUrls = urls.filter(url => !scriptCache[url]);

  try {
    const responses = await Promise.all(newUrls.map(url => fetch(url)));
    const scripts = await Promise.all(responses.map(response => response.text()));
    return [...cachedScripts, ...scripts];
  } catch (error) {
    console.error('Error fetching scripts:', error);
    throw new Error(config.defaultErrorMessage);
  }
}

// Function to render scripts as a footer
function renderFooterScripts(scripts) {
  const scriptElements = scripts.map((script, index) => `
    <script key="script-${index}" type="${script.type || 'text/javascript'}">${script.code}</script>
  `).join('');

  return `<footer>${config.loadingSpinner}${scriptElements}</footer>`;
}

// Function to manage and clean up old script elements
function cleanupScripts() {
  const existingScripts = document.querySelectorAll('footer > script');
  existingScripts.forEach(script => script.remove());
}

// Main function to fetch, render, and update the DOM
async function updateFooterWithScripts(urls) {
  try {
    cleanupScripts();
    const scripts = await fetchScripts(urls);
    const htmlString = renderFooterScripts(scripts);
    document.querySelector('body').insertAdjacentHTML('beforeend', htmlString);
  } catch (error) {
    console.error('Error updating footer:', error);
  }
}

// Example usage
const scriptUrls = [
  'https://example.com/script1.js',
  'https://example.com/script2.js'
];
updateFooterWithScripts(scriptUrls);
```

This code snippet demonstrates a modular approach to fetching, rendering, and managing scripts for a web page footer. It includes features such as caching, dynamic loading, error handling, and performance optimization. The configuration object allows users to customize the behavior of script loading.

