using System;
using System.Collections.Generic;
using UnityEngine;

public delegate T DistributionFunction<T>(T min, T max);

public class AdvancedCustomRandomGenerator
{
    private static int currentSeed = Environment.TickCount;
    private static Random random = new Random(currentSeed);
    private static Dictionary<string, (DistributionFunction<float>, float[], float[])> distributionCache = new Dictionary<string, (DistributionFunction<float>, float[], float[])>();

    public static void SetSeed(int seed)
    {
        currentSeed = seed;
        random = new Random(seed);
    }

    public static int CustomRange(int min, int max)
    {
        return random.Next(min, max + 1);
    }

    public static float CustomRange(float min, float max)
    {
        return (float)(random.NextDouble() * (max - min) + min);
    }

    public static Vector2 CustomRange(Vector2 min, Vector2 max)
    {
        return new Vector2(CustomRange(min.x, max.x), CustomRange(min.y, max.y));
    }

    public static Vector3 CustomRange(Vector3 min, Vector3 max)
    {
        return new Vector3(CustomRange(min.x, max.x), CustomRange(min.y, max.y), CustomRange(min.z, max.z));
    }

    public static T GenerateRandomValue<T>(T min, T max) where T : IConvertible
    {
        if (typeof(T) == typeof(int))
            return (T)(object)CustomRange((int)Convert.ToInt32(min), (int)Convert.ToInt32(max));
        else if (typeof(T) == typeof(float))
            return (T)(object)CustomRange((float)Convert.ToSingle(min), (float)Convert.ToSingle(max));
        else
            throw new ArgumentException("Unsupported type");
    }

    public static T CustomRange<T>(DistributionFunction<T> distribution, params Tuple<float, float>[] ranges) where T : IConvertible
    {
        if (!distributionCache.ContainsKey(distribution.ToString()))
        {
            distributionCache[distribution.ToString()] = (distribution, Array.ConvertAll(ranges, x => x.Item1), Array.ConvertAll(ranges, x => x.Item2));
        }

        var cachedDistribution = distributionCache[distribution.ToString()];
        float[] values = new float[ranges.Length];

        for (int i = 0; i < ranges.Length; i++)
        {
            values[i] = cachedDistribution.distribution(cachedDistribution.minRange[i], cachedDistribution.maxRange[i]);
        }

        return (T)(object)values;
    }

    public static void AddCustomDistribution(string name, DistributionFunction<float> distribution, float[] minLimits, float[] maxLimits)
    {
        if (distributionCache.ContainsKey(name))
            throw new ArgumentException("Distribution already exists");

        distributionCache[name] = (distribution, minLimits, maxLimits);
    }

    // Additional methods and properties can be added here as per the requirements
}
