// Function to generate a secure random string
function generateSecureToken($length = 32, $charset = 'alphanumeric') {
    static $charsets = [
        'alphanumeric' => 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789',
        'special' => 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+{}|:"<>?[];', // Add more special characters as needed
    ];

    if (!isset($charsets[$charset])) {
        throw new InvalidArgumentException("Invalid character set provided.");
    }

    $characters = $charsets[$charset];
    $token = '';

    for ($i = 0; $i < $length; $i++) {
        $token .= $characters[random_int(0, strlen($characters) - 1)];
    }

    return hash('sha256', $token); // Hash the token for security
}

// Example usage:
$token = generateSecureToken(32, 'alphanumeric');
echo "Generated Token: " . $token;

?>
