```javascript
// config-merger.js
const fs = require('fs/promises');
const path = require('path');
const log4js = require('log4js');

log4js.configure({
  appenders: { out: { type: 'stdout' } },
  categories: { default: { appenders: ['out'], level: 'debug' } }
});
const logger = log4js.getLogger();

async function mergeConfigs(directory, fileTypes = ['.json'], defaults = {}) {
  const mergedConfig = { ...defaults };
  try {
    const files = await fs.readdir(directory);
    const promises = files
      .filter(file => fileTypes.includes(path.extname(file)))
      .map(async (file) => {
        try {
          const filePath = path.join(directory, file);
          const content = await fs.readFile(filePath, 'utf8');
          let config;
          try {
            config = JSON.parse(content);
          } catch (e) {
            logger.error(`Error parsing ${filePath}:`, e.message);
            throw new Error('Invalid JSON format');
          }
          return config;
        } catch (error) {
          logger.error(`Error reading ${file}:`, error.message);
          throw error;
        }
      });
    const configs = await Promise.all(promises);
    configs.forEach(config => Object.assign(mergedConfig, config));
  } catch (error) {
    logger.error('Failed to merge configurations:', error.message);
    throw error;
  }
  return mergedConfig;
}

module.exports = { mergeConfigs };
```

