// config-merger.test.js
const { mergeConfigs } = require('./config-merger');
const fs = require('fs/promises');
const path = require('path');

jest.mock('fs/promises', () => ({
  readdir: jest.fn(),
  readFile: jest.fn()
}));

describe('mergeConfigs', () => {
  let directory, fileTypes, defaults;

  beforeEach(() => {
    directory = '/test/configs';
    fileTypes = ['.json'];
    defaults = { defaultSetting: 'value' };
  });

  afterEach(() => {
    fs.readdir.mockReset();
    fs.readFile.mockReset();
  });

  it('reads and merges JSON files', async () => {
    const jsonContent1 = '{"key1": "value1"}';
    const jsonContent2 = '{"key2": "value2"}';

    fs.readdir.mockResolvedValue(['config1.json', 'config2.json']);
    fs.readFile.mockResolvedValueOnce(jsonContent1).mockResolvedValueOnce(jsonContent2);

    const result = await mergeConfigs(directory, fileTypes, defaults);
    expect(result).toEqual({ defaultSetting: 'value', key1: 'value1', key2: 'value2' });
  });

  it('handles missing files', async () => {
    fs.readdir.mockResolvedValue(['config1.json', 'missing.json']);
    fs.readFile.mockRejectedValueOnce(new Error('File not found'));

    await expect(mergeConfigs(directory, fileTypes)).rejects.toThrowError(/File not found/);
  });

  it('logs errors and continues merging', async () => {
    const jsonContent = '{"key": "value"}';
    logger.error = jest.fn();

    fs.readdir.mockResolvedValue(['config1.json', 'invalid.json']);
    fs.readFile.mockResolvedValueOnce(jsonContent).mockRejectedValueOnce(new Error('Invalid JSON format'));

    await mergeConfigs(directory, fileTypes);
    expect(logger.error).toHaveBeenCalledWith(expect.stringContaining('Error parsing invalid.json'));
  });

  it('uses default values for missing configurations', async () => {
    const result = await mergeConfigs(directory, fileTypes, { defaultSetting: 'value' });
    expect(result).toEqual({ defaultSetting: 'value' });
  });
});
