```javascript
// Import necessary libraries and modules
const express = require('express');
const bodyParser = require('body-parser');
const rateLimit = require('express-rate-limit');
const { Pool } = require('pg');

// Set up the Express app
const app = express();
app.use(bodyParser.json());
app.use(rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100 // limit each IP to 100 requests per windowMs
}));

// Create a PostgreSQL database connection pool
const pool = new Pool({
    user: 'your_username',
    host: 'localhost',
    database: 'your_database',
    password: 'your_password',
    port: 5432,
});

// Function to update an existing resource
app.put('/resources/:id', async (req, res) => {
    const { id } = req.params;
    const { body } = req;
    const { version, ifModifiedSince } = req.headers;

    try {
        // Check for optimistic concurrency control
        if (version) {
            const result = await pool.query('SELECT version FROM resources WHERE id=$1 AND version=$2', [id, version]);
            if (result.rows.length === 0) {
                return res.status(412).send('Precondition Failed');
            }
        }

        // Check for conditional update based on last modification timestamp
        if (ifModifiedSince) {
            const result = await pool.query('SELECT modified_at FROM resources WHERE id=$1', [id]);
            if (result.rows[0].modified_at > ifModifiedSince) {
                return res.status(409).send('Conflict');
            }
        }

        // Update the resource
        const updateResult = await pool.query('UPDATE resources SET data=$1, version=$2 WHERE id=$3', [body, Date.now(), id]);
        if (updateResult.rowCount === 0) {
            return res.status(404).send('Resource not found');
        }

        return res.status(200).send('Resource updated successfully');
    } catch (error) {
        console.error(error);
        res.status(500).send('Internal Server Error');
    }
});

// Function to delete a resource
app.delete('/resources/:id', async (req, res) => {
    const { id } = req.params;
    const { version, ifUnmodifiedSince } = req.headers;

    try {
        // Check for optimistic concurrency control
        if (version) {
            const result = await pool.query('SELECT version FROM resources WHERE id=$1 AND version=$2', [id, version]);
            if (result.rows.length === 0) {
                return res.status(412).send('Precondition Failed');
            }
        }

        // Check for conditional deletion based on last modification timestamp
        if (ifUnmodifiedSince) {
            const result = await pool.query('SELECT modified_at FROM resources WHERE id=$1', [id]);
            if (result.rows[0].modified_at < ifUnmodifiedSince) {
                return res.status(409).send('Conflict');
            }
        }

        // Delete the resource
        const deleteResult = await pool.query('DELETE FROM resources WHERE id=$1', [id]);
        if (deleteResult.rowCount === 0) {
            return res.status(404).send('Resource not found');
        }

        return res.status(200).send('Resource deleted successfully');
    } catch (error) {
        console.error(error);
        res.status(500).send('Internal Server Error');
    }
});

// Start the server
app.listen(3000, () => {
    console.log('Server is running on port 3000');
});
```

This code sets up a basic web API using Express.js to handle PUT and DELETE requests for resources. It includes error handling, rate limiting, and uses PostgreSQL for database operations with transactional safety. The API checks for optimistic concurrency control using version numbers and conditional update/deletion based on last modification timestamps.

