    const { id, version } = req.params;

    try {
        // Check if the specified version exists
        const result = await pool.query('SELECT * FROM resource_versions WHERE resource_id=$1 AND version=$2', [id, version]);
        if (result.rows.length === 0) {
            return res.status(404).send('Version not found');
        }

        // Revert the resource to the specified version
        const revertResult = await pool.query('UPDATE resources SET data=$1 WHERE id=$2', [JSON.stringify(result.rows[0].data), id]);
        if (revertResult.rowCount === 0) {
            return res.status(404).send('Resource not found');
        }

        return res.status(200).send('Resource reverted successfully to version ' + version);
    } catch (error) {
        console.error(error);
        res.status(500).send('Internal Server Error');
    }
});
