```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

#define MAX_THREADS 10

typedef struct {
    CURL *curl;
    char *url;
} Job;

Job jobs[MAX_THREADS];
int job_count = 0;
pthread_mutex_t job_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t job_cv = PTHREAD_COND_INITIALIZER;

void *worker(void *arg) {
    while (1) {
        Job job;
        pthread_mutex_lock(&job_lock);
        while (job_count == 0) {
            pthread_cond_wait(&job_cv, &job_lock);
        }
        job = jobs[--job_count];
        pthread_mutex_unlock(&job_lock);

        CURLcode res = curl_easy_setopt(job.curl, CURLOPT_URL, job.url);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_setopt() failed: %s\n", curl_easy_strerror(res));
            continue;
        }
        res = curl_easy_perform(job.curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            continue;
        }

        curl_easy_cleanup(job.curl);
    }
}

int main(int argc, char *argv[]) {
    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_create(&threads[i], NULL, worker, NULL);
    }

    // Example usage: Add URLs to the job queue
    jobs[0].curl = curl_easy_init();
    jobs[0].url = "http://example.com";
    pthread_mutex_lock(&job_lock);
    jobs[job_count++] = jobs[0];
    pthread_cond_signal(&job_cv);
    pthread_mutex_unlock(&job_lock);

    // Wait for threads to finish
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

