fn compile_directory(directory_path: &Path) -> Result<HashMap<PathBuf, CompilationResult>, io::Error> {
    let start_time = Instant::now();
    let mut results = HashMap::new();

    for entry in fs::read_dir(directory_path)? {
        let entry = entry?;
        let path = entry.path();
        if path.is_file() && path.extension().and_then(|ext| ext.to_str()) == Some("rs") {
            let start_time = Instant::now();
            let output = Command::new("rustc")
                .arg(path)
                .output()?;
            let end_time = Instant::now();

            results.insert(
                path,
                CompilationResult {
                    duration: end_time - start_time,
                    memory_usage: get_resident_set_size(),
                    output: String::from_utf8_lossy(&output.stdout).to_string(),
                    errors: String::from_utf8_lossy(&output.stderr).to_string(),
                },
            );
        }
    }

    results.insert(
        directory_path.to_path_buf(),
        CompilationResult {
            duration: start_time.elapsed(),
            memory_usage: get_resident_set_size(),
            output: format!("Total compilation time for directory {}", directory_path.display()),
            errors: String::new(),
        },
    );

    Ok(results)
}

