using System;
using System.Collections.Concurrent;
using System.Threading;
using UnityEngine;

public class AdvancedCustomRandomGenerator
{
    private static ConcurrentDictionary<int, Random> _randomGenerators = new ConcurrentDictionary<int, Random>();
    private static int _currentSeed = Environment.TickCount;
    private static readonly object _seedLock = new object();
    private static Timer _seedRotationTimer;
    private static readonly string ConfigFilePath = "path_to_config_file.xml";
    private static ConcurrentDictionary<string, float[]> _configRangeLimits = new ConcurrentDictionary<string, float[]>();
    private static Func<float> _customDistributionFunction;

    public AdvancedCustomRandomGenerator()
    {
        InitializeSeedRotation();
        LoadConfiguration();
    }

    private void InitializeSeedRotation()
    {
        lock (_seedLock)
        {
            if (_seedRotationTimer == null)
            {
                _seedRotationTimer = new Timer(RotateSeed, null, TimeSpan.Zero, TimeSpan.FromSeconds(60));
            }
        }
    }

    private static void RotateSeed(object state)
    {
        lock (_seedLock)
        {
            _currentSeed += 1;
            _randomGenerators.Values.ForEach(r => r.Seed = _currentSeed);
        }
    }

    public T CustomRange<T>(T min, T max) where T : IComparable<T>
    {
        if (min.CompareTo(max) > 0)
        {
            throw new ArgumentException("Min value must be less than or equal to Max value");
        }

        Random rng = _randomGenerators.GetOrAdd(Thread.CurrentThread.ManagedThreadId, new Random(_currentSeed));
        if (typeof(T) == typeof(float))
        {
            return (T)(object)rng.NextFloat((float)min, (float)max);
        }
        else if (typeof(T) == typeof(int))
        {
            return (T)(object)rng.Next((int)min, (int)max + 1);
        }

        throw new NotSupportedException("Unsupported type");
    }

    public Tuple<T, T> CustomRange<T>(Tuple<T, T> min, Tuple<T, T> max) where T : IComparable<T>
    {
        return new Tuple<T, T>(
            CustomRange(min.Item1, max.Item1),
            CustomRange(min.Item2, max.Item2)
