from threading import Lock
import time
import logging
import hashlib
import sys

# Set up logging
logging.basicConfig(level=logging.INFO)

class DirectoryManager:
    # Class variables
    _lock = Lock()
    _cache = {}
    _config = {
        'retry_attempts': 5,
        'timeout': 10,
        'temp_dir_lifetime': 3600
    }

    @staticmethod
    def create_directory(path, parent=None):
        with DirectoryManager._lock:
            if path in DirectoryManager._cache:
                return DirectoryManager._cache[path]

            attempt = 0
            while attempt < DirectoryManager._config['retry_attempts']:
                try:
                    if parent is not None:
                        os.makedirs(parent, exist_ok=True)
                    os.makedirs(path, exist_ok=True)
                    DirectoryManager._cache[path] = True
                    return True
                except (FileExistsError, PermissionError, OSError) as e:
                    logging.warning(f"Failed to create directory {path}: {e}")
                    attempt += 1
                    time.sleep(DirectoryManager._config['timeout'])

            raise Exception(f"Failed to create directory {path} after {DirectoryManager._config['retry_attempts']} attempts")

    @staticmethod
    def delete_directory(path):
        with DirectoryManager._lock:
            if path in DirectoryManager._cache:
                shutil.rmtree(path)
                del DirectoryManager._cache[path]

