using System;
using System.IO;
using System.Xml;
using System.Xml.Linq;
using System.Xml.Schema;
using System.Xml.XPath;
using Microsoft.Extensions.Caching.Memory;

public class DynamicXmlManager : IDynamicXmlManager
{
    private readonly IMemoryCache _cache;
    private readonly XmlSchemaSet _schemaSet;

    public DynamicXmlManager(IMemoryCache cache)
    {
        _cache = cache;
        _schemaSet = new XmlSchemaSet();
        // Load XSD schemas into the schema set
        _schemaSet.Add("namespace", "path_to_schema_file");
    }

    public async Task<string> ParseAndValidateXmlAsync(string xmlContent, string xsdNamespace)
    {
        if (!_cache.TryGetValue(xsdNamespace, out var xmlDoc))
        {
            using (var reader = new StringReader(xmlContent))
            {
                var doc = XDocument.Load(reader);
                await ValidateXmlAsync(doc, xsdNamespace);
                _cache.Set(xsdNamespace, doc, new MemoryCacheEntryOptions().SetAbsoluteExpiration(TimeSpan.FromMinutes(30)));
                xmlDoc = doc;
            }
        }

        return xmlDoc.ToString();
    }

    private async Task ValidateXmlAsync(XDocument xml, string xsdNamespace)
    {
        var settings = new XmlReaderSettings
        {
            Schemas = _schemaSet,
            ValidationType = ValidationType.Schema
        };
        settings.ValidationEventHandler += (sender, e) => throw new Exception(e.Message);

        using (var reader = XmlReader.Create(new StringReader(xml.ToString()), settings))
        {
            while (await reader.ReadAsync()) { }
        }
    }

    public async Task<string> ExecuteXPathQueryAsync(string xmlContent, string xpathExpression)
    {
        var xmlDoc = await ParseAndValidateXmlAsync(xmlContent, "namespace");
        using (var reader = XmlReader.Create(new StringReader(xmlDoc.ToString())))
        {
            var navigator = XDocument.Load(reader).CreateNavigator();
            var results = navigator.Select(xpathExpression);

            if (!results.MoveNext())
                throw new InvalidOperationException("No results found for the XPath query.");

            return results.Current.Value;
        }
    }

    // Dependency injection interface
    public interface IDynamicXmlManager { }
}
