    public class XmlDocumentManager : IDisposable
    {
        private readonly ConcurrentDictionary<string, XDocument> _cache = new ConcurrentDictionary<string, XDocument>();
        private readonly XSchemaSet _schemaSet;
        private readonly Func<XDocument> _xmlLoader;
        private readonly string _versionControlKey;

