        if ($this->isRateLimited($userIp)) {
            throw new Exception("Rate limit exceeded. Please try again later.");
        }

        // Transaction handling
        $this->db->beginTransaction();

        try {
            // Update clinic status
            $stmt = $this->db->prepare("UPDATE clinics SET status = :status, last_modified = NOW(), last_modified_ip = :ip WHERE id = :id");
            $stmt->execute([':status' => $newStatus, ':ip' => $userIp, ':id' => $clinicId]);

            // Log update
            $this->logUpdate($clinicId, $userId, $reason, $newStatus);

            // Commit transaction
            $this->db->commit();
        } catch (Exception $e) {
            // Rollback in case of error
            $this->db->rollBack();
            throw new Exception("Failed to update clinic status: " . $e->getMessage());
