import java.io.*;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;
import java.util.concurrent.*;

public class FileHashValidator {

    private static final int BUFFER_SIZE = 8192;
    private static final int MAX_RETRIES = 3;

    public Map<String, String> validateFileHashes(List<String> filePaths, Set<String> supportedAlgorithms, int retryCount) throws HashMismatchException {
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        CompletionService<Map.Entry<String, String>> completionService = new ExecutorCompletionService<>(executor);

        for (String filePath : filePaths) {
            completionService.submit(() -> {
                try {
                    String algorithm = selectAlgorithm(supportedAlgorithms);
                    MessageDigest md = MessageDigest.getInstance(algorithm);
                    String computedHash = computeFileHash(filePath, md);
                    String serviceHash = fetchServiceHash(filePath);
                    validateHash(computedHash, serviceHash);
                    return new AbstractMap.SimpleEntry<>(filePath, computedHash);
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            });
        }

        Map<String, String> resultMap = new HashMap<>();
        for (int i = 0; i < filePaths.size(); i++) {
            try {
                Future<Map.Entry<String, String>> future = completionService.take();
                resultMap.put(future.get().getKey(), future.get().getValue());
            } catch (InterruptedException | ExecutionException e) {
                throw new HashMismatchException("Error processing file: " + e.getMessage());
            }
        }

        executor.shutdown();
        return resultMap;
    }

    private String selectAlgorithm(Set<String> supportedAlgorithms) {
        // Implement logic to select an appropriate hashing algorithm
        return "MD5"; // Placeholder
    }

    private String computeFileHash(String filePath, MessageDigest md) throws IOException {
        try (InputStream is = new FileInputStream(filePath)) {
            byte[] buffer = new byte[BUFFER_SIZE];
            int bytesRead;
            while ((bytesRead = is.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
        }
        return bytesToHex(md.digest());
    }

    private String fetchServiceHash(String filePath) throws IOException, InterruptedException, ExecutionException {
        URL url = new URL("https://api.service.com/hash?file=" + URLEncoder.encode(filePath, StandardCharsets.UTF_8));
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");
        int responseCode = connection.getResponseCode();

        if (responseCode == HttpURLConnection.HTTP_OK) {
            try (BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
                return in.readLine();
            }
        } else {
            throw new IOException("Failed to fetch service hash. Response code: " + responseCode);
        }
    }

    private void validateHash(String computedHash, String serviceHash) throws HashMismatchException {
        if (!computedHash.equals(serviceHash)) {
            throw new HashMismatchException("Hash mismatch for file");
        }
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static class HashMismatchException extends Exception {
        public HashMismatchException(String message) {
            super(message);
        }
    }
}
