    long* offsets = (long*)malloc(count * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        return NULL;
    }

    int* keys = (int*)malloc(count * sizeof(int));
    if (!keys) {
        free(offsets);
        perror("Failed to allocate memory for keys");
        return NULL;
    }

    Record* records = (Record*)malloc(count * sizeof(Record));
    if (!records) {
        free(offsets);
        free(keys);
        perror("Failed to allocate memory for records");
        return NULL;
    }

    srand(time(NULL));

    // Simulate external data source with random key generation
    for (long i = 0; i < count; ++i) {
        int key;
        do {
            key = rand() % 100000; // Assuming the range is 0-99,999
        } while (is_key_unique(keys, i, key));

        keys[i] = key;
        records[i].field = key;
    }

    // Simulate external data source delay
    sleep(2);

    for (long i = 0; i < count; ++i) {
        offsets[i] = i * sizeof(int); // Example offset calculation
    }

    pthread_exit(NULL);
}

int is_key_unique(int* keys, long index, int key) {
    for (long i = 0; i < index; ++i) {
        if (keys[i] == key) {
            return 1;
        }
    }
    return 0;
}

