    LogLevel_WARNING,
    LogLevel_INFO,
    // Add more log levels as needed
} LogLevel;

LogLevel current_log_level = LogLevel_INFO;
int message_count = 0;
char buffer[MAX_MESSAGE_SIZE];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void setLogLevel(const char *level_str) {
    if (strcmp(level_str, "ERROR") == 0) current_log_level = LogLevel_ERROR;
    else if (strcmp(level_str, "WARNING") == 0) current_log_level = LogLevel_WARNING;
    else if (strcmp(level_str, "INFO") == 0) current_log_level = LogLevel_INFO;
    // Add more levels as needed
}

void rotateLogfile() {
    // Implement file rotation logic here
    message_count = 0;
}

void logCondition(const char *level_str, const char *format, ...) {
    va_list args;
    pthread_mutex_lock(&lock);

    if (message_count >= 1000) {
        rotateLogfile();
    }

    snprintf(buffer, MAX_MESSAGE_SIZE, "[%s] %s: ", level_str, format);
    va_start(args, format);
    vsnprintf(buffer + strlen(buffer), MAX_MESSAGE_SIZE - strlen(buffer), format, args);
    va_end(args);

    FILE *logFile = fopen("error_log.txt", "a");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    fprintf(logFile, "%s\n", buffer);
    fclose(logFile);
    message_count++;

    pthread_mutex_unlock(&lock);
}

int main() {
    setLogLevel("ERROR");

    logCondition("ERROR", "Failed to allocate memory for %s", "user");
    logCondition("WARNING", "Low disk space: %d GB remaining", 5);

    return 0;
}
