```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class SecureFileManagementSystem
{
    private readonly string _encryptionKey;
    private readonly string _salt;
    private readonly ICloudStorageService _storageService;
    private readonly ILogger _logger;

    public SecureFileManagementSystem(string encryptionKey, string salt, ICloudStorageService storageService, ILogger logger)
    {
        _encryptionKey = encryptionKey;
        _salt = salt;
        _storageService = storageService ?? throw new ArgumentNullException(nameof(storageService));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task UploadFileAsync(string filePath, string destinationPath)
    {
        try
        {
            var (encryptedData, nonce, tag) = EncryptFile(filePath);
            await _storageService.UploadMetadataAsync(destinationPath, encryptedData, nonce, tag);
            _logger.LogInformation($"File uploaded successfully: {destinationPath}");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error uploading file");
            throw;
        }
    }

    public async Task DownloadFileAsync(string sourcePath, string destinationPath)
    {
        try
        {
            var (encryptedData, nonce, tag) = await _storageService.DownloadMetadataAsync(sourcePath);
            DecryptFile(encryptedData, nonce, tag, destinationPath);
            _logger.LogInformation($"File downloaded successfully: {destinationPath}");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error downloading file");
            throw;
        }
    }

    private byte[] EncryptFile(string filePath)
    {
        using var aesGcm = Aes.Create();
        aesGcm.GenerateKey(32);
        aesGcm.GenerateIV();

        var (encryptedData, nonce, tag) = aesGcm.EncryptFile(filePath, _salt);

        return encryptedData;
    }

    private void DecryptFile(byte[] encryptedData, byte[] nonce, byte[] tag, string destinationPath)
    {
        using var aesGcm = Aes.Create();
        aesGcm.GenerateKey(32);
        aesGcm.IV = nonce;

        aesGcm.DecryptFile(encryptedData, tag, destinationPath, _salt);
    }
}

public interface ICloudStorageService
{
    Task UploadMetadataAsync(string filePath, byte[] encryptedData, byte[] nonce, byte[] tag);
    Task<(byte[] encryptedData, byte[] nonce, byte[] tag)> DownloadMetadataAsync(string filePath);
}

public interface ILogger
{
    void LogInformation(string message);
    void LogError(Exception ex, string errorMessage);
}
