#include <iostream>
#include <fstream>
#include <string>
#include <unordered_map>
#include <variant>
#include <json/json.h> // Include a JSON library like nlohmann's json.hpp

// Function to load configuration settings from a JSON file
std::unordered_map<std::string, std::variant<int, double, std::string, bool>> loadConfig(const std::string& filePath) {
    try {
        std::ifstream file(filePath);
        if (!file.is_open()) {
            throw std::runtime_error("Failed to open configuration file: " + filePath);
        }

        Json::Value root;
        file >> root;

        // Convert JSON values to variant types
        std::unordered_map<std::string, std::variant<int, double, std::string, bool>> configMap;
        for (const auto& item : root) {
            if (!item.isMember("key") || !item["key"].isString()) {
                throw std::runtime_error("Invalid key in configuration file");
            }
            const std::string& key = item["key"].asString();
            if (!item.isMember("value")) {
                throw std::runtime_error("Missing value for key: " + key);
            }

            Json::Value value = item["value"];
            if (value.isInt()) configMap[key] = value.asInt();
            else if (value.isDouble()) configMap[key] = value.asDouble();
            else if (value.isString()) configMap[key] = value.asString();
            else if (value.isBool()) configMap[key] = value.asBool();
            else throw std::runtime_error("Unsupported type for key: " + key);
        }

        return configMap;

    } catch (const Json::Exception& e) {
        // Log JSON parsing error
        std::cerr << "JSON parsing error: " << e.what() << std::endl;
        throw;
    } catch (const std::exception& e) {
        // Log general error
        std::cerr << "Error loading configuration: " << e.what() << std::endl;
        throw;
    }
}

int main() {
    try {
        auto config = loadConfig("config.json");
        // Process the configuration settings
    } catch (const std::exception& e) {
        // Handle exceptions
    }

    return 0;
}
