```java
import java.io.ByteArrayInputStream;
import java.io.ObjectInputStream;
import java.util.Properties;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class RandomStringGenerator {
    private static final Properties charsetProperties = new Properties();

    static {
        try (InputStream input = Thread.currentThread().getContextClassLoader().getResourceAsStream("charset.properties")) {
            if (input == null) throw new RuntimeException("Property file not found in the classpath.");
            charsetProperties.load(input);
        } catch (IOException e) {
            throw new RuntimeException("Failed to load properties.", e);
        }
    }

    public static String generateRandomString(byte[] data, int length) {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
            // Deserialize object
            Object obj = ois.readObject();
            return hashToString(obj.toString(), "SHA-256").substring(0, length);
        } catch (Exception e) {
            throw new RuntimeException("Failed to generate random string.", e);
        }
    }

    public static String hashToString(String input, String algorithm) {
        try {
            MessageDigest digest = MessageDigest.getInstance(algorithm);
            byte[] hashBytes = digest.digest(input.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Hash algorithm not found.", e);
        }
    }

    public static String hashPassword(String password, String algorithm) {
        return hashToString(password, algorithm);
    }
}
