#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/sha.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[32];
    unsigned char iv[16];
} AESContext;

void cleanup(AESContext *ctx) {
    if (ctx->ctx != NULL) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        ctx->ctx = NULL;
    }
}

int generate_key_iv(const char *password, int key_length, AESContext *ctx) {
    SHA256((unsigned char *)password, strlen(password), ctx->key);
    if (key_length == 192) {
        memcpy(ctx->iv, &ctx->key[32], 16);
    } else if (key_length == 256) {
        memcpy(ctx->iv, &ctx->key[48], 16);
    } else {
        return -1; // Invalid key length
    }
    return 0;
}

int init_cipher(const char *password, int key_length, AESContext **ctx_ptr) {
    AESContext *ctx = (AESContext *)malloc(sizeof(AESContext));
    if (ctx == NULL) {
        return -1; // Memory allocation failed
    }

    ctx->ctx = EVP_CIPHER_CTX_new();
    if (ctx->ctx == NULL) {
        free(ctx);
        return -1; // EVP_CIPHER_CTX creation failed
    }

    if (generate_key_iv(password, key_length, ctx) != 0) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
        return -1; // Key/IV generation failed
    }

    *ctx_ptr = ctx;
    return 0;
}

void disable_cipher(AESContext *ctx) {
    cleanup(ctx);
    free(ctx);
}
