#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <libcurl/curl.h>
#include <pthread.h>

#define MAX_URLS 1024
#define MAX_THREADS 512

typedef struct {
    CURL *curl;
    char url[MAX_URLS];
} Task;

void* worker(void* arg) {
    Task task = *(Task*)arg;
    CURLcode res = curl_easy_setopt(task.curl, CURLOPT_URL, task.url);
    if(res != CURLE_OK) {
        fprintf(stderr, "Failed to set URL: %s\n", curl_easy_strerror(res));
        return NULL;
    }

    res = curl_easy_perform(task.curl);
    if(res != CURLE_OK) {
        fprintf(stderr, "Curl failed with error: %s\n", curl_easy_strerror(res));
    }

    curl_easy_cleanup(task.curl);
    return NULL;
}

int main(int argc, char *argv[]) {
    CURL *multi_handle = curl_multi_init();
    Task tasks[MAX_THREADS];
    int num_tasks = 0;

    // Example URLs to scrape
    strcpy(tasks[num_tasks++].url, "http://example.com");
    strcpy(tasks[num_tasks++].url, "http://example.org");

    for(int i = 0; i < num_tasks; i++) {
        tasks[i].curl = curl_easy_init();
        if(curl_multi_add_handle(multi_handle, tasks[i].curl) != CURLM_OK) {
            fprintf(stderr, "Failed to add handle %d\n", i);
            return 1;
        }
    }

    int still_running;
    while(1) {
        CURLMcode mc = curl_multi_perform(multi_handle, &still_running);
        if(mc != CURLM_OK) {
            fprintf(stderr, "Curl multi perform failed with error: %d\n", mc);
            break;
        }

        if(still_running == 0)
            break;

        struct timeval timeout;
        timeout.tv_sec = 1;
        timeout.tv_usec = 0;
        int rc = select(curl_multi_fdset(multi_handle, NULL), NULL, NULL, &timeout, NULL);

        if(rc == -1) {
            fprintf(stderr, "Select failed\n");
            break;
        }
    }

    for(int i = 0; i < num_tasks; i++) {
        curl_multi_remove_handle(multi_handle, tasks[i].curl);
        curl_easy_cleanup(tasks[i].curl);
    }

    curl_multi_cleanup(multi_handle);
    return 0;
}
