import random
from gremlin_python import statics
from gremlin_python.structure.graph import Graph
from gremlin_python.driver.driver_remote_connection import DriverRemoteConnection
from gremlin_python.process.traversal import __
from external_property_store import ExternalPropertyStore

class GraphManager:
    def __init__(self, graph_uri, property_store_url):
        self.graph = Graph()
        self.g = self.graph.traversal().withRemote(DriverRemoteConnection(graph_uri, 'g'))
        self.property_store = ExternalPropertyStore(property_store_url)

    def add_random_vertices_and_edges(self, num_vertices, num_edges):
        try:
            for _ in range(num_vertices):
                vertex_id = self.add_vertex_with_properties()

            for _ in range(num_edges):
                self.add_edge_between_vertices(vertex_id1, vertex_id2)

        except Exception as e:
            print(f"An error occurred: {e}")

    def add_vertex_with_properties(self):
        vertex = self.g.addV('vertex_type').next()
        properties = self.generate_random_properties()
        for key, value in properties.items():
            vertex.property(key, value)
        self.property_store.set_property(vertex.id, properties)
        return vertex.id

    def add_edge_between_vertices(self, vertex_id1, vertex_id2):
        edge = self.g.V(vertex_id1).addE('edge_type').to(self.g.V(vertex_id2)).next()
        properties = self.generate_random_properties()
        for key, value in properties.items():
            edge.property(key, value)
        self.property_store.set_property(edge.id, properties)

    def generate_random_properties(self):
        return {
            'property1': random.randint(0, 100),
            'property2': random.random(),
            'property3': ''.join(random.choices('abcdefghijklmnopqrstuvwxyz', k=5))
        }

    def cleanup_resources(self):
        self.property_store.close()
