// Function to initialize AES-NI-256-GCM cipher with a given password
EVP_CIPHER_CTX *init_aes_cipher(const char *password, int key_len, int iv_len, int tag_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return NULL;
    }

    const char *cipher_name = "aes-256-gcm";
    int pbkdf2_iterations = 10000; // Example value

    EVP_CIPHER *cipher;
    load_config("config.ini", &cipher, &key_len, &iv_len, &tag_len);

    if (!EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL)) {
        fprintf(stderr, "Failed to initialize cipher context\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Generate key and IV securely
    unsigned char key[key_len];
    unsigned char iv[iv_len];

    if (!RAND_bytes(key, key_len) || !RAND_bytes(iv, iv_len)) {
        fprintf(stderr, "Failed to generate random key or IV\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Set encryption parameters
    if (!EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv)) {
        fprintf(stderr, "Failed to set encryption parameters\n");
        secure_delete(key, key_len);
        secure_delete(iv, iv_len);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Set tag length for GCM mode
    if (!EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG_LENGTH, tag_len, NULL)) {
        fprintf(stderr, "Failed to set tag length\n");
        secure_delete(key, key_len);
        secure_delete(iv, iv_len);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Set key stretching using PBKDF2
    if (!EVP_PKEY_CTX_set_pbkdf2_rounds(EVP_PKEY_CTX_new_id(EVP_PKEY_HMAC, NULL), pbkdf2_iterations)) {
        fprintf(stderr, "Failed to set PBKDF2 iterations\n");
        secure_delete(key, key_len);
        secure_delete(iv, iv_len);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Set the password for key stretching
    if (!EVP_PKEY_derive_init(EVP_PKEY_CTX_new_id(EVP_PKEY_HMAC, NULL))) {
        fprintf(stderr, "Failed to initialize key derivation context\n");
        secure_delete(key, key_len);
        secure_delete(iv, iv_len);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (!EVP_PKEY_derive_set_peer(EVP_PKEY_CTX_new_id(EVP_PKEY_HMAC, NULL), password)) {
        fprintf(stderr, "Failed to set peer for key derivation\n");
        secure_delete(key, key_len);
        secure_delete(iv, iv_len);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (!EVP_PKEY_derive(EVP_PKEY_CTX_new_id(EVP_PKEY_HMAC, NULL), key, &key_len)) {
        fprintf(stderr, "Failed to derive key\n");
        secure_delete(key, key_len);
        secure_delete(iv, iv_len);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Set the derived key and IV for encryption
    if (!EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv)) {
        fprintf(stderr, "Failed to set encryption parameters with derived key\n");
        secure_delete(key, key_len);
        secure_delete(iv, iv_len);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

// Example usage
int main() {
    const char *password = "my_secure_password";
    int key_len = 32; // 256-bit key length
    int iv_len = 12;  // 96-bit IV length
    int tag_len = 16; // 128-bit authentication tag

    EVP_CIPHER_CTX *ctx = init_aes_cipher(password, key_len, iv_len, tag_len);
    if (ctx) {
        printf("Cipher initialized successfully\n");
        EVP_CIPHER_CTX_free(ctx);
    }

    return 0;
}
