// Define the ScriptFooter module
const ScriptFooter = (function() {
    // Private variables and functions

    const scriptsCache = new Map();
    const spinnerElement = document.createElement('div');
    spinnerElement.textContent = 'Loading...';
    spinnerElement.style.position = 'fixed';
    spinnerElement.style.top = '50%';
    spinnerElement.style.left = '50%';
    spinnerElement.style.transform = 'translate(-50%, -50%)';
    spinnerElement.style.backgroundColor = 'rgba(255, 255, 255, 0.8)';
    spinnerElement.style.padding = '10px';
    document.body.appendChild(spinnerElement);

    function showSpinner() {
        spinnerElement.style.display = 'block';
    }

    function hideSpinner() {
        spinnerElement.style.display = 'none';
    }

    function isValidScript(script) {
        return script && script.code || script.src;
    }

    function fetchScript(url) {
        return fetch(url)
            .then(response => response.text())
            .catch(error => {
                console.error('Failed to fetch script:', error);
                return null;
            });
    }

    function renderScript(script, container = document.body) {
        if (!isValidScript(script)) {
            console.warn('Invalid script object provided');
            return;
        }

        if (scriptsCache.has(script.src)) {
            const cachedScript = scriptsCache.get(script.src);
            container.appendChild(cachedScript.cloneNode(true));
            return;
        }

        showSpinner();

        let newScript;
        if (script.code) {
            newScript = document.createElement('script');
            newScript.textContent = script.code;
        } else if (script.src) {
            newScript = document.createElement('script');
            newScript.src = script.src;
            newScript.async = true;
        }

        newScript.onload = () => {
            scriptsCache.set(script.src, newScript);
            container.appendChild(newScript);
            hideSpinner();
        };

        newScript.onerror = () => {
            console.error('Failed to load script:', script.src);
            hideSpinner();
        };
    }

    function renderScripts(scripts) {
        const container = document.getElementById('footer-scripts');
        if (!container) {
            console.warn('Footer scripts container not found');
            return;
        }

        scripts.forEach(renderScript, this);
    }

    // Public API
    return {
        fetchAndRenderScripts: async (urls) => {
            showSpinner();
            try {
                const scriptPromises = urls.map(fetchScript);
                const scripts = await Promise.all(scriptPromises);
                renderScripts(scripts.filter(Boolean));
            } catch (error) {
                console.error('Error fetching and rendering scripts:', error);
            } finally {
                hideSpinner();
            }
        }
    };
})();

// Example usage
document.addEventListener('DOMContentLoaded', () => {
    const scriptUrls = [
        'https://example.com/script1.js',
        'https://example.com/script2.js'
    ];
    ScriptFooter.fetchAndRenderScripts(scriptUrls);
});
