import asyncio
from aiohttp import ClientSession
from aioredis import Redis
from functools import lru_cache
from typing import Dict, List

# Constants
MAX_RETRIES = 5
RATE_LIMIT = 10  # requests per second
CACHE_EXPIRATION = {
    "Preparing": 3600,
    "On the Way": 600,
    "Delivered": 300
}

class OrderProcessingException(Exception):
    pass

async def fetch_delivery_person_info(order_id: str, session: ClientSession) -> Dict:
    url = f"https://deliveryapi.com/person/{order_id}"
    for attempt in range(MAX_RETRIES):
        try:
            async with session.get(url) as response:
                if response.status == 200:
                    return await response.json()
                else:
                    raise OrderProcessingException(f"Failed to fetch delivery person info: {response.status}")
        except Exception as e:
            print(f"Attempt {attempt + 1} failed: {e}")
            await asyncio.sleep(1)  # Exponential backoff
    raise OrderProcessingException("Max retries exceeded for fetching delivery person info")

@lru_cache(maxsize=128)
def get_order_status_expiration(order_status: str) -> int:
    return CACHE_EXPIRATION.get(order_status, 3600)

async def update_order_batch(orders: List[Dict], redis_client: Redis) -> None:
    async with ClientSession() as session:
        for order in orders:
            try:
                # Validate status transition logic here
                new_status = order["status"]
                current_status = await redis_client.get(f"order:{order['id']}:status")
                if current_status and new_status != "Delivered":
                    raise OrderProcessingException("Invalid status transition")

                delivery_person = await fetch_delivery_person_info(order["id"], session)
                order.update(delivery_person)

                # Update Redis with new order details
                await redis_client.set(f"order:{order['id']}:status", new_status, expire=get_order_status_expiration(new_status))
                for field in order:
                    if field != "id":
                        await redis_client.hset(f"order:{order['id']}", field, order[field])

            except OrderProcessingException as e:
                print(f"Error updating order {order['id']} - {str(e)}")

async def handle_order_batch_processing(orders: List[Dict]) -> None:
    # Partition orders into sub-batches if necessary
    sub_batches = [orders[i:i+10] for i in range(0, len(orders), 10)]

    async with Redis() as redis_client:
        tasks = []
        for batch in sub_batches:
            tasks.append(update_order_batch(batch, redis_client))

        await asyncio.gather(*tasks)

# Example usage
if __name__ == "__main__":
    orders = [
        {"id": "1", "status": "Preparing"},
        {"id": "2", "status": "Delivered"}
    ]
    asyncio.run(handle_order_batch_processing(orders))
```

