import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class DistributedCache {
    private final ConcurrentHashMap<String, CacheEntry> cache = new ConcurrentHashMap<>();
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);

    public DistributedCache() {
        // Start TTL cleanup task
        scheduler.scheduleAtFixedRate(this::cleanupExpiredEntries, 1, 1, TimeUnit.MINUTES);
    }

    public void put(String key, Object value, int ttl) {
        CacheEntry entry = new CacheEntry(value, System.currentTimeMillis() + ttl);
        cache.put(key, entry);
    }

    public Object get(String key) {
        CacheEntry entry = cache.get(key);
        if (entry != null && !isExpired(entry)) {
            return entry.getValue();
        }
        return null;
    }

    public void evict(String key) {
        cache.remove(key);
    }

    private boolean isExpired(CacheEntry entry) {
        return System.currentTimeMillis() > entry.getExpiryTime();
    }

    private void cleanupExpiredEntries() {
        cache.entrySet().removeIf(entry -> isExpired(entry.getValue()));
    }

    private static class CacheEntry {
        private final Object value;
        private final long expiryTime;

        public CacheEntry(Object value, long expiryTime) {
            this.value = value;
            this.expiryTime = expiryTime;
        }

        public Object getValue() {
            return value;
        }

        public long getExpiryTime() {
            return expiryTime;
        }
    }

    // Add methods for handling node management, coordination with ZooKeeper,
    // integrating with cloud provider's storage service, and data rebalancing.
}

