import threading
import logging
from queue import Queue, Empty
import psycopg2
from sqlalchemy import create_engine, text

class DatabaseConnectionManager:
    def __init__(self, db_type, db_config, max_connections=10):
        self.db_type = db_type
        self.db_config = db_config
        self.max_connections = max_connections
        self.pool = Queue(maxsize=max_connections)
        self.lock = threading.Lock()
        self.logger = logging.getLogger(__name__)
        self._initialize_pool()

    def _initialize_pool(self):
        for _ in range(self.max_connections):
            conn = self._create_connection()
            if conn:
                self.pool.put(conn)

    def _create_connection(self):
        try:
            if self.db_type == 'postgres':
                return psycopg2.connect(**self.db_config)
            # Add other database types here
            else:
                raise ValueError("Unsupported database type")
        except Exception as e:
            self.logger.error(f"Failed to create connection: {e}")
            return None

    def establish_connection(self):
        try:
            conn = self.pool.get(block=False)
            if conn.closed:
                conn = self._create_connection()
            if conn is not None:
                return conn
        except Empty:
            pass
        raise Exception("No available connections in pool")

    def execute_query(self, query, params=None):
        conn = self.establish_connection()
        try:
            with conn.cursor() as cursor:
                if params:
                    cursor.execute(text(query), params)
                else:
                    cursor.execute(text(query))
                result = cursor.fetchall()
            return result
        finally:
            self.pool.put(conn)

    def start_transaction(self):
        conn = self.establish_connection()
        try:
            conn.autocommit = False
            return conn
        except Exception as e:
            self.logger.error(f"Failed to start transaction: {e}")
            raise

    def commit_transaction(self, conn):
        try:
            conn.commit()
        finally:
            self.pool.put(conn)

    def rollback_transaction(self, conn):
        try:
            conn.rollback()
        finally:
            self.pool.put(conn)

    def get_pool_size(self):
        return self.pool.qsize()

    def set_pool_size(self, size):
        with self.lock:
            if size < self.pool.qsize():
                for _ in range(size, self.pool.qsize()):
                    self.pool.get_nowait()
            else:
                while self.pool.qsize() < size:
                    conn = self._create_connection()
                    if conn:
                        self.pool.put(conn)
