# Encryption and decryption functions using AES-256 in CBC mode
def encrypt_data(key, iv, plaintext):
    cipher = Cipher(algorithms.AES(key), modes.CBC(iv), backend=default_backend())
    encryptor = cipher.encryptor()
    return encryptor.update(plaintext) + encryptor.finalize()

def decrypt_data(key, iv, ciphertext):
    cipher = Cipher(algorithms.AES(key), modes.CBC(iv), backend=default_backend())
    decryptor = cipher.decryptor()
    return decryptor.update(ciphertext) + decryptor.finalize()

# Compression and decompression functions using LZ4
def compress_lz4(data):
    return lz4.frame.compress(data)

def decompress_lz4(compressed_data):
    return lz4.frame.decompress(compressed_data)

# Compression and decompression functions using Zstandard
def compress_zstd(data, level=3):
    return zstd.compress(data, level=level)

def decompress_zstd(compressed_data):
    return zstd.decompress(compressed_data)

# Compression and decompression functions using Brotli
def compress_brotli(data, quality=6):
    return brotli.compress(data, mode=brotli.MODE_TEXT, quality=quality)

def decompress_brotli(compressed_data):
