import redis
from redis import ConnectionError, TimeoutError

def connect_to_cache():
    try:
        # Connect to Redis cache
        return redis.StrictRedis(host='localhost', port=6379, db=0)
    except (ConnectionError, TimeoutError) as e:
        print(f"Failed to connect to Redis: {e}")
        return None

def initialize_cache():
    cache = connect_to_cache()
    if cache:
        # Initialize cache settings
        cache.config_set('maxmemory-policy', 'allkeys-lru')
        cache.set_option(redis.OPTION_ALLKEYSLRU)
    return cache

def add_stock_ticker(cache, ticker, data):
    if cache:
        # Add stock ticker and data to cache
        cache.set(ticker, data)

def update_stock_data(cache, ticker, new_data):
    if cache:
        # Update existing stock data
        cache.set(ticker, new_data)

def get_stock_data(cache, ticker):
    if cache:
        # Retrieve stock data from cache
        return cache.get(ticker)
    return None

def delete_stock_ticker(cache, ticker):
    if cache:
        # Remove stock ticker from cache
        cache.delete(ticker)

def main():
    cache = initialize_cache()
    if cache:
        add_stock_ticker(cache, 'AAPL', '{"price": 150.75, "volume": 23456}')
        update_stock_data(cache, 'AAPL', '{"price": 151.00, "volume": 25678}')
        stock_data = get_stock_data(cache, 'AAPL')
        print(f"Stock Data for AAPL: {stock_data}")
        delete_stock_ticker(cache, 'AAPL')

if __name__ == "__main__":
    main()
