```c
#include <openssl/aes.h>
#include <openssl/rand.h>
#include <openssl/sha.h>
#include <string.h>

typedef struct {
    AES_KEY enc_key;
    AES_KEY dec_key;
    unsigned char *iv;
    int iv_len;
    unsigned char *tag;
    int tag_len;
} AES_GCM_CTX;

int aes_gcm_init(AES_GCM_CTX *ctx, const unsigned char *password, size_t password_len,
                 int iv_len, int tag_len) {
    unsigned char key[32];
    SHA256(password, password_len, key);

    if (AES_set_encrypt_key(key, 256, &ctx->enc_key) != 0 ||
        AES_set_decrypt_key(key, 256, &ctx->dec_key) != 0) {
        return -1;
    }

    ctx->iv = malloc(iv_len);
    if (!ctx->iv) {
        return -1;
    }
    ctx->iv_len = iv_len;

    ctx->tag = malloc(tag_len);
    if (!ctx->tag) {
        free(ctx->iv);
        return -1;
    }
    ctx->tag_len = tag_len;

    return 0;
}

int aes_gcm_encrypt(AES_GCM_CTX *ctx, const unsigned char *plaintext, size_t plaintext_len,
                   unsigned char *ciphertext, unsigned char *auth_tag) {
    if (!RAND_bytes(ctx->iv, ctx->iv_len)) {
        return -1;
    }

    EVP_CIPHER_CTX *cipher_ctx = EVP_CIPHER_CTX_new();
    if (!cipher_ctx) {
        return -1;
    }

    if (EVP_EncryptInit_ex(cipher_ctx, EVP_aes_256_gcm(), NULL, NULL, ctx->iv) != 1 ||
        EVP_EncryptUpdate(cipher_ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len) != 1 ||
        EVP_EncryptFinal_ex(cipher_ctx, ciphertext + ciphertext_len, &ciphertext_len) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }

    if (EVP_CIPHER_CTX_ctrl(cipher_ctx, EVP_CTRL_GCM_SET_IVLEN, ctx->iv_len, NULL) != 1 ||
        EVP_EncryptFinal_ex(cipher_ctx, ciphertext + ciphertext_len, &ciphertext_len) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }

    if (EVP_CIPHER_CTX_ctrl(cipher_ctx, EVP_CTRL_GCM_SET_TAG, ctx->tag_len, auth_tag) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }

    EVP_CIPHER_CTX_free(cipher_ctx);
    return ciphertext_len;
}

int aes_gcm_decrypt(AES_GCM_CTX *ctx, const unsigned char *ciphertext, size_t ciphertext_len,
                   const unsigned char *auth_tag, unsigned char *plaintext) {
    EVP_CIPHER_CTX *cipher_ctx = EVP_CIPHER_CTX_new();
    if (!cipher_ctx) {
        return -1;
    }

    if (EVP_DecryptInit_ex(cipher_ctx, EVP_aes_256_gcm(), NULL, NULL, ctx->iv) != 1 ||
        EVP_DecryptUpdate(cipher_ctx, plaintext, &ciphertext_len, ciphertext, ciphertext_len) != 1 ||
        EVP_CIPHER_CTX_ctrl(cipher_ctx, EVP_CTRL_GCM_SET_TAG, ctx->tag_len, (void*)auth_tag) != 1 ||
        EVP_DecryptFinal_ex(cipher_ctx, plaintext + ciphertext_len, &ciphertext_len) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }

    EVP_CIPHER_CTX_free(cipher_ctx);
    return ciphertext_len;
}

void aes_gcm_cleanup(AES_GCM_CTX *ctx) {
    if (ctx->iv) {
        free(ctx->iv);
    }
    if (ctx->tag) {
        free(ctx->tag);
    }
}
