<?php

// Configuration Management System

class ConfigManager {
    private $environment;
    private $config;

    public function __construct() {
        $this->detectEnvironment();
        $this->loadConfigFromDatabase();
        $this->applyFallbacks();
    }

    private function detectEnvironment() {
        if (isset($_ENV['APP_ENV'])) {
            $this->environment = $_ENV['APP_ENV'];
        } else {
            $this->environment = 'development';
        }
    }

    private function loadConfigFromDatabase() {
        // Connect to the database
        $db = new PDO('mysql:host=localhost;dbname=config_db', 'username', 'password');

        // Fetch configuration based on environment
        $stmt = $db->prepare("SELECT * FROM config WHERE environment = ?");
        $stmt->execute([$this->environment]);
        $config = $stmt->fetch(PDO::FETCH_ASSOC);

        if ($config) {
            $this->config = json_decode($config['data'], true);
        } else {
            $this->loadDefaultConfig();
        }
    }

    private function applyFallbacks() {
        // Apply fallback mechanisms for critical settings
        $fallbacks = [
            'DB_HOST' => $_ENV['DB_HOST'] ?? 'localhost',
            'API_KEY' => $_ENV['API_KEY'] ?? 'default_key'
        ];

        foreach ($fallbacks as $key => $value) {
            if (!isset($this->config[$key])) {
                $this->config[$key] = $value;
            }
        }
    }

    private function loadDefaultConfig() {
        // Load default configuration settings
        $this->config = [
            'DB_HOST' => 'localhost',
            'DB_NAME' => 'default_db',
            'API_KEY' => 'default_key'
        ];
    }

    public function get($key) {
        return $this->config[$key] ?? null;
    }
}

// Usage example
$configManager = new ConfigManager();
$databaseHost = $configManager->get('DB_HOST');
```

This code snippet provides a basic structure for the configuration management system. It detects the server environment, loads configuration settings from a database, applies fallbacks if necessary, and retrieves configuration values. The `ConfigManager` class can be further extended to include additional features such as external validation, versioning, customizable fallback mechanisms, and security enhancements like encryption and secure transmission.

