class MemoryProfiler {
private:
    size_t totalAllocated;

public:
    MemoryProfiler() : totalAllocated(0) {}

    void* Allocate(size_t size) {
        totalAllocated += size;
        return malloc(size);
    }

    void Free(void* ptr, size_t size) {
        totalAllocated -= size;
        free(ptr);
    }

    size_t GetTotalMemoryUsed() const {
        return totalAllocated;
    }
};
