    pthread_mutex_unlock(&config->lock);
    return allow_request;
}

void log_rate_limiting_event(RateLimiterConfig *config) {
    printf("Rate limiting event logged\n");
}

int main() {
    RateLimiterConfig *config = create_rate_limiter(0, 60, 10); // Fixed window policy, 60-second window, max 10 requests

    while (1) {
        if (is_request_allowed(config)) {
            printf("Request allowed\n");
        } else {
            log_rate_limiting_event(config);
            printf("Rate limit exceeded\n");
