    public async Task DecryptCiphertextAsync(string ciphertext, string keyBase64, string ivBase64)
    {
        if (!IsValidKeyAndIV(keyBase64, ivBase64))
        {
            throw new ArgumentException("Invalid encryption key or IV.");
        }

        byte[] ciphertextBytes = Convert.FromBase64String(ciphertext);
        byte[] keyBytes = Convert.FromBase64String(keyBase64);
        byte[] ivBytes = Convert.FromBase64String(ivBase64);

        using (Aes aes = Aes.Create())
