            aes.IV = ivBytes;
            aes.Mode = _cipherMode;
            aes.Padding = _paddingMode;

            ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
            byte[] decryptedBytes = await DecryptAsync(decryptor, ciphertextBytes);

            string plaintext = Encoding.UTF8.GetString(decryptedBytes);
            ValidatePlaintextIntegrity(plaintext); // Implement validation logic here
        }
    }

    private bool IsValidKeyAndIV(string keyBase64, string ivBase64)
