using System;
using System.IO;
using System.Net.NetworkInformation;
using System.Threading;
using System.Threading.Tasks;

public class WebSiteManager
{
    private static readonly object _lock = new object();
    private static readonly SemaphoreSlim _semaphore = new SemaphoreSlim(1, 1);

    public async Task AddWebSiteAsync(string directoryPath, string siteName, int portNumber)
    {
        await _semaphore.WaitAsync(); // Handle concurrent access
        try
        {
            if (!Directory.Exists(directoryPath))
            {
                throw new DirectoryNotFoundException("The specified directory does not exist.");
            }

            if (!directoryPath.All(char.IsLetterOrDigit) && !directoryPath.All(char.IsWhiteSpace))
            {
                throw new ArgumentException("The directory path contains invalid characters.");
            }

            string webConfigPath = Path.Combine(directoryPath, "web.config");
            if (!File.Exists(webConfigPath))
            {
                await GenerateWebConfigAsync(webConfigPath);
            }

            // Validate site name
            if (siteName.Any(c => !char.IsLetterOrDigit(c)))
            {
                throw new ArgumentException("The site name contains invalid characters.");
            }

            // Check for port conflicts
            using (TcpListener listener = TcpListener.Create(portNumber))
            {
                try
                {
                    listener.Start();
                }
                catch (SocketException)
                {
                    throw new InvalidOperationException("Port is already in use by another process.");
                }
                finally
                {
                    listener.Stop();
                }
            }

            // Add and start the site asynchronously
            await Task.Run(() =>
            {
                using (Process process = new Process())
                {
                    process.StartInfo.FileName = "cscript";
                    process.StartInfo.Arguments = $"/E:JScript \"{Path.Combine(AppDomain.CurrentDomain.BaseDirectory, \"AddWebSite.vbs\")}\" \"{directoryPath}\" \"{siteName}\" {portNumber}";
                    process.StartInfo.RedirectStandardOutput = true;
                    process.StartInfo.RedirectStandardError = true;
                    process.StartInfo.UseShellExecute = false;
                    process.OutputDataReceived += (sender, e) => Console.WriteLine(e.Data);
                    process.ErrorDataReceived += (sender, e) => Console.WriteLine($"ERROR: {e.Data}");
                    process.Start();
                    process.BeginOutputReadLine();
                    process.BeginErrorReadLine();
                    process.WaitForExit();
                }
            }, CancellationToken.None);

            // Log successful addition and start of the site
            Console.WriteLine("Web site added and started successfully.");
        }
        catch (Exception ex)
        {
            // Log any errors that occur during the process
            Console.Error.WriteLine($"ERROR: {ex.Message}");
        }
        finally
        {
            _semaphore.Release(); // Release lock after operation completes
        }
    }

    private static async Task GenerateWebConfigAsync(string webConfigPath)
    {
        // Implement logic to generate a default web.config file using an external configuration management system
        await Task.Delay(1000); // Simulate asynchronous operation
        File.WriteAllText(webConfigPath, "<configuration></configuration>");
    }
}
