async function discoverAndLoadModules() {
  const modules = [];
  const moduleDir = path.resolve(__dirname, config.moduleDir);

  try {
    const files = await fs.promises.readdir(moduleDir);
    for (const file of files) {
      if (file.endsWith('.test.js')) {
        const modulePath = path.join(moduleDir, file);
        try {
          const module = require(modulePath);
          modules.push(module);
        } catch (error) {
          console.error(`Failed to load module ${modulePath}:`, error);
        }
      }
    }
  } catch (error) {
