using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;

public class DynamicDatabaseConnectionManager
{
    private string connectionStringTemplate;
    private Dictionary<string, string> tenantConnectionStringMapping;
    private Queue<SqlConnection> connectionPool;
    private ConfigurationManager configurationManager;

    public DynamicDatabaseConnectionManager(string template, ConfigurationManager manager)
    {
        connectionStringTemplate = template;
        configurationManager = manager;
        tenantConnectionStringMapping = new Dictionary<string, string>();
        connectionPool = new Queue<SqlConnection>();

        // Initialize with a default number of connections
        for (int i = 0; i < 10; i++)
        {
            connectionPool.Enqueue(new SqlConnection(connectionStringTemplate));
        }
    }

    public void EstablishConnection(string tenantId)
    {
        if (!tenantConnectionStringMapping.ContainsKey(tenantId))
        {
            string connectionString = GetTenantConnectionString(tenantId);
            tenantConnectionStringMapping[tenantId] = connectionString;
        }

        // Reuse connections from the pool or create a new one
        SqlConnection connection;
        if (connectionPool.Count > 0)
        {
            connection = connectionPool.Dequeue();
        }
        else
        {
            connection = new SqlConnection(tenantConnectionStringMapping[tenantId]);
        }

        try
        {
            connection.Open();
        }
        catch (Exception ex)
        {
            // Handle connection errors
            Console.WriteLine("Error establishing connection: " + ex.Message);
        }

        // Use the connection for database operations
    }

    public DataTable ExecuteQuery(string tenantId, string query)
    {
        using (SqlConnection connection = EstablishConnection(tenantId))
        {
            SqlCommand command = new SqlCommand(query, connection);
            SqlDataAdapter adapter = new SqlDataAdapter(command);
            DataTable dataTable = new DataTable();
            try
            {
                adapter.Fill(dataTable);
            }
            catch (Exception ex)
            {
                // Handle query execution errors
                Console.WriteLine("Error executing query: " + ex.Message);
            }
            return dataTable;
        }
    }

    public void BeginTransaction(string tenantId)
    {
        // Implement transaction management logic
    }

    public void CommitTransaction()
    {
        // Implement transaction management logic
    }

    public void RollbackTransaction()
    {
        // Implement transaction management logic
    }

    private string GetTenantConnectionString(string tenantId)
    {
        return configurationManager.GetConnectionString(tenantId);
    }

    public void CloseConnection(string tenantId, SqlConnection connection)
    {
        if (connection != null && connection.State == ConnectionState.Open)
        {
            try
            {
                connection.Close();
            }
            catch (Exception ex)
            {
                // Handle closing errors
                Console.WriteLine("Error closing connection: " + ex.Message);
            }
            connectionPool.Enqueue(connection);
        }
    }

    public void UpdateConfiguration(string template, Dictionary<string, string> mappings)
    {
        connectionStringTemplate = template;
        tenantConnectionStringMapping.Clear();
        tenantConnectionStringMapping = mappings;
    }

    public override string ToString()
    {
        return $"Active Connections: {connectionPool.Count}, Connection String Template: {connectionStringTemplate}";
    }
}

public interface ConfigurationManager
{
    string GetConnectionString(string tenantId);
}
